window.BIO_DATA = [{"i":0,"n":"אבא (7)","l":"א","b":"חכם ארץ ישראלי קדום. קיבל מהזוגות. חי בימי הלל, כמאה שנה לפני חורבן בית שני. מובא במשנה: \"מעשה שזרע ר\u0027 שמעון איש המצפה, ובא לפני רבן גמליאל הזקן, ועלו ללשכת הגזית ושאלו, אמר נחום הלבלר: \u0027מקובל אני מרבי מיאשא, שקבל מאבא, שקבל מן הזוגות, שקבלו מן הנביאים, הלכה למשה מסיני בזורע\u0027 וכו\u0027\" (פאה פ\"ב מ\"ו)."},{"i":1,"n":"רבי אבא (2)","l":"א","b":"אמורא בבלי בדור השלישי. תלמידם של רב הונא (מנחות כ\"ט ע\"א) ושל רב יהודה (יבמות ע\"ה ע\"ב), ועוד למד מרב (יומא ס\"ד ע\"ב) ושמואל (ברכות נ\u0027 ע\"א). עלה לא\"י לפני ר\u0027 זירא (חולין נ\"ז ע\"א - רש\"י), שהיה חברו המובהק (שם נ\u0027 ע\"א). בא\"י למד לפני רבי יוחנן (נדה כ\"ה ע\"ב) ושם התעלה, עד שהגמרא אומרת \"רבותינו שבארץ ישראל - רבי אבא\" (סנהדרין י\"ז ע\"ב), ושלח פסקים מא\"י לבבל (ב\"ב קכ\"ז ע\"ב). מדי פעם ירד לבבל והביא עמו מתורת חכמי א\"י (ב\"מ ק\"ז ע\"א) כשנפטר רב הונא רבו והביאוהו לא\"י\", הספידו ר\u0027 אבא (מו\"ק כ\"ה ע\"א). עסק במסחר המשי (ב\"ק קי\"ז ע\"ב) והיה עשיר (שבת קי\"ט ע\"א). נתן צדקה בדרך שלא לבייש את העניים (כתובות ס\"ז ע\"ב). האריך ימים, שכן דיבר עם שמואל [שנפטר בשנת ד\u0027 י\"ג (352)] (ירו\u0027 עירובין פ\"ו ה\"ז), ומאידך חי עוד בימי רבא [שנפטר בשנת ד\u0027 קי\"א (153)] (ב\"ק ק\"ד ע\"ב)."},{"i":2,"n":"ר\u0027 אבא אבוה דרב בריה דרב משרשיא","l":"א","b":"מובא בבבלי (עירובין כ\"ד ע\"א). \"סדר הדורות\" כתב: \"וטעות סופר יש כאן\". ע\"ע רב אבא אחוה דרב בריה דרב משרשיא."},{"i":3,"n":"ר\u0027 אבא אבוה דר\u0027 אבא בר מרי","l":"א","b":"כתב ב\"סדר הדורות\": \"נ\"ל שצ\"ל אבא אבוי דר\u0027 אבא מרי\"."},{"i":4,"n":"ר\u0027 אבא אבוה דר\u0027 אבא מרי","l":"א","b":"אמורא ארץ ישראלי מובא בירושלמי (ברכות פ\"ט ה\"ג). מצינו שמסר בשם רבי אחא (שם)."},{"i":5,"n":"אבא אבוה דר\u0027 ירמיה בר אבא","l":"א","b":"אמורא בבלי בדור הראשון. בשמו הובאה ברייתא ששנה: \"דתני אבוה דרבי [צ\"ל דרב] ירמיה בר אבא\". (מנחות מ\"ז ע\"א). היה לו אח ושמו אחא, ואחד משניהם היה בעל תשובה גדול: \"דאמר רב \u0027אין לך גדול בבעלי תשובה וכו\u0027 ומנו? אבא אבוה דר\u0027 ירמיה בר אבא\u0027, ואמרי לה: אחא אחוה דאבא\" (שבת נ\"ו ע\"ב)."},{"i":6,"n":"אבא אבוה דר\u0027 שמלאי","l":"א","b":"אמורא בבלי בדור הראשון. נראה, שמושבו היה בנהרדעא. שאל לשמואל שאלה בסוד העיבור ולא ידע לענות לו (ר\"ה כ\u0027 ע\"ב) בנו רבי שמלאי היה תלמידו של יהודה נשיאה הראשון (ע\"ז ל\"ז ע\"א)."},{"i":7,"n":"אבא אבוה דשמואל","l":"א","b":"ע\"ע אבא בר אבא אבוה דשמואל."},{"i":8,"n":"אבא אומנא","l":"א","b":"חסיד גדול שחי בבבל בדור השלישי לאמוראים. בכל יום שאלו לשלומו מן השמים ואילו לשלום אביי - רק בכל ערב שבת: דבר זה גרם לאביי חלישות דעת והוא שלח את תלמידיו לבדוק אחריו מה זכותו הגדולה, ואז נוכח בגודל חסידותו (תענית כ\"א ע\"ב). מלאכתו היתה הקזת דם. (שם)."},{"i":9,"n":"אבא אושעיא איש טורייא","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. נולד ביום שנפטר רבין (ב\"ר נ\"ח - ב\u0027). היה חסיד וזהיר במעשיו (ירו\u0027, ב\"ק פ\"י ה\"י). פעם קידש שם שמים, בהחזירו אבידה יקרה למלכה (ירו\u0027, ב\"מ פ\"ב ה\"ה). כשנפטר ריחפה מיטתו באויר (מד\"ר שה\"ש פ\"ח - ז\u0027)."},{"i":10,"n":"רב אבא אחוה דרב בריה דרב משרשיא","l":"א","b":"מובא בבבלי (עירובין כ\"ד ע\"א). כך גירסת מסורת הש\"ס."},{"i":11,"n":"ר\u0027 אבא אחוה דר\u0027 יהודה בר זבדי","l":"א","b":"אמורא בבלי בדור השני - השלישי. תלמידו של רב יהודה. רב שמואל בר יהודה מסר משמו (יבמות פ\"ג ע\"ב). היה לו אח ושמו ר\u0027 סימון (ירו\u0027, ב\"ב רפ\"ג). ע\"ע ר\u0027 אבא בר זבדי."},{"i":12,"n":"אבא אלעזר","l":"א","b":"תנא ארץ ישראלי בדור השלישי. חי בזמן הבית: \"א\"ר יוסי: \u0027סח לי אבא אלעזר: פעם אחת היה לנו עגל של זבחי שלמים והביאנוהו לעזרת נשים\u0027\" (חגיגה ט\"ז ע\"ב)."},{"i":13,"n":"אבא אלעזר בן אליעזר בן דולעאי","l":"א","b":"תנא בדור הרביעי. חלק על תלמידי ר\"ע - רבי מאיר, רבי יהודה ורבי שמעון (מקואות ספ\"ב)."},{"i":14,"n":"אבא אלעזר בן גומל","l":"א","b":"מובא בבבלי (בכורות נ\"ח ע\"ב), והוא אבא אלעזר בן גימל (ביצה י\"ג ע\"ב)."},{"i":15,"n":"אבא אלעזר בן גימל","l":"א","b":"תנא שאין לקבוע זמנו המדויק. מובא בבבלי (ביצה י\"ג ע\"ב). ה\"יוחסין\" כתב עליו: \"נראה שהוא בזמן ר\u0027 יוחנן\". שמו נשתבש בכמה פנים."},{"i":16,"n":"אבא אלעזר בן גמלא","l":"א","b":"מובא בבבלי (גיטין ל\u0027 ע\"ב), והוא אבא אלעזר בן גימל."},{"i":17,"n":"אבא אלעזר בן גמליאל","l":"א","b":"מובא בספרי (קרח פ\u0027 ונחשב), והוא אבא אלעזר בן גימל."},{"i":18,"n":"אבא אלעזר בן דולעאי","l":"א","b":"תנא בדור החמישי. חלק על רבי מאיר ורבי יהודה וחבריהם (מקואות ספ\"ב). \"סה\"ד\" מסתפק אם הוא אליעזר בן דגלאי."},{"i":19,"n":"אבא אנטולי","l":"א","b":"חי בארץ ישראל, בדור הראשון לאמוראים. מובא בירושלמי (דמאי פ\"ה ה\"ח), ששאל את רבי יהודה בן לוי בענין מעשרות. ספק אם נמנה עם החכמים."},{"i":20,"n":"אבא אריכא","l":"א","b":"הוא רב, כדמצינו בבבלי (חולין קל\"ז ע\"ב)."},{"i":21,"n":"אבא ביראה","l":"א","b":"אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מוזכר פעם בבבלי (מנחות צ\"ג ע\"ב): \"דתניא, אבא ביראה ברבי אליעזר בן יעקב אומר\" [פירוש המלה ברבי כמו בדבי (עירובין י\"ט ע\"א רש\"י ד\"ה: בדבי)]."},{"i":22,"n":"אבא בן יוסי","l":"א","b":"מובא בספרי (נשא פמ\"ב), והוא אבא יוסי בן דוסתאי."},{"i":23,"n":"אבא בנימין (2)","l":"א","b":"תנא שאין לקבוע זמנו המדוייק. ארבעה מאמרי אגדה הובאו בשמו בבבלי (ברכות ה\u0027 ע\"ב). מצינו בירושלמי אבא פנימון (תרומות פ\"ג ה\"ג), ואולי חד הוא."},{"i":24,"n":"אבא בר אבא","l":"א","b":"מובא בבבלי (ברכות י\"ח ע\"ב), והוא אבוה דשמואל. (ע\"ע)."},{"i":25,"n":"אבא בר אבא אבוה דשמואל","l":"א","b":"אמורא בבלי בדור המעבר בין התנאים לאמוראים. אביו של האמורא שמואל (ברכות י\"ח ע\"ב). היה הראש בנהרדעא (ביצה ט\"ז ע\"ב). נראה שקיבל מרב הונא ראש גלותא (מעילה ט\u0027 ע\"א). כשלוי ירד לבבל, היו לחברים ולמדו יחד (ב\"ב מ\"ב ע\"ב). זכו יחד לגילוי שכינה (מגילה כ\"ט ע\"א). [לוי נפטר לפניו (ירו\u0027, ברכות פ\"ב ה\"ח)]. ביקר בארץ ישראל והיה לתלמידו של רבי (ירו\u0027, ר\"ה פ\"ג ה\"ו). בנו שמואל, קיבל ממנו (זבחים כ\"ו ע\"א). וכן קיבל ממנו רב (כתובות נ\"א ע\"ב). שלחו לו שאלות מארץ ישראל (ב\"מ צ\u0027 ע\"א). עסק במסחר המשי. נפגש לרגל מסחרו עם ר\u0027 יהודה בן בתירא, והוא בירכו שיהיה לו בן גדול כשמואל הרמתי (מדרש שמואל פ\"י - ג). היה חסיד ונהג לפנים משורת הדין (ב\"מ כ\"ד ע\"ב) ולימד את שמואל בנו לנהוג כן (ירו\u0027, סוף פאה). היה לו בן חכם נוסף ושמו פנחס (מו\"ק י\"ח ע\"א). היו לו גם בנות (שבת ס\"ה ע\"א). נראה שהאריך ימים וחי אף בימי ר\u0027 יהודה נשיאה נכד רבי (יבמות קט\"ו ע\"ב)."},{"i":26,"n":"אבא בר אבא בר ממל","l":"א","b":"אמורא בדור הרביעי. מובא בירושלמי (פאה פ\"ח ה\"ה). נראה שם כאילו היה תלמידו של רבי אלעאי, אבל נראה יותר שהיו חברים."},{"i":27,"n":"רבי אבא בר אבין","l":"א","b":"אמורא ארץ ישראלי בדור החמישי. מסר יחד עם רבי תנחום, בשם רבי אחא (ב\"ר פל\"ג - ס\"ג)."},{"i":28,"n":"רבי אבא בר אבינא","l":"א","b":"אמורא ארץ ישראלי בדור השני. נראה שכך שמו, כמובא (שבת ס\u0027 ע\"ב). ושמו שובש בצורות שונות. תלמידו של רב (ירו\u0027, ב\"מ פ\"ד ה\"א). היה דיין בעירו (שם פ\"ה ה\"א). ר\u0027 אבא בר זבדי שאל ממנו (שבת שם). חיבר נוסח וידוי ליום הכיפורים (ירו\u0027, סוף יומא). היה לו אח ושמו חגרא (ירו\u0027, מגילה פ\"א ה\"ט)."},{"i":29,"n":"רבי אבא בר אדא","l":"א","b":"אמורא ארץ ישראלי בדור החמישי. מובא בירושלמי (גיטין פ\"ד ה\"ו). מצינו ששאל לרב מני (שם). ואינו בהכרח תלמידו."},{"i":30,"n":"אבא בר אחא","l":"א","b":"אמורא ארץ ישראלי בדור הראשון. מסר בשם רבי (ירו\u0027, ברכות פ\"א ה\"ו). מצינו שירד לבבל (שם). מאמרו המפורסם: \"אין אתה יכול לעמוד על אופיה של אומה זו, נתבעין לעגל ונותנין, נתבעין למשכן ונותנין\" (ירו\u0027, שקלים פ\"א ה\"א)."},{"i":31,"n":"אבא בר אחא כרסלא","l":"א","b":"הוא אבי אביו של רב. (סנהדרין ה\u0027 ע\"א)."},{"i":32,"n":"אבא בר איבו","l":"א","b":"הוא רב. ושם אביו היה איבו (סנהדרין ה\u0027 ע\"א). שמו של רב הוא אבא, כך פירש הרשב\"ם \"אבא כך שמו של רב אלא בכבוד קורין אותו רב בבבל\" (פסחים קי\"ט ע\"ב ד\"ה: אבא) ורש\"י סובר שאבא זה לשון חשיבות: \"ושמואל היה קורא לרב אבא לכבודו\" (ברכות מ\"ז ע\"א רש\"י ד\"ה: אילו) וכתבו התוספות: \"אמר שמואל ומודה לי אבא לא כמו שפירש בקונטרס לשון חשיבות אלא כך היה שמו של רב כדפירש \u0027בערוך\u0027 בערך אבא\" (יבמות נ\"ז ע\"ב ד\"ה: אמר). ומצינו שקראו לו רב (יומא כ\u0027 ע\"ב: חולין נ\"ד ע\"א)."},{"i":33,"n":"רבי אבא בר אילעי","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. ר\u0027 זירא מסר בשמו. (ירו\u0027, ר\"ה פ\"ד ה\"י)."},{"i":34,"n":"ר\u0027 אבא בר אלישע","l":"א","b":"מובא בבראשית רבה (פ\"פ - ז\u0027)."},{"i":35,"n":"ר\u0027 אבא בר אמי","l":"א","b":"מובא בב\"ר (רפ\"ה), ר\u0027 ברכיה מאמוראי א\"י בדור הרביעי מסר בשמו."},{"i":36,"n":"רבי אבא בר ביזנא","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי: תלמידו של רבי אסי ומסר הלכה מרבו, בשם רבי יוחנן (ירו\u0027, ב\"ק פ\"ה ה\"ז)."},{"i":37,"n":"אבא בר בנימין","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי (שביעית פ\"ו ה\"ג). חברו של רבי אבהו (שם)."},{"i":38,"n":"אבא בר בר חנא","l":"א","b":"הוא רבה בר בר חנא."},{"i":39,"n":"אבא בר בר חנה","l":"א","b":"מובא בירושלמי (ברכות פ\"ב ה\"א), והוא רבה בר בר חנה [אבא הוא רבה]. וכן פרשב\"ם (ב\"ב ע\"ד ע\"א)."},{"i":40,"n":"ר\u0027 אבא בר בריה דר\u0027 חייא בר אבא","l":"א","b":"מובא בירושלמי (שבת פ\"ג ה\"ד). ט\"ס וצ\"ל: ר\u0027 אבא בריה דר\u0027 חייא בר אבא."},{"i":41,"n":"ר\u0027 אבא בר גרשון","l":"א","b":"מוזכר בירושלמי (תרומות פ\"י ה\"ו). נראה שזהה לרב אידי בר אידי בר גרשום. וע\"ע ר\u0027 אידי בר גרשום."},{"i":42,"n":"ר\u0027 אבא בר המנונא","l":"א","b":"אמורא בדור השלישי. מסר בשם רב אדא בר אחא [אדא זהה לאהבה] (ירו\u0027, גיטין פ\"ח ה\"ג)."},{"i":43,"n":"רבי אבא בר זבדא","l":"א","b":"מובא בבבלי (שבת ס\u0027 ע\"ב), והוא רבי אבא בר זבדי."},{"i":44,"n":"ר\u0027 אבא בר זבדי","l":"א","b":"אמורא בדור השני - השלישי. בבבל למד לפני רב (ירו\u0027, ב\"מ פ\"ב ה\"ד). לאחר פטירת רב למד לפני רב הונא יחד עם חבריו רב גידל, ר\u0027 חלבו ורב ששת (יבמות ס\"ד ע\"ב). עלה לארץ ישראל, ומשם שלח שאלותיו לרב הונא (גיטין פ\"ו ע\"ב). היה תלמידו של רבי חנינא (ירו\u0027, יבמות ספ\"ו). וחברו של רבי אלעזר (שם). לאחר פטירת ר\"א נחשב כאחד מחשובי חכמי א\"י. היה הפותח בהלכה ור\u0027 אמי ור\u0027 אסי החותמים (ירו\u0027, ר\"ה פ\"ב ה\"ה). האריך ימים, שהרי רבא בצעירותו שלח אליו לברר קושיא (ב\"מ ט\"ז ע\"א). היו לו שני אחים חכמים: ר\u0027 יהודה (ירו\u0027, קידושין פ\"ד ה\"ב) ור\u0027 סימון (ירו\u0027, ב\"ב רפ\"ג)."},{"i":45,"n":"רבי אבא בר זבינא","l":"א","b":"מובא בירושלמי (דמאי פ\"א ה\"ג). ע\"ע ר\u0027 אבא בר זמינא."},{"i":46,"n":"ר\u0027 אבא בר זוטרא","l":"א","b":"אמורא ארץ ישראלי בדור השני. תלמידם של ר\u0027 חנינא ור\u0027 יהושע בן לוי (ירו\u0027, גיטין פ\"ד ה\"ד). מתורגמן של ר\u0027 יוחנן (ירו\u0027, נדרים פ\"י ה\"ח). נראה, שירד לבבל לתקופה מסוימת ולמד שם אצל שמואל (ירו\u0027, יבמות פ\"ד הי\"א). ר\u0027 זירא מסר בשמו (ירו\u0027, שבת פי\"ד ה\"ד)."},{"i":47,"n":"אבא בר זימנא","l":"א","b":"ע\"ע ר\u0027 אבא בר זמינא."},{"i":48,"n":"ר\u0027 אבא בר זמינא","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי זירא (ירו\u0027, ברכות פ\"ז ה\"ג). גם אביו זמינא היה חכם, והתגורר בעיר צור (ירו\u0027, בכורים פ\"ג ה\"ג). פרנסתו היתה מתפירת מנעלים. עמד בנסיון בעבדו אצל גוי, שאיים עליו להורגו אם לא יאכל נבלה (ירו\u0027, שביעית פ\"ד ה\"ב). מאמרו הנודע: \"אין הוון קדמאי בני מלאכים אנן בני אנש\" (ירו\u0027, דמאי פ\"א ה\"ג) מובא גם בבבלי: \"אם ראשונים בני מלאכים אנו בני אנשים\" (שבת קי\"ב ע\"ב)."},{"i":49,"n":"ר\u0027 אבא בר זעירא","l":"א","b":"מובא במדרש תהלים (פכ\"ח - ד\u0027). אולי הוא אהבה בר זעירא."},{"i":50,"n":"רב אבא בר חוניא","l":"א","b":"אמורא ארץ ישראלי. נראה שחי בדור הרביעי - החמישי. נותרו ממנו מאמרים באגדה (קה\"ר פ\"א - ב)."},{"i":51,"n":"אבא בר חייא","l":"א","b":"מובא בירושלמי (כלאים פ\"ב ה\"א). והוא רבה בר חייא קטוספאה."},{"i":52,"n":"רבי אבא בר חייא בר אשי","l":"א","b":"מובא בירו\u0027 (שבת פ\"ז ה\"ב). יש גורסים שט\"ס וצ\"ל: ר\u0027 אבא ב\"ר: ב\"ר הם ראשי תיבות של \"בשם רב\" חייא בר אשי."},{"i":53,"n":"ר\u0027 אבא בר חיננא","l":"א","b":"מובא בירושלמי (גיטין פ\"ג ה\"א), יחד עם רב אסי ורב יוחנן."},{"i":54,"n":"אבא בר חליפיי בר קריי","l":"א","b":"ע\"ע אבא חליפא קרויא."},{"i":55,"n":"אבא בר חמא","l":"א","b":"אמורא בבלי בדור השני. רב חסדא אמר: \"אמר לי אבא בר חמא\" וכו\u0027 (ע\"ז ל\"א ע\"א)."},{"i":56,"n":"אבא בר חנן","l":"א","b":"מובא בבבלי (ע\"ז ס\u0027 ע\"ב). אולי צ\"ל אבא בר חמא."},{"i":57,"n":"אבא בר חסדא","l":"א","b":"מובא בבבלי (ע\"ז מ\"ט ע\"ב). אולי צ\"ל אבא בר חייא."},{"i":58,"n":"ר\u0027 אבא בר טבליי","l":"א","b":"אמורא בבלי בדור השני - השלישי. מסר בשם רב (ירו\u0027, ב\"ב פ\"ד ה\"ח)."},{"i":59,"n":"ר\u0027 אבא בר יהודה","l":"א","b":"אמורא שאין לקבוע זמנו. מסר בשם רב (ירו\u0027, שבועות רפ\"ג), בשם ר\u0027 אחא (ב\"ר כ\"ג - ה\u0027), ובשם ר\u0027 יהודה בר סימון (ויק\"ר פ\"ז - ב\u0027). ממאמריו: \"כל מה שפסל הקב\"ה בבהמה, הכשיר באדם\" (ויק\"ר פ\"ז - ב\u0027)."},{"i":60,"n":"ר\u0027 אבא בר יודן","l":"א","b":"הוא ר\u0027 אבא בר יהודה."},{"i":61,"n":"ר\u0027 אבא בר יוסף","l":"א","b":"הוא רבא, ע\"ע. כך מובא בבבלי (ביצה ח\u0027 ע\"ב), ובירושלמי (ביצה פ\"א ה\"ג)."},{"i":62,"n":"רב אבא בר יוסף בר רבא","l":"א","b":"אמורא בבלי בדור החמישי - הששי. בן בנו של רבא. עמד בקשר עם רב כהנא (חולין קמ\"א ע\"א)."},{"i":63,"n":"ר\u0027 אבא בר ימינא","l":"א","b":"מובא בב\"ר (פ\"ס - ח\u0027), והוא ר\u0027 אבא בר זמינא."},{"i":64,"n":"רבי אבא בר יסא","l":"א","b":"מובא בירושלמי (סנהדרין פ\"ד ה\"ח). יש גורסין ר\u0027 אבא [בשם] ר\u0027 יסא [ר\u0027 יסא הוא ר\u0027 אסי] בשם ר\u0027 יוחנן."},{"i":65,"n":"ר\u0027 אבא בר יעקב","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של ר\u0027 יוחנן (כתובות ע\"ז ע\"א). כן מסר בשם רבי יצחק רובא (ירו\u0027, ברכות פ\"ו ה\"א)."},{"i":66,"n":"ר\u0027 אבא בר יצחק","l":"א","b":"אמורא בבלי בדור השלישי. תלמידו של רב חסדא (מנחות ק\"י ע\"א)."},{"i":67,"n":"ר\u0027 אבא בר ירמיה","l":"א","b":"מובא בבבלי (נדה י\"א ע\"ב). ע\"ע רבה בר ירמיה."},{"i":68,"n":"ר\u0027 אבא בר כהן","l":"א","b":"אמורא ארץ ישראלי בדור החמישי. נראה שהיה דיין בכפר עקביה ליד צפת (ירו\u0027, נזיר פ\"ט ה\"ג). תלמידם של ר\u0027 יוסי (ירו\u0027, ביצה פ\"ה ה\"ב), ושל ר\u0027 יונה (ירו\u0027, מע\"ש פ\"ב ה\"ג). מסר שמועה בשם רב ששת (ירו\u0027, שבת פ\"ו ה\"א)."},{"i":69,"n":"ר\u0027 אבא בר כהנא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. כן מסר בשם חכמי בבל. רב (ירו\u0027, סוטה פ\"ט הי\"ג) ור\u0027 חייא בר אשי (ירו\u0027, ברכות פ\"ו ה\"ו). קיבל מרבי חנינא (שבת קכ\"א ע\"ב). ומסר בשם ר\u0027 יוחנן (ב\"ר פכ\"ו - ז\u0027) ובשם רבי אליעזר (ירו\u0027, ברכות רפ\"ו). היה חברו של ר\u0027 לוי ושל ר\u0027 זירא (ירו\u0027, מעשרות ספ\"ג). ר\"ז היה מקנטרו על היותו בעל אגדה ודרשן (ירו\u0027, מעשרות ספ\"ג). נפטר אחרי ר\"ז (קה\"ר פ\"א - פ\"ד)."},{"i":70,"n":"ר\u0027 אבא בר כהנא בר יודן","l":"א","b":"מובא בשהש\"ר (ספ\"ז). יש גורסין ר\u0027 אבא בר יודן."},{"i":71,"n":"ר\u0027 אבא בר לוי","l":"א","b":"אמורא. זמנו ומקומו אינם ידועים. מובא בבבלי (כתובות נ\"ז ע\"ב)."},{"i":72,"n":"ר\u0027 אבא בר מדיא","l":"א","b":"מוזכר במדרש שמואל (פ\"א - ז\u0027). יש גורסין ר\u0027 אבא בר מריא."},{"i":73,"n":"ר\u0027 אבא בר מימי","l":"א","b":"מובא (שהש\"ר פ\"א פ\u0027 נאוו) \"כגון ר\u0027 אבא בר מימי וחביריו\"."},{"i":74,"n":"ר\u0027 אבא בר מינא","l":"א","b":"מובא בירושלמי (ב\"מ פ\"ה ה\"א), והוא רבי אבא בר אבינא."},{"i":75,"n":"ר\u0027 אבא בר ממל","l":"א","b":"אמורא ארץ ישראלי בדור השני - השלישי. קיבל מר\u0027 אושעיא (ירו\u0027, ב\"ק פ\"ב ה\"א). וכן מסר בשם רב (ב\"ב ל\"ח ע\"א). וכשמלך ר\u0027 אמי היה מראשי הדור (ב\"ב נ\"ט ע\"א). נראה, שקיבל גם מר\u0027 אמי (יבמות ק\"ה ע\"א). ר\u0027 זירא שאל ממנו (חולין קכ\"ט ע\"א). נפטר לפני ר\"ז (ירו\u0027, שבועות פ\"ג ה\"ד)."},{"i":76,"n":"ר\u0027 אבא בר מניומי","l":"א","b":"מובא בבבלי (גיטין כ\"ט ע\"ב), והוא אבא בר מרתא."},{"i":77,"n":"ר\u0027 אבא בר מריא","l":"א","b":"מובא במדרש שמואל (פ\"א - ז\u0027). יש גורסין ר\u0027 אבא בר מדיא."},{"i":78,"n":"אבא בר מרתא","l":"א","b":"אמורא בבלי בדור השלישי - הרביעי. והוא אבא בר מניומי. נקרא גם ע\"ש אמו, כנראה משום שהודות לסגולה שעשתה לו אמו, נתרפא מנשיכת כלב שוטה. היה תלמידו של רב יהודה (שבת קכ\"א ע\"ב). מצינו ששאל מאביי (ביצה כ\"ב ע\"א). בא לנחם את רבא באבלו (מו\"ק כ\"ו ע\"ב)."},{"i":79,"n":"ר\u0027 אבא בר נגרי","l":"א","b":"אמורא ארץ ישראלי בדור החמישי. מובא בירושלמי (פאה פ\"ה ה\"ד)."},{"i":80,"n":"ר\u0027 אבא בר נתן","l":"א","b":"מובא בירושלמי (מו\"ק פ\"ג ה\"ד), והוא רבה בר נתן."},{"i":81,"n":"ר\u0027 אבא בר סיסי","l":"א","b":"מובא בילקוט ירמיה (רמז שו)."},{"i":82,"n":"ר\u0027 אבא בר עילאי","l":"א","b":"אמורא בדור השלישי. מסר בשם רב (ירו\u0027, ר\"ה פ\"ד ה\"י), חברם של ר\u0027 ברכיה ור\u0027 חלבו (ירו\u0027, תענית פ\"ג ה\"ט). ר\"ז קבל ממנו (ירו\u0027, ר\"ה פ\"ד ה\"י)."},{"i":83,"n":"ר\u0027 אבא בר פפא","l":"א","b":"אמורא בבלי בדור השלישי. חברו של ר\u0027 זירא. ר\"ז ביקשו שבדרכו לארץ ישראל ישאל שאלה את ר\u0027 יעקב בר אידי (ב\"מ מ\"ג ע\"ב). \"יוחסין\" סובר שהוא ר\u0027 אבא הכהן בר פפא."},{"i":84,"n":"רבי אבא בר פפי","l":"א","b":"אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי יוסי (ירו\u0027, גיטין רפ\"ה). רבו של רבי מנא (ירו\u0027, שבת פ\"ג ה\"א). חברו של רבי יהושע דסיכנון, ושניהם מסרו בשם לוי (ירו\u0027, יומא פ\"ד ה\"א). נהג לדרוש מקראות (ירו\u0027, סוטה פ\"א ה\"ז)."},{"i":85,"n":"אבא בר קוריה","l":"א","b":"מובא בב\"ר (פי\"ט - ג\u0027)."},{"i":86,"n":"אבא בר קפרא","l":"א","b":"מובא בקה\"ר (פ\"א ספ\"ג). אולי הוא בר קפרא."},{"i":87,"n":"אבא בר רב הונא","l":"א","b":"מובא בירושלמי (תרומות פ\"א ה\"ד). ע\"ע רבה בר רב הונא."},{"i":88,"n":"רב אבא בר שומני","l":"א","b":"אמורא בבלי בדור השני. חברו של רב מנשיא בר ירמיה, שהיה תלמידו של רב (עירובין ס\"ד ע\"א)."},{"i":89,"n":"רבי אבא בר שילא","l":"א","b":"מוזכר בבבלי (גיטין כ\"ו ע\"ב), והוא רבה בר שילא (כמובא בכתובות מ\u0027 ע\"א)."},{"i":90,"n":"ר\u0027 אבא בר שמואל","l":"א","b":"מובא בבבלי (ב\"ב ט\"ו ע\"ב). ע\"ע רבה בר שמואל."},{"i":91,"n":"ר\u0027 אבא בר תחליפא","l":"א","b":"נראה, שצ\"ל ר\u0027 אחא בר תחליפא, והיימן כתב: \"ובאמת לא היה אמורא כזה\"."},{"i":92,"n":"רבי אבא בריה דרב ביבי","l":"א","b":"מובא בילקוט שמעוני (פ\u0027 אמור רמז תרמ\"ה)."},{"i":93,"n":"אבא בריה דרב בנימין בר חייא","l":"א","b":"מובא בבבלי (ר\"ה ל\"ה ע\"א). ע\"ע אבא בריה דרב מנימין בר חייא."},{"i":94,"n":"אבא בריה דרב מנימין בר חייא (2)","l":"א","b":"אמורא בבלי בדור השלישי. נראה, שהיה תלמידו של רב הונא בר חייא (חולין פ\u0027 ע\"א). יש שיבושים בשמו בכמה מקומות בש\"ס, שכן המאמר \"עם שאחורי כהנים\" הנמסר בשמו (בסוטה ל\"ח ע\"ב), נמסר גם בשם אבא בריה דרב בנימין בר חייא (ר\"ה ל\"ה ע\"א), ובשם אביי בר בנימין (ירו\u0027, גיטין פ\"ה ה\"ט) ובשם אביי בי רבי בנימין (ירו\u0027, ברכות פ\"ה ה\"ד). ונראה שכולם אותו חכם."},{"i":95,"n":"ר\u0027 אבא בריה דרב נחמן","l":"א","b":"מובא בירושלמי (ערלה פ\"ב ה\"ג). ע\"ע רבה בר נחמני."},{"i":96,"n":"אבא בריה דרבה בר רב הונא","l":"א","b":"אמורא בדור הרביעי. בן בנו של רב הונא (סוטה מ\"ט ע\"א), והוא רבא בריה דרבה בר רב הונא."},{"i":97,"n":"רבי אבא בריה דרבי חייא בר אבא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. בנו ותלמידו של רבי חייא בר אבא (חולין פ\"ו ע\"ב). חברו של רבי זירא (מו\"ק כ\"ב ע\"א). שניהם למדו אצל רבי אמי (חולין פ\"ו ע\"ב). הקשה לרבי אבהו (פסחים נ\"ט ע\"ב). נראה שלמד גם לפני ר\u0027 יוחנן (תמורה י\"ד ע\"ב). רבנן שיבחוהו על נוסח ברכה שלו בברכת האבל (ירו\u0027, ברכות ספ\"ז)."},{"i":98,"n":"ר\u0027 אבא בריה דר\u0027 יוסי בן חלפתא","l":"א","b":"תנא, והוא הוא רבי מנחם בר\u0027 יוסי בן חלפתא ומובא: (ירו\u0027, נדרים פי\"א ה\"א)."},{"i":99,"n":"ר\u0027 אבא בר\u0027 זירא","l":"א","b":"מובא בירושלמי (עירובין פ\"ו ה\"ז), והוא אהבה בריה דר\u0027 זירא."},{"i":100,"n":"אבא גוריא","l":"א","b":"תנא. נראה שהיה בדור השלישי - הרביעי. משמו אמרו אבא גוריין איש צדיין וכן רבי יהודה בר אלעאי (קידושין פ\"ב ע\"א)."},{"i":101,"n":"אבא גוריין איש צדיין","l":"א","b":"תנא. נראה שהיה בדור הרביעי - החמישי. מסר משמו של אבא גוריא (קידושין פ\"ב ע\"א)."},{"i":102,"n":"רבי אבא דמן חיפא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מוזכר פעם בבבלי שר\u0027 אבא ור\u0027 אסי באו אליו לביקור (שבת מ\"ה ע\"ב)."},{"i":103,"n":"רבי אבא דמן כיפה","l":"א","b":"אמורא ארץ ישראלי בדור החמישי - השישי. תלמידו של רבי יונה (ירו\u0027, סוכה פ\"ג ה\"י)."},{"i":104,"n":"ר\u0027 אבא דמן כיפה","l":"א","b":"מובא בירושלמי: \"קומי רבי יונה\" (סוכה פ\"ג ה\"י). \"פני משה\" מפרש שהיה חכם בשם זה, אך \"קרבן העדה\" פירש שר\u0027 אבא אמר: \u0027כוף ידך\u0027, ואם כן אין זה חכם אחר מאשר ר\u0027 אבא ב\u0027."},{"i":105,"n":"רבי אבא דמן עכו","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. נראה, שעבר לדור בקיסרין. כשרצו למנות את רבי אבהו לראש, המליץ שימנו את רבי אבא דמן עכו במקומו (סוטה מ\u0027 ע\"א), אבל לא מצינו שנתמנה לראש. מובא בבבלי (כתובות כ\"ב ע\"א): \"ורבי זירא אמר: \u0027הא מלתא מרבי אבא שמיע לי, ואי לאו רבי אבא דמן עכו שכחתה\u0027\". היה עני מרוד (סוטה שם)."},{"i":106,"n":"רבי אבא דמן קיסרי","l":"א","b":"מובא בבבלי (תענית ט\"ו ע\"ב). גירסת הרי\"ף: ר\u0027 אדא דמן קיסרי."},{"i":107,"n":"רבי אבא האדומי","l":"א","b":"מובא במד\u0027 תנחומא (בראשית ז\u0027). ע\"ע ר\u0027 אבא סמוקה."},{"i":108,"n":"אבא הדורש","l":"א","b":"תנא. שאין לקבוע זמנו המדוייק. מובא בספרי (האזינו)."},{"i":109,"n":"רב אבא הונא הכהן בר אבין","l":"א","b":"מובא במד\"ר (פ\"ג - ז\u0027). זהה שהוא רב הונא הכהן בר אבין (ע\"ע)."},{"i":110,"n":"אבא הושעיא איש טרייא","l":"א","b":"מובא בירושלמי (ב\"ק פ\"י ה\"י). ע\"ע אבא אושעיא איש טורייא."},{"i":111,"n":"רבי אבא הכהן","l":"א","b":"אמורא ארץ ישראלי בדור השני - השלישי. חברו של רבי יוסי הכהן (ר\"ה ט\"ו ע\"ב), ומסר בשמו: \"מעשה ומתו בניו של ר\u0027 יוסי בן רבי חנינא\" (תענית י\"ג ע\"א)."},{"i":112,"n":"ר\u0027 אבא הכהן בר פפא","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של ר\u0027 יוסי בר זבידא (מ\"ר פט\"ו - ז\u0027)."},{"i":113,"n":"ר\u0027 אבא הכהן בר\u0027 אליעזר","l":"א","b":"מובא בב\"ר (פ\"פ - ד\u0027)."},{"i":114,"n":"רבי אבא זוטי","l":"א","b":"מובא בבבלי (מנחות ט\"ו ע\"ב). ע\"ע רבה זוטי."},{"i":115,"n":"אבא חילפא בן קרויא","l":"א","b":"מובא בתוספתא (מע\"ש רפ\"ד [צוקערמאנדל]). ע\"ע אבא חליפא קרויא."},{"i":116,"n":"אבא חליפא קרויא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי חייא בר אבא (ב\"ב קכ\"ג ע\"א). רבן גמליאל (בנו של רבי יהודה נשיאה השני) הלך אליו להתפלל (מד\u0027 תהלים הישן פ\"כ) שמו מובא בכמה כתובים שונים."},{"i":117,"n":"אבא חלפי","l":"א","b":"תנא שזמנו אינו ידוע. מובא במסכת דרך ארץ (פ\"א), שם מסר משום אביו אבא חגרא."},{"i":118,"n":"אבא חלפתא","l":"א","b":"הוא רבי חלפתא, אביו של רבי יוסי בן חלפתא. ומצינו: \"אמר רבי יוסי: \u0027מודה אבא חלפתא בזה שמותר\u0027\" (בכורות כ\"ו ע\"א) רש\"י שינה בד\"ה וכתב: \"אמר רבי יוסי מודה אבא ששמו חלפתא\". ובמקום אחר כתב רש\"י בד\"ה: אלו היה אבא חלפתא: \"אביו של רבי יוסי\" (מעילה י\"ז ע\"ב)."},{"i":119,"n":"אבא חלפתא איש כפר חנניא","l":"א","b":"תנא בדור החמישי. מובא באבות (פ\"ג מ\"ו). מאמרו שם: \"עשרה שיושבין ועוסקין בתורה שכינה שרויה ביניהם\". תלמידו של רבי מאיר (ב\"מ צ\"ד ע\"א), ושל שמעון בן חנניה (תוספתא כלים פ\"ד ה\"ט)."},{"i":120,"n":"אבא חלקיה","l":"א","b":"חסיד גדול שחי בזמן בית המקדש השני. בן בנו של חוני המעגל. מובא בבבלי (תענית כ\"ג ע\"א), שם מסופר על חסידותו והקפדתו היתרה בכל דרכי התנהגותו. כשהיו זקוקים לגשמים, שלחו אליו שיתפלל (שם). אשתו הקפידה מאד על מתן לחם לעניים, ובזכות תפילתה ירד גשם בטרם נענתה תפילת בעלה (שם). עליו אמרו: \"פועל צדק כגון אבא חלקיהו\" (מכות כ\"ד ע\"א)."},{"i":121,"n":"אבא חלקיה מן קרויה","l":"א","b":"תנא שזמנו אינו ידוע. מובא בתוספתא (מע\"ש פ\"ד ה\"ג). ובתוספתא צוקערמאנדל הגירסא: אבא חילפא מן קרויא."},{"i":122,"n":"אבא חנן","l":"א","b":"תנא בדור השלישי - הרביעי. מסר הרבה בשם רבי אליעזר (יבמות ס\"ד ע\"א). וכן מסר פעם בשם ר\u0027 יהושע (נדה כ\"ט ע\"א). היה חברו של ר\u0027 שמעון שזורי (נזיר מ\"ה ע\"א)."},{"i":123,"n":"רבי אבא חסידא","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי מובא בירושלמי (נדרים פ\"ח ה\"א). אומר בשם רבי זירא (שם)."},{"i":124,"n":"אבא יהודה","l":"א","b":"חי בדור השני - השלישי לתנאים. מובא בירושלמי (הוריות פ\"ג ה\"ד). חסיד ובעל צדקה. כשירד מנכסיו ולא היה לו לתת צדקה לחכמים, יעצה לו אשתו, שהיתה צדקת, למכור חצי שדהו שנשאר ויתן להם צדקה. וכך עשה, ובירכוהו ר\u0027 אליעזר ור\u0027 יהושע ור\u0027 עקיבא, ועושרו חזר אליו (שם)."},{"i":125,"n":"אבא יודן","l":"א","b":"מובא בב\"ר (פ\"י - ח\u0027), והוא אבדן תלמידו הגדול דרב: תוספות כתבו שאבדן הוא אבא יודן בירושלמי (יבמות ק\"ה ע\"ב)."},{"i":126,"n":"אבא יודן איש ציידן","l":"א","b":"תנא בדור השלישי. העיד בשם רבי אליעזר (תוספתא אהלות פי\"ח ז\u0027)."},{"i":127,"n":"אבא יוסי","l":"א","b":"מובא בבבלי (מנחות ל\"ג ע\"ב), וצ\"ל: רב יוסף, כמו ברי\"ף, והוא רב יוסף מחכמי הסבוראים."},{"i":128,"n":"אבא יוסי בן אבא (2)","l":"א","b":"נראה, שהיה בסוף תקופת התנאים. מרבותיו של ר\u0027 יוחנן. \"א\"ר יוחנן: \u0027משום אבא יוסי בן אבא שמיע לי\u0027\" (חולין צ\"ז ע\"א)."},{"i":129,"n":"אבא יוסי בן דוסאי","l":"א","b":"מובא במשנה (מכשירין פ\"ב מ\"י), וצ\"ל אבא יוסי בן דוסתאי."},{"i":130,"n":"אבא יוסי בן דוסתאי","l":"א","b":"תנא בדור הרביעי. מסר בשם רבי אליעזר (תוספתא פאה פ\"ד ב\u0027), ובשם רבי יוסי הגלילי (שם פ\"ו ו\u0027). רבי מסר בשמו (זבחים קט\"ז ע\"ב)."},{"i":131,"n":"אבא יוסי בן חנין","l":"א","b":"מובא בבבלי (פסחים נ\"ז ע\"א): \"אבא שאול בן בטניס משמו\". \"דק\"ס\" גורס: אבא יוסי בן חנן. אם אין שיבוש בשמו, הרי שחי בדור הראשון לתנאים."},{"i":132,"n":"אבא יוסי בן חנן","l":"א","b":"תנא. מובא במשנה (מדות פ\"ב מ\"ו). גיר\u0027 \"דק\"ס\": אבא יוסי בן חנין."},{"i":133,"n":"אבא יוסי בן יוחנן","l":"א","b":"מובא בבבלי (כריתות ו\u0027 ע\"ב). \"אבא\" הוא גם לשון כבוד, ואין לדעת מי הוא, שכן יש יוסי בן יוחנן איש ירושלים מחכמי ה\"זוגות\", ויש אבא יוסי בן יוחנן איש ירושלים שאמר משום רבי מאיר (יבמות נ\"ג ע\"ב), ויש אבא יוסי בן יוחנן איש ינוח (ירו\u0027, כלאים פ\"ב ה\"ד)."},{"i":134,"n":"אבא יוסי בן יוחנן איש יוני","l":"א","b":"הוא אבא יוסי בן יוחנן איש ינוח."},{"i":135,"n":"אבא יוסי בן יוחנן איש ינוח","l":"א","b":"מאחרוני התנאים. מובא בירושלמי יחד עם רבי אלעזר בר\u0027 שמעון. (כלאים פ\"ב ה\"ד)."},{"i":136,"n":"אבא יוסי בן יוחנן איש ירושלים","l":"א","b":"תנא בדור החמישי. תלמידו של רבי מאיר ואמר משמו (יבמות נ\"ג ע\"ב)."},{"i":137,"n":"אבא יוסי בן סימאי","l":"א","b":"בדור המעבר בין התנאים לאמוראים. \"מעשה בשני ת\"ח שהיו באים עם אבא יוסי בן סימאי בספינה וטבעה והשיא רבי נשותיהן\" (יבמות קט\"ו ע\"א)."},{"i":138,"n":"אבא יוסי בן קטנותא","l":"א","b":"תנא שאין לקבוע זמנו המדוייק. עליו אמרו: \"משמת אבא יוסי בן קטנותא בטלו חסידים, ולמה נקרא שמו אבא יוסי בן קטנותא? שהיה מקטני חסידים\" (סוף סוטה)."},{"i":139,"n":"אבא יוסי בר חנן","l":"א","b":"אמורא ארץ ישראלי בדור הראשון. מסר בשם אבא כהן ברדלא (ספרי דברים פסוק ב\u0027)."},{"i":140,"n":"אבא יוסי המחוזי","l":"א","b":"תנא בדור השלישי. מובא במכילתא שר\u0027 נתן אמר משמו. (פ\u0027 בשלח מס\u0027 ויהי פ\"ג)."},{"i":141,"n":"אבא יוסי התורתי","l":"א","b":"מובא בב\"ר (פל\"ד - י\u0027)."},{"i":142,"n":"אבא יוסי חלי קופרי איש טבעון","l":"א","b":"תנא בדור הראשון. ר\u0027 יהושע מסר משמו (מכשירין פ\"א מ\"ג)."},{"i":143,"n":"אבא יוסי חנן איש יוני","l":"א","b":"הוא אבא יוסף בן יוחנן איש ינוח."},{"i":144,"n":"אבא יוסף בן דוסתאי","l":"א","b":"מובא בבבלי (ברכות כ\"ח ע\"א). נראה, שצ\"ל אבא יוסי בן דוסתאי."},{"i":145,"n":"אבא יוסף הבנאי","l":"א","b":"תנא בדור הרביעי. כששאל אבנימוס הגרדי (מחכמי אומות העולם) לחכמים היאך ברא ה\u0027 את עולמו, שלחו לו לאבא יוסף הבנאי והוא השיבו (ש\"ר רפ\"ג)."},{"i":146,"n":"אבא יוסף החורני","l":"א","b":"תנא בדור השלישי. השיב לר\u0027 ישמעאל (תוספתא מקואות ספ\"ג)."},{"i":147,"n":"אבא ירמיה","l":"א","b":"תנא שאין לקבוע זמנו המדויק. מסר בשם רבי מאיר (ויק\"ר רפל\"ד)."},{"i":148,"n":"אבא כהן בר דלייה","l":"א","b":"ע\"ע אבא כהן ברדלא."},{"i":149,"n":"אבא כהן ברדלא","l":"א","b":"תנא שאין לקבוע זמנו המדויק. היה מן התנאים האחרונים. ר\"ל מסר בשמו את הדין הידוע ש\"ד\u0027 אמות של אדם קונות לו בכל מקום\" (ב\"מ י\u0027 ע\"א). מובא בירושלמי ושם אבא בר דלייה (ב\"ב פ\"ח ה\"ג)."},{"i":150,"n":"אבא מהגרוניא","l":"א","b":"אמורא בבלי בדור השלישי. בנו, רב שמואל בר אבא מהגרוניא, שאל מרבי אבא (ב\"ק ז\u0027 ע\"ב). אחר פטירתו של אבא מהגרוניא, נשא רבי אבא את אלמנתו לאשה. (ב\"ק פ\"ח ע\"א)."},{"i":151,"n":"אבא מר בר רב אשי","l":"א","b":"מובא בבבלי (סוטה ל\"ח ע\"ב). אולי צ\"ל מר בר רב אשי."},{"i":152,"n":"אבא מר בריה דרב פפא","l":"א","b":"אמורא בבלי בדור הששי. אביו רב פפא שיבחו ואמר עליו: \"כגון אבא מר ברי דקים לי בגוויה [שאינו משקר]\" (כתובות פ\"ה ע\"א), ולכבודו הפסיק רב פפא את סעודתו לפנים משורת הדין (ברכות מ\"ה ע\"ב). היה קשור בעסקי אביו (ב\"מ ס\"ט ע\"ב)."},{"i":153,"n":"ר\u0027 אבא מרומניא","l":"א","b":"מובא במ\"ר (פכ\"ב - ח\u0027). זהה לר\u0027 אבא סרונגיא (ע\"ע)."},{"i":154,"n":"אבא מרי","l":"א","b":"אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר\u0027 חזקיה (ירו\u0027, סוטה פ\"ו ה\"א). חברם של ר\u0027 אליעזר [בר\u0027 יוסי האמורא] (ירו\u0027, ביצה פ\"א ה\"ז), ור\u0027 מתניא (שם)."},{"i":155,"n":"ר\u0027 אבא מרי אחוי דר\u0027 יוסי","l":"א","b":"אמורא ארץ ישראלי בדור החמישי. אחיו של האמורא רבי יוסי (ירו\u0027, ברכות פ\"ז ה\"א)."},{"i":156,"n":"ר\u0027 אבא מרי בבלייה","l":"א","b":"אמורא שאין פרטים עליו. מובא פעם אחת בירושלמי (מגילה פ\"ב ה\"ה) ונראה שאין הוא אבא מרי הארץ ישראלי, שכן מודגש \"בבלייה\", שהיה מבבל."},{"i":157,"n":"ר\u0027 אבא מרי בצלאה","l":"א","b":"מובא במדרש שמואל (פי\"ג)."},{"i":158,"n":"אבא מרי ריש גלותא","l":"א","b":"ראש הגולה בבבל בדור הרביעי לאמוראים. מובא בבבלי (נדה ס\"ז ע\"ב)."},{"i":159,"n":"אבא נהוראי","l":"א","b":"נראה, שהיה מן התנאים. רבי חנינא ורבי מרינוס מסרו משמו (ב\"ר פצ\"א - ט\u0027)."},{"i":160,"n":"ר\u0027 אבא סדרונגיא","l":"א","b":"מובא במ\"ר (פי\"ד - ד\u0027). זהה לר\u0027 אבא סרונגיא (ע\"ע)."},{"i":161,"n":"ר\u0027 אבא סדרוניא","l":"א","b":"מובא במד\"ר (פ\u0027 י\"ד). זהה לר\u0027 אבא סרונגיא (ע\"ע)."},{"i":162,"n":"אבא סוראה","l":"א","b":"אמורא בבלי בדור הרביעי. חותנו של רב פפא (כתובות ל\"ט ע\"ב). רב פפא השיא לבנו את אחות אשתו, היא בת אבא סוראה (כתובות נ\"ב ע\"ב)."},{"i":163,"n":"אבא סימי","l":"א","b":"מובא בירושלמי (יבמות פט\"ז ה\"ה), רבא בר זבדא בשם רב: \"מעשה באבא סימי ששקעה ספינתו בים\". נראה, שהוא אבא יוסי בן סימאי (ע\"ע)."},{"i":164,"n":"ר\u0027 אבא סלא רבא","l":"א","b":"אמורא בדור הרביעי. מובא בבבלי (כתובות קי\"א ע\"א). אביי השיב על קושייתו."},{"i":165,"n":"ר\u0027 אבא סמוקה","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי (ברכות פ\"ט ה\"א). ר\u0027 חלבו ור\u0027 ברכיה מסרו בשמו (שם). מאמרי אגדה שלו מובאים בירושלמי."},{"i":166,"n":"אבא סמוקיד (2)","l":"א","b":"מובא במ\"ר (פ\"ג - ז\u0027). ר\u0027 ברכיה מסר בשם ר\u0027 חלבו בשמו."},{"i":167,"n":"ר\u0027 אבא סמיקא","l":"א","b":"מובא בירושלמי: ר\u0027 ברכיה ור\u0027 חלבו בשם ר\u0027 אבא סמיקא\" (ברכות פ\"ט ה\"ג). ונראה, שהוא ר\u0027 אבא סמוקה (ע\"ע)."},{"i":168,"n":"ר\u0027 אבא סנגוריא","l":"א","b":"מובא בתנחומא (מטות - ז\u0027). זהה לר\u0027 אבא סרונגיא (ע\"ע)."},{"i":169,"n":"אבא סקרא","l":"א","b":"ראש בריוני ירושלים בזמן חורבן בית שני. בן אחותו של רבן יוחנן בן זכאי. עזר לריב\"ז לצאת מירושלים אל הרומאים (גיטין נ\"ו ע\"א). ע\"ע בן בטיח."},{"i":170,"n":"ר\u0027 אבא סרונגיא","l":"א","b":"אמורא ארץ ישראלי שזמנו אינו ידוע. מובא בב\"ר (פ\"א - ו\u0027). נמנה עם בעלי האגדה. שמו נשתבש בכמה אופנים."},{"i":171,"n":"ר\u0027 אבא סרונגלא","l":"א","b":"מובא בפסיקתא רבתי (פ\u0027 ביום השמיני). זהה לר\u0027 אבא סרונגיא (ע\"ע)."},{"i":172,"n":"אבא פנימון","l":"א","b":"מובא בירושלמי (תרומות פ\"ג ה\"ג). לפי לשון הירושלמי יתכן שהוא אבא בנימין (ע\"ע)."},{"i":173,"n":"אבא צידוני","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בקה\"ר (פ\"ז - ג\u0027). נזכר יחד עם תלמידי ר\u0027 אבא (שם)."},{"i":174,"n":"אבא קוריי","l":"א","b":"(מובא ב\"ר פי\"ט)."},{"i":175,"n":"ר\u0027 אבא קרתיגנאה","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי (שבועות פ\"ג ה\"א). ר\u0027 אלעאי מתרץ שם קושייתו."},{"i":176,"n":"רבי אבא קרתיגניא","l":"א","b":"מובא בירושלמי (כלאים פ\"א ה\"ט). זהה לר\u0027 אבא קרתיגנאה (ע\"ע)."},{"i":177,"n":"אבא שאול (2)","l":"א","b":"תנא בדור השני. נראה, שזכה לראות את המקדש (מדות פ\"ב מ\"ה). קיבל מר\u0027 יוחנן בן זכאי (אבות פ\"ב מ\"ח). \"ארוך בדורו הוה\" (נדה כ\"ד ע\"ב)."},{"i":178,"n":"אבא שאול בן אמא מרים","l":"א","b":"תנא בדור החמישי או בדור קודם. שמואל מסר משמו (כתובות פ\"ז ע\"א)."},{"i":179,"n":"אבא שאול בן בטנית","l":"א","b":"תנא קדמון. נראה, שחי שני דורות לפני החורבן לפי: \"מעשה בימי אביו של רבי צדוק ובימי אבא שאול בן בטנית\" (שבת קנ\"ז ע\"א) - ורבי צדוק צם 04 שנה לפני החורבן (גיטין נ\"ו ע\"א): וא\"כ הם חיו שני דורות לפני החורבן. ושניהם היו חנוונים ומסופר על חסידותם (ירו\u0027, ביצה פ\"ג ה\"ח). וכשחלה באו חכמים לבקרו (שם). לפני פטירתו ציוה לבניו לקברו למרגלות אביו ולהתיר הציציות מטליתו (שמחות פי\"ב). רש\"י כתב: \"שהיה חכם גדול ובאים רבים לשאול הימנו\" (ביצה כ\"ט ע\"א ד\"ה: תנא)."},{"i":180,"n":"אבא שאול בן חוני","l":"א","b":"מובא בתוספתא (מקואות פ\"ג)."},{"i":181,"n":"אבא שאול בן ננס","l":"א","b":"מובא באבות דר\"נ (רפ\"ט)."},{"i":182,"n":"אבא שאול בר נש","l":"א","b":"מובא בבבלי (נדה כ\"ה ע\"ב)."},{"i":183,"n":"אבא שאול גבל דבי רבי","l":"א","b":"מובא בבבלי (פסחים ל\"ד ע\"א). אין ראיה מכרעת שהיה חכם."},{"i":184,"n":"אבא שאול מבית מרמשא","l":"א","b":"כך היתה הגרסא לפני ה\"יוחסין\" (אבות פ\"ב מ\"ח): שכתב שהיה תלמיד חבר לרבי יוחנן בן זכאי (אם כן, היה בדור הראשון - השני לתנאים)."},{"i":185,"n":"אבא תחנא חסידא","l":"א","b":"מובא בקה\"ר (פ\"ט - ז\u0027). שם מסופר עליו, שערב שבת עם חשכה הכניס מוכה שחין לעיר ונעשה לו נס והשמש זרחה שוב, להראות שעדיין לא היה שבת."},{"i":186,"n":"אבא תנחומא","l":"א","b":"מובא במדרש תהלים (פ\"א - ק\u0027), והוא ר\u0027 תנחומא."},{"i":187,"n":"ר\u0027 אבדומא","l":"א","b":"הוא אבדימי."},{"i":188,"n":"ר\u0027 אבדומא דמן חיפה","l":"א","b":"מובא בירושלמי (מו\"ק פ\"ג ה\"ה), והוא ר\u0027 אבדימי דמן חיפה (ע\"ע)."},{"i":189,"n":"ר\u0027 אבדומא מלחא","l":"א","b":"מובא בירושלמי (סוכה פ\"ב ה\"ט). והוא ר\u0027 אבדימא מלחא. (ע\"ע)."},{"i":190,"n":"ר\u0027 אבדומה דמן נחותא","l":"א","b":"מובא בירושלמי (שקלים פ\"ג ה\"ב), והוא ר\u0027 אבדימי."},{"i":191,"n":"רבי אבדומי בר טוביא","l":"א","b":"נראה, שהוא ר\u0027 אבדימי בר טובי."},{"i":192,"n":"אבדומי המדורי","l":"א","b":"הוא בר המדור."},{"i":193,"n":"אבדומי נחותא","l":"א","b":"מובא בירושלמי (עירובין פ\"א ה\"ו). והוא רב דימי."},{"i":194,"n":"אבדימא","l":"א","b":"הוא אבדומא."},{"i":195,"n":"רבי אבדימא דציפורין","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. תלמידו של רבי מנא (ירו\u0027, ברכות פ\"ד ה\"ג). אביו, שגם הוא היה חכם, נקרא על שם בנו: \"רבי אליעזר בשם ר\u0027 אימי אבוי דר\u0027 אבדומא דציפורי\" (ירו\u0027, ביצה פ\"א ה\"ט)."},{"i":196,"n":"ר\u0027 אבדימא מלחא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי (ב\"מ ספ\"ד: סוכה פ\"ב ה\"ה)."},{"i":197,"n":"אבדימוס","l":"א","b":"תנא בדור החמישי, והוא רבי מנחם ברבי יוסי בן חלפתא המובא בירושלמי (יבמות פ\"א ה\"א)."},{"i":198,"n":"אבדימי","l":"א","b":"הוא אבדומא או אבדימא."},{"i":199,"n":"ר\u0027 אבדימי","l":"א","b":"מאחרוני אמוראי ארץ ישראל. תלמידו של ר\u0027 מנא (ירו\u0027, עירובין פ\"י ה\"ב), יחד עם חברו ר\u0027 אליעזר [בנו של ר\u0027 יוסי]."},{"i":200,"n":"ר\u0027 אבדימי אחוה דר\u0027 יוסי","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. אחיו של האמורא ר\u0027 יוסי מראשי דור הרביעי. ר\u0027 אחא כעס עליו וחלה ונטה למות, ואחיו ר\u0027 יוסי ביקרו ונתרפא (ירו\u0027, ב\"ב פ\"ב ה\"ג)."},{"i":201,"n":"ר\u0027 אבדימי בר ברתיה דר\u0027 טובי","l":"א","b":"אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא בירושלמי (סנהדרין פ\"ו ה\"ה). מסר (שם) בשם ר\u0027 יאשיה [שחי בדור השלישי]."},{"i":202,"n":"ר\u0027 אבדימי בר המדורא","l":"א","b":"מובא (סוכה כ\u0027 ע\"א), והוא בר המדורי."},{"i":203,"n":"ר\u0027 אבדימי בר חמא","l":"א","b":"מובא בבבלי (ע\"ז י\"ט ע\"א). נראה שהוא ר\u0027 אבדימי בר חמא בר חסא (ע\"ע). אמר: \"כל העוסק בתורה, הקב\"ה עושה לו חפציו\" (שם)."},{"i":204,"n":"ר\u0027 אבדימי בר חמא בר חסא","l":"א","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (שבת פ\"ח ע\"א). שם מאמרו הידוע: \"מלמד שכפה הקב\"ה עליהם את ההר כגיגית\"."},{"i":205,"n":"ר\u0027 אבדימי בר חסא","l":"א","b":"מובא בבבלי (זבחים קי\"ח ע\"א). נראה שהוא ר\u0027 אבדימי בר חמא בר חסא."},{"i":206,"n":"ר\u0027 אבדימי בר טובי","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי (מו\"ק פ\"ג ה\"ה). מסר בשם רבי אבהו (שם). יש גם אבימי בר טובי, תלמיד ר\u0027 אבהו (ירו\u0027, נזיר פ\"ט ה\"א). ואולי אחד הם."},{"i":207,"n":"ר\u0027 אבדימי בר נחוניא","l":"א","b":"מובא במדרש תהלים (רפק\"ג)."},{"i":208,"n":"ר\u0027 אבדימי בר תנחום","l":"א","b":"מובא בירושלמי (מו\"ק פ\"ג ה\"ח)."},{"i":209,"n":"ר\u0027 אבדימי דמן חיפה","l":"א","b":"אמורא ארץ ישראלי בדור השני - שלישי. מסר בשם ריש לקיש (ירו\u0027, סוכה פ\"א ה\"א). מתלמידיו: רבי אבהו (ירו\u0027, מו\"ק פ\"ג ה\"ה) ור\u0027 זירא (ירו\u0027, תרומות פ\"ג ה\"ג). מושבו היה בחיפה, שם היה מורה הוראה (ירו\u0027, עירובין פ\"ב ה\"א)."},{"i":210,"n":"רב אבדימי נחותא","l":"א","b":"מובא בירושלמי (עירובין פ\"א ה\"ו), והוא רב דימי."},{"i":211,"n":"רבי אבדימס","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי (כתובות פי\"א ה\"ב)."},{"i":212,"n":"אבדן","l":"א","b":"בדור המעבר בין התנאים לאמוראים. תלמידו הגדול של רבי (ירו\u0027, ברכות פ\"ה ה\"א) והאמורא שלו (שם פ\"ד ה\"א). אירעו לו אסונות משפחתיים רבים (יבמות ק\"ה ע\"ב)."},{"i":213,"n":"אבהו","l":"א","b":"מוחלף לפעמים באבוה."},{"i":214,"n":"רב אבהו","l":"א","b":"אמורא בבלי בדור הששי. נשא ונתן עם רב אשי (ב\"ק קי\"ז ע\"א). מראשי כלה דרפרם בפומבדיתא (חולין מ\"ט ע\"א). בנו, רב שמואל, היה מרבנן סבוראי."},{"i":215,"n":"רבי אבהו","l":"א","b":"אמורא ארץ ישראלי בדור השלישי מתלמידיו המובהקים של רבי יוחנן (כתובות נ\"ז ע\"א). אמר על רבו: \"מפתח לנו רבי יוחנן פתח מאיר כאורה\" (ירו\u0027, פסחים פ\"ב סה\"ב). רש\"י כתב, שרבי אלעזר היה רבו (יומא פ\u0027 ע\"א), וכן קיבל מר\"ל (פסחים מ\"ו ע\"א). מושבו היה בקיסרי והיה מקורב למלכות (חגיגה י\"ד ע\"א). התווכח הרבה עם המינים וניצחם (ברכות י\u0027 ע\"א). חבריו הגדולים היו רבי אמי, רבי אסי, ורבי חייא בר אבא (יבמות ס\"ה ע\"ב). אחרי פטירת רבי אמי רצו להושיבו בראש ומרוב ענוה ביקש להושיב במקומו את רבי אבא מעכו (סוטה מ\u0027 ע\"א). היה מבורך בעושר (שבת קי\"ט ע\"א) ביופי (ב\"מ פ\"ד ע\"א). אמרו עליו \"שופריה דר\u0027 אבהו מעין שופריה דיעקב אבינו\" (שם). היה בעל כח רב (ברכות ס\u0027 ע\"א). היו לו תלמידים רבים וביניהם ראשי הדור הרביעי רבי יונה (ירו\u0027, סנהדרין ספ\"ו) ורבי יוסי (סנהדרין ספ\"ו) כן היו תלמידיו, אבימי (קדושין ל\"א ע\"ב), רבי זעירא (ירו\u0027, ברכות רפ\"ט), ורבי חנינא בנו (קידושין ל\"ג ע\"ב). חמו של רבי אבהו היה חכם ושמו רבי תחליפא דקיסרין, ורבי אבהו אמר משמו (קה\"ר ספ\"י). כשמת רבי אבהו הראו לו את חלקו המזומן לו לעוה\"ב, ואפילו עמודי השיש שבקיסרי זלגו דמעות (מו\"ק כ\"ה ע\"ב)."},{"i":216,"n":"ר\u0027 אבהו בר אחא","l":"א","b":"מובא במדרש תהלים (הישן פק\"ז). ב\"סה\"ד\" כתב: \"קרוב בעיני שהוא ר\u0027 אבא בר אחא\"."},{"i":217,"n":"אבהו בר גניבא","l":"א","b":"אמורא בבלי בדור החמישי. תלמידו של רבא (ב\"ב קל\"ט ע\"א)."},{"i":218,"n":"ר\u0027 אבהו בר זוטרתי","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של ר\u0027 יהודה בר זבידא (ברכות י\"ב ע\"ב)."},{"i":219,"n":"ר\u0027 אבהו בר זעירא","l":"א","b":"אמורא, כנראה, ארץ ישראלי, שאין לקבוע זמנו המדוייק. מובא במדרש תהלים (פ\"ד - י\"ב)."},{"i":220,"n":"ר\u0027 אבהו בר חנינא","l":"א","b":"מובא בתנחומא (הישן, ויצא - ג\u0027)."},{"i":221,"n":"ר\u0027 אבהו בר כהנא","l":"א","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (מנחות צ\"ה ע\"ב)."},{"i":222,"n":"רבי אבהו בר נגרי","l":"א","b":"אמורא ארץ ישראלי. מובא פעם אחת בש\"ס הירושלמי (פאה פ\"ה ה\"ד): יתכן שהוא ר\u0027 אייבו בר נגרי."},{"i":223,"n":"אבוברם","l":"א","b":"אמורא בבלי בדור החמישי - הששי. מובא בבבלי: \"אמר רבינא אמר לי סמא בר חילקאי אקשי בה אבוה דבר אבוברם\" (חולין ל\"ח ע\"א), ופרש\"י שם: \"זהו אבוברם עצמו ומכירין את הבן ולא את האב והיו קורין אותו על שם בנו שעשו את הבן סימן לו\"."},{"i":224,"n":"אבודמא","l":"א","b":"ע\"ע אבדימי או אבדימא."},{"i":225,"n":"ר\u0027 אבודמא דציפורי","l":"א","b":"מובא בירושלמי (ביצה פ\"א ה\"ט). והוא ר\u0027 אבדימא דציפורין."},{"i":226,"n":"אבוה (2)","l":"א","b":"חי בבבל בתקופת אביי בדור רביעי לאמוראים. אביו של רב יעקב בר אבוה. אביי אמר עליו שהוא \"בן תורה\" (קידושין ל\"א ע\"ב). אין לדעת אם נמנה עם האמוראים."},{"i":227,"n":"אבוה בר איהי","l":"א","b":"אמורא בבלי בדור השני. מושבו בנהרדעא. תלמיד מובהק של שמואל (נזיר כ\"ד ע\"ב). הוא ואחיו מנימן בר איהי היו חסידים גדולים (מגילה כ\"ח ע\"א). לאחד מהם נתגלה אליהו הנביא (כתובות ס\"א ע\"א)."},{"i":228,"n":"אבוה דבר אבוברם","l":"א","b":"מובא בבבלי (חולין ל\"ח ע\"א), והוא אבוברם עצמו (ע\"ע)."},{"i":229,"n":"אבוה דבר נטה","l":"א","b":"מובא בירושלמי (תענית פ\"ד ה\"ב). ע\"ע ר\u0027 חיננא אבוה דר\u0027 ינטה."},{"i":230,"n":"אבוה דרב אחא בריה דרב איקא","l":"א","b":"מובא בבבלי (ע\"ז ס\"ה ע\"א), והוא רב איקא עצמו (ע\"ע)."},{"i":231,"n":"רב אבוה דרב משרשיא","l":"א","b":"יש שכך גורסים בבבלי (עירובין כ\"ד ע\"א), ויש גורסים: ר\u0027 אבא אחוה דרב בריה דרב משרשיא."},{"i":232,"n":"אבוה דרב ספרא","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. שאל את רבי זירא (ירו\u0027, כלאים פ\"ט ה\"ד)."},{"i":233,"n":"אבוה דרבי אפטוריקי","l":"א","b":"אמורא, כנראה, ארץ ישראלי, שאין לקבוע זמנו המדוייק. שמו היה דוסתאי (חולין ס\"ד ע\"ב). נראה, שבנו היה מפורסם ממנו ועל כן נקרא על שם בנו. היה שונה ברייתות (ב\"מ ה\u0027 ע\"א)."},{"i":234,"n":"אבוה דר\u0027 אבין","l":"א","b":"אמורא בבלי בדור הרביעי. מובא מספר פעמים בבבלי כשונה ברייתות (גיטין נ\"ג ע\"א). פעם שנה ברייתא לפני רבי זירא (שם פ\"ה ע\"א). כנראה שנה ברייתות בישיבות האמוראים בבבל."},{"i":235,"n":"אבוה דר\u0027 אושעיה","l":"א","b":"מובא בבבלי (מו\"ק כ\"ד ע\"א), והוא רבי חמא בר ביסא [אביו של רבי אושעיא]. ובירושלמי מובא: \"ר\u0027 חמא אבוה דר\u0027 הושעיא\" (מו\"ק פ\"ג ה\"ה)."},{"i":236,"n":"אבוה דר\u0027 זירא","l":"א","b":"אמורא בבלי בדור השני. אביו של האמורא רבי זירא. שמו היה איסי (מו\"ק כ\u0027 ע\"ב). הקשה על דברי ר\u0027 יהושע בן לוי (תענית כ\"ו ע\"ב). היה גבאי מסים של המלך, שהקל על העם (סנהדרין כ\"ה ע\"ב)."},{"i":237,"n":"אבוה דשמואל","l":"א","b":"ע\"ע אבא בר אבא אבוה דשמואל."},{"i":238,"n":"אבוה דשמואל בר אבין","l":"א","b":"מובא בבבלי (סנהדרין נ\"א ע\"ב). \"דק\"ס\" גורס: אבוה דר\u0027 אבין."},{"i":239,"n":"אבוה דשמואל בר יצחק","l":"א","b":"אמורא בבלי בדור השני. מובא בבבלי על שם בנו (זבחים קי\"א ע\"ב). בנו, ר\u0027 שמואל בר יצחק, מסר בשם אביו מאמר שקיבל מרב (ירו\u0027, שבועות פ\"ד ה\"א). היה חסיד גדול. ונפטר לאחר שצם יומיים בצום כיפור משום ספק (ירו\u0027, ר\"ה פ\"א ה\"ד)."},{"i":240,"n":"אבויה","l":"א","b":"ע\"ע אבוה."},{"i":241,"n":"אבויה דר\"ש","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי נראה שרב יוסי קיבל ממנו (ירו\u0027, פאה פ\"א ה\"ה)."},{"i":242,"n":"אבון","l":"א","b":"ע\"ע אבין."},{"i":243,"n":"רבי אבון בר ביסנא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם רבי יונתן דבית גוברין (ירו\u0027, יבמות פ\"א סה\"א), ובשם ר\u0027 אבא בר ממל (שם פ\"ו ה\"ב)."},{"i":244,"n":"ר\u0027 אבון בר חייא","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. ר\u0027 שמאי (שמי) מסר משמו (ירו\u0027, שקלים פ\"ג ה\"א)."},{"i":245,"n":"אבון בר חסדאי","l":"א","b":"הוא רבין בר רב חסדא."},{"i":246,"n":"רבי אבון הלוי","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי אבא בר כהנא (תנחומא, תזריע - ח\u0027). מבעלי האגדה הנודעים. בעל המאמר: \"הנפטר מחבירו יאמר לו לך לשלום והנפרד מן המת יאמר לך בשלום\" (שילהי ברכות)."},{"i":247,"n":"אבונא","l":"א","b":"מובא בירושלמי (שביעית פ\"ד ה\"ב). ע\"ע ר\u0027 אבינא."},{"i":248,"n":"ר\u0027 אבונא בר סחורה","l":"א","b":"מובא בירושלמי (פסחים פ\"י ה\"ה)."},{"i":249,"n":"רבי אבונא ספרא","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. מובא בירושלמי (מגילה פ\"ג ה\"ז)."},{"i":250,"n":"רבי אבונה בר סחורה","l":"א","b":"אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. נראה שחי בדור החמישי - הששי. מובא בירושלמי (פסחים פ\"י ה\"ה)."},{"i":251,"n":"רבי אבונה זעירא","l":"א","b":"אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא בירושלמי (שביעית פ\"ד ה\"ב), שם מסופר שגויים אנסוהו לרוץ בשבת אחרי חמור."},{"i":252,"n":"אבורודימוס","l":"א","b":"כך מובא בירושלמי (שביעית פ\"ח ה\"ח) ובבבלי: ורדימס (ע\"ע)."},{"i":253,"n":"אבטולומוס","l":"א","b":"תנא ארץ ישראלי בדור השלישי. מובא בבבלי (עירובין ל\"ו ע\"א). רבו של ר\u0027 יוסי בר חלפתא."},{"i":254,"n":"אבטולומוס בר ראובן","l":"א","b":"מובא בבבלי (ב\"ק פ\"ג ע\"א), והוא ר\u0027 ראובן בן איסטרובלי (ע\"ע), על פי גירסת התוס\u0027 (שם, בד\"ה: התירו)."},{"i":255,"n":"אבטולוס","l":"א","b":"אמורא ארץ ישראלי בדור הראשון. מובא בבבלי (מנחות נ\"ג ע\"א). היה דור עשירי לעזרא. בן בנו, רבי עזרא, בא לפני רבי פרידא (שם)."},{"i":256,"n":"ר\u0027 אבטולוס בן ראובן","l":"א","b":"מובא בבבלי (סוטה מ\"ט ע\"ב). והוא ר\u0027 ראובן בן איסטרובלי, (ע\"ע)."},{"i":257,"n":"רבי אבטולוס הזקן","l":"א","b":"תנא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא במכילתא (בשלח פ\"ג). וגירסת הילקוט והגר\"א וגירסא שלנו: \"רבי אבשלום הזקן\"."},{"i":258,"n":"רבי אבטילס","l":"א","b":"תנא בדור החמישי. מובא בבבלי (שבת קי\"ח ע\"ב). בנו הרביעי של רבי יוסי בן חלפתא."},{"i":259,"n":"אבטליון","l":"א","b":"חכם קדום. חי יותר ממאה שנה לפני חורבן בית שני. נמנה עם ה\"זוגות\" שהיו אחר אנשי כנסת הגדולה. הוא וחברו שמעיה היו הזוג הרביעי. היה אב\"ד ושמעיה בן זוגו היה נשיא (חגיגה ט\"ז ע\"א). שניהם היו ממשפחת גרים (גיטין נ\"ז ע\"ב). תלמידיהם היו הלל ושמאי (אבות פ\"א מי\"ב). ע\"ע שמעיה."},{"i":260,"n":"אבי רודימס","l":"א","b":"מובא בירושלמי (שביעית פ\"ח ה\"ה). והוא וורדימס (ע\"ע רבי מנחם בר\u0027 יוסי בן חלפתא)."},{"i":261,"n":"אביבי סנוותאה","l":"א","b":"מובא בבבלי (שבת י\"ז ע\"ב). כך הגירסא בדפוסים הישנים, ולפנינו: אבימי סנוותאה (ע\"ע אבימי נותאה)."},{"i":262,"n":"אבידן","l":"א","b":"מובא בבבלי (ברכות כ\"ז ע\"ב), והוא אבדן, תלמידו של רבי (ע\"ע)."},{"i":263,"n":"ר\u0027 אביה","l":"א","b":"מובא בתנחומא (פ\"ג - ז\u0027)."},{"i":264,"n":"ר\u0027 אביטול ספרא","l":"א","b":"אמורא בבלי, שאין לקבוע זמנו המדוייק. מובא בבבלי (מו\"ק י\"ח ע\"א), שמסר בשם רב."},{"i":265,"n":"אביי","l":"א","b":"אמורא בבלי בדור הרביעי. מגדולי האמוראים. נולד בשנת ד\u0027 ל\"ז (772), ונפטר בגיל 06 (ר\"ה י\"ח ע\"א), בשנת ד\u0027 צ\"ז (733) (\"אגרת רב שרירא גאון\"). הוא וחברו הצעיר רבא הטביעו חותמם על הש\"ס, שנקרא \"הויות דאביי ורבא\" (סוכה כ\"ח ע\"א). היה יתום מאביו ואמו - כשעברתו אמו מת אביו, וכשילדתו - מתה אמו (קידושין ל\"א ע\"ב). רבה בר נחמני, שהיה דודו (\"ערוך\" ערך אביי), גידלו בביתו (נדרים נ\"ד ע\"ב ר\"ן), והיה גם רבו המובהק (שבת כ\"ב ע\"א). רבו המובהק השני היה רב יוסף (קידושין ל\"ג ע\"א), ואביי נהפך אח\"כ לתלמיד חבר לו. שני רבותיו אלה עמדו בראש ישיבת פומבדיתא, ואחר פטירת רב יוסף נתמנה אביי ראש ישיבת פומבדיתא (סוף הוריות). הוא מלך משנת ד\u0027 פ\"ב עד ד\u0027 צ\"ז (423 - 733). היו לו מאות תלמידים (כתובות ק\"ו ע\"א). במחלוקת אביי ורבא הלכה כרבא, חוץ מ\"יע\"ל קג\"ם\" שבהם הלכה כאביי (ב\"מ כ\"ב ע\"ב). במחלוקת אביי ורב יוסף הלכה כאביי, חוץ מ\"במחצה\" (רמב\"ם בפסקי עירובין). שם אביו, כנראה, כייליל (זבחים קי\"ח ע\"ב ברש\"י). בנו רב ביבי היה חכם (סנהדרין ס\"ו ע\"ב). אשתו השניה היתה בת איסי, שהיה נכדו של רב יהודה. ונראה שסמוך לאחר נשואיו אלה, נפטר אביי (יבמות ס\"ד ע\"ב). היה חסיד במעשיו (גיטין מ\"ה ע\"א - רש\"י). כל יום ששי היתה בת קול יוצאת מן השמים ואומרת לו \"שלום עליך\" (תענית כ\"א ע\"ב רש\"י). אחריו היה רבא חברו ראש ישיבת פומבדיתא."},{"i":266,"n":"ר\u0027 אביי","l":"א","b":"אמורא ארץ ישראלי בדור השני. מובא בירושלמי (ר\"ה פ\"א ה\"ח). נשא ונתן עם ריש לקיש (שם). ר\u0027 יונה מסר בשמו (ירו\u0027, תרומות פ\"ה ה\"ב)."},{"i":267,"n":"אביי בי רבי בנימין","l":"א","b":"מובא בירושלמי (ברכות פ\"ה ה\"ד). ע\"ע אבא בריה דרב מנימין בר חייא."},{"i":268,"n":"אביי בר אבא","l":"א","b":"מובא בבבלי (יבמות ל\"ו ע\"א). והוא אביי בר אבין."},{"i":269,"n":"אביי בר אבין","l":"א","b":"אמורא בבלי בדור הרביעי. למד לפני רבה יחד עם אחיו חנינא (פסחים ל\"ד ע\"א). היה חברו של אביי (עירובין פ\"ב ע\"ב)."},{"i":270,"n":"אביי בר בנימין","l":"א","b":"מובא בירושלמי (גיטין פ\"ה ה\"ט). ע\"ע אבא בריה דרב מנימין בר חייא."},{"i":271,"n":"אביי בר הונא","l":"א","b":"אמורא בבלי בדור השלישי. תלמידו של רב חמא בר גוריא (זבחים ס\"ב ע\"ב). גירסת \"שיטה מקובצת\" שצ\"ל: אבין בר הונא, והשם אבין השתבש לאביי."},{"i":272,"n":"אביי בר נאזי","l":"א","b":"מובא בבבלי (ב\"ב קט\"ו ע\"א). כך גירסת הרי\"ף. ולפנינו: אבימי בר נאזי, (ע\"ע)."},{"i":273,"n":"אביי בר רבין","l":"א","b":"מובא בבבלי (שבת פ\"ו ע\"ב), והוא אביי בר אבין."},{"i":274,"n":"אביי בריה דר\u0027 אבהו","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בבבלי (קידושין י\"ט ע\"א). בנו של האמורא ר\u0027 אבהו. (שם). \"סה\"ד\" מפקפק: \"אולי צ\"ל אבימי בריה דר\u0027 אבהו\"."},{"i":275,"n":"אביי קשישא","l":"א","b":"אמורא בבלי בדור השני או השלישי. הקשה מרב על רב (שבת נ\"ו ע\"א). אביי מביאו (כתובות צ\"ד ע\"א). היה שונה ברייתות (יבמות כ\"ד ע\"א). נראה שהכנוי קשישא בא להבדילו מאביי הידוע."},{"i":276,"n":"רב אבייא","l":"א","b":"מובא בירושלמי (סוכה פ\"ב ה\"ח), והוא ר\u0027 אביי, (ע\"ע)."},{"i":277,"n":"אבימוס","l":"א","b":"מובא בירושלמי (ריש יבמות). וב\"סה\"ד\" כתב: ט\"ס (ולי נראה שצ\"ל שם אביטלס כמו בשבת קי\"ח ע\"ב)."},{"i":278,"n":"אבימי (2)","l":"א","b":"אמורא בבלי בדור השני. מובא בבבלי (מנחות ז\u0027 ע\"א). רבו של רב חסדא (שם). משום סיבה שכח אבימי לימודו, ורב חסדא הזכירו (שם)."},{"i":279,"n":"אבימי אחוי דחיפא","l":"א","b":"מובא (ירו\u0027, נדרים פ\"ב ה\"ג), והוא אבימי בר רחבא."},{"i":280,"n":"ר\u0027 אבימי בר טובי","l":"א","b":"אמורא בבלי בדור הרביעי. תלמידו של רב אבהו (ירו\u0027, נזיר רפ\"ט). יש גם ר\u0027 אבדימי בר טובי בשם ר\u0027 אבהו (ירו\u0027, מו\"ק פ\"ג ה\"ה). ואולי אחד הם."},{"i":281,"n":"אבימי בר נאזי","l":"א","b":"חי בבבל בדור הרביעי. מובא בבבלי (ב\"ק קט\"ו ע\"א). חמיו של רבינא."},{"i":282,"n":"אבימי בר פפי","l":"א","b":"אמורא בבלי בדור השלישי. חברם של עולא ור\u0027 נחמן (ע\"ז ס\"ג ע\"א). ר\u0027 זירא פנה אליו בשאלה (ירו\u0027, כתובות פ\"ד הי\"ג)."},{"i":283,"n":"אבימי בר רחבה מפומבדיתא","l":"א","b":"אמורא בבלי בדור הרביעי. הוא ואחיו עיפה מכונים \"חריפי דפומבדיתא\" (סנהדרין י\"ז ע\"ב), והיו תלמידיו של רבה (שבועות כ\"ח ע\"ב). אביו, רחבה דפומבדיתא, היה תלמידו המובהק של רב יהודה (פסחים נ\"ב ע\"ב)."},{"i":284,"n":"אבימי בריה דר\u0027 אבהו","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. בנו של האמורא ר\u0027 אבהו. פעם ביקשוהו חכמים לשאול שאלה אחת מאביו (גיטין כ\"ט ע\"ב). אביו סיפר על כבוד אב שקיים בנו זה (קידושין ל\"א ע\"ב). \"סה\"ד\" מפקפק אם אבימי ואביי בר אבהו אחד הם."},{"i":285,"n":"אבימי דמן חבריא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מובא בב\"ר (פי\"ג - ט\"ז). רבי חייא בר אבא דיבר עמו (שם)."},{"i":286,"n":"אבימי מבי חוזאי","l":"א","b":"אמורא בבלי שאין לקבוע זמנו המדוייק. מובא בבבלי (נדה ה\u0027 ע\"ב)."},{"i":287,"n":"אבימי מהגרוניא","l":"א","b":"אמורא בבלי בדור החמישי. נראה, שהיה תלמיד של רבא, שכן מובא כמה פעמים: \"אמר ליה רב מרדכי לרב אשי: הכי אמר אבימי מהגרוניא, משמיה דרבא\" (כתובות ק\"ט ע\"ב: ב\"מ ע\"ז ע\"ב: שם צ\"ז ע\"א: ב\"ב קע\"ד ע\"ב: מכות י\"ג ע\"ב). פעם אחת מסר משם רב הונא (יבמות ס\"ד ע\"ב)."},{"i":288,"n":"אבימי נותאה","l":"א","b":"אמורא בבלי בדור השני. מסר בשם רב (ע\"ז ל\"ו ע\"ב). רבו של האמורא באלי (שם). במסכת שבת (י\"ז ע\"ב) הגירסא:\" אבימי סנוותאה\" (ע\"ע)."},{"i":289,"n":"אבימי סנוותאה","l":"א","b":"מובא בבבלי (שבת י\"ז ע\"ב). במסכת ע\"ז (ל\"ו ע\"ב). הגירסא:\" אבימי נותאה\" (ע\"ע), וכן גירסת \"דק\"ס\"."},{"i":290,"n":"אבין","l":"א","b":"ע\"ע רבין."},{"i":291,"n":"ר\u0027 אבין אביו דר\u0027 אבין הלוי","l":"א","b":"מובא בתנחומא (בובר, תזריע)."},{"i":292,"n":"רבי אבין איש נחום","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מובא בילקוט שמעוני (בא רמז קצ\"א). רבי ברכיה מסר בשמו (שם)."},{"i":293,"n":"אבין בר בנימין","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בויק\"ר (פ\"י - ה\u0027). מסר בשם ר\u0027 אבא (שם). ע\"ע רבי אחא בר אבין בר בנימין."},{"i":294,"n":"אבין בר הונא","l":"א","b":"אמורא בבלי בדור השלישי. מובא בבבלי (שבת ס\"ו ע\"ב) תלמיד תלמידו של רב, ותלמידו של רב חמא בר גוריא (שם)."},{"i":295,"n":"ר\u0027 אבין בר זוטרתי","l":"א","b":"מובא בבבלי (ברכות י\"ב ע\"ב), וכן גירסת \"יוחסין\". ולפנינו: \"ר\u0027 אבהו בר זוטרתי\"."},{"i":296,"n":"ר\u0027 אבין בר חייא (2)","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. למד לפני ר\u0027 יוחנן (קידושין מ\"ד ע\"א), לפני ריש לקיש (ירו\u0027, תרומות פ\"ו סה\"א), ולפני ר\u0027 זירא (ירו\u0027, מעשרות רפ\"ב). נפטר בגיל 82 ור\"ז הספידו ואמר עליו שיגע יותר מאשר תלמיד ותיק במאה שנה (ירו\u0027, ברכות פ\"ב ה\"ח)."},{"i":297,"n":"ר\u0027 אבין בר חנין","l":"א","b":"מובא במדרש שמואל (פי\"ז). המאמר מובא גם בפדר\"כ (מה) ושם: \"ר\u0027 אבין בשם ר\u0027 חנין\", ואולי במקום בר צ\"ל: בשם רבי."},{"i":298,"n":"ר\u0027 אבין בר כהן","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי (מע\"ש פ\"ד ה\"ו). תלמידו של רבי אסי (שם)."},{"i":299,"n":"ר\u0027 אבין בר כהנא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. קיבל מרבי אלעאי (ירו\u0027, פסחים פ\"ג ה\"ח). שאל מר\u0027 אמי (ירו\u0027, ב\"ק רפ\"ה). ר\u0027 יוסי קיבל ממנו (ירו\u0027, עירובין פ\"ז ה\"א). בימי ר\u0027 מנא, כבר היה זקן מאד (ירו\u0027, מו\"ק ספ\"א)."},{"i":300,"n":"ר\u0027 אבין בר רב אדא","l":"א","b":"מובא בבבלי (פסחים ח\u0027 ע\"ב), הוא רבין בר רב אדא."},{"i":301,"n":"ר\u0027 אבין בר רב אחא","l":"א","b":"מובא בבבלי (פסחים ל\"ד ע\"א). \"דק\"ס\" גורס: \"ר\u0027 אבין בר רב אדא\"."},{"i":302,"n":"ר\u0027 אבין בר ר\u0027 אלעזר","l":"א","b":"מובא בירושלמי (סנהדרין פ\"ב ה\"ד). יש גורסים: ר\u0027 אבין בשם ר\u0027 אלעזר."},{"i":303,"n":"רבי אבין בר שבא","l":"א","b":"מובא בבבלי (חולין פ\"ו ע\"א): \"והאמר רבין בר אבא, ואמרי לה אמר רבי אבין בר שבא\"."},{"i":304,"n":"ר\u0027 אבין בריה דר\u0027 תנחום בר טרפון","l":"א","b":"מובא בירושלמי (בכורות רפ\"ב)."},{"i":305,"n":"אבין דמן נשיקיא","l":"א","b":"אמורא בבלי בדור השני. מובא בבבלי (שבת קכ\"א ע\"א). שם מוזכר שביקרו אצלו רב יהודה, רב ירמיה בר אבא ורב חנן בר רבא. אבין לימד את בנו (שם)."},{"i":306,"n":"ר\u0027 אבין הלוי","l":"א","b":"מובא בבבלי (סוף ברכות): \"א\"ר אבין הלוי: \u0027כל הדוחק את השעה, שעה דוחקתו, וכל הנדחה מפני השעה, שעה נדחת מפניו\u0027\"."},{"i":307,"n":"ר\u0027 אבין הלוי בר חמא","l":"א","b":"מובא בתנחומא (וישב - ט\"ו). יש אומרים שצ\"ל: ר\u0027 אבין הלוי בר חייא. ושני יודין היו ל\"מם\"."},{"i":308,"n":"ר\u0027 אבין זוטרתי","l":"א","b":"מובא בבבלי (ברכות י\"ב ע\"ב). כן גירסת ה\"יוחסין\". ולפנינו: \"ר\u0027 אבהו בר זוטרי\"."},{"i":309,"n":"רב אבין נגרא","l":"א","b":"חי בבבל בדור השני. מלאכתו היתה חרש עצים (שבת כ\"ג ע\"ב). רב הונא רגיל היה לעבור ליד ביתו, ובראותו שהדליק נרות רבים לכבוד שבת, בירכו ששני חכמים יוולדו לו, ואכן נולדו לו רב אידי ורב חייא (שם)."},{"i":310,"n":"אבין צפיראה","l":"א","b":"אמורא ארץ ישראלי בדור החמישי - הששי. מובא בבבלי (שבת כ\"ט ע\"ב). ישב לפני רבי יצחק בן אלעזר (שם)."},{"i":311,"n":"אבין רמאה","l":"א","b":"חי בארץ ישראל בימי ריש לקיש. מובא בבמד\"ר (פ\"ד - ד\u0027). היה בעל צדקה גדול. ר\"ל כיבדו מאד עבור מעשיו (שם). אין להכריע שהיה מן החכמים."},{"i":312,"n":"אבין תורן","l":"א","b":"אמורא בבלי בדור הראשון. מובא בבבלי (שבת קכ\"ב ע\"ב). שמו היה אבין והיה ממקום ששמו תורן (שם ברש\"י)."},{"i":313,"n":"אבין תכלא","l":"א","b":"מובא בבבלי (פסחים ע\u0027 ע\"ב), והוא רבין. ופרש\"י: קובר את בניו היה (לכן כינוהו כך)."},{"i":314,"n":"ר\u0027 אבינא","l":"א","b":"אמורא בבלי בדור השלישי. תלמידו של רב הונא (גיטין ס\"ו ע\"א). כן קיבל מר\u0027 ירמיה בר אבא (שבת קל\"ז ע\"ב), מרב חסדא (פסחים נ\"ט ע\"א) ומגניבא (חולין נ\u0027 ע\"ב). וגניבא הוריש לו ד\u0027 מאות זוז, לפני שהוצא להורג ע\"י המלכות (גיטין ס\"ה ע\"ב). עלה לא\"י וישב לפני ר\u0027 אמי (ירו\u0027, שביעית פ\"ד ה\"ב). בשמו מסרו: ר\u0027 יונה ור\u0027 יוסי (ירו\u0027, שביעית פ\"ב ה\"ג)."},{"i":315,"n":"אבירודימוס","l":"א","b":"תנא והוא הוא רבי מנחם בר יוסי בר חלפתא ומובא (ירו\u0027, שביעית פ\"ח ה\"ה)."},{"i":316,"n":"רבי אביתר","l":"א","b":"אמורא ארץ ישראלי בדור השני - השלישי. מובא בבבלי (גיטין ו\u0027 ע\"ב). עמד בקשר עם רב יהודה ורב חסדא (שם). זכה לגילוי אליהו (שם)."},{"i":317,"n":"רבי אבמכיס","l":"א","b":"אמורא ארץ ישראלי בדור השני - השלישי. מובא בירושלמי (סנהדרין ספ\"ג) שבא לפני ר\u0027 אלעזר."},{"i":318,"n":"אבמרי","l":"א","b":"מובא בירושלמי (תענית פ\"א ה\"ו). זהה לאבא מרי (ע\"ע)."},{"i":319,"n":"ר\u0027 אבמרי אחוי דרבי יוסי","l":"א","b":"מובא בירושלמי (שבת פ\"ג ה\"ו). ע\"ע ר\u0027 אבא מרי אחוי דר\u0027 יוסי."},{"i":320,"n":"אבסקטא","l":"א","b":"מובא בירושלמי (ברכות פ\"ט ה\"א). \"פני משה\", (שם), מפרש מלשון \"נשיאות חן וכבוד\" והירושלמי (ע\"ז פ\"א ה\"ט) גרס: אבסקנטה (ע\"ע)."},{"i":321,"n":"אבסקנטה","l":"א","b":"מובא בירושלמי (ע\"ז פ\"א ה\"ט). \"פני משה\", (שם), מפרש מלשון \"נשיאות חן וכבוד\" (ואין זה כלל שם אדם), ו\"סה\"ד\" מפרש: \"שם חכם\". והירושלמי (ברכות פ\"ט ה\"א) גרס: אבסקטא (ע\"ע)."},{"i":322,"n":"אברם חוזאה","l":"א","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (גיטין נ\u0027 ע\"א)."},{"i":323,"n":"רבי אבשלום הזקן","l":"א","b":"תנא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא במכילתא (בשלח פ\"ג). ע\"ע רבי אבטולוס הזקן."},{"i":324,"n":"אגרא","l":"א","b":"אמורא ארץ ישראלי בדור השני. חותנו של ר\u0027 אבא (מנחות כ\"ט ע\"ב), ושאל מר\u0027 אבא חתנו (שם). מצינו ששנה ברייתא (חולין ק\"ד ע\"ב)."},{"i":325,"n":"רב אדא","l":"א","b":"אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של ר\u0027 שמלאי (סוטה ל\"ח ע\"ב), ושל רב (יבמות פ\"ג ע\"ב). בבבלי סוטה (שם) ובירושלמי (תרומות פ\"י ה\"ו) מובא בלי ר\u0027. אבל בבבלי יבמות (שם) מובא: רב אדא."},{"i":326,"n":"ר\u0027 אדא","l":"א","b":"פעמים מוחלף בר\u0027 אחא או בר\u0027 אבא."},{"i":327,"n":"רב אדא א\u0027","l":"א","b":"אמורא בבלי בדור החמישי. מובא בבבלי (מנחות מ\"ג ע\"א). תלמידו של רב יוסף (נדה כ\"ה ע\"ב) ושל רבא (מנחות שם)."},{"i":328,"n":"רבי אדא בי ר\u0027 שמעון","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם רבי יוחנן (ירו\u0027, מגילה פ\"א ה\"ט). אותו מאמר (ירו\u0027, ברכות פ\"ב ה\"ג) בשם ר\u0027 אידי בר שמעון בשם ר\u0027 יוחנן\u0027."},{"i":329,"n":"ר\u0027 אדא בר אבא","l":"א","b":"מובא בבבלי (ב\"ב כ\"ב ע\"א). וצ\"ל: ר\u0027 אדא בר אהבה (ב\u0027)."},{"i":330,"n":"ר\u0027 אדא בר אבוה","l":"א","b":"אמורא שאין לנו פרטים עליו ומובא פעם בש\"ס הירושלמי (ב\"ב פ\"ג ה\"ח)."},{"i":331,"n":"רב אדא בר אבימי","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי: תלמידו של ר\u0027 זירא (ירו\u0027, ברכות פ\"ט ה\"ב)."},{"i":332,"n":"רב אדא בר אבין","l":"א","b":"מובא בבבלי (כריתות כ\"א ע\"א). אך הגירסא במקום אחר (יומא ע\"ד ע\"ב): רב אידי בר אבין."},{"i":333,"n":"רב אדא בר אהבה","l":"א","b":"אמורא בבלי בדור הראשון - השני. תלמידו המובהק של רב (ברכות מ\"ב ע\"ב). חברו של רב הונא (ברכות ה\u0027 ע\"ב). נולד ביום שמת רבי (קידושין ע\"ב ע\"ב). זכה לאריכות ימים (תענית כ\u0027 ע\"ב). לפי שיטת רש\"י חי עד תקופת ר\u0027 נחמן בר יצחק (קידושין ע\"ב ע\"ב), ותוס\u0027 חולקים וסוברים ששני ר\u0027 אדא בר אהבה היו (שם). מקום מושבו היה בפומבדיתא (יבמות ק\"י ע\"ב), שם הרביץ תורה, יחד עם חתנו רב חנא (שם). היה מופלג בצניעות (ברכות כ\u0027 ע\"א) ובחסידות (תענית כ\u0027 ע\"ב) ומלומד בנסים (שם בירו\u0027 תענית ספ\"ג)."},{"i":334,"n":"ר\u0027 אדא בר אהבה (2)","l":"א","b":"אמורא בדור הששי. תלמידו של רב פפא (חולין קל\"ג ע\"ב). חי בדורו של רב אשי. והוא שאמר: \"מימות רבי עד רב אשי לא מצינו תורה וגדולה במקום אחד\" (סנהדרין ל\"ו ע\"א). [והוא אינו ר\u0027 אדא בר אהבה הקודם, שכן הוא נפטר בחיי רבא (ב\"ב כ\"ב ע\"א) ורבא נפטר ביום שנולד רב אשי (קידושין ע\"ב ע\"ב)]. ולפי הגירסאות שצ\"ל רב אחא בריה דרבא במקום רב אדא בר אהבה, לא היו אלא שני רב אדא בר אהבה, ע\"ע רש\"י ותוספות (קידושין ע\"ב ע\"ב)."},{"i":335,"n":"אדא בר אוכמי","l":"א","b":"אמורא בבלי בדור השלישי, בזמנו של רב נחמן (ביצה כ\"ו ע\"ב) ופרש\"י: \"חכם א\u0027 שהיו מכירין בו שהיה גורס משניות ומשכח ומשבשן\". אין זה ר\u0027 אבא בר איכומה (ירו\u0027, תענית פ\"א ה\"ג), שם ט\"ס וצ\"ל ר\u0027 אדא בר אבימי."},{"i":336,"n":"רב אדא בר אחא","l":"א","b":"מוזכר בירושלמי (ברכות פ\"א ה\"ב), והוא ר\u0027 אדא בר אהבה (ע\"ע)."},{"i":337,"n":"ר\u0027 אדא בר אחא","l":"א","b":"אמורא בבלי בדור הרביעי. מוזכר בבבלי (זבחים כ\"ב ע\"א). נראה, שחי בתקופת אביי (שם)."},{"i":338,"n":"רב אדא בר אחוה דר\u0027 יהודה","l":"א","b":"אמורא ארץ ישראלי בדור השני. רב זעירא מסר בשמו (ירו\u0027, בכורים פ\"א ה\"ה)."},{"i":339,"n":"רב אדא בר איכומה","l":"א","b":"מוזכר בירושלמי (תענית פ\"א ה\"ג). וצ\"ל רב אדא בר אבימי (ע\"ע)."},{"i":340,"n":"אדא בר בר חנא","l":"א","b":"מוזכר בירושלמי (יבמות ט\"ו ה\"ו). צ\"ל אבא בר בר חנא. והוא הוא רבה בר בר חנא (ע\"ע)."},{"i":341,"n":"אדא בר גרשון","l":"א","b":"אמורא שמובא בירושלמי (תרומות פ\"י ה\"ו) פעם אחת בלבד ואין לנו פרטים עליו."},{"i":342,"n":"אדא בר זבדא","l":"א","b":"הוא ר\u0027 אבא בר זבדא מובא (ירו\u0027, כתובות פי\"ג ה\"ג)."},{"i":343,"n":"אדא בר חבו","l":"א","b":"אמורא בבלי בדור הששי - השביעי. שאל את רב אשי ונשא ונתן עמו בהלכה (חולין ע\"ה ע\"ב)."},{"i":344,"n":"רב אדא בר חמא","l":"א","b":"אמורא בבלי בדור הרביעי. תלמידו של רב ששת (ב\"מ ל\u0027 ע\"א)."},{"i":345,"n":"רב אדא בר מניומי","l":"א","b":"אמורא בבלי בדור השביעי. תלמידו של רבינא (ב\"ק ל\"א ע\"ב). היה ראש הדיינים בנהרדעא (סנהדרין י\"ז ע\"ב). במחלוקת שהיתה לו עם חברו הונא מר בריה דרב אידי, פסק רבינא כרב אדא (חולין מ\"ט ע\"א)."},{"i":346,"n":"רב אדא בר מתנא","l":"א","b":"אמורא בבלי בדור החמישי - הששי. תלמידו של רבא (ברכות ס\"ב ע\"ב), לפניו ישב עם רב פפא חברו (כתובות פ\"ה ע\"א), ותלמידו של אביי (שבת מ\"ח ע\"א), ואמר לאביי \"לאפוקי ממר\" (כתובות ע\"ז ע\"ב). ונראה שגם היה אח\"כ תלמידו של רבינא (זבחים ק\u0027 ע\"ב - רש\"י). היה עני גדול (עירובין כ\"ב ע\"א)."},{"i":347,"n":"רב אדא בר מתנה","l":"א","b":"אמורא בבלי בדור השלישי. תלמידו של רב (שבת ק\"ט ע\"א). ישב גם לפני רב יוסף, וכשרב יוסף חלה ושכח תלמודו, היה הוא מזכירו באמרו לו: \"בפירוש אמרת לן וכו\u0027\" (פסחים י\"ג ע\"א). היה חברם של רב נחמן ורב ששת וקטן מהם כדמצינו: \"יתיב רב נחמן ורב ששת ויתיב רב אדא בר מתנה גבייהו\" (זבחים ה\u0027 ע\"ב)."},{"i":348,"n":"רב אדא בר נתן","l":"א","b":"מוזכר בבבלי (חולין מ\"ט ע\"א). ע\"ע רב אחא בר נתן."},{"i":349,"n":"רב אדא בר עזא","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי אסי (קידושין פ\"א ע\"ב)."},{"i":350,"n":"רבי אדא בר פפא","l":"א","b":"מובא בבבלי (ב\"ק פ\u0027 ע\"ב)."},{"i":351,"n":"רב אדא בר שימי","l":"א","b":"אמורא בבלי בדור החמישי - הששי. הקשה למר בר רב אידאי על דברי רב ביבי בר אביי (חולין ס\"ג ע\"א). ע\"ע רב אידי בר שימי."},{"i":352,"n":"רבי אדא בר תחליפא","l":"א","b":"אמורא ארץ ישראלי בדור השני. מסר בשם רבי אושעיא (ירו\u0027, גיטין פ\"ו ה\"א). ר\u0027 חייא בר אבין היה תלמידו (שם)."},{"i":353,"n":"רב אדא ברבי חנינא","l":"א","b":"אמורא. אולי ארץ ישראלי. מאמרו: \"אילמלא לא חטאו ישראל לא ניתן להם אלא חמש חומשי תורה וספר יהושע בלבד\" (נדרים כ\"ב ע\"ב). \"ולפי שבעטו וחטאו, נוסף להם רוב חכמה, שאר הספרים, להטריחן יותר\"."},{"i":354,"n":"רב אדא בריה דרב אויא","l":"א","b":"מוזכר בבבלי (ב\"ק ס\"ב ע\"א). גירסת הרי\"ף:\" רב אחא בריה דרב אויא\" (ע\"ע)."},{"i":355,"n":"רב אדא בריה דרב איקא","l":"א","b":"מוזכר בבבלי (גיטין פ\"ד ע\"ב). אולי זהה לר\u0027 אידי בריה דרב איקא. מצינו שרבינא מתקיף על דבריו (שם)."},{"i":356,"n":"רב אדא בריה דרב יצחק","l":"א","b":"אמורא בבלי בדור הרביעי בתקופת רבא (זבחים קי\"א ע\"א). רב פפא מתקיף על דבריו, ואביי מוסיף עליהם (גיטין כ\"ח ע\"א)."},{"i":357,"n":"רב אדא בריה דרבא","l":"א","b":"מובא בבבלי (חולין נ\"ז ע\"ב). כן הגירסא שם לפי ה\"יוחסין\" ו\"סה\"ד\". לפנינו: ר\u0027 אחא בריה דרבא."},{"i":358,"n":"רבי אדא דחוטרא","l":"א","b":"מובא בירושלמי (שקלים פ\"ב ה\"ה). כן גירסת \"יוחסין\" ו\"סה\"ד\". ולפנינו: רבי אידי דחוטרא."},{"i":359,"n":"אדא דיילא","l":"א","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב יהודה (ב\"ק קי\"ט ע\"א). היה ארוך בדורו והגיע לכתפיו של רב יהודה (נדה כ\"ד ע\"ב)."},{"i":360,"n":"רבי אדא דמן יפו","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מאמרו בבבלי (מגילה ט\"ז ע\"ב) מובא בירושלמי (מגילה פ\"ג ה\"ז) בשם בנו, ר\u0027 חייא בריה דר\u0027 אדא דמן יפו: \"עשרת בני המן צריך לממרינהו בנשימה אחת\"."},{"i":361,"n":"ר\u0027 אדא דמן קיסרי","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של ר\u0027 יוחנן (מו\"ק כ\u0027 ע\"ב)."},{"i":362,"n":"רב אדא מבי כלוחית","l":"א","b":"אמורא בבלי בדור הרביעי. בן תקופת אביי ורבא. חברו של רב שלמן מבי כלוחית (ביצה ה\u0027 ע\"ב)."},{"i":363,"n":"רב אדא מסורא","l":"א","b":"מובא בבבלי (נדה ס\"ז ע\"ב). כן גירסת ה\"יוחסין\", \"סה\"ד\" והב\"ח. ולפנינו: רב אדא."},{"i":364,"n":"אדא מרי","l":"א","b":"אמורא בבלי מובא (שבת ס\"ו ע\"ב): \"אמר אדא מרי [פרש\"י: כך שמו] אמר רב נחמן בר ברוך אמר רב אשי בר אבין אמר רב יהודה\". ומובא (זבחים ל\"ח ע\"א) לגירסת \"דק\"ס\": \"אמר רבא רב אדא מרי אסברא לי\". ולפנינו (שם) בר אבא מרי."},{"i":365,"n":"רב אדא משוחאה","l":"א","b":"אמורא בבלי בדור השלישי. תלמידו של רב יהודה (ב\"מ ק\"ז ע\"ב). נראה, שהוא בר אדא שמזכיר רבא \"בר אדא משוחאה אסברא לי\" (עירובין נ\"ו ע\"ב), ופרש\"י: \"משוחאה מציין תחומי העיר\" ועל שם מלאכתו שהיה מודד קרקעות מכונה משוחאה."},{"i":366,"n":"רב אדא נרשאה","l":"א","b":"אמורא בבלי בדור הרביעי. תלמידו של רב יוסף. חברו של אביי (שבת ס\u0027 ע\"א)."},{"i":367,"n":"רב אדא סבא","l":"א","b":"ע\"ע רב אחא סבא."},{"i":368,"n":"אדא ציידא","l":"א","b":"מובא בבבלי (מו\"ק י\"א ע\"א). חי בבבל, בדור הראשון לאמוראים. ספק אם היה חכם. לימד לרב את תכונות הדגים (שם)."},{"i":369,"n":"רב אדא קרחינאה","l":"א","b":"אמורא בבלי בדור החמישי. תלמידו של רב כהנא. אמר קמיה משמיה דרבא (יבמות י\u0027 ע\"א)."},{"i":370,"n":"אדא שמשא","l":"א","b":"מובא בירושלמי (שבת פ\"ב ה\"א). חי בארץ ישראל, בדור השלישי. שאל לר\u0027 אמי (שם). היה משמש חולים (שם). ספק אם היה חכם."},{"i":371,"n":"ר\u0027 אדאי","l":"א","b":"מובא בירושלמי (ברכות פ\"ב ה\"א), ונראה שהוא ר\u0027 אדא."},{"i":372,"n":"רב אדומה נחותה","l":"א","b":"הוא רב דימי."},{"i":373,"n":"ר\u0027 אדימי בר המדורא","l":"א","b":"אמורא בדור השני. ר\u0027 אבא מפרש דבריו (סוכה כ\u0027 ע\"א)."},{"i":374,"n":"אדמון","l":"א","b":"אחד מ\"דייני גזירות\" שהיו בירושלים (כתובות ק\"ה ע\"א), לפני חורבן הבית (יוחסין כתב שהיה בזמנו של אבטליון). שם אביו גדאי (שם). על דבריו אמר רבן גמליאל: \"רואה אני את דברי אדמון\" (שם)."},{"i":375,"n":"ר\u0027 אהבה בר זעירא","l":"א","b":"מובא בב\"ר (פפ\"ד - ט\u0027). בילקוט שמואל הגיר\u0027 ר\u0027 אחא [אחא זהה לאהבה]. אולי הוא ר\u0027 אבא בר זעירא."},{"i":376,"n":"רב אהבה בר כהנא","l":"א","b":"מובא בויק\"ר (פי\"א - א\u0027). נראה, שהוא ר\u0027 אבא בר כהנא."},{"i":377,"n":"אהבה בריה דרבי זירא","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. בנו ותלמידו של רבי זירא. שימש \"תנא\" אצל אביו (עירובין צ\"ו ע\"ב). ישב בקיסרין ושם שמע ממנו ר\u0027 מנא, בנו של ר\u0027 יונא (ירו\u0027, פסחים פ\"ב ה\"ד). שמו נשתבש בכמה אופנים."},{"i":378,"n":"רב אהילאי","l":"א","b":"אמורא בבלי בדור השני. בנו נשא לאשה את בת רב יצחק בר שמואל בר מרתא (ברכות כ\"ה ע\"ב) - לגירסת ה\"יוחסין\" ו\"דק\"ס\". לפנינו שם: רב אחאי. ע\"ע רב אחאי. וע\"ע רב אחלי."},{"i":379,"n":"רב אהרון","l":"א","b":"אמורא בבלי בדור הששי. חברו של רבינא, עמו נשא ונתן בהלכה. (ב\"ק ק\"ט ע\"ב)."},{"i":380,"n":"רב אויא","l":"א","b":"אמורא בבלי בדור הרביעי. תלמידו של רב יוסף (ברכות כ\"ח ע\"ב) חברו של אביי (שם) ושל רבא (שבת מ\"ו ע\"א). היה גם בארץ ישראל ולמד לפני רבי אמי (חולין נ\u0027 ע\"א)."},{"i":381,"n":"רב אויא סבא א\u0027","l":"א","b":"אמורא בבלי בדור השני. תלמידו של רב הונא (ביצה כ\"א ע\"א)."},{"i":382,"n":"רב אויא סבא ב\u0027","l":"א","b":"אמורא בבלי בדור החמישי. חברו של רב פפא (מו\"ק כ\"ד ע\"ב)."},{"i":383,"n":"אוירא סבא","l":"א","b":"ע\"ע רב עוירא סבא."},{"i":384,"n":"רב אוירא סבא","l":"א","b":"מובא בבבלי (פסחים נ\"א ע\"א). ב\"סה\"ד\": \"אולי צ\"ל אויא\" (סבא)."},{"i":385,"n":"אולפנא","l":"א","b":"מובא בבבלי (עירובין ס\"ז ע\"א), ופירש\"י: \"ששמע מרבו ורבו מרבו\". \"יוחסין\" כתב: \"והיה נראה שהוא שם חכם או ר\"ל כמ\"ש במקומות אחרים משמיה דגמרא\"."},{"i":386,"n":"און בר אמי","l":"א","b":"מובא בירושלמי (שבת פ\"ו ה\"ה). כן גירסת ה\"יוחסין\" ו\"סה\"ד\". ולפנינו: אנן בר אימא, ולפני \"אור זרוע\" (ח\"ב ספ\"ד):\" חנן בר אימי\" (ע\"ע)."},{"i":387,"n":"ר\u0027 אוניא","l":"א","b":"מובא בשה\"ר (פ\"ב - ז\u0027)."},{"i":388,"n":"אונקלוס","l":"א","b":"יש מטילים ספק אם אונקלוס ועקילס הם אותו אדם. תנא בדור השלישי. גר צדק. בן אחותו של אדריאנוס (תנחומא משפטים ג\u0027). בבבלי (גיטין נ\"ו ע\"ב) מובא שהיה בן אחותו של טיטוס הרשע (וגיר\u0027 הגר\"א: בן אחותו של אדריאנוס). רבותיו היו רבי אליעזר ורבי יהושע: \"תרגום של תורה אונקלוס הגר אמרו מפי ר\"א ור\u0027 יהושע\" (מגילה ג\u0027 ע\"א). וכן היה תלמידו של רבי עקיבא: \"תירגם עקילס הגר לפני ר\"ע\" (ירו\u0027, קידושין פ\"א ה\"א). חברו של רבן גמליאל (תוספתא מקואות פ\"ו). בתרגומו יש שאונקלוס מוסיף מלים על הפסוק. פרש\"י (קידושין מ\"ט ע\"א): \"ואונקלוס כשהוסיף לא מדעתו הוסיף שהרי בסיני ניתן אלא שנשתכח וחזר ויסדו\"."},{"i":389,"n":"אונקלוס בר קלונימוס","l":"א","b":"ע\"ע אונקלוס."},{"i":390,"n":"ר\u0027 אורי","l":"א","b":"אמורא בבלי בדור הרביעי. תלמידו דרב יוסף (ירו\u0027 ברכות רפ\"ב)."},{"i":391,"n":"רב אושעיא","l":"א","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו המובהק של רב יהודה (ב\"מ מ\"ג ע\"ב) וכן תלמידו של ר\"ה (ברכות ל\"ז ע\"ב). כשעלה לארץ ישראל היה תלמידו של ר\u0027 יוחנן, שרצה לסמוך אותו ולא עלתה בידו (סנהדרין י\"ד ע\"א). היה אחיו של רבה (מהרש\"א בסנהדרין שם). היה תדיר יחד עם אחיו השני רב חנינא (מכות י\"ט ע\"ב). ושניהם עסקו בספר היצירה (סנהדרין ס\"ה ע\"ב)."},{"i":392,"n":"רבי אושעיא","l":"א","b":"מגדולי אמוראי ארץ ישראל בדור הראשון. זכה לכינוי \"אבי המשנה\" (ירו\u0027, ב\"ק פ\"ד ה\"ו). תלמידם של בר קפרא (מו\"ק כ\"ד ע\"ב) ור\u0027 חייא (ירו\u0027, שבת פ\"ג ה\"א). הברייתות שהוא ורבו ר\u0027 חייא כתבו, היו מקובלות בבית המדרש כמהימנות ומדוייקות (חולין קמ\"א ע\"א). ישיבתו היתה בקיסרין (ירו\u0027, תרומות פ\"י ה\"ב). היה רבו של ר\u0027 יוחנן (עירובין נ\"ג ע\"א). אביו ר\u0027 חמא ואבי אביו ר\u0027 ביסא, היו חכמים גדולים, ועליהם אמרו: \"והחוט המשולש לא במהרה ינתק\" (ב\"ב נ\"ט ע\"א). שם בתוס\u0027 נראה שהיה גדול מאביו. עליו אמרו כדוגמת רבי מאיר \"לא יכלו חבריו לעמוד על סוף דעתו\" (עירובין שם)."},{"i":393,"n":"רבי אושעיא בנו של רבי יהודה הבשם","l":"א","b":"תנא בדור השלישי - הרביעי. תלמידו של ר\"ע. והעיד לפניו משמו של רבי טרפון (חולין נ\"ה ע\"ב). בתוספתא (חולין פ\"ג ה\"ז וכן בשביעית פ\"ה הי\"ב) הגירסא: ר\u0027 יהודה בן ישעיה הבשם, (ע\"ע)."},{"i":394,"n":"רבי אושעיא בנו של ר\u0027 חמא בר ביסא","l":"א","b":"מובא בבבלי (ב\"ב נ\"ט ע\"א). והוא רבי אושעיא סתם."},{"i":395,"n":"רבי אושעיא בר אבא","l":"א","b":"מובא בירושלמי (גיטין פ\"ד ה\"ב), ואולי צ\"ל: רבי אושעיא רבה."},{"i":396,"n":"אושעיא בר זבדא","l":"א","b":"אמורא שאין לקבוע זמנו ומקומו. התקיף על דברי רבי יהושע בן לוי, ור\u0027 יצחק תירץ קושייתו (תענית כ\"ו ע\"ב)."},{"i":397,"n":"ר\u0027 אושעיא בר חייא","l":"א","b":"אמורא ארץ ישראלי בדור הראשון. חברם של רבי חייא ורבי אושעיא (יבמות מ\"ו ע\"ב)."},{"i":398,"n":"רבי אושעיא בר שימי","l":"א","b":"אמורא ארץ ישראלי בדור הששי. מושבו היה בקיסרין (ירו\u0027, כלאים פ\"ו ה\"ג). בנו של ר\u0027 שמאי, שהיה מאמוראי א\"י בדור הרביעי. היה תלמידו של ר\u0027 יצחק בר אלעזר, וקרא לו ולחברו ר\u0027 בורקי: עדה קדושה (קה\"ר פ\"ט - ט\u0027). ר\u0027 מנא עמד עמו בקשרי מכתבים (ירו\u0027, מגילה פ\"ג ה\"ב)."},{"i":399,"n":"רבי אושעיא בריבי","l":"א","b":"מובא בבבלי (עירובין נ\"ג ע\"א), והוא רבי אושעיא. ופרש\"י ד\"ה אושעיא בריבי: \"אדם גדול בדורו, וכל היכי דקרי בריבי הכי פירושו\"."},{"i":400,"n":"אושעיא זעירא דמן חבריא","l":"א","b":"אמורא בבלי שאין לקבוע זמנו המדוייק. עוד בהיותו צעיר שבישיבה, היה מופלג בחסידות וכל מעשיו היו לשם שמים (תענית כ\"ד ע\"א). מצינו ששמו מובא (נדה כ\"ו ע\"א): ושם ר\u0027 אושעיא וכו\u0027."},{"i":401,"n":"רבי אושעיא תורגמא","l":"א","b":"אמורא ארץ ישראלי בדור השני. רבי תנחומא בר חייא (שמסר בשם רבי יהושע בן לוי), מסר בשמו (ב\"ר פנ\"א - ט\u0027)."},{"i":402,"n":"רב אושעיה","l":"א","b":"אמורא בבלי בדור החמישי. תלמידו של רבא \"תני ר\u0027 אושעיא קמיה דרבא\" (ברכות ט\"ו ע\"ב). וגירסת \"דק\"ס\": \"תני רבי יאשיה קמיה דרבא\"."},{"i":403,"n":"אחא","l":"א","b":"מובא בבבלי (שבת נ\"ו ע\"ב). חי בדור הראשון לאמוראי בבל. היה אחי אביו של רבי ירמיה בר אבא (שם). היה בעל תשובה גדול (שם)."},{"i":404,"n":"רב אחא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. היה דיין בעירו (ירו\u0027, ב\"ב פ\"ח ה\"א). מובא רבות בירושלמי. תלמידם של ר\u0027 יוסי בר חנינא (ירו\u0027, יבמות פ\"א ה\"ב) ור\u0027 אבא (ירו\u0027, שבת רפ\"ו). היה חברו ובן עירו של ר\u0027 יהודה בן פזי (ירו\u0027, סנהדרין פ\"א ה\"ב). גדולי דור הרביעי קבלו ממנו, וביניהם ר\u0027 יונה ור\u0027 יוסי (ירו\u0027, ברכות פ\"ב ה\"ד). כשנפטר חשכו השמים ונראו כוכבים בעצם היום (ירו\u0027, ע\"ז פ\"ג ה\"א)."},{"i":405,"n":"רבי אחא","l":"א","b":"תנא בדור הרביעי - החמישי. מסר משום ר\"ע (תוספתא שבת ספט\"ז). מצינו אותו חולק על תלמידי ר\"ע: רבי שמעון (שבת קכ\"ז ע\"א) ורבי אלעזר (שבת ל\"ב ע\"א) ור\"א בן יעקב (גיטין ל\"ב ע\"א - שם הגירסא ר\u0027 אחי). בשמו מסר רבי שמעון בן חלפתא (פסיקתא רבתי פסקא דביום השמיני)."},{"i":406,"n":"ר\u0027 אחא","l":"א","b":"ע\"ע ר\u0027 אדא או ר\u0027 אחי או ר\u0027 אחאי."},{"i":407,"n":"רב אחא אחוה דמר אחאי","l":"א","b":"מובא בבבלי (שבת קי\"א ע\"ב). כן גירסת הדפוסים הישנים. וכך היתה הגירסא לפני ה\"יוחסין\" ו\"סה\"ד\". אך לפנינו הגירסא: רב אחדבוי אחוי דמר אחא."},{"i":408,"n":"רב אחא אריכא","l":"א","b":"אמורא בבלי בדור השלישי. והוא רב אחא בר פפא המכונה רב אחא אריכא (שבת קי\"א ע\"א). תלמיד של רב הונא (מנחות ל\"ה ע\"ב). כשעלה לארץ ישראל, שאל מרבי אבהו (שבת שם), מרבי אבא (שבת קי\"ג ע\"א) ומרבי זעירא (ירו\u0027, מע\"ש פ\"ה ה\"ה). מצינו שהתיר נדר לרבי אמי (ירו\u0027, נדרים פ\"י ה\"ח)."},{"i":409,"n":"רב אחא בר אבא","l":"א","b":"שמו מובא בבבלי מספר פעמים (שבת קי\"ג ע\"ב: קידושין פ\"א ע\"ב: ע\"ז י\"ט ע\"ב ועוד), אך נראה שיש טעות בשם, ולפי גירסאות הרא\"ש, האשר\"י, \"דק\"ס\", ו\"מסורת הש\"ס\" לא היה מעולם אמורא בשם זה."},{"i":410,"n":"ר\u0027 אחא בר אבא בר אחא","l":"א","b":"מובא בבבלי (ברכות כ\"ה ע\"ב): \"ר\u0027 אחא בר אבא בר אחא בשם רבינו\" י\"א שצ\"ל: ר\u0027 אבא בר אחא."},{"i":411,"n":"רב אחא בר אביי","l":"א","b":"אמורא בבלי בסוף הדור הששי. נראה, כי היה חברו של רבינא, שעמו נשא ונתן (ב\"ק ל\"ט ע\"ב)."},{"i":412,"n":"רבי אחא בר אבין בר בנימין","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. מובא (שהש\"ר פ\"ח - ו\u0027) אמר בשם רבי אחא בריה דרב פפא (הוא רבי אחא אריכא) ו\"סה\"ד\" כתב: \"נראה כי רב אחא ט\"ס\"."},{"i":413,"n":"רב אחא בר אדא","l":"א","b":"אמורא בבלי בדור השלישי. תלמידם של רב (ברכות כ\"ט ע\"ב) ושל רב המנונא (עירובין ע\"ז ע\"ב). אמר משמיה דרב יהודה (סנהדרין צ\u0027 ע\"ב). היה בארץ ישראל וחזר לבבל (קידושין ל\u0027 ע\"א). האריך ימים עד תקופת רבא (ב\"ב קס\"ז ע\"א)."},{"i":414,"n":"רב אחא בר אהבה","l":"א","b":"מובא בבבלי (עירובין צ\"ח ע\"א). אך \"דק\"ס\" גורס: \"רב אדא בר אהבה\", וכן יש גורסים במקום אחר (יומא מ\"ד ע\"ב)."},{"i":415,"n":"רב אחא בר אושעיא","l":"א","b":"מובא ברא\"ש (רפ\"א דעירובין)."},{"i":416,"n":"רב אחא בר אחווא","l":"א","b":"מובא בירושלמי (שבועות פ\"א ה\"א), והוא זהה לרב אחו בר אהבה."},{"i":417,"n":"רב אחא בר אילא","l":"א","b":"מובא בב\"ר (פצ\"ד - ד\u0027), והוא רב אחא בר עולא."},{"i":418,"n":"רב אחא בר אלישיב","l":"א","b":"מובא בויק\"ר (פל\"ה - ו\u0027)."},{"i":419,"n":"אחא בר ביבי מר","l":"א","b":"אמורא בבלי בדור הששי. תלמידו של רבינא (יבמות ח\u0027 ע\"א). אמר שמועה בשם רבא (שם)."},{"i":420,"n":"רב אחא בר ביזנא","l":"א","b":"מובא בבבלי (ברכות ג\u0027 ע\"ב). יתכן שאמורא בעל שם זה לא היה כלל. שכן אותו מאמר מובא במקום אחר (סנהדרין ט\"ז ע\"א), ושם רב אחא בר ביזנא, וכן כתב \"סה\"ד\": \"ט\"ס, וכן הוא ב\u0027עין יעקב\u0027 רב חנא בר ביזנא, ובשס\"ח לא תקנו\"."},{"i":421,"n":"ר\u0027 אחא בר גמדא","l":"א","b":"מובא ב\"ילקוט\" (משלי סוף רמז תתקל\"ב), ואולי ט\"ס וצ\"ל: ר\u0027 חייא בר גמדא, המובא בבבלי (מגילה ל\"א ע\"ב)."},{"i":422,"n":"ר\u0027 אחא בר זבינא","l":"א","b":"מובא (במד\"ר פ\"ח - ר\u0027) והגיר\u0027 (ירו\u0027, קידושין פ\"ד ה\"א) ר\u0027 אבא בר זמינא."},{"i":423,"n":"רב אחא בר זעירא","l":"א","b":"(ע\"ע ר\u0027 אהבה בר זעירא). בלשון ירושלמי \"אחא\" הוא \"אהבה\"."},{"i":424,"n":"רבי אחא בר חיננא","l":"א","b":"מובא בירושלמי (פ\"ג ה\"ז), והוא רבי אחא בר חנינא."},{"i":425,"n":"ר\u0027 אחא בר חנא","l":"א","b":"אמורא בבלי בדור הרביעי. תלמידו של רב ששת (עירובין ס\"ח ע\"ב). \"דק\"ס\" גורס: רבה בר רב חנא."},{"i":426,"n":"רבי אחא בר חנינא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מושבו היה בדרום (חולין קל\"ב ע\"ב). תלמידו של ר\u0027 אסי (סנהדרין מ\"ב ע\"א) ושל רבי אבהו (יבמות ס\"ה ע\"ב). ר\u0027 לוי מסר בשמו (ירו\u0027, ברכות פ\"ב ה\"ד), וכן ר\"ז (פסחים נ\"א ע\"א). על דבריו התבססו אמוראי בבל: \"והאמר ר\u0027 אחא בר חנינא\" (חולין קל\"ב ע\"ב: עירובין ס\"ד ע\"א). היה עני מרוד (שבת קי\"ד ע\"א)."},{"i":427,"n":"ר\u0027 אחא בר יאשיה","l":"א","b":"מובא בבבלי (נדרים כ\u0027 ע\"א), ונראה שצ\"ל: ר\u0027 אחי בר יאשיה."},{"i":428,"n":"רב אחא בר יוסף","l":"א","b":"אמורא בבלי בדור השלישי. תלמידו של רב הונא (שבת ק\"מ ע\"א) ושל רב חסדא (ב\"מ פ\"ז ע\"א). רב נחמן בר יצחק היה בן אחותו (שם)."},{"i":429,"n":"רב אחא בר יעקב","l":"א","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב הונא (יבמות ס\"ד ע\"ב). האריך ימים, ורב פפא עוד היה תלמידו (חולין ל\"ג ע\"א). רבא שיבחו לפני רב נחמן שהוא אדם גדול, ור\"נ לא ידע להשיב על שאלותיו (ב\"ק מ\u0027 ע\"א). היה מראשי העיר פפוניא, הסמוכה לפומבדיתא (נדה ס\"ז ע\"ב). היה מלומד בנסים (קידושין כ\"ט ע\"ב). נפטר מתוך עין הרע (ב\"ב י\"ד ע\"א)."},{"i":430,"n":"רבי אחא בר יצחק","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. שאל מר\u0027 זעירא (ירו\u0027, שבת פ\"ו ה\"ב). חברו של ר\u0027 אבא בר ממל (ירו\u0027, שבת פ\"ג ה\"ג)."},{"i":431,"n":"ר\u0027 אחא בר לא","l":"א","b":"הוא ר\u0027 אחא בר אילא מובא בירו\u0027 (דמאי פ\"ו ה\"ב)."},{"i":432,"n":"רב אחא בר מניומי","l":"א","b":"אמורא בבלי בדור הרביעי. תלמידו של רב נחמן (ב\"ק ק\"ו ע\"א). נשא ונתן בהלכה עם אביי (ב\"ק נ\"ט ע\"ב), ומצינו שרבא משיב על דבריו (נדרים מ\"ז ע\"ב)."},{"i":433,"n":"רב אחא בר נתן","l":"א","b":"אמורא בבלי בדור החמישי. מובא בבבלי (חולין מ\"ט ע\"א) לפי גירסת הרא\"ש. חלק עם מר זוטרא בריה דרב מרי (שם)."},{"i":434,"n":"ר\u0027 אחא בר סימון","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. מובא בב\"ר (ספמ\"א). ור\u0027 עזריה אומר משמו (שם)."},{"i":435,"n":"רב אחא בר עויא","l":"א","b":"הוא רב אחא בר רב עויא."},{"i":436,"n":"רב אחא בר עוירא","l":"א","b":"אמורא בבלי בדור השביעי. תלמיד של רב אשי (ברכות מ\"ד ע\"א). יתכן שהשם משובש, והוא: רב אחא בר אויא."},{"i":437,"n":"ר\u0027 אחא בר עולא","l":"א","b":"אמורא בבלי בדור הרביעי. תלמידו של רב חסדא (שבת נ\"ד ע\"ב). עלה לארץ ישראל ונשא ונתן שם עם רבי זירא (ירו\u0027, עירובין פ\"א ה\"א). מצינו, שרב פפא בריה דרב אחא בר אדא אמר משמו (עירובין כ\"א ע\"ב). היה עמל בתורה ועל כן נתן לו ר\u0027 יונה מעשר, על אף שלא היה כהן (ירו\u0027, מע\"ש פ\"ה ה\"ג)."},{"i":438,"n":"רב אחא בר עזא","l":"א","b":"הוא רב אדא בר עזא."},{"i":439,"n":"רב אחא בר עילא","l":"א","b":"מובא בירושלמי (עירובין פ\"א ה\"א), והוא רב אחא בר עולא."},{"i":440,"n":"אחא בר פנחס","l":"א","b":"אמורא בבלי בדור הרביעי. מובא בבבלי (מו\"ק ט\"ו ע\"א). מסר בשמו של רב יוסף (שם)."},{"i":441,"n":"רב אחא בר פפא","l":"א","b":"מובא בבבלי (שבת קי\"א ע\"א), וע\"ע רב אחא אריכא."},{"i":442,"n":"רב אחא בר פפי","l":"א","b":"מובא בירושלמי (יבמות פ\"ח ה\"ב). נראה, שהוא רב אחא בר פפא, וע\"ע רב אחא אריכא."},{"i":443,"n":"רב אחא בר רב","l":"א","b":"אמורא בבלי בדור השביעי. תלמידו של רבינא הראשון (קידושין י\"ג ע\"א), ומצינו שהקשה לו (חולין ל\"ג ע\"א). חלק עם רבינא האחרון ובענין זה באו לשאול אצל מר בר רב אשי (חולין צ\"ז ע\"ב, לפי גירסת הב\"ח)."},{"i":444,"n":"אחא בר רב הונא","l":"א","b":"אמורא בבלי בדור הרביעי. תלמידו של רבה (שבועות ל\"ו ע\"ב), של רב יוסף (קידושין י\"ב ע\"ב), של ר\u0027 ששת (ב\"ב ע\u0027 ע\"א) ושל רב נחמן (חולין ע\"ו ע\"ב). היה שליח להעברת הלכות בין רב חסדא לרבה (פסחים מ\"ז ע\"א). רבא קרא לו \"גברא רבא\" (נדרים צ\u0027 ע\"א). ושאל מרבא (קידושין נ\u0027 ע\"ב)."},{"i":445,"n":"רב אחא בר רב הונא","l":"א","b":"מובא בבבלי (חולין נ\"ט ע\"ב), יחד עם חכם סבוראי אחר - רב שמואל בריה דרב הונא. נפטר ביום א\u0027, ד\u0027 אדר תתי\"ז לשטרות [ד\"א רס\"ו] - (605), (\"אגרת רב שרירא גאון\")."},{"i":446,"n":"רב אחא בר רב חנה","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מובא בבבלי (ע\"ז ל\"ח ע\"ב: מנחות ל\"א ע\"ב). תלמידו של רבי יוחנן (שם), ואולי הוא ר\u0027 אחא בר חנא."},{"i":447,"n":"רב אחא בר רב עוא","l":"א","b":"מובא בבבלי (חולין נ\u0027 ע\"ב), וצ\"ל: רב אחא בר רב עויא."},{"i":448,"n":"רב אחא בר רב עויא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (פסחים ל\"ג ע\"ב) ושל רבי אסי (ב\"ב נ\"ו ע\"א). כשירד לבבל, למד לפני רב חסדא (פסחים שם)."},{"i":449,"n":"רב אחא בר רב קטינה","l":"א","b":"ע\"ע רב חנינא בר רב קטינא ורב הונא בר רב קטינא."},{"i":450,"n":"רב אחא בר רבינא","l":"א","b":"אמורא בבלי בדור הששי. בן דורו של רב אשי, ששלח לו שבסר זוזי בפדיון הבן (בכורות ג\u0027 ע\"א). יש סוברים, שצ\"ל: רב אחא בריה דרבא."},{"i":451,"n":"אחא בר שילא איש כפר תמרתא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. בעל אגדה. ר\u0027 לוי מסר בשמו (אס\"ר ספ\"ו)."},{"i":452,"n":"רב אחא בר שישא","l":"א","b":"מובא בבבלי (שבת ס\u0027 ע\"א) לגירסת \"דק\"ס\", אבל לפנינו: רב אדא נרשאה."},{"i":453,"n":"רב אחא בר תחליפא","l":"א","b":"אמורא בבלי בדור החמישי. תלמיד של רבא (ב\"ק ל\"ד ע\"ב). חברו של ר\u0027 אלעזר מהגרוניא: שניהם בקרו בביתו של רב אחא בר איקא (עירובין ס\"ג ע\"א). כשחלק עם רבינא, הכריע רבא כרב אחא בר תחליפא (גיטין ע\"ג ע\"א)."},{"i":454,"n":"רב אחא ברדלא","l":"א","b":"אמורא בבלי בדור השני. תלמיד של רב (סוכה כ\"ו ע\"א)."},{"i":455,"n":"רב אחא בריה דרב אויא","l":"א","b":"אמורא בבלי בדור הששי - השביעי. היה תלמידו של רב אשי (ב\"מ ק\"ט ע\"ב ברש\"י ד\"ה: כי מטית). נראה שהשתתף עם רב אשי בסידור הש\"ס (עירובין מ\"ח ע\"ב)."},{"i":456,"n":"רב אחא בריה דרב אחא","l":"א","b":"אמורא בבלי בדור השביעי. מצינו שהקשה לרב אשי (שבת ק\"א ע\"א). \"דק\"ס\" גורס: \"בריה דרבא\"."},{"i":457,"n":"רב אחא בריה דרב איקא","l":"א","b":"אמורא בבלי בדור החמישי. בן אחותו ותלמידו של רב אחא בר יעקב (כתובות ע\"ד ע\"א). חברו של רב פפא ונשא ונתן עמו (שבת ו\u0027 ע\"א) וכן עם רב אשי (ברכות ו\u0027 ע\"א). אביו נקרא על שמו. אולי היה גדול מאביו (ע\"ז ס\"ה ע\"א)."},{"i":458,"n":"רב אחא בריה דרב אמי","l":"א","b":"מובא בבבלי (יומא פ\"ד ע\"א). יתכן שאמורא בעל שם זה לא היה כלל. וגירסת \"דק\"ס\" שם: \"רב אחא בריה דרבא\", כפי שמובא אותו מאמר במקום אחר (ע\"ז כ\"ח ע\"א), ובמקום שלישי (זבחים ס\"א ע\"ב) אותו מאמר לפי גירסת \"שיטה מקובצת\": \"רב אחדבוי בר אמי\"."},{"i":459,"n":"רב אחא בריה דרב אשי","l":"א","b":"מובא בבבלי (זבחים צ\"א ע\"א). יתכן שאמורא בעל שם זה לא היה כלל. גירסת \"דק\"ס\": רב אחא בריה דרבא. וכן גירסת השאלתות במקום אחר (חולין צ\"ז ע\"ב - עיין מסורת הש\"ס): רב אחא בר רב. כן גרס הב\"ח."},{"i":460,"n":"רב אחא בריה דרב חייא","l":"א","b":"אמורא בדור השביעי. שאל מרב אשי (נדרים י\u0027 ע\"ב)."},{"i":461,"n":"רב אחא בריה דרב יוסף","l":"א","b":"אמורא בבלי בדור הששי. שאל מרב אשי (יבמות ל\"א ע\"ב). היה חריף ומעמיק (ב\"מ ק\"ט ע\"ב ברש\"י ד\"ה: כי)."},{"i":462,"n":"רב אחא בריה דרב ייבא","l":"א","b":"אמורא בבלי בדור הששי - השביעי מצינו שאמר משמיה דמר זוטרא (נדה ס\"א ע\"ב), ורב אשי הקשה על דבריו (שם)."},{"i":463,"n":"רב אחא בריה דרב נחמן","l":"א","b":"אמורא בבלי בדור הרביעי. בנו של רב נחמן (שבת קי\"ד ע\"א). אך \"דק\"ס\" גורס שם: מר זוטרא, ואם כן לא היה קיים כלל אמורא ושמו רב אחא בריה דרב נחמן, שכן הוא נזכר בש\"ס רק בפעם זאת."},{"i":464,"n":"רב אחא בריה דרבא","l":"א","b":"אמורא בבלי בדור הששי. תלמיד מובהק לר\u0027 כהנא (סוכה ל\"ב ע\"ב). נשא ונתן רבות עם רב אשי. יותר משבעים פעם נמצא בש\"ס הלשון: \"אמר ליה רב אחא בריה דרבא לרב אשי\". היה כתלמיד - חבר לרב אשי (חולין י\"ז ע\"ב), אמר על רב אשי \"מימות רבי ועד רב אשי לא מצינו תורה וגדולה במקום אחד\" (גיטין נ\"ט ע\"א). היה גם חברו של רבינא (פסחים ל\"ט ע\"א). עמד בראש ישיבת פומבדיתא מד\"א קע\"ד (414) עד פטירתו בשנת קע\"ט (914) (\"אגרת רב שרירא גאון\")."},{"i":465,"n":"ר\u0027 אחא בריה דרבה","l":"א","b":"מובא בבבלי (יבמות מ\"ה ע\"ב). והוא רב אחא בריה דרבא."},{"i":466,"n":"ר\u0027 אחא בריה דר\u0027 בא בר ממל","l":"א","b":"מובא בירושלמי (שבת פ\"ו ה\"ו). יש דפוסים שבהם כתוב: ר\u0027 אחא בשם ר\u0027 בא בר ממל."},{"i":467,"n":"רב אחא בריה דר\u0027 חייא בר אבא","l":"א","b":"מוזכר בבבלי (ברכות י\"ד ע\"א). יתכן שאמורא נושא שם זה לא היה כלל, שכן גירסת \"דק\"ס\": א\"ר אבא בריה דר\u0027 חייא בר אבא. ו\"סה\"ד\" מפקפק: \"אולי צ\"ל ר\u0027 אבא בריה דר\u0027 חייא בר אבא\", ועוד, אם נגרוס אחא ולא אבא, האם הוא זהה לר\u0027 אחא בריה דר\u0027 חייא המובא בבבלי? (נדרים י\u0027 ע\"ב)."},{"i":468,"n":"רב אחא גלילאה","l":"א","b":"מובא בבבלי (ע\"ז ג\u0027 ע\"ב). כן גירסת ה\"יוחסין\", \"סה\"ד\", \"עין יעקב\" ו\"דק\"ס\". ולפנינו: \"א\"ל רב אחא [בלי גלילאה] לרב נחמן בר יצחק: \u0027מיום שחרב בית המקדש אין שחוק להקב\"ה\"."},{"i":469,"n":"אחא כרסלא","l":"א","b":"מובא בבבלי (סנהדרין ה\u0027 ע\"א). חי בבבל בדור המעבר בין התנאים לאמוראים. אבי אביו של רבי חייא (שם). אין ראיה שהיה חכם."},{"i":470,"n":"רב אחא מבי חוזאה","l":"א","b":"מובא בבבלי (גיטין ז\u0027 ע\"א). נראה, שהיה בזמנו של רב אשי (כן דעת \"סה\"ד\"). לפי גירסת רב שרירא גאון צ\"ל: \"רב אחא מבי חתים\", והוא מרבנן סבוראי. וכן דעת בעל ה\"כריתות\" שהוא היה ריש מרבנן סבוראי."},{"i":471,"n":"רב אחא מבי חתים","l":"א","b":"ע\"ע רב אחא מבי חוזאה."},{"i":472,"n":"רב אחא מגדלאה","l":"א","b":"מובא בילקוט (ישעיה רמז)."},{"i":473,"n":"רב אחא מדפתי","l":"א","b":"אמורא בבלי בדור השביעי. תלמיד של רבינא. עשרות פעמים מוזכר הלשון בש\"ס: \"אמר ליה רב אחא מדפתי לרבינא\" (שבת קל\"ט ע\"ב). תלמיד של מרימר (ברכות מ\"ה ע\"ב). חברם של יהודה בר מרימר ומר בר רב אשי (שם), והיו שווים בחכמה ושנים ולא היה אחד מופלג וגדול מחברו (שם ברש\"י). רצו למנותו לראש ישיבה, אך מר בר רב אשי הקדימו (ב\"ב י\"ב ע\"ב)."},{"i":474,"n":"רב אחא מהוצל","l":"א","b":"אמורא בבלי בדור הששי. מובא בבבלי (ביצה ל\"ב ע\"ב). חברו של רבינא (שם). היה לו נדר להתיר ובא לרב אשי (כריתות י\"ג ע\"ב)."},{"i":475,"n":"רב אחא מפרזקיא","l":"א","b":"אמורא בבלי בדור הששי - השביעי. תלמידו של רב אשי (יבמות נ\"ט ע\"ב - לגירסת הרא\"ש: וכן לגירסת התוספות בתמורה ל\u0027 ע\"ב ד\"ה: מנא). ולפנינו הגירסא: רבא מפרקין. ומסורת הש\"ס מתקן: רבא מפרזקיא."},{"i":476,"n":"רב אחא סבא","l":"א","b":"אמורא בבלי בדור החמישי - הששי. נשא ונתן עם רב אשי (קידושין כ\"א ע\"א). היה בנו של רב מרי בר איסור (שם ס\"ה ע\"ב). (עיין מר זוטרא בריה דרב מרי). יש גירסא ר\u0027 אדא סבא, אך \"סה\"ד\" גורס: ר\u0027 אחא סבא."},{"i":477,"n":"רב אחא קרחינאה","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. תלמיד של רבי אלעזר (ברכות ל\"ג ע\"א). בסנהדרין (צ\"ב ע\"א) מובא שמו בטעות: ר\u0027 אדא קרחינאה וצ\"ל: ר\u0027 אחא קרחינאה. ויש רב אדא קרחינאה, אמורא בבלי בדור החמישי."},{"i":478,"n":"רב אחא קרטיגנאה","l":"א","b":"בשם זה יש שיבושים. בבבלי (ב\"ק קי\"ד ע\"ב) מובא: \"א\"ר חנא קרטיגנאה ואמרי לה רב אחא קרטיגואה\", ובאותו ענין: \"א\"ר חנן קרטיגנאה\" (כתובות כ\"ז ע\"ב). ובענין אחר מובא \"חיננא קרתיגנאה\" (ירו\u0027, שבת פט\"ז ה\"ב), ובאותו ענין בשיבוש: \"חיננא קרתחמה\" (שם ביצה פ\"א ה\"ו)."},{"i":479,"n":"ר\u0027 אחא רובא","l":"א","b":"אמורא ארץ ישראלי בדור השני. מצינו שרבי אסי מסר בשמו (ירו\u0027, ברכות פ\"ב ה\"ד)."},{"i":480,"n":"רבי אחא שר הבירא (2)","l":"א","b":"תנא בדור הרביעי. בבבלי (ב\"ב קמ\"ו ע\"א) מובא: \"וזו הלכה העלה רב [צ\"ל רבי] אחא שר הבירה לפני חכמים באושא\"."},{"i":481,"n":"רב אחאי (2)","l":"א","b":"מובא בבבלי (זבחים ק\"ב ע\"ב). בתוספות שם כתבו: \"שהיה מרבנן סבוראי דבתר רבינא ורב אשי דהוסיף הוראה וכתבו אחרי כן דבריו בסוף הש\"ס\"."},{"i":482,"n":"ר\u0027 אחאי (2)","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי, שמסר בשם רבי אבא בר ממל (תרומות פ\"י ה\"א)."},{"i":483,"n":"ר\u0027 אחאי בר יעקב","l":"א","b":"מובא בירושלמי (שבת פ\"ב ה\"ו), ונראה שהוא הוא ר\u0027 אחא בר יעקב."},{"i":484,"n":"ר\u0027 אחאי בריבי","l":"א","b":"מובא בבבלי (בכורות כ\"ד ע\"ב), ופרש\"י: \"אדם גדול וחשוב בדורו\" ואין לקבוע במדוייק מי הוא. ע\"ע בריבי."},{"i":485,"n":"רב אחדבוי","l":"א","b":"אמורא בבלי בדור השני. תלמידו של רב, כדמצינו: \"אמר רב אחדבוי אמר רב\" (ע\"ז ל\"ד ע\"ב). ופירש\"י: \"אחדבוי שם חכם\"."},{"i":486,"n":"רב אחדבוי אחוי דמר אחא","l":"א","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (שבת קי\"א ע\"ב). ע\"ע רב אחא אחוה דמר אחאי."},{"i":487,"n":"רב אחדבוי בר אמי","l":"א","b":"אמורא בבלי בדור השני - השלישי. מסר בשם רב (תמורה ל\u0027 ע\"ב). מהלשון נראה כאילו קיבל תורה מפי רב חסדא (פסחים ע\"ה ע\"א), ואולי אף מרב ששת (סנהדרין נ\"ה ע\"א). אך נראה יותר שהיה חברם."},{"i":488,"n":"רב אחדבוי בר רב מתנה","l":"א","b":"אמורא בבלי בדור השלישי. מצינו שמסר בשם רב מתנה אביו (שבת ס\u0027 ע\"ב). גם אחיו רב טובי היה אמורא (ב\"ב קנ\"א ע\"א)."},{"i":489,"n":"רב אחו בר אהבה","l":"א","b":"הוא רב אחא בר אחווא."},{"i":490,"n":"אחוה בר זעירא","l":"א","b":"ע\"ע ר\u0027 אהבה בר זעירא. בלשון ירושלמי \"אחוה\" הוא \"אהבה\"."},{"i":491,"n":"אחוה דבר אבוברם","l":"א","b":"אמורא בבלי בדור החמישי - הששי. בנו של האמורא אבוברם (חולין ל\"ח ע\"א). ע\"ע אבוברם."},{"i":492,"n":"ר\u0027 אחווא בר\u0027 זירא","l":"א","b":"מובא בירושלמי (פסחים פ\"ב ה\"ד). זהה עם אהבה בריה דר\u0027 זירא."},{"i":493,"n":"ר\u0027 אחווה","l":"א","b":"בב\"ר: \"א\"ר אחווה בשם ר\"ז\". (פל\"ט - י\"א), וצ\"ל ר\u0027 אחווה בר זעירא. ע\"ע אהבה בריה דרבי זירא."},{"i":494,"n":"אחי (2)","l":"א","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. היה ממונה על הגיטין בימי ר\u0027 אסי (גיטין ה\u0027 ע\"ב), ואולי זה ר\u0027 אחי, שמסר בשמם של רבי אבהו ורבי שמואל בר נחמני (ע\"ע)."},{"i":495,"n":"רב אחי","l":"א","b":"אמורא בבלי בדור השלישי - הרביעי. תלמיד של רב יוסף (עירובין י\u0027 ע\"א), ואולי זה ר\u0027 אחי שמסר בשמם של רבי אבהו ורבי שמואל בר נחמני (ע\"ע)."},{"i":496,"n":"רבי אחי (3)","l":"א","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מסר בשם רבי אבהו (ירו\u0027, סנהדרין פ\"ד ה\"ו) ובשם ר\u0027 שמואל בר נחמני (ילקוט מלכים א\u0027 רמז קע\"ג). אולי הוא ר\u0027 אחי תלמיד רב יוסף."},{"i":497,"n":"ר\u0027 אחי","l":"א","b":"פעמים בא במקום ר\u0027 אחאי."},{"i":498,"n":"ר\u0027 אחי בר חנינא","l":"א","b":"תנא. מובא בברייתא בבבלי (שבת ע\"ט ע\"ב). רבי אחא מסר בשמו (שם)."},{"i":499,"n":"אחי בר יאשיה","l":"א","b":"תנא בדור החמישי. רבינו הקדוש הזכירו לפני פטירתו (קידושין ע\"ב ע\"א). חלק עם אביו (גיטין מ\"ה ע\"א). נקבר בנהרדעא (שבת קנ\"ב ע\"ב)."},{"i":500,"n":"אחי שקיא","l":"א","b":"אמורא בבלי בדור השלישי. מובא בבבלי (ביצה כ\"ה ע\"ב). תלמיד של רב הונא (שם)."},{"i":501,"n":"רבי אחיא","l":"א","b":"מובא בבבלי (זבחים מ\"ח ע\"ב). ע\"ע רבי אחייה."},{"i":502,"n":"אחיה","l":"א","b":"הוא ואחיו שמעיה היו מהרוגי מלכות בזמן הבית, ופירש\"י: \"חסידים היו\" (תענית י\"ח ע\"ב). וב\"ערוך\" ערך \"הרג\" כתב שהם: \"הרוגי לוד\" (פסחים נ\u0027 ע\"א), עליהם נאמר (שם) ש\"אין אדם יכול לעמוד במחיצתן\"."},{"i":503,"n":"רב אחיי בר אדא","l":"א","b":"מובא בבבלי (קידושין כ\"ב ע\"ב). נראה אולי שהיה בתקופת רב אשי (דור ששי לאמוראי בבל)."},{"i":504,"n":"ר\u0027 אחייא בר אבא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מובא בב\"ר (פצ\"ח - ט\u0027). ר\u0027 ירמיה אמר בשמו (שם)."},{"i":505,"n":"רבי אחייה","l":"א","b":"תנא בדור השלישי - הרביעי. היה ראש לבני הגולה בזמנו של חנניה בן אחי רבי יהושע (ברכות ס\"ג ע\"ב). נראה, שהוא המובא (מו\"ק כ\u0027 ע\"ב) \"רבי חייא לחוד רבי אחייה לחוד\", וכן נראה שהוא המובא (מנחות נ\"ו ע\"א) \"דתניא ר\u0027 אחייה אומר\" (סה\"ד: קבע להם ערכים נפרדים)."},{"i":506,"n":"אחייה בר זעירא","l":"א","b":"ע\"ע ר\u0027 אהבה בר זעירא. בלשון ירושלמי \"אחייה\" הוא גם \"אהבה\"."},{"i":507,"n":"ר\u0027 אחייה בר\u0027 זירא","l":"א","b":"מובא בירושלמי (ברכות פ\"א), והוא ואהבה בריה דר\u0027 זירא אחד הוא."},{"i":508,"n":"רב אחלי","l":"א","b":"מובא בבבלי (עירובין י\"ב ע\"א). ה\"יוחסין\" סובר שהיה בזמן שמואל, ואין זה מוכרח מהגמרא. \"דק\"ס\" גרס: רב אהלי. ו\"סה\"ד\" כתב בערך אהילאי: \"עיין לקמן רב אחלי וכו\u0027 והכל אחד\"."},{"i":509,"n":"אחר","l":"א","b":"מובא בבבלי (ברכות נ\"ז ע\"ב). והוא אלישע בן אבויה."},{"i":510,"n":"אחרים","l":"א","b":"מובא בבבלי (הוריות י\"ג ע\"ב). שם מובא ענין הסכסוך שהיה בין רשב\"ג ור\"מ וקנסו לר\"מ שיקראוהו בשם אחרים. אבל אין זה כלל בכל הש\"ס. (סוטה י\"ב ע\"א - בתוספות)."},{"i":511,"n":"איבו (4)","l":"א","b":"אמורא בדור המעבר של התנאים לאמוראים. אביו של רב. היה בארץ ישראל וקיבל מר\"א בר צדוק (סוכה מ\"ד ע\"ב). נשא לאשה את אחות רבי חייא. (פסחים ד\u0027 ע\"א - רש\"י). איבו ורבי חייא היו אחים מן האב."},{"i":512,"n":"רבי איבו","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. תלמיד של רבי ינאי (פסחים מ\"ו ע\"א). מבעלי האגדה החשובים. מדרשים רבים ממנו מצויים בבראשית רבה. הוא בעל המאמר: \"אין אדם יוצא מן העולם וחצי תאותו בידו\" (קה\"ר פ\"א - י\"ג)."},{"i":513,"n":"ר\u0027 איבו בר אגרא","l":"א","b":"מובא בב\"ר (פפ\"ה - ו\u0027), והוא ר\u0027 איבו בר נגרי."},{"i":514,"n":"ר\u0027 איבו בר כהנא","l":"א","b":"כתב \"סה\"ד\" בערך ר\u0027 אבא בר כהנא: \"ובתנחומא פ\u0027 ראה ר\u0027 איבא בר כהנא אולי אחד הוא\"."},{"i":515,"n":"רבי איבו בר נגרי","l":"א","b":"ע\"ע רבי אייבו בר נגרי."},{"i":516,"n":"איבות בר איהי","l":"א","b":"מובא בבבלי (עירובין ע\"ד ע\"א). גירסת \"דק\"ס\": אבוה בר איהי."},{"i":517,"n":"רב אידאי","l":"א","b":"אמורא בדור הרביעי - החמישי. אביו של אמורא ושמו מר בר רב אידאי (חולין ס\"ג ע\"א), ואין לנו מאומה מתורתו. מובא רק בהקשר לבנו (שם)."},{"i":518,"n":"רב אידי","l":"א","b":"אמורא בדור השלישי - הרביעי. עלה לארץ ישראל והיה שם תלמיד של רבי אסי (ירו\u0027, יבמות פי\"א ה\"ב). מצינו שמסר שמועה בשם רב חסדא (שם). נראה שחזר לבבל ורבא קבל ממנו (נדרים ה\u0027 ע\"ב)."},{"i":519,"n":"רב אידי אבוה דרבי יעקב בר אידי","l":"א","b":"אמורא ארץ ישראלי בדור השני. תלמיד של רבי יהושע בן לוי (עירובין ס\u0027 ע\"ב). היה אבי רבי יעקב בר אידי (חגיגה ה\u0027 ע\"ב). רבנן קראו לו \"בר בי רב דחד יומא\", לאחר שהלך ג\u0027 חדשים מביתו לבית המדרש ושהה שם רק יום אחד (שם). מצינו שר\u0027 יוחנן פייסו (שם)."},{"i":520,"n":"רב אידי בר אבין (2)","l":"א","b":"אמורא בבלי בדור הרביעי. תלמיד של רב חסדא (פסחים ק\"א ע\"ב). מתלמידיו: רב פפא ורב הונא בריה דר\u0027 יהושע (פסחים ל\"ה ע\"א). רב הונא בירך את אביו שיהיו לו בנים חכמים, ונולדו לו: הוא ואחיו רב חייא בר אבין (שבת כ\"ג ע\"ב). שלח לאביי (יבמות ע\"ו ע\"א). מצינו שהיה לו בן. (שבת קל\"ו ע\"א)."},{"i":521,"n":"רב אידי בר אידי בר גרשם","l":"א","b":"אמורא בדור השני - השלישי. מסר בשמו של ר\u0027 שמן בר אבא (חולין צ\"ח ע\"א). אולי הוא אדא בר גרשון."},{"i":522,"n":"ר\u0027 אידי בר גרשום","l":"א","b":"אמורא בדור השני. מסר בשם רב אדא בר אהבה (כריתות ט\u0027 ע\"א), ואולי הוא ר\u0027 אדא בר גרשון."},{"i":523,"n":"אידי בר יעקב","l":"א","b":"מובא ב\"זוהר\" (פ\u0027 לך)."},{"i":524,"n":"רב אידי בר שימי","l":"א","b":"מובא ב\"ילקוט\" (זכריה רמז תקע\"ח). ואולי צ\"ל: רב אדא בר שימי. (ע\"ע)."},{"i":525,"n":"רב אידי בר שישא","l":"א","b":"מובא בבבלי (פסחים ק\"ו ע\"א). אמורא שאין לקבוע את זמנו המדוייק."},{"i":526,"n":"ר\u0027 אידי בר שמעון","l":"א","b":"מובא בירושלמי (ברכות פ\"ב ה\"ג), והוא ר\u0027 אדא בר שמעון."},{"i":527,"n":"רב אידי בריה דרב איקא","l":"א","b":"אמורא בבלי בדור הששי. רב הונא בר מנוח מסר משמו (יבמות מ\"ג ע\"א), ואולי הוא ר\u0027 אדא בריה דרב איקא."},{"i":528,"n":"רבי אידי דחוטריה","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. תלמיד של ירמיה (ירו\u0027, שקלים פ\"ז ה\"ה)."},{"i":529,"n":"ר\u0027 אידי דקיסרין","l":"א","b":"מסר בשם ר\"י (ירו\u0027, מו\"ק פ\"ג ה\"ה) ושוב לא נזכר שמו."},{"i":530,"n":"רב אידי סרסיה","l":"א","b":"אמורא בבלי בדור השלישי - הרביעי. סרסיה (שמש) ותלמיד של רב ששת (בכורות ל\"א ע\"ב). רב ששת הקפיד עליו שלא אמר בשמו (שם)."},{"i":531,"n":"רב אידית","l":"א","b":"אמורא בבלי בדור השני - השלישי. חי בזמנו של רב נחמן, שאמר עליו שרק היודע להשיב למינים כרב אידית, רשאי להתוכח עמהם (סנהדרין ל\"ח ע\"ב)."},{"i":532,"n":"איו","l":"א","b":"מובא בבבלי (עירובין ל\"ו ע\"ב). שם מצינו שרב מסתמך על ברייתא ששנה איו. ופירש\"י: איו - שם חכם."},{"i":533,"n":"אייבו","l":"א","b":"הוא איבו."},{"i":534,"n":"רבי אייבו בר נגרי","l":"א","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידו של רבי חייא בר אבא (סנהדרין ס\"ז ע\"ב), ושניהם היו תלמידיו של רבי יוחנן (ר\"ה כ\"א ע\"א - רש\"י)."},{"i":535,"n":"ר\u0027 אייבון","l":"א","b":"מובא (ירו\u0027, עירובין פ\"א ה\"א) ע\"ע אבין."},{"i":536,"n":"רבי אייניא בן פזי","l":"א","b":"אמורא בבלי בדור הרביעי. אמר בשם ר\u0027 יהודה (ירו\u0027, עירובין ספ\"ה). \"סה\"ד\" סובר שר\u0027 אונייא בן פזי ור\u0027 חנניא בן פזי אחד הוא."},{"i":537,"n":"אילא","l":"א","b":"חי ביבנה בזמן התנאים. בזכות היותו חסיד, התירו לו חכמים לקחת כסף תמורת ראיית מומי בכורות (בכורות כ\"ט ע\"א)."},{"i":538,"n":"ר\u0027 אילא","l":"א","b":"מובא בבבלי (מו\"ק כ\"ה ע\"א), והוא רבי אלעאי האמורא."},{"i":539,"n":"ר\u0027 אילא בריה דרב שמואל בר מרתא","l":"א","b":"אמורא בבלי בדור השני. אמר משמיה דרב (ברכות י\"ג ע\"ב)."},{"i":540,"n":"ר\u0027 אילאי דנציבין","l":"א","b":"מובא ב\"זוהר\" (שלח קס\"ב). הוא ובנו ירדו למערה (שם)."},{"i":541,"n":"ר\u0027 אילם","l":"א","b":"מובא באיכ\"ר (פ\"ב - י\"ב). הגירסא במקום אחר (ויק\"ר פי\"ב - ה\u0027): ר\u0027 הלל בר הילני."},{"i":542,"n":"ר\u0027 אילעא בר יברכיה","l":"א","b":"מובא בבבלי (סוטה מ\"ט ע\"א), והוא ר\u0027 אלעאי בר ברכיה."},{"i":543,"n":"איסור גיורא","l":"א","b":"גר צדק בדור השני - השלישי. חתנו של שמואל (חברו דרב). והיה גר צדק, כמו שרש\"י מפרש: \"ובת שמואל היתה ונשבית לבין העמים ובא עליה אחד ונתעברה ממנו ואח\"כ התגייר ושמיה איסור\" (ברכות ט\"ז ע\"א). נראה שנעשה אח\"כ חכם: \"אמר רבא אמר לי איסור גיורא\" (ע\"ז ע\u0027 ע\"א). בנו ונכדיו היו אמוראים: בנו האמורא רב מרי, ושני בני רב מרי - מר זוטרא ורב אדא סבא."},{"i":544,"n":"איסי (2)","l":"א","b":"חי בבבל בדור השלישי - הרביעי. בנו של ר\u0027 יצחק ונכדו של רב יהודה ואביה של חומה שנישאה לשלושה אמוראים שמתו תחתיה (רחבה דפומבדיתא, רב יצחק בריה דרבה בר בר חנא ואביי)."},{"i":545,"n":"איסי אחוה דרבי זירא","l":"א","b":"מובא בבבלי (מו\"ק כ\u0027 ע\"ב). ע\"ע אבוה דר\u0027 זירא."},{"i":546,"n":"איסי בן גור אריה","l":"א","b":"והוא איסי בן עקביה (פסחים קי\"ג ע\"ב)."},{"i":547,"n":"איסי בן גמליאל","l":"א","b":"והוא איסי בן עקביא (פסחים קי\"ג ע\"ב)."},{"i":548,"n":"איסי בן יהודה","l":"א","b":"מובא בבבלי (גיטין ס\"ז ע\"א), והוא איסי בן עקביה."},{"i":549,"n":"איסי בן יעקב","l":"א","b":"מובא בילקוט (משפטים רמז שכ\"ד) והוא ט\"ס, וצ\"ל: איסי בן עקביה כמו במקום אחר (מכילתא משפטים מס\u0027 דנזיקין פ\"ד)."},{"i":550,"n":"איסי בן מהללאל","l":"א","b":"והוא איסי בן עקביה (פסחים קי\"ג ע\"ב)."},{"i":551,"n":"איסי בן מנחם","l":"א","b":"תנא בדור החמישי. חלק עם איסי בן יהודה (סוטה ט\"ז ע\"א)."},{"i":552,"n":"איסי בן עזאי","l":"א","b":"מובא ב\"ילקוט\" (בשלח רמז רמ\"ג). \"סה\"ד\" כתב כי ט\"ס הוא והגירסא: איסי בן שמאי (מכילתא בשלח מס\u0027 דשירה פ\"ב)."},{"i":553,"n":"איסי בן עקביה","l":"א","b":"תנא בדור החמישי. עלה מבבל לארץ ישראל. היו לו שמות רבים כמובא בבבלי: \"הוא יוסף איש הוצל, הוא יוסף הבבלי, הוא איסי בן גור אריה, הוא איסי בן יהודה, הוא איסי בן גמליאל, הוא איסי בן מהללאל, ומה שמו? איסי בן עקביה שמו\" (פסחים קי\"ג ע\"ב): ובירושלמי: \"הוא יוסף הבבלי, הוא יוסף בן יהודה, הוא יוסי קטנתא\" (ב\"ק פ\"ג ה\"ז). ובדרך כלל מובא בשם: איסי בן יהודה. היה תלמידו החביב של רבי אלעזר בן שמוע (מנחות י\"ח ע\"א), ותלמידו של רבי יוסי (נדרים פ\"א ע\"א) חברו של רבי שמעון בן יוחי (אדר\"נ ספי\"ח). היה מונה שבחם של חכמים (גיטין ס\"ז ע\"א). כשמת אמרו עליו: \"פסקו חסידים\" (סוטה מ\"ט ע\"א)."},{"i":554,"n":"איסי בן שימי","l":"א","b":"מובא במכילתא (בשלח פרשת ויסע סוף פרשה ג\u0027). ונראה שהוא איסי בן שמאי."},{"i":555,"n":"איסי בן שמאי","l":"א","b":"מובא במכילתא (בשלח מס\u0027 דשירה פ\"ב)."},{"i":556,"n":"איסי בר היני","l":"א","b":"אמורא בבלי בדור הראשון - השני. היתה לו ישיבה בבבל ועולא ביקר בה (שבת קמ\"ז ע\"א). עלה לארץ ישראל והקשה על דברי ר\u0027 יוחנן (חולין קל\"ז ע\"ב). כינה את רב \"אבא אריכא\" ורבי יוחנן הקפיד על כך (שם)."},{"i":557,"n":"איסי בר נתן","l":"א","b":"מובא בבבלי (ברכות ס\"ב ע\"א). גירסת \"דק\"ס\": רב אסי בר נתן."},{"i":558,"n":"איסי בריה דרב יצחק בריה דרב יהודה","l":"א","b":"חי בבבל. היה בן בנו של האנורא המפורסם רב יהודה בר יחזקל. מובא פעם בש\"ס ובתו חומה נישאה לרחבא דפומבדיתא ומת, ונישאה לרב יצחק בריה דרבה בר בר חנה ומת, ונישאה לאביי ומת (יבמות ס\"ד ע\"ב). ואין ראיה שאיסי זה נמנה עם החכמים."},{"i":559,"n":"ר\u0027 איסי דקיסרין","l":"א","b":"מובא בקה\"ר (פ\"ז - כ\"ו). \"סה\"ד\" גורס: ר\u0027 יוסי דמן קסרי."},{"i":560,"n":"איפה","l":"א","b":"מובא בבבלי (שבת ס\u0027 ע\"ב), והוא עיפא בן רחבה דפומבדיתא (עיין רש\"י שם)."},{"i":561,"n":"רב איקא","l":"א","b":"אמורא בבלי בדור הרביעי. נשא לאשה את אחות רב אחא בר יעקב, שילדה לו את רב אחא בר איקא (כתובות ע\"ד ע\"א). רב הונא בר מנוח אמר משמו של רב איקא (ב\"ק כ\"ב ע\"א). בנו היה כנראה גדול מאביו, שכן נקרא ע\"ש בנו (ע\"ז ס\"ה ע\"א)."},{"i":562,"n":"רב איקא בר אבין","l":"א","b":"אמורא בבלי בדור השלישי. תלמידו של רב חננאל (קידושין ע\"ב ע\"א), שהיה תלמיד מובהק של רב."},{"i":563,"n":"רב איקא בר חנינא","l":"א","b":"אמורא בבלי בדור הרביעי - החמישי. מובא בבבלי (חולין צ\u0027 ע\"ב)."},{"i":564,"n":"רב איקא בריה דרב אידי","l":"א","b":"מובא בבבלי (ב\"ק י\"ב ע\"א). מסורת הש\"ס גורס: רב איקא בריה דרב אמי."},{"i":565,"n":"רב איקא בריה דרב אמי","l":"א","b":"אמורא בבלי בדור החמישי. נראה שהיה מבית מדרשו של רבא (ב\"ב קמ\"ט ע\"א). רבא הקפיד עליו (שם)."},{"i":566,"n":"רב איקא מפשרוניא","l":"א","b":"אמורא בבלי בדור הרביעי - החמישי. תלמידו של רבא. הקשה לרבא (עירובין ק\"ד ע\"א)."},{"i":567,"n":"ר\u0027 איתי","l":"א","b":"ע\"ע רב אסי."},{"i":568,"n":"ר\u0027 אלאי היורש","l":"א","b":"אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא בירושלמי (גיטין פ\"ח ה\"ב) ופירש \"קרבן העדה\": \"כך שמו\"."},{"i":569,"n":"ר\u0027 אלוני בר טברי","l":"א","b":"מובא בש\"ר (פמ\"ד - ה\u0027). אמר בשם ר\u0027 יצחק (שם)."},{"i":570,"n":"ר\u0027 אליהו","l":"א","b":"מובא בשהש\"ר (פ\"ב - י\"ד - ז\u0027)."},{"i":571,"n":"ר\u0027 אליהו עיני","l":"א","b":"אמורא ארץ ישראלי בדור השני. רבי שמואל בר נחמני מסר בשמו (ב\"ר נ\"א - ט\u0027)."},{"i":572,"n":"אליעזר","l":"א","b":"עיין אלעזר."},{"i":573,"n":"רבי אליעזר","l":"א","b":"הוא רבי אליעזר בן הורקנוס."},{"i":574,"n":"ר\u0027 אליעזר אבוי דר\u0027 יצחק בר נחמן","l":"א","b":"אמורא ארץ ישראלי בדור השני. תלמידו של רבי אושעיא (ירו\u0027, ב\"ב פ\"ח ה\"א). \"סה\"ד\" כתב: \"יש ט\"ס וכו\u0027 ואולי צ\"ל אחוי דר\u0027 יצחק בר נחמן\"."},{"i":575,"n":"אליעזר איש ביריא","l":"א","b":"תנא שאין לקבוע זמנו המדוייק. מובא בבבלי: \"תניא נמי הכי, אליעזר איש ביריא אומר: \u0027יושבי צריפין כיושבי קברים\u0027\" (עירובין נ\"ה ע\"ב), וב\"עין יעקב\" הגירסא: איש ברתותא."},{"i":576,"n":"אליעזר בן גימל","l":"א","b":"מובא (בירו\u0027, תרומות פ\"א ה\"ד), והוא אבא אלעזר בן גימל."},{"i":577,"n":"רבי אליעזר בן דהבאי","l":"א","b":"תנא שאין לקבוע זמנו המדוייק. מובא במסכת כלה רבתי (ספ\"ב). אימרתו: \"האומר דבר בשם רבו מביא גאולה לעולם\" (שם)."},{"i":578,"n":"רבי אליעזר בן הורקנוס","l":"א","b":"תנא בדור השני. והוא סתם רבי אליעזר במשנה (הליכות עולם) או רבי אליעזר הגדול (גיטין נ\"ז ע\"א). היה חתנו של הנשיא רבן גמליאל הזקן (ב\"מ נ\"ט ע\"ב). מושבו היה בלוד, שם היתה לו ישיבה (סנהדרין ל\"ב ע\"ב). החל ללמוד תורה רק בגיל מבוגר (אבות דר\"נ פ\"ו ג\u0027). מגדולי תלמידיו של רבן יוחנן בן זכאי (אבות פ\"ב מ\"ח), שאמר עליו שהוא שקול כנגד כל חכמי ישראל (שם). רבו הגדול של רבי עקיבא, שלמד אצלו 31 שנה (ירו\u0027, פסחים פ\"ו ה\"ג). חברו המובהק של רבי יהושע בן חנניה, ושניהם הוציאו את רבן יוחנן בן זכאי מירושלים בזמן החורבן (גיטין נ\"ו ע\"א). היה אחד מארבעה חכמי הסנהדרין ביבנה שהיו בקיאים בשבעים לשון (סנהדרין י\"ז ע\"ב). פעם חלק על החכמים ולא רצה לקבל דעתם, ואף שיצאה בת קול ואמרה שהלכה כר\u0027 אליעזר בכל מקום - נידוהו (ב\"מ נ\"ט ע\"ב). נשאר בנידויו עד יום מותו, ואז התירוהו (סנהדרין ס\"ח ע\"א). גיסו רבן גמליאל הנשיא, מת לפניו בגלל נדוי זה (ב\"מ שם). מהגמרא משתמע שהאריך ימים עד לאחר חורבן ביתר (גיטין נ\"ז ע\"א). עליו אמרו: \"משמת רבי אליעזר נגנז ס\"ת\" (סוטה מ\"ט ע\"ב)."},{"i":579,"n":"רבי אליעזר בן חלפתא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. רב אחא אמר בשמו (ויר\"ר פכ\"ז - ד\u0027)."},{"i":580,"n":"אליעזר בן חנוך","l":"א","b":"תנא שאין לקבוע זמנו המדוייק. נידוהו על שפיקפק בנטילת ידים, ומת בנידויו, וסקלו ב\"ד את ארונו (עדיות פ\"ה מ\"ו)."},{"i":581,"n":"אליעזר בן יהודה איש איבלים","l":"א","b":"מובא בבבלי (חולין נ\"ה ע\"ב), והוא רבי אליעזר בן יהודה איש אבלים."},{"i":582,"n":"רב אליעזר בן יעקב א\u0027","l":"א","b":"תנא בדור הראשון, שראה בעיניו את הבית ותיארו, ועל לשכה אחת אמר: \"שכחתי מה היתה משמשת\" (מידות פ\"ב מ\"ה). ועוד סיפר, שפעם מצאו את אחי אמו (כהן בביהמ\"ק) ישן ושרפו את כסותו (שם פ\"א מ\"ב). גם הרמב\"ם בהקדמתו מונה אותו בדור שראו החורבן. הוא כתב את מסכת מדות (ירו\u0027, יומא פ\"ב ה\"ב - ובבלי יומא ט\"ו ע\"א). בן עזאי מצא מגילת יוחסין ובה כתוב: \"משנת רבי אליעזר בן יעקב קב ונקי\" (יבמות מ\"ט ע\"ב - וברש\"י שם: \"בכל מקום שנזכר הלכה כמותו\"). ר\u0027 אלעאי (אבי ר\u0027 יהודה בר אלעאי) קיבל ממנו (פסחים ל\"ט ע\"א)."},{"i":583,"n":"רבי אליעזר בן יעקב ב\u0027","l":"א","b":"תנא בדור הרביעי. מתלמידי ר\"ע (ירו\u0027, חגיגה פ\"ג ה\"א). נמנה ששי מבין שבעת תלמידי ר\"ע המוזכרים שם. מסר בשם רבי פנחס בן יאיר, חתנו של רבי שמעון בר יוחאי (מד\u0027 תהלים ספל\"ב). נמנה עם חכמי אושא שנתכנסו אחר מרד בר כוכבא (שהש\"ר פ\"ב - ה\u0027). מצינו שחלק עם ר\"מ (ר\"ה ד\u0027 ע\"ב). ולפי פרש\"י (יבמות צ\"ג א\u0027 - ד\"ה: ורב) קיבל ממנו רבי מאיר."},{"i":584,"n":"רבי אליעזר בן פיאבי","l":"א","b":"הוא רבי אליעזר בן פילא."},{"i":585,"n":"רבי אליעזר בן פילא","l":"א","b":"תנא שחי אחר רבי עקיבא בדור הרביעי או החמישי, והיה מנמק את דעתו של רבי עקיבא (טהרות פ\"ז מ\"ט)."},{"i":586,"n":"רבי אליעזר בן שמעיה איש כפר אותני","l":"א","b":"תנא בדור הראשון. שאל את רבי יוחנן בן זכאי (תוספתא פרה פ\"ט). ע\"ע שמעיה איש כפר עותני."},{"i":587,"n":"אליעזר בר יוסי","l":"א","b":"אמורא ארץ ישראלי בדור החמישי - הששי. היה בנו של ר\u0027 יוסי, שהיה מראשי הדור הרביעי (ירו\u0027, תענית פ\"ב ה\"ב)."},{"i":588,"n":"רבי אליעזר ניותאה","l":"א","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (גיטין נ\u0027 ע\"א). \"יוחסין\" מביא שתי גירסאות נוספות: רבי אליעזר ניזאה או שופאה."},{"i":589,"n":"רב אליקים","l":"א","b":"אמורא בבלי בדור הרביעי - החמישי. שמשו של רבא. רבא שלחו לסגור הדלת בפני רב הונא בריה דרב נחמן \"שלא יקפחנו בהלכות על דברי מחלוקתם\" (ע\"ז נ\"ח ע\"א - רש\"י). ה\"יוחסין\" כתב שהיה תלמידו של רבא."},{"i":590,"n":"אלישיב","l":"א","b":"אמורא שאין לקבוע זמנו ומקומו. מובא בבבלי (מו\"ק כ\"ה ע\"ב). שם מוזכר כי כל עוד שהיה חי, לא היו בזכותו גנבים במקום מגוריו."},{"i":591,"n":"אלישע בן אבויה","l":"א","b":"תנא בדור השלישי, שיצא לתרבות רעה ומשום כך כינוהו \"אחר\". היה חברם של רבי עקיבא ובן עזאי ובן זומא: ארבעתם \"נכנסו לפרדס\", (ופירש רש\"י: \"עלו לרקיע ע\"י שם\"), בן עזאי הציץ ומת, בן זומא הציץ ונפגע, \"אחר\" קיצץ בנטיעות ורבי עקיבא יצא בשלום (חגיגה י\"ד ע\"ב). שמו מוזכר במשנה (אבות פ\"ד מ\"כ). היה רבו של רבי מאיר, שלמד ממנו גם לאחר שיצא לתרבות רעה, ואמרו: רבי מאיר רימון מצא, תוכו אכל קליפתו זרק (חגיגה ט\"ו ע\"ב). מת אחרי רבי עקיבא, והותיר אחריו בת שבאה לפני רבי וביקשתו שיפרנסנה (שם)."},{"i":592,"n":"אלישע בעל כנפים","l":"א","b":"ה\"יוחסין\" כתב שנראה שהיה בתקופת התנאים. מובא בבבלי: \"פעם גזרה המלכות שכל המניח תפילין ינקרו את מוחו והיה אלישע מניחם, ראהו ממונה ורץ אחריו ונטל אלישע תפילין מראשו ואחזן בידו ונהפכו לכנפי יונה\" (שבת מ\"ט ע\"א)."},{"i":593,"n":"ר\u0027 אלכסא","l":"א","b":"אמורא ארץ ישראלי בדור השני. מובא בירושלמי (כתובות פ\"ה ה\"א). תלמידו של חזקיהו, (בנו של ר\u0027 חייא ורבו של ר\u0027 יעקב בר אחא) (שם)."},{"i":594,"n":"אלכסנדר","l":"א","b":"מובא בירושלמי (ב\"ב פ\"ט ה\"ג) יחד עם שני אחיו החכמים: ר\u0027 שמואל בר סוסרטיי ור\u0027 הוריינא אחוי דר\u0027 שמואל. נראה, שהוא עצמו לא היה חכם."},{"i":595,"n":"ר\u0027 אלכסנדר","l":"א","b":"מובא בירושלמי (מעשרות פ\"ה ה\"ה). ע\"ע רבי אלכסנדרי."},{"i":596,"n":"ר\u0027 אלכסנדרא","l":"א","b":"מובא (ירו\u0027, מע\"ש פ\"ה ה\"ה), והוא ר\u0027 אלכסנדר."},{"i":597,"n":"רבי אלכסנדרי","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יהושע בן לוי (ברכות נ\"ט ע\"א). כן קיבל מרבי יוחנן (ב\"ר פע\"א - ז\u0027). משמו מסרו חכמי הדרום (ב\"ר ס\"ג - ח\u0027) ורבי אחא (מדרש תהלים פק\"ב - ג\u0027). מסופר שהלך והכריז מי מבקש חיים, וכשנתקבצו אליו אנשים אמר להם: \"מי האיש החפץ חיים וכו\u0027 נצור לשונך מרע וכו\u0027\" (ע\"ז י\"ט ע\"ב)."},{"i":598,"n":"ר\u0027 אלכסנדרי בר הדרין","l":"א","b":"מובא בשהש\"ר (פ\"ה - י\"א), ונראה אולי שצ\"ל: ר\u0027 אלכסנדרי בר חגאי."},{"i":599,"n":"ר\u0027 אלכסנדרי בר חגאי","l":"א","b":"אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מאמרו בשם ר\u0027 אלכסנדרי קרובה (ויק\"ר פי\"ט - ב\u0027): \"אם מתכנסין כל באי עולם להלבין כנף אחד של עורב אין יכולין, כך אם מתכנשין כל באי העולם לעקור דבר אחד מן התורה אין יכולין\"."},{"i":600,"n":"ר\u0027 אלכסנדרי בר חגרי","l":"א","b":"כך גירסת ה\"יוחסין\". הגירסא לפנינו: ר\u0027 אלכסנדרי בר חגאי. (ע\"ע)."},{"i":601,"n":"ר\u0027 אלכסנדרי קרובה","l":"א","b":"מובא בויק\"ר (פי\"ט - ב\u0027). ע\"ע ר\u0027 אלכסנדרי בר חגאי."},{"i":602,"n":"ר\u0027 אלכסנדריא דצדוקא","l":"א","b":"אמורא ארץ ישראלי בדור השני. מובא בירושלמי (דמאי פ\"ב ה\"א). רבי זירא שאל ממנו (שם)."},{"i":603,"n":"ר\u0027 אלעא הזקן","l":"א","b":"מובא בבבלי ומאמרו (שם): \"אם רואה אדם שיצרו מתגבר עליו ילך למקום שאין מכירין אותו וילבש שחורים וכו\u0027\" (חגיגה ט\"ז ע\"א). ע\"ע ר\u0027 אלעאי הזקן."},{"i":604,"n":"רבי אלעאי (2)","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. שמו שובש ב - 02 צורות כתיב שונות. רש\"י פירש (בכורות מ\"ב ע\"ב): \"רבי אלעאי אמורא הוא, ולאו היינו האי דברייתא דאיירי לעיל משום רבי ישמעאל\". נראה, שמושבו היה בצור (ירו\u0027, שביעית פ\"ב ה\"ד), ובא מבבל ושם עוד קיבל מרב (שבת קמ\"ב ע\"א). כן מסר בשם שמואל (ירו\u0027, פסחים פ\"ט ה\"ו). חברו המובהק היה רב ברונא (תלמידו דרב), כדמצינו (ברכות ט\u0027 ע\"ב). בארץ ישראל קיבל עוד מרבי חנינא (עירובין כ\"ח ע\"ב), ומסר בשם רבי ינאי (ירו\u0027, עירובין פ\"ו ה\"ט), ר\u0027 יוחנן (עירובין פ\"א ע\"ב) ור\"ל (ירו\u0027, שבת פ\"ח ה\"ו). בארץ ישראל היה חברו ובר פלוגתיה דרבי זירא (ב\"ב נ\"ט ע\"א). בין תלמידיו: רבי יונה (ירו\u0027, תרומות פ\"ב ה\"ד) ורבי יוסי (שם), שהיו מראשי הדור הרביעי - החמישי."},{"i":605,"n":"ר\u0027 אלעאי בן אלעזר","l":"א","b":"מובא (שבת ס\u0027 ע\"א) מקודם מובאים דברי שמואל ואח\"כ דבריו אך אין ראיה מזה מי קדם למי כי יתכן שזה ממסדר הש\"ס."},{"i":606,"n":"ר\u0027 אלעאי בר ברכיה","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (סנהדרין ק\"ד ע\"ב - לפי גירסת \"דק\"ס\"). מאמרו: \"שני תלמידי חכמים שהיו הולכים בדרך ואין ביניהן דברי תורה ראויין לישרף\" (תענית י\u0027 ע\"ב)."},{"i":607,"n":"ר\u0027 אלעאי בר מנחם","l":"א","b":"מובא בויק\"ר (פ\"א - י\"ג)."},{"i":608,"n":"ר\u0027 אלעאי בר שמעיה","l":"א","b":"מובא בויק\"ר (פ\"י - ה\u0027)."},{"i":609,"n":"ר\u0027 אלעאי הזקן","l":"א","b":"מובא (מו\"ק ט\"ז ע\"א) ייתכן שהוא אביו של רבי יהודה התנא. נראה, שהוא רבי אלעא. (ע\"ע ר\u0027 אלעא הזקן)."},{"i":610,"n":"אלעזר (2)","l":"א","b":"היה ממונה על הפרוכת בבית המקדש. מובא במשנה (שקלים פ\"ה מ\"א)."},{"i":611,"n":"רבי אלעזר","l":"א","b":"יש תנא בשם רבי אלעזר (בן שמוע), ויש אמורא בשם רבי אלעזר (בן פדת)."},{"i":612,"n":"אלעזר איש בירתא","l":"א","b":"מובא בבבלי (תענית כ\"ד ע\"א). לפי גירסת \"דק\"ס\" הוא אלעזר בן יהודה איש ברתותא."},{"i":613,"n":"ר\u0027 אלעזר איש ברתות","l":"א","b":"מובא באבות (פ\"ג מ\"ז), והוא רבי אלעזר בן יהודה איש ברתותא."},{"i":614,"n":"ר\u0027 אלעזר בוצראה","l":"א","b":"אמורא ארץ ישראלי. מובא באיכ\"ר (פ\"ד - פ\"ג). הוא ור\u0027 תנחום (שחי בדור החמישי) אמרו בשם ר\u0027 אחא (שם)."},{"i":615,"n":"ר\u0027 אלעזר בי ר\"ש","l":"א","b":"מובא בירושלמי (עירובין פ\"ח ה\"ג). אין לדעת משמעות ראשי התיבות: שמואל או שמעון. אמר בשם ר\u0027 אושעיא (שם)."},{"i":616,"n":"אלעזר בן אהווי","l":"א","b":"מובא בספרא (ויקרא ספ\"ב), ואולי הוא ר\u0027 אלעזר בן מהבאי."},{"i":617,"n":"אלעזר בן אחוי","l":"א","b":"מובא בב\"ר (פצ\"ח - ג\u0027)."},{"i":618,"n":"רבי אלעזר בן אחוי","l":"א","b":"מובא בספרא (ויקרא סוף פ\"א). צ\"ל: ר\"א בן מהבאי."},{"i":619,"n":"ר\u0027 אלעזר בן אנטיגנוס","l":"א","b":"אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של רבי אלעזר ב\"ר ינאי (גיטין ל\"א ע\"א). רבי זירא היה תלמידו (ירו\u0027, ברכות פ\"ה ה\"ב)."},{"i":620,"n":"רבי אלעזר בן דגלאי","l":"א","b":"תנא שחי בזמן הבית (תמיד פ\"ג - דף ל\u0027 ע\"ב)."},{"i":621,"n":"רבי אלעזר בן דורדיא","l":"א","b":"אף שמכונה רבי, אינו תנא. חי בתקופת התנאים, ככל הנראה בזמנו של רבי או אף לפניו. היה בעל תשובה גדול ומת בתשובתו ויצאה בת קול ואמרה: \"רבי אלעזר בן דורדיא מזומן לחיי העולם הבא\". בכה רבי ואמר: \u0027יש קונה עולמו בכמה שנים ויש קונה עולמו בשעה אחת\u0027. ואמר רבי: \"לא דיין לבעלי תשובה שמקבלין אותן אלא שקורין אותן רבי\" (ע\"ז י\"ז ע\"א)."},{"i":622,"n":"רבי אלעזר בן דלגוי","l":"א","b":"מובא בירושלמי (סוכה פ\"ה ה\"ג), והוא אלעזר בן דגלאי."},{"i":623,"n":"אלעזר בן דמא","l":"א","b":"תנא בדור השלישי - הרביעי. שאל מרבי ישמעאל דודו \"כגון אני שלמדתי כל התורה כולה מהו ללמוד חכמת היונית\" (מנחות צ\"ט ע\"ב). מת מנשיכת נחש וקרא עליו רבי ישמעאל \"אשריך בן דמא שגופך טהור ויצאה נשמתך בטהרה\" (ע\"ז כ\"ז ע\"ב)."},{"i":624,"n":"רבי אלעזר בן הקפר","l":"א","b":"ע\"ע רבי אלעזר הקפר."},{"i":625,"n":"רבי אלעזר בן זמרא","l":"א","b":"מובא בב\"ר (ספל\"ט). \"סה\"ד\" כתב: \"ואולי צ\"ל: בשם רבי יוסי בן זמרי\"."},{"i":626,"n":"ר\u0027 אלעזר בן חגייא","l":"א","b":"אמורא ארץ ישראלי בדור הששי. תלמידו של רבי מנא ב\u0027 (ירו\u0027, שקלים פ\"ז ה\"ב)."},{"i":627,"n":"אלעזר בן חנך","l":"א","b":"מובא בבבלי (ברכות י\"ט ע\"א), והוא אליעזר בן חנוך."},{"i":628,"n":"אלעזר בן חנניה בן חזקיה בן גרון","l":"א","b":"תנא קדמון שחי בזמן הבית. הוא וסיעתו כתבו את מגלת תענית (מגילת תענית פי\"ב). פעם אבד לו ספר תורה שנקנה במאה מנה ועלה והקיף את הר הבית ולא זז משם עד שמצאו אותו (שמחות פ\"ו)."},{"i":629,"n":"רבי אלעזר בן חסמא","l":"א","b":"מובא בבבלי (גיטין ס\"ב ע\"א), וצ\"ל: רבי אלעזר חסמא, חסמא אינו שם אביו."},{"i":630,"n":"ר\u0027 אלעזר בן חרסום","l":"א","b":"כהן גדול ששימש אחת עשרה שנה בכהונה גדולה (יומא ט\u0027 ע\"א). היה עשיר גדול ושימש כדוגמא לעשירות (קידושין מ\"ט ע\"א) וישב ועסק בתורה \"כל היום וכל הלילה\" (יומא ל\"ה ע\"ב), ועליו אמרו (שם): \"רבי אלעזר בן חרסום מחייב את העשירים\" (שלא יהיה להם פתחון מדוע לא למדו תורה)."},{"i":631,"n":"רבי אלעזר בן יהודה","l":"א","b":"מובא במשנה (זבים רפ\"א), והוא רבי אלעזר בן יהודה איש ברתותא (כדמוכח בתוספתא שם)."},{"i":632,"n":"אלעזר בן יהודה איש אבלים","l":"א","b":"תנא בדור החמישי. מסר בשם רבי יעקב [בן קורשאי] (זבחים כ\"ח ע\"א). שם מקומו נשתבש בכמה אופנים."},{"i":633,"n":"אלעזר בן יהודה איש איבלייס","l":"א","b":"מובא בתוספתא (מע\"ש פ\"א), והוא אלעזר בן יהודה איש אבלים."},{"i":634,"n":"רבי אלעזר בן יהודה איש ברתותא","l":"א","b":"תנא בדור השלישי. תלמידו של רבי יהושע (משנה טבול יום פ\"ג מ\"ד) וחברו של ר\"ע (שם). רבי שמעון בן יוחאי מסר בשמו (תוספתא זבים פ\"א ה\"ה). נתן לצדקה כל מה שהיה בידו וגבאי צדקה ברחו ממנו (תענית כ\"ד ע\"א)."},{"i":635,"n":"אלעזר בן יהודה איש כפר אובלון","l":"א","b":"מובא בתוספתא (סוף נדה), והוא אלעזר בן יהודה איש אבלים."},{"i":636,"n":"רבי אלעזר בן יצחק איש כפר דרום","l":"א","b":"תנא. נראה, שחי בדור השלישי. חלק עם אבא יוסי בן חנן ועם רבי ישמעאל שנזכר אחריו (סוטה כ\u0027 ע\"ב)."},{"i":637,"n":"ר\u0027 אלעזר בן ירמיה","l":"א","b":"תנא שאין לקבוע את זמנו המדוייק. מובא בבבלי (סוטה ד\u0027 ע\"א). ב\"אגרת רב שרירא גאון\" נאמר שהיה בדורו של רשב\"ג."},{"i":638,"n":"ר\u0027 אלעזר בן מהבאי","l":"א","b":"תנא שאין לקבוע זמנו המדוייק. מובא בבבלי (שבת ק\"ו ע\"ב)."},{"i":639,"n":"רבי אלעזר בן מתיא","l":"א","b":"תנא בדור השלישי - הרביעי. קיבל מר\"ע (תוספתא ברכות פ\"ד). מחכמי יבנה שהיו בקיאים בשבעים לשון (ירו\u0027, שקלים פ\"ח ה\"א). חבריו היו: שמעון בן עזאי, שמעון התימני וחנינא בן חכינאי (תוספתא ברכות שם). \"יוחסין\" סובר שהוא בנו של מתיא בן חרש."},{"i":640,"n":"רבי אלעזר בן עזריה","l":"א","b":"תנא בדור השלישי. נתמנה זמנית לנשיא במקום רבן גמליאל (ברכות כ\"ז ע\"ב), לפי הבבלי (שם) בגיל שמונה עשרה, ולפי הירושלמי (ברכות פ\"ד ה\"א) בגיל שש עשרה. תלמידו של רבי יוסי הגלילי (ירו\u0027, כתובות פי\"א ה\"ג). הרמב\"ם, בהקדמתו לזרעים, שייך את ר\"א בן עזריה לדור השני, ואת ר\u0027 יוסי הגלילי לדור השלישי. היה חבר מובהק לר\"ע (סנהדרין ל\"ח ע\"ב), וכן חברם של ר\u0027 ישמעאל, ר\"ט ור\u0027 יהושע (ידים פ\"ד מ\"ג, ובהגדה של פסח). ר\u0027 מתיא בן חרש שאל ממנו (יומא פ\"ו ע\"א). ר\"א ב\"ר שמעון אמר משמו (תנחומא ויגש - ז\u0027). היה דור עשירי לעזרא (יבמות ט\"ז ע\"א). כהן ועשיר מופלג (שבת נ\"ד ע\"ב). עשירותו שימשה כמשל בפי החכמים (קידושין מ\"ט ע\"ב). רבי יהושע אמר עליו: \"אין דור יתום שר\"א בן עזריה שרוי בתוכו\" (חגיגה ג\u0027 ע\"ב). בפרשנות המקרא קבע כלל \"דברה תורה כלשון בני אדם\" (קידושין י\"ז ע\"ב). אמרו עליו: \"משמת ר\"א בן עזריה בטלו עטרות חכמה\" (סוף סוטה)."},{"i":641,"n":"רבי אלעזר בן ערך","l":"א","b":"תנא בדור השני. מגדולי תלמידיו של ר\u0027 יוחנן בן זכאי, שאמר עליו שהוא \"כמעין המתגבר ושקול כנגד כל חכמי ישראל\" (אבות פ\"ב מ\"ח). לבסוף הלך בעצת אשתו לדיומסית מקום רחצה ויין, ונעקר תלמודו ושכחו. חבריו בקשו רחמים ותלמודו חזר אליו (שבת קמ\"ז ע\"ב - אבות דר\"נ ספי\"ד). חבריו היו: ר\u0027 אליעזר בן הורקנוס, יהושע בן חנניה, יוסי החסיד ור\u0027 שמעון בן נתנאל. דרש במעשה מרכבה וירדה אש מן השמים. עמד ר\u0027 יוחנן בן זכאי ונשקו על ראשו (חגיגה י\"ד ע\"ב)."},{"i":642,"n":"רבי אלעזר בן פדת","l":"א","b":"אמורא בדור השני. והוא ר\u0027 אלעזר סתם בגמרא (שבת י\"ט ע\"ב ברש\"י). בבבל שימש את רב ושמואל (חולין קי\"א ע\"ב). עלה לארץ ישראל בעודו צעיר ועדיין לא היה נשוי (ברכות ט\"ז ע\"א). רבו המובהק היה רבי יוחנן (יומא נ\"ג ע\"א). ואח\"כ הפך להיות לרבי יוחנן תלמיד - חבר (ירו\u0027, סנהדרין פ\"א ה\"א). היה תלמידם של רבי חנינא בר חמא (ברכות כ\u0027 ע\"ב) ושל רבי אושעיא (שם ל\"ב ע\"ב). נקרא \"מרא דארעא דישראל\" (נדה כ\u0027 ע\"ב). בכל מקום שאמרו \"שלחו מתם\" הוא ר\"א (סנהדרין י\"ז ע\"ב). היה עני מרוד (תענית כ\"ה ע\"א). מילא מקומו של ר\u0027 יוחנן כראש ישיבה (ירו\u0027, מגילה פ\"א הי\"א). נפטר באותה שנה שנפטר ר\u0027 יוחנן (\"אגרת רב שרירא גאון\")."},{"i":643,"n":"רבי אלעזר בן פנחס","l":"א","b":"תנא. נראה שבדור הרביעי. נזכר במחלוקת לאחר ר\"א, ר\u0027 יהושע בן עזאי, ר\"ע וריב\"ב. (ירו\u0027, סוטה פ\"א ה\"ב). מסר בשם ר\u0027 יהודה בן בתירא (יומא י\"ח ע\"א)."},{"i":644,"n":"ר\u0027 אלעזר בן פרטא","l":"א","b":"תנא בדור השלישי - הרביעי. מושבו היה בציפורי (במד\"ר פכ\"ג - א\u0027). מסר בשם רבי אלעזר המודעי (סנהדרין כ\"ב ע\"ב). חברו של רבי חנינא בן תרדיון (ע\"ז י\"ז ע\"ב). בברייתא מוזכר יחד עם רבי ישמעאל ורבי עקיבא (יומא ע\"ה ע\"ב). בזמן גזירת השמד נתפס על לימוד תורה וניצל (ע\"ז שם)."},{"i":645,"n":"רבי אלעזר בן צדוק","l":"א","b":"תנא בדור הרביעי - החמישי. כנראה נכדו של ר\"א בן צדוק הראשון. קיבל מר\"מ (כלאים פ\"ז מ\"ב) חברם של תלמידי ר\"ע: חלק עם רבי יהודה (כלים ספכ\"ו) ועם רבי יוסי (שם פ\"ב מ\"ו). התרועע עם רבי יהודה הנשיא (תוספתא סוכה פ\"ב ב\u0027). אביו של רב מספר שעמד לפני ר\"א בן צדוק (סוכה מ\"ד ע\"ב), וכנראה שהכוונה אליו."},{"i":646,"n":"רבי אלעזר בן שמוע","l":"א","b":"תנא בדור הרביעי, והוא סתם ר\u0027 אלעזר במשנה או ברייתא (שבת י\"ט ע\"ב ברש\"י). מתלמידיו האחרונים של רבי עקיבא (יבמות ס\"ב ע\"ב). נסמך על ידי רבי יהודה בן בבא (סנהדרין י\"ד ע\"א). חברו של רבי יוחנן הסנדלר (ספרי ראה פיסקא פ\u0027). נשא ונתן עם רבי מאיר (תוספתא נזיר פ\"ה א\u0027), ועם רבי יהודה (ירו\u0027, נזיר פ\"ו ה\"ז). רבי היה מתלמידיו (יומא ע\"ט ע\"ב). ר\u0027 יוחנן אמר עליו שלבו היה רחב כפתחו של היכל (עירובין נ\"ג ע\"א). האריך ימים ותלמידיו שאלו אותו \"במה הארכת ימים\" (סוטה ל\"ט ע\"א)."},{"i":647,"n":"רבי אלעזר בן תדאי","l":"א","b":"תנא בדור הרביעי. רב שרירא גאון כותב באיגרתו, שהיה בדורו של רשב\"ג. מובא בבבלי (שבת קכ\"ג ע\"א)."},{"i":648,"n":"רבי אלעזר בן תרדיון","l":"א","b":"תנא. חי בדור חכמי יבנה (\"אגרת רב שרירא גאון\"). מובא בירושלמי (גיטין פ\"ז ה\"ד)."},{"i":649,"n":"רבי אלעזר בנו של רבי אלעזר הקפר","l":"א","b":"מובא בירושלמי: \"זה אחד מד\u0027 דברים שהיה ר\u0027 חייא הגדול אומר שאין להם תשובה והשיב ר\u0027 אלעזר בנו של ר\u0027 אלעזר הקפר\" (ביצה פ\"א ה\"ג), ובבלי: \"השיב ר\u0027 אלעזר הקפר בריבי תשובה\" (חולין פ\"ד ע\"ב). יש סבורים, שבר קפרא הוא ר\u0027 אלעזר זה, והיה בנו של ר\u0027 אלעזר הקפר."},{"i":650,"n":"רבי אלעזר בנו של רבי יוסי הגלילי","l":"א","b":"תנא בדור הרביעי. בנו של התנא ר\u0027 יוסי הגלילי. רבי יוחנן אמר: \"כל מקום שאתה מוצא דבריו של ר\"א בנו של ר\u0027 יוסי הגלילי בהגדה עשה אזנך כאפרכסת\" (חולין פ\"ט ע\"א). מיוחסת לו ברייתא \"דל\"ב מדות שהאגדה נדרשת בהן\" (יצא לאור ניו יורק, תרצ\"ד). רבנו שמשון מקינון בספר \"כריתות\" היה הראשון שהזכיר זאת."},{"i":651,"n":"ר\u0027 אלעזר בר אבין","l":"א","b":"מובא בש\"ר (פמ\"ז - ה\u0027), ואולי צ\"ל ר\u0027 אלעזר ור\u0027 אבין כמובא בב\"ר (פמ\"ח - י\"ד)."},{"i":652,"n":"ר\u0027 אלעזר בר אבינא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. ר\u0027 יודן (כצ\"ל) מסר בשמו (ב\"ר פצ\"ח - ב\u0027). מאמרו: \"אין פורענות באה לעולם אלא בשביל ישראל\" (יבמות ס\"ג ע\"א)."},{"i":653,"n":"רבי אלעזר בר אושעיא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. חלק עם ר\u0027 יצחק בר אלעזר (ירו\u0027, ברכות פ\"ה ה\"ב)."},{"i":654,"n":"רבי אלעזר בר ביסנא","l":"א","b":"אמורא ארץ ישראלי. אמר בשם רבי אחא, שחי בדור הרביעי (ב\"ר פי\"ח - א\u0027)."},{"i":655,"n":"ר\u0027 אלעזר בר ברכיה","l":"א","b":"מובא בבבלי (סנהדרין צ\"ד ע\"ב)."},{"i":656,"n":"ר\u0027 אלעזר בר חנינא","l":"א","b":"מובא בירושלמי (כתובות פ\"ז ה\"ז). יש שסבורים שצ\"ל: ר\"א בשם ר\u0027 חנינא."},{"i":657,"n":"רבי אלעזר בר יוסי","l":"א","b":"תנא בדור החמישי. בנו של התנא רבי יוסי בן חלפתא. כבר בחיי אביו היה גדול בתורה, ואביו מספר \"אלעזר בני אומר וכו\u0027 ונראין דבריו מדבריהם\" (פסחים קי\"ז ע\"א). הלך לרומי עם רבי שמעון בן יוחאי לבטל גזרה, ושם ראה את הפרוכת שלקח טיטוס הרשע מבית המקדש, והיו עליה כמה טיפות דמים מפר השעיר של יום הכיפורים שהוזו עליה. (מעילה י\"ז ע\"ב). ניצח את הכותים בויכוחים (סוטה ל\"ג ע\"ב)."},{"i":658,"n":"רבי אלעזר בר יוסף","l":"א","b":"הוא רבי אלעזר בר יוסי. מובא בירושלמי (ברכות ספ\"ז). מסר בשם רב (שם)."},{"i":659,"n":"רבי אלעזר בר ינאי","l":"א","b":"תנא בדורו של רבי. \"יוחסין\" כתב עליו: \"בזמן רבי יוחנן ואם כן אינו תנא\" והשיג עליו \"סה\"ד\" וכתב: \"לא ידעתי מי הגיד לו נבואה זו\". מסר בשם רבי אלעזר חסמא לפני רבי (תוספתא זבים פ\"א). רבי אלעזר בן אנטיגנוס מסר בשמו (גיטין ל\"א ע\"א)."},{"i":660,"n":"ר\u0027 אלעזר בר ישמעאל","l":"א","b":"מובא בירושלמי (תרומות פי\"א ה\"ב). ו\"סה\"ד\" כתב: \"טעות הוא וצ\"ל ר\"א כר\u0027 ישמעאל\"."},{"i":661,"n":"רבי אלעזר בר מלאי","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. אמר בשם ר\"ל (שבת קל\"ט ע\"א)."},{"i":662,"n":"רבי אלעזר בר מנחם","l":"א","b":"אמורא ארץ ישראלי בדור השלישי, בזמנו של רבי אבהו (ב\"ר ספכ\"ג). היה מבעלי האגדה."},{"i":663,"n":"ר\u0027 אלעזר בר מניומי","l":"א","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (חולין י\"ט ע\"ב). ור\"נ אמר \"לאו היינו דר\"א בר מניומי דאמר\"."},{"i":664,"n":"רבי אלעזר בר מרון","l":"א","b":"מובא בשהש\"ר (רפ\"ז), ונראה שהוא ר\"א בר מרים."},{"i":665,"n":"רבי אלעזר בר מרים","l":"א","b":"אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של רבי יונה (ירו\u0027, תענית פ\"ד ה\"ג)."},{"i":666,"n":"ר\u0027 אלעזר בר מרינוס","l":"א","b":"מובא באיכ\"ר (ספ\"ב)."},{"i":667,"n":"ר\u0027 אלעזר בר סימון","l":"א","b":"מובא (ב\"ר פ\"כ) ר\u0027 יוחנן בשמו, ויתכן שיש שם איזה שיבוש, ולא ידעתי מהו."},{"i":668,"n":"רבי אלעזר בר צדוק","l":"א","b":"תנא בדור השני - השלישי. בנו של רבי צדוק שסופר עליו שצם ארבעים שנה כדי שלא תחרב ירושלים (גיטין נ\"ו ע\"א). ראה את הבית ומתאר כמה ממנהגיהם של אנשי ירושלים לפני החורבן (סוכה מ\"א ע\"ב). כן סיפר שבזמן החורבן ראה את בת נקדימון בן גוריון מלקטת שעורים מבין טלפי סוסים (כתובות ס\"ז ע\"א). תלמידו של רבי יוחנן בן החורני (יבמות ט\"ו ע\"ב)."},{"i":669,"n":"רבי אלעזר בר שמעון","l":"א","b":"תנא בדור החמישי. בנו ותלמידו של התנא רבי שמעון בן יוחאי (ירו\u0027, שבת פ\"י ה\"ה) לאחר פטירת אביו למד יחד עם חברו רבי, אצל רבן שמעון בן גמליאל ורבי יהושע בן קרחה (ב\"מ פ\"ד ע\"ב). היה גדול מרבי (ירו\u0027, שבת פ\"י ה\"ה). ישב עם אביו 31 שנה במערה (שבת ל\"ג ע\"ב)."},{"i":670,"n":"ר\u0027 אלעזר בר\u0027 יוסי בן זמרא","l":"א","b":"מובא בויק\"ר (פכ\"ז - ה\u0027). יש גורסים: ר\"א בשם ר\u0027 יוסי בן זמרא."},{"i":671,"n":"ר\u0027 אלעזר בר\u0027 יצחק","l":"א","b":"מובא בבבלי (סוכה מ\"ד ע\"ב) לפי גירסת \"דק\"ס\" וה\"יוחסין\" שם. וכן מובא במקום אחר (הוריות י\"ג ע\"ב). אבל \"סה\"ד\" כתב שהוא ט\"ס וצ\"ל: ר\"א בר צדוק."},{"i":672,"n":"ר\u0027 אלעזר בר\u0027 סימאי","l":"א","b":"מובא בקה\"ר (פי\"א - א\u0027). נראה שצ\"ל: ר\"א בשם ר\u0027 סימאי, וכן כתב \"סה\"ד\" שהוא ט\"ס."},{"i":673,"n":"ר\u0027 אלעזר דמן ננוה","l":"א","b":"אמורא בדור השני - השלישי. רבה בר רב הונא ספר, שראהו הולך בתענית ציבור בסנדלי שעם (יומא ע\"ח ע\"ב)."},{"i":674,"n":"רבי אלעזר דמן רומא","l":"א","b":"אמורא בדור הראשון. רבי יוחנן מסר ממנו הלכה (גיטין ס\"ז ע\"ב)."},{"i":675,"n":"רבי אלעזר דרומה","l":"א","b":"אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי יוסי חברו של ר\u0027 יונה (ירו\u0027, פאה פ\"ח ה\"ב)."},{"i":676,"n":"רבי אלעזר דרומייא","l":"א","b":"מובא בירושלמי (חגיגה פ\"ג ה\"ב), והוא ר\"א דרומה."},{"i":677,"n":"רבי אלעזר המודעי","l":"א","b":"תנא בדור השני - השלישי. תלמידו של רבן יוחנן בן זכאי (ב\"ב י\u0027 ע\"ב). ישב עם ר\u0027 ישמעאל ורבי טרפון, וקרא לר\"ט \"רבי\" (יומא ע\"ו ע\"א). חברם של ר\"א, ר\u0027 יהושע ור\"ג (ב\"ב שם). רבן גמליאל אמר עליו: \"עדיין אנו צריכים למודעי\" (שם)."},{"i":678,"n":"ר\u0027 אלעזר הקליר","l":"א","b":"תנא. והוא רבי אלעזר ברבי שמעון [בן יוחאי] על פי דעה שמביא תוספות (חגיגה י\"ג ע\"א בד\"ה: ורגלי)."},{"i":679,"n":"רבי אלעזר הקפר","l":"א","b":"תנא בדור החמישי. מושבו היה בלוד (תוספתא אהלות פי\"ח ח\u0027). חברם של רבי ור\u0027 ישמעאל בר יוסי, והיה ר\u0027 פנחס בן יאיר יושב לפניהם (שם). רבי יהושע בן לוי היה תלמידו (ע\"ז מ\"ג ע\"א). בנו, רבי אלעזר, מוזכר בירושלמי (ביצה פ\"א ה\"ג). יש אומרים שהוא רבי אלעזר בן קפרא. במסכת חולין (פ\"ד ע\"ב) \"אמר ר\u0027 אבא: \u0027זה אחד מן הדברים שאמר ר\u0027 חייא אין לי עליהם תשובה והשיב ר\"א הקפר תשובה\u0027\". מאמרו המפורסם: \"הקנאה והתאוה והכבוד מוציאים את האדם מן העולם\" (אבות פ\"ד)."},{"i":680,"n":"רבי אלעזר הקפר בריבי","l":"א","b":"מובא בבבלי (ע\"ז מ\"ג ע\"א), והוא רבי אלעזר הקפר, ופרש\"י ד\"ה בריבי: \"כלומר, אדם גדול, וכן קורין לו בכינוי\"."},{"i":681,"n":"אלעזר זעירא","l":"א","b":"אמורא בבלי בדור הראשון. בהיותו בנהרדעא נעל נעליים שחורות כסימן אבל על חורבן ירושלים, ואנשי ראש הגולה חשבוהו כבעל גאוה וחבשוהו בכלא. ולאחר שנוכחו שהוא אדם גדול - שחררוהו (ב\"ק נ\"ט ע\"ב)."},{"i":682,"n":"רבי אלעזר חסמא","l":"א","b":"תנא בדור השלישי. מחכמי יבנה. תלמידו המובהק של רבי יהושע (תוספתא זבחים פ\"ד ד\u0027). הלך להקביל פניו (חגיגה ג\u0027 ע\"א). הלך עמו ושאל ממנו (נגעים פ\"ז מ\"ב). והנימוק שקראו לו ר\"א חסמא מובא (ויק\"ר פכ\"ג ד\u0027), וחסמא אינו שם."},{"i":683,"n":"ר\u0027 אלעזר חרסנה","l":"א","b":"מובא באיכ\"ר (פ\"ב - ד\u0027). היה מהרוגי מלכות (שם)."},{"i":684,"n":"רב אלעזר מהגרוניא","l":"א","b":"אמוראי בבלי בדור הרביעי - החמישי. תלמידו של רבא (תענית כ\"ד ע\"ב). חברו של רב אחא בר תחליפא, ושניהם ביקרו אצל רב אחא בריה דרב איקא."},{"i":685,"n":"אלעזר ספרא","l":"א","b":"תנא בדור השלישי. חברו של רבי יוחנן בן גודגדא (חולין נ\"ה ע\"ב)."},{"i":686,"n":"ר\u0027 אלעשא","l":"א","b":"אמורא ארץ ישראלי. מובא בויק\"ר (פ\"ד - ו\u0027)."},{"i":687,"n":"אמוראי דנהרדעא","l":"א","b":"מובא בבבלי (סנהדרין י\"ז ע\"ב) \"אמוראי דנהרדעא רב חמא\" (וע\"ע נהרדעי)."},{"i":688,"n":"אמי","l":"א","b":"אמורא בבלי בדור השלישי - הרביעי. \"ואמי [בלי \"רבי\"] שם חכם\" וכן כתבו תוספות (זבחים נ\u0027 ע\"א ד\"ה: אמר). ור\u0027 יוסף אמר: \"היינו דשמענא לאמי וכו\u0027 ולא ידענא מאי ניהו\" (יבמות פ\u0027 ע\"א). רבא אמר: \"אמר לי אמי\" (כתובות מ\"ח ע\"ב). עלה לא\"י (ירו\u0027, תרומות רפ\"ז). נראה שהוא חתנו של ר\u0027 יונה (מראשי דור החמישי בא\"י) כמובא בירושלמי (גיטין פ\"ב ה\"א)."},{"i":689,"n":"רבי אמי","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. שם אביו נתן (גיטין מ\"ד ע\"א). היה בבבל (מו\"ק כ\"ה ע\"א) ויתכן לומר ששם היה מתלמידיו הקטנים של ר\"ה (שם). וגם כשהיו הוא וחברו רבי אסי \"כהני חשיבי דארעא ישראל\", היו כפופים לרב הונא (מגילה כ\"ב ע\"א). מסר בשם רב (נדרים מ\u0027 ע\"ב). בארץ ישראל היה תלמידו המובהק של רבי יוחנן (חולין קי\"א ע\"ב), וכן קיבל עוד מר\u0027 אושעיא (ירו\u0027, שבת פ\"ג ה\"א). חברו המובהק היה רבי אסי ונסמכו יחד ונזכרים תדיר יחד (כתובות י\"ז ע\"א), ועליהם אמרו: \"דייני דארץ ישראל רבי אמי ורבי אסי\" (סנהדרין י\"ז ע\"ב). ואח\"כ היה ראש הדור, כדמצינו: \"מיני אמי בר נתן תצא תורה לכל ישראל\" (גיטין מ\"ד ע\"א). עמד בראש ישיבת טבריה אחרי פטירת רבי יוחנן (\"אגרת רב שרירא גאון\"). בין תלמידיו היו ר\"ז (חולין פ\"ו ע\"ב). וגם רב חסדא אמר: \"הא מילתא מגברא רבה שמיע לי ומנו רבי אמי\" (יבמות כ\"א ע\"ב). האריך ימים עד ימי רבא ששלח לשאול ממנו (גיטין ס\"ג ע\"ב)."},{"i":690,"n":"רבי אמי אבוה דרבי אבדימא דציפורן","l":"א","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. רבי יצחק בר אלעזר אמר בשמו (ירו\u0027, ביצה פ\"א ה\"ט). בנו היה האמורא רבי אבדימי דציפורן, תלמידו של רבינא."},{"i":691,"n":"אמי אבוה דשמואל בר אמי","l":"א","b":"אמורא בדור השני - השלישי. אביו של האמורא הארץ ישראלי רבי שמואל בר אמי (ירו\u0027, יבמות פ\"י ה\"ו). אמר בשם רב יהודה (שם)."},{"i":692,"n":"רבי אמי אסי","l":"א","b":"אמורא ארץ ישראלי בדור הרביעי, ששמו אמי אסי, נראה שהיה תלמיד ר\u0027 ירמיה (ירו\u0027, ברכות פ\"ב ה\"ג)."},{"i":693,"n":"רב אמי בבליא","l":"א","b":"מובא בירושלמי (גיטין פ\"ב ה\"א) והוא ר\u0027 אמי סתם."},{"i":694,"n":"ר\u0027 אמי בר אבא","l":"א","b":"אמורא בבלי בדור הרביעי - החמישי. חותנו של רב אשי (חולין קי\"א ע\"א). נראה, שקיבל מרב אשי (לפי גיר\u0027 הרי\"ף [שבת רפט\"ו]: \"א\"ר אמי בר אבא אמר רב אשי\")."},{"i":695,"n":"ר\u0027 אמי בר אבין","l":"א","b":"אמורא בבלי בדור הרביעי. מובא בבבלי (כריתות כ\u0027 ע\"א): \"אמי בר אבין ורב חנינא בר אבין דאמרי תרווייהו\": וס\"א גורסים שם: אביי בר אבין."},{"i":696,"n":"רב אמי בר אדא הרפנאה","l":"א","b":"אמורא בבלי בדור הרביעי. תלמידו של רבה (עירובין נ\"ט ע\"ב)."},{"i":697,"n":"רב אמי בר אהבה","l":"א","b":"מובא בבבלי (יבמות כ\"ט ע\"ב). המאמר מובא במקום אחר (נדרים ע\"ד ע\"א) אבל \"מסה\"ש\" (שם) לא גורס \"בר אהבה\"."},{"i":698,"n":"רב אמי בר דיקולי","l":"א","b":"והוא רמי בר תמרי."},{"i":699,"n":"רב אמי בר חייא","l":"א","b":"אמורא בבלי בדור השלישי. ר\"ז שאל ממנו (זבחים ק\"ה ע\"ב). גירסת \"שיטה מקובצת\": \"אבין בר חייא\"."},{"i":700,"n":"רב אמי בר חמא","l":"א","b":"והוא רמי בר חמא. כך נקרא בירושלמי, וכן בבבלי (כתובות מ\"ה ע\"ב)."},{"i":701,"n":"ר\u0027 אמי בר טביומי","l":"א","b":"אמורא שחי לפני אביי, ואביי מפרש דבריו מובא בבבלי (סוכה ט\"ז ע\"א)."},{"i":702,"n":"ר\u0027 אמי בר טובי","l":"א","b":"והוא ר\u0027 אמי בר טביומי."},{"i":703,"n":"ר\u0027 אמי בר יחזקאל","l":"א","b":"מובא בירושלמי (תענית פ\"ב הי\"ד), והוא רמי בר יחזקאל."},{"i":704,"n":"רב אמי בר מתנה","l":"א","b":"אמורא בבלי בדור השני. תלמידו של שמואל. (ברכות ס\"ג ע\"א)."},{"i":705,"n":"רבי אמי בר נתן","l":"א","b":"מובא בבבלי (גיטין מ\"ד ע\"א). והוא רבי אמי סתם בש\"ס, חברו דרבי אסי."},{"i":706,"n":"רבי אמי בר עוקבא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מצינו שאמר בשם רבי יוסי בר חנינא (ירו\u0027, כתובות פ\"ז ה\"ז)."},{"i":707,"n":"ר\u0027 אמי בר פפי","l":"א","b":"מובא בירושלמי (כתובות פ\"ו ה\"ו), והוא אבימי בר פפי."},{"i":708,"n":"ר\u0027 אמי בר קרחה","l":"א","b":"אמורא בבלי בדור השני. אמר בשם רב (ירו\u0027, ב\"ב פ\"י ה\"ח)."},{"i":709,"n":"רב אמי בר שמואל","l":"א","b":"אמורא בבלי בדור השני. תלמיד מובהק של שמואל שאמר: \"לדידי מפרשא לי מיניה דמר שמואל\" (נדה כ\"ה ע\"ב)."},{"i":710,"n":"אמי ורדינאה","l":"א","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. היה תלמידו של ר\u0027 אבהו (נדה י\"ט ע\"ב). לפי לשון ראשון ברש\"י (שם) הוא \"אמי שפיר נאה\" (מובא גיטין מ\"א ע\"א). כינויו ורדינא הוא על שם יופיו (ביצה כ\"ז ע\"ב רש\"י)."},{"i":711,"n":"ר\u0027 אמי חתנו דר\u0027 יונה","l":"א","b":"ע\"ע אמי."},{"i":712,"n":"אמי שפיר נאה","l":"א","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידו של רבי יוחנן (גיטין מ\"א ע\"א). לפי לשון ראשון ברש\"י (נדה י\"ט ע\"ב) הוא אמי ורדינאה."},{"i":713,"n":"אמי תנורא","l":"א","b":"רב יהודה (האמורא הבבלי המפורסם שחי בדור השני) הורה לו דין בחול המועד (מו\"ק י\"א ע\"א). ה\"יוחסין\": כתב \"לא ידעתי אם הוא חכם\". ו\"סה\"ד\" לא הוסיף מאומה, וגם לי נראה שאין להכריע שהיה חכם."},{"i":714,"n":"אמימר","l":"א","b":"אמורא בדור החמישי. מסר משמו של רבא (קידושין י\u0027 ע\"א). אך רבו המובהק היה רב זביד מנהרדעא (ב\"מ ע\"ג ע\"ב). מושבו היה בנהרדעא (ב\"ב ל\"א ע\"א), שם היה הראש (ברכות י\"ב ע\"א). היה הקובע גם במחוזא (ר\"ה ל\"א ע\"ב). כנראה שעמד בראש ישיבה (ביצה כ\"ח ע\"ב). רב אשי היה תלמידו (מנחות ל\"ז ע\"ב): \"רב אשי היה יתיב קמיה דאמימר\", והפך להיות לו תלמיד - חבר (ברכות נ\"ה ע\"ב): \"אמימר ומר זוטרא ורב אשי הוו יתבי בהדי הדדי\". נפטר בחיי רב אשי (ב\"מ ס\"ח ע\"א) בשל פליטת פה של רב אשי. בנו של אמימר ששמו היה מר היה תלמידו של רב אשי (שם)."},{"i":715,"n":"רב אמימר בר מר ינוקא","l":"א","b":"אמורא בבלי בדור השביעי. תלמידו של ר\u0027 חייא בריה דרב אויא (חולין י\"ח ע\"ב). נתפס ע\"י המלכות, בחודש טבת שנת תשפ\"א לשטרות (ד\"א ר\"ל /074), יחד עם הונא מר בר ריש גלותא ומשרשיא בר פקוד, ובאדר אותה שנה נהרג (\"אגרת רב שרירא גאון\")."},{"i":716,"n":"אנטונינוס","l":"א","b":"קיסר רומי ידידו ואוהבו בנפש של רבנו הקדוש. רבי לימדו תורה (ע\"ז י\u0027 ע\"ב). פעמים, ורבי קיבל את סברתו (סנהדרין צ\"א ע\"ב): \"אמר רבי דבר זה למדני אנטונינוס ומקרא מסייעו\". יש אומרים שנתגייר (ירו\u0027, מגילה פ\"א הי\"א). נראה, שמת אחרי רבי (קה\"ר פ\"י ה\u0027)."},{"i":717,"n":"רבי אנטיגנוס","l":"א","b":"אמורא ארץ ישראלי קדום בדור הראשון, ואפשר שחי בדור המעבר בין התנאים לאמוראים. רבי יהושע בן לוי מסר משמו (ירו\u0027, הוריות פ\"ג ה\"ד)."},{"i":718,"n":"אנטיגנוס איש סוכו","l":"א","b":"מראשוני החכמים בדור המעבר בין אנשי כנסת גדולה ל\"זוגות\", כ - 052 שנה לפני החורבן. תלמידו של שמעון הצדיק (אבות פ\"א מ\"ג). שני תלמידיו צדוק ובייתוס יצאו לתרבות רעה, ויסדו כתות צדוקים ובייתוסים (אבות דרבי נתן פ\"ה). יוסי בן יועזר ויוסי בן יוחנן, שהיו דור ראשון ל\"זוגות\", קיבלו ממנו (אבות פ\"א מ\"ד)."},{"i":719,"n":"ר\u0027 אנייני בן סוסיי","l":"א","b":"הוא רבי אנינייא בר סיסי (ע\"ע)."},{"i":720,"n":"רבי אנינייא בר סיסי","l":"א","b":"אמורא ארץ ישראלי בדור השני. ר\u0027 סימון מסר בשמו (ירו\u0027, יומא פ\"ג ה\"ה). דודו של רבי נסא (ירו\u0027, ברכות פ\"ז ה\"ב). \"סה\"ד\" סובר שהוא, ור\u0027 חנינא בר סיסי (ירו\u0027, סנהדרין פ\"ב ה\"ו) אחד הוא. ונראה לומר, שהיה אמורא נוסף בשם זהה, בדור החמישי - הששי. ע\"ע רבי חנינא בר סיסי."},{"i":721,"n":"אנן בר אימא","l":"א","b":"מובא בירושלמי (שבת פ\"ו ה\"ה). גיר\u0027 \"אור זרוע\" ח\"ב ספ\"ד: חנן בר אימי (תלמידו של רב יהודה), (ע\"ע)."},{"i":722,"n":"רבי אסא","l":"א","b":"מובא במד\"ר (פ\u0027 נשא פ\"ו), ואולי ט\"ס היא וצ\"ל: ר\u0027 אסי."},{"i":723,"n":"אסא בן עקיבא","l":"א","b":"מובא בירושלמי (עירובין פ\"ד ה\"א), והוא איסי בן עקביה."},{"i":724,"n":"רב אסי","l":"א","b":"אמורא בבלי בדור הראשון (להבדילו מרבי אסי, אמורא ארץ ישראלי בדור השלישי). תלמיד חבר לרב (שבת קמ\"ו ע\"ב רש\"י ד\"ה: רב): לגמירי דרב הוו צריך ולא לסברתו (סנהדרין ל\"ו ע\"ב). ללוי קרא \"רבי\" (ע\"ז ל\"ח ע\"ב). היה הראש בעיר הוצל (מגילה ה\u0027 ע\"ב). נראה, שעמד בראש ישיבה אחרי פטירת רב ואח\"כ באו תלמידיו לפני שמואל (יבמות י\"ז ע\"א רש\"י). ר\"ה היה תלמידו (כתובות מ\"ח ע\"ב) וכן רב יהודה (שבת כ\"ב ע\"א). נפטר כעונש על שהכניס בשמתא את חברו (נדה ל\"ו ע\"ב)."},{"i":725,"n":"רבי אסי","l":"א","b":"אמורא ארצישראלי בדור השלישי. עלה מבבל ושם עוד הכיר אישית את שמואל וסיפר ששמע את רב יהודה שואל את שמואל (ירו\u0027, עירובין פ\"ו ה\"ח). ולמד מרב יהודה (ב\"מ מ\"ג ע\"א). בארץ ישראל היה תלמידו המובהק של רבי יוחנן (חגיגה י\"ג ע\"א). וכן קיבל מרבי אלעזר (ירו\u0027, חגיגה פ\"א ה\"ז) ומרבי חנינא (סנהדרין מ\"ג ע\"ב). היה חברו המובהק של רבי אמי, ושניהם נזכרים כמעט תמיד יחד בש\"ס, והיו כפופים לרב הונא (מו\"ק כ\"ה ע\"א) ונסמכו יחד בארץ ישראל (כתובות י\"ז ע\"א). והם המכונים \"דייני דארץ ישראל\" (סנהדרין י\"ז ע\"ב). בין תלמידיו היה ר\"ז (ב\"ב פ\"ד ע\"ב). גם רבי אבהו קיבל ממנו (יבמות ס\"ה ע\"ב). כשמת - נתקבצו החכמים על מנת לחזור על השמועות ששמעו מפיו, כדי שלא ישתכחו (קידושין י\"ג ע\"א)."},{"i":726,"n":"רבי אסי בן שאול","l":"א","b":"מובא בבבלי (שבת נ\u0027 ע\"א). צ\"ל: רבי יוסי בן שאול (תלמידו של רבי)."},{"i":727,"n":"רבי אסי בר אבא","l":"א","b":"מובא בבבלי לפי גירסת הרי\"ף מסר משם רבי יוחנן (יבמות ל\"ט ע\"ב)."},{"i":728,"n":"ר\u0027 אסי בר היני","l":"א","b":"הוא איסי בר היני."},{"i":729,"n":"ר\u0027 אסי בר חייא","l":"א","b":"מובא בבבלי (ע\"ז נ\"א ע\"ב). \"סה\"ד\" מפקפק שמא הוא ור\u0027 אמי בר חייא אחד הוא. \"דק\"ס\" גורס: \"ר\u0027 שימי בר חייא\"."},{"i":730,"n":"ר\u0027 אסי בר חמא","l":"א","b":"מובא בבבלי (ב\"ק צ\"ג ע\"א). \"סה\"ד\" ו\"דק\"ס\" גורסים: \"רב יוסף בר חמא\" (אבי רבא)."},{"i":731,"n":"ר\u0027 אסי בר חנינא","l":"א","b":"מובא בבבלי (בכורות ל\"ד ע\"ב), והגיהו שם: ר\u0027 יוסי בר חנינא. וכ\"ה ב\"דק\"ס\" (ב\"ב נ\"ו ע\"א)."},{"i":732,"n":"רב אסי בר ממל","l":"א","b":"מובא בירושלמי (גיטין פ\"ג ה\"ח): \"חנינא בריה דרב אסי בר ממל\"."},{"i":733,"n":"ר\u0027 אסי בר מתיא","l":"א","b":"מובא ב\"ילקוט\" (פנחס רמז תשע\"ו)."},{"i":734,"n":"רב אסי בר נתן","l":"א","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב ששת (נדרים ע\"ח ע\"א). שאל מרבי חייא בר אשי (שבת נ\"ג ע\"א), ודיבר עם רבי זירא (שם)."},{"i":735,"n":"רב אסי ג\u0027","l":"א","b":"אמורא בבלי בדור הששי. תלמידו של רבא (שבת צ\"ה ע\"ב). חברו של רב אשי (כתובות ח\u0027 ע\"א). בנו, רב סמא, היה תלמידו של רב אשי (שם ל\"ג ע\"ב). בכתבי יד קדומים נקרא: רב אתי או איתי, ושיבשוהו לרב אסי."},{"i":736,"n":"רב אסי דהוצל","l":"א","b":"אמורא בבלי בדור השלישי. נראה, שהיה בזמנו של ר\"ה (קידושין נ\"ח ע\"ב)."},{"i":737,"n":"ר\u0027 אסי מנהרביל","l":"א","b":"מובא בבבלי (חולין פ\"ז ע\"ב). גירסת ה\"יוחסין\": מנהר - בול. ושם (קל\"ו ע\"א): \"אמר רבי יוסי מנהרביל\". וב\"דק\"ס\": \"אסי ויוסי אחד הם\". \"יוחסין\" גרס שני שמות: ר\u0027 יוסי מנהר - בול ור\u0027 אסי מנהר - בול."},{"i":738,"n":"רבי אפטוריקי","l":"א","b":"אמורא, כנראה ארץ ישראלי, שאין לקבוע זמנו המדוייק. מובא בבבלי (זבחים י\"ב ע\"א). רב אדא בר אהבה מתיב על דבריו (מנחות נ\"ה ע\"ב). אביו דוסתאי היה חכם שונה ברייתות (חולין ס\"ד ע\"ב: ב\"מ ה\u0027 ע\"א). נקרא על שם בנו אבוה דר\u0027 אפטוריקי (חולין שם)."},{"i":739,"n":"רבי אפס","l":"א","b":"אמורא ארץ ישראלי. מראשוני הדור הראשון. בדורו של ר\u0027 יהודה הנשיא. מושבו היה בדרום א\"י (עירובין ס\"ה ע\"ב: ירו\u0027, תענית פ\"ד ה\"ב). היה סופרו של ר\u0027 יהודה הנשיא (ב\"ר ע\"ה - ה\u0027). אחר פטירת ר\u0027 יהודה הנשיא ישב בראש הישיבה (כתובות ק\"ג ע\"ב). בענין הלכה מוזכר שמו רק פעם אחת (יומא ס\"א ע\"א). ריש לקיש פנה אליו בשאלה (עירובין שם). רבי הושעיא מסר משמו (ירו\u0027, יומא פ\"ה ה\"ז). לוי היה כפוף לו (כתובות שם)."},{"i":740,"n":"אפקולוס","l":"א","b":"תנא דברייתא. מובא בתוספתא (חולין רפ\"ח). \"סה\"ד\" מביא גם את פירוש הר\"ן (חולין ק\"ד ע\"ב) \"אפקולוס פירוש מטלית\"."},{"i":741,"n":"אפרא הורמיז","l":"א","b":"אמו של מלך פרס בזמנו של רבא. מוזכרת לשבח בבבלי (נדה כ\u0027 ע\"ב). היתה נוכרית וקרובה להתגייר, ואף קרבנות היתה שולחת. כדי להוכיח לבנה המלך שבור מלכא את גדולתם של החכמים ביקשה מרבא שיבקש שירד גשם בתמוז וכן היה (תענית כ\"ד ע\"ב)."},{"i":742,"n":"אפרים","l":"א","b":"מובא בירושלמי (סוף ב\"מ). ע\"ע אפרים ספרא."},{"i":743,"n":"אפרים מקשאה","l":"א","b":"תנא בדור החמישי. תלמידו של ר\"מ (ב\"מ פ\"ז ע\"א). פירוש השם \"מקשאה\": שומר קשואין או מקשה הלכות."},{"i":744,"n":"אפרים ספרא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי (סוף ב\"מ): \"אפרים בשם ריש לקיש\"."},{"i":745,"n":"אריוך","l":"א","b":"כינוי לשמואל (מנחות ל\"ח ע\"ב), ופרש\"י: \"לשון מלך כמו (בראשית מ\"ט) גור אריה יהודה, ולהכי קרי לשמואל - אריוך, דקיימא לן (בכורות מ\"ט ע\"ב) הלכה כשמואל בדיני, כי היכי דדינא דמלכותא דינא\". ע\"ע שבור מלכא."},{"i":746,"n":"אריוס","l":"א","b":"מובא בספרי (דברים פ\u0027 י\"ג) ואין להכריע אם היה חכם. שאל את רבי יוסי (תנא ארץ ישראלי בדור הרביעי) (שם)."},{"i":747,"n":"ר\u0027 אריסטי","l":"א","b":"אמורא ארץ ישראלי בדור החמישי. מובא בתנחומא (תולדות י\"ט), שמסר בשם רבי ברכיה."},{"i":748,"n":"רבי ארמניא","l":"א","b":"אמורא ארץ ישראלי בדור הששי. רבי מנא הורה לו בדיני אבלות (ירו\u0027, מו\"ק פ\"ג ה\"ה)."},{"i":749,"n":"רב אשי","l":"א","b":"גדול אמוראי בבל בדור הששי וראש הדור. נולד ביום שמת רבא (קידושין ע\"ב ע\"ב), בשנת ד\"א קי\"א (153) נפטר בשנת ד\"א קפ\"ו (624) (\"אגרת רב שרירא גאון\"). עמד בראש ישיבת סורא. סידר וערך את התלמוד הבבלי בשתי מהדורות במשך 06 שנה (ב\"ב קנ\"ז ע\"ב וברשב\"ם). בתוספות כתבו (חולין ב\u0027 ע\"ב ד\"ה: אנא): \"ומכאן ראיה שרב אשי סידר הגמרא\". \"רב אשי ורבינא סוף הוראה\" (ב\"מ פ\"ו ע\"א), ופרש\"י: \"סוף כל האמוראים\". עמד בראש במתא מחסא (שבת י\"א ע\"א רש\"י) שהיא סורא (\"אגרת רב שרירא גאון\" ב\"יוחסין\" הישן). רבותיו המובהקים היו רב כהנא (ברכות ל\"ט ע\"א), ר\"פ (ע\"ז מ\u0027 ע\"א) ורב מתנה (זבחים כ\"ט ע\"א). בין תלמידיו הרבים היה בנו מר בר רב אשי (חולין ע\"ו ע\"ב), שישב על כסא אביו (ב\"ב י\"ב ע\"ב). היה עשיר מופלג ועליו אמרו \"מימות רבי ועד רב אשי לא מצינו תורה וגדולה במקום אחד\" (גיטין נ\"ט ע\"א). על פטירתו מסופר, שמלאך המות פגשו בשוק ורב אשי בקשו שימתין 03 יום טרם ימות, כדי שיחזור על תלמודו (מו\"ק כ\"ח ע\"א)."},{"i":750,"n":"רב אשי בר אבין","l":"א","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב יהודה (שבת ס\"ו ע\"ב). גירסת הרי\"ף, הרא\"ש ו\"דק\"ס\": \"רב אידי בר אבין\"."},{"i":751,"n":"רב אשי מאויריא","l":"א","b":"אמורא בבלי בדור הרביעי. אמר בשם ר\u0027 זירא (שבועות כ\"ד ע\"ב). ישב באויריא (רש\"י שם)."},{"i":752,"n":"רב אשי מהוצל","l":"א","b":"מובא בבבלי: \"התקין רב אשי בהוצל\" (חולין ק\"ז ע\"א). יש גירסא:\" רב אסי דהוצל\" (ע\"ע)."},{"i":753,"n":"אשיאן א\u0027","l":"א","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מובא בבבלי: \"בעא מיניה אשיאן תנא דבי רבי אמי מרבי אמי\" (ברכות י\"ד ע\"א)."},{"i":754,"n":"אשיאן בר נידבך","l":"א","b":"אמורא בדור השלישי. אמר משמו של רב יהודה (מנחות כ\"ט ע\"א). ר\"ז אמר משמו (ירו\u0027, מגילה פ\"א ה\"ט). היה חתנו של רבי ייבא (ב\"ב כ\"ב ע\"ב)."},{"i":755,"n":"רב אשיאן ב\u0027","l":"א","b":"מובא בירושלמי (תרומות ספ\"א), והוא בן אשיין. נראה, שהוא גם רבי שיין. (ע\"ע)."},{"i":756,"n":"רב אשייאן בר יקום","l":"א","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. שאל לר\u0027 אסי ושקיל וטרי עמו (ירו\u0027, יבמות פי\"א ה\"ז)."},{"i":757,"n":"אשייאן בר נידבה","l":"א","b":"מובא בירושלמי (מגילה פ\"א ה\"ט), והוא אשיאן בר נידבך."},{"i":758,"n":"אשייאן נגרא","l":"א","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם רבי יוחנן (ירו\u0027, ע\"ז רפ\"ג)."},{"i":759,"n":"רבי אשיין","l":"א","b":"אמורא ארץ ישראלי בדור החמישי - הששי. מסר הרבה בשם רבי יונה (ירו\u0027, יומא פ\"ח ה\"ז). הוא ור\u0027 אשייאן אחד הם. נראה, שהוא גם רבי שיין (ירו\u0027, עירובין פ\"א ה\"ו)."},{"i":760,"n":"ר\u0027 אתי","l":"א","b":"ע\"ע רב אסי ג\u0027."},{"i":761,"n":"א\"ר יוסי בר\u0027","l":"א","b":"כך מובא בירושלמי (ברכות פ\"ח ה\"א), והמאמר מובא בבבלי (פסחים ק\"ו ע\"ב תד\"ה: מקדש) בשם יוסי בר בון, ונראה שבירושלמי הושמט השם בון."},{"i":762,"n":"ר\u0027 בא","l":"ב","b":"מגדולי אמוראי בבל ומראשי הדור הרביעי. אביו היה האמורא רב יוסף בר חמא (עירובין נ\"ד ע\"א). רש\"י כתב: \"רבא בריה דרב יוסף בר חמא (כצ\"ל) הוא והוא רבא בכולי גמרא בר פלוגתיה דאביי\" (חולין מ\"ג ע\"ב). היה ראש ישיבת מחוזא ארבע עשרה שנה נפטר בשנת ד\u0027 קי\"א (153). במותו נחלקה ישיבת מחוזא לשתים: רב נחמן בר יצחק תלמידו מלך בפומבדיתא ורב פפא תלמידו מלך בנרש (\"אגרת רב שרירא גאון\"). רב נחמן היה רבו המובהק (ברכות כ\"ג ע\"ב). רבא היה אצלו כשרב נחמן נפטר (מו\"ק כ\"ח ע\"א). וגם רב חסדא היה רבו (קידושין נ\"ג ע\"ב), וכן היה חותנו (יבמות ל\"ד ע\"ב). גם רב יוסף היה רבו המובהק (יומא נ\"ג ע\"א). וכשנודע לרב יוסף שרבא מכבדו מאוד, ברכו שיהיה ראש ישיבה (שם). ולדעת תוספות היה גם רב סחורה רבו המובהק. \"רב סחורה רבו המובהק של רבא היה\" (ע\"ז י\"ט ע\"א ד\"ה: אמר). חברו הגדול והמובהק היה אביי, ועל שמם נקרא הש\"ס: \"הויות דאביי ורבא\" (סוכה כ\"ח ע\"א). מחלוקותיהם ושקלי וטרי שלהם פזורים בכל הש\"ס, וכבר בילדותם למדו יחד (ברכות מ\"ח ע\"א). כשנפטר רב יוסף, מינו את אביי לראש (סוף הוריות), וכשאביי נפטר בשנת ד\u0027 צ\"ח (833) בפומבדיתא, מלך רבא. אך במקום בפומבדיתא, יסד את ישיבתו במחוזא, והיא היתה הישיבה המרכזית בבבל (\"אגרת רב שרירא גאון\"), ורב נחמן בר יצחק שימש כראש כלה אצלו (ב\"ב כ\"ב ע\"א). דרך לימודו של רבא היה בחריפות: \"אמר רבא וכו\u0027 היינו דאמרי אינשי: \u0027טבא פילפלתא חריפתא ממלי צנא דקרי\u0027\" (חגיגה י\u0027 ע\"א). אהב את הסברא: \"אמר להו (רבא): \u0027זיל בתר סברא\u0027\" (גיטין ע\"ג ע\"א). והלכה כרבא שהוא בתראה (ברכות י\"ג ע\"ב תוס\u0027). תוספות כתבו: \"בכל מקום שהרב והתלמיד חולקין הלכה כדברי הרב באמוראי עד אביי ורבא, אבל מכאן ואילך פסקינן כבתראי\" (קידושין מה ע\"ב ד\"ה: הוה). בין תלמידיו הרבים היו רבינא (ב\"ב ט\"ז ע\"ב), רב פפא (כתובות פ\"ה ע\"א), ובניו רב יוסף (חולין כ\"ח ע\"ב) ורב משרשיא (שם ע\"א), ועל שניהם אמר רבא: \"חכים ברי בטריפות\" (שם). היה מופלג בחסידות ולא בוש לומר: \"טעיתי\" (עירובין ק\"ד ע\"א). נהג לצום שני ימים ביום הכיפורים משום ספיקא (ר\"ה כ\"א ע\"א). ובכל ערבי יום כפורים יצאה בת קול מהשמים ושאלה לשלומו (תענית כ\"א ע\"ב). היה עשיר מופלג וחכם נדיר (מו\"ק כ\"ח ע\"א). היה מקורב למלכות (ב\"ב י\u0027 ע\"ב). לפי דרישתו של שבור מלכא מלך פרס, שניסה אותו, ביקש פעם מן השמים בחודש תמוז שירד גשם שוטף ובקשתו נתקבלה, ואביו בא לו בחלום ואמר שלא ישן במיטתו בלילה, שכן יש הקפדה מהשמים שהטריח בעניין הגשמים, ובלילה, חתכו השדים את מיטתו (תענית כ\"ד ע\"ב). ושוב שלחו מבית שבור מלכא לשאלו אם יודע להבחין בין סוגי דם, וידע להבחין יותר מששים סוגי דם (נדה כ\u0027 ע\"ב). ומסופר (מו\"ק שם) על פטירתו, שרב שעורים אחיו של רבא היה אצלו כשמת, וביקש רבא את אחיו שיאמר למלאך המות שלא יצערו. אחרי פטירתו נגלה לאחיו רב שעורים וסיפר לו שהיתה לו מיתה קלה בלי צער, והתחושה היתה כאילו הקיזו דם. כשמת רב יהודה, נולד רבא, וכשמת רבא, נולד רב אשי (קידושין ע\"ב ע\"ב)."},{"i":763,"n":"רבי בא בר בינא","l":"ב","b":"מובא בירושלמי (כתובות פ\"א ה\"ב). ע\"ע רבי אבא בר אבינא."},{"i":764,"n":"רבי בא בר בינה","l":"ב","b":"מובא בירושלמי (מגילה פ\"א ה\"ט). ע\"ע רבי אבא בר אבינא."},{"i":765,"n":"רבי בא בר חונא","l":"ב","b":"מובא בירושלמי (שבת רפי\"א). ע\"ע רבה בר רב הונא."},{"i":766,"n":"רבי בא בר חייא בר אשי","l":"ב","b":"מובא בירושלמי (שבת פ\"ז ה\"ב). סביר שצ\"ל: ר\u0027 אבא [בשם] ר\u0027 חייא בר אשי."},{"i":767,"n":"רבי בא בריה דרבי חייא בר יוא","l":"ב","b":"מובא בירושלמי (דמאי פ\"א ה\"ד), והוא רבי אבא בריה דרבי חייא בר אבא (ע\"ע)."},{"i":768,"n":"באלי","l":"ב","b":"אמורא בבלי בדור הרביעי. תלמידו של רב חייא בר אבא (תענית י\"ח ע\"א). כן מסר בשם רבי יעקב ברה דבת שמואל (ברכות כ\"ה ע\"ב)."},{"i":769,"n":"בבא בן בוטא","l":"ב","b":"תנא בדור הראשון. דור לפני החורבן. אף שהיה מתלמידיו של שמאי עשה כהלל (ביצה כ\u0027 ע\"א). כאשר הורדוס הרג את חכמי ישראל, השאיר בחיים את בבא בן בוטא, אך ניקר את עיניו. אח\"כ, בהשפעתו, חידש ובנה הורדוס את בית המקדש (ב\"ב ד\u0027 ע\"א). היה חסיד (כריתות כ\"ה ע\"א), ענו (נדרים ס\"ו ע\"א) וחכם (גיטין נ\"ז ע\"א)."},{"i":770,"n":"בג בג","l":"ב","b":"ראה בן בג בג."},{"i":771,"n":"ר\u0027 בדלה","l":"ב","b":"מובא בבמד\"ר (פי\"ב - ח\u0027), ונראה שצ\"ל: ר\u0027 בצלאל."},{"i":772,"n":"בהא","l":"ב","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (תמורה כ\"ט ע\"א). עלה מבבל לארץ ישראל והיה חברו של ר\u0027 אבא (שם)."},{"i":773,"n":"רב בודיא","l":"ב","b":"אמורא בבלי בדור הששי - השביעי. הקשה לרב אשי (גיטין מ\"ה ע\"ב)."},{"i":774,"n":"בוהיין","l":"ב","b":"חי בתקופת התנאים, בדורו של ר\"ע, שבא לביתו לאיסוף כסף לצרכי צדקה (ירו\u0027, פסחים ספ\"ד). בבבלי (פסחים נ\"ז ע\"א) מובא: בן בוהיין נתן פאה לירק (על אף שפטורים מכך). בירושלמי (שם) מכונה \"בן מביא יין\"."},{"i":775,"n":"ר\u0027 בוטא","l":"ב","b":"מובא בזהר חדש (פ\u0027 נעשה אדם)."},{"i":776,"n":"בוטנית בריה דאבא שאול בן בוטנית","l":"ב","b":"תנא - אמורא בדור המעבר בין התנאים לאמוראים בארץ ישראל. מצא פתח לנדר של ר\u0027 שמעון, בנו של רבי (נדרים כ\"ג ע\"א)."},{"i":777,"n":"ר\u0027 בולאטה","l":"ב","b":"מובא (ירו\u0027, תענית פ\"ד ה\"ב) והוא בלוויטי."},{"i":778,"n":"ר\u0027 בון","l":"ב","b":"ע\"ע אבין או רבין."},{"i":779,"n":"בונה בר שילא","l":"ב","b":"מובא בירושלמי (גיטין פ\"ב ה\"ג), והוא רבינא בר שילא."},{"i":780,"n":"בוני (2)","l":"ב","b":"ע\"ע נקדימון בן גוריון."},{"i":781,"n":"בונייס בן בונייס","l":"ב","b":"אמורא ארץ ישראלי בדור רבי (עירובין פ\"ה ע\"ב). היה עשיר גדול (גיטין נ\"ט ע\"א). שלח לרבי מתנות יקרות (שם)."},{"i":782,"n":"בונים בן נונים","l":"ב","b":"מובא בבבלי (גיטין נ\"ט ע\"א), והוא בונייס בן בונייס."},{"i":783,"n":"רבי בוסנא","l":"ב","b":"אמורא ארץ ישראלי בדור הרביעי. אמר בשם ר\u0027 אלעאי (ירו\u0027, שבת פ\"ב ה\"ו), ובשם ר\u0027 חייא בר אבא (תנחומא שמיני - י\"ב), וחלק עם רבי ברכיה (ירו\u0027, מעשרות פ\"ה ה\"ג)."},{"i":784,"n":"רב בוריא","l":"ב","b":"כך גירסת \"יחוסי תנאים ואמוראים\", ולפנינו (גיטין מ\"ה ע\"ב) רב בודיא."},{"i":785,"n":"רבי בורקי","l":"ב","b":"אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי מנא (ירו\u0027, קידושין פ\"ג ה\"ב), ושנה לפניו ברייתא (ירו\u0027 ע\"ז פ\"ג ה\"ה). הוא וחבריו היו משלשין את היום: שליש לתורה שליש לתפילה ושליש למלאכה (קה\"ר פ\"ט - ט\u0027)."},{"i":786,"n":"ר\u0027 בזירה","l":"ב","b":"מובא בירושלמי (ברכות פ\"ח ה\"ה), ונראה שהוא ט\"ס וצ\"ל בשם ר\u0027 נזירא."},{"i":787,"n":"ר\u0027 ביבא","l":"ב","b":"ע\"ע רבי ביבי א\u0027."},{"i":788,"n":"ר\u0027 ביבא אבא","l":"ב","b":"מובא בירושלמי (תענית פ\"ב ה\"ד). אמר (שם) בשם ר\u0027 יוחנן. גיר\u0027 \"סה\"ד\" שצ\"ל: ר\u0027 ביבי בר אבין\"."},{"i":789,"n":"ר\u0027 ביבא בר אחא","l":"ב","b":"מובא בירושלמי (שקלים פ\"א), לגיר\u0027 ה\"יוחסין\"."},{"i":790,"n":"ר\u0027 ביבא בר זבדא","l":"ב","b":"מובא באיכ\"ר (פ\"ג פ\u0027 נחפשה). ויש גורסים: ר\u0027 בא בר זבדא."},{"i":791,"n":"רב ביבא בריה דר\u0027 אבא","l":"ב","b":"מובא בויק\"ר (פ\"ג). ו\"סה\"ד\" סובר שצ\"ל: \"ר\u0027 ביבי בר אבין\"."},{"i":792,"n":"ר\u0027 ביבא סנגוריא","l":"ב","b":"מובא באיכ\"ר (פ\"א - נ\"א). נראה, שצ\"ל: ר\u0027 אבא סרונגיא."},{"i":793,"n":"ר\u0027 ביבא רבה","l":"ב","b":"מובא בפסיקתא דר\"כ (קנ\"ד), ונראה שהוא רב ביבי ב\u0027."},{"i":794,"n":"ר\u0027 ביבון","l":"ב","b":"מובא בירושלמי (גיטין פ\"ג ה\"א)."},{"i":795,"n":"ר\u0027 ביבון בר חייא","l":"ב","b":"מובא בירושלמי (גיטין פ\"ג ה\"א)."},{"i":796,"n":"רבי ביבי א\u0027","l":"ב","b":"אמורא בבלי בדור הרביעי. תלמידם של ר\"נ (חגיגה כ\"ב ע\"ב) ושל רב יהודה (עירובין כ\"ג ע\"ב). קיבל גם מרב המנונא [תלמיד חבר של רב חסדא] (נדה כ\"ז ע\"א). ר\"פ היה קטן ממנו (שם). התאכסן אצל רב יוסף, שקרא לו גברא רבא (קידושין ע\"ו ע\"ב)."},{"i":797,"n":"רב ביבי בר אביי (2)","l":"ב","b":"אמורא בבלי בדור החמישי. בנו של אביי (סנהדרין ס\"ו ע\"ב). תלמידו של רב יוסף (שם). לא מצינו בש\"ס שקבל מאביו אביי. רבו של רב פפי (חולין מ\"ג ע\"ב). מלאך המות היה שכיח גביה (חגיגה ד\u0027 ע\"ב). ביקש לראות שדים וניזוק, והתפללו עליו ונתרפא (ברכות ו\u0027 ע\"ב)."},{"i":798,"n":"רב ביבי בר אבין","l":"ב","b":"מובא בבבלי (נדה כ\"ה ע\"ב), לגיר\u0027 ה\"יוחסין\", והוא רבי ביבי ב\u0027 (ע\"ע)."},{"i":799,"n":"רב ביבי בר אבינא","l":"ב","b":"מובא ב\"ילקוט\" (משלי רמז תתקנ\"ט)."},{"i":800,"n":"רב ביבי בר אשי","l":"ב","b":"גיר\u0027 \"יוחסין\": א\"ר ביבי אמר רב אשי."},{"i":801,"n":"רב ביבי בר ביזנא","l":"ב","b":"ע\"ע נהרבלאי."},{"i":802,"n":"ביבי בר גוזלון","l":"ב","b":"אמורא בבלי בדור הראשון - השני. תלמידו של רב. רבו של רב הונא. (ירו\u0027, ב\"מ פ\"ב ה\"ה)."},{"i":803,"n":"ר\u0027 ביבי בר גוזלן","l":"ב","b":"ע\"ע ביבי בר גוזלון."},{"i":804,"n":"ר\u0027 ביבי בר חייא","l":"ב","b":"נראה שהוא ר\u0027 אבון בר חייא."},{"i":805,"n":"ר\u0027 ביבי בר כהנא","l":"ב","b":"מובא בירושלמי (שקלים פ\"ב ה\"ד). וצ\"ל: ר\u0027 בון [אבין] בר כהנא."},{"i":806,"n":"ר\u0027 ביבי בריה דר\u0027 אמי","l":"ב","b":"מובא בב\"ר (פכ\"ו - ו\u0027)."},{"i":807,"n":"רבי ביבי ב\u0027","l":"ב","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. נראה שהוא ר\u0027 ביבי בר אביי, תלמידו המובהק של ר\u0027 יוחנן (נדה כ\"ה ע\"ב) [לא ר\u0027 ביבי בר אביי בנו של אביי]. וכן מצינו: \"אמר ר\u0027 ביבי אמר ר\"ל\" (מכות י\"ז ע\"א). היה תלמידם של ר\u0027 אמי ושל ר\u0027 אסי (שבת ע\"ד ע\"א)."},{"i":808,"n":"ר\u0027 ביבי מרגניא","l":"ב","b":"מובא באיכ\"ר (פ\"א - מ\"א). \"סה\"ד\": \"אולי ט\"ס ואולי צ\"ל ר\u0027 אבא סרונגיא\"."},{"i":809,"n":"ר\u0027 ביבי מרנגיא","l":"ב","b":"מובא באיכ\"ר (פ\"א - מ\"א), ונראה שצ\"ל: ר\u0027 אבא סרונגיא."},{"i":810,"n":"ר\u0027 ביבי רבה","l":"ב","b":"מובא בירושלמי (תענית פ\"ב), ונראה שצ\"ל: ר\u0027 ביבי בר אבין."},{"i":811,"n":"ר\u0027 ביבן","l":"ב","b":"ע\"ע רבי ביבי א\u0027."},{"i":812,"n":"ר\u0027 ביזנא בר זבדא","l":"ב","b":"מובא בבבלי: \"א\"ר ביזנא בר זבדא א\"ר עקיבא א\"ר פנדא וכו\u0027\" (ברכות נ\"ה ע\"ב). ונראה לי כי יש כאן איזה שיבוש."},{"i":813,"n":"ביטנית בריה דאבא שאול בן ביטנית","l":"ב","b":"מובא (נדרים כ\"ג ע\"א) שהתיר נדר לר\u0027 שמעון בנו של רבינו הקדוש (שחי בדור ראשון לאמוראים), ואם כן אין לומר שזה ביטנית בנו של אבא שאול בן ביטנית, שחי שתי דורות לפני החורבן. אם לא נאמר שיש כאן שיבוש הרי לא ידעתי מיהו ביטנית זה."},{"i":814,"n":"ר\u0027 בייתוס","l":"ב","b":"מובא בירושלמי (עירובין פ\"ו ה\"ד). ר\u0027 יוסטי בר סימון אמר משמו."},{"i":815,"n":"בייתוס בן זונין א\u0027","l":"ב","b":"תנא בדור השני - השלישי. תלמידו של ר\"ג דיבנה (ירו\u0027, פסחים פ\"ב ה\"ד). עשה שדהו מכר, ע\"פ ר\"א בן עזריה (ב\"מ ס\"ג ע\"א). היה עשיר (ירו\u0027, ע\"ז פ\"ה ה\"ב)."},{"i":816,"n":"בייתוס בן זונין ב\u0027","l":"ב","b":"תנא בדור החמישי (בנו של זונין בר בייתוס ב\u0027) שנה לפני רבי (ירו\u0027, שבת פ\"ח ה\"ו)."},{"i":817,"n":"בינה","l":"ב","b":"פעמים מוחלף עם אבינא."},{"i":818,"n":"רבי בינה","l":"ב","b":"אמורא בבלי בדור השלישי - הרביעי. אמר בשם ר\u0027 ירמיה [בר אבא] (ירו\u0027, ב\"מ פ\"ו ה\"א). ר\u0027 חזקיה אמר משמו (ירו\u0027, ע\"ז פ\"ג ה\"ג), ושם - ר\u0027 כיני והוא ר\u0027 בינה."},{"i":819,"n":"רבי ביסא","l":"ב","b":"אביו של רבי חמא וזקנו של רבי אושעיא מסדר הברייתות. עליהם אמרו: \"והחוט המשולש לא במהרה ינתק\" (ב\"ב נ\"ט ע\"א). הראב\"ד (בהקדמת הרמב\"ם) כתב שהיה מבית דינו של רבי, וזו גם דעתו של הרמב\"ם."},{"i":820,"n":"ר\u0027 ביסנא","l":"ב","b":"אמורא ארץ ישראלי בדור הרביעי. מסר משם ר\u0027 אלעאי (ירו\u0027, שבת פ\"ב ה\"ו) ורבי חייא בר אבא (תנחומא שמיני). חברו היה ר\u0027 אבין (ירו\u0027, יבמות פ\"ג ה\"ט)."},{"i":821,"n":"בירא","l":"ב","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של ר\u0027 אמי (סוכה כ\"ז ע\"א). שמו נשתבש בכמה אופנים. ר\u0027 אבא בר כהנא מסר בשמו (ב\"ר פמ\"ז - ה\u0027)."},{"i":822,"n":"ביראה","l":"ב","b":"מובא בבבלי (סוכה ל\"ד ע\"ב), והוא בירא (ע\"ע)."},{"i":823,"n":"ר\u0027 בירי","l":"ב","b":"מובא בב\"ר (פמ\"ז - ה\u0027), והוא בירא (ע\"ע)."},{"i":824,"n":"ביריי","l":"ב","b":"מובא בירושלמי (תרומות פ\"י ה\"ו), והוא בירא (ע\"ע)."},{"i":825,"n":"ביריים","l":"ב","b":"מובא בבבלי (חולין צ\"ח ע\"א), ונראה זהה לבירא (ע\"ע)."},{"i":826,"n":"ר\u0027 בירייס","l":"ב","b":"אמורא ארץ ישראלי. מסר משום רבי יהושע בן לוי (ב\"ק פ\"ב ע\"א), ואולי הוא ביריים."},{"i":827,"n":"בית אבטינוס","l":"ב","b":"מובא במשנה (שקלים רפ\"ה), שהיו ממונים בבית שני על מעשה הקטורת. היתה להם לשכה מיוחדת למעשה הקטורת (יומא י\"ט ע\"א). מוזכרים לגנאי (יומא ל\"ח - ע\"א) על שלא רצו ללמד על מעשה הקטורת אך גם מוזכרים לשבח (שם), שמעולם לא יצאת כלה מבושמת מבתיהן, שלא יאמרו ממעשה הקטורת מתבסמין."},{"i":828,"n":"בית בייתוס","l":"ב","b":"מובא בבבלי (פסחים נ\"ז ע\"א): \"אמר אבא שאול בן בטנית משום אבא יוסף בן חנין אוי לי מבית בייתוס אוי לי מאלתן\". היו כהנים גדולים בבית שני."},{"i":829,"n":"בית גרמו","l":"ב","b":"מובא במשנה (שקלים רפ\"ה), שהיו ממונים בבית שני על מעשה לחם הפנים. מוזכרים לגנאי (יומא ל\"ח ע\"א) על שלא רצו ללמד על מעשה לחם הפנים וכן מוזכרים (שם) לשבח, ש\"מעולם לא נמצאת פת נקיה ביד בניהם, שלא יאמרו ממעשה לחם הפנים זה ניזונין\"."},{"i":830,"n":"ביתוס בר זונין","l":"ב","b":"מובא בתוספתא (סוף פסחים), והוא בייתוס בר זונין."},{"i":831,"n":"בלוויטי","l":"ב","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (ערכין י\"א ע\"א): \"בלויטי אמר רבי יוחנן\" - ופרש\"י שהוא שם חכם. בנו הוא חזקיה בר בילוטו (ערכין כ\"ח ע\"ב)."},{"i":832,"n":"בלצא","l":"ב","b":"מובא בשמ\"ר (פכ\"ט - מ\u0027), ששאל את ר\"ע מהיכן נעשה הרעש. \"סה\"ד\" מסתפק אם היה חכם."},{"i":833,"n":"בן אבטיח","l":"ב","b":"מובא בבבלי (בכורות ל\"ז ע\"ב). ע\"ע בן בטיח."},{"i":834,"n":"בן אחייה","l":"ב","b":"מובא במשנה (שקלים רפ\"ה), שהיה ממונה בבית המקדש על הכהנים חולי מעיים. נראה שהיה רופא. יען שהכהנים היו הולכים יחף על הרצפה בעזרה ואוכלים בשר ושותים מים, סבלו ממחלת מעיים (שם בגמ\u0027)."},{"i":835,"n":"בן אטיטם","l":"ב","b":"מובא בירושלמי (חלה פ\"ד ה\"ה) שהעלה בכורות מבבל בזמן בית המקדש ולא קיבלו ממנו. בבבלי (חלה פ\"ד מי\"א) הגיר\u0027: בן אנטינוס. ובמקום אחר (תמורה כ\"א ע\"א): בן אנטיגנוס. \"יוחסין\" כתב (ערך ניתאי איש תקוע) \"כולם חסידים ואנשי מעשה לכן הזכרתים\"."},{"i":836,"n":"בן אילם","l":"ב","b":"מובא בירושלמי (מגילה פ\"א ה\"י), והוא יוסף בן אלם."},{"i":837,"n":"בן אלעשה","l":"ב","b":"חתנו של רבי. לא נמנה על החכמים ובר קפרא קנטרו על כך. ורבי שהוקיר את חתנו הגיב על כך ואמר לבר קפרא שלעולם לא יתן לו סמיכה (ירו\u0027, מו\"ק רפ\"ג)."},{"i":838,"n":"בן אנטיגנוס","l":"ב","b":"מובא בבבלי (תמורה כ\"א ע\"א). ע\"ע בן אטיטם."},{"i":839,"n":"בן אנטינוס","l":"ב","b":"מובא בבבלי (חלה פ\"ד מי\"א). ע\"ע בן אטיטם."},{"i":840,"n":"בן ארזה","l":"ב","b":"מובא במשנה (שקלים רפ\"ה), שהיה ממונה בבית שני על כלי שיר."},{"i":841,"n":"בן בבי","l":"ב","b":"מובא במשנה (שקלים רפ\"ה), שהיה ממונה בבית שני על הפתילות להדלקת המנורה."},{"i":842,"n":"בן בג בג","l":"ב","b":"תנא שאין לקבוע במדוייק אם חי בימי הלל או בימי רבי יהושע. פתגמו המפורסם: \"הפוך בה והפוך בה דכולה בה\" (אבות פ\"ה מכ\"ב). תוספות (חגיגה ט\u0027 ע\"ב) מביא יש מפרשים שהיה גר. \"יוחסין\" כתב שהוא רבי יוחנן בן בג בג (קידושין י\u0027 ע\"ב), שעליו שלח רבי יהודה בן בתירא \"מוחזקני בך שאתה בקי בחדרי תורה\" (שם)."},{"i":843,"n":"בן בוהיין","l":"ב","b":"מובא בבבלי (פסחים נ\"ז ע\"א). שם אביו היה בוהיין. ובנו מכונה בן בוהיין. ע\"ע בוהיין."},{"i":844,"n":"בן בוכרי","l":"ב","b":"תנא בדור הראשון - השני. העיד ביבנה וכו\u0027 ואמר לו רבן יוחנן בן זכאי וכו\u0027 (שקלים פ\"א מ\"ד)."},{"i":845,"n":"בן בטיח","l":"ב","b":"בן אחותו של רבן יוחנן בן זכאי ע\"ע אבא סקרא. היה איש גבה קומה ובעל אברים גדולים. מובא במשנה (כלים פי\"ז מי\"ב): \"אגרוף גדול זהו אגרופו של בן בטיח\"."},{"i":846,"n":"בן ביבאי","l":"ב","b":"מובא בבבלי (יומא כ\"ג ע\"א), והוא בן בבי."},{"i":847,"n":"בן ביבי","l":"ב","b":"מובא בירושלמי (מע\"ש ספ\"ג), והוא ר\u0027 יוסה בן ביבי."},{"i":848,"n":"בן בנו של זכריה בן קבוטל","l":"ב","b":"תנא בדור החמישי. חברו של זכריה בן קבוטל. שמו לא נזכר בש\"ס."},{"i":849,"n":"בן בתירא","l":"ב","b":"מובא בבבלי (שבת ק\"כ ע\"א). סתם בן בתירא הוא רבי יהושע בן בתירא (רמב\"ם בהקדמתו לזרעים). ע\"ע רבי יהודה בן בתירא ב\u0027, ר\u0027 יהושע בן בתירא ורבי שמעון בן בתירא."},{"i":850,"n":"בן גבר","l":"ב","b":"מובא במשנה (שקלים רפ\"ה), שהיה ממונה בבית שני על נעילת שערים."},{"i":851,"n":"בן גמלא","l":"ב","b":"מובא בבבלי (יומא ל\"ז ע\"א), והוא יהושע בן גמלא כהן גדול."},{"i":852,"n":"בן דופאי","l":"ב","b":"מובא בתוספתא (שקלים ספ\"ב), שהיה ממונה בבית שני על הלולב."},{"i":853,"n":"בן דורתאי","l":"ב","b":"ע\"ע יהודה בן דורתאי."},{"i":854,"n":"בן דמה","l":"ב","b":"מובא בבבלי (מנחות צ\"ט ע\"ב), והוא אלעזר בן דמה."},{"i":855,"n":"בן הא הא","l":"ב","b":"תנא. מובא באבות (ספ\"ה). ובתוי\"ט מביא בשם הרשב\"ם שמובא במדרש שמואל, שבן הא הא ובן בג בג - היו גרים. וכן כתבו התוספות (חגיגה ט\u0027 ע\"ב)."},{"i":856,"n":"בן הסגן","l":"ב","b":"מובא בבבלי (יומא מ\"ד ע\"ב), והוא רבי שמעון בן הסגן."},{"i":857,"n":"בן הקפר","l":"ב","b":"מובא (ירו\u0027, פ\"ו ה\"א), והוא רבי אלעזר הקפר."},{"i":858,"n":"בן הרכינס","l":"ב","b":"מובא בירושלמי (יבמות פ\"א ה\"ו), והוא רבי דוסא בן הרכינס."},{"i":859,"n":"בן זומא","l":"ב","b":"מובא באבות (רפ\"ד), והוא שמעון בן זומא."},{"i":860,"n":"בן זכאי א\u0027","l":"ב","b":"מובא בבבלי (סנהדרין מ\"א ע\"ב), והוא רבן יוחנן בן זכאי, כשהיה עוד כתלמיד היושב לפני רבו."},{"i":861,"n":"בן זכאי ב\u0027","l":"ב","b":"מובא בבבלי (חולין נ\"ב ע\"א). לגירסת רש\"י: בר זכאי. וגיר\u0027 התוס\u0027: עולא בן רבי זכאי. ע\"ע עולא בר ר\u0027 זכאי."},{"i":862,"n":"בן חכינאי (2)","l":"ב","b":"מובא בבבלי (שבת קמ\"ז ע\"ב), והוא רבי חנניה בן חכינאי."},{"i":863,"n":"בן טוטפת","l":"ב","b":"מובא בתוספתא (שקלים ספ\"ב), שהיה ממונה בבית שני על המפתחות."},{"i":864,"n":"בן יאסין","l":"ב","b":"תנא בדור השלישי. מובא בבבלי (יבמות צ\"ח ע\"א). חי בדורו של ר\"ע (שם)."},{"i":865,"n":"בן יהוצדק","l":"ב","b":"מובא בירושלמי (סוכה פ\"ה ה\"ד), שבזמן בית שני היה מהחסידים ואנשי מעשה. השתבח בקפיצותיו בשמחת בית השואבה."},{"i":866,"n":"בן כוברי","l":"ב","b":"והוא בן בוכרי."},{"i":867,"n":"בן כוזיבא","l":"ב","b":"מובא בבבלי (יבמות ע\"ב ע\"א). ע\"ע בר כוכבא."},{"i":868,"n":"בן כלבא שבוע","l":"ב","b":"חי בדור חורבן בית שני. היה אחד מעשירי ירושלים (גיטין נ\"ו ע\"א). חותנו של רבי עקיבא (כתובות ס\"ב ע\"ב). לאחר שר\"ע למד והיה גדול בתורה נתן לו מחצית רכושו. (שם ס\"ג ע\"א). במגלת יוחסין בירושלים מצאו, שכתוב בה שהיה מיוצאי חלציו של כלב (ירו\u0027, תענית פ\"ד ה\"ב)."},{"i":869,"n":"בן מארא","l":"ב","b":"מובא בתנחומא (הישן ריש בהר). ב\"יוחסין\" ו\"סה\"ד\" הגיר\u0027: בן מאדא."},{"i":870,"n":"בן מביא יין","l":"ב","b":"מובא בירושלמי (פסחים ספ\"ד), והוא בן בוהיין."},{"i":871,"n":"בן מעדיה","l":"ב","b":"מובא בירושלמי (דמאי פ\"ב ה\"א). ר\u0027 יוסי דכפר דן אמר בשמו."},{"i":872,"n":"רבי בן מעדיה","l":"ב","b":"מובא בירושלמי (דמאי פ\"ב ה\"א) ו\"סה\"ד\" גרס (בערך ר\u0027 יוסי דכפר דן) \"מערייה\"."},{"i":873,"n":"בן מקליט","l":"ב","b":"מובא בתוספתא (שקלים ספ\"ב), שהיה ממונה בבית שני על המלח."},{"i":874,"n":"בן נזירא","l":"ב","b":"מובא בירושלמי (שקלים ספ\"ב), ע\"ע בר טירא."},{"i":875,"n":"בן ננס","l":"ב","b":"מובא בבבלי (כתובות צ\u0027 ע\"ב). ע\"ע רבי שמעון בן ננס."},{"i":876,"n":"בן סירא","l":"ב","b":"שמו המלא היה יהושע בן סירא. מחכמי ישראל בימי הזוגות. כתב \"ספר בן סירא\" ובו דברי חכמה ומוסר השכל. מובא פעמים רבות בש\"ס: \"כתוב בספר בן סירא\" (חגיגה י\"ג ע\"א ועוד). נראה שספר בן סירא היה הראשון לאחר כתבי הקדש (תוספתא ידים פ\"ה). בכל זאת פסק רב יוסף (סנהדרין ק\u0027 ע\"ב), שאף בספר בן סירא אסור לקרוא. כנראה שרש\"י ובעלי התוספות לא קראו בו. רש\"י כתב: \"בדקתי אחר המקרא זה, ואינו בכל הכתובים, ושמא בספר בן סירא הוא\" (עירובין ס\"ה ע\"ב ד\"ה: בצר). ותוס\u0027 כתבו: \"אין זה מקרא בכל התורה, ושמא בבן סירא הוא\" (ב\"ק צ\"ב ע\"ב ד\"ה: משולש). ואמנם הפסוקים נמצאים בספר בן סירא."},{"i":877,"n":"בן עזאי","l":"ב","b":"מובא בבבלי (ברכות ס\"ב ע\"א). ע\"ע שמעון בן עזאי."},{"i":878,"n":"בן פדת","l":"ב","b":"הוא רבי אלעזר בן פדת, כמו שכתבו התוספות: \"ואין זה בן פדת, דבן פדת הוא רבי אלעזר בן פדת\" (תמורה י\u0027 ע\"א ד\"ה: איתמר)."},{"i":879,"n":"בן פזי","l":"ב","b":"מובא בבבלי (חולין מ\"ו ע\"א). מצינו, שעולא \"הוה קאימנא קמיה\" (שם), ונראה שזה רבי שמעון בן פזי."},{"i":880,"n":"בן פטורא","l":"ב","b":"תנא. \"דרש בן פטירא מוטב שישתו שניהם וימותו ואל יראה וכו\u0027, עד שבא ר\"ע ולימד\" (ב\"מ ס\"ב ע\"א). מתוך שלא כתוב: \"ור\"ע אומר\", אלא: \"עד שבא ר\"ע\", נראה אולי לומר שחי לפני ר\"ע. \"יתו\"א\" גורס בן פטורין."},{"i":881,"n":"בן פלח","l":"ב","b":"מובא בתוספתא (שקלים ספ\"ב), שהיה ממונה בבית שני על העצים."},{"i":882,"n":"בן ציצית הכסת","l":"ב","b":"חי בדור חורבן בית שני. היה אחד משלושת עשירי ירושלים (גיטין נ\"ו ע\"א). נקרא כן על כי ציצתו נגררה על גבי כסתות. ואיכא דאמרי: \"שהיתה כסותו מוטלת בין גדולי רומי\" (שם)."},{"i":883,"n":"בן קופיא","l":"ב","b":"חי בדור השלישי של התנאים. ספק אם היה חכם. כשגזרו על ר\u0027 יהודה הנחתום שיהרג, רצה בן קופיא להצילו, ונודע למלכות, וגזרו מות גם עליו (מדרש תהלים פ\"ט - ג)."},{"i":884,"n":"בן קטין","l":"ב","b":"כהן גדול. מובא במשנה (יומא ל\"ז ע\"א): \"עשה שנים עשר דד לכיור\" (בבית המקדש)."},{"i":885,"n":"בן ריפאי","l":"ב","b":"מובא בתוספתא (שקלים ספ\"ב). כך הגיר\u0027 בתוספתא צוקרמנדל. ולפנינו: בן דופאי."},{"i":886,"n":"בן שלקות","l":"ב","b":"תנא בדור השלישי - הרביעי. בזמנו של ר\"ע, ורבי עקיבא אמר עליו: \"בן שלקות איני מכיר\" (נדה נ\"ב ע\"ב)."},{"i":887,"n":"בן תימא","l":"ב","b":"מובא בבבלי (פסחים ע\u0027 ע\"א). סביר שהוא ר\u0027 יהודה בן תימא (ע\"ע)."},{"i":888,"n":"רבי בנאה","l":"ב","b":"בדור המעבר בין התנאים לאמוראים. דבריו עוד נזכרו בברייתא (תענית ז\u0027 ע\"א). היה חכם גדול ודיין, והבין רמזים וחידות. המלכות אף מינתה אותו לשופט (ב\"ב נ\"ח ע\"א). רבי יוחנן היה תלמידו (ב\"ב נ\"ח ע\"ב)."},{"i":889,"n":"ר\u0027 בנאה בריה דר\u0027 עולא","l":"ב","b":"מובא בבבלי (פסחים נ\"ד ע\"א). \"סה\"ד\" סובר, שהוא רבינא בריה דר\u0027 עולא (ביצה ג\u0027 ע\"ב)."},{"i":890,"n":"רבי בנאי אחוה דר\u0027 חייא בר אבא","l":"ב","b":"מובא בבבלי (כתובות נ\u0027 ע\"ב), והוא רבנאי אחוה דר\u0027 חייא בר אבא."},{"i":891,"n":"בני בתירא","l":"ב","b":"ע\"ע בן בתירא."},{"i":892,"n":"בני רחבה","l":"ב","b":"מובא בבבלי (סנהדרין כ\"ו ע\"א), והם עיפא בן רחבא מפומבדיתא ואבימי (ע\"ע)."},{"i":893,"n":"ר\u0027 בניי","l":"ב","b":"אמורא, כנראה ארץ ישראלי, שאין לקבוע זמנו המדוייק. אמר בשם שמואל (ירו\u0027, סנהדרין ספ\"ג). ור\u0027 תנחומא מסר משמו (ב\"ר רפ\"ח). ע\"ע ר\u0027 בנייה."},{"i":894,"n":"ר\u0027 בנייה","l":"ב","b":"אמורא שמסר בשם ר\"ה (פדר\"כ כ\"ד), ואולי הוא ר\u0027 בניי."},{"i":895,"n":"בנימין (2)","l":"ב","b":"מובא בתוספתא (שקלים ספ\"ב), שהיה ממונה בבית שני על תנורים."},{"i":896,"n":"רבי בנימין","l":"ב","b":"תנא בדור הרביעי. מתלמידי רבי עקיבא ומסר בשמו (שמחות רפ\"ט). חלק עם רבי אלעזר [בן שמוע] (כתובות פ\"ד ע\"א)."},{"i":897,"n":"בנימין בר איהי","l":"ב","b":"ע\"ע מנימין בר איהי."},{"i":898,"n":"בנימין בר אשתור","l":"ב","b":"אמורא בדור השלישי - הרביעי. תלמידו של רבי חייא בר אבא (ירו\u0027, בכורים פ\"א ה\"ד). \"פני משה\" כתב (שם) ש\"היה מבני גרים\"."},{"i":899,"n":"רבי בנימין בר גידל","l":"ב","b":"אמורא בדור הרביעי. הוא ור\u0027 אחא חלקו בדברי ר\u0027 יוסי בר חנינא (ירו\u0027, יבמות רפ\"א). מסר בשם רבי יוחנן (חולין קכ\"ה ע\"א)."},{"i":900,"n":"ר\u0027 בנימין בר חייא","l":"ב","b":"מובא בבבלי (סוף ר\"ה): \"אבא בריה דרב בנימין בר חייא\"."},{"i":901,"n":"בנימין בר יפת","l":"ב","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (ברכות ל\"ח ע\"ב). ר\"ז אמר עליו, שאינו מדייק בשמועותיו כמו רב חייא בר אבא (שם). מסר בשם רבי אלעזר (יומא כ\"ט ע\"א)."},{"i":902,"n":"רבי בנימין בר לוי","l":"ב","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של רב אמי (ירו\u0027, פאה רפ\"א). רבין אמר בשמו (ירו\u0027, פסחים פ\"ז ה\"ו)."},{"i":903,"n":"בנימין גנוביא (2)","l":"ב","b":"לפי גירסת ה\"יוחסין\" ו\"סה\"ד\", מובא בשם רב - דין מוטעה, ושמואל שמע - ואיקפיד, ומת בנימין, וקרא עליו: \"ברוך שנגפו\" (ירו\u0027, ברכות פ\"ב ה\"ו)."},{"i":904,"n":"בנימין גר מצרי","l":"ב","b":"מובא (ירו\u0027, יבמות פ\"ח ה\"ב), והוא מנימין גר מצרי."},{"i":905,"n":"בנימין הצדיק","l":"ב","b":"תנא שאין לקבוע זמנו המדוייק. מובא בבבלי (ב\"ב י\"א ע\"א), שהיה ממונה על קופה של צדקה. פעם פרנס אשה משלו, וכשנטה למות הוסיפו לו 22 שנה על שנותיו (שם). \"סה\"ד\" כתב שמקום מנוחתו בעיר רומי."},{"i":906,"n":"בנימין רעיא","l":"ב","b":"חי בזמנו של רב. מובא בבבלי (ברכות מ\u0027 ע\"ב): \"כרך ריפתא ואמר: \u0027בריך מריה דהאי פיתא\u0027, אמר רב...\" גיר\u0027 \"יוחסין\": רבא. אין הכרעה מוחלטת שהיה אמורא."},{"i":907,"n":"בנן של קדושים","l":"ב","b":"ע\"ע רבי מנחם ברבי סימאי."},{"i":908,"n":"ר\u0027 בצלאל","l":"ב","b":"אמורא ארץ ישראלי בדור השלישי. רבי ברכיה אמר בשמו (שהש\"ר ספ\"ג). ונראה שצ\"ל כן בבמד\"ר (פי\"ב - ח\u0027) ושם ר\u0027 בצלה."},{"i":909,"n":"בר אבוה","l":"ב","b":"שכנו של אביי. ואביי היה מברך (ברכת מאורי האש בהבדלה) אדבי בר אבוה (ברכות נ\"ג ע\"ב). אין לדעת אם היה חכם."},{"i":910,"n":"בר אבין","l":"ב","b":"דרשן וספדן. האריך ימים, שהרי מצינו אותו דורש בפני רבא (מו\"ק כ\"ה ע\"ב), והוא וחברו בר קיפוץ היו ספדנים בימי רב אשי (שם). נענש ע\"י רב אשי ונהפכו רגליו (שם)."},{"i":911,"n":"בר אדא בר אחוה דר\u0027 יהודה","l":"ב","b":"אמורא בבלי בדור השלישי. ר\u0027 זירא אמר משמו (ירו\u0027, בכורים פ\"א ה\"ה)."},{"i":912,"n":"בר אדא מרי","l":"ב","b":"אמורא בבלי בדור השלישי. מובא בבבלי (זבחים ל\"ח ע\"א): \"אמר רבא: \u0027בר אדא מרי אסברה לי\u0027\"."},{"i":913,"n":"בר אדא משחאה","l":"ב","b":"נראה שהוא רב אדא משוחאה (ע\"ע)."},{"i":914,"n":"בר אדא סבולאה","l":"ב","b":"חי בבבל בדור החמישי לאמוראים. היה לו דין תורה בפני רב פפא (ב\"מ צ\"ג ע\"ב). \"סה\"ד\" כתב: \"לא ידעתי אם חכם היה\"."},{"i":915,"n":"בר אהינא","l":"ב","b":"אמורא בבלי בדור השלישי. היה מרבותיו של רבא: \"אמר רבא: \u0027בר אהיני אסברא לי\u0027\" (סוטה ל\"ט ע\"ב). אפשר שהוא רבא בר אהיני (מנחות ל\"ז ע\"ב), ושם מובאת דעתו אחרת מר\u0027 יוסף."},{"i":916,"n":"בר אושפזתי","l":"ב","b":"מובא בבבלי (תענית כ\"ד ע\"ב), והוא רב פפא. גירסתו של \"הערוך\": אושפרתי, וזה שם אמו של רב פפא."},{"i":917,"n":"בר אלנתן","l":"ב","b":"מובא באיכ\"ר (בפתיחתא)."},{"i":918,"n":"בר ביבי בר גידל","l":"ב","b":"אמורא בבלי בדור השני - השלישי. תלמידו של ר\u0027 שמעון חסידא (ב\"ק קי\"ג ע\"ב)."},{"i":919,"n":"בר הדיא","l":"ב","b":"פותר חלומות שחי בזמן אביי ורבא. לאביי, שנתן לו כסף, פתר טוב: ולרבא שלא נתן לו כסף, פתר רע: פתרונותיו התגשמו ורבא כינהו: \"רשע\" (ברכות נ\"ו ע\"א). אין להעלות על הדעת שהיה חכם."},{"i":920,"n":"בר הדיא א\u0027","l":"ב","b":"אמורא בדור השלישי - הרביעי. תלמידו של רבי אמי (חולין ק\"ו ע\"ב). אביי הקשה על דבריו (מו\"ק י\"ח ע\"א). אין זה בר הדיא פותר החלומות שרבא כינהו: \"רשע\" (ברכות נ\"ו ע\"א)."},{"i":921,"n":"בר הי הי","l":"ב","b":"תנא בדור הראשון. שאל את הלל (חגיגה ט\u0027 ע\"ב). זכה לגילוי אליהו הנביא (שם). תוספות כתבו: \"ויש מפרשים שגר היה\" (שם). היימן כתב (ע\u0027 582 ערך בר הא הא) שהלל זה הוא אמורא, ולא הלל הזקן, וא\"כ הפך את בר הי הי מתנא בדור הראשון, לאמורא."},{"i":922,"n":"בר הידיא","l":"ב","b":"מובא בבבלי (מו\"ק י\"ח ע\"ב), והוא בר הדיא. כן גירסת הר\"ח."},{"i":923,"n":"בר הינך","l":"ב","b":"מובא בבבלי (פסחים ק\"א ע\"ב). ע\"ע רב הינך."},{"i":924,"n":"בר המדודי","l":"ב","b":"ע\"ע בר המדורי."},{"i":925,"n":"בר המדורי","l":"ב","b":"אמורא בבלי בדור השלישי. תלמידו של שמואל (יומא פ\"ז ע\"ב). האריך ימים והיה רבו של רבא (שבת ק\"ז סע\"ב)."},{"i":926,"n":"בר זעירא","l":"ב","b":"מובא במדרש שמואל (פי\"ז) וצ\"ל רבי זירא."},{"i":927,"n":"בר חבו","l":"ב","b":"כותב תפילין בזמנו של אביי (מגילה י\"ח ע\"ב: וב\"מ כ\"ט ע\"ב). אין להכריע שהיה חכם."},{"i":928,"n":"בר חוטא","l":"ב","b":"מובא בשהש\"ר (פ\"ה - ד\u0027), ואולי צ\"ל: בר חטייא."},{"i":929,"n":"בר חוניא","l":"ב","b":"מובא (משלי פכ\"ב - ב\u0027), ואולי צ\"ל: בר חטייא."},{"i":930,"n":"בר חטייא (2)","l":"ב","b":"אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. מובא מספר פעמים בב\"ר. פעם מובא בב\"ר שמו המלא: \"שמעון בר חוטא\" (פכ\"ו - ג\u0027). רבי עזריה (תלמידו של רבי מנא) מסר בשמו (שם נ\"ג - י\"ב)."},{"i":931,"n":"בר טברי (2)","l":"ב","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. שאל את רבי יצחק (ירו\u0027, מגילה פ\"ד ה\"י)."},{"i":932,"n":"בר טירא","l":"ב","b":"אמורא ארץ ישראלי בדור הראשון - השני. מובא בירושלמי (מו\"ק פ\"ג ה\"ז). וגירסא אחרת מצאנו לאותו ענין: ר\u0027 שמעון בר נזירא (ירו\u0027, שקלים פ\"ב ה\"ה). ובבבלי: \"אמר ר\u0027 יצחק בר זעירא, ואיתימא שמעון נזירא\" (יבמות צ\"ז ע\"א), ונראה שאחד הוא."},{"i":933,"n":"בר יודני","l":"ב","b":"מובא בירושלמי (תרומות פ\"ח דפוס ווינציא), וצ\"ל: בר נטיזא."},{"i":934,"n":"בר ינטה","l":"ב","b":"מובא בירושלמי (תענית פ\"ד ה\"ה)."},{"i":935,"n":"בר ישיטה","l":"ב","b":"אמורא ארץ ישראלי בדור הרביעי. בנו של ר\u0027 חיננא (ירו\u0027, מגילה פ\"ד ה\"י). היה אמורא של ר\u0027 אבהו (שם)."},{"i":936,"n":"בר כדה","l":"ב","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מובא בירושלמי: \"בר כרה (צ\"ל כדה) אמר רבי אבהו\". (פאה פ\"ז ה\"ב)."},{"i":937,"n":"בר כוזבה","l":"ב","b":"מובא בירושלמי (תענית פ\"ד ה\"ה). ע\"ע בר כוכבא."},{"i":938,"n":"בר כוכבא","l":"ב","b":"חי בדור השלישי לתנאים. רבי עקיבא אמר עליו שהוא משיח, ודרש עליו: \"דרך כוכב מיעקב\" (ירו\u0027, תענית פ\"ד ה\"ה). מלך שלוש וחצי שנים. עמד בראש מרד ביתר. מספר חייליו היה ארבע מאות אלף. מאתיים אלף מהם קטעו לעצמם בוהן כאות לאומץ לב, ומאתיים אלף האחרים - עקרו עץ ברכיבה על סוס (שם). שלוש וחצי שנים צר אדריינוס על ביתר עד שנפלה. בר כוכבא נהרג ע\"י נחש ואדריינוס אמר עליו, שאילולי אלקים הרגו מי יכול להרגו (שם). סיבת נפילת ביתר לפי המסופר (שם) היתה, שבר כוכבא הרג את דודו התנא רבי אליעזר המודעי בגלל חשד שוא, שרצה להסגיר את ביתר לאדריינוס."},{"i":939,"n":"בר כרא","l":"ב","b":"הוא בר כדה."},{"i":940,"n":"בר לוליתא","l":"ב","b":"אמורא ארץ ישראלי בדור השני. תלמידו של רבי חייא (ירו\u0027, חלה פ\"ב ה\"ג). מסר בשם רבי יהושע בן לוי (שם)."},{"i":941,"n":"בר ליואי א\u0027","l":"ב","b":"מובא בבבלי (כתובות ע\"ז ע\"ב), והוא רבי יהושע בן לוי."},{"i":942,"n":"בר ליואי ב\u0027","l":"ב","b":"אמורא בבלי בדור השני. תלמידו של מר עוקבא (שבת ק\"ח ע\"ב). אין זה בר ליואי הידוע, שהוא רבי יהושע בן לוי (ע\"ע)."},{"i":943,"n":"בר לקיש","l":"ב","b":"מובא בבבלי (מגילה כ\"ח ע\"ב). ע\"ע רבי שמעון בן לקיש."},{"i":944,"n":"בר מריון","l":"ב","b":"חי בבבל בדור הרביעי לאמוראים, היה עשיר גדול ובא לברר דין לפני אביי (ב\"מ כ\"ד ע\"ב). גם בניו היו עשירים (ב\"ב ח\u0027 ע\"א). אין ראיה שנמנה עם החכמים."},{"i":945,"n":"בר מרינא","l":"ב","b":"אמורא ארץ ישראלי בדור הרביעי. בירך על הפת לפני ר\"ז ור\u0027 חייא בר אבא (ירו\u0027, ברכות פ\"ו ה\"א). שאל מרבי אמי (ירו\u0027, שבת רפי\"ט)."},{"i":946,"n":"בר נטוזא","l":"ב","b":"מובא בירושלמי (תרומות פ\"ח), וצ\"ל: בר נטיזא."},{"i":947,"n":"בר נטיזא","l":"ב","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. שאל לר\u0027 אבא בר ממל (ירו\u0027, ע\"ז פ\"ב ה\"ג)."},{"i":948,"n":"בר נפחא","l":"ב","b":"והוא רבי יוחנן, כך פירש רש\"י (סנהדרין צ\"ו ע\"א). ומכונה כך על שם יופיו."},{"i":949,"n":"בר נתן","l":"ב","b":"מובא בבבלי (מו\"ק כ\"ח ע\"א), והוא רב הונא בר נתן (כמוכח גיטין נ\"ט ע\"א תד\"ה: והא)."},{"i":950,"n":"בר נתן אסיא","l":"ב","b":"כך גירסת בעל \"יתו\"א\", ולפנינו: רב נתן בר אסיא (פסחים נ\"ב ע\"א)."},{"i":951,"n":"בר סירא","l":"ב","b":"מובא בירושלמי (חגיגה פ\"ב ה\"א), והוא בן סירא."},{"i":952,"n":"בר עולא","l":"ב","b":"אמורא ארץ ישראלי בדור הרביעי. ר\u0027 יונה ור\u0027 יוסי שאלו ממנו (ירו\u0027, שבת פ\"ד ה\"ב)."},{"i":953,"n":"בר עיטיין","l":"ב","b":"מובא בירושלמי: \"ר\u0027 יסא בשם רבנין וכו\u0027 מבי מדרשא דבר עיטיין\" (ב\"ב פ\"ו ה\"א)."},{"i":954,"n":"בר פאטי","l":"ב","b":"מובא במסכת סופרים (פי\"ב). ע\"ע לוי בר בוטי."},{"i":955,"n":"בר פדא","l":"ב","b":"אמורא ארץ ישראלי בדור הראשון. בן אחותו ותלמידו של בר קפרא (מעילה ד\u0027 ע\"ב). שמו שובש בכמה פנים: בר פדייה, ר\u0027 פדיה, והוא רבי יהודה בן פדייה. היה מרבותיו של אילפא: \"אילפא אמרה קמיה דרב פדא\" (זבחים י\"ג ע\"ב), וכן היה רבו דרבי יוחנן (ירו\u0027, שבת פ\"א ה\"ב). תוספות כתבו: \"זהו בר פדא בן אחותו של בר קפרא\" (תמורה י\u0027 ע\"א ד\"ה: איתמר בר פדא)."},{"i":956,"n":"בר פדייה","l":"ב","b":"הוא בר פדא."},{"i":957,"n":"בר פחתי","l":"ב","b":"כך קרא רבי חייא לרב (שבת ג\u0027 ע\"ב) ופרש\"י: \"בן גדולים\"."},{"i":958,"n":"בר פיולי","l":"ב","b":"מנקר בזמן שמואל ועמד לפני שמואל וניקר (חולין צ\"ו ע\"א), ואין הוכחה שנמנה עם החכמים."},{"i":959,"n":"בר פיקא","l":"ב","b":"מובא בירושלמי ששאל לרבי וכו\u0027, א\"ל רבי: \"בר פיקא עומד בשטותו\" (נזיר פ\"ט ה\"ב). אין להכריע לאיזה רבי הכונה שכן כל הנשיאים מרבי ואילך מכונים לעתים בירושלמי: \"רבי\" (סיווגתיו לרבי הראשון והוא רבינו הקדוש)."},{"i":960,"n":"בר פתייא","l":"ב","b":"הוא בר פדא."},{"i":961,"n":"בר קזא","l":"ב","b":"מובא בבבלי (כתובות ק\"ד ע\"א): \"אר\"נ בר יצחק: תני רב יהודה בר קזא במתניתא דבי בר קזא\" פרש\"י \"שם חכם\"."},{"i":962,"n":"בר קיפוף","l":"ב","b":"ספדן שחי בדור הרביעי לאמוראי בבל והאריך ימים עד ימי רב אשי, ונענש מפני שבגללו חלשה דעתו דרב אשי (מו\"ק כ\"ה ע\"ב) אין ראיה כי נמנה עם החכמים."},{"i":963,"n":"רבי בר קיריא","l":"ב","b":"כן הגיר\u0027 בירושלמי (כלאים פ\"ט ה\"ג). יש גורסים: רבה בר קיריא (שם), ובפס\u0027 רבתי (פ\u0027 דשבת ור\"ח - ו\u0027) הגיר\u0027: ר\u0027 ברוקאי."},{"i":964,"n":"בר קפרא","l":"ב","b":"תנא בדור המעבר בין התנאים לאמוראים. תלמידו של רבי (יבמות ל\"ב ע\"ב). לדעת הרמב\"ם (בהקדמתו לזרעים) היה מבית דינו של רבי. רבי עצמו שאל ממנו (פסחים מ\"ב ע\"א). היה חברו של רבי חייא (יבמות שם) ושל חזקיה בנו של ר\u0027 חייא, ועל שניהם - חזקיה ובר קפרא - אומרים התוספות שהיו תנאים (ע\"ז ל\"ח ע\"ב). גדולי דור הראשון לאמוראי א\"י קיבלו ממנו. על רבי אושעיא נאמר מפורש שהיה תלמידו (מו\"ק כ\"ד ע\"א). רבי יהושע בן לוי מסר משמו (ברכות ל\"ד ע\"א), וכן ר\"ל (פסחים ט\"ו ע\"א). קיבץ הלכות שנקראו \"משנת בר קפרא\" (ב\"ב קנ\"ד ע\"ב). פעם העליב את חתנו של רבי, ורבי הקפיד עליו ואמר לו: \"איני מכירך רבי [שלא יסמכהו]\" (ירו\u0027, מו\"ק רפ\"ג). היה בפטירתו של רבי וקרע בגדיו ואמר: \"אראלים ומצוקים אחזו בארון הקודש וכו\u0027 ונשבה ארון הקודש\" (כתובות ק\"ד ע\"א). היה גם דרשן ובעל משלים וחידות (נדרים נ\"א ע\"א, ויק\"ר כ\"ח - ב\u0027). הגיע לזקנה (ברכות ל\"ט ע\"א), וכאשר כעס על שני תלמידיו אמר להם על עצמו: \"אם חכמה אין כאן, זקנה אין כאן\", פרש\"י: \"והלא זקן אני\". ולא יתכן לפרש זקן נסמך, כי לא נסמך מעולם (ירו\u0027, מו\"ק רפ\"ג)."},{"i":965,"n":"בר רב זביד אחוה דר\"ש בר ר\u0027 זביד","l":"ב","b":"מובא בבבלי (ברכות ל\"ח ע\"א). ע\"ע רב זביד אבוה דר\u0027 שמעון בר זביד."},{"i":966,"n":"בר רחומי","l":"ב","b":"מובא בבבלי (נזיר י\"ג ע\"א) ששאל מאביי. ע\"ע רב רחומי א\u0027."},{"i":967,"n":"רב בר שבא","l":"ב","b":"אמורא בבלי בדור החמישי. נראה שהאריך ימים, שכן היה בביתו של רב נחמן בהיותו תלמיד (חולין קי\"א ע\"א) וסירב לאכול ורב נחמן הורה להלעיטו בעל כורחו, שאל מרב פפא (עירובין ל\"ג ע\"ב), ושקיל וטרי עם רב כהנא [רבו של רב אשי], (מו\"ק כ\"ו ע\"א). ואיקלע לגבי רבינא, ורבינא לא הפסיק ב\"הלל\" לשאול בשלומו, שכן שלא היה חשוב לגביו (ברכות י\"ד ע\"א). \"דק\"ס\" גרס בברכות: \"רבא בר שבא\" (תלמידו של רבינא)."},{"i":968,"n":"בר שלמיא ספרא","l":"ב","b":"סופר בארץ ישראל בדור הששי לאמוראים. שאל מרבי מנא, שאמר על השאלה, שיש להסתפק בה הרבה (ירו\u0027, תענית פ\"ד ה\"א)."},{"i":969,"n":"בר שפיר","l":"ב","b":"כך גירסת יחוסי תנאים ואמוראים ולפנינו הגירסא רב שפיר (מו\"ק י\"א ע\"א)."},{"i":970,"n":"רב בר שרביא","l":"ב","b":"אמורא בבלי בדור הששי. היה לו דין תורה לפני רב פפא, ו\"דק\"ס\" גרס רב בר שבא (שבועות ל\u0027 ע\"ב)."},{"i":971,"n":"בר תוטני","l":"ב","b":"אמורא ארץ ישראלי בדור הראשון. ר\"ל מסר משמו (שבת ע\"א ע\"א)."},{"i":972,"n":"ברדלא","l":"ב","b":"מובא בבבלי (מכות י\"ד ע\"ב): \"אמר רבי יוחנן: \u0027תני ברדלא\u0027\", ופרש\"י: \"שם חכם\"."},{"i":973,"n":"רב ברדלא בר טביומי","l":"ב","b":"אמורא בבלי בדור השני. תלמידו של רב (חגיגה ה\u0027 ע\"א)."},{"i":974,"n":"ברוך רבו דרבי יהודה בר אלעאי","l":"ב","b":"מובא בירושלמי (תענית פ\"ד ה\"ה): \"תני א\"ר יהודה בן ר\u0027 אלעאי ברוך ר\u0027 היה דורש\", ולי נראה שיש כאן איזה ט\"ס ולא ידעתי מהו כי לא מצינו לרבי יהודה התנא רבי ושמו ברוך."},{"i":975,"n":"רב ברונא","l":"ב","b":"אמורא בבלי בדור השני. תלמידו המובהק של רב (פסחים ק\"ג ע\"א). כן קיבל משמואל (עירובין ע\"ד ע\"א). חברם של רב חננאל (פסחים שם) ושל רבי אלעזר (ברכות ט\u0027 ע\"ב, לגיר\u0027 \"דק\"ס\" ו\"סה\"ד\"). מצינו אותו עם רב יהודה (עירובין ס\u0027 ע\"א). ר\u0027 טבלא אמר בשמו (סנהדרין כ\"ח ע\"ב). רבי אלעאי שלח מארץ ישראל לשאול בשלומו וקרא לו \"אחי\" (ברכות ט\u0027 ע\"ב)."},{"i":976,"n":"ר\u0027 ברוקא","l":"ב","b":"מובא בזהר חדש (בראשית פ\u0027 ויטע)."},{"i":977,"n":"ר\u0027 ברוקא חוזאה","l":"ב","b":"מובא בבבלי (תענית כ\"ב ע\"א), שאליהו הנביא היה שכיח אצלו."},{"i":978,"n":"ר\u0027 ברוקאי","l":"ב","b":"אמורא ארץ ישראלי בדור השני. חברו של רבי אלעזר בן פדת (פס\u0027 רבתי פ\u0027 דשבת ור\"ח - ו\u0027). אבל בירושלמי הגירסא: רבי בר קיריא (כלאים פ\"ט ה\"ג), ויש גורסים: רבה בר קיריא."},{"i":979,"n":"ברוריה","l":"ב","b":"אשה חכמה ומלומדת בדור הרביעי של התנאים. בתו של התנא רבי חנניה בן תרדיון, שנהרג על קידוש ה\u0027, ואשתו של התנא המפורסם רבי מאיר (ע\"ז י\"ח ע\"א). אשה יחידה שהשתתפה במשא ומתן הלכתי עם התנאים. שמה מובא בשני התלמודים כאחד התנאים. ר\u0027 יהודה מכריע כדעתה: \"יפה אמרה ברוריא\" (ריש תוספתא כלים לפי גיר\u0027 אור הגנוז). בס\u0027 \"כריתות\" (לשון לימודים שער ב\u0027 ס\u0027 צ\"ג) נאמר: \"בת ר\u0027 חנינא בן תרדיון חולקת עם אביה והלכה כדבריה\". היתה לומדת כל יום שלוש מאות הלכות (פסחים ס\"ב ע\"ב). שני בניה מתו בחייה, בשבת (מדרש משלי פרק ל\"א). במסכת ע\"ז (י\"ח ע\"ב עיין שם רש\"י) מסופר: \"פעם אחת ליגלגה על שאמרו חכמים: \u0027נשים דעתן קלות\u0027, וציוה [ר\"מ] לאחד מתלמידיו לנסותה לדבר עבירה, והפציר בה ימים רבים עד שנתרצית, וכשנודע לה חנקה עצמה\"."},{"i":980,"n":"בריבי (2)","l":"ב","b":"תנא דברייתא ששמו בריבי. \"תנא, בריבי אומר: \u0027לא הרגו\u0027\" (מכות ה\u0027 ע\"ב), ופרש\"י: \"כך היה שמו\", וכן פרש\"י: \"שם חכם\" (חולין נ\"ב ע\"ב). ל\"בריבי\" משמעות נוספת והיא גדול הדור, וכאשר כתוב: \"ר\u0027 יהודה בריבי אומר\", או \"אחאי בריבי\", המשמעות היא תיאור גדולתו (ע\"ע בריבי). במקום אחר מפקפק רש\"י בד\"ה: \"התניא בריבי אומר: \u0027לא ידעינון מנו אלא אחד גדול בדור היה וכו\u0027\" (חולין י\"א ע\"ב)."},{"i":981,"n":"בריה דרב אידי בר אבין","l":"ב","b":"אמורא בבלי בדור החמישי. מובא בבבלי: \"רב פפא ורב הונא בריה דרב יהושע איקלעי לבי בריה דרב אידי בר אבין, ועביד להו עיגלא תילתא\" (שבת קל\"ו ע\"א)."},{"i":982,"n":"בריה דרב זוטרא בריה דרב זירא","l":"ב","b":"ע\"ע בריה דרב זוטרא בריה דרב זעירא."},{"i":983,"n":"בריה דרב זוטרא בריה דרב זעירא","l":"ב","b":"מובא בבבלי (נדרים ע\"ז ע\"א). אביו רב זוטרא ואבי אביו רב זעירא לא מובאים שוב בש\"ס, ואין מהם תורה או מימרא כלשהי. ובמקום אחר (שבת קנ\"ז ע\"א) הגיר\u0027 זירא במקום זעירא."},{"i":984,"n":"רב בריה דשמואל","l":"ב","b":"אמורא בבלי בדור השני. מסר בשם שמואל (מד\u0027 תהלים רפ\"ט). \"סה\"ד\" שיבש השם וכתב שצ\"ל: רבה בר שמואל. \"סה\"ד\" ו\"יוחסין\" סוברים שרבה בר שמואל היה בנו של שמואל."},{"i":985,"n":"רבי ברייס","l":"ב","b":"אמורא ארץ ישראלי בדור השני. מובא בבבלי: \"ר\u0027 תנחום ור\u0027 ברייס אמרו משום זקן אחד, ומנו: ר\u0027 יהושע בן לוי\" (ב\"ק פ\"ב ע\"א)."},{"i":986,"n":"רבי ברכיה","l":"ב","b":"אמורא ארץ ישראלי בדור הרביעי. מגדולי בעלי האגדה. רבו המובהק היה רבי חלבו (ירו\u0027, כלאים פ\"ט ה\"ג): בשמו מסר את רוב מאמרי האגדה, וכן מסר מכל גדולי הדור ובשם אביו (תנחומא בובר חיי שרה ו\u0027). ושניהם יחד מוסרים דברי אגדה (ויק\"ר ל\u0027 א\u0027). נראה שאולי אביו הוא ר\u0027 חמא (לגיר\u0027 \"סה\"ד\") או ר\u0027 חייא. ר\u0027 מנא, מגדולי הדור הרביעי, קרא לו: \"רבי\" (ירו\u0027, יבמות פ\"ד הי\"א). אחיו, רבי שמואל היה מחכמי ההלכה (ירו\u0027, ערלה רפ\"ב). כן נזכר בן בתו של ר\u0027 ברכיה (ב\"ר פ\"ט - ה\u0027)."},{"i":987,"n":"ר\u0027 ברכיה בר אבא בר כהנא","l":"ב","b":"מובא בבמד\"ר (פ\"ט - מ\"ח), ונראה שהוא ט\"ס, כי המקור בירושלמי, ושם: \"ר\u0027 ברכיה [בשם] ר\u0027 אבא בר כהנא\" (סוטה פ\"ג ה\"ד)."},{"i":988,"n":"ר\u0027 ברכיה בר אבוה","l":"ב","b":"מובא ב\"ילקוט\" (הושע רמז תקכח). ואולי צ\"ל: ר\u0027 ברכיה [בשם] ר\u0027 אבהו."},{"i":989,"n":"ר\u0027 ברכיה בר חייא הכהן","l":"ב","b":"מובא בויק\"ר (רפ\"ל). גיר\u0027 \"יוחסין\" ו\"סה\"ד\": חמא במקום חייא (אולי משני יודין נעשה מ\"ם). יש סבורים שזה רבי ברכיה המפורסם באגדה (ע\"ע)."},{"i":990,"n":"ר\u0027 ברכיה בר חמא הכהן","l":"ב","b":"ויש גור\u0027: ר\u0027 ברכיה בר חייא הכהן (ע\"ע). ויש סבורים שזה רבי ברכיה המפורסם באגדה (ע\"ע)."},{"i":991,"n":"ר\u0027 ברכיה בר חנינא בר איקא","l":"ב","b":"מובא במדרש תהלים (פע\"ח - י\"א)."},{"i":992,"n":"ר\u0027 ברכיה בר יהודה ב\"ר סימון","l":"ב","b":"מובא בב\"ר (פנ\"ג - ח)."},{"i":993,"n":"ר\u0027 ברכיה בר יעקב בר בת יעקב","l":"ב","b":"מובא בירושלמי (מע\"ש פ\"ה ה\"א), וצ\"ל: ר\u0027 ברכיה יעקב (ולא בר יעקב). והמשמעות: ר\u0027 ברכיה [בשם] יעקב בר בת יעקב, כמובא בירושלמי (מו\"ק פ\"א ה\"ב)."},{"i":994,"n":"ר\u0027 ברכיה בר יצחק","l":"ב","b":"מובא במדרש שמואל (פ\"כ - ז\u0027), וכן מובא בתוספות (סוטה מ\"ב ע\"ב ד\"ה: מאה). הגיר\u0027 ברו\"ר (פ\"ב - כ): ר\u0027 ברכיה בשם ר\u0027 יצחק."},{"i":995,"n":"ר\u0027 ברכיה בר סימון","l":"ב","b":"מובא בקה\"ר (פ\"י - ז\u0027)."},{"i":996,"n":"ר\u0027 ברכיה בר\u0027 חלבו","l":"ב","b":"מובא בויק\"ר (פל\"ו - ו\u0027): \"אמר בשם רבה בר זבדא\", ו\"סה\"ד\" כתב: \"ואולי ט\"ס וצ\"ל: ר\u0027 ברכיה ור\u0027 חלבו, דבהרבה מקומות נזכרים יחד\" עכ\"ל. ואולי צ\"ל: ר\u0027 ברכיה בשם ר\u0027 חלבו, שכן היה רבו המובהק."},{"i":997,"n":"ר\u0027 ברכיה הכהן (2)","l":"ב","b":"אמורא ארץ ישראלי בדור הרביעי. מסר בשם ר\u0027 חלבו (תנחומא וארא כ\"ב)."},{"i":998,"n":"ר\u0027 ברכיה סבא","l":"ב","b":"מובא בויק\"ר (פ\"א - ד\u0027), שר\u0027 אבין אמר בשמו."},{"i":999,"n":"ברקא","l":"ב","b":"כך גורס \"יחוסי תנאים ואמוראים\", ולפנינו הגיר\u0027: רבי בורקי."},{"i":1000,"n":"בתא","l":"ב","b":"מובא בבבלי (תמורה כ\"ט ע\"א), וכן הגיר\u0027 \"כפתור ופרח\" וה\"יוחסין\", ולפנינו: בהא."},{"i":1001,"n":"בתירא","l":"ב","b":"ע\"ע רבי יהודה בן בתירא ב\u0027, ר\u0027 יהושע בן בתירא, רבי יוחנן בן בתירא, ר\u0027 יונתן בן בתירא ורבי שמעון בן בתירא."},{"i":1002,"n":"גביהא בן פסיסא","l":"ג","b":"חי בתקופת בית המקדש, בזמנו של שמעון הצדיק. ליוה את המלך אלכסנדר מוקדון בביקורו בבית המקדש (מגילת תענית פ\"ג). היה חכם גדול, ובויכוחים שהיו לו עם אלכסנדר מוקדון ובני אפריקה, מצרים וישמעאל, ניצח את כולם (סנהדרין צ\"א ע\"א)."},{"i":1003,"n":"רב גביהא מארגיזא","l":"ג","b":"אמורא בבלי בדור הששי. רב הונא בר נתן, ראש הגולה, מסר לרב אשי בשמו (גיטין ז\u0027 ע\"א)."},{"i":1004,"n":"רב גביהה מבי כתיל","l":"ג","b":"אמורא בבלי בדור הששי. עמד בראש ישיבת פומבדיתא, בשנים ד\"א קע\"ט - קצ\"ג (914 - 334) (\"אגרת רב שרירא גאון\"). היה כפוף לרבא (ע\"ז כ\"ב ע\"א). חברם של רב אשי ואמימר (ביצה כ\"ג ע\"א). נראה שנטל חלק בעריכת הש\"ס עם רב אשי (יבמות ס\u0027 ע\"א)."},{"i":1005,"n":"גבילה","l":"ג","b":"מובא בירושלמי (נזיר פ\"ז ה\"א), ע\"ע מגבילה."},{"i":1006,"n":"גביני","l":"ג","b":"מובא במשנה (שקלים רפ\"ה), שהיה ממונה במקדש להכריז, וקולו נשמע עד למרחק ג\u0027 פרסאות, ואגריפס המלך נתן לו על כך מתנות (יומא כ\u0027 ע\"ב)."},{"i":1007,"n":"גביעה בן קוסם","l":"ג","b":"מובא בב\"ר (ספס\"א), והוא גביהא בן פסיסא."},{"i":1008,"n":"רב גדא","l":"ג","b":"אמורא בבלי בדור השלישי. היה שמשו של רב ששת (עירובין י\"א ע\"ב)."},{"i":1009,"n":"רב גדל","l":"ג","b":"מובא בבבלי (ברכות מ\"ט ע\"א), והוא רב גידל."},{"i":1010,"n":"גוריא בר חמא","l":"ג","b":"מובא בבבלי (ברכות נ\"ג ע\"ב), שרבא בירך במוצאי שבת על אור שלו, שהיה סמוך לביתו. \"יוחסין\" קבע כי גוריון זה הוא בנו של רב חמא בר גוריון."},{"i":1011,"n":"ר\u0027 גוריון","l":"ג","b":"אמורא ארץ ישראלי בדור הרביעי. מסר בשם ר\"ל (ירו\u0027, מגילה פ\"ג ה\"א) ובשם ר\u0027 יוסי בר חנינא (ירו\u0027, נזיר רפ\"ח). ר\u0027 יונה ביקרו באבלו וקרא לו: \"ברנש זעיר\" (ירו\u0027, מו\"ק פ\"ג ה\"ה)."},{"i":1012,"n":"גוריון בן אסטיון","l":"ג","b":"אמורא בבלי בדור השני. מסר בשם רב (ב\"מ פ\"ו ע\"ב)."},{"i":1013,"n":"גוריון מאספורק","l":"ג","b":"מובא בבבלי: \"אמר רב יוסף: \u0027תני גוריון דמן אספורק\u0027\" (תמורה ל\u0027 ע\"ב). \"יוחסין\" כתב שר\u0027 יוסף אמר בשמו ו\"סה\"ד\" תמה עליו."},{"i":1014,"n":"גורסק בר דרי","l":"ג","b":"אמורא בבלי בדור השלישי. מובא בבבלי (עירובין כ\"ט ע\"א), שאמר משמיה דרב מנשיא בר שגובלי, שאמר משמיה דרב."},{"i":1015,"n":"רב גזא","l":"ג","b":"מובא בבבלי (יבמות מ\"ה ע\"ב). סביב המובא על אודותיו יש כמה ספקות: \"אמר רבינא [בדור החמישי]: אמר לי רב גזא: איקלע וכו\u0027. אמר רב ששת [בבבל, בדור השני - השלישי]: לדידי אמר לי רב גזא וכו\u0027\" גירסת \"דק\"ס\": רב גדא (היה שמשו ותלמידו של רב ששת)."},{"i":1016,"n":"ר\u0027 גידול","l":"ג","b":"מובא בירושלמי (ביצה פ\"א ה\"א), והוא ר\u0027 גידל, תלמידם של רב ור\"ה."},{"i":1017,"n":"גידול בר מיניימון","l":"ג","b":"מובא בירושלמי (סוטה פ\"ו ה\"ד), והוא רב גידל בר בנימין."},{"i":1018,"n":"גידול בר רעילאי","l":"ג","b":"אמורא בבלי בדור הרביעי. מובא בבבלי (גיטין ל\"ד ע\"א) ששלח גט לאשתו, ואביו ורבא שקלו וטרו בענין גט זה. \"סה\"ד\" כתב: \"לא ידעתי אם חכם הוה\"."},{"i":1019,"n":"רב גידל","l":"ג","b":"אמורא בבלי בדור השני - השלישי. תלמידו של רב (עירובין י\"ז ע\"א), וכן קיבל משמואל (נדרים ט\"ז ע\"ב). אחר פטירתו של רב היה לתלמידו של ר\"ה (יבמות ס\"ד ע\"ב), וכן קיבל מרב חייא בר יוסף (שבת ז\u0027 ע\"א) ומרב ירמיה בר אבא (בכורות ל\"ו ע\"ב). הלך לא\"י. קיבל מרב יוחנן (נדה כ\"ד ע\"א). בא\"י היה לו דין ודברים עם רבי אבא (קידושין נ\"ט ע\"א). ר\"ז אמר משמו (ברכות מ\"ט ע\"א). גם רבא בר רב הונא קיבל ממנו (קידושין מ\"ב ע\"א)."},{"i":1020,"n":"רב גידל בר בנימין","l":"ג","b":"אמורא בבלי בדור השני - השלישי. תלמידו של רב (ירו\u0027, פסחים פ\"ח ה\"ח). וכן היה תלמידו של רב נחמן (ברכות מ\"ט ע\"א). רב חייא בר יוסף, מתלמידי רב, מסר בשמו (ירו\u0027, פסחים שם). ואין זה רב גידל סתמא, שכן רב נחמן בר יצחק מבדיל בפירוש בין שלושה חכמים ושמם רב גידל, וכולם היו תלמידי רב: \"אמר רב נחמן בר יצחק וכו\u0027 לא גידול בר מנשיא ולא גידול בר מניומי [הוא בנימין], אלא גידול סתמא\" (פסחים ק\"ז ע\"א)."},{"i":1021,"n":"גידל בר מניומי","l":"ג","b":"מובא בבבלי (ב\"ב ל\"ט ע\"ב), והוא רב גידל בר בנימין."},{"i":1022,"n":"רב גידל בר מנשה מבירי דנרש","l":"ג","b":"מובא בבבלי (יומא פ\"א ע\"ב), ונראה שהוא רב גידל בר מנשיא."},{"i":1023,"n":"רב גידל בר מנשיא","l":"ג","b":"אמורא בדור השני. תלמידם של רב (מו\"ק כ\"ד ע\"ב) ושל שמואל (שם כ\"ד ע\"א). היו שלושה רב גידל תלמידי רב. ע\"ע רב גידל בר בנימין."},{"i":1024,"n":"רב גידל דמן נרש","l":"ג","b":"אמורא בבלי. נראה, שחי בדור השלישי, בזמן תלמידי ר\"ה. \"אמר ר\"ה אמר רב וכן תני רב גידל דמן נרש וכו\u0027\" (פסחים ק\"ז ע\"א)."},{"i":1025,"n":"רב גמדא","l":"ג","b":"אמורא בבלי בדור הששי. בזמן רב אשי, היה גדול הדור (כתובות ס\"ג ע\"ב). מסר מאמריו של רבא (ב\"ק ע\"ב ע\"א). היה כחברם של אמימר, מר זוטרא ורב אשי (כתובות שם)."},{"i":1026,"n":"גמליאל (6)","l":"ג","b":"רבן גמליאל דיבנה - תנא בדור השני. נשיא ישראל. דור רביעי להלל הזקן. בנו של רבן שמעון בן גמליאל הנהרג ובן בנו של רבן גמליאל הזקן (שבת ט\"ו ע\"א), ואבי אביו של רבי (שם). הוא נקרא בדרך כלל סתם \"רבן גמליאל\" בש\"ס (נדה ו\u0027 ע\"ב תד\"ה: בשפחתו). בדורו היה חורבן בית המקדש. נתמנה לנשיא כשנתיים אחר החורבן (שבת נ\"ד ע\"ב תד\"ה: הוה). לפניו שימש כנשיא רבן יוחנן בן זכאי (שם), ורבן גמליאל היה תלמידו (ב\"ב י\u0027 ע\"ב). היה הראש ביבנה (סנהדרין ל\"ב ע\"ב). חבריו הגדולים היו: רבי אליעזר, שהיה גם גיסו, שנשא ר\"א את אימא שלום אחותו (ב\"מ נ\"ט ע\"ב), ורבי יהושע (הוריות י\u0027 ע\"א). ציוה על ר\u0027 יהושע לבוא אליו במקלו ובתרמילו ובמעותיו ביום כפור שחל להיות לפי חשבונו, וכשבא רבי יהושע עמד ר\"ג ונשקו על ראשו וקרא לו \"רבי בחכמה ותלמידי שקבלת דברי\" (ר\"ה כ\"ה ע\"א). ובגלל ענין אחר שהיה לו עם ר\u0027 יהושע הורידו את ר\"ג מנשיאותו לתקופה מסוימת ומינו במקומו את ר\"א בן עזריה (ברכות כ\"ז ע\"ב). עם תלמידיו נמנה ר\"ע (פסחים מ\"ח ע\"ב). היה בעל רוח הקודש (עירובין ס\"ד ע\"ב). נהג להחמיר על עצמו (ברכות ט\"ז ע\"א). הרומאים רצו להרגו וניצל (תענית כ\"ט ע\"א). נפטר בעקבות נידוי רבי אלעזר גיסו (ב\"מ נ\"ט ע\"ב)."},{"i":1027,"n":"רבי גמליאל בי רבי אבינה","l":"ג","b":"מובא בירושלמי (כתובות פ\"ג ה\"י), והוא ר\u0027 גמליאל בר\u0027 אלעאי."},{"i":1028,"n":"גמליאל בי רבי ליאני","l":"ג","b":"מובא בירושלמי (נדה ספ\"ג), והוא ר\u0027 גמליאל בר ר\u0027 אלעאי."},{"i":1029,"n":"ר\u0027 גמליאל בן אינינוא","l":"ג","b":"מובא בירושלמי (פאה רפ\"א), והוא ר\u0027 גמליאל בר ר\u0027 אלעאי."},{"i":1030,"n":"רבי גמליאל בר אניא","l":"ג","b":"מובא בירושלמי (כתובות פ\"ד ה\"א), והוא ר\u0027 גמליאל בר ר\u0027 אלעאי."},{"i":1031,"n":"ר\u0027 גמליאל בר ר\u0027 אלעאי","l":"ג","b":"אמורא ארץ ישראלי בדור הששי. תלמידו של ר\u0027 מנא (ירו\u0027, שביעית ספ\"ה). שמו שובש בכמה צורות: ר\"ג בן אינינוא (ירו\u0027, פאה רפ\"א), רבן גמליאל ברבי איניונא (ירו\u0027, פסחים פ\"א ה\"א), ר\"ג בר\u0027 איניוני (ירו\u0027, יומא פ\"א ה\"א), רבי גמליאל בי רבי אבינה (ירו\u0027, כתובות פ\"ג ה\"י), רבי גמליאל בר אניא (ירו\u0027, שם פ\"ד ה\"ח), גמליאל בי רבי ליאני (ירו\u0027, נדה ספ\"ג). לחינם חילקו אותו חוקרים שונים לאנשים שונים. מאידך, יש חוקרים ש\"צירפו\" את גמליאל ברבי חנינא וסברו שהוא הוא ר\u0027 גמליאל בר ר\u0027 אלעאי ולא היא, שכן הוא היה חכם אחר (קה\"ר פ\"ה - יב)."},{"i":1032,"n":"רבן גמליאל ברבי","l":"ג","b":"מובא בבבלי (שבת קט\"ו ע\"א), והוא רבן גמליאל דיבנה. ברבי פירושו גדול הדור, (ויש רבן גמליאל בר רבי והוא בנו של רבינו הקדוש)."},{"i":1033,"n":"רבן גמליאל ברבי איניונא","l":"ג","b":"מובא בירושלמי (פסחים פ\"א ה\"א), והוא ר\u0027 גמליאל בר ר\u0027 אלעאי."},{"i":1034,"n":"ר\u0027 גמליאל ברבי חנינא","l":"ג","b":"אמורא ארץ ישראל בדור הששי. תלמידו של ר\u0027 מנא (קה\"ר פ\"ה - יב)."},{"i":1035,"n":"ר\u0027 גמליאל בר\u0027 איניוני","l":"ג","b":"מובא בירושלמי (יומא פ\"א ה\"א), והוא ר\u0027 גמליאל בר ר\u0027 אלעאי."},{"i":1036,"n":"גמליאל דקונתיה","l":"ג","b":"אמורא ארץ ישראלי בדור השלישי. נפטר בחיי רבי סימון (ירו\u0027, מו\"ק פ\"ג ה\"ה). ר\u0027 מנא (חי בדור החמישי) התיר לו נדר (ירו\u0027, נדרים ספ\"י). נראה שקראו לו \"גמליאל דקונתיה\" (הזקן), שכן גם בן בנו גמליאל היה חכם (שם)."},{"i":1037,"n":"גמליאל זוגא","l":"ג","b":"אמורא ארץ ישראלי בדור השלישי. שאל מר\u0027 יוחנן (ירו\u0027, חלה פ\"ד ה\"ג), וקיבל מר\"ל (ירו\u0027, ע\"ז פ\"ג הי\"א). היה משמש לר\u0027 יהושע בן לוי [לפי גיר\u0027 \"סה\"ד\"] (ירו\u0027, ע\"ז פ\"ג הי\"א). היה לו אח צעיר ושמו הלל (ירו\u0027, מו\"ק פ\"ג ה\"ה)."},{"i":1038,"n":"גניבא","l":"ג","b":"אמורא בבלי בדור הראשון - השני. היה תלמידו של רב (ברכות כ\"ה ע\"א). אח\"כ היה לו כתלמיד חבר ורב אמר עליו \"אני זקן והוא זקן\" (ירו\u0027, ע\"ז פ\"ב ה\"ח). כן מסר בשם רב אסי [תלמיד חבר של רב] (חולין נ\u0027 ע\"ב). רבי חייא בר אבא אמר: \"לדידי מפרשא לי מיניה דגניבא\" (שם). היתה לגניבא מחלוקת קשה עם מר עוקבא, ומר עוקבא שלח לרבי אלעזר: \"בני אדם העומדים עלי וכו\u0027\" ור\"א השיב לו: \"הדבר יצא מפי רבי אלעזר ונתנוהו לגניבא בקולר\" (גיטין ז\u0027 ע\"א). ופרש\"י: \"שלשלת של ברזל שנותנים שם המוכתבים למלכות להריגה\". ואמנם הוא הוצא להורג מטעם המלכות (גיטין ס\"ה ע\"ב)."},{"i":1039,"n":"ר\u0027 גרשום","l":"ג","b":"אמורא ארץ ישראלי בדור החמישי. אמר בשם ר\u0027 אחא. (ירו\u0027, נדרים פ\"ג ה\"ח)."},{"i":1040,"n":"ר\u0027 דוסא (2)","l":"ד","b":"אמורא ארץ ישראלי בדור השלישי. עולא שכפא שנה לפניו ברייתות, וא\"ל ר\u0027 דוסא: חזור בך [מאחת הברייתות], א\"ל ר\"ז: \u0027אל תחזור בך\u0027 (ירו\u0027, ע\"ז פ\"ב ה\"ט). ר\u0027 ברכיה אמר משמו (ב\"ר פי\"ב - ו), וכן רב הונא ב\u0027 (רות רבה פ\"א - ד). נפטר בר\"ח ניסן (ירו\u0027, סוף מו\"ק)."},{"i":1041,"n":"ר\u0027 דוסא בן ארכינס","l":"ד","b":"מובא בירושלמי (כתובות פי\"ב ה\"א), והוא ר\u0027 דוסא בן הרכינס. וכן גרס \"יתו\"א\": ר\u0027 דוסא בן ארקינס הזקן."},{"i":1042,"n":"דוסא בן הורכניס","l":"ד","b":"תנא בדור הראשון והשני, שהאריך ימים והגיע לדור חכמי יבנה (לדעת הרמב\"ם בהקדמתו לזרעים, האריך ימים עד מאד). ידוע כר\u0027 דוסא וגם כבן הורכניס (יבמות ט\"ז ע\"א). חלק עם חכמים מדור הראשון, עם רבי יוחנן בן זכאי (ירו\u0027, כתובות פי\"ג ה\"א) ועקביא בן מהללאל (נגעים פ\"א מ\"ד), ועם רבי אליעזר (סנהדרין צ\"ט ע\"א) ועם רבן גמליאל מדור השני (ר\"ה כ\"ה ע\"א). רבי יהושע בא להוועץ עמו, לאחר שר\"ג גזר עליו לבוא אליו במקלו ובמעותיו ביום הכיפורים שחל להיות לפי חשבונו (שם). בדורם של חכמי יבנה כבר היה זקן מופלג ועיניו כהו מראות (יבמות ט\"ז ע\"א). היה עשיר מופלג, וכשר\u0027 יהושע ור\u0027 אליעזר ור\u0027 עקיבא באו לביתו הושיבם על מטות של זהב (שם). היה לו אח חריף ביותר ושמו יונתן, שהיה מתלמידי שמאי (שם)."},{"i":1043,"n":"ר\u0027 דוסא בן טבת","l":"ד","b":"מובא בשהש\"ר (פ\"ז - ח). ר\u0027 חנינא אמר בשמו (שם)."},{"i":1044,"n":"ר\u0027 דוסא בר חנינא","l":"ד","b":"מובא בפדר\"כ (קל\"ג), ואולי צ\"ל ר\u0027 יוסי בר חנינא."},{"i":1045,"n":"ר\u0027 דוסא ממלחיא","l":"ד","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. אמר בשם ר\u0027 אחא שאמר בשם רבי אלעזר (ירו\u0027, סוטה פ\"ג ה\"ז)."},{"i":1046,"n":"דוסאי","l":"ד","b":"מובא ב\"ר פ\"א."},{"i":1047,"n":"ר\u0027 דוסי סבא","l":"ד","b":"אמורא ארץ ישראלי, ככל הנראה בדור הרביעי. מובא בירושלמי: \"ר\u0027 חזקיה, ר\u0027 דוסתי, ר\u0027 אבא בר זמינא ומטו בה משמיה דר\u0027 דוסי סבא\" (חגיגה פ\"א ה\"ח)."},{"i":1048,"n":"ר\u0027 דוסתאי","l":"ד","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. בב\"ר (פי\"א - ח\u0027) מובאת מחלוקת ר\u0027 ברכיה, ר\u0027 דוסתאי ור\u0027 שמואל בר נחמני."},{"i":1049,"n":"דוסתאי אבוה דר\u0027 אפטוריקי","l":"ד","b":"אמורא ארץ ישראלי בדור הראשון. נמנה עם התנאים שוני ברייתות (חולין ס\"ד ע\"ב: ב\"מ ה\u0027 ע\"א). נזכר גם כאבוה דר\u0027 אפטוריקי (שם)."},{"i":1050,"n":"דוסתאי איש כפר איתמה","l":"ד","b":"מובא בירושלמי (ערלה פ\"ב ה\"ג), והוא דוסתאי איש כפר יתמה."},{"i":1051,"n":"דוסתאי איש כפר יתמה","l":"ד","b":"תנא בדור הראשון, בזמן הבית. תלמידו של שמאי הזקן (ערלה פ\"ב מ\"ה)."},{"i":1052,"n":"ר\u0027 דוסתאי בר יהודה","l":"ד","b":"תנא בדור החמישי. מובא בבבלי (קידושין ס\"ז ע\"א). מסר בשם רבי שמעון בר יוחי (חולין קכ\"ג ע\"ב). חלק עם רבי (ערכין ל\u0027 ע\"א)."},{"i":1053,"n":"ר\u0027 דוסתאי בר ינאי","l":"ד","b":"תנא בדור החמישי. מסר כמה פעמים בשם רבי מאיר (עירובין נ\"ח ע\"א). מחלוקת אחת בינו לבין רבי נמסרה על ידי רבי אבהו (ירו\u0027, דמאי פ\"ז ה\"ז). ירד לבבל יחד עם חברו ר\u0027 יוסף בר כיפור. ר\u0027 יאשיה ביקש מהם לגבות חוב המגיע לו בנהרדעא (גיטין י\"ד ע\"ב). היו לו תלמידים (נדה ל\"א ע\"ב)."},{"i":1054,"n":"ר\u0027 דוסתאי בר מתון","l":"ד","b":"מובא בבבלי: \"ר\u0027 דוסתאי בר מתון א\"ר יוחנן\" (יומא ל\u0027 ע\"ב), אך נראה ט\"ס וצ\"ל כמו במקום אחר: \"ר\u0027 יוסטאי בר מתון\" (זבחים צ\"ט ע\"א), ור\u0027 דוסתאי בר מתון היה תנא: \"ותניא ר\u0027 דוסתאי בר מתון אמר\" (מגילה ו\u0027 ע\"ב)."},{"i":1055,"n":"ר\u0027 דוסתאי דמן בירי","l":"ד","b":"אמורא בדור השני. רבו של עולא (ע\"ז מ\u0027 ע\"א). לא ברור אם היה מא\"י שכן בירי הוא מקום גם בא\"י וגם בבבל. בירי מקום ליד צפת, או דבי בירי ודבי נרש בבבל (עירובין נ\"ו ע\"א). גם מהענין המובא במסכת ע\"ז (שם), אין להכריע אם הדבר היה בא\"י או בבבל, שכן הן עולא והן ר\u0027 זירא היו בא\"י וגם בבבל."},{"i":1056,"n":"ר\u0027 דוסתאי מבי ישבב","l":"ד","b":"תנא בדור החמישי. מובא במדרש משלי (ספ\"ג) ששאל לר\u0027 מאיר."},{"i":1057,"n":"ר\u0027 דוסתאי מן כוכבא","l":"ד","b":"מובא בפד\"כ (נ\"ט) ואולי צ\"ל ר\u0027 דוסתאי מבי ישבב."},{"i":1058,"n":"דוסתאי סבא","l":"ד","b":"מובא ב\"זוהר\" (תזריע ע\"ו). אמר בשם יוסא סבא, ואולי הוא ר\u0027 דוסי סבא."},{"i":1059,"n":"ר\u0027 דוסתאי סבא","l":"ד","b":"מובא בירושלמי (נדרים ספ\"י) והוא ר\u0027 דוסי סבא."},{"i":1060,"n":"דורתאי","l":"ד","b":"חכם קדמון מימי הזוגות, חי בדורו של שמעיה ואבטליון (רבותיהם של הלל ושמאי). ומצינו \"פירוש הוא ודורתאי בנו והלך וישב לו בדרום\" (פסחים ע\u0027 ע\"ב), ופרש\"י: \"בן דורתאי פירש מן החכמים ונבדל מהם מפני שהיו אומרים אין חגיגת ארבעה עשר דוחה שבת\". \"סה\"ד\" כתב בערך יהודה בן דורתאי: \"ונראה שהיה צדוקי\", ואם הסיק כך מדברי רש\"י, פליאה בעיני אם אכן כך הבין את רש\"י, וכיצד הפך חכם קדמון ל\"צדוקי\" ואם היה לבעל \"סה\"ד\" מקור אחר, נעלם ממני."},{"i":1061,"n":"דייני ארץ ישראל","l":"ד","b":"הם רבי אמי ורבי אסי (סנהדרין י\"ז ע\"ב)."},{"i":1062,"n":"דייני גולה","l":"ד","b":"הוא קרנא (סנהדרין י\"ז ע\"ב)."},{"i":1063,"n":"דייני גזירות","l":"ד","b":"הם אדמון בן גדאי, חנן המצרי וחנן בן אבשלום (כתובות ק\"ה ע\"א)."},{"i":1064,"n":"דייני דנהרדעא","l":"ד","b":"הוא רבי אדא (סנהדרין י\"ז ע\"ב), ו\"סה\"ד\" כתב שב\"ערוך\", ערך דן, כתב: רב אבא בר מניומי."},{"i":1065,"n":"דייני דפומבדיתא","l":"ד","b":"הוא רב פפא בר שמואל (סנהדרין י\"ז ע\"ב)."},{"i":1066,"n":"דייני דציפורי","l":"ד","b":"בתקופת התנאים. מובא במשנה (ב\"ב צ\"ט ע\"ב), ופירש הרשב\"ם: \"לא איתפריש\"."},{"i":1067,"n":"דייני דקיסרי","l":"ד","b":"מובא בבבלי (עירובין ע\"ו ע\"ב), שרבי יוחנן אמר כמותם, ולא ברור מי הם."},{"i":1068,"n":"רב דימי","l":"ד","b":"אמורא בדור השלישי - הרביעי. נראה שהיה בבלי (\"אגרת רב שרירא גאון\"). היה מ\"הנחותי\", כלומר היה יורד להביא תורת א\"י לבבל והביא עשרות דינים מחכמי א\"י, ובחזרו הביא מתורת בבל לא\"י. כגון: \"כי אתא רב דימי א\"ר חנינא\" (שבת קכ\"ה ע\"ב), \"כי אתא רב דימי א\"ר יוחנן\" (שבת ז\u0027 ע\"א) \"כי סליק רב דימי\" (תמורה י\"ד ע\"א). בירושלמי נזכר כרב אבדימי נחותא (עירובין פ\"א ה\"ו). היה תלמידו של רב נחמן (חולין קי\"ב ע\"א). רבין חברו היה גם הוא מן הנחותי, ופעמים שבאו זה אחר זה \"כי אתא רב דימי אמר ר\u0027 אלעזר וכו\u0027, כי אתא רבין וכו\u0027 אמר ר\u0027 אלעזר\" (שבת קל\"ד ע\"ב). בסוף ימי אביי ורבא, באו כל \"הנחותי\" לבבל בגלל הגזירות בא\"י (\"אגרת רב שרירא גאון\"). כן מצינו: \"אתא רבין וכל נחותי וכו\u0027\" (חולין קכ\"ד ע\"א)."},{"i":1069,"n":"רב דימי אחוה דרב ספרא","l":"ד","b":"אמורא בבלי בדור השלישי. אחיו של רב ספרא (ערכין ט\"ז ע\"א). ר\u0027 אבא אמר עליו לאחר פטירתו: \"ידענא ביה ברב דימי ולא אמיד\" (כתובות פ\"ה ע\"ב). ידוע מאמרו: \"אל יספר אדם בטובתו של חבירו, שמתוך טובתו בא לידי רעתו\" (ב\"ב קס\"ד ע\"ב)."},{"i":1070,"n":"רב דימי בר אבא","l":"ד","b":"אמורא בבלי. מובא בבבלי (ברכות כ\"ג ע\"ב). (לפי \"סה\"ד\" נפטר ד\u0027 ר\"י (054) דור שביעי לאמוראים)."},{"i":1071,"n":"רב דימי בר חיננא (2)","l":"ד","b":"אמורא בבלי בדור השלישי - הרביעי. מתשובתו לשאלת רב חייא, בנו של רבה, נראה שעוד זכה לקבל שמועות מרב (ר\"ה ל\"ד ע\"ב). דן על דברי רבה (ב\"ק צ\"ח ע\"ב). רב חסדא אמר עליו: \"מרגלא בפומיה דרב דימי בר חיננא\" (זבחים ל\"ו ע\"ב). האריך ימים - מצינו שבא לדין תורה בפני רבא (ב\"ב י\"ג ע\"ב)."},{"i":1072,"n":"רב דימי בר חמא","l":"ד","b":"מובא בבבלי (ע\"ז כ\u0027 ע\"ב), והוא רב אבדימי בר חמא."},{"i":1073,"n":"ר\u0027 דימי בר חמא","l":"ד","b":"מובא בבבלי (ע\"ז ב\u0027 ע\"ב), והוא ר\u0027 אבדימי בר חמא בר חסא."},{"i":1074,"n":"רב דימי בר יוסף","l":"ד","b":"אמורא בבלי בדור השני - השלישי. תלמידו המובהק של שמואל (נדה ס\"ו ע\"א), קיבל גם מרב (ברכות מ\"ה ע\"ב). ר\"נ קראו שיבוא להתדיין לפניו עם אחותו, וכשסירב איים עליו בנידוי (ב\"ב קנ\"א ע\"ב)."},{"i":1075,"n":"רב דימי בר יצחק","l":"ד","b":"אמורא בבלי בדור השלישי. תלמידו של רב יהודה (חולין מ\"ה ע\"ב)."},{"i":1076,"n":"רב דימי בר ליואי","l":"ד","b":"אמורא בבלי בדור הרביעי. אביי פסק לו בענין דין בשבת (ברכות כ\"ז ע\"ב)."},{"i":1077,"n":"דימי בר שישנא","l":"ד","b":"אמורא בבלי בדור השני. מסר מאמרים בודדים בשם רב (גיטין ס\"ב ע\"א)."},{"i":1078,"n":"רב דימי בריה דרב הונא מדמהוריא","l":"ד","b":"אמורא בבלי בדור הששי - השביעי. שאל מרבינא, ואין להכריע אם היה חבר או תלמיד לרבינא (מנחות פ\"א ע\"א: סנהדרין כ\"ט ע\"ב)."},{"i":1079,"n":"רב דימי בריה דרב נחמן בריה דרב יוסף","l":"ד","b":"מובא בבבלי (סנהדרין כ\"ד ע\"א)."},{"i":1080,"n":"רב דימי דמן חיפא","l":"ד","b":"מובא בבבלי (מגילה כ\"ט ע\"ב), והוא ר\u0027 אבדימי דמן חיפא."},{"i":1081,"n":"רב דימי מנהרדעא","l":"ד","b":"אמורא בבלי בדור הרביעי - החמישי בימי רב יוסף (ב\"ב כ\"ב ע\"א). היה חכם בלתי ידוע ורבא שלח לבדוק אחריו (שם). לא ברור מי היו רבותיו. מלך בפומבדיתא משנת ד\u0027 קמ\"ה - קמ\"ח (583 - 883) (\"אגרת רב שרירא גאון\"). אמימר מסר בשמו (חולין נ\"א ע\"ב), ואין זה רב דימי סתם, כמוכח (ע\"ז י\"א ע\"א). האריך ימים ונפטר 56 שנה אחר רב יוסף (\"אגרת רב שרירא גאון\")."},{"i":1082,"n":"רב דניאל בר רב קטינא","l":"ד","b":"אמורא בבלי בדור השלישי. תלמידו של רב (מו\"ק ח\u0027 ע\"א). אח\"כ היה לתלמידו של רב הונא (כתובות צ\"ז ע\"א), וכן מסר בשמו של רב אסי (ירו\u0027, שבת פ\"ג ה\"א). מסופר עליו נס מופלא כיצד הוריד גשם בתפילותיו רק למקומות מסויימים בגינתו (תענית ט\u0027 ע\"ב)."},{"i":1083,"n":"דניאל חייטא","l":"ד","b":"מובא בב\"ר (פס\"ד - ז\u0027)."},{"i":1084,"n":"דנין לפני חכמים","l":"ד","b":"הם שמעון בן עזאי, שמעון בן זומא, חנן המצרי וחנניא בן חכינאי. ורב נחמן בר יצחק אומר: אף שמעון התימני (סנהדרין י\"ז ע\"ב)."},{"i":1085,"n":"דרו בר פפא","l":"ד","b":"אמורא בבלי בדור השני. אמר בשם רב וחלק עם רבי יוחנן (ע\"ז כ\"ז ע\"א)."},{"i":1086,"n":"דרומאי","l":"ד","b":"חכמי דרום שגרו בדרומה של ארץ ישראל, וגם ר\u0027 אפס ישב שם (עירובין ס\"ה ע\"ב). \"דרומאי מתני משמיה דרבי יהושע בן לוי\" (ב\"ב צ\"ו ע\"א). \"מתיב רבי שמעון בן לקיש לדרומאי\" (ירו\u0027, פסחים פ\"ז ה\"ז)."},{"i":1087,"n":"ר\u0027 דרומי","l":"ד","b":"כך הגירסא בירושלמי (קידושין פ\"א ה\"ז), וגירסת \"קרבן העדה\": ר\u0027 דרוסי: אם כן, לגירסתו ר\u0027 דרומי לא היה ולא נברא, שכן הוא מובא רק פעם אחת בש\"ס הירושלמי."},{"i":1088,"n":"רבי דרוסא","l":"ד","b":"מובא בירושלמי (כלאים פ\"ט רה\"ג), והוא רבי דרוסי."},{"i":1089,"n":"רבי דרוסי","l":"ד","b":"אמורא ארץ ישראלי בדור החמישי. חברו של רבי יוסי בר אלעזר וחלק עמו (ירו\u0027, שבת פ\"א ה\"ב). היה לו אח ושמו רבי פטרוקי (ירו\u0027, יומא פ\"ד ה\"ד)."},{"i":1090,"n":"רבי דרוסתאי","l":"ד","b":"מובא במדרש שמואל (כ\"ח - ד\u0027) ונראה שהוא רבי דרוסי."},{"i":1091,"n":"ההוא מרבנן ורבי יעקב שמיה","l":"ה","b":"ע\"ע ר\u0027 יעקב."},{"i":1092,"n":"הון בריה דרב נחמן","l":"ה","b":"אמורא בבלי בדור הרביעי. בנו ותלמידו של רב נחמן. הקשה לר\"נ (יבמות ל\"ד ע\"א) ושאל ממנו (שם קי\"ב ע\"א)."},{"i":1093,"n":"רב הונא (4)","l":"ה","b":"גדול אמוראי בבל בדור השני. חי למעלה משמונים שנה (מו\"ק כ\"ח ע\"א). נפטר בשנת ד\u0027 נ\"ו (692) (\"אגרת רב שרירא גאון\"). תלמידו המובהק של רב (שבת קכ\"ח ע\"א). לאחר פטירת רב נתמנה לראש ישיבת סורא ומלך 04 שנה (\"אגרת רב שרירא גאון\"). היה הראש בבבל. רבים מתלמידי רב באו לפניו אחרי פטירת רב, כגון: רב חלבו (יבמות ס\"ד ע\"ב), ר\u0027 חייא בר אבין (קידושין נ\"ח ע\"א) ורב גידל בר בנימין (ב\"ב ל\"ט ע\"ב). אחר פטירת ר\u0027 יוחנן בשנת ד\u0027 ל\"ט (972) היו גם ראשי ארץ ישראל כפופים לו: \"רבי אמי ורבי אסי כהני חשובי דא\"י מיכף הוו כייפי ליה\" (גיטין נ\"ט ע\"ב). רבי אלעזר בן פדת החשיב עצמו קטן מרב הונא (ב\"ב קכ\"ה ע\"א). היו לו 008 תלמידים, ו - 31 אמוראים היו משמיעים את דבריו לתלמידים הרבים שהיו סביבו (כתובות ק\"ו ע\"א). ר\u0027 יוסף היה תלמידו המובהק (סוכה י\"א ע\"א), וכן רבה (עירובין י\"ז ע\"א) ורב ששת (כתובות ס\"ד ע\"ב) ובנו רבה בר רב הונא (ברכות נ\"ג ע\"ב). רב חסדא היה תלמיד חבר שלו (יבמות פ\"ג ע\"ב ד\"ה: אמרי). היה חכם גדול, ורבא ביקש שיזכה לחכמתו של ר\"ה (מו\"ק כ\"ח ע\"א). היה חסיד גדול, ופעם אחת כאשר נהפכו לו רצועות התפילין, צם 04 תעניות (מו\"ק כ\"ה ע\"א). בתחילה היה עני מרוד, ורב בירכו והעשיר (מגילה כ\"ז ע\"ב). כשנפטר העלו את ארונו לא\"י, וקברוהו במערת קברו של רבי חייא ובניו (מו\"ק שם). את מקומו מילא רב חסדא (\"אגרת רב שרירא גאון\")."},{"i":1094,"n":"רב הונא אביו של זעירא הכהן","l":"ה","b":"מובא בירושלמי (ברכות פ\"ח ה\"ה). יש שם אי בהירות או שיבוש, ואין הכרעה, וכבר האריך בזה \"סה\"ד\"."},{"i":1095,"n":"רב הונא אביו של ר\u0027 אחא","l":"ה","b":"מובא בבמד\"ר (פ\"ט - יב)."},{"i":1096,"n":"רב הונא בבלאה","l":"ה","b":"הוא רב הונא סתם."},{"i":1097,"n":"רב הונא בר אבא","l":"ה","b":"מובא בתנחומא (ישן, תצוה). יתכן שצ\"ל: ר\u0027 חייא בר אבא (עיין תנחומא בובר סוף תצוה)."},{"i":1098,"n":"רב הונא בר אבין","l":"ה","b":"אמורא ארץ ישראלי בדור הרביעי ו\"שלח\" הרבה מא\"י לבבל. \"שלח לרבא\" (ר\"ה כ\"א ע\"א), וכן \"שלח\" (ב\"ב נ\"א ע\"א ושם נ\"ה ע\"א). היו לו בנים שבאו לשאול דין מר\u0027 אמי (קידושין ח\u0027 ע\"ב)."},{"i":1099,"n":"רב הונא בר אדא","l":"ה","b":"מובא בבבלי (ברכות ס\"ב ע\"ב), לפי גיר\u0027 \"דק\"ס\", ולפנינו: רב חנא בר אדא, ושוב לא נזכר בש\"ס."},{"i":1100,"n":"רב הונא בר אויא","l":"ה","b":"אמורא בדור החמישי. חברו של רב אשי (חולין מ\"ז ע\"א). נפטר לפני רב אשי, ורב אשי סיפר לרב מרדכי שר\"ה אויא בא לו בחלום (ב\"ב קמ\"ג ע\"א)."},{"i":1101,"n":"רב הונא בר אחא","l":"ה","b":"אמורא ארץ ישראלי בדור השלישי. אמר בשם רבי אלכסנדרי (ירו\u0027, סוף מע\"ש). ור\u0027 יוסי בן חנינא מוסיף על דבריו (שם)."},{"i":1102,"n":"רב הונא בר אידי","l":"ה","b":"אמורא בבלי בדור השני. תלמידו של שמואל (קידושין ע\u0027 ע\"א). רב יהודה אמר לרב נחמן: \"לא סבר לה מר, להא דאמר רב הונא בר אידי, אמר שמואל\" (שם)."},{"i":1103,"n":"רב הונא בר אמי","l":"ה","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של פדת [בנו של ר\"א בן פדת] (ברכות נ\"ה ע\"ב). ו\"סה\"ד\", בערך רב חנן בן אמי, מפקפק אם אין כאן ט\"ס."},{"i":1104,"n":"רב הונא בר אשי","l":"ה","b":"אמורא בבלי בדור השני. תלמידו של רב (סוטה ט\"ז ע\"ב)."},{"i":1105,"n":"רב הונא בר ביזנא","l":"ה","b":"מובא בבבלי (יבמות ס\u0027 ע\"ב), ונראה שהוא רב חנא בר ביזנא."},{"i":1106,"n":"רב הונא בר ברכיה","l":"ה","b":"אמורא ארץ ישראלי בדור הראשון. אמר משום אלעזר הקפר (ברכות ס\"ג ע\"א)."},{"i":1107,"n":"רב הונא בר גוריון","l":"ה","b":"מובא בב\"ר (פכ\"ו - ו\u0027), ואולי צ\"ל: רב חמא בר גוריון (עיין קה\"ר פ\"ח - ט\u0027)."},{"i":1108,"n":"רב הונא בר גניבא","l":"ה","b":"מובא בקה\"ר (ספ\"ד)."},{"i":1109,"n":"רב הונא בר חיון","l":"ה","b":"אמורא בבלי בדור הששי. הבבלי (שבת קל\"ט ע\"ב) מפקפק אם שמו רב הונא בר חיון או רב הונא בר חלוון. תלמידיו התלוננו עליו, ורב אשי הצדיקו (שם)."},{"i":1110,"n":"רב הונא בר חייא","l":"ה","b":"אמורא בבלי בדור השלישי. חתנו ותלמידו של רבי ירמיה בר אבא [תלמיד חבר של רב] (שבת קנ\"ו ע\"א). קיבל משמואל (שבת נ\"א ע\"ב), מרב הונא (ב\"ב קי\"א ע\"ב) ומרב יהודה (סנהדרין ק\u0027 ע\"א). היה לו בית מדרש (\"אגרת רב שרירא גאון\"). רבה ורב יוסף וארבע מאות חכמים באו אליו לשאול ממנו הלכות, ולאחר ששמעו שנעשה גבאי המלך פרשו ממנו חלק מהחכמים, ורבה למד ממנו (בכורות ל\"א ע\"א)."},{"i":1111,"n":"רב הונא בר חיננא","l":"ה","b":"אמורא בבלי בדור הרביעי. תלמידו של רב יוסף (עירובין י\"ד ע\"ב). ישב לפני רב חסדא ושאל מרב ששת (קידושין כ\u0027 ע\"ב). קיבל מרב נחמן (כתובות ק\u0027 ע\"א). כמה מהוראותיו היו בניגוד לדעתו של רבא (ע\"ז מ\u0027 ע\"א, וראה גם עירובין ס\"ז ע\"ב). חבריו היו: רחבה (שם כ\"ו ע\"ב) ואביי (ב\"ב קס\"ז ע\"ב). נראה, שרב פפא היה תלמידו. (ע\"ז מ\u0027 ע\"א) ובנו למד אצל ר\"פ (פסחים ט\"ז ע\"א)."},{"i":1112,"n":"רב הונא בר חלוב","l":"ה","b":"אמורא בבלי בדור הרביעי. שאל מרב נחמן (שבת קט\"ו ע\"ב)."},{"i":1113,"n":"רב הונא בר חלוון","l":"ה","b":"מובא בבבלי (שבת קל\"ט ע\"ב). ע\"ע רב הונא בר חיון."},{"i":1114,"n":"הונא בר חנינא","l":"ה","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של ר\"א (ירו\u0027, מעשרות פ\"ד ה\"ד)."},{"i":1115,"n":"רב הונא בר חנינא","l":"ה","b":"מובא בבבלי (כתובות ק\u0027 ע\"א), והוא רב הונא בר חיננא."},{"i":1116,"n":"רב הונא בר יהודה","l":"ה","b":"אמורא בבלי בדור הרביעי. קיבל הרבה מרב ששת (עירובין כ\"ו ע\"ב), ומרב נחמן (פסחים מ\u0027 ע\"ב), וכן היה כתלמיד לרבא (פסחים י\"ב ע\"א) ושאל ממנו (נדרים י\"ט ע\"א). רב נחמן קרא לו מר (פסחים מ\u0027 ע\"ב)."},{"i":1117,"n":"רב הונא בר יצחק","l":"ה","b":"אמורא ארץ ישראלי בדור השלישי. ר\u0027 יהושע בר נחמיה אמר בשמו (פס\u0027 רבתי פ\u0027 בחודש השביעי)."},{"i":1118,"n":"רב הונא בר יקי","l":"ה","b":"מובא בפס\u0027 רבתי (פ\u0027 את קרבני)."},{"i":1119,"n":"רב הונא בר ירמיה","l":"ה","b":"מובא בבבלי (פסחים מ\"ג ע\"א), ואולי הוא ר\"ה בר ירמיה בר אבא."},{"i":1120,"n":"רב הונא בר כהנא","l":"ה","b":"מובא בילקוט (קהלת רמז תתקסו)."},{"i":1121,"n":"רב הונא בר לואי","l":"ה","b":"מובא בבבלי (ברכות נ\"ה ע\"ב) לגיר\u0027 \"עין יעקב\", ולפנינו סתם רב הונא."},{"i":1122,"n":"רב הונא בר לוליאני","l":"ה","b":"מובא בב\"ר (פל\"ו - ח\u0027). ואולי זה שיבוש מרבי חייא בר לולייני (ע\"ע)."},{"i":1123,"n":"רב הונא בר מנוח","l":"ה","b":"אמורא בבלי בדור החמישי. תלמידו של רבא (תענית ט\u0027 ע\"א). חברם של רב שמואל בר אידי ורב חייא מוסתניא: שלושתם למדו אצל רבא, ולאחר פטירתו באו ללמוד אצל רב פפא. בכל פעם שאמר שמועה שלא נראתה להם, רמזו זה לזה וחלשה דעתו של ר\"פ, ושילחם מעל פניו, לבל ייענשו מן השמים (שם). מסר בשם רב אחא בריה דרב איקא (מגילה כ\"ה ע\"ב)."},{"i":1124,"n":"הונא בר מניומי","l":"ה","b":"אמורא בבלי בדור השלישי - הרביעי. בא לשאול דין מרב יוסף ולא ידע להשיב לו, ואח\"כ פגש בחנן חייטא שהשיב לשאלתו (ע\"ז ל\"ט ע\"א)."},{"i":1125,"n":"רב הונא בר משה בר עצרי","l":"ה","b":"אמורא בבלי בדור הרביעי. מובא בבבלי (ב\"ב קע\"ד ע\"ב). אביו לא היה חכם (שם)."},{"i":1126,"n":"הונא בר נתן","l":"ה","b":"מובא בבבלי (ב\"ב נ\"ה ע\"א), והוא רב הונא בריה דרב נתן."},{"i":1127,"n":"רב הונא בר סחורה","l":"ה","b":"אמורא בבלי בדור הרביעי. תלמידו של רבא (בכורות ס\u0027 ע\"א). אמר רב נחמן בר יצחק: \"זכתה אמו שילדה בן כמותו\" (שם)."},{"i":1128,"n":"רב הונא בר עוקבא","l":"ה","b":"מובא ב\"ילקוט\" (איכה רמז תתרא)."},{"i":1129,"n":"רב הונא בר פפא","l":"ה","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. חלק עם ר\u0027 סימון (מדרש תהלים פק\"ד - י\"ד). רבי פנחס מסר בשמו (ב\"ר ספס\"ח)."},{"i":1130,"n":"ר\u0027 הונא בר רב יוסף","l":"ה","b":"מובא בב\"ר (פמ\"ד - י\"ב), ואולי זהה עם רב הונא בר יוסי."},{"i":1131,"n":"רב הונא בר רב קטינא","l":"ה","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב חסדא (זבחים קט\"ו - ע\"ב). וגיר\u0027 \"שיטה מקובצת\" וה\"ב\"ח\": \"רב חונה\". ובמקום אחר: \"רב הונא ברב קטינא\" (חולין י\"ז ע\"ב), וגיר\u0027 \"דק\"ס\": רב חנא יש סבורים שהוא: רב חנא בר רב קטינא."},{"i":1132,"n":"רב הונא בר רב תחליפא","l":"ה","b":"אמורא בבלי בדור החמישי - הששי. תלמידו של רבא (יבמות ח\u0027 ע\"ב). רבו של רב רחומי (זבחים ע\"ז ע\"א). גם אביו של רב הונא בר תחליפא (ר\u0027 תחליפא עצמו) היה תלמידו של רבא (יומא ו\u0027 ע\"ב)."},{"i":1133,"n":"רב הונא בר תורתא","l":"ה","b":"מובא בבבלי: \"אמר רב הונא בר תורתא: וכו\u0027 וכשבאתי לפני רבי שמעון החסיד [תנא דברייתא] אמר לי וכו\u0027\" (חולין קכ\"ז ע\"א). נראה, שהיה תנא ו\"יוחסין\" מביא שהיה גר, ומפני שפרתו לא רצתה לחרוש בשבת נעשה יהודי והמעשה מובא (פס\u0027 רבתי פ\u0027 פרה) והגיר\u0027 שלנו: רבי יוחנן בן תורתא."},{"i":1134,"n":"הונא בריה דמר זוטרא","l":"ה","b":"אמורא בבלי בדור הששי - השביעי. תלמידו של רבינא (ב\"ב פ\"ו ע\"א)."},{"i":1135,"n":"רב הונא בריה דרב אידי","l":"ה","b":"מובא בבבלי (ר\"ה כ\"ד ע\"ב). \"סה\"ד\" כתב: \"ט\"ס וצ\"ל: רב הונא בריה דרב יהושע\", וכן נראה מגיר\u0027 רש\"י (ע\"ז מ\"ב ע\"ב, ד\"ה: וכדרב הונא בריה דרב יהושע)."},{"i":1136,"n":"הונא בריה דרב איקא","l":"ה","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של רב אבהו (פסחים נ\"ב ע\"ב). דייק מאד במסירת שמועות שקיבל מרבו (שם). נראה, שהיה גם בבבל ורב פפא ביקר אצלו (ברכות מ\"ג ע\"ב). ומצינו: \"אמר אביי וכו\u0027 מתיב ר\"ה בריה דרב איקא\" (ביצה ט\"ו ע\"א)."},{"i":1137,"n":"רב הונא בריה דרב הועיא","l":"ה","b":"מובא ב\"ילקוט\" (משלי רמז תתקנד), ונראה אולי שצ\"ל: ר\"ה בריה דרב יהושע (עיין סוטה ה\u0027 ע\"א)."},{"i":1138,"n":"רב הונא בריה דרב הושעיא","l":"ה","b":"מובא בבבלי (הוריות ג\u0027 ע\"ב)."},{"i":1139,"n":"רב הונא בריה דרב חייא","l":"ה","b":"מובא בבבלי (ע\"ז פ\"ז ע\"ב: נזיר ל\"ז ע\"ב). אך באותו ענין יש גירסא הפוכה (רב חייא בריה דרב הונא), בשני מקומות אחרים: (פסחים מ\"ד ע\"ב: ע\"ז ע\"ה ע\"ב)."},{"i":1140,"n":"רב הונא בריה דרב יהושע","l":"ה","b":"אמורא בבלי בדור החמישי. חברו המובהק של רב פפא. שניהם נזכרים יחד פעמים רבות בש\"ס הבבלי, ושניהם היו מתלמידיו המובהקים של אביי (פסחים קי\"א ע\"ב) ושל רבא (ב\"ב כ\"ב ע\"א: הוריות י\u0027 ע\"ב), וגם שלחו ידם במסחר יחדיו (גיטין ע\"ג ע\"א). לאחר פטירת רבא יסד רב פפא ישיבה בעיר נרש הסמוכה לסורא ובה שימש רב הונא בריה דרב יהושע כראש כלה (ברכות נ\"ז ע\"א). מחבריו היו רב מרי ורב פנחס בני רב חסדא (קידושין ל\"ב ע\"ב) ורב פנחס בר אמי (כתובות פ\"ה ע\"א) ורנב\"י (סנהדרין ל\u0027 ע\"ב). ר\u0027 יעקב מנהר פקוד אמר משמו לפני רבינא (סנהדרין ס\"ט ע\"א). חלה ונטה למות ובזכות שנהג להעביר על מידותיו ריחמו עליו מן השמים והבריא (ר\"ה י\"ז ע\"א)."},{"i":1141,"n":"רב הונא בריה דרב נחמיה","l":"ה","b":"מובא בבלי (חולין י\"ח ע\"ב), והוא רב הונא מר בריה דרב נחמיה."},{"i":1142,"n":"הונא בריה דרב נחמן","l":"ה","b":"אמורא בבלי בדור הרביעי. בנו של רב נחמן (חולין מ\"ט ע\"ב). יחד עם חברו רב הונא בר חיננא, גרו בעיר סוכרא הסמוכה למחוזא, ושניהם חלקו על רבא (ע\"ז נ\"ז ע\"ב). כשנזדמן למחוזא, ציוה רבא לשמשו לסגור את הדלת, שכן פחד ממנו שמא יקפחנו בהלכות (שם נ\"ח ע\"א). תירץ לרב פפא קושיה ורב פפא נשקו על ראשו, ונתן לו את בתו לאשה (הוריות י\"ב ע\"ב)."},{"i":1143,"n":"רב הונא בריה דרב נתן","l":"ה","b":"אמורא בבלי בדור החמישי - הששי. ראש הגולה בימי רב אשי (\"אגדת רב שרירא גאון\"). תלמידו של רבא (נדרים י\"ב ע\"א) ושל אמימר (גיטין י\"ט ע\"ב). היה כפוף לרב אשי, אף שרב אשי מסר משמו (גיטין י\"ט ע\"ב; ב\"ב נ\"ה ע\"א). זכה לתורה וגדולה גם יחד (גיטין נ\"ט ע\"א), שלא היה כמותו מימות רבי מסדר המשנה (שם). היה מקורב מאד למלך הפרסי איזגדר (זבחים י\"ט ע\"א). נפטר בשנת ד\u0027 ר\"א (144) (ספר \"כריתות\")."},{"i":1144,"n":"רב הונא בריה דרב עילאי","l":"ה","b":"מובא בבבלי (יומא ל\"ה ע\"א), וגיר\u0027 \"דק\"ס\": \"רב עולא בריה דרב עילאי\"."},{"i":1145,"n":"רב הונא בריה דרב פנחס","l":"ה","b":"אמורא בבלי בדור הרביעי. אמר משמו של רב יוסף (מו\"ק ט\"ו ע\"ב)."},{"i":1146,"n":"רב הונא בריה דרב פפי","l":"ה","b":"אמורא בבלי בדור החמישי. בש\"ס אין הלכות ממנו. מובא בבבלי (חולין מ\"ח ע\"א) בהקשר לבנו מר זוטרא בריה דרב הונא בריה דרב פפי."},{"i":1147,"n":"רב הונא בריה דרבא","l":"ה","b":"אמורא בבלי. למד יחד עם רב אשי (ב\"ק ע\"ב ע\"א)."},{"i":1148,"n":"רב הונא בריה דר\u0027 ירמיה בר אבא","l":"ה","b":"אמורא בבלי בדור השלישי. בנו של ר\u0027 ירמיה בר אבא [תלמיד חבר של רב], ואביו של מרי (ברכות כ\"ו ע\"א). לא מובאת בש\"ס הלכה ממנו."},{"i":1149,"n":"רב הונא בריה דר\u0027 שמואל בר נחמני","l":"ה","b":"נראה שיבוש. עיין \"ילקוט משלי\" (רמז תתקסא) ובב\"ר (פע\"ה - ג\u0027)."},{"i":1150,"n":"רב הונא בר\u0027 יוסי","l":"ה","b":"מובא בתנחומא (נ\"ח - י\"ג), ואולי זהה עם רב הונא בר רב יוסף."},{"i":1151,"n":"רב הונא דציפורין","l":"ה","b":""},{"i":1152,"n":"ר\u0027 הונא דשאב","l":"ה","b":"מובא בתנחומא (מצורע ז\u0027), ונראה שצ\"ל: ר\u0027 מנא דשאב."},{"i":1153,"n":"ר\u0027 הונא הכהן","l":"ה","b":"אמורא ארץ ישראלי בדור הרביעי. אמר בשם רבי ירמיה (מד\u0027 תהלים פק\"ו - ב\u0027)."},{"i":1154,"n":"רב הונא הכהן בר אבין","l":"ה","b":"מובא בפס\u0027 רבתי (פ\"ח), וצ\"ל: רב הונא הכהן בר אבין."},{"i":1155,"n":"רבי הונא הכהן בר אבין","l":"ה","b":"אמורא ארץ ישראלי בדור החמישי. מסר בשם ר\u0027 שמואל בר נחמני (מ\"ר פ\"ז - ד\u0027) ורב יוסף (פס\u0027 רבתי פ\u0027 אנכי מנחמכם). רבו של רבי תנחומא בר אבא שהוא בעל התנחומא (מד\"ר פ\"ג - ז\u0027)."},{"i":1156,"n":"רב הונא זוטי","l":"ה","b":"אמורא בבלי בדור הרביעי. בש\"ס אין הלכה בשמו, ומובא רק בהקשר לבנו: \"דרש רבא בר רב הונא זוטי\" (ביצה כ\"ט ע\"ב), וכן: (כתובות ס\"ט ע\"א). שלח וכו\u0027 לרבה בר רב הונא זוטא\"."},{"i":1157,"n":"רב הונא מברניש","l":"ה","b":"מובא בבבלי (שבת כ\"ח ע\"א), לגיר\u0027 \"יוחסין\" ו\"סה\"ד\", ולפנינו: רבא מברניש."},{"i":1158,"n":"רב הונא מדמהריא","l":"ה","b":"אמורא בבלי בדור החמישי - הששי. אין בש\"ס הלכה בשמו, ומובא רק בהקשר לבנו: רב דימי בר רב הונא מדמהריא (סנהדרין כ\"ט ע\"ב: מנחות פ\"א ע\"א)."},{"i":1159,"n":"רב הונא מדסקרתא","l":"ה","b":"אמורא בבלי בדור הרביעי - החמישי. תלמידו של רבא (ב\"מ מ\"ז ע\"א). כשהקשה לפני רבא על דברי לוי, ענה לו רבא כי אילו לוי היה שם היה מנדה אותו על שחשד שלכך התכון בדבריו (שם)."},{"i":1160,"n":"רב הונא מסורא","l":"ה","b":"מובא בבבלי (זבחים צ\"א ע\"א)."},{"i":1161,"n":"רב הונא מר בר אויא","l":"ה","b":"מובא בבבלי (חולין מ\"ז ע\"א) שהקשה לרב אשי, והוא רב הונא בר אויא."},{"i":1162,"n":"רב הונא מר בר חייא","l":"ה","b":"אמורא בבלי בדור הששי. היה חברו של רב אשי (חולין נ\"ח ע\"ב)."},{"i":1163,"n":"הונא מר בר מרימר","l":"ה","b":"אמורא בבלי בדור הששי. תלמידו של רבינא (ב\"מ פ\"א ע\"א)."},{"i":1164,"n":"הונא מר בריה דרב אידי","l":"ה","b":"אמורא בבלי בדור השביעי. חברו של רב אדא בר מניומי, ובענין מחלוקת ביניהם בדין טריפות, שאלו לרבינא (חולין מ\"ט ע\"א)."},{"i":1165,"n":"הונא מר בריה דרבא מפרזיקא","l":"ה","b":"אמורא בבלי בדור הששי - השביעי. הקשה לרב אשי (כתובות י\u0027 ע\"א)."},{"i":1166,"n":"רב הונא מר בריה דר\u0027 נחמיה","l":"ה","b":"אמורא בבלי בדור הששי - השביעי. תלמידו של רב אשי (חולין י\"ז ע\"ב) והקשה לו (גיטין י\"ד ע\"א), ושקיל וטרי עמו (קידושין ו\u0027 ע\"ב)."},{"i":1167,"n":"הונא מרי בר מר זוטרא","l":"ה","b":"מן האמוראים האחרונים בתחילת הסבוראים (\"אגרת רב שרירא גאון\"). נהרג בשנת ד\u0027 תרל\"א לשטרות (ד\u0027 רע\"ט /915) עם אמימר בר מר ינוקא ור\u0027 משרשיא, בן בנו של רב אחא בר רב."},{"i":1168,"n":"רב הונא ספרא דסדרא","l":"ה","b":"מובא בירושלמי (שבת פ\"ט ה\"ב). פירש \"קרבן העדה\": \"סופר של בית המדרש\"."},{"i":1169,"n":"רב הונא צפוראה","l":"ה","b":"מובא בבבלי (יומא ע\"ז ע\"ב), והוא רבי הונא רובא דציפורין."},{"i":1170,"n":"רב הונא רב","l":"ה","b":"מובא בירושלמי (שקלים פ\"א), ונראה שהוא רב הונא סתם."},{"i":1171,"n":"רב הונא רבה","l":"ה","b":"מובא בבבלי (בכורות ל\"ז ע\"ב), והוא רב הונא סתם."},{"i":1172,"n":"רב הונא רבה דציפורין","l":"ה","b":"מובא בירושלמי (שקלים פ\"א ה\"א), והוא רב הונא רובא דציפורין."},{"i":1173,"n":"רב הונא רובא דציפורין","l":"ה","b":"אמורא ארץ ישראלי בדור השלישי. מסר כמה פעמים בשם רבי יוחנן (ירו\u0027, ברכות ספ\"ד). ר\u0027 אחא בר יצחק מסר משמו קטע תפילה, שחלקים ממנה יש בסידורים שלנו (ירו\u0027, תענית פ\"ב ה\"ב)."},{"i":1174,"n":"רב הונא ריש גלותא","l":"ה","b":"ע\"ע רב הונא (תנא)."},{"i":1175,"n":"רבי הונדקס","l":"ה","b":"כך מובא בירושלמי (שבת פט\"ז ה\"ג), והוא רבי חדקא."},{"i":1176,"n":"הורדוס","l":"ה","b":"מלך על ישראל החל מק\"ג שנה לפני חורבן בית שני (ע\"ז ט\u0027 ע\"א) [הלל החל את נשיאותו ק\u0027 שנה לפני הבית (שבת ט\"ו ע\"א)]. מזרע האדומים, שיוחנן כהן גדול הביאם בברית דת היהודים (יוסיפוס). בהיותו כבן 52 מינהו אביו אנטיפטר למושל על ארץ הגליל (שם). הועמד לדין בפני הסנהדרין על הריגה, ונמלט מהם. קיסר רומי עשהו למלך על ישראל (שם). כשמלך, הרג רבים מאד מחכמי ישראל (ב\"ב ג\u0027 ע\"ב), ובבא בן בוטא יעץ לו לבנות מחדש את בית המקדש, על מנת לכפר על מעשיו. ואכן זאת עשה - \"מי שלא ראה בנין הורדוס לא ראה בנין נאה מימיו\" (שם). ומן השמים סייעו לו: \"בימי הורדוס שהיו עוסקין בבנין בית המקדש, היו יורדין גשמים בלילה, ויצאו למחר, נשבה הרוח ונתפזרו העבים וזרחה החמה, ויצאו העם למלאכתן, וידעו שמלאכת שמים בידיהם\" (תענית כ\"ג ע\"א)."},{"i":1177,"n":"ר\u0027 הוריינא אחוי דר\u0027 שמואל בר סוסרטיי","l":"ה","b":"אמורא בדור השלישי - הרביעי. אין מימרה בש\"ס ממנו. נזכר בירושלמי (ב\"ב פ\"ט ה\"ג) יחד עם שני אחיו ר\u0027 שמואל בר סוסרטיי ואלכסנדרי, בענין ירושתם נראה שאחיו אלכסנדר לא היה חכם."},{"i":1178,"n":"רבי הורקנוס","l":"ה","b":"מובא בבבלי (יבמות ק\"ו ע\"ב). ע\"ע הורקנוס בנו של רבי אליעזר בן הורקנוס."},{"i":1179,"n":"הורקנוס בנו של רבי אליעזר בן הורקנוס","l":"ה","b":"תנא בדור השלישי. בנו של רבי אליעזר הגדול (סנהדרין ס\"ח ע\"א). חלק עם אביו (רב נסים גאון שבת ל\"ה ע\"ב). \"אמר לו הורקנוס בנו: \u0027בשביל וכו\u0027\". מוזכר תמיד בלי תואר ר\u0027. ו\"יוחסין\" ו\"סה\"ד\" מביאים אותו בתואר רבי. ואולי מה שמצינו במשנה (יבמות ק\"ו ע\"ב) \"וכשהקריא רבי הורקנוס\" - הכוונה להורקנוס זה."},{"i":1180,"n":"הושעיא","l":"ה","b":"רבי הושעיא, הוא רבי אושעיא, ורב אושעיא הוא רב הושעיא."},{"i":1181,"n":"רב הושעיא בר רב יצחק","l":"ה","b":"אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא בירושלמי (ביצה פ\"א ה\"ז), שם מקשים על דבריו מר\u0027 אבהו."},{"i":1182,"n":"רב הושעיא בריה דרב אידי","l":"ה","b":"מובא בבבלי (יבמות ל\"ו ע\"ב). ולפי גיר\u0027 רש\"י (שם ל\"ז ע\"א ד\"ה: הכא) צ\"ל: ר\u0027 יהושע בריה דרב אידי."},{"i":1183,"n":"ר\u0027 הושעיא בריה דר\u0027 שמלאי דקיסרין","l":"ה","b":"מובא בויק\"ר (פל\"א - ט\u0027), שם מסר בשמו של ר\u0027 יצחק בר זעירא."},{"i":1184,"n":"רבי הושעיא רבה","l":"ה","b":"הוא רבי אושעיא."},{"i":1185,"n":"ר\u0027 הושעיא תורגמנא","l":"ה","b":"אמורא ארץ ישראלי. מובא בב\"ר (פנ\"א - ט\u0027). ר\u0027 תנחום בר חייא [אמורא ארץ ישראלי בדור השלישי] מסר בשמו (שם)."},{"i":1186,"n":"רבי הושעיה בן לוי","l":"ה","b":"והוא רבי יהושע בן לוי (ירו\u0027, נזיר פ\"ו ה\"ט)."},{"i":1187,"n":"רבי הושעיה בר שמי","l":"ה","b":"והוא רבי אושעיא בר שימי (ירו\u0027, פאה פ\"ב ה\"ה)."},{"i":1188,"n":"רב הינך","l":"ה","b":"מובא בבבלי: \"א\"ל רב אידי בר אבין לרב חסדאי: \u0027הכי תנינא לה במתניתא דבי רב הינך\u0027. ואמרי לה \u0027במתניתא בר הינך כוותיך\u0027\" (פסחים ק\"א ע\"ב)."},{"i":1189,"n":"הלל (2)","l":"ה","b":"דור י\"ג להלל הזקן. חי בדור החמישי לאמוראים. שמו ייזכר בזכות שהתקין את הלוח העברי וקידוש החדשים ועיבור השנים עד ימות המשיח, כלשון הרמב\"ן (ספר הזכות, מסכת גיטין, פרק השולח): \"מימי הלל בנו של רבי יהודה נשיאה שנת תר\"ע לשטרות (ד\"א קי\"ח /853) בטלה הסנהדרין בא\"י, ובטלו ממנה מומחים, והוא שתקן סדר העיבור ומנה שנים וקידש חדשים לדורות\". בימיו היו גזירות קשות בא\"י, הנצרות החלה להרים ראש ורבות מישיבות א\"י נחרבו."},{"i":1190,"n":"רב הלל","l":"ה","b":"אמורא בבלי בדור הששי. תלמידו של רב כהנא (שבת ק\"ט ע\"א) ושל רבא (ביצה כ\"ו ע\"ב). חברו של רב אשי (יבמות כ\"א ע\"ב)."},{"i":1191,"n":"הלל אחוה דר\u0027 גמליאל זוגא","l":"ה","b":"אמורא ארץ ישראלי בדור השלישי, מובא בירושלמי (מו\"ק פ\"ג ה\"ה)."},{"i":1192,"n":"רבי הלל בי רב אלם","l":"ה","b":"מובא בירושלמי (כלאים פ\"א ה\"א). נראה, שהוא רבי הלל בריה דר\u0027 וולס."},{"i":1193,"n":"רבי הלל בן הליס","l":"ה","b":"מובא בירושלמי (חלה פ\"א ה\"ג), והוא ר\u0027 הלל בריה דר\u0027 וולס."},{"i":1194,"n":"רבי הלל בן פזי","l":"ה","b":"אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי יוסי (ירו\u0027, כתובות פ\"ט ה\"א). נראה, שקיבל גם מרבי יונה (ירו\u0027, דמאי פ\"ז ה\"ז). בנו רבי שמעון שאל ממנו (ירו\u0027, סנהדרין פ\"ז ה\"ה)."},{"i":1195,"n":"ר\u0027 הלל בר אלס","l":"ה","b":"הוא רבי הלל בריה דר\u0027 וולס."},{"i":1196,"n":"ר\u0027 הלל בר ברכיה","l":"ה","b":"מובא באיכ\"ר (פ\"א ל\"א)."},{"i":1197,"n":"ר\u0027 הלל בר הילני","l":"ה","b":"מובא בויק\"ר (פי\"ב - ה\u0027), והגיר\u0027 (איכ\"ר פ\"ב - י\"ב): ר\u0027 אילם."},{"i":1198,"n":"רבי הלל בריה דרבי וולס","l":"ה","b":"תנא בדור המעבר שבין התנאים לאמוראים. חי בדורו של רבי, היה מבני פמלייתו ושאל ממנו (ירו\u0027, גיטין פ\"ו ה\"ז). קיבל גם מאביו (ירו\u0027, כלאים ספ\"ב). ידוע מאמרו: \"מימות משה עד רבי לא מצינו תורה וגדולה במקום אחד\" (גיטין נ\"ט ע\"א). היה עשיר מופלג ונתן לרבי במתנה בגד ששוויו שלושים ריבוא דינר (ירו\u0027, כלאים פ\"ט ה\"א)."},{"i":1199,"n":"רבי הלל בריה דרבי שמואל בר נחמני","l":"ה","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מובא בבבלי (שבת פ\u0027 ע\"א). בנו של בעל האגדה רבי שמואל בר נחמני. נזכר יחד עם בעל האגדה רבי לוי (ברכות כ\"ח ע\"ב)."},{"i":1200,"n":"ר\u0027 הלל דכיפרא","l":"ה","b":"אמורא ארץ ישראלי בדור הששי. מובא בירושלמי (פסחים פ\"ח ה\"ח): \"ר\u0027 מנא הורי לר\u0027 הלל\", אך אין הכרח שהיה תלמידו."},{"i":1201,"n":"הלל הזקן (2)","l":"ה","b":"נשיא ארץ ישראל וראש שושלת הנשיאים של בית הלל, שנמשכה 51 דורות במשך כ - 054 שנה. נצר מגזע בית דוד (ירו\u0027, תענית פ\"ד ה\"ב). הוא וחברו שמאי היו אחרון הזוגות. וממנו ואילך החלה תקופת התנאים. נולד בבבל ג\u0027 תרמ\"ח (211 לפה\"ס) ומת בארץ ישראל בגיל 021 (בשנת תשס\"ח 8 לס\u0027) עלה מבבל בגיל 04 שנה, שימש חכמים 04 שנה ושימש את ישראל 04 שנה (ספרי ברכות סל\"ו). החל את נשיאותו 001 שנה לפני החורבן (שבת ט\"ו ע\"א). שימש את שמעיה ואבטליון (יומא ל\"ה ע\"ב). וזה הביא להתמנותו לנשיא (פסחים ס\"ו ע\"א), כי הלכה נתעלמה מבני בתירה: \"אמרו להן: אדם אחד יש שעלה מבבל, והלל הבבלי שמו, ששימש שני גדולי הדור שמעיה ואבטליון וכו\u0027, מיד הושיבוהו בראש ומינוהו נשיא עליהם\". היו לו תלמידים רבים: \"שמונים תלמידים היו לו להלל הזקן, שלשים מהן ראויים שתשרה עליהן שכינה כמשה רבינו, ושלשים מהן ראויים שתעמוד להם חמה כיהושע בן נון, עשרים בינונים. גדול שבכולן - יונתן בן עוזיאל, קטן שבכולן - רבן יוחנן בן זכאי\" (סוכה כ\"ח ע\"א). תלמידיו ותלמידי תלמידיו מכונים \"בית הלל\". תיקן תקנות גדולות: \"והלל התקין פרוזבול מפני תיקון העולם\" (ירו\u0027, גיטין פ\"ג). שימש את רבותיו בעוני גדול עד שאמרו עליו \"הלל מחייב את העניים\" (יומא ל\"ה ע\"ב). היה סמל הענווה והסבלנות. ועליו אמרו \"לעולם יהא אדם ענוותן כהלל\" (שבת ל\u0027 ע\"ב)."},{"i":1202,"n":"רבי הלל חתניה דר\u0027 יוסי בר אבון","l":"ה","b":"אמורא ארץ ישראלי בדור הששי. חתנו ותלמידו של רבי יוסי בר אבין (ירו\u0027, ברכות פ\"ב ה\"ה)."},{"i":1203,"n":"המכריעים לפני חכמים","l":"ה","b":"מובא בבבלי (קידושין כ\"ד ע\"ב), ולא איתפריש מי הם."},{"i":1204,"n":"רב המנונא","l":"ה","b":"בדור המעבר שבין התנאים לאמוראים בבבל. רבו של רבי חנינא בר חמא: כשישב רבי חנינא בר חמא לפני רבי, והוא שאלו: רבי, ממי למדת מקרא, ענה לו: \"אצל רב המנונא בבבל\" (ירו\u0027, תענית פ\"ד ה\"ב)."},{"i":1205,"n":"רב המנונא בריה דרב אדא בר אהבה","l":"ה","b":"מובא בקה\"ר (פ\"א - ה). יש כאן איזה שיבוש."},{"i":1206,"n":"המנונא בריה דרב יוסף","l":"ה","b":"אמורא בבלי בדור החמישי. תלמידו של רבא (ברכות כ\"ד ע\"א). ו\"דק\"ס\" גורס: ר\u0027 נחמיה בריה דרב יוסף. לפי גירסתו לא היה אמורא ששמו המנונא בריה דרב יוסף, שכן הוא מוזכר בש\"ס רק בפעם זאת."},{"i":1207,"n":"רב המנונא בריה דרבא מפשרוניא","l":"ה","b":"מובא בבבלי (גיטין מ\"ה ע\"ב). במקום אחר (מנחות מ\"ב ע\"א) הגיר\u0027: רב חיננא. היה בדור הרביעי לאמוראי בבל, בזמנו של רבא (חולין קי\"ב ע\"א)."},{"i":1208,"n":"רב המנונא ב\u0027","l":"ה","b":"אמורא בבלי בדור השני. תלמיד מובהק של רב (ב\"ק ק\"ו סע\"א), שקרא לו \"בני\" (עירובין נ\"ד ע\"א). בכל מקום שנאמר \"אמרי בי רב\" הכוונה לרב המנונא (סנהדרין י\"ז ע\"ב). היה הזקן שבחבורה (ירו\u0027, מעשרות ספ\"ד). חברו של רב חסדא (שבת צ\"ז ע\"א), ואולי הוא רב המנונא שקבע את הברכה \"אשר בחר בנו מכל העמים ונתן לנו את תורתו וכו\u0027\" (ברכות י\"א ע\"ב)."},{"i":1209,"n":"רב המנונא ג\u0027","l":"ה","b":"אמורא בבלי בדור השלישי. תלמידו של רב יהודה (שבועות ל\"ד ע\"ב). נראה, שגם היה תלמידו של רב הונא (קידושין כ\"ט ע\"ב). תלמיד חבר לרב חסדא (יבמות פ\"ג ע\"ב תד\"ה: אמר). רבו של רבי זירא (זבחים ק\"ה ע\"ב). נפטר יחד עם רבה בר רב הונא (מו\"ק כ\"ה ע\"ב)."},{"i":1210,"n":"רב המנונא ד\u0027","l":"ה","b":"אמורא בבלי בדור הרביעי. חברו המובהק של רבא (תמורה כ\"ה ע\"ב), ושל אביי ושקיל וטרי עמם (נזיר ס\"ד ע\"ב). רבו של רב פפא (נדה כ\"ז ע\"א)."},{"i":1211,"n":"רב המנונא זוטא","l":"ה","b":"מובא בבבלי (ברכות ל\"א ע\"א). רב המנונא זוטי."},{"i":1212,"n":"רב המנונא זוטי","l":"ה","b":"אמורא בבלי בדור השלישי. נשארה בידינו תפילת וידוי שלו, שבה מסיימים את תפילת יום כיפור: \"אלקי עד שלא נוצרתי איני כדאי וכו\u0027\" (ברכות י\"ז ע\"א), ורבא נהג לסיים בוידוי זה את תפילתו (שם). היה בחתונת מר, בנו של רבינא, ושר שם שיר מוסר בלשון חכמים (ברכות ל\"א ע\"א)."},{"i":1213,"n":"רב המנונא סבא","l":"ה","b":"אמורא בבלי בדור השני. תלמידו של רב (פסחים ק\"ה ע\"א)."},{"i":1214,"n":"ר\u0027 המנונא סבא","l":"ה","b":"תנא המוזכר ב\"זהר\", נפטר לפני רבי שמעון בר יוחאי. \"סה\"ד\" תמה על ה\"יוחסין\" ו\"שארית יוסף\" שלא הזכירוהו."},{"i":1215,"n":"רב המנונא ספרא","l":"ה","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי (ב\"ב פ\"ו ה\"ב) ששאל לרב חנינא ולא השיבו, ושאל לרבי ירמיה."},{"i":1216,"n":"רבי ווא","l":"ו","b":"הוא רבי אבא. כך מכונה בירושלמי."},{"i":1217,"n":"רבי וולוס","l":"ו","b":"ע\"ע רבי וולס."},{"i":1218,"n":"רבי וולס","l":"ו","b":"מן התנאים האחרונים בדור החמישי. אביו ורבו של רבי הלל בר ר\u0027 וולס (ירו\u0027, כלאים ספ\"ב) וגיר\u0027 רש\"י: רבי וולוס (סנהדרין ל\"ו ע\"א)."},{"i":1219,"n":"ויידא","l":"ו","b":"מובא בירושלמי: \"ויידא אמר דא וכו\u0027\" (פסחים פ\"ז הי\"ג), ופירש \"קרבן העדה\" ד\"ה: ויידא אמר דא: \"והיכן אמר דבר זה\". \"ציון ירושלים\" כתב שם: \"ויידא אמר דא, עיין \u0027קרבן העדה\u0027 שפירש היכן אמר דבר זה, ובאמת אין הפירוש כן, כי ויידא שם חכם, וכן משמעות הכ\"מ פ\"י מקרבן פסח ה\"ד וכו\u0027 וכדומה לי שבכה\"ג סוף או\"ח ראיתי שכתב זה\" עכ\"ל. וכתב \"שיירי כנסת הגדולה\" ב\"כללי התלמוד\" אות צד\"י: \"ויידא שם חכם בירושלמי דפסחים פרק צולין: ויידא אמר דא וכו\u0027, הביא הירושלמי הזה הרב הכ\"מ הלכות קרבן פסח וכו\u0027\"."},{"i":1220,"n":"ויתור מעונה","l":"ו","b":"אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי: \"רבי אבדימי דציפורי בשם רב יחונה משום ויתור מעונה\" (כתובות פ\"א ה\"ב). \"קרבן העדה\" ו\"פני משה\" פירשו שהוא חכם."},{"i":1221,"n":"וסטיני","l":"ו","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של ר\"ל (ב\"מ קי\"ז ע\"א). השם בא בשינויים: יוסטא יוסטני יוסטיני."},{"i":1222,"n":"ורדימס","l":"ו","b":"תנא בדור החמישי. בנו של רבי יוסי בר חלפתא מובא בבבלי: \"היינו ורדימס, היינו מנחם\" (שבת קי\"ח ע\"ב). ע\"ע רבי מנחם בר\u0027 יוסי בן חלפתא."},{"i":1223,"n":"זבדא","l":"ז","b":"ע\"ע רב זבדי."},{"i":1224,"n":"זבדא בר לוי","l":"ז","b":"מובא בבבלי (כריתות ה\u0027 ע\"א), והוא זבדי בר לוי."},{"i":1225,"n":"ר\u0027 זבדא חתניה דר\u0027 לוי","l":"ז","b":"מובא ברו\"ר (פ\"ב - י\u0027), ונראה שצ\"ל: ר\u0027 זכריה חתניה דר\u0027 לוי."},{"i":1226,"n":"רב זבדי","l":"ז","b":"אמורא בבלי בדור השלישי. תלמידו של ר\"ה. מובא בבבלי (ערכין י\"ג ע\"ב)."},{"i":1227,"n":"זבדי בר לוי","l":"ז","b":"אמורא ארץ ישראלי בדור הראשון. חברו של ר\u0027 יהושע בן לוי. אחרי פטירתו של ריב\"ל, נתגלה לו בחלומו והראה לר\u0027 זבדי את פניהם של צדיקים ושל רשעים שכבר מתו (קה\"ר פ\"ט - י\u0027). באגדה נזכר פעמים רבות. בהלכה מובא פעם בבבלי: \"אמר ר\u0027 יוחנן תני זבדי בר לוי\" (זבחים כ\"ח ע\"ב): ופעם בירושלמי, שר\u0027 אושעיא רבה שלחו להפריש תרומה ומעשרות (דמאי רפ\"ז)."},{"i":1228,"n":"רב זבדי בריה דרבי יעקב בר זבדי","l":"ז","b":"אמורא ארץ ישראלי בדור החמישי. בנו של האמורא רבי יעקב בר זבדי (תלמידו של רבי אבהו). מסר בשם רבי יונה (ירו\u0027, ברכות פ\"א ה\"ב)."},{"i":1229,"n":"ר\u0027 זבדיה חתניה דר\u0027 לוי","l":"ז","b":"מובא במדרש שמואל (פ\"ב - ג\u0027), ונראה שצ\"ל: ר\u0027 זכריה חתניה דר\u0027 לוי."},{"i":1230,"n":"זבולון בן דן","l":"ז","b":"תלמיד בימי שמואל בדור הראשון לאמוראי בבל, שלימדו אבי אביו מקרא ומשנה וגמרא הלכות ואגדות (קידושין ל\u0027 ע\"א)."},{"i":1231,"n":"רב זביד","l":"ז","b":"אמורא בבלי בדור החמישי. עמד בראש ישיבת פומבדיתא אחרי ר\u0027 נחמן בר\u0027 יצחק, בשנים ד\u0027 קל\"ו - קמ\"ד (673 - 483) (\"אגרת רב שרירא גאון\"). היה תלמידו של רבא ומסר הרבה בשמו (שבת צ\"ג ע\"א) וכן של אביי (סוטה ל\"ב ע\"ב). מחבריו היו ר\"פ (ברכות מ\"ה ע\"ב) ורב מרי (חולין קי\"ז ע\"א). ומתלמידיו היה רב כהנא [רבו של רב אשי] (ב\"מ ק\"א ע\"א). אמימר אמר משמו (חולין ע\"ו ע\"ב). החמיר על אנשי ריש גלותא והשקוהו כוס חומץ ומת (ע\"ז ל\"ח ע\"ב)."},{"i":1232,"n":"רב זביד אבוה דר\u0027 שמעון בר זביד","l":"ז","b":"מובא בבבלי (ברכות ל\"ח ע\"א) לגיר\u0027 \"דק\"ס\", ולפנינו הגיר\u0027: בר רב זביד אחוה דר\u0027 שמעון בר ר\u0027 זביד."},{"i":1233,"n":"רב זביד בר\u0027 אושעיא","l":"ז","b":"מובא בבבלי (יבמות צ\"ו ע\"א). \"סה\"ד\" כתב: \"ט\"ס וצ\"ל: בדבי ר\u0027 אושעיא\"."},{"i":1234,"n":"ר\u0027 זביד מנהרדעא","l":"ז","b":"אמורא בבלי בדור החמישי. והוא אינו רב זביד סתם (קידושין ע\"ב ע\"ב רש\"י). רבו המובהק של רב כהנא (יבמות י\"ח ע\"ב) ישב לפניו הרבה, וכשמת הספידו רב כהנא (מו\"ק כ\"ז ע\"ב)."},{"i":1235,"n":"זבידא","l":"ז","b":"חי בבבל בדור הששי. בגמרא מסופר: אמר רב אשי: \u0027אמר לי זבידא\u0027 (ע\"ז ט\"ז ע\"א) פרש\"י \"פטם היה\", ונראה שלא נמנה על החכמים."},{"i":1236,"n":"רבי זבידא","l":"ז","b":"אמורא ארץ ישראלי בדור הרביעי. ר\u0027 קרוספא (תלמידו ר\u0027 יוחנן) אמר לו: \"לא תתניה הכי\" (ירו\u0027, מע\"ש ספ\"א). מסר מאמרי הלכה בשם ר\u0027 אבא בר ממל (ירו\u0027, ב\"ק פ\"ט ה\"ז) ובשם ר\u0027 יסא [הוא ר\u0027 אסי] (ירו\u0027, יומא פ\"ח ה\"ז)."},{"i":1237,"n":"ר\u0027 זבידי חתניה דר\u0027 לוי","l":"ז","b":"מובא בירושלמי (כלאים פ\"א ה\"ח), ונראה שצ\"ל: ר\u0027 זכריה חתניה דר\u0027 לוי."},{"i":1238,"n":"זוג","l":"ז","b":"מובא בבבלי (סנהדרין י\"ב ע\"א). ע\"ע זוגא דמן הדייב."},{"i":1239,"n":"זוגא (2)","l":"ז","b":"אמורא בבלי בדור הראשון היה תלמידו של רבי (ירו\u0027, נדה פ\"ג ה\"ב), חברם של רבי חמא אבי ר\u0027 אושעיה ושל בר קפרא (שם) ו\"פני משה\" מפרש: \"זוגא: שם אמורא\". ובמקום אחר לפנינו: זונא (ירו\u0027, מע\"ש רפ\"ה) וגיר\u0027 \"יוחסין\" ו\"סה\"ד\": זוגא."},{"i":1240,"n":"זוגא דמהדייב","l":"ז","b":"מובא בבבלי (מו\"ק כ\"ח ע\"א). ע\"ע זוגא דמן הדייב."},{"i":1241,"n":"זוגא דמן הדייב","l":"ז","b":"מובא בבבלי (מו\"ק כ\"ח ע\"א: נדה כ\"א ע\"א). ומחלוקת בין רש\"י ל\"ערוך\", רש\"י מפרש שני תלמידי חכמים מאותו מקום (נדה שם), וכעין זה פירש\"י: \"שלחו ליה לרבא זוג שני תלמידי חכמים\" (סנהדרין י\"ב ע\"א). ותוספות כתבו: פי\u0027 ב\"ערוך\" שם חכם (נדה כ\"ה ע\"ב ד\"ה: זוזא) ובירושלמי: \"שאלתי לרבי יצחק בר אליעזר ואמר לי: \u0027כך נהג זוגא\u0027\" (דמאי פ\"ב ה\"א) ופירש \"פני משה\": \"כך נהג זוגא דרבנן\". ו\"סה\"ד\" כתב: \"ונראה כפי\u0027 ה\u0027ערוך\u0027 דזווא או זוגא הוא שם חכם לא לשון שנים\"."},{"i":1242,"n":"רבי זוהמאי","l":"ז","b":"תנא בדור החמישי. מובא בבבלי (ברכות נ\"ג ע\"ב) יחד עם רבי זילאי ורבי זיואי."},{"i":1243,"n":"זווא","l":"ז","b":"כך הגיר\u0027 לפי \"הערוך\". (מו\"ק כ\"ח ע\"א) ע\"ע זוגא דמן הדייב."},{"i":1244,"n":"זוזא","l":"ז","b":"ע\"ע זוגא דמן הדייב."},{"i":1245,"n":"זוטי","l":"ז","b":"מובא בבבלי (שבת קנ\"ז ע\"א). ע\"ע רב זוטי."},{"i":1246,"n":"רב זוטי","l":"ז","b":"אמורא בבלי בדור החמישי. מובא שלוש פעמים בבבלי (שבת קנ\"ז ע\"א: נדרים ע\"ז ע\"א: יבמות כ\"ה ע\"ב). נראה, שהיה התנא שונה הברייתות בישיבת רב פפי."},{"i":1247,"n":"רב זוטי דבי רב פפי","l":"ז","b":"ע\"ע רב זוטי."},{"i":1248,"n":"רב זוטרא","l":"ז","b":"מובא בבבלי (מכות ו\u0027 ע\"ב) שמתקיף על דברי רב נחמן. ואולי הוא מר זוטרא."},{"i":1249,"n":"רבי זוטרא","l":"ז","b":"תנא דברייתא בדור החמישי. יש סבורים שהיה בבלי. חלק עם ר\u0027 יאשיה (ברכות י\"ג ע\"ב)."},{"i":1250,"n":"רב זוטרא בר טוביא","l":"ז","b":"אמורא בבלי בדור החמישי. בש\"ס אין מימרה בשמו. מובא בבבלי בהקשר למתנה שאמו נתנה לו, ובא הענין לפני ביבי בר אביי (ב\"ב קנ\"א ע\"א)."},{"i":1251,"n":"רב זוטרא בר טוביה","l":"ז","b":"אמורא בבלי בדור השני - השלישי. תלמידו של רב. מסר כמה ממאמריו של רב בהלכה ובאגדה (ברכות מ\"ג ע\"ב). כן היה תלמידו של רב יהודה. פעם חש שרב יהודה נפגע מדבריו, ונהג בעצמו נזיפות ליום אחד (מו\"ק ט\"ז ע\"ב). כן מסר מאמר אחד בשם ר\"נ (יומא פ\"ו ע\"ב)."},{"i":1252,"n":"רב זוטרא בריה דרב זורא","l":"ז","b":"כך גירסת \"יתו\"א\", ולפנינו רב זוטרא בריה דרבי זירא."},{"i":1253,"n":"רב זוטרא בריה דרב מרי","l":"ז","b":"ע\"ע מר זוטרא בריה דרב מרי."},{"i":1254,"n":"רב זוטרא בריה דר\u0027 זירא","l":"ז","b":"מובא בבבלי (שבת קנ\"ז ע\"א). נראה, שהוא בנו של רבי זירא."},{"i":1255,"n":"רב זוטרא בריה דר\u0027 זעירא","l":"ז","b":"הוא רב זוטרא בריה דר\u0027 זירא."},{"i":1256,"n":"זוטרא חסידא","l":"ז","b":"ע\"ע מר זוטרא חסידא."},{"i":1257,"n":"רב זוטראי","l":"ז","b":"מובא בבבלי (שבת קכ\"ד ע\"ב) שהקשה על דברי רב יהודה אמר שמואל. \"דק\"ס\" גורס: \u0027מר זוטרא\u0027. ולגירסתו לא היה כלל חכם בשם זה."},{"i":1258,"n":"זונא","l":"ז","b":"מובא (ירו\u0027, מע\"ש פ\"ד ה\"א). שאל מרבי וכנראה שהוא זונין ששאל מרבי (ע\"ע)."},{"i":1259,"n":"זונין (2)","l":"ז","b":"ממונה של ר\"ג הנשיא. חי בדור השני לתנאים (פסחים מ\"ט ע\"א). בנו הוא התנא בייתוס בן זונין. יש זונין ששאל לר\"ע (ע\"ז נ\"ה ע\"א) ופרש\"י: ישראל היה. \"חידושי אגדות\" מפרש שהיה עכו\"ם. \"יתו\"א\" גרס: זונן רבה, ואם כן לדעתו היה חכם."},{"i":1260,"n":"רבי זיואי","l":"ז","b":"תנא בדור החמישי. מובא בבבלי, שחלק עם ר\u0027 זילאי ור\u0027 אחא (ברכות נ\"ג ע\"ב)."},{"i":1261,"n":"זיותאי","l":"ז","b":"תנא בדור החמישי. חתנו של ר\"מ מובא בקה\"ר (פ\"ט - ח\u0027) שאמר משום ר\"מ. אותו דבר מובא בבבלי, אך בלי הזכרת שמו המלא (שבת קנ\"ג ע\"א)."},{"i":1262,"n":"ר\u0027 זיכיי","l":"ז","b":"מובא בירו\u0027, (סוכה פ\"ד ה\"ג) והוא ר\u0027 זכאי תלמידו דר\u0027 יוחנן."},{"i":1263,"n":"רבי זילאי","l":"ז","b":"תנא בדור החמישי. מובא בבבלי (ברכות נ\"ג ע\"ב), חלק עם רבי זיואי ור\u0027 אחא."},{"i":1264,"n":"רבי זינון החזן","l":"ז","b":"חזן ביבנה בדור השני - השלישי של התנאים. נוכח ביבנה בעת שהעבירו את ר\"ג מנשיאותו (ירו\u0027, ברכות פ\"ד ה\"א): \"אמרו לרבי זינון החזן: \u0027אמור\u0027 התחיל ואמר וכו\u0027\" ובבבלי הגיר\u0027: \"ואמרו לחוצפית המתורגמן עמוד [שתוק], ועמד\" (ברכות נ\"ז ע\"ב)."},{"i":1265,"n":"זירא","l":"ז","b":"פעמים זעירא ופעמים זעירי."},{"i":1266,"n":"רב זירא","l":"ז","b":"הוא רבי זירא (ע\"ע)."},{"i":1267,"n":"רבי זירא","l":"ז","b":"מגדולי האמוראים בדור השלישי. ידוע גם כר\u0027 זעירא (ברכות נ\"ה ע\"ב). נקרא רב זירא, וכשעלה לא\"י ונסמך קראוהו רבי זירא (כתובות מ\"ג ע\"ב ברש\"י). ותוספות חולקים על רש\"י (מנחות מ\u0027 ע\"ב) וסוברים שהיו שנים: רב זירא ורבי זירא. נולד בבבל. למד בסורא אצל רב הונא (מנחות כ\"ט ע\"א), ובפומבדיתא לפני רב יהודה (יבמות ל\"ח ע\"ב). מסר הרבה בשם רב (שבת כ\"א ע\"ב) ובשם שמואל (שם נ\"ג ע\"א). לאחר שעלה לארץ ישראל (כתובות קי\"ב ע\"א) צם 001 תעניות, כדי לשכוח את דרכי לימודם של הבבלים (ב\"מ פ\"ה ע\"א). לבסוף אף נהג לומר: \"בבלאי טפשאי\" (ביצה ט\"ז ע\"א). בא\"י קיבל מרבי יוחנן (קידושין נ\"ב ע\"א), מריש לקיש (עירובין פ\u0027 ע\"א), ומר\"א (ירו\u0027, תרומות פי\"א סה\"ג), מר\u0027 אמי (חולין כ\"א ע\"א) ומר\u0027 אסי (ב\"ב פ\"ד ע\"ב). הקרוב אליו ביותר מבין תלמידיו הרבים היה רבי ירמיה, אף הוא בבלי, וקרא לו \"ירמיה בני\" (מו\"ק ד\u0027 ע\"א). צם 001 תעניות כדי להנצל מאש גיהנום (ב\"מ פ\"ה ע\"א). התפרנס מפשתן. אבי ר\"ז, היה גבאי המלך (סנהדרין כ\"ה ע\"ב). בנו רבי אהבה, היה אמורא בדור הרביעי (עירובין צ\"ו ע\"ב). האריך ימים (מגילה כ\"ח ע\"א)."},{"i":1268,"n":"רבי זירא בר אדא","l":"ז","b":"מובא בבבלי (כריתות כ\"ז ע\"א) והוא ט\"ס וצ\"ל: רבי חייא בר אבא."},{"i":1269,"n":"ר\u0027 זירא בר ממל","l":"ז","b":"מובא בבבלי (קידושין ט\u0027 ע\"א). כתב \"סה\"ד\": \"ומצינו ר\"ז אמר לרבי אבא בר ממל, ואולי ט\"ס כאן\"."},{"i":1270,"n":"רבי זירא בר רב","l":"ז","b":"אמורא בדור השלישי. מובא ב\"זוהר\": \"רבי אבא הוה אזל ללוד פגע ביה ר\u0027 זירא בר רב\" (נשא קמ\"ח)."},{"i":1271,"n":"רב זירא ב\u0027","l":"ז","b":"אמורא בבלי בדור הרביעי - החמישי. תלמידו של רב יוסף (ב\"ב קנ\"ד ע\"ב). חברם של אביי (כריתות י\"ב ע\"ב) ושל רבא (קידושין ע\"ג ע\"א). עלה לארץ ישראל והיה תלמידו המובהק של רבי ירמיה (ירו\u0027, ברכות פ\"ו ה\"ו) ותלמידו של ר\u0027 יוסי (ירו\u0027, כתובות פ\"א ה\"ט) ושל ר\u0027 מנא (ירו\u0027, נזיר פ\"ט ה\"ב). לאחר פטירתו של רב יוסף היו ארבעה מועמדים לתפקיד ראש ישיבת פומבדיתא: אביי, רבא, רבי זירא ורבה בר מתנה, ומתוכם נבחר אביי (סוף הוריות)."},{"i":1272,"n":"רבי זכאי (2)","l":"ז","b":"אמורא בבלי בדור השני. עלה לארץ ישראל ושימש \"תנא\" שונה ברייתות, בישיבתו של רבי יוחנן: \"תני רבי זכיי קומי רבי יוחנן וכו\u0027, א\"ל ר\"י: בבלייא עברת בידך תלתא נהרין ואיתברת\" (ירו\u0027, יבמות פ\"ח ה\"ג). נראה שנסמך, שכן קראו לו רבי זכאי. רב יהודה ורבי אבא למדו בבי מעצרתא דבי רב זכאי (עירובין מ\"ט ע\"א). ומר עוקבא קיבל ממנו (סנהדרין ל\u0027 ע\"א)."},{"i":1273,"n":"רבי זכאי דאלכסנדריאה","l":"ז","b":"אמורא ארץ ישראלי בדור החמישי. ישב באלכסנדריה במצרים. נראה שלמד בישיבות א\"י ונסמך וקיבל תואר רבי. רבי יוסי בר בון אמר עליו, שהוא יודע למתק את הים הגדול ויודע את חשבון המים שבים (ירו\u0027, ע\"ז פ\"ב ה\"ח)."},{"i":1274,"n":"רבי זכאי דכבול","l":"ז","b":"אמורא בדור הראשון. היה מגדולי עירו (ויק\"ר פ\"כ - ג\u0027). רבי חיננא בר אנדריי (מדור הרביעי - החמישי) מסר בשמו (ירו\u0027, מגילה פ\"ד ה\"ה). יהודה והלל (נכדי רבי) התאכסנו אצלו בשהותם בעיר כבול (שמחות פ\"ח)."},{"i":1275,"n":"רבי זכאי דשאב","l":"ז","b":"אמורא בדור השלישי - הרביעי. מובא מספר פעמים במדרשים (במד\"ר פי\"ז - ג\u0027). מסר בשם רבי שמואל בר נחמן (תנחומא, הוצאת בובר, פ\u0027 חוקת סי\u0027 י\"ח)."},{"i":1276,"n":"זכאי טבחא","l":"ז","b":"אמורא ארץ ישראלי בדור השלישי. אמר בשם רבי יוחנן (ירו\u0027, מגילה פ\"ד ה\"א)."},{"i":1277,"n":"ר\u0027 זכאי רבה","l":"ז","b":"מובא בב\"ר (פצ\"ז - ג\u0027)."},{"i":1278,"n":"זכיי","l":"ז","b":"ע\"ע רבי זכאי."},{"i":1279,"n":"רבי זכיי רבי אלכסנדריה","l":"ז","b":"מובא בירושלמי (יבמות פ\"ז ה\"ה), וצ\"ל: רבי זכאי דאלכסנדריה."},{"i":1280,"n":"רבי זכריה","l":"ז","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי אמי (ירו\u0027, סנהדרין פ\"א ה\"א). מסר עם ר\u0027 עזריה (תלמידו של רבי מנא) בשם ר\u0027 יצחק בר מריון (מדרש שמואל פכ\"ב - ה\u0027)."},{"i":1281,"n":"רבי זכריה בן אבקולס","l":"ז","b":"תנא בדור הראשון. חי בירושלים בדור החורבן. הוא שעיכב את הקרבת קרבנו של קיסר רומי, לאחר שהטילו בו מום. דבר זה גרם לחורבן בית המקדש השני (גיטין נ\"ו ע\"א), ור\u0027 יוחנן אמר: \"ענותנותו של ר\u0027 זכריה בן אבקולס החריבה את ביתנו ושרפה את היכלנו והגליתנו מארצנו\" (שם). היה בין החכמים שהשתתפו בסעודת קמצא ובר קמצא ולא מיחה כשגירשו את בר קמצא (איכ\"ר פ\"ד ג\u0027). מובאת ממנו הלכה אחת (שבת קמ\"ג ע\"א)."},{"i":1282,"n":"רבי זכריה בן הקצב","l":"ז","b":"תנא בדור הראשון. חי בירושלים בדור החורבן ונשבע: \"המעון הזה לא זזה ידה מתוך ידי [נשבע שאשתו לא נאנסה], משעה שנכנסו גויים לירושלים ועד שיצאו\", אך עדותו לא נתקבלה שכן לא היו לו עדים ואין אדם מעיד על עצמו (כתובות כ\"ז ע\"א), והיות והיה כהן אסרו עליו חכמים את אשתו, ואעפ\"כ לא שילחה אלא ייחד לה בית בחצרו ולא היה מתייחד עמה אלא בפני בניה (שם). נזכר יחד עם ר\u0027 יוסי הכהן, תלמיד רבי יוחנן בן זכאי (עדויות פ\"ח מ\"ב). שמואל אמר: \"אפס זכריה\" (ב\"ב קי\"א ע\"א) ופירש רשב\"ם: \"אין הלכה כמותו\"."},{"i":1283,"n":"זכריה בן קבוטל","l":"ז","b":"חכם בדור הראשון של תנאים חי בזמן הבית. סיפר שפעמים רבות קרא לפני כהן גדול ביום כיפור בספר דניאל (יומא י\"ח ע\"ב) בן בנו היה מהתנאים בדור השלישי, ששלחוהו יחד עם יוסי בן כיפור לר\u0027 חנניה בן אחי ר\u0027 יהושע לצוות עליו להפסיק לעבר שנים בבבל (ברכות ס\"ג ע\"א)."},{"i":1284,"n":"ר\u0027 זכריה חתניה דר\u0027 לוי","l":"ז","b":"אמורא ארץ ישראלי בדור הרביעי. חתנו של בעל האגדה המפורסם רבי לוי. יש ממנו מאמרי הלכה (ירו\u0027, פסחים פ\"א ה\"א) ומאמרי אגדה (ירו\u0027, תענית פ\"ד ה\"ה). היו מלעיזים עליו שאינו צריך ליטול מן הצדקה ונוטל, וכשנפטר התברר כי את שלקח נתן לאחרים (ירו\u0027, סוף פאה)."},{"i":1285,"n":"ר\u0027 זכריה טבחא","l":"ז","b":"מובא בפס\u0027 רבתי (ר\"פ אפרים), וצ\"ל: רבי זכאי טבחא."},{"i":1286,"n":"רבי זמינא","l":"ז","b":"אמורא בדור הרביעי. חברו של ר\u0027 יונה (ירו\u0027, בכורים פ\"ג סה\"ג)."},{"i":1287,"n":"זעיר בן חנינא","l":"ז","b":"מובא בירושלמי (תרומות ספ\"ח). נראה, שהוא זעירא בר חיננא."},{"i":1288,"n":"זעירא","l":"ז","b":"פעמים זירא או זעירי."},{"i":1289,"n":"ר\u0027 זעירא","l":"ז","b":"מובא בבבלי (ברכות נ\"ה ע\"ב), והוא רבי זירא."},{"i":1290,"n":"זעירא א\u0027","l":"ז","b":"תנא בדור השלישי. \"דאמר רבי יאשיה: שלשה דברים סח לי זעירא מאנשי ירושלים\" (סוטה כ\"ה ע\"א, פרש\"י שהיה מאנשי ירושלים). ובירושלמי הגיר\u0027: \"משום אנשי ירושלים\" (סוטה פ\"ד ה\"ב וסנהדרין פ\"ח ה\"ו) וכן בספרי (פ\u0027 תצא): \"סח לי זעירא משום אנשי ירושלים וכו\u0027 וכשבאתי אצל רבי יהודה בן בתירא לנציבין על שנים הודה לי וכו\u0027\" (ירו\u0027, סנהדרין שם)."},{"i":1291,"n":"רבי זעירא בר אבונא","l":"ז","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. אמר בשם רבי ירמיה (ירו\u0027, שבת פ\"א סה\"ד)."},{"i":1292,"n":"רבי זעירא בר בא","l":"ז","b":"מובא בירושלמי (נזיר פ\"ז ה\"א), ונראה שט\"ס בשם וצ\"ל: רבי זעירא [הוא רבי זירא]."},{"i":1293,"n":"זעירא בר חייא בר אשי","l":"ז","b":"אמורא בבלי בדור השלישי. חלק עם רבי זעירא (ירו\u0027, שבת פ\"ז ה\"ב)."},{"i":1294,"n":"זעירא בר חיננא","l":"ז","b":"אמורא ארץ ישראלי בדור השני - השלישי. בירושלמי נזכר בלי תואר \"רבי\". ובבבלי נזכר רק פעם אחת בתואר \"רבי\" (נדה נ\u0027 ע\"ב). מסר בשם רבי חנינא [בר חמא] (ירו\u0027, סנהדרין רפ\"ד). פעם נשבה בידי גזלנים ונעשה לו נס וניצל (ירו\u0027, תרומות ספ\"ח)."},{"i":1295,"n":"רבי זעירא בר חמא","l":"ז","b":"חי בארץ ישראל בדור השני לתנאים. סיפר לרב יוסף בנו של ריב\"ל ממנהגי אביו ביום הכיפורים (יומא ע\"ח ע\"א). נראה, שהגיע לזקנה מופלגת, שכן התארחו אצלו ריב\"ל (מן הדור הראשון) וגם ר\u0027 אמי ור\u0027 אסי [מן הדור השלישי] (שם). נראה, שגם ר\"א התאכסן אצלו (ירו\u0027, ביצה פ\"ג ה\"ח)."},{"i":1296,"n":"ר\u0027 זעירא בר חנינא","l":"ז","b":"מובא בבבלי (נדה נ\u0027 ע\"ב), והוא זעירא בר חיננא."},{"i":1297,"n":"זעירא בר ר\u0027 אבהו","l":"ז","b":"אמורא ארץ ישראלי בדור הרביעי. בנו של האמורא המפורסם ר\u0027 אבהו. מושבו היה בקיסרין ושם היה דורש (ב\"ר פ\"ג - ו\u0027). מסר בשם אביו (ירו\u0027, ברכות פ\"ט ה\"א)."},{"i":1298,"n":"ר\u0027 זעירא דכפר ראמין","l":"ז","b":"מובא ב\"זוהר\" (שמיני מא). גם בנו רבי יוסי נמנה על החכמים והיה תלמידו."},{"i":1299,"n":"זעירא יתמא","l":"ז","b":"מובא: \"אמר רב אשי אנא ורב כהנא חתמינן אשטרא דאימיה דזעירא יתמא\" (גיטין נ\"ב ע\"ב). אין ראיה שנמנה עם החכמים."},{"i":1300,"n":"זעירא מדיהבות","l":"ז","b":"אמורא בבלי בדור הששי. מצינו שהקשה לרבינא (תענית ז\u0027 ע\"ב). רש\"י גורס: מר זעירא מדיהבת."},{"i":1301,"n":"ר\u0027 זעירא תנאי","l":"ז","b":"מובא בירושלמי: \"ר\u0027 זעירא תנאי, אחוה דר\u0027 חייא בר אבא\" (ברכות פ\"א ה\"א)."},{"i":1302,"n":"זעירי","l":"ז","b":"אמורא ארץ ישראלי בדור השני - השלישי. ירד לבבל (ברכות כ\"ב ע\"א). תלמידו המובהק של רבי יוחנן (קידושין ע\"א ע\"ב). קיבל מרבי חייא [שהיה רבו של רבי יוחנן] (שבת קנ\"ו ע\"א). היה חברו של רב (ב\"ק ל\u0027 ע\"ב). תלמידו המובהק היה רב חייא בר אשי (שבת ק\"ט ע\"ב). קיבלו ממנו גדולי תלמידי רב יהודה (מנחות כ\"א ע\"א), רב גידל (יומא ע\"ז ע\"ב), רב חסדא (ברכות מ\"ג ע\"א), וכן רב יוסף ורבה (נדרים מ\"ו ע\"ב). רבא אמר: \"כל מתניתא דלא מפרשא לה רב זעירי, לא מיפרשא\" (זבחים מ\"ג ע\"ב). \"סה\"ד\" כתב: \"נראה תיבת רב ט\"ס, כי בכל מקום אינו נקרא בשם רב זעירי\"."},{"i":1303,"n":"זקני דרום","l":"ז","b":"מובאים בבבלי (זבחים כ\"ב ע\"ב) ור\"ל הקשה עליהם. ותוספות כתבו (שם כ\"ג ע\"א ד\"ה: זקני): \"וזקני דרום תנאי הוו\"."},{"i":1304,"n":"זקני הגליל","l":"ז","b":"מובאים בירושלמי (נדרים פ\"ט ה\"א). ר\"ש בר רבי לא מצא פתח להתרת נדר, עד שבא אחד מזקני גליל (שם)."},{"i":1305,"n":"זקנים הראשונים","l":"ז","b":"קדומים מרבי עקיבא: \"זקנים הראשונים אמרו וכו\u0027, עד שבא ר\"ע וכו\u0027\" (שבת ס\"ד ע\"ב)."},{"i":1306,"n":"ר\u0027 זריקא (2)","l":"ז","b":"אמורא בבלי בדור השלישי. תלמידם של ר\"ה (סוטה כ\"א ע\"ב), רב יהודה (ביצה ז\u0027 ע\"ב) ורב המנונא (ירו\u0027, עירובין רפ\"י). עלה לארץ ישראל וקיבל מרבי יוחנן (גיטין כ\"ג ע\"א) ומריש לקיש (ברכות י\"א ע\"ב) ומר\"א (סוטה ד\u0027 ע\"ב). אח\"כ קיבל גם מרבי אמי (ברכות ג\u0027 ע\"ב). חבריו היו רבי ביבי (מנחות ק\"ג ע\"ב) ורבי ירמיה (גיטין מ\"ד ע\"א). רבי חזקיה אמר משמו (ירו\u0027, פ\"א ה\"א)."},{"i":1307,"n":"ר\u0027 זריקן","l":"ז","b":"הוא ר\u0027 זריקא."},{"i":1308,"n":"ר\u0027 זריקן בר חמוי דר\u0027 זריקן","l":"ז","b":"מובא בירושלמי (ברכות ספ\"ז)."},{"i":1309,"n":"רב חבוניה","l":"ח","b":"כך גירסת \"יתו\"א\" ולפנינו (חולין נ\"א ע\"א) רב חביבא, ובאמת אין אנו מוצאים בשום מקום בתלמוד רב חבוניה, אך לגירסתו היה אמורא בבלי בדור החמישי - הששי."},{"i":1310,"n":"רב חביבא (2)","l":"ח","b":"אמורא בבלי בדור הששי. בנו של רבינא (חברו של רב אשי). נשא לאשה את בתו של רב חביבא (נדה ס\"ו סע\"א), לגיר\u0027 הרי\"ף, הרא\"ש והרשב\"א ולפנינו: רב חנינא. חלק עם מר בר רב אשי (ב\"ב קמ\"ג ע\"ב). יתכן לומר שרב חביבא סתם הוא רב חביבא מסורא דפרת, ששקיל וטרי תמיד עם רבינא (מו\"ק כ\u0027 ע\"א: כ\"ד ע\"ב)."},{"i":1311,"n":"רב חביבא בר סורמקי","l":"ח","b":"אמורא בבלי בדור הששי. \"אמר רב חביבא: \u0027אשתעי לי רב חביבא בר סורמקי וכו\u0027\" (ב\"מ פ\"ה ע\"ב). היה בארץ ישראל: \"כי סליק רב חביבא בר סורמקי, אמרה וכו\u0027\" (יומא י\u0027 ע\"א). וגירסת \"יתו\"א\": סורמסי."},{"i":1312,"n":"רב חביבא בריה דרב יוסף בריה דרבא","l":"ח","b":"אמורא בבלי בדור החמישי - הששי. בן בנו של רבא ואמר בשמו של זקנו (ב\"ב קמ\"ג ע\"ב). היו לו שני אחים חכמים: רבי אבא (חולין קמ\"א ע\"א) ונאנאי (יבמות ס\"ו ע\"ב)."},{"i":1313,"n":"רב חביבא בריה דרבא","l":"ח","b":"מובא בבבלי (ע\"ז ל\"ד ע\"ב). וגיר\u0027 \"דק\"ס\": רב אחא בריה דרבא."},{"i":1314,"n":"חביבא מחוזנאה","l":"ח","b":"אמורא בבלי בדור הששי. היה כתלמיד לרב אשי ושקיל וטרי עמו (עירובין נ\"ז ע\"א)."},{"i":1315,"n":"רב חביבא מסורא דפרת","l":"ח","b":"מובא (ב\"מ ק\"ו ע\"ב), ונראה שהוא רב חביבא סתם."},{"i":1316,"n":"חביבי","l":"ח","b":"רב קרא כך לר\u0027 חייא דודו (ב\"ב מ\"ו ע\"א)."},{"i":1317,"n":"רב חגא (2)","l":"ח","b":"אמורא בבלי שעלה לארץ ישראל. תלמידו של רב הונא (תלמידו דרב) (מו\"ק כ\"ה ע\"א). כשנפטר רב הונא והעלו ארונו לא\"י היה ר\u0027 חגא בן 08 שנה, ונכנס למערת ר\u0027 חייא והכפילו לו את שנותיו וחי 061 שנה (ירו\u0027, כתובות פי\"ב ה\"ג)."},{"i":1318,"n":"ר\u0027 חגאי","l":"ח","b":"מובא ב\"זוהר\" (לך פ\"ט)."},{"i":1319,"n":"ר\u0027 חגי","l":"ח","b":"הוא ר\u0027 חגא או ר\u0027 חגיי."},{"i":1320,"n":"ר\u0027 חגי בן אלעזר","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. מאמרים ספורים באגדה הובאו בשמו במדרשים (שמו\"ר פמ\"ב - ג\u0027). רבי יהודה בן שלום (תלמידו של רבי יוסי) מסר בשמו (שו\"ט קי\"ט - ג\u0027)."},{"i":1321,"n":"רב חגיי","l":"ח","b":"מובא בירושלמי (כתובות פי\"ב ה\"ג), והוא רב חגא."},{"i":1322,"n":"חגרא אחיו דר\u0027 בא בר בינא","l":"ח","b":"אמורא בבלי בדור השני. מובא בירושלמי (מגילה פ\"א ה\"ט), שנתן ספר תורה לרב חננאל לקרות בו."},{"i":1323,"n":"רבי חדקא","l":"ח","b":"תנא בדור הרביעי. מתלמידיו של ר\"ע. חברו של רבי שמעון השקמוני (ב\"ב קי\"ט ע\"א). מפורסמת ההלכה שלו שחייב אדם לאכול בשבת ארבע סעודות (שבת קי\"ז ע\"ב). ממאמריו מובאים באגדה (תענית י\"א ע\"ב: דרך ארץ זוטא פ\"א). גירסת \"יתו\"א\": חדקאי."},{"i":1324,"n":"חולפנא","l":"ח","b":"מובא בבבלי (ערכין כ\"ח ע\"ב), ונראה שזהה לאולפנא (ע\"ע)."},{"i":1325,"n":"ר\u0027 חונא","l":"ח","b":"מובא בירושלמי (גיטין פ\"א ה\"ב), והוא רב הונא."},{"i":1326,"n":"רב חונא בר אדא","l":"ח","b":"מובא בירושלמי (שביעית פ\"י ה\"ג)."},{"i":1327,"n":"רב חונא בר חייא","l":"ח","b":"מובא בירושלמי (שביעית פ\"ב ה\"ה), והוא רב הונא בר חייא."},{"i":1328,"n":"רבי חונא דברת חוורין","l":"ח","b":"הוא רבי חוניה דברת חוורין."},{"i":1329,"n":"ר\u0027 חונא דציפורין","l":"ח","b":"והוא רב הונא רובא דציפורן."},{"i":1330,"n":"חונה","l":"ח","b":"הוא הונא."},{"i":1331,"n":"ר\u0027 חונה בר חמא","l":"ח","b":"מובא בירושלמי (שביעית פ\"ב)."},{"i":1332,"n":"ר\u0027 חונה בר יוסף","l":"ח","b":"מובא (ירו\u0027, תענית פ\"ד ה\"ה), והוא ר\u0027 הונא בר יוסף."},{"i":1333,"n":"ר\u0027 חונה רבה דציפורין","l":"ח","b":"מובא בירושלמי (ר\"ה ספ\"ד), והוא רב הונא רובא דציפורין."},{"i":1334,"n":"ר\u0027 חוני","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי אמי (ירו\u0027, שקלים פ\"ו ה\"ד)."},{"i":1335,"n":"חוני המעגל","l":"ח","b":"חכם קדמון בימי ה\"זוגות\". חי בדורו של שמעון בן שטח (תענית י\"ט ע\"א). היה חסיד גדול ומלומד בנסים. מנהגו היה להתוות עיגול מסביבו ולעמוד בתוכו ולהתפלל עד שנתקבלה בקשתו (שם), ומכאן כינויו (רש\"י מנחות צ\"ד ע\"ב ד\"ה: דעגיל). \"אמר: \u0027רבש\"ע, נשבע אני בשמך הגדול שאיני זז מכאן עד שתרחם על בניך\" (שם), שלח לו שמעון בן שטח: \u0027אלמלא חוני אתה, גוזרני עליך נידוי\u0027\" (שם). מסופר שישן 07 שנה וכשהתעורר לא הכירו איש ולא כיבדוהו, וביקש רחמים, ומת (תענית כ\"ג ע\"א). וכן מסופר, שכאשר צר הורקנוס על אריסטובולוס, תפסוהו אנשי הורקנוס ורצו שיקלל בשם ה\u0027 את אריסטובולוס, וכשסירב הרגוהו (\"קדמוניות היהודים\"), יתכן שהיו שני חוני המעגל, והשני מיוצאי חלציו של הראשון. \"סה\"ד\" משער, שהראשון ישן 07 שנה, והשני היה בן בנו והוא הנהרג. ולפי הירושלמי נראה שהיו שנים: \"חונה המעגל בר בריה דחוני המעגל הוה\" (תענית פ\"ג ה\"ט) ו\"יתו\"א\" כתב בהרחבה על חוני המעגל וסיים: \"והירושלמי חולק על גמ\u0027 דידן\"."},{"i":1336,"n":"חוני הקטן","l":"ח","b":"מובא בתוספתא: \"והלא במעמד כולם זקני ב\"ש ירד חוני הקטן ואמר וכו\u0027\" (ר\"ה ספ\"ב)."},{"i":1337,"n":"חוניא","l":"ח","b":"כהן גדול. בנו של שמעון הצדיק (מנחות ק\"ט ע\"ב). שמעון הצדיק ציוה לפני פטירתו, שישמש במקומו ככהן גדול, ושמעי אחיו הגדול, שנתקנא בו, לימדו את סדר העבודה והטעהו, ורצו הכהנים להרוג את חוניא, וברח לאלכסנדריה שבמצרים ובנה שם מזבח (שם)."},{"i":1338,"n":"ר\u0027 חוניא","l":"ח","b":"מובא בירושלמי (נדרים פ\"ג ה\"ב)."},{"i":1339,"n":"חוניא בן יוסף בן פכסס הכהן","l":"ח","b":"חי בזמן התנאים. מובא בירושלמי: \"מעשה ביוסף בן פכסס שעלתה נומי על רגלו, וביקש הרופא לחותכה וכו\u0027, קרא לנחונייה בנו וא\"ל: עד כאן היית חייב לטפל בי וכו\u0027\" (נזיר רפ\"ז). אין הוכחה שנמנה עם החכמים."},{"i":1340,"n":"ר\u0027 חוניא בר אלעזר","l":"ח","b":"מובא בב\"ר (פמ\"ב - ג\u0027)."},{"i":1341,"n":"ר\u0027 חוניא חמוהי דר\u0027 אמי","l":"ח","b":"מובא ב\"ילקוט\" (מלכים א\u0027 רמז קעט)."},{"i":1342,"n":"רבי חוניה דברת חוורין","l":"ח","b":"אמורא ארץ ישראלי בדור המעבר בין התנאים לאמוראים. קיבל מרבי שמעון בן חלפתא (ירו\u0027, שקלים פ\"ד רה\"ב). נראה, שמושבו היה בעבר הירדן בהר חוורן. לקח חלק בעיבור השנה בטבריה (ירו\u0027, ע\"ז פ\"ג ה\"א). היה בעל מופת, וכשעבר את ים כנרת בדרכו לטבריה לעבר את השנה, היה הים נקרע לפניו. גדולי הדור הראשון והשני קבלו ממנו: רבי יוחנן (סוכה מ\"ד ע\"א), ר\u0027 אבא בר זבדא (ירו\u0027, סוכה פ\"ד ה\"א) ור\u0027 יהושע בן לוי (ירו\u0027, נדה פ\"ג ה\"ד). בנו ר\u0027 עוזיאל מסר בשמו (ירו\u0027, מע\"ש רפ\"ה)."},{"i":1343,"n":"ר\u0027 חונייא דברת חוורין","l":"ח","b":"מובא בירושלמי (סוכה פ\"ד ה\"א), והוא ר\u0027 חוניה דברת חוורין."},{"i":1344,"n":"רבי חונייה מברת חוורן","l":"ח","b":"מובא בירושלמי (נדה פ\"ג ה\"ד), והוא ר\u0027 חוניה דברת חוורין."},{"i":1345,"n":"רבי חוצפית","l":"ח","b":"ע\"ע רבי חוצפית המתורגמן."},{"i":1346,"n":"רבי חוצפית המתורגמן","l":"ח","b":"תנא בדור השלישי. היה מתורגמן בסנהדרין ביבנה, בנשיאותו של רבן גמליאל דיבנה (ברכות כ\"ז ע\"ב). שמו מובא פעם אחת במשנה בבבלי: \"בשם ר\u0027 חוצפית\" (שביעית פ\"י מ\"ו). חברם של רבי ישבב, רבי חלפתא ור\u0027 יוחנן בן נורי (תוספתא כלים ב\"ב ב\u0027 ב\u0027). היה שקול כיונתן בן עוזיאל (\"אור זרוע\" סי\u0027 תק\"י בשם מדרש עשרה הרוגי מלוכה). היה אחד מעשרה הרוגי מלכות (איכ\"ר פ\"ב - ד\u0027), וכן בתוספות (בכורות ל\"ו ע\"א). האריך ימים ונהרג בגיל 301 (ביהמ\"ד הוצאות ילינק ח\"ב עמ\u0027 07). לא ניתן לקבורה ויש אומרים שאלישע בן אבויה יצא לתרבות רעה משום שראה את לשונו של רבי חוצפית נגררת על ידי דבר אחר [חזיר] (קידושין ל\"ט ע\"ב)."},{"i":1347,"n":"ר\u0027 חזאל","l":"ח","b":"לפי גירסת \"יתו\"א\" תנא בדור הראשון ומובא בפירקי דר\"א מ\"ז, ולפנינו מובא בפרק מ\"ח, אך בשינויים, ובנוסחאות שלנו אין זכר לשם חזאל כפי שהיה לפני \"יתו\"א\"."},{"i":1348,"n":"חזקיה (2)","l":"ח","b":"אמורא ארץ ישראלי. מראשוני הדור הראשון ועדיין כינוהו תנא (רש\"י חולין ק\"ו ע\"א ד\"ה: אין: תוספות ע\"ז ל\"ח ע\"ב ד\"ה: תנו). בנו של ר\u0027 חייא הגדול. אליהו הנביא גילה לרבי, שר\u0027 חייא ושני בניו יהודה וחזקיה הם דוגמת האבות (ב\"מ פ\"ה ע\"ב). ועליו ואחיו יהודה אמרו: \"תרי אמוראי במערבא\" (ב\"ב ע\"ה ע\"א). היה גדול בדורו (חולין נ\"ז ע\"א רש\"י ד\"ה: בריבי). ר\"ל אמר: \"כשנשתכחה תורה מישראל, עלה עזרא מבבל ויסדה, חזרה ונשתכחה, עלה הלל הבבלי ויסדה, חזרה ונשתכחה, עלו רבי חייא ובניו ויסדוה\" (סוכה כ\u0027 ע\"א). ונראה שסידר קובץ ברייתות, כדמצינו \"דבי חזקיה תנא\" (סנהדרין מ\"א ע\"א) והוא חזקיה, בנו של ר\u0027 חייא, כדמפורש בתוספות (כתובות ל\"ה ע\"א ד\"ה: ומי). היה מאוכלי שולחנו של רבי (סנהדרין ל\"ח ע\"א). היה קשיש מרבי יהודה נשיאה (ע\"ז ל\"ח ע\"ב תד\"ה: תנו). חבריו היו בר קפרא (סנהדרין ק\u0027 ע\"א) ור\u0027 ינאי שחלק עמו ועם אחיו (זבחים ט\"ו ע\"א) אבל רבי ינאי היה קשיש ממנו הרבה וקרא לו ולאחיו \"רובין\" [נערים] (חולין כ\u0027 ע\"א). מתלמידיו הגדולים: רבי יוחנן (שבת קי\"ב ע\"ב). ור\"ל מסר בשמו (ב\"ק ט\u0027 ע\"ב). מקומו הקבוע היה בטבריה (מגילה ה\u0027 ע\"ב) ונפטר ונקבר שם במערה לשמאל אביו (מו\"ק כ\"ה ע\"א), ואחיו יהודה לימין אביו. (יש עוד אמורא ארץ ישראלי בדור הרביעי בשם ר\u0027 חזקיה)."},{"i":1349,"n":"רבי חזקיה","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי ירמיה (זבחים ע\"ה ע\"ב). כן למד אצל רבי אבהו (ירו\u0027, ביצה פ\"א ה\"ב), שמצינו: \"ר\u0027 חזקיה אמר אביי\" (שבת ל\"ח ע\"ב), ובשם רבא (ירו\u0027, יבמות פ\"ח ה\"א). חברו של ר\"ה ב\u0027 (זבחים שם). ר\u0027 מנא היה לו כתלמיד (ירו\u0027, נדרים פ\"ד ה\"ה)."},{"i":1350,"n":"ר\u0027 חזקיה","l":"ח","b":"מובא הרבה ב\"זוהר\" (נח ס\"ט)."},{"i":1351,"n":"חזקיה אבי עיקש","l":"ח","b":"תנא בדור השלישי. העיד לפני רבן גמליאל ביבנה משום רבן גמליאל הזקן (בכורות ל\"ח ע\"א)."},{"i":1352,"n":"חזקיה איש עיקש","l":"ח","b":"מובא ב\"ילקוט\" (שמיני רמז תקלט), והוא חזקיה אבי עיקש."},{"i":1353,"n":"חזקיה בן גרון","l":"ח","b":"\"סה\"ד\" כתב שהיה בזמן הלל. מובא בירושלמי: \"אלו ההלכות שאמרו בעליית חנניא בן חזקיה בן גרון שעלו לבקרו, ונמנו ורבו ב\"ש על ב\"ה\" (שבת פ\"א ה\"ד). וכן בבבלי (שבת י\"ג ע\"ב)."},{"i":1354,"n":"חזקיה בר בילוטו","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי אבהו (ערכין כ\"ח ע\"ב). אביו בילווטו (כן הגירסא בערכין י\"א ע\"א) היה תלמידו של ר\u0027 יוחנן (שם)."},{"i":1355,"n":"ר\u0027 חזקיה בר יעקב בר אחא","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. אמר בשם ר\u0027 יוסי בר חנינא (ירו\u0027, שבועות פ\"ג ה\"ד). יש סבורים שצ\"ל: ר\u0027 חזקיה [בשם] ר\u0027 יעקב בר אחא [בשם] ר\u0027 יוסי בר חנינא."},{"i":1356,"n":"ר\u0027 חזקיה בר ירמיה","l":"ח","b":"מובא בירושלמי בשמו: \"אם יכל את לשלשל שמועה עד משה וכו\u0027\" (קידושין פ\"א ה\"ז). אותו מאמר מובא במקום אחר: \"ר\u0027 חזקיה [בשם] ר\u0027 ירמיה [בשם] ר\u0027 חייא\" (ירו\u0027, שבת פ\"א ה\"ב). נראה שהוא ט\"ס ולא היה כלל אמורא ששמו ר\u0027 חזקיה בר ירמיה."},{"i":1357,"n":"חזקיה בריבי","l":"ח","b":"מובא בירושלמי (בכורים פ\"ג ה\"ג), והוא חזקיה סתם בנו של רבי חייא בריבי גדול הדור."},{"i":1358,"n":"חזקיה בריה דר\u0027 חייא","l":"ח","b":"כן הביא \"סה\"ד\" בשם הרשב\"א מפרק המגרש. ואין לפנינו בש\"ס."},{"i":1359,"n":"חזקיה בריה דר\u0027 פרנק","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי, תלמידו של רבי יוחנן (ברכות ס\"ג ע\"ב)."},{"i":1360,"n":"ר\u0027 חזקיה חוקוק","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. חברם של רב הונא ב\u0027 ור\u0027 פנחס (ירו\u0027, סנהדרין פ\"ג ה\"ט)."},{"i":1361,"n":"ר\u0027 חזקיה עכייה","l":"ח","b":"מובא בירושלמי (שבת פי\"ד ה\"ד), שאמר בשם רבנן דקיסרין."},{"i":1362,"n":"רבי חזקיה רבה","l":"ח","b":"מובא (ירו\u0027, כתובות פ\"ה ה\"ו). נראה שהוא רבי חזקיה סתם, בנו של רבי חייא."},{"i":1363,"n":"חטיא","l":"ח","b":"מובא ב\"ילקוט\" (נביאים סי\u0027 קי\"ט). וזה לשון \"סה\"ד\": \"שם חכם בקמץ הח\u0027 בחירק הט\u0027 בקמץ היוד\"."},{"i":1364,"n":"רבי חידקא","l":"ח","b":"הוא רבי חדקא."},{"i":1365,"n":"רבי חייא","l":"ח","b":"תנא - אמורא ארץ ישראלי בדור המעבר שבין התנאים לאמוראים (נדה כ\"ו ע\"א רש\"י: \"רבי חייא תנא ואמורא הוא\", ב\"מ ע\"א: ע\"ב \"ר\u0027 חייא תנא ופליג\"). בדורו של רבי, מבני פמלייתו של הנשיא וסמוך על שולחנו (עירובין ע\"ג ע\"א) והוא סתם ר\u0027 חייא בש\"ס הבבלי או, רבי חייא רבה (שבת י\"ח ע\"ב). ובירושלמי כמעט תמיד נקרא רבי חייא רובא או רבי חייא הגדול (אבל ר\u0027 חייא סתם בירושלמי הוא ר\u0027 חייא בר אבא). יליד בבל. עלה לא\"י יחד עם בניו יהודה וחזקיה (סוכה כ\u0027 ע\"א): \"וכשנשתכחה תורה מישראל וכו\u0027 חזרה ונשתכחה, עלו רבי חייא ובניו ויסדוה\". חיבר עם ר\u0027 אושעיא הברייתות שבידינו (חולין קמ\"א ע\"ב). רבי מסר לו הרבה מחכמתו (נדרים מ\"א ע\"א) והיה תלמיד חבר לרבי (נדה י\"ד ע\"ב תוס\u0027), וגם רבי שאל ממנו (הוריות י\"א ע\"א). רבו ודודו של רב (מו\"ק ט\"ז ע\"ב). אליהו הנביא גילה לרבי, שר\u0027 חייא ובניו שקולים כאבות (ב\"מ פ\"ד ע\"ב). ר\"ל אמר: הריני כפרת ר\u0027 חייא ובניו (סוכה כ\u0027 ע\"א). צם 003 תעניות למען שיזכה לראות את ר\u0027 חייא בחלום (ירו\u0027, כלאים פ\"ט סה\"ג). מלאך המות לא יכול להתקרב אליו (מו\"ק כ\"ח ע\"א)."},{"i":1366,"n":"רבי חייא אבוי דרבי ברכיה","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי. אבי רבי ברכיה בעל האגדה המפורסם בדור הרביעי. שניהם, רבי ברכיה ואביו, מסרו ביחד דברי אגדה (ויק\"ר פ\"ל - א\u0027), וכן מסר רבי ברכיה בשם אביו (תנחומא פ\u0027 חיי שרה). גם בנו השני, רבי שמואל, היה מחכמי ההלכה (ירו\u0027, שבת ספט\"ו)."},{"i":1367,"n":"ר\u0027 חייא אבוי דר\u0027 אחא","l":"ח","b":"מובא בתנחומא (ישן פ\u0027 שלח), ונראה שיש שיבוש (עיין תנחומא בובר וכן מ\"ר פי\"ז - ב\u0027)."},{"i":1368,"n":"רבי חייא איש כפר עכו","l":"ח","b":"אמורא ארץ ישראלי בדור השני. אין מתורתו מאומה בש\"ס. מובא בהקשר לבנו: \"ר\u0027 תנחום בנו של ר\u0027 חייא איש כפר עכו\" (ברכות ס\"ג ע\"ב)."},{"i":1369,"n":"רבי חייא אריכא","l":"ח","b":"אמורא בבלי בדור הרביעי. בא לדין תורה לפני רבא (כתובות ק\"ד ע\"ב). ר\u0027 יצחק בן טבלי מסר בשמו (נדרים ח\u0027 ע\"ב). \"סה\"ד\" תמה על זה: \"כי ר\u0027 יצחק בן טבלי נראה קדום לו\", ונראה שיש איזה שיבוש."},{"i":1370,"n":"רבי חייא בר אבא","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי. בירושלמי נקרא ר\u0027 חייא או ר\u0027 חייא בר ווא או ר\u0027 חייא בר בא, ובבבלי ר\u0027 חייא בר אבא. יליד בבל (שבת ק\"ה ע\"ב). קיבל מרב (חולין צ\"ב ע\"א) ומגניבא (חולין נ\u0027 ע\"א). כשעלה לא\"י שימש את רבי חנינא (ירו\u0027, הוריות פ\"ג סה\"ד). ר\u0027 יוחנן היה רבו המובהק (ברכות ל\"ח ע\"ב) כן שימש את ריב\"ל (ירו\u0027, שבת פ\"א רה\"ב) וקיבל מר\"א בן פדת (ירו\u0027, חגיגה פ\"א ה\"ז). חבריו היו: ר\u0027 אמי ור\u0027 אסי, ושלושתם היו חשובים בעיני הנשיא (שם). מתלמידיו: ר\u0027 ירמיה (ברכות י\"ג ע\"ב) ור\u0027 חמא בר חנינא (סנהדרין כ\"ט ע\"א). מדי 03 יום היה חוזר על תלמודו לפני ר\u0027 יוחנן (ברכות ל\"ח ע\"ב): ודייק מאד בשמועותיו (שם). ירד מספר פעמים לבבל (\"אגרת רב שרירא גאון\"). היה עני מרוד (ברכות מ\"ג ע\"ב). היו לו שלושה בנים אמוראים: ר\u0027 אבא (חולין פ\"ו ע\"ב), ר\u0027 כהנא (ירו\u0027, שבת פ\"א סה\"ד) ור\u0027 נחמיה (ירו\u0027, דמאי פ\"א ה\"ב)."},{"i":1371,"n":"ר\u0027 חייא בר אבא דמן יפו","l":"ח","b":"מובא במדרש תהלים (פס\"ב - ג\u0027), ואולי צ\"ל: ר\u0027 חייא בר אדא דמן יפו."},{"i":1372,"n":"ר\u0027 חייא בר אבויה","l":"ח","b":"יתכן שהיה תנא. היה זקנו של ר\u0027 פרידא (סנהדרין פ\"ב ע\"א רש\"י), ומצא גולגלתו של המלך יהויקים ועסק בקבורתה."},{"i":1373,"n":"רב חייא בר אבין","l":"ח","b":"אמורא בבלי בדור השלישי. זכה לקבל מרב (עירובין ל\"ח ע\"ב) ומשמואל (שבת נ\"ב ע\"א). היה תלמיד של ר\"ה (קידושין נ\"ח ע\"א). שאל מאדא בר אהבה (שבת ק\"מ ע\"א) ומרב חסדא (מנחות מ\"ט ע\"א). עלה ולמד אצל ר\"א בטבריה, ומשם שלח הוראות לבבל (יבמות מ\"ג ע\"א). וכן: \"אמר ר\u0027 חייא בר אבין אמר ר\u0027 יוחנן\" (עירובין מ\"ז ע\"ב). ר\"ה בירך את אביו שיצאו ממנו שני אנשים גדולים, ונולדו הוא ואחיו רב אידי בר אבין (שבת כ\"ג ע\"ב). רבא קרא לו \"ארי שבחבורה\" (קידושין מ\"ח ע\"ב). רנב\"י שאל ממנו (ברכות ו\u0027 ע\"א)."},{"i":1374,"n":"רב חייא בר אדא","l":"ח","b":"אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של רבי אחא (ירו\u0027, ברכות פ\"ו סה\"א) ושל רבי מנא [בנו של ר\u0027 יונה] (ירו\u0027, דמאי פ\"ב ה\"א)."},{"i":1375,"n":"רבי חייא בר אדא","l":"ח","b":"אמורא ארץ ישראלי בדור השני - השלישי. בן אחותו של בר קפרא (פסיקתא דרב כהנא צ\"ז - א\u0027). תלמידו של ר\"ל, ומת בחיי רבו (ירו\u0027, ברכות פ\"ב ה\"ח). שאל מרבי יוחנן (ירו\u0027, מעשרות פ\"א ה\"א). הצטיין בקול ערב (פסדר\"כ שם)."},{"i":1376,"n":"רבי חייא בר אחא","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי. אמר בשם רשב\"ל (ירו\u0027, פסחים פ\"ז ה\"ב)."},{"i":1377,"n":"רב חייא בר אמי","l":"ח","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של עולא (ברכות ח\u0027 ע\"א). פעם ישב בחברתו של עולא: \"יתיב ר\"נ ועולא ואבימי בר פפי, ויתיב רב חייא בר אמי גבייהו\" (ע\"ז ס\"ג ע\"ב)."},{"i":1378,"n":"רב חייא בר אסי","l":"ח","b":"אמורא בבלי בדור השני - השלישי. תלמידו של רב (תענית י\"ח ע\"א). כן מסר בשם ר\u0027 יוחנן (מדרש תהלים פע\"ב - ו\u0027)."},{"i":1379,"n":"רב חייא בר אשי","l":"ח","b":"אמורא בבלי בדור השני. מתלמידיו הגדולים והמובהקים של רב (ברכות י\"ז ע\"א). כן היה תלמידם של זעירי (שבת ק\"ט ע\"א) ושל שמואל (יבמות קי\"ג ע\"א). עמד בראש ישיבה בקורקוניא, הסמוכה לסורא (ע\"ז ט\"ז ע\"א). חלק על ר\"ה חברו, שעמד בראש ישיבת סורא, בדבר הלכה (חולין קי\"א ע\"ב). האומרים בשמו: רבי אבא (נדה ט\"ז ע\"ב), רבי זירא (שבת קמ\"ה ע\"א) ורב עמרם חסידא (סוכה י\"א ע\"א). פרש מאשתו והיא התחפשה לזונה והכשילתו, ורצה לשרוף עצמו, גם לאחר שאמרה לו כי לא נכשל, כי היא היתה זו, באמרו: \"אבל אני התכונתי לאיסורא\": וכל ימיו של אותו צדיק היה מתענה, עד שמת בשריפה (קידושין פ\"א ע\"ב)."},{"i":1380,"n":"חייא בר בון","l":"ח","b":"מובא בירושלמי (דמאי פ\"ג ה\"ד), והוא ר\u0027 חייא בר אבין."},{"i":1381,"n":"רבי חייא בר ברתיה דר\u0027 ברכיה","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי. בן בתו של ר\u0027 ברכיה, מחשובי בעלי האגדה הארץ ישראליים בדור הרביעי. מסר בשם סבו זה (ב\"ר פ\"ט - ה\u0027)."},{"i":1382,"n":"ר\u0027 חייא בר גוריא","l":"ח","b":"אמורא בבלי. מובא בבבלי. (נדה נ\"ה ע\"ב). אמר מ\"ט דרב."},{"i":1383,"n":"רב חייא בר גמדא","l":"ח","b":"אמורא בבלי בדור השני. עלה לארץ ישראל, וכשהגיע לגבול התפלש בעפרה (כתובות קי\"ב ע\"ב). היה תלמידו של רבי יוסי בר שאול [מתלמידי רבי] (ר\"ה כ\"ד ע\"א), וקיהל ממנו מספר מאמרים בשם רבי. כן למד מר\u0027 יוסי בר חנינא (סוטה ז\u0027 ע\"ב). נראה שהאריך ימים, שכן מובא: \"א\"ר חייא בר גמדא: \u0027נזרקה מפי החבורה\u0027\" (שבת ג\u0027 ע\"א) ומפרשים התוספות (ד\"ה: איתמר): \"חבורה של תנאים\" ואם כן, נראה שנפגש בשעתו עם חבורת התנאים."},{"i":1384,"n":"ר\u0027 חייא בר זבדא","l":"ח","b":"מובא בב\"ר (פפ\"ד - ח\u0027)."},{"i":1385,"n":"ר\u0027 חייא בר זעירא","l":"ח","b":"מובא בבמד\"ר (פי\"א - ב\u0027). יתכן שחל שיבוש בשם זה."},{"i":1386,"n":"רבי חייא בר זרנוקי","l":"ח","b":"אמורא ארץ ישראלי בדור השני. חברו של ר\u0027 שמעון בן יהוצדק ב\u0027. הלך לעבר שנה ופגש בר\"ל, ולאחר שלימד זכות על עוברי עבירה כינה אותו ר\"ל \u0027רועה בקר\u0027, והוא התלונן על כך בפני ר\u0027 יוחנן (סנהדרין כ\"ו ע\"א)."},{"i":1387,"n":"ר\u0027 חייא בר חיננא","l":"ח","b":"אמורא לאחר הדור השלישי. התקיף על דברי רבי חנינא בר פפא (מנחות נ\"ג ע\"ב)."},{"i":1388,"n":"ר\u0027 חייא בר טיטס","l":"ח","b":"אמורא ארץ ישראלי לאחר הדור השני - השלישי. רבנן דקיסרין אמרו בשמו (ירו\u0027, תרומות פ\"ח ה\"ג)."},{"i":1389,"n":"רב חייא בר יהודה","l":"ח","b":"אמורא בבלי בדור השלישי. תלמידו של רב יהודה (כתובות כ\"א ע\"א)."},{"i":1390,"n":"ר\u0027 חייא בר יוכי","l":"ח","b":"מובא בב\"ר (ספנ\"ה). \"סה\"ד\" כתב: \"אולי צ\"ל ר\u0027 חייא בר יוסי\"."},{"i":1391,"n":"ר\u0027 חייא בר יוסי","l":"ח","b":"מובא בבבלי (פסחים ז\u0027 ע\"א), והוא ר\u0027 חייא בר יוסף."},{"i":1392,"n":"רב חייא בר יוסף","l":"ח","b":"אמורא בבלי בדור השני. תלמידם של רב (שבת ז\u0027 ע\"א) ושל שמואל (חולין מ\"ה ע\"ב). כשעלה לארץ ישראל היה לתלמידו של רבי יוחנן (גיטין לט ע\"א), ומסר מתורתו של רב לר\u0027 יוחנן ור\"ל (חולין נ\"ד ע\"א). עוד קיבל מר\u0027 אושעיא (ע\"ז נ\"א ע\"ב). האומרים משמו: ר\u0027 אלעאי (ב\"מ קי\"ז ע\"א) ור\u0027 חייא בר אבא (ירו\u0027, כלאים פ\"ד ה\"ד). בהיותו בבבל היה הריש בעיר סיכרא, והתקין שם תקנות (ב\"מ פ\"ג ע\"א). בא\"י ישב יחד עם ר\u0027 יוחנן בדין (ירו\u0027, ב\"מ פ\"ד ה\"ב). סחר במלח (שם)."},{"i":1393,"n":"ר\u0027 חייא בר ינאי","l":"ח","b":"מובא באס\"ר (פ\"ז - י\u0027)."},{"i":1394,"n":"ר\u0027 חייא בר יעקב","l":"ח","b":"מובא בתנחומא (הישן פ\u0027 עקב)."},{"i":1395,"n":"ר\u0027 חייא בר כהנא","l":"ח","b":"מובא באגדת בראשית (פ\"ב)."},{"i":1396,"n":"רבי חייא בר לוליבא","l":"ח","b":"מובא בירושלמי (ערלה רפ\"ב), והוא רבי חייא בר לולייני."},{"i":1397,"n":"רבי חייא בר לולייני","l":"ח","b":"אמורא ארץ ישראלי בדור החמישי - הששי. חברו של רבי יוסי בי רבי בון: שניהם מסרו יחד מאמרי הלכה בירושלמי (נזיר פ\"ד סה\"ד). נראה שהיה ראש ישיבה. בירושלמי מוזכרים תלמידיו (יומא פ\"ב רה\"ב). מסופר ששמע לעננים שרצו להוריד גשם בעמון ומואב והתפלל שירדו בא\"י, וכך הווה. (תענית כ\"ה ע\"א)."},{"i":1398,"n":"רבי חייא בר מדייא","l":"ח","b":"מובא בירושלמי (ב\"ב פ\"ח ה\"ח), והוא רבי חייא בר מרייה."},{"i":1399,"n":"ר\u0027 חייא בר ממל","l":"ח","b":"כך גירסת \"יתו\"א\" (ב\"ק י\"ט ע\"א), ולפנינו הגיר\u0027 ר\u0027 חייא בר אבא."},{"i":1400,"n":"ר\u0027 חייא בר מנחמא","l":"ח","b":"מובא בויק\"ר (פל\"ו - ו\u0027). רבי תנחומא מסר בשמו, ו\"סה\"ד\" גרס: בר מנהמא."},{"i":1401,"n":"רבי חייא בר מרייה","l":"ח","b":"אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של רבי יונה וישב לפניו (ירו\u0027, כתובות פ\"ט ה\"א). כן היה תלמידו של רבי יוסי (ירו\u0027, ב\"ב פ\"ח ה\"ח). חברו של רבי מנא (בנו של ר\u0027 יונה), שמסר לו דעתו של ר\u0027 יונה אביו במספר ענינים (ירו\u0027, עירובין פ\"ח ה\"ט)."},{"i":1402,"n":"רב חייא בר מתנה","l":"ח","b":"אמורא בבלי בדור השלישי. מובא בבבלי: \"דרש משמיה דרב וכו\u0027 א\"ל רב נחמן וכו\u0027\" (נדה ס\u0027 ע\"ב)."},{"i":1403,"n":"ר\u0027 חייא בר נחמן","l":"ח","b":"מובא בויק\"ר (רפי\"ח)."},{"i":1404,"n":"רב חייא בר נחמני","l":"ח","b":"תנא ארץ ישראלי בדור הרביעי. תלמידו של רבי ישמעאל (ברכות מ\"ח ע\"ב)."},{"i":1405,"n":"ר\u0027 חייא בר עוקבה","l":"ח","b":"אמורא ארץ ישראלי בדור החמישי. אמר בשם רבי יוסי (ירו\u0027, גיטין פ\"ג ה\"ז)."},{"i":1406,"n":"רב חייא בר עמרם","l":"ח","b":"מובא בבבלי (בכורות ל\"ו ע\"ב). ב\"שיטה מקובצת\" הגיר\u0027: ר\u0027 חייא בר אבין אמר ר\u0027 עמרם."},{"i":1407,"n":"חייא בר פפא","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של ר\u0027 זירא (ירו\u0027, ברכות פ\"ו ה\"א)."},{"i":1408,"n":"רב חייא בר רב","l":"ח","b":"אמורא בבלי בדור השני. בנו ותלמידו המובהק של רב (פסחים ע\u0027 ע\"א). רב פיקח על לימודו של בנו, וגדולי תלמידי רב היו רבותיו. רב חייא בר אשי (עירובין מ\"ז ע\"א), רב חנן בר רבא [חתנו של רב] (יומא י\"ט ע\"ב) ורב יהודה (עירובין י\"ד ע\"א). עם ר\"ה היה כחבר ושניהם ישבו לפני שמואל (ערכין ט\"ז ע\"ב), וכן ישבו יחד כחברי בית דין (ב\"ב ל\"ט ע\"ב). בשמו מסרו ר\"ה בר חיננא (ברכות ל\u0027 ע\"א) ואביי (שבועות י\"ז ע\"ב). היה לו בן חכם ושמו שימי, שהיה חביב על רב זקנו (קידושין י\"ב ע\"א)."},{"i":1409,"n":"ר\u0027 חייא בר רב מדיפתי","l":"ח","b":"אמורא בבלי בדור השלישי. חי עד הדור החמישי. נראה, שהיה בקי בברייתות, ומצינו, שפעם ישבו רב חסדא ורבה בר רב הונא בדין כל היום וחלש לבם, ושנה להם ר\u0027 חייא בר רב מדיפתי ברייתא לעודדם (שבת י\u0027 ע\"ב). ומצינו אותו (כנראה בזקנותו) שאמר לרב פפא: \"שמא עני בא לידך ולא פרנסתו כדתניא וכו\u0027\" (ב\"ב י\u0027 ע\"א). שמו מובא בדרך כלל בלי תואר רב רק פעם מובא בתואר רב (יבמות ע\"ד ע\"א)."},{"i":1410,"n":"ר\u0027 חייא בר רבא","l":"ח","b":"מובא במדרש משלי (פט\"ו)."},{"i":1411,"n":"רבי חייא בר ריבי","l":"ח","b":"כך גירסת הרי\"ף בבבלי (יבמות מ\"ו ע\"ב), והוא רבי חייא סתם. ו\"בריבי\" פירושו גדול הדור."},{"i":1412,"n":"רב חייא בר שימי","l":"ח","b":"כך גירסת \"יתו\"א\" (עירובין מ\"ד ע\"ב), ולפנינו אין בכל הש\"ס השם רב חייא בר שימי וגירסתנו בעירובין רב שימי בר חייא."},{"i":1413,"n":"רבי חייא ברבי","l":"ח","b":"הוא רבי חייא."},{"i":1414,"n":"רב חייא בריה דאבא בר נחמני","l":"ח","b":"מובא בבבלי (ע\"ז ס\u0027 ע\"ב), והוא רב חייא בריה דרבה בר נחמני (\"דק\"ס\")."},{"i":1415,"n":"רב חייא בריה דרב אויא","l":"ח","b":"אמורא בבלי בדור הששי. רבו של רב אמימר בר ינוקא (חולין י\"ח ע\"ב). נהג לאכול מיני מגדים בשבת ויו\"ט, כדי להשלים מאה ברכות (מנחות מ\"ג ע\"ב)."},{"i":1416,"n":"רב חייא בריה דרב איקא","l":"ח","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (נדה מ\"ה ע\"א): \"מתקיף לה רב חייא בריה דרב איקא וכו\u0027, אמר רב חסדא: ת\"ש וכו\u0027\"."},{"i":1417,"n":"רב חייא בריה דרב הונא","l":"ח","b":"אמורא בבלי בדור הרביעי. תלמיד מובהק של אביי ורבא (ברכות ל\"ד ע\"ב)."},{"i":1418,"n":"רב חייא בריה דרב ייבא","l":"ח","b":"אמורא בבלי אחרי הדור השלישי. הוסיף על דברי רב חסדא (סוכה מ\"ב ע\"ב)."},{"i":1419,"n":"רב חייא בריה דרב יצחק","l":"ח","b":"אמורא בבלי בדור החמישי. רבינא פסק לו דין (ע\"ז ל\"ג ע\"ב)."},{"i":1420,"n":"רב חייא בריה דרב נחמן","l":"ח","b":"אמורא בבלי בדור הרביעי. בנו של האמורא המפורסם רב נחמן. הוסיף על דברי רב (ב\"ב מ\"ו ע\"א)."},{"i":1421,"n":"רב חייא בריה דרב נתן","l":"ח","b":"אמורא בבלי. מובא בבבלי (פסחים מ\"א ע\"א: מנחות ל\"ט ע\"א)."},{"i":1422,"n":"ר\u0027 חייא בריה דרב פפי","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. חברו של ר\u0027 יהושע דסכנין, והם אמרו בשם ר\u0027 לוי (ויק\"ר רפי\"ח)."},{"i":1423,"n":"רב חייא בריה דרבה בר נחמני","l":"ח","b":"אמורא בבלי בדור הרביעי. בנו של האמורא רבה בר נחמני, ראש ישיבת פומבדיתא. תלמידו של רב חסדא (סנהדרין ס\"ט ע\"ב). לא מצינו בשום מקום שדיבר עם אביו או קיבל ממנו."},{"i":1424,"n":"ר\u0027 חייא בריה דרבי חייא בר נחמני","l":"ח","b":"מובא בבבלי (ע\"ז ל\"א ע\"א). \"דק\"ס\" גורס: ר\u0027 חייא בריה דרבה בר נחמני."},{"i":1425,"n":"רבי חייא בריה דר\u0027 אדא דיפו","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. בנו של האמורא ר\u0027 אדא דמן יפו. מסר בשם ר\u0027 ירמיה, שחייבים בפורים לקרות במגילה את עשרת בני המן בנשימה אחת (ירו\u0027, מגילה פ\"ג ה\"ז). כן מסר בשם ר\u0027 שמואל בר נחמני (ש\"ר פמ\"ג - ג\u0027). ר\u0027 ברכיה מחשובי בעלי האגדה מסר בשמו (שם)."},{"i":1426,"n":"ר\u0027 חייא בריה דר\u0027 יוסי","l":"ח","b":"מובא ב\"זוהר\" (יתרו)."},{"i":1427,"n":"חייא בריה דר\u0027 יצחק עטושיא","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. בנו של יצחק עטושיא (תלמידו של ר\"ז). קיבל מר\u0027 ירמיה (ירו\u0027, נזיר פ\"ג ה\"א)."},{"i":1428,"n":"ר\u0027 חייא בריה דר\u0027 שבת","l":"ח","b":"אמורא ארץ ישראלי. רבי עקיבא (האמורא) מסר בשמו (ירו\u0027, יבמות ספ\"ב)."},{"i":1429,"n":"ר\u0027 חייא דכפר תחומין","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי. ר\u0027 אבהו מספר עליו: \"פירשה ר\u0027 חייא דכפר תחומין\" (ירו\u0027, סוף תרומות). חלק עם ר\u0027 ברכיה (ירו\u0027, פאה פ\"א)."},{"i":1430,"n":"רבי חייא הגדול","l":"ח","b":"הוא רבי חייא."},{"i":1431,"n":"ר\u0027 חייא מאבל ערב","l":"ח","b":"מובא בבבלי (פסחים ע\"ב ע\"א), ויתכן שיש שיבוש בשם."},{"i":1432,"n":"רב חייא מהורמיז ארדשיד","l":"ח","b":"אמורא בבלי בדור השלישי. מובא בבבלי: \"אמר רב נחמן בר יצחק: אישתעי לי רב חייא מהורמיז ארדשיד\" (ב\"ב נ\"ב ע\"א)."},{"i":1433,"n":"רב חייא מוסתניא","l":"ח","b":"אמורא בבלי בדור החמישי. תלמידו של רבא, ואצלו למד יחד עם חבריו, רב שמואל בר אידי ורב הונא בר מנוח. לאחר פטירת רבא באו שלושתם לפני ר\"פ ללמוד, וכל פעם שאמר ר\"פ שמועה שלא נתקבלה על דעתם, היו מרמזים זה לזה: חלשה דעתו של ר\"פ ומחשש שיענשו שילחם מעל פניו (תענית ט\u0027 ע\"א)."},{"i":1434,"n":"ר\u0027 חייא מיוסתיניא","l":"ח","b":"מובא בבבלי (זבחים קי\"ב ע\"א). נראה לי, שהוא הוא רב חייא מוסתניא, ומה שפירש רש\"י (תענית ט\u0027 ע\"א ד\"ה: מווסתניא): \"מאותו מקום\" ובמסכת (זבחים קי\"ב ע\"א) פרש\"י ד\"ה: מיוסתינא \"מקום\", ונראה כאילו גרס רש\"י ששני מקומות נפרדים היו, אינו ראיה, שכן דרכו של רש\"י לפרש בכל מקום כפי הגיר\u0027 בגמ\u0027 שלפניו אם אינו משנה לסוגיא ופשט ולענין. ולכן גורס ששניהם חד הוא."},{"i":1435,"n":"רב חייא פרוואה","l":"ח","b":"אמורא בבלי בדור החמישי. איקלע לבי ריש גלותא ופסק להם דין ורב זביד התנגד לדעתו והחמיר ועבדי ריש גלותא השקו את רב זביד כוס של חומץ ומת. (ע\"ז ל\"ח ע\"ב)."},{"i":1436,"n":"רבי חייא ציפוראה","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי אמי (ירו\u0027, ערלה פ\"ג ה\"ב)."},{"i":1437,"n":"ר\u0027 חייא קטוספאה","l":"ח","b":"אמורא בבלי בדור השני. אמר משמיה דרב (ביצה ל\"ח ע\"ב). ואולי צ\"ל: רבה בר חייא קטוספאה, כמו שמצינו במקומות אחרים (ב\"ב צ\"ג ע\"ב: ירו\u0027, כלאים רפ\"ב)."},{"i":1438,"n":"ר\u0027 חייא קרא","l":"ח","b":"מובא באיכ\"ר (פ\"ד - ד\u0027). אמר בשם רבי שמואל בר נחמני. מקור המימרה בירושלמי (סוכה פ\"ד ה\"ו) ושם הגיר\u0027: ר\u0027 יודא בר לקרה. ואולי אחד הוא."},{"i":1439,"n":"רבי חייא רבה","l":"ח","b":"הוא רבי חייא."},{"i":1440,"n":"רב חייא רובא","l":"ח","b":"הוא רבי חייא."},{"i":1441,"n":"רבי חייא רובא בר לוליתא","l":"ח","b":"מובא בירושלמי (חלה פ\"ב ה\"ג), והוא רבי חייא בר לולייני."},{"i":1442,"n":"ר\u0027 חייה","l":"ח","b":""},{"i":1443,"n":"רבי חייה בר לוליינו","l":"ח","b":"מובא בירושלמי (כתובות י\"ג ע\"ב). והוא רבי חייא בר לולייני."},{"i":1444,"n":"ר\u0027 חייה בר שיבתיי","l":"ח","b":"מובא בירושלמי (עירובין פ\"ה ה\"א), והוא ר\u0027 חייה בריה דר\u0027 שבתי."},{"i":1445,"n":"חילפא בר אגרא","l":"ח","b":"תנא ארץ ישראלי בדור הרביעי. מסר בשם ר\u0027 יוחנן בן נורי. רבי שמעון בן אלעזר מסר בשמו (שבת ק\"ה ע\"ב)."},{"i":1446,"n":"חילפא בר אידי","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי. מובא בויק\"ר (רפט\"ז), והוא ור\u0027 חייא בר אבא אמרו וכו\u0027."},{"i":1447,"n":"ר\u0027 חילפא דרומיה","l":"ח","b":"מובא בפס\u0027 רבתי (פ\u0027 אנכי מנחמכם סי\"ב)."},{"i":1448,"n":"חילפי בר אידי","l":"ח","b":"מובא בויק\"ר (רפט\"ז), ואולי הוא זהה לר\u0027 חליפי בר זטרי (פד\"כ קלג)."},{"i":1449,"n":"חילפיי","l":"ח","b":"מובא בירושלמי (קידושין פ\"א ה\"א), והוא אילפא."},{"i":1450,"n":"ר\u0027 חילפיי בר בריה דר\u0027 אבהו","l":"ח","b":"אמורא בדור החמישי. מובא בירושלמי (בכורים רפ\"ב). ואותו ענין מובא בשינוי גיר\u0027 ב\"ילקוט\" (תהלים רמז תש\"פ)."},{"i":1451,"n":"רב חינא","l":"ח","b":"מובא בירושלמי (שבת פי\"ג ה\"ו), ונראה שהוא רב הונא."},{"i":1452,"n":"רב חיננא","l":"ח","b":"אמורא בבלי בדור השני. תלמידו של רב (בכורות ל\"ב ע\"א)."},{"i":1453,"n":"ר\u0027 חיננא (2)","l":"ח","b":"ע\"ע ר\u0027 חנינא או ר\u0027 חנניה."},{"i":1454,"n":"ר\u0027 חיננא אבוה דבר ישיטה","l":"ח","b":"אמורא ארץ ישראלי בדור השני - השלישי. ר\u0027 אבהו אמר בשמו, ובנו של ר\u0027 חיננא היה ה\"אמורא\" של ר\u0027 אבהו (ירו\u0027, מגילה פ\"ד ה\"י)."},{"i":1455,"n":"ר\u0027 חיננא אבוה דר\u0027 ינטה","l":"ח","b":"מובא בירושלמי (פסחים רפ\"ד), ונראה שהוא אבוה דבר נטה (ירו\u0027, מגילה פ\"ד ה\"י)."},{"i":1456,"n":"ר\u0027 חיננא בי רבי חנניה","l":"ח","b":"אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא בירושלמי (סנהדרין ספ\"ז)."},{"i":1457,"n":"רב חיננא בר אבא","l":"ח","b":"מובא בבבלי (יבמות ל\"ו ע\"א), והוא רב חיננא בר אבין."},{"i":1458,"n":"רב חיננא בר אידי","l":"ח","b":"אמורא בבלי בדור השלישי. תלמידו של רב אדא בר אהבה (ע\"ז מ\u0027 ע\"א)."},{"i":1459,"n":"ר\u0027 חיננא בר אנדריי","l":"ח","b":"מובא בירושלמי (מגילה פ\"ד ה\"ה) והוא ר\u0027 חנינא בר אנדריי."},{"i":1460,"n":"רב חיננא בר ביסנא","l":"ח","b":"מובא בבבלי (ביצה כ\"ב ע\"א). סביב שם זה יש גיר\u0027 שונות ב\"סה\"ד\" ו\"דק\"ס\"."},{"i":1461,"n":"רב חיננא בר חייא","l":"ח","b":"אמורא בבלי בדור השלישי. מצינו שהקשה לר\u0027 יהודה: \"ומי אמר שמואל הכי והא וכו\u0027\" (כתובות כ\"א ע\"א)."},{"i":1462,"n":"רב חיננא בר יהודה","l":"ח","b":"אמורא בבלי בדור השני. תלמידו של רב (סנהדרין ע\"ז ע\"ב)."},{"i":1463,"n":"ר\u0027 חיננא בר יצחק","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי. מבעלי האגדה. מובא רק בירושלמי ובאגדות. ר\u0027 יהושע בר נחמיה מסר בשמו (ב\"ר פ\"ח - יא)."},{"i":1464,"n":"ר\u0027 חיננא בר כהנא","l":"ח","b":"מובא בבבלי (שבת צ\"ו ע\"א), והוא ר\u0027 חנינא בר כהנא."},{"i":1465,"n":"רב חיננא בר שילת","l":"ח","b":"אמורא בבלי בדור השני. נראה, שהיה קרובו של רב, שאהבו מאד ואמר: כל מי שיבוא עלי במחתרת אהרגנו, חוץ מרב חיננא בר שילת (סנהדרין ע\"ב ע\"ב). נראה שהיה תלמידו של שמואל (עירובין י\"ב ע\"א). שמו נשתבש בכמה אופנים: ר\u0027 חנניה בר שילא ור\u0027 חנינא בר שילא. היה חשוב בעיני ראש הגולה (שבת נ\"ח ע\"א)."},{"i":1466,"n":"רב חיננא בר שלמיא","l":"ח","b":"אמורא בבלי בדור השני. מתלמידיו של רב (פסחים ק\"ה ע\"א). קיבל גם מרב ירמיה בר אבא (ירו\u0027, סוכה פ\"א ה\"א). אחר פטירת רב שאל משמואל (סנהדרין כ\"ד ע\"ב), אך נראה שלא בא לפני שמואל ממש, אלא רק שלח שאלותיו (שם). חברם של רב עמרם ורב המנונא סבא (שם). היה מרבותיו של רב חייא בר רב (עירובין צ\"ח ע\"ב)."},{"i":1467,"n":"חיננא בר שלמיה","l":"ח","b":"מובא בירושלמי (סוכה פ\"א ה\"ו), והוא רב חיננא בר שלמיא."},{"i":1468,"n":"רב חיננא בריה דרב איקא","l":"ח","b":"אמורא בבלי בדור החמישי. יתכן אולי לדייק, שהיה תלמידם של אביי ורבא (ברכות כ\"ה ע\"ב). בגלל חילופי מלים עם רב פפא ורב הונא בריה דר\u0027 יהושע, נענש ומת (שם נ\"ח ע\"ב)."},{"i":1469,"n":"ר\u0027 חיננא בריה דרב אסי בר ממל","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם ר\u0027 אלעזר (ירו\u0027, גיטין פ\"ג ה\"ח), ונראה שהוא ר\u0027 חיננא בריה דרב אסי (ירו\u0027, שם פ\"א ה\"א). היה רופא."},{"i":1470,"n":"רב חיננא בריה דרבא מפשרוניא","l":"ח","b":"אמורא בבלי בדור הרביעי. היה הריש בפשרוניא. רבא אמר עליו: \"מאן חכים למישרי מלתא כי הא, אי לאו רב חיננא בריה דרבא מפשרוניא, דגברא רבה הוא\" (פסחים ע\"ו ע\"א). מימרתו (מנחות מ\"ב ע\"א) מובאת (גיטין מ\"ה ע\"ב) בשם ר\u0027 המנונא בריה דרבא מפשרוניא. אחיו רב עוקבא, שהיה חכם, גר בפשרוניא והקשה לרבא (פסחים צ\"א ע\"א). אולי רב עוקבא בר חיננא מפרישנא הוא בנו (פסחים צ\"א ע\"א)."},{"i":1471,"n":"ר\u0027 חיננא בריה דר\u0027 אסי","l":"ח","b":"מובא בירושלמי (גיטין פ\"א ה\"א), ונראה שהוא ר\u0027 חיננא בריה דר\u0027 אסי בר ממל."},{"i":1472,"n":"ר\u0027 חיננא בריה דר\u0027 הלל","l":"ח","b":"מובא בירושלמי (תרומות פ\"ד ה\"ו), והוא ר\u0027 חנינא בריה דר\u0027 הלל."},{"i":1473,"n":"רב חיננא בריה דר\u0027 יהושע","l":"ח","b":"מובא בבבלי (פסחים ק\"י ע\"ב). ו\"דק\"ס\" גורס: \"רב הונא בריה דר\u0027 יהושע\"."},{"i":1474,"n":"רב חיננא וורדאן","l":"ח","b":"אמורא בבלי בדור השני - השלישי. הקשה על דברי רב חסדא ועל תשובתו (גיטין ס\"ד ע\"ב)."},{"i":1475,"n":"ר\u0027 חיננא חברה דרבנן","l":"ח","b":"מובא בירושלמי (עירובין פ\"ג ה\"ה)."},{"i":1476,"n":"רב חיננא מסורא","l":"ח","b":"אמורא בבלי בדור החמישי - הששי. חלק עם מר זוטרא (נדה ס\"ז ע\"ב) ועם רב מרי (זבחים פ\"ה ע\"ב)."},{"i":1477,"n":"רב חיננא סבא","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של ר\u0027 אסי. (פסחים ע\"ה ע\"א)."},{"i":1478,"n":"ר\u0027 חיננא קרת חייה","l":"ח","b":"מובא בירושלמי (ביצה פ\"א ה\"ו). ע\"ע רב אחא קרטיגנאה."},{"i":1479,"n":"ר\u0027 חיננא קרתיגנאה","l":"ח","b":"מובא בירושלמי (שבת פט\"ז ה\"ב). ע\"ע רב אחא קרטיגנאה."},{"i":1480,"n":"חיפא","l":"ח","b":"מובא בירושלמי (נדרים פ\"ב ה\"ג), והוא עיפא בן רחבה דפומבדיתא."},{"i":1481,"n":"ר\u0027 חכינאי","l":"ח","b":"תנא בדור השני - השלישי. אביו של התנא הנודע ר\u0027 חנניא בן חכינאי. מובא (בפדר\"א פמ\"א)."},{"i":1482,"n":"רבי חלבו","l":"ח","b":"אמורא בבלי בדור השלישי. מחשובי תלמידי ר\"ה. למד יחד עם חבריו: ר\u0027 אבא בר זבדא, רב גידל, רב ששת ורב אחא בר יעקב (יבמות ס\"ד ע\"ב). כן קיבל מרב חמא בר גוריון, תלמידו של רב (שבת ל\"ז ע\"ב), ומסר שמועות בשם רב (ירו\u0027, ברכות ספ\"ט). עלה לארץ ישראל ושם היה תלמידם של שמואל בר נחמני (ירו\u0027, מגילה פ\"א ה\"א), רבי אמי (ירו\u0027, כלאים פ\"ט ה\"ג) ור\u0027 יצחק נפחא (גיטין ס\u0027 ע\"א). תלמידו היה רבי ברכיה (ב\"ר פע\"ח - א\u0027). ידוע מאמרו: \"קשים גרים לישראל כספחת\" (קידושין ע\u0027 סע\"ב)."},{"i":1483,"n":"ר\u0027 חלבו בקרוייה","l":"ח","b":"מובא במדרש תהלים (פ\"כ - ט\u0027), והוא אבא חליפא קרויא."},{"i":1484,"n":"ר\u0027 חלבו בר חונה","l":"ח","b":"מובא בירושלמי (נזיר רפ\"ג), ויתכן מאד שצ\"ל: ר\u0027 חלבו [בשם] ר\u0027 חונה [הוא ר\"ה]."},{"i":1485,"n":"ר\u0027 חלבו בר חילפא בר סמקאי","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. אמר בשם ר\u0027 יהודה בר\u0027 סימון (ב\"ר פנ\"א - ב\u0027)."},{"i":1486,"n":"ר\u0027 חלבו בר חנן","l":"ח","b":"אמורא בבלי בדור השני. מסר בשם רב, ורב ששת מתיב עליו (ירו\u0027, ברכות פ\"ז ה\"א)."},{"i":1487,"n":"ר\u0027 חליפי בר זטרי","l":"ח","b":"מובא בפד\"כ (קלג), ויש גירסא אחרת (ויק\"ר רפט\"ז ובאיכ\"ר פ\"ד - יח)."},{"i":1488,"n":"חלפא בר אידי","l":"ח","b":"מובא בויק\"ר (פט\"ז), ונראה שיש שיבוש בשם."},{"i":1489,"n":"רבי חלפו בר זביד","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי אסי (איכ\"ר פ\"ד - י\"ח)."},{"i":1490,"n":"ר\u0027 חלפון","l":"ח","b":"מובא בב\"ר (פי\"ט - ז\u0027)."},{"i":1491,"n":"חלפי בר זביד","l":"ח","b":"מובא באיכ\"ר (פ\"ד - י\"ח), ואולי הוא זהה לר\u0027 חליפי בר זטרי (פד\"כ קלג)."},{"i":1492,"n":"רבי חלפתא (2)","l":"ח","b":"תנא בדור השלישי. אביו ורבו של התנא הנודע רבי יוסי בר חלפתא. חי בזמן הבית ומסר לרבן גמליאל דיבנה מעשה מזקנו רבן גמליאל הזקן, שראהו עומד על גבי מעלה בהר הבית (שבת קט\"ו ע\"א). היה הריש בצפורי (ר\"ה כ\"ז ע\"א). חברם של רבי יוחנן בן נורי (תוספתא ב\"ב פ\"ב י\u0027) ורבי חנניה בן תרדיון (תענית ט\"ז ע\"ב). הלך עם חבריו אלעזר בן מתיא וחנניה בן חכינאי לראות את האבנים שהעמיד יהושע בן נון בירדן (סוטה ל\"ד ע\"א). היה עם ר\u0027 חוצפית המתורגמן ורבי ישבב אצל רבי אלעזר בן עזריה בצפורי (תוספתא כלים ב\"ב ב\u0027). חוץ מבנו, לא מצינו לו תלמידים."},{"i":1493,"n":"ר\u0027 חלפתא איש כפר חנניה","l":"ח","b":"מובא בתוספתא (כלים פ\"ד ט\u0027), והוא אבא חלפתא איש כפר חנניא."},{"i":1494,"n":"ר\u0027 חלפתא בן קוינא","l":"ח","b":"מובא בתוספתא (מכשירין פ\"ג ב\u0027)."},{"i":1495,"n":"רבי חלפתא בן שאול","l":"ח","b":"אמורא בדור המעבר בין התנאים לאמוראים. היה משוני הברייתות (ירו\u0027, ברכות פ\"א ה\"ה). יש השערה שהיה אחיהם של ר\u0027 יוסי בן שאול (תלמידו של רבי) ור\u0027 יוחנן בן שאול. פעם אחת הובאו יחד רבי חלפתא ורבי יוסי (ירו\u0027, שבת פ\"ד ה\"ב)."},{"i":1496,"n":"ר\u0027 חלפתא בר כהנא","l":"ח","b":"מובא בתנחומא (פ\u0027 חיי שרה - ו\u0027)."},{"i":1497,"n":"רבי חלפתא ברבי יוסי","l":"ח","b":"תנא בדור החמישי. אחד מחמשת בניו של ר\u0027 יוסי בר חלפתא (שבת קי\"ח ע\"ב)."},{"i":1498,"n":"רבי חלפתא דמן הוה","l":"ח","b":"מובא בירושלמי (גיטין פ\"ט ה\"ג), והוא רבי חלפתא דמן הונא."},{"i":1499,"n":"רבי חלפתא דמן הונא","l":"ח","b":"אמורא ארץ ישראלי בדור הראשון. ר\u0027 יוחנן מסר לבני ר\u0027 חלפתא הלכות בשם אביהם (גיטין פ\"ו ע\"ב)."},{"i":1500,"n":"רבי חלפתא דמן חיפא","l":"ח","b":"מובא בבבלי (גיטין פ\"ו ע\"ב), והוא רבי חלפתא דמן הונא."},{"i":1501,"n":"ר\u0027 חלפתא קסריא","l":"ח","b":"אמורא ארץ ישראלי בדור השני. מסר בשם רבי שמעון בן לקיש (שהש\"ר פ\"ד - י\"א)."},{"i":1502,"n":"רבי חלקיה","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. תלמידו של רבי סימון (ירו\u0027, שקלים פ\"א ה\"ד). רבו של רבי פנחס (ב\"ר פ\"ט - י\"ב). אולי הוא רבי חלקיה הדרומי, כמובא בתנחומא: \"רבי פנחס בשם רבי חלקיה הדרומי\" (פ\u0027 קדושים א\u0027)."},{"i":1503,"n":"רב חלקיה בר טובי","l":"ח","b":"אמורא בבלי בדור השני. תלמידו של רב (ב\"ב ל\"ט ע\"ב). התרועע עם גדולי תלמידיו של רב (שם). היה עובד אדמה, ובדרך מיוחדת הניב שדהו כפליים תבואה (מנחות פ\"ה ע\"ב)."},{"i":1504,"n":"רב חלקיה בר טוביה","l":"ח","b":"מובא בבבלי (גיטין נ\"ז ע\"א), והוא רב חלקיה בר טובי."},{"i":1505,"n":"רבי חלקיה בריה דרב אויא","l":"ח","b":"אמורא בבלי כנראה בדור הרביעי. מובא בבבלי: \"אמר ליה ההוא מרבנן ורב חלקיה בריה דרב אויא שמיה וכו\u0027, אלא אמר רבא וכו\u0027\" (ב\"מ צ\"ו ע\"ב)."},{"i":1506,"n":"ר\u0027 חלקיה הדרומי","l":"ח","b":"ע\"ע רבי חלקיה."},{"i":1507,"n":"רב חלקיה מהגרוניא","l":"ח","b":"אמורא בבלי שזמנו אינו ידוע. מובא בבבלי (יבמות ט\u0027 ע\"א: הוריות ח\u0027 ע\"א)."},{"i":1508,"n":"רב חמא","l":"ח","b":"אמורא בבלי בדור הרביעי - החמישי. מושבו היה בנהרדעא (סנהדרין י\"ז ע\"ב). עמד בראש ישיבת פומבדיתא כעשרים שנה. נפטר בשנת ד\u0027 קל\"ז (773) לאחר פטירתו של רב נחמן בר יצחק (\"אגרת רב שרירא גאון\"). מסר בשם רבא (כתובות פ\"ו ע\"א). רב פפא היה חברו (שם). אמימר מסר משמו (שם). מלך פרס פנה אליו בשאלה בענין קבורת מתים (סנהדרין מ\"ו ע\"ב) ולא מצא מה להשיב לו, ואמר עליו רב אחא בר יעקב: \"אימסר עלמא בידא דטפשאי\" (שם). פרנסתו היתה הלואת כסף - ונענש (ב\"מ ס\"ט ע\"ב)."},{"i":1509,"n":"ר\u0027 חמא אבוה דר\u0027 אושעיא","l":"ח","b":"מובא בירושלמי (מו\"ק פ\"ג ה\"ה). והוא ר\u0027 חייא בר ביסא."},{"i":1510,"n":"ר\u0027 חמא אבוי דבר קפרא","l":"ח","b":"מובא בירושלמי (שבועות פ\"ו ה\"ב). \"סה\"ד\" כתב שהוא ט\"ס, וצ\"ל: ר\u0027 חמא אבי ר\u0027 הושעיה, ובר קפרא."},{"i":1511,"n":"חמא אבוי דרב יוסף","l":"ח","b":"אמורא בבלי בדור השני. מובא בבבלי: \"בעא מיניה אבוה דרב יוסף בר חמא מרבה בר נתן\" (סנהדרין פ\"א ע\"א). היה זקנו של רבא (עירובין נ\"ד ע\"א)."},{"i":1512,"n":"ר\u0027 חמא אבוי דר\u0027 יהושעיה","l":"ח","b":"מובא בירושלמי (שקלים פ\"ה ה\"ד), והוא ר\u0027 חייא בר ביסא."},{"i":1513,"n":"ר\u0027 חמא בן לקיש","l":"ח","b":"מובא בשאלתות (בראשית). מאמרו שם, מובא בתנחומא בשם ר\u0027 יהודה בן גדיא: \"כל העונה אמן בעוה\"ז זוכה ועונה לעוה\"ב\" (פ\u0027 צו - ט\u0027)."},{"i":1514,"n":"רב חמא בר אבא","l":"ח","b":"אמורא בבלי בדור השני - השלישי. רב נחמן הוסיף על דבריו והסבירם (יבמות ס\"ב ע\"ב)."},{"i":1515,"n":"חמא בר אדא","l":"ח","b":"אמורא בבלי בדור השני - השלישי. היה רגיל לעלות לירושלים (ביצה כ\"ה ע\"ב) ורב נחמן אמר לו פעם: \"כי סלקת להתם אקיף וכו\u0027 וזיל לגבי דר\u0027 יעקב בר אידי ובעי מיניה וכו\u0027\", ועד שהגיע לשם נפטר ר\u0027 יעקב בר אידי (שם)."},{"i":1516,"n":"ר\u0027 חמא בר אושעיא","l":"ח","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (סנהדרין כ\"ה ע\"א)."},{"i":1517,"n":"ר\u0027 חמא בר אשי","l":"ח","b":"מובא בירושלמי (כתובות פ\"ב ה\"ט). \"סה\"ד\" מפקפק אם הוא ט\"ס וצ\"ל: רב חנין בר אשי. יש גורסים: ר\u0027 חייא בר אשי."},{"i":1518,"n":"רב חמא בר בוזי","l":"ח","b":"אמורא בבלי בדור החמישי. תלמידו המובהק של רבא. חברו של רבינא (ב\"ב ט\"ז ע\"ב). רבא קרא לשניהם: \"דרדקי\" (שם), ומובא ששניהם באו לביתו של ריש גלותא (ברכות נ\u0027 ע\"א)."},{"i":1519,"n":"רב חמא בר ביסא","l":"ח","b":"תנא בדור החמישי. מאחרוני התנאים. רבי אמר עליו שהוא אדם גדול (נדה י\"ד ע\"ב). אביו של האמורא מחבר הברייתות רבי אושעיא רבה. מושבו היה בדרום (ירו\u0027, נדה פ\"ג ה\"ב). למד בישיבה 21 שנה וכשחזר לא הכיר את בנו ר\u0027 אושעיא (כתובות ס\"ב ע\"ב). ר\u0027 אושעיא בנו חלק עליו וניצחו (ב\"ב נ\"ט ע\"א). תוספות מפרשים (שם) שהיה גדול מאביו, ואכן מוזכר על שם בנו ר\u0027 חמא אבוי דר\u0027 אושעיא בירושלמי (שקלים פ\"ה ה\"ד: נדה רפ\"ב). רמי בר חמא אמר: \"והחוט המשולש לא במהרה ינתק זה ר\u0027 אושעיא בנו של ר\u0027 חמא בנו של ר\u0027 ביסא\" (כתובות שם). בר פלוגתיה דבר קפרא (מו\"ק כ\"ד ע\"א). רבי יוסי בר חנינא מסר בשמו (ירו\u0027, שביעית פ\"ב ה\"ב לפי דפוס וינציה)."},{"i":1520,"n":"רב חמא בר ברתיה דחסא","l":"ח","b":"אמורא בבלי בדור השלישי - הרביעי. מובא בבבלי: \"אמר רב כהנא: אישתעי לי רב חמא בר ברתיה דחסא: רבה בר נחמני אגב שמדא, נח נפשיה\" (ב\"מ פ\"ו ע\"א)."},{"i":1521,"n":"רב חמא בר גוריא","l":"ח","b":"אמורא בבלי בדור השני. תלמידו המובהק של רב והרבה למסור בשמו (ירו\u0027, יבמות פ\"ד הט\"ו: בבלי שבת י\"א ע\"ב). למד גם לפני שמואל (ב\"ק צ\"ט ע\"ב). רבים קיבלו ממנו וביניהם רב חסדא (מנחות ע\"ח ע\"א), ר\u0027 חלבו (שבת ל\"ז ע\"א) ורבה (עירובין ע\"ט ע\"ב)."},{"i":1522,"n":"רב חמא בר חלפתא","l":"ח","b":"מובא בויק\"ר (פכ\"ח - ו\u0027)."},{"i":1523,"n":"רבי חמא בר חנינא","l":"ח","b":"אמורא ארץ ישראלי בדור השני. בנו ותלמידו של האמורא הגדול רבי חנינא בר חמא (שמו\"ר פכ\"א - ז\u0027). עוד זכה להיות בחברתו של רבי (שבת ל\"ח ע\"א). מושבו בציפורי (ירו\u0027, שבת פ\"ו ה\"ב) והיה מגדולי העיר (תענית כ\"ה ע\"א). חלק עם רבי אושעיא (ירו\u0027, עירובין פ\"ה סה\"א) ונמצא בחברתו בביקורם בלוד (ירו\u0027, סוף פאה). חלק עם רבי יוחנן (שבת קמ\"ז ע\"ב). הצטיין באגדה כאביו. בעל האגדה הנודע רבי לוי, מסר הרבה בשמו (ב\"ר פ\"ט - א\u0027)."},{"i":1524,"n":"ר\u0027 חמא בר חנינא","l":"ח","b":"מובא בבבלי: \"אמר ר\u0027 חמא בר חנינא מפירקיה דרבי חייא בר אבא שמיע לי\" (סנהדרין כ\"ט ע\"א). אם אין כאן איזה ט\"ס צריך לומר שאין זה רבי חמא בר רבי חנינא (ע\"ע) בנו של ר\u0027 חנינא, שזכה להיות בחברתו של רבי, כי איך יאמר: מפירקיה דרבי חייא בר אבא שמיע לי? הרי ר\u0027 חייא בר אבא היה מאוחר יותר."},{"i":1525,"n":"ר\u0027 חמא בר חנינא בר פפא","l":"ח","b":"מובא במדרש חזית (פ\u0027 הסבי עינך). \"סה\"ד\" גרס, שנראה שהוא ר\u0027 חמא בר פפא."},{"i":1526,"n":"רב חמא בר טוביה","l":"ח","b":"אמורא בבלי בזמנו של רב יוסף או לפניו. דן למיתה בת כהן שזנתה (סנהדרין נ\"ב ע\"ב)."},{"i":1527,"n":"רבי חמא בר יוסי","l":"ח","b":"מובא בירושלמי (כלאים פ\"ב ה\"ה), והוא רבי חמא בר יוסף."},{"i":1528,"n":"רבי חמא בר יוסף","l":"ח","b":"אמורא ארץ ישראלי בדור השני. מושבו היה בחמתא דגדר [סמוכה לטבריה] (ירו\u0027, עירובין פ\"ה ה\"ז). והיה שם הריש (שם פ\"ו ה\"ד). בימי רבי יוחנן ור\"ל כבר היה זקן הדור (שם). היה תלמידו של רבי אושעיא (סנהדרין ט\"ז ע\"ב). התיב קומי רבי יוחנן בהלכה (ירו\u0027, ערלה פ\"ב ה\"ה). רבי חייא בר אבא, רבי אסי ורבי אמי, פנו אליו בשאלה הלכתית (ירו\u0027, עירובין פ\"ו ה\"ד). רבי דימי מסר בשמו (ע\"ז י\"ד ע\"ב)."},{"i":1529,"n":"רבי חמא בר עוקבא","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוסי בר חנינא, ומסר בשמו עשרות מאמרים בש\"ס הבבלי והירושלמי (סוכה ל\"ז ע\"ב). כן אמר בשם רבי יהושע בן לוי (ירו\u0027, יומא פ\"ב ה\"א), ובשם ר\"ל (ירו\u0027, שבת פ\"ז סה\"ב). התרועע עם רבי לוי (ב\"ר ספמ\"ב). אמרו בשמו רבי יונה (ירו\u0027, עירובין פ\"ג ה\"ז) ורבי ירמיה (ירו\u0027, כלאים פ\"ז ה\"א)."},{"i":1530,"n":"רב חמא בר עקיבא","l":"ח","b":"מובא בבבלי (קידושין נ\"ה ע\"א), ונראה שהוא רב חמא בר עוקבא. \"מסורת הש\"ס\" כתב: \"אפשר דצ\"ל: בר עוקבא\" \"סה\"ד\" כתב: ט\"ס."},{"i":1531,"n":"רבי חמא בר פפא","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. תלמידו של רבי יהודה בר סימון (ויק\"ר פכ\"ב - ה\u0027). מאמרו בבבלי: \"כל אדם שיש עליו חן, בידוע שהוא ירא שמים\" (סוכה מ\"ט ע\"ב)."},{"i":1532,"n":"רב חמא בריה דרבה בר אבהו","l":"ח","b":"אמורא בבלי בדור השלישי. בנו של האמורא המפורסם רבה בר אבהו. היה גיסו של ר\"נ (יבמות פ\u0027 ע\"ב). חברו של אביי (עירובין ג\u0027 ע\"א). הלך לא\"י והתרועע שם עם אבימי בריה דרבי אבהו (כתובות פ\"ה ע\"א) כשחזר לבבל ביקש ממנו אבימי להחזיר עבורו בבבל חוב כסף שהיה חייב."},{"i":1533,"n":"ר\u0027 חמא דכפר תחומין","l":"ח","b":"אמורא בבלי בדור השני. רב יהודה אמר משמו (מדרש חזית, פסוק \"יונתי בחגוי הסלע\")."},{"i":1534,"n":"רב חמא חברהון דרבנן","l":"ח","b":"מובא בירושלמי (ר\"ה פ\"א ה\"א)."},{"i":1535,"n":"רב חמא מנהרדעא","l":"ח","b":"מובא בבבלי (ב\"ב ז\u0027 ע\"ב תד\"ה: נהרדעי), והוא רב חמא."},{"i":1536,"n":"חנא","l":"ח","b":"אמורא בבלי בדור השלישי. חתנו של ר\u0027 אבא בר אהבה. מובא בבבלי (יבמות ק\"י ע\"ב). לגירסת \"יתו\"א\": רב חגא חתניה של רב אדא בר אהבה."},{"i":1537,"n":"רב חנא","l":"ח","b":"אמורא בבלי בדור השלישי - הרביעי. מובא בבבלי: \"אמר רב חנא אמר רב יהודה\" (שבת צ\"ז ע\"א). רב יוסף קרא לו מר (שם). גיר\u0027 התוספות (שבת ד\u0027 ע\"ב ד\"ה: זרק) \"רב חסדא\" במקום רב יהודה."},{"i":1538,"n":"רב חנא בגדתאה","l":"ח","b":"אמורא בבלי בדור השני. היה מהעיר בגדד שבבבל (רש\"י כתובות ו\u0027 ע\"ב) תלמיד מובהק של שמואל (יבמות ס\"ז ע\"א), ומסר משמו כמה מאמרים בש\"ס. בירר אצל רבי יהודה כיצד אמר שמואל בענין מסויים (עירובין פ\"א ע\"ב). בבבלי (כתובות י\u0027 ע\"ב) יש ממנו מספר מאמרים ברציפות."},{"i":1539,"n":"רב חנא בר אבא","l":"ח","b":"מובא בירושלמי (שבת ספ\"ד). גיר\u0027 \"קרבן העדה\": \"רבי אבא בר חנה\"."},{"i":1540,"n":"רב חנא בר אדא","l":"ח","b":"אמורא בבלי בדור השלישי. מובא בבבלי (יבמות ע\"ח ע\"ב). מסר בשם רב סמא בריה דרב מרי [הנזכר בש\"ס רק במקום זה] (ברכות ס\"ב ע\"ב). רבא ביקר אצל בנו מר יוחנא ואכל אצלו (חולין קל\"ג ע\"א)."},{"i":1541,"n":"רב חנא בר אחא","l":"ח","b":"אמורא בבלי שאין לקבוע זמנו המדוייק. מובא בבבלי: \"אמר רב חנא בר אחא: אמרי בי רב וכו\u0027\" (סוכה נ\"ב ע\"ב)."},{"i":1542,"n":"רב חנא בר ביזנא","l":"ח","b":"אמורא בבלי בדור השני - השלישי. היה דיין בפומבדיתא. ר\"נ ביטל את פסק דינו (כתובות נ\u0027 ע\"ב). היה בעל אגדה. מאמרים מעטים אמר בשם עצמו (סנהדרין ק\"ח ע\"ב), ורובם מסר בשם רבי שמעון חסידא (ברכות ז\u0027 ע\"א). נראה, שעלה לארץ ישראל וקיבל שם משמעון חסידא (שהיה אמורא ארץ ישראלי בדור הראשון). התוכח עם רב ששת, ולבסוף אמר לו רב ששת: \"בהדי חנא באגדתא למה לי\" (סוכה נ\"ב ע\"ב) ופרש\"י: \"מה לי אצלו באגדה, בקי הוא בהגדה ממני ולא אוכל לו\"."},{"i":1543,"n":"רבי חנא בר הינדא","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. אמר בשם רבי פדת [בשם] רבי יוחנן (שאלתות פ\u0027 מקץ)."},{"i":1544,"n":"רב חנא בר חיננא","l":"ח","b":"אמורא בבלי בדור השלישי. מובא בבבלי: \"בעי מרב הונא\" (פסחים ק\"ו ע\"ב)."},{"i":1545,"n":"רב חנא בר חנילאי","l":"ח","b":"אמורא בבלי בדור השני. תלמידו של ר\"ה (ביצה מ\u0027 ע\"א). התרועע עם רב חסדא (שם כ\"א ע\"א). היה בעל צדקה גדול - בביתו היו 06 אופים שאפו לנצרכים, ובביתו היו ארבעה שערים לארבע רוחות השמים וכל עני שהיה נכנס רעב יצא שבע, ובשנות בצורת היה משליך חטים ושעורים מסביב לבית, כדי שהמתבייש להנות מצדקה יקח מהן בלילה (ברכות נ\"ח ע\"ב). נפטר לפני עולא ורב חסדא (שם)."},{"i":1546,"n":"רב חנא בר יהודה","l":"ח","b":"אמורא בבלי בדור החמישי. מסר משמו של רבא (ברכות מ\"ח ע\"א)."},{"i":1547,"n":"רב חנא בר ליוואי","l":"ח","b":"מובא בבבלי (סנהדרין ק\"ח ע\"ב). גיר\u0027 \"דק\"ס\": ר\"ה בר יהודה."},{"i":1548,"n":"רב חנא בר רב קטינא (2)","l":"ח","b":"אמורא בבלי בדור השלישי. בנו של האמורא רב קטינא. מובא בבבלי (יומא נ\"ד ע\"א) יחד עם אביו, ורב נחמן שהיה חברו (חולין י\"ט ע\"א). הקשה לרבה (נדרים ס\"ה ע\"ב, לגיר\u0027 פסקי הרא\"ש). היה לו אח אמורא ושמו רב דניאל בר רב קטינא."},{"i":1549,"n":"ר\u0027 חנא בר שאונה","l":"ח","b":"מובא בבבלי (נדה ס\"ה ע\"ב). ע\"ע ר\u0027 חנא בר שאינה."},{"i":1550,"n":"ר\u0027 חנא בר שאינה","l":"ח","b":"מובא בבבלי (ע\"ז ע\"ה ע\"א). הגמ\u0027 מפקפקת אם שמו ר\u0027 חנא שאינה או ר\u0027 חנא בר שאינה. ובאותו ענין מפקפקת הגמ\u0027 אם שמו ר\u0027 חנא שאונא או ר\u0027 חנא בר שאונא (נדה ס\"ה ע\"ב). \"סה\"ד\" סובר, שהוא ור\u0027 יוחנן בר שאונה, המובא בויק\"ר (פ\"ה - ב\u0027), אחד הם."},{"i":1551,"n":"רב חנא חתניה דרב אדא בר אהבה","l":"ח","b":"אמורא בבלי. מובא בבבלי: \"אמר רב נחמן: \u0027אשכחתיה לרב אדא בר אהבה ולרב חנא חתניה\u0027\" (יבמות ק\"י ע\"ב)."},{"i":1552,"n":"רבי חנא פתוראי","l":"ח","b":"אמורא ארץ ישראלי בדור השני. היה שולחני. ר\u0027 יוחנן (בר נפחא) שאלו בענין מטבעות (חולין נ\"ד ע\"ב)."},{"i":1553,"n":"ר\u0027 חנא קרטיגנאה","l":"ח","b":"מובא בבבלי (ב\"ק קי\"ד ע\"ב). ע\"ע רב אחא קרטיגנאה."},{"i":1554,"n":"ר\u0027 חנא שאונא","l":"ח","b":"מובא בבבלי (נדה ס\"ה ע\"ב). ע\"ע ר\u0027 חנא בר שאינה."},{"i":1555,"n":"ר\u0027 חנא שאינה","l":"ח","b":"מובא בבבלי (ע\"ז ע\"ה ע\"א). ע\"ע ר\u0027 חנא בר שאינה."},{"i":1556,"n":"חנה","l":"ח","b":"אחי אביו (דודו) של רב ואביו של רבה בר חנה. היו לו ארבעה אחים: איבו, שילא, מרתא ורבי חייא (סנהדרין ה\u0027 ע\"א)."},{"i":1557,"n":"ר\u0027 חנה ציפוראי","l":"ח","b":"מובא בבבלי (ר\"ה ל\"ד ע\"ב), ולגיר\u0027 \"דק\"ס\" צ\"ל: ר\u0027 חונא ציפוראה. ע\"ע רב הונא דציפורין."},{"i":1558,"n":"ר\u0027 חנון בן פזי","l":"ח","b":"מובא בויק\"ר (פכ\"ה - ו\u0027). יש סבורים שהוא ר\u0027 חנינא בן פזי."},{"i":1559,"n":"ר\u0027 חנילאי","l":"ח","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי שאמר משום ר\"א בר שמעון (נדה מ\"ג ע\"ב). מצינו: ר\u0027 תנחום אמר ר\u0027 חנילאי (יבמות ס\"ב ע\"ב)."},{"i":1560,"n":"רב חנילאי בר אידי","l":"ח","b":"אמורא בבלי בדור השני. תלמידו של שמואל (כתובות ע\"ט ע\"א). מר עוקבא אמר: \"הכי אמר ר\u0027 חנילאי בר אידי\" (שם). ר\u0027 נחמן הסתמך על שמועותיו (גיטין נ\"ב ע\"א)."},{"i":1561,"n":"ר\u0027 חנילאי בר חנילאי","l":"ח","b":"מובא בבבלי (ע\"ז י\"ח ע\"ב). \"מסורת הש\"ס\" גורס: ר\u0027 תנחום בר חנילאי, וכן גיר\u0027 \"דק\"ס\" וכן נראה לגיר\u0027 \"סה\"ד\"."},{"i":1562,"n":"רב חנילאי מחוזנאה","l":"ח","b":"אמורא בבלי בדור השביעי. תלמידו של רב אשי (עירובין נ\"ז ע\"א). \"סה\"ד\" מפקפק אם הוא ור\u0027 חנין מחוזנאה חד הם."},{"i":1563,"n":"חנין","l":"ח","b":"שם המתחלף בחנן."},{"i":1564,"n":"רב חנין (2)","l":"ח","b":"אמורא בבלי בדור השביעי. תלמידו של רב אשי (גיטין פ\"ה ע\"ב). \"סה\"ד\" שקיל וטרי בענין הגירסא שם."},{"i":1565,"n":"ר\u0027 חנין (2)","l":"ח","b":"אמורא ארץ ישראלי בדור השני - השלישי. מסר בשם ר\u0027 חנינא (ברכות ל\"ב ע\"ב, ו\"דק\"ס\" גורס אחרת), ובשם ר\u0027 יהושע בן לוי (ירו\u0027, ב\"ב פ\"ח ה\"ח). היה בעיקר בעל אגדה."},{"i":1566,"n":"ר\u0027 חנין בן פזי","l":"ח","b":"מובא במדרש תהלים (פצ\"ב - י\"ב). יש סבורים שהוא ר\u0027 חנינא בן פזי."},{"i":1567,"n":"חנין בן פנחס","l":"ח","b":"תנא שאין לקבוע זמנו המדוייק. מובא בבבלי (סוטה ד\u0027 ע\"א)."},{"i":1568,"n":"ר\u0027 חנין בר אביי","l":"ח","b":"מובא בבבלי: \"דא\"ר חנין בר אביי א\"ר פדת אמר רבי יוחנן\" וא\"כ, היה אמורא ארץ ישראלי בדור הרביעי. (פסחים ק\"א ע\"א). אך \"דק\"ס\" גורס: \"ר\u0027 חנין בר אמי\", ו\"סה\"ד\" כתב: \"ר\u0027 חנין בר אביי, בודאי ט\"ס\"."},{"i":1569,"n":"ר\u0027 חנין בר אדא","l":"ח","b":"מובא במדרש תהלים (פ\"ה - ב\u0027)."},{"i":1570,"n":"רב חנין בר אמי","l":"ח","b":"מובא בבבלי (שבת י\"ג ע\"א). ואולי צריך לגרוס (כמו בחולין ק\"ז ע\"ב): רב חנן בר אמי."},{"i":1571,"n":"ר\u0027 חנין בר אשי","l":"ח","b":"מובא בבבלי (בכורות ל\"ד ע\"א), ואולי צריך לגרוס ר\u0027 חנין בר אמי, או ר\u0027 חנן בר אמי, כמו במקומות אחרים (שבת קי\"א ע\"ב: כתובות ל\"א ע\"א: בכורות כ\"ה ע\"א)."},{"i":1572,"n":"ר\u0027 חנין בר בא","l":"ח","b":"מובא (ירו\u0027, שבת פ\"ו ה\"ב). ע\"ע ר\u0027 חנן בר אבא."},{"i":1573,"n":"רב חנין בר ביזנא","l":"ח","b":"מובא בבבלי (סוטה י\u0027 ע\"ב). ונראה שצ\"ל: ר\u0027 חנא בר ביזנא."},{"i":1574,"n":"ר\u0027 חנין בר לוי","l":"ח","b":"מובא בירושלמי (ביצה רפ\"ד)."},{"i":1575,"n":"רב חנין בר פפא","l":"ח","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (עירובין ס\"ה ע\"א)."},{"i":1576,"n":"ר\u0027 חנין בר רבא","l":"ח","b":"מובא בבבלי (פסחים קי\"ז ע\"א). ע\"ע רב חנן בר רבא."},{"i":1577,"n":"רב חנין בריה דרב ייבא","l":"ח","b":"אמורא בבלי בדור הרביעי בזמנו של רבא, שאמר עליו: \"מאן חכים למעבד כי הא מלתא, אי לאו רב חנין בריה דרב ייבא\" (ב\"ב קע\"ד ע\"א)."},{"i":1578,"n":"ר\u0027 חנין בריה דרבי","l":"ח","b":"מובא בויק\"ר (רפ\"ב - כ\"ב). ונראה שצ\"ל: ר\u0027 חנן בריה דר\u0027 ברכיה בוצריה, כמו בשהש\"ר (פ\"ז - א\u0027)."},{"i":1579,"n":"ר\u0027 חנין דציפורי","l":"ח","b":"ע\"ע רב הונא דציפורין."},{"i":1580,"n":"ר\u0027 חנין חתניה דבי נשיאה","l":"ח","b":"אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מת ביום שילדה אשתו בן, וקראו לבן: חנין על שמו. (מו\"ק כ\"ה ע\"א)."},{"i":1581,"n":"חנין מגופתייה","l":"ח","b":"אמורא בבלי בדור השני. תלמידו של שמואל (ירו\u0027, שבת פ\"ה ה\"ב). שמואל קנסו על שעקר כלאים (ירו\u0027, ערלה פ\"ג ה\"ז)."},{"i":1582,"n":"ר\u0027 חנין מחוזנאה","l":"ח","b":"אמורא בבלי בדור השביעי. תלמידו של רב אשי (גיטין פ\"ה ע\"ב). \"סה\"ד\" מפקפק אם הוא ור\u0027 חנילאי מחוזנאה אחד."},{"i":1583,"n":"רבי חנינא (2)","l":"ח","b":"מובא (ע\"ז ל\"ח ע\"ב), והוא רבי חנינא דציפורין."},{"i":1584,"n":"ר\u0027 חנינא (2)","l":"ח","b":"תנא בדור השלישי. בהיותו צעיר ניבא לו רבן גמליאל שיהיה מורה הוראה בישראל, וכן היה (נזיר כ\"ט ע\"ב). ובירושלמי \"אמר רבי אלעזר בר צדוק: \u0027אני ראיתיו יושב ודורש ביבנה\u0027\" (נזיר ספ\"ד). מובא בברייתא (ברכות ב\u0027 ע\"ב) אחרי ר\u0027 מאיר ור\u0027 יהודה."},{"i":1585,"n":"ר\u0027 חנינא אביו של ר\u0027 אחא","l":"ח","b":"מובא בתנחומא (בובר פ\u0027 נשא), ואולי צ\"ל: ר\u0027 הונא אביו של ר\u0027 אחא."},{"i":1586,"n":"ר\u0027 חנינא אחוה דר\u0027 מנא","l":"ח","b":"מובא בירושלמי ששאל ר\u0027 מנא לר\u0027 יוסי כשמת בנו (מו\"ק פ\"ג ה\"ד). אם צריך לכפות המטה."},{"i":1587,"n":"ר\u0027 חנינא איש אונו","l":"ח","b":"תנא בדור השלישי - הרביעי. מובא במשנה: \"וזו הלכה העלה ר\u0027 חנינא איש אונו מבית האסורין\" (גיטין ס\"ו ע\"א - פירש\"י: משמו של ר\u0027 עקיבא). ושם: \"א\"ר שמעון ברבי לפני רבי, מאחר שר\"מ וחנינא איש אונו חולקין, מה ראה רבי לומר הלכה כר\u0027 יוסי\" (ס\"ז ע\"א)."},{"i":1588,"n":"ר\u0027 חנינא בן אורי","l":"ח","b":"תנא בדור הרביעי - החמישי. מובא בדרך ארץ רבה (רפ\"א), שמסר משום ר\u0027 נתן."},{"i":1589,"n":"חנינא בן אחי ר\u0027 יהושע","l":"ח","b":"מובא בבבלי (שבועות ל\"ה ע\"ב), והוא חנניה בן אחי ר\u0027 יהושע."},{"i":1590,"n":"ר\u0027 חנינא בן אנטיגנוס","l":"ח","b":"תנא בדור השלישי. נראה, שהאריך ימים ובשעתו ראה את בית המקדש (תוספתא ערכין ספ\"א). רבן שמעון בן גמליאל (אבי רבי) אמר: \"נראין דברי רבי חנינא בן אנטיגנוס מדברי ומדבריהם\" (נדה נ\"ח ע\"ב). גם בנו היה חכם, ור\u0027 יהודה ור\u0027 יוסי, תלמידי ר\"ע, שלחו אל בנו לשאול הלכה (בכורות ל\u0027 ע\"ב)."},{"i":1591,"n":"ר\u0027 חנינא בן בינאי","l":"ח","b":"מובא בתוספתא (נגעים פ\"א). ו\"סה\"ד\" כתב: נ\"ל ט\"ס וצ\"ל: ר\u0027 חנינא בן חכינאי."},{"i":1592,"n":"ר\u0027 חנינא בן גמלא","l":"ח","b":"מובא בבבלי (סנהדרין קי\"א ע\"א), ויש גורסים ר\u0027 חנינא בן גמליאל."},{"i":1593,"n":"ר\u0027 חנינא בן גמליאל","l":"ח","b":"תנא בדור הרביעי בנו של רבן גמליאל דיבנה (נדה ח\u0027 ע\"ב רש\"י). אחיו הגדול של רבן שמעון בן גמליאל (אבי רבי). רשב\"ג מסר משמו (תוספתא נדה פ\"ז ה\u0027). נראה שהיה תלמידו של ר\u0027 טרפון (נדרים ס\"ב ע\"א) חלק עם ר\u0027 עקיבא (נדה שם) ועם תלמידיו של ר\u0027 עקיבא (תוספתא ע\"ז פ\"ד)."},{"i":1594,"n":"רבי חנינא בן דוסא","l":"ח","b":"תנא בדור הראשון. מופלג בחסידות ומלומד בנסים ותפילתו נשמעה בכל עת: ונהג להתפלל על חולים ולומר \"זה חי וזה מת\" (ברכות ל\"ד ע\"ב). הלך ללמוד תורה אצל ר\u0027 יוחנן בן זכאי וכשחלה בנו של ריב\"ז אמר לו \"חנינא בני, בקש עליו רחמים ויחיה הניח ראשו בין ברכיו ובקש עליו רחמים וחיה\" (שם). היה עני מרוד ובזכותו התקיימו בני דורו \"בכל יום ויום בת קול יוצאת ואומרת כל העולם כולו ניזון בשביל חנינא בני וחנינא בני דיו לו בקב חרובים מערב שבת לערב שבת\" (תענית כ\"ד ע\"ב). \"פעם ביקשתו אשתו ואמרה: עד מתי נצטער בקש רחמים\" - \"יצאה כמין פיסת יד\" ונתנה להם רגל של שולחן זהב; לבסוף חזרה בה אשתו וביקש רחמים ונטלו מהשמים את רגל הזהב. \"תנא: גדול היה נס אחרון יותר מן הראשון\" (שם). הקב\"ה זימן לו חמישה מלאכים שעזרו לו (ראש קה\"ר). בפטירתו אמרו: \"משמת רבי חנינא בן דוסא בטלו אנשי מעשה\" (סוף סוטה)."},{"i":1595,"n":"חנינא בן חזקיה","l":"ח","b":"מובא בבבלי (מנחות מ\"ה ע\"א), והוא חנניה בן חזקיה בן גרון."},{"i":1596,"n":"חנינא בן חכינאי","l":"ח","b":"מובא במשנה (כלאים פ\"ד ע\"א), והוא חנניה בן חכינאי."},{"i":1597,"n":"ר\u0027 חנינא בן עקביא","l":"ח","b":"תנא בדור הרביעי. חברו של ר\u0027 יהודה. כשנפטר בנו של ר\u0027 יהודה נכנס עמו לבית המדרש וישב לצידו (מו\"ק כ\"א ע\"א). פעם חלק עמו כיצד אמר רבן גמליאל. כן חלק עם ר\u0027 יוסי (תוספתא ערכין פ\"א ג\u0027). נראה שהיה הריש בטבריה (עירובין פ\"ז ע\"ב)."},{"i":1598,"n":"רבי חנינא בן פזי","l":"ח","b":"מובא בב\"ר (פ\u0027 לך לך פ\u0027 מ\"ו), והוא חנניא בן פזי."},{"i":1599,"n":"ר\u0027 חנינא בן פזי","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. הקשה לר\u0027 חלבו (ירו\u0027, מגילה פ\"ד ה\"ג)."},{"i":1600,"n":"ר\u0027 חנינא בן שמואל","l":"ח","b":"מובא בירושלמי (סוכה פ\"א ה\"א), והוא ר\u0027 חנניה בן שמואל."},{"i":1601,"n":"רבי חנינא בן תרדיון","l":"ח","b":"תנא בדור השלישי. אביה של ברוריה וחותנו של ר\"מ (ע\"ז י\"ח ע\"א). אחד מעשרה הרוגי מלכות (איכ\"ר פ\"ב פ\u0027 בלע). נשרף על קידוש השם, ספר תורה עמו (ע\"ז שם), ביום כ\"ז סיון (סוף מגילת תענית). נהרג אחרי ר\"ע (שמחות פ\"ה). כן נגזר על אשתו להריגה ועל בתו לישב בקובה של זונות (ע\"ז שם). בנו נתפס לליסטות (שמחות ספי\"ב). מסר משום ר\u0027 אליעזר (יומא ע\"ח ע\"ב). היתה לו ישיבה בסיכנין (סנהדרין ל\"ב ע\"ב). מאמרו הידוע: \"שנים שיושבין ואין ביניהן דברי תורה, הרי זה מושב לצים\" (אבות פ\"ג מ\"ב).Uלםכ"},{"i":1602,"n":"ר\u0027 חנינא בנו של ר\u0027 יוסי הגלילי","l":"ח","b":"תנא בדור הרביעי. מובא בבבלי (ר\"ה ל\"ב ע\"א): \"ירד רבי חנינא בנו של רבי יוסי הגלילי ועשה כרבי עקיבא, אמר רשב\"ג: \u0027כך היו נוהגין ביבנה\u0027\". מצינו שחלק עם ר\u0027 יהודה (חולין י\"ב ע\"א)."},{"i":1603,"n":"ר\u0027 חנינא בנו של ר\u0027 ישמעאל","l":"ח","b":"מובא בש\"ר (פל\"ח - ח\u0027)."},{"i":1604,"n":"רב חנינא בר אבדימי","l":"ח","b":"אמורא בבלי בדור השני. תלמידו של רב (נדרים ס\"א ע\"ב)."},{"i":1605,"n":"רב חנינא בר אבין","l":"ח","b":"אמורא בבלי בדור הרביעי. הוא ואחיו אביי בר אבין היו תלמידי רבה (פסחים ל\"ד ע\"א). אביי היה חברם וקטן מהם (עירובין ס\"ב ע\"א)."},{"i":1606,"n":"ר\u0027 חנינא בר אחא","l":"ח","b":"אמורא ארץ ישראלי בדור השני. חלק עם ר\u0027 חמא בר חנינא (ב\"ר פצ\"ה - ג\u0027)."},{"i":1607,"n":"ר\u0027 חנינא בר איבו","l":"ח","b":"תנא בדור החמישי. מובא בבבלי (שבועות ל\"ה ע\"ב). חלק עם ר\u0027 אחי בר יאשיה (ספרא קדושים סק\"ב)."},{"i":1608,"n":"ר\u0027 חנינא בר אידי","l":"ח","b":"אמורא שזמנו ומקומו אינם ידועים. בבבלי מובא מאמרו: \"למה נמשלו דברי תורה למים וכו\u0027, מה מים מניחין מקום גבוה והולך למקום נמוך, אף דברי תורה אין מתקימין אלא במי שדעתו שפלה\" (תענית ז\u0027 ע\"א)."},{"i":1609,"n":"ר\u0027 חנינא בר איסי","l":"ח","b":"מובא בירושלמי (תרומות פ\"ד ה\"ג), ונראה שהוא ר\u0027 חנינא בר אסי. ע\"ע ר\u0027 חיננא בריה דרב אסי בר ממל."},{"i":1610,"n":"חנינא בר איקא","l":"ח","b":"מובא בירושלמי (כתובות פ\"ז ה\"ו), והוא חנינא בר יקא."},{"i":1611,"n":"ר\u0027 חנינא בר אמי","l":"ח","b":"אמורא ארץ ישראלי בדור החמישי. מובא בב\"ר (פט\"ז - ג\u0027), שמסר בשם ר\u0027 יהושע דסכנין."},{"i":1612,"n":"ר\u0027 חנינא בר אנדריי","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי, שמסר בשם ר\u0027 שמואל בר סוטר (ברכות פ\"א ה\"א)."},{"i":1613,"n":"רבי חנינא בר חמא","l":"ח","b":"אמורא ארץ ישראלי בדור הראשון. עלה מבבל לא\"י יחד עם בנו (ירו\u0027, פאה פ\"ז ה\"ג). ידוע כר\u0027 חנינא הגדול (תענית כ\"ז ע\"ב). \"סה\"ד\" כתב שנראה כי הוא סתם ר\u0027 חנינא בש\"ס. היה תלמידו המובהק של רבי, שאמר עליו בשעת פטירתו: \"חנינא בר חמא ישב בראש\" (כתובות ק\"ג ע\"ב). אך רבי לא הסמיכו בחייו (ירו\u0027, תענית פ\"ד ה\"ב). וכשקיסר אנטונינוס בא בהסתר לרבי ישב ר\u0027 חנינא אצלו (ע\"ז י\u0027 ע\"ב). קיבל מר\u0027 ישמעאל בר\u0027 יוסי (קידושין ע\"א ע\"ב) מר\u0027 חייא (ירו\u0027, שביעית פ\"ו ה\"א) ומבר קפרא (ירו\u0027, נדה פ\"ב ה\"ז). בין תלמידיו הרבים היו ר\u0027 יוחנן (ירו\u0027, הוריות פ\"ג ה\"ד)."},{"i":1614,"n":"ר\u0027 חנינא בר חנינא","l":"ח","b":"מובא בירושלמי (נזיר ספ\"ד), והוא ר\u0027 חנינא (התנא)."},{"i":1615,"n":"חנינא בר יונה","l":"ח","b":"מובא ב\"ילקוט\" (מלאכי רמז תקפט)."},{"i":1616,"n":"ר\u0027 חנינא בר יוסף","l":"ח","b":"מובא בבבלי (עירובין ס\"ה ע\"ב). ויש לפקפק (וכן ב\"סה\"ד\") אם אין כאן שיבוש בשם."},{"i":1617,"n":"ר\u0027 חנינא בר יסא","l":"ח","b":"מובא בירושלמי (ע\"ז פ\"ג ה\"ה), והוא ר\u0027 חנינא בר יקא."},{"i":1618,"n":"ר\u0027 חנינא בר יקא","l":"ח","b":"אמורא בבלי בדור השלישי. בשמו יש כמה וכמה שיבושים. מסר בשם רבי יהודה: \"שורשי חטה בוקעין וכו\u0027\" (ירו\u0027, ברכות פ\"ט ה\"ב), ואותו מאמר בשם ר\u0027 חנינא בר יסא (ירו\u0027, ע\"ז פ\"ג ה\"ה), וכן בשם ר\u0027 חנינא בריקא (ירו\u0027, תענית פ\"א ה\"ג). וכן מצינו: \"ר\u0027 חנינא בן ברוקא בני מישא וכו\u0027\" (ירו\u0027, קידושין פ\"ד ה\"א), ואותו מאמר בשם ר\u0027 חנינא ברוקא (ירו\u0027, יבמות פ\"א ה\"ו). וכן מצינו שיבושים נוספים: ר\u0027 חנינא בר עיזקא (ב\"ר ספ\"ג), חנינא בר איקא (ירו\u0027, כתובות פ\"ז ה\"ו) והכל אחד הוא."},{"i":1619,"n":"רב חנינא בר כהנא (2)","l":"ח","b":"אמורא בבלי בדור השני - השלישי. תלמידו של רב (ביצה ו\u0027 ע\"א) ושל שמואל (ב\"ק קי\"ג ע\"ב). מסר גם בשם ר\u0027 אלעזר (שבת צ\"ו ע\"א)."},{"i":1620,"n":"ר\u0027 חנינא בר ליוואי","l":"ח","b":"מובא בבבלי (סנהדרין ק\"ח ע\"ב), לפי גיר\u0027 \"יוחסין\" ו\"דק\"ס\", לפנינו ר\u0027 חנא בר ליוואי."},{"i":1621,"n":"רב חנינא בר מיניומי","l":"ח","b":"אמורא בבלי בדור החמישי. הקשה לאביי (ב\"ב קל\"א ע\"א). שנה ברייתא של דבי ר\u0027 אלעזר בן יעקב (התנא) (יומא מ\"ה ע\"ב)."},{"i":1622,"n":"רבי חנינא בר סיסי","l":"ח","b":"מובא בירושלמי (סנהדרין פ\"ב ה\"ו). היה דיין בציפורן. רבי יוחנן כינהו רבי. \"סה\"ד\" סבור שהוא רבי אנינייא בר סיסי."},{"i":1623,"n":"ר\u0027 חנינא בר סנסן","l":"ח","b":"מובא בב\"ר (פי\"ט - ב\u0027)."},{"i":1624,"n":"רבי חנינא בר סרסי","l":"ח","b":"מובא בבבלי (ברכות מ\"ח ע\"א תד\"ה: ולית). ע\"ע רבי חנינא בר סיסי. נראה, שיש שם איזה ט\"ס, שכן לפי התוספות היה תנא בדור השלישי דודו של רבי יוסי בר חלפתא וזה לשון התוספות: \"ומיהו קאמר בירושלמי אמר רבי יוסי זמנין אכלית עם רבי חלפתא אבא ועם רבי חנינא בר סרסי חביבי\" [דודי], ואכן \"סה\"ד\" כתב (בערך ר\u0027 חנינא בר סיסי) שהיה דודו של רבי יוסי בר חלפתא, בהסתמך על התוס\u0027 בברכות."},{"i":1625,"n":"ר\u0027 חנינא בר עגול","l":"ח","b":"מובא בירושלמי (יבמות פ\"ו ה\"ו), והוא ר\u0027 חנינא בר עגיל."},{"i":1626,"n":"ר\u0027 חנינא בר עגיל","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי הרביעי. שאל מר\u0027 חייא בר אבא: מפני מה בדברות הראשונות לא נאמר בהם טוב ובדברות האחרונות נאמר בהם טוב? ולא ידע להשיב לו, ושלחו לר\u0027 תנחום בר חנילאי והוא השיב לו (ב\"ק נ\"ה ע\"א)."},{"i":1627,"n":"ר\u0027 חנינא בר עטל","l":"ח","b":"מובא באס\"ר (פ\"ב - ה\u0027), והוא ר\u0027 חנינא בר עיגול (כמובא מדרש אבא גוריון פסוק ובמלאת)."},{"i":1628,"n":"ר\u0027 חנינא בר עיזקא","l":"ח","b":"מובא בב\"ר (ספי\"ג), והוא ר\u0027 חנינא בר יקא."},{"i":1629,"n":"ר\u0027 חנינא בר פפא","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי. מתלמידי ר\u0027 יוחנן (ירו\u0027, ב\"ק פ\"י ה\"ב). היה תלמידו של ר\u0027 שמואל בר נחמני באגדה (ירו\u0027, שביעית ספ\"ה). חברם של ר\u0027 אבהו, ר\u0027 יצחק נפחא (גיטין כ\"ט ע\"ב) ור\u0027 אמי (יבמות מ\"ח ע\"ב). רב יוסף ואביי שלחו לשאול אצלו הכרעה, ואביי לא קיבל את הכרעתו (כתובות פ\"א ה\"ב). ר\u0027 אלעאי אמר משמו (חגיגה כ\"א ע\"ב). היה חסיד גדול (קידושין ל\"ט ע\"ב). שימש לאמוראים כסמל הצניעות (שם פ\"א ע\"א). מלאך המות אהבו והיה רגיל אצלו (כתובות ע\"ז ע\"ב). וכשנפטר הפסיק עמוד אש בינו לבין העם, דבר המוכיח שהיה מיחידי סגולה בדורו (כתובות ע\"ז ע\"ב)."},{"i":1630,"n":"ר\u0027 חנינא בר פפי","l":"ח","b":"מובא בבבלי (כתובות פ\"ד ע\"ב), ונראה שזהה לר\u0027 חנינא בר פפא."},{"i":1631,"n":"רב חנינא בר רב קטינא","l":"ח","b":"שמו שובש בכמה צורות. מובא בבבלי (גיטין ל\"ח ע\"א). אותו ענין מובא: \"אמר רב הונא בר רב קטינא\" (שם מ\"ג ע\"ב), ושוב אותו ענין מובא:\" רב אחא בר רב קטינה\" (יבמות ס\"ו ע\"א) (ע\"ע)."},{"i":1632,"n":"ר\u0027 חנינא בר שילא","l":"ח","b":"מובא בבבלי (סנהדרין ע\"ב ע\"ב), ועיין רב חיננא בר שילת."},{"i":1633,"n":"ר\u0027 חנינא בר שלדא","l":"ח","b":"מובא באסת\"ר (פ\"ה - ג\u0027), ונראה שהוא ר\u0027 חנינא שלקא."},{"i":1634,"n":"רבי חנינא בר שלמיא","l":"ח","b":"מובא בבבלי (חולין ל\"ז ע\"ב), והוא רב חיננא בר שלמיא."},{"i":1635,"n":"ר\u0027 חנינא ברוקא","l":"ח","b":"מובא בירושלמי (יבמות פ\"א ה\"ו), והוא ר\u0027 חנינא בר יקא."},{"i":1636,"n":"ר\u0027 חנינא בריה דר\u0027 אבא","l":"ח","b":"מובא בויק\"ר (פכ\"ג - ה\u0027)."},{"i":1637,"n":"ר\u0027 חנינא בריה דר\u0027 אבהו","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. בנו ותלמידו של ר\u0027 אבהו (קידושין ל\"ג ע\"ב). אביו שלחו לטבריה ללמוד תורה (ירו\u0027, פסחים פ\"ג ה\"ז). היה דיין בעירו (ירו\u0027, יבמות פ\"ב ה\"ד). האומרים בשמו: ר\u0027 ברכיה (מדרש תהלים פקי\"ט - י\"ד) ור\u0027 חזקיה (בכורים פ\"ג ה\"ה)."},{"i":1638,"n":"ר\u0027 חנינא בריה דר\u0027 אדא","l":"ח","b":"מובא בשהש\"ר (פ\"א - ב\u0027)."},{"i":1639,"n":"ר\u0027 חנינא בריה דר\u0027 בחיי","l":"ח","b":"מובא בירושלמי (פסחים פ\"ג), ואפשר שהוא רב חיננא בר חייא."},{"i":1640,"n":"ר\u0027 חנינא בריה דר\u0027 הלל","l":"ח","b":"אמורא ארץ ישראלי בדור החמישי. פעם הביא מחלוקת של ר\u0027 יונה ור\u0027 יוסי (ירו\u0027, שבת פ\"ג ה\"ה)."},{"i":1641,"n":"ר\u0027 חנינא בריקא","l":"ח","b":"אמורא בבלי בדור השלישי. בשמו יש כמה וכמה שיבושים. מסר בשם רבי יהודה: \"שורשי חטה בוקעין וכו\u0027\" (ירו\u0027, ברכות פ\"ט ה\"ב), ואותו מאמר בשם ר\u0027 חנינא בר יסא (ירו\u0027, ע\"ז פ\"ג ה\"ה), וכן בשם ר\u0027 חנינא בריקא (ירו\u0027, תענית פ\"א ה\"ג). וכן מצינו: \"ר\u0027 חנינא בן ברוקא בני מישא וכו\u0027\" (ירו\u0027, קידושין פ\"ד ה\"א), ואותו מאמר בשם ר\u0027 חנינא ברוקא (ירו\u0027, יבמות פ\"א ה\"ו). וכן מצינו שיבושים נוספים: ר\u0027 חנינא בר עיזקא (ב\"ר ספ\"ג), חנינא בר איקא (ירו\u0027, כתובות פ\"ז ה\"ו) והכל אחד הוא."},{"i":1642,"n":"רבי חנינא דברת חוורן","l":"ח","b":"מובא בירושלמי (ע\"ז פ\"ג ה\"א), והוא רבי חוניה דברת חוורן."},{"i":1643,"n":"ר\u0027 חנינא דציפורין","l":"ח","b":"אמורא ארץ ישראלי בדור החמישי הששי. הרבה למסור בשם ר\u0027 פנחס (ירו\u0027, מעשרות פ\"ג ה\"א). כן מסר בשם ר\u0027 אבהו (ירו\u0027, פ\"ז ה\"ב). היה חברו ובר פלוגתיה דר\u0027 מנא (ירו\u0027, פסחים פ\"ג ה\"א). היה הריש בישיבת ציפורי, וכשנחרבה ישיבת טבריה מקום ר\u0027 מנא, מסר לו ר\u0027 חנינא את הנהגת הישיבה בציפורי. וזה שמצינו: \"ג\u0027 הניחו כתרן בעוה\"ז וירשו חיי העוה\"ב וכו\u0027 ר\u0027 חנינא דציפורן לר\u0027 מנא\" (ירו\u0027, פסחים פ\"ו ה\"א). ישב לפני ר\u0027 מנא (ירו\u0027, מע\"ש פ\"ג ה\"ו)."},{"i":1644,"n":"ר\u0027 חנינא דקיסרין","l":"ח","b":"והוא ר\u0027 חנינא בריה דר\u0027 אבהו."},{"i":1645,"n":"ר\u0027 חנינא הגדול","l":"ח","b":"והוא ר\u0027 חנינא בר חמא."},{"i":1646,"n":"ר\u0027 חנינא הזקן","l":"ח","b":"אמורא ארץ ישראלי בדור השני. הקשה לר\u0027 חנינא (תנחומא שופטים - ח\u0027)."},{"i":1647,"n":"ר\u0027 חנינא חברון דרבנן","l":"ח","b":"מובא (ירו\u0027, ברכות פ\"א ה\"א), והוא רב חנניה (ע\"ע) אחיו של רבה."},{"i":1648,"n":"רב חנינא חוזאה","l":"ח","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של ר\u0027 חסדא (מו\"ק כ\u0027 ע\"א). בא לשאול מרב נחמן (חולין צ\"ה ע\"ב). ממנו ההלכה: \"חזקה הוא על חבר שאינו מוציא דבר שאינו מתוקן\" (עירובין ל\"ב ע\"א)."},{"i":1649,"n":"רבי חנינא טירנאה","l":"ח","b":"מובא בבבלי (כריתות ט\u0027 ע\"א), והוא רבי חנינא תורתייא."},{"i":1650,"n":"רבי חנינא טירתא","l":"ח","b":"מובא בבבלי (מנחות מ\"ח ע\"א), והוא ר\u0027 חנינא תורתייא."},{"i":1651,"n":"ר\u0027 חנינא כתובה","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. אמר בשם ר\u0027 אחא, שאמר בשם ר\u0027 שמעון בן לקיש (ירו\u0027, הוריות רפ\"ג)."},{"i":1652,"n":"רב חנינא מסורא","l":"ח","b":"מובא בבבלי (ב\"ב קל\"ו ע\"א), והוא ר\u0027 חיננא מסורא."},{"i":1653,"n":"רב חנינא מסורא דפרת","l":"ח","b":"אמורא בבלי בדור הששי. חברו של רבינא. כשרבינא בא לסורא דפרת (פרש\"י: ואין זו סורא סתם) שאלו ר\u0027 חנינא (ב\"מ ס\"א ע\"ב)."},{"i":1654,"n":"רבי חנינא סגן הכהנים","l":"ח","b":"תנא בדור הראשון. היה בזמן הבית ואמר: \"אני ראיתיה [אש של הקדש] ורבוצה ככלב\" (יומא כ\"א ע\"ב). גם אביו שימש במקדש: \"רבי חנינא סגן הכהנים אומר: \u0027דוחה היה אבא את בעלי מומין מעל גבי המזבח\u0027\" (זבחים פ\"ד ע\"א). ראה את החורבן בעיניו (תענית י\"ג ע\"א). חלק עם ר\u0027 דוסא בן הרכינס, ועם עקביא בן מהללאל ועם ר\"ע (נגעים פ\"ה מ\"ד). רבי שמעון בן הסגן הוא בנו (לדעת הרמב\"ם). נהרג כ\"ה סיון (שו\"ע או\"ח סי\u0027 תק\"פ). \"יתו\"א\" כתב, שנהרג עם רשב\"ג ועם רבי ישמעאל כהן גדול בזמן שבית המקדש היה קיים."},{"i":1655,"n":"ר\u0027 חנינא ספרא","l":"ח","b":"אמורא ארץ ישראלי בדור השני. ר\u0027 חנינא בר פפא אמר בשמו (מדרש שמואל פכ\"ה - ב\u0027)."},{"i":1656,"n":"רבי חנינא ענתונא","l":"ח","b":"מובא בירושלמי (תרומות פ\"ב ה\"א), והוא ר\u0027 חנינא ענתונייא."},{"i":1657,"n":"רבי חנינא ענתונייא","l":"ח","b":"אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר\u0027 מנא (ירו\u0027, פאה פ\"א ה\"א). מסר בשם ר\u0027 שמעון בן לקיש (ירו\u0027, ע\"ז פ\"ה הי\"א). שמו השתבש בכמה אופנים: ענתוניא (ירו\u0027, תרומות פ\"ב ה\"א), ענתנייה (ירו\u0027, ברכות פ\"ו ה\"ה), סנתוניא (ירו\u0027, פאה פ\"א ה\"א)."},{"i":1658,"n":"ר\u0027 חנינא ענתנייה","l":"ח","b":"מובא בירושלמי (ברכות פ\"ו ה\"ה), והוא ר\u0027 חנינא ענתונייא."},{"i":1659,"n":"ר\u0027 חנינא קרא","l":"ח","b":"אמורא ארץ ישראלי בדור השני. תלמידם של ר\u0027 ינאי (ברכות ל\u0027 ע\"ב) ושל ר\u0027 חנינא (תענית כ\"ז ע\"ב). היה מלמד תינוקות (שם)."},{"i":1660,"n":"ר\u0027 חנינא שלקא","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של ר\u0027 יוחנן (תנחומא תצא - י\u0027)."},{"i":1661,"n":"רבי חנינא תורתייא","l":"ח","b":"אמורא ארץ ישראלי בדור השני - השלישי. שמו שובש בכמה צורות. היה תלמידו של ר\u0027 יוחנן. מסר בשם חזקיה [רבו של ר\u0027 יוחנן] (ירו\u0027, פאה פ\"ג ה\"ז), בשם ר\u0027 ינאי (ירו\u0027, תרומות ספ\"ז) ובשם ר\u0027 אושעיא (שם פ\"י ה\"ו). ר\u0027 יונה מסר בשמו (ירו\u0027, פאה שם). נראה, שר\u0027 חייא בר אבא היה תלמידו (ירו\u0027, ברכות פ\"ג ה\"ה)."},{"i":1662,"n":"רבי חנינא תורתייה","l":"ח","b":"מובא בירושלמי (תרומות ספ\"ז), והוא ר\u0027 חנינא תורתייא."},{"i":1663,"n":"רבי חנינא תיתרא","l":"ח","b":"מובא בירושלמי (תרומות פ\"י ה\"ו), והוא ר\u0027 חנינא תורתייא."},{"i":1664,"n":"רבי חנינא תריתאה","l":"ח","b":"מובא בבבלי (נדרים נ\"ז ע\"ב), והוא ר\u0027 חנינא תורתייא."},{"i":1665,"n":"ר\u0027 חנינה בן ברוקא","l":"ח","b":"מובא בירושלמי (קדושין פ\"ד ה\"א), והוא ר\u0027 חנינא בן בריקא."},{"i":1666,"n":"ר\u0027 חנינה תרתיה","l":"ח","b":"מובא בירושלמי (ברכות פ\"ג ה\"ה), והוא ר\u0027 חנינא תורתייא."},{"i":1667,"n":"חנן","l":"ח","b":"ע\"ע חנין."},{"i":1668,"n":"רב חנן (3)","l":"ח","b":"מובא בבבלי (חולין צ\"ה ע\"ב), ולגיר\u0027 רבנו גרשום: רב חנן בר רבא, והוא היה חתנו דרב (שם)."},{"i":1669,"n":"רבי חנן","l":"ח","b":"תנא בדור החמישי. מסר בשם ר\u0027 מאיר. (מגילה י\"ב ע\"א) וקיבל מרבי (סוכה ט\"ו ע\"ב)."},{"i":1670,"n":"ר\u0027 חנן","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי. מובא בבבלי: \"אר\u0027 חנן, אר\u0027 יעקב בר אידי, אר\u0027 יהושע בן לוי, משום בר קפרא\" (חולין ה\u0027 ע\"ב). אולי הוא ר\u0027 חנין, שמסר בשם ר\u0027 יהושע בן לוי."},{"i":1671,"n":"ר\u0027 חנן אבוה דר\"ש","l":"ח","b":"אמורא ארץ ישראלי בדור השני. מסר בשם ר\u0027 יהושע בן לוי. שמו המדוייק לא ברור - ר\u0027 שמעון או ר\u0027 שמואל, שכן בגמ\u0027 יש ראשי תיבות ר\"ש."},{"i":1672,"n":"חנן בן אבישלום","l":"ח","b":"מדייני גזירות בירושלים בדור החורבן (כתובות ק\"ה ע\"א). חברו של אדמון, גם מדייני גזירות. על שנים מפסקי דינו חלקו בני כהנים גדולים ור\u0027 דוסא בר הרכינס, רבן יוחנן בן זכאי סבר כמוהו ואמר: \"יפה אמר חנן\" (שם ק\"ה ע\"א - ק\"ז ע\"ב)."},{"i":1673,"n":"רב חנן בן פזי","l":"ח","b":"מובא במ\"ר (פ\"ג - א\u0027), ונראה שהוא רבי חנינא בן פזי."},{"i":1674,"n":"חנן בן פנחס","l":"ח","b":"מובא בבבלי (קידושין ע\"ב ע\"א). נראה, שאולי חי בבבל בדור החמישי לאמוראים."},{"i":1675,"n":"ר\u0027 חנן בר אבא","l":"ח","b":"מובא בבבלי (פסחים ל\"ו ע\"ב). ע\"ע רב חנן בר רבא."},{"i":1676,"n":"רב חנן בר אביי","l":"ח","b":"מובא בבבלי (פסחים ק\"א ע\"א), ואולי צ\"ל: רב חנן בר אמי (כמו ע\"ז ל\"ח ע\"א)."},{"i":1677,"n":"רב חנן בר אדא","l":"ח","b":"מובא במדרש שמואל (פי\"ד - ב\u0027)."},{"i":1678,"n":"חנן בר אימי","l":"ח","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב יהודה. מובא בירושלמי (שבת פ\"ו ה\"ה) לפי גיר\u0027 \"אור זרוע\" (ח\"ב ספ\"ד), ולפנינו הגיר\u0027: אנן בר אימא. ולפי \"יוחסין\" ו\"סה\"ד\" הגיר\u0027: און בר אימי."},{"i":1679,"n":"רב חנן בר אמי","l":"ח","b":"אמורא בבלי בדור השני. תלמידם של רב (חולין ט\"ו ע\"א) ושל שמואל (שבת קי\"א ע\"ב). פעמים הגיר\u0027: ר\u0027 חנין בר אמי, ונראה ששניהם אחד. (ע\"ע ר\u0027 חנין בר אשי)."},{"i":1680,"n":"ר\u0027 חנן בר אשי","l":"ח","b":"נראה שצ\"ל: ר\u0027 חנין בר אמי. ע\"ע ר\u0027 חנין בר אשי."},{"i":1681,"n":"חנן בר בא","l":"ח","b":"והוא ר\u0027 חנן בר אבא. ע\"ע רב חנן בר רבא."},{"i":1682,"n":"ר\u0027 חנן בר יוסף","l":"ח","b":"מובא בש\"ר (פמ\"ב - ד\u0027)."},{"i":1683,"n":"ר\u0027 חנן בר מולדה","l":"ח","b":"אמורא בבלי בדור השלישי. תלמידו של רב הונא (סנהדרין ע\u0027 ע\"א)."},{"i":1684,"n":"רבי חנן בר פיטום","l":"ח","b":"תנא בדור הרביעי. תלמידו של רבי עקיבא (תענית כ\"ב ע\"ב)."},{"i":1685,"n":"רב חנן בר רב חסדא","l":"ח","b":"אמורא בבלי בדור השלישי. בנו ותלמידו של האמורא רב חסדא (חולין ס\"ג ע\"א). קיבל מרב (ע\"ז י\"א ע\"ב)."},{"i":1686,"n":"רב חנן בר רב יצחק","l":"ח","b":"מובא בבבלי (פסחים ל\u0027 ע\"ב), לפי גיר\u0027 הרי\"ף, ולפנינו: רבא בר אבא."},{"i":1687,"n":"רב חנן בר רב קטינא","l":"ח","b":"מובא בבבלי: \"א\"ל רב חנן בר רב קטינא לר\"נ\" (חולין י\"ט ע\"א): ול\"דק\"ס\" הגיר\u0027: אמר רב חנא בר רב קטינא לר\"נ."},{"i":1688,"n":"רב חנן בר רבא","l":"ח","b":"אמורא בבלי בדור השני. חתנו ותלמידו של רב (חולין צ\"ה ע\"ב בפי\u0027 ר\u0027 גרשום). וכן היה תלמידו של שמואל (ירו\u0027, ברכות פ\"א ה\"ה). חברו של רב הונא (עירובין ו\u0027 ע\"א). רב חסדא היה חתנו ותלמידו (חולין ס\"ג ע\"א ורש\"י שם). שמו של ר\u0027 חנן בר רבא השתבש פעמים לר\u0027 חנן בר רבה או אבא."},{"i":1689,"n":"ר\u0027 חנן בר רבה","l":"ח","b":"מובא בבבלי (סוכה ב\u0027 ע\"ב). ע\"ע רב חנן בר רבא."},{"i":1690,"n":"רב חנן בר תחליפא","l":"ח","b":"אמורא בבלי בדור השלישי. שלח לרב יוסף (סנהדרין צ\"ז ע\"ב)."},{"i":1691,"n":"ר\u0027 חנן בריה דר\u0027 ברכיה בוצרייה","l":"ח","b":"אמורא ארץ ישראלי בדור החמישי. מבעלי האגדה. מסר בשם ר\u0027 ירמיה (שהש\"ר פ\"ז - א\u0027). ר\u0027 שמואל בר תנחום מסר בשמו (שם)."},{"i":1692,"n":"ר\u0027 חנן דציפורי","l":"ח","b":"מובא בב\"ר (פ\"י - ד\u0027). סביב שם זה יש כמה גירסאות ב\"סה\"ד\"."},{"i":1693,"n":"חנן המצרי א\u0027","l":"ח","b":"היה מדייני גזירות בירושלים בזמן הבית. חי בדור ראשון לתנאים, הוא דורו של ר\u0027 יוחנן בן זכאי (כתובות ק\"ה ע\"א)."},{"i":1694,"n":"חנן המצרי ב\u0027","l":"ח","b":"תנא בדור השלישי. מחכמי יבנה. חברם של בן עזאי ובן זומא (סנהדרין י\"ז ע\"ב)."},{"i":1695,"n":"חנן הנחבא","l":"ח","b":"חסיד ומלומד בניסים, שחי בזמן בית שני, בימי ה\"זוגות\". בן בנו של חוני המעגל. כאשר היו זקוקים לגשמים פנו אליו שיתפלל (תענית כ\"ג ע\"ב)."},{"i":1696,"n":"חנן חייטא","l":"ח","b":"אמורא בבלי בדור השלישי. כשר\u0027 יוסף לא ידע להשיב, אמר עליו: \"יוסף עניא מנא ליה\" (ע\"ז ל\"ט ע\"א)."},{"i":1697,"n":"רב חנן מבי כלוחית","l":"ח","b":"אמורא בבלי בדור הרביעי. אין מתורתו בש\"ס. מובא בבבלי בהקשר לבנו ר\u0027 פפא, שהיה תלמידו של ר\u0027 שימי בר אשי (כתובות מ\u0027 ע\"ב)."},{"i":1698,"n":"רב חנן מנהרדעא","l":"ח","b":"אמורא בבלי בדור השני. חלק עם רב חסדא ורב המנונא (שבת פ\"ב ע\"א). יתכן שהיה עוד חכם ושמו ר\u0027 חנן מנהרדעא, בדור החמישי בבבל, שכן מצינו אותו עם רב כהנא מפום נהרא (קידושין פ\"א ע\"ב), ושמא בקידושין ט\"ס, וצריך לגרוס: רב נחמן מנהרדעא."},{"i":1699,"n":"רב חנן קרטיגנאה","l":"ח","b":"מובא בבבלי (כתובות כ\"ז ע\"ב). ע\"ע רב אחא קרטיגנאה."},{"i":1700,"n":"ר\u0027 חננא","l":"ח","b":"ע\"ע ר\u0027 חנניה או ר\u0027 חנינא או ר\u0027 חיננא."},{"i":1701,"n":"רב חננאל","l":"ח","b":"אמורא בבלי בדור השני. תלמידו המובהק של רב. חברו של רב ברונא (פסחים ק\"ג ע\"א). נראה שהיה מחשובי דורו, ופעם כשנשאל רב הונא, הפנה את השואלים לרב חננאל (בכורות כ\"ד ע\"ב). משמו אמרו: רב איקא בר אבין (מגילה ג\u0027 ע\"א) ור\u0027 זירא (ירו\u0027 מגילה פ\"א ה\"ט). אביי היה לו קשר אישי עמו (קידושין ע\"ב ע\"א). התפרנס מהיותו סופר מומחה (מגילה י\"ח ע\"ב). פעם מצאו רב חסדא כותב ספרים שלא מן הכתב \"אמר ליה: \u0027ראויה כל התורה כולה ליכתב על פיך אלא כך אמרו חכמים אסור לכתוב אות אחת שלא מן הכתב\u0027\" (שם). בנו מובא בירושלמי (מגילה שם)."},{"i":1702,"n":"רב חננאל בר פפא","l":"ח","b":"מובא בבבלי (שבת פ\"ח ע\"ב)."},{"i":1703,"n":"ר\u0027 חננה","l":"ח","b":"עיין ר\u0027 חנינא או ר\u0027 חנניה או ר\u0027 חיננא."},{"i":1704,"n":"ר\u0027 חנניא בן בינאי","l":"ח","b":"מובא בתוספתא (נגעים פ\"א). \"סה\"ד\" כתב: \"נ\"ל ט\"ס וצ\"ל חכנאי\" (כלומר ר\u0027 חנניה בן חכנאי)."},{"i":1705,"n":"רבי חנניא בן יהודה","l":"ח","b":"תנא בדור השלישי - הרביעי. התוכח עם רבי עקיבא (ספרא צו פרשה ב\u0027). רבי יהודה מסר דרשתו: \"קשה הקפדה, שגרמה לו למשה לטעות\" (ספרא שמיני ספ\"א)."},{"i":1706,"n":"רב חנניא חבריהון דרבנן","l":"ח","b":"מובא בירושלמי (תרומות פ\"ה ה\"ג)."},{"i":1707,"n":"רב חנניא טריטאה","l":"ח","b":"מובא בבבלי (תמורה כ\"ט ע\"א), והוא רבי חנינא תורתייא."},{"i":1708,"n":"רב חנניה","l":"ח","b":"אמורא בבלי בדור השלישי, שעלה לארץ ישראל. הוא ואחיו רב אושעיא (לא רבי אושעיא מסדר הברייתות) היו אחיו של רבה (סנהדרין י\"ד ע\"א מהרש\"א). ושלחו מא\"י לבבל לרבה שיבוא לארץ ישראל, ללמוד לפני רבי יוחנן (כתובות קי\"א ע\"א). עליית אחיו רב אושעיא לא\"י מובאת בבבלי (חולין קכ\"ד ע\"א). קיבל מרבי יוחנן (סנהדרין י\"ד ע\"א). ר\u0027 יוחנן הצטער שרצה להסמיכו ולא עלה בידו (סנהדרין שם), ונראה שמשום כך נקרא: \"ר\u0027 חנניה חברון דרבנן\" (ירו\u0027, מעשרות פ\"ה ה\"ב), יען כי לא נסמך על ידי ר\u0027 יוחנן. קיבל גם מר\u0027 אלעזר (בכורות ה\u0027 ע\"ב). ר\u0027 יונה שאל ממנו (ירו\u0027, מו\"ק פ\"ג ה\"ה). ר\u0027 ירמיה אמר בשמו (ירו\u0027, עירובין פ\"ג ה\"ה). הוא ואחיו ר\u0027 אושעיא עסקו בספר יצירה, ובראו עגלא תילתא כל ערב שבת (סנהדרין ס\"ה ע\"ב)."},{"i":1709,"n":"ר\u0027 חנניה (2)","l":"ח","b":"מובא בירושלמי (ערלה פ\"א ה\"ה), והוא ר\u0027 חנינא ציפורין."},{"i":1710,"n":"ר\u0027 חנניה אחי ר\u0027 אחא בר\u0027 חנינא","l":"ח","b":"מובא במ\"ר (פי\"ז - ב\u0027), ונראה שיש כאן ט\"ס."},{"i":1711,"n":"ר\u0027 חנניה איש כפר טבעון","l":"ח","b":"לפי גיר\u0027 \"ילקוט\" (בספרי האזינו פ\u0027 אם לא). וגיר\u0027 שלפנינו ר\u0027 יהודה איש טבעים."},{"i":1712,"n":"ר\u0027 חנניה בן אחוי דרב הושעיא","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי (ירו\u0027, תענית פ\"א ה\"ב)."},{"i":1713,"n":"חנניה בן אחי יאשיה","l":"ח","b":"מובא בבבלי (כתובות ע\"ט ע\"ב). יש חנניה בן אחי יהושע שהיה תנא, ויש רבי חנניה בן אחוי דר\u0027 הושעיא שהיה אמורא."},{"i":1714,"n":"חנניה בן אחי רבי יהושע","l":"ח","b":"תנא בדור השלישי, והוא סתם חנניה בברייתא (יוחסין). ירד לבבל (ספרי דברים פיסקא ב\u0027) וחזר לא\"י (סוכה כ\u0027 ע\"ב), ואח\"כ שוב ירד לבבל, השתקע שם (ברכות ס\"ג ע\"א) ויסד ישיבה גדולה בפומבדיתא (סנהדרין ל\"ב ע\"ב): \"צדק צדק תרדוף וכו\u0027 הלך אחר ר\u0027 חנניה בן אחי ר\u0027 יהושע לגולה\" (שם, רש\"י). היה תלמידו של דודו ר\u0027 יהושע (נדה כ\"ד ע\"ב) ומגדולי הדור (ברכות שם). עיבר שנים בבבל ושלחו לו שלוחים מא\"י שיפסיק מלעבר שנים אחרת יהיה בנידוי, ואחרי שהתיעץ עם רבי יהודה בן בתירא, נשמע לשליחים ופסק מלעבר שנים (שם). נפטר בבבל (קה\"ר פ\"א - ח\u0027)."},{"i":1715,"n":"חנניה בן חזקיה בן גורן","l":"ח","b":"מראשוני התנאים בדור הראשון. אלמלא הוא, היו גונזים את ספר יחזקאל שהיו סותרין דברי תורה: \"מה עשה? העלו לו ג\u0027 מאות גרבי שמן וישב בעליה ודרשן\" (שבת י\"ג ע\"ב). ביתו היה מפגש לחכמים: \"ואלו מן ההלכות שאמרו בעליית חנניה בן חזקיה בן גרון\" (שם). פעם נמנו ורבו ב\"ש על בית הלל וגזרו בעלית חנניה בן חזקיה י\"ח דברים (שם)."},{"i":1716,"n":"חנניה בן חכינאי","l":"ח","b":"תנא בדור השלישי. היה בישיבת יבנה מה\"דנין לפני חכמים\", יחד עם שמעון בן עזאי, שמעון בן זומא וחנן המצרי (סנהדרין י\"ז ע\"ב). תלמידו של רבי עקיבא (חגיגה י\"ד ע\"ב). ישב שתים עשרה שנה בבית המדרש ולמד, וכשחזר פתאום, ואשתו ראתה אותו, יצאה נפשה מרוב בהלה וביקש רחמים ונפשה שבה אליה (כתובות ס\"ב ע\"ב), והפכה למופת כאשת חיל (ב\"ר פי\"ז - ג\u0027)."},{"i":1717,"n":"חנניה בן חכנאי","l":"ח","b":"לדעתו של בעל \"יתו\"א\" היו שני חנניה בן חכנאי שהקדמון בזמנו של רבי יוחנן בן זכאי, והשני שני דורות לאחריו."},{"i":1718,"n":"ר\u0027 חנניה בן חלניפי","l":"ח","b":"מובא במכילתא (בשלח פ\"ג). ונראה שצ\"ל: חכינאי."},{"i":1719,"n":"חנניה בן חנילא","l":"ח","b":"מובא בירושלמי (שקלים פ\"ה ה\"א), וצ\"ל: חנניה בן חכינאי."},{"i":1720,"n":"ר\u0027 חנניה בן יעקב","l":"ח","b":"מובא באבות דר\"נ (פכ\"ט מ\"ג)."},{"i":1721,"n":"ר\u0027 חנניה בן עדו","l":"ח","b":"מובא בתוספתא (סוף עדיות), ויש גירסאות: ר\u0027 חנניא בר עדיי."},{"i":1722,"n":"רבי חנניה בן עקביא","l":"ח","b":"מובא בבבלי (מו\"ק כ\"א ע\"ב), והוא ר\u0027 חנינא בן עקביא."},{"i":1723,"n":"רבי חנניה בן עקשיא","l":"ח","b":"תנא שאין לקבוע זמנו המדוייק. מפורסם מאמרו שנוהגים לסיים בו קריאת כל פרק מפרקי אבות: \"רצה הקב\"ה לזכות את ישראל, לפיכך הרבה להם תורה ומצוות, שנאמר: \u0027ה\u0027 חפץ למען צדקו יגדיל תורה ויאדיר\u0027\" (מכות כ\"ג ע\"ב)."},{"i":1724,"n":"רבי חנניה בן פזי","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי (מגילה פ\"ד ה\"ג), יחד עם רבי חלבו. \"סה\"ד\" סבור, שרבי חנינא בן פזי ורבי איניא בן פזי אחד הם."},{"i":1725,"n":"רבי חנניה בן שמואל","l":"ח","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של ר\u0027 יוחנן (ירו\u0027, דמאי פ\"ב ה\"א)."},{"i":1726,"n":"ר\u0027 חנניה בר אידי","l":"ח","b":"אמורא בבלי בדור החמישי. מובא בבבלי: \"שלח להו רב שמואל בר אידי: \u0027חנניא אחי אומר\u0027\" (פסחים ק\"ד ע\"א)."},{"i":1727,"n":"רב חנניה בר ביבי","l":"ח","b":"אמורא בבלי בדור הששי. מובא בבבלי: \"אמר רב אשי חזינא לרב חנניה בר ביבי וכו\u0027\" (פסחים ק\"י ע\"א). \"יוחסין\" סובר שהיה בן בנו של אביי."},{"i":1728,"n":"רבי חנניה בר מניומי","l":"ח","b":"מובא בבבלי (יומא מ\"ה ע\"ב). זהה לר\u0027 חנינא בר מניומי."},{"i":1729,"n":"רבי חנניה בר עכברי","l":"ח","b":"אמורא ארץ ישראלי בדור הרביעי. מצינו אותו אצל ר\u0027 חייא ציפוראי (ירו\u0027, סוף תרומות)."},{"i":1730,"n":"רב חנניה בר שילא","l":"ח","b":"מובא בבבלי (עירובין י\"ב ע\"א), וע\"ע רב חיננא בר שילת."},{"i":1731,"n":"רב חנניה בר שלמיא","l":"ח","b":"מובא בבכורות (כ\"ד ע\"ב), והוא רב חיננא בר שלמיא."},{"i":1732,"n":"ר\u0027 חנניה בריה דרבי הלל","l":"ח","b":"מובא בירושלמי (יומא פ\"ח ה\"ז), והוא ר\u0027 חנינא בריה דר\u0027 הלל."},{"i":1733,"n":"ר\u0027 חנניה בריה דר\u0027 איבי","l":"ח","b":"מובא בשהש\"ר (פ\"ז - ב\u0027)."},{"i":1734,"n":"ר\u0027 חנניה בר\u0027 יהושע","l":"ח","b":"מובא במ\"ר (פ\"י - ד\u0027), ואולי צ\"ל: ר\u0027 חנניה בן אחי ר\u0027 יהושע."},{"i":1735,"n":"ר\u0027 חנניה ב\u0027","l":"ח","b":"אמורא בבלי בדור החמישי. תלמידו של רבא (כריתות ז\u0027 ע\"א)."},{"i":1736,"n":"ר\u0027 חנניה חברון דרבנן","l":"ח","b":"מובא בירושלמי (מעשרות פ\"ה ה\"ב)."},{"i":1737,"n":"רבי חנניה סגן הכהנים","l":"ח","b":"מובא בבבלי (יומא כ\"א ע\"ב), והוא ר\u0027 חנינא סגן הכהנים."},{"i":1738,"n":"רב חנניה סנתוניא","l":"ח","b":"מובא בירושלמי (פאה פ\"א ה\"א), והוא ר\u0027 חנינא ענתונייא."},{"i":1739,"n":"רבי חנניה תרתייה","l":"ח","b":"מובא בירושלמי (קידושין פ\"א ה\"ה), והוא ר\u0027 חנינא תורתייא."},{"i":1740,"n":"חסא","l":"ח","b":"גברא רבה בדור השלישי בבבל. טבע, ויש אומרים שר\u0027 נחמן הורה לאשתו שמותר לה להנשא (יבמות קכ\"א ע\"ב). והמובא בבבלי: \"שכיב חסא\" (כתובות פ\"ה ע\"ב), ופרש\"י: \"שהוא חסא המובא ביבמות, שטבע בנהר\", ותוספות כתבו: \"משמע דרב נחמן לא פליג ארב חסא רבו\" (ב\"מ נ\"ז ע\"א ד\"ה: אמר), והשיג \"סה\"ד\" וכתב: \"לא ידעתי מנ\"ל דחסא רבו\"."},{"i":1741,"n":"ר\u0027 חסא","l":"ח","b":"מובא ברו\"ר (פ\"ה - ד\u0027)."},{"i":1742,"n":"רב חסדא","l":"ח","b":"אמורא בבלי מפורסם בדור השני - השלישי. עמד בראש ישיבת סורא משנת ד\u0027 נ\"ח - ס\"ח (892 - 803) (\"אגרת רב שרירא גאון\"). תלמידו של רב (ביצה כ\"ה ע\"א רש\"י ד\"ה: מדברי). תלמיד חבר לרב הונא (יבמות פ\"ג ע\"ב תד\"ה: אמרי). בגלל חילופי דברים חריפים עם רב הונא צם 04 תעניות (ב\"מ ל\"ג ע\"א). שניהם, ר\"ה ור\u0027 חסדא מכונים \"סבי דסורא\" (סנהדרין י\"ז ע\"ב) ו\"חסידי בבל\" (תענית כ\"ג ע\"ב). קיבל גם מר\u0027 ירמיה בר אבא (ברכות נ\"ה ע\"ב) ומחותנו רב חנן בר רבא (חולין ס\"ג ע\"א). חבריו היו רב נחמן ורב ששת (עירובין ס\"ז ע\"א) ורב ששת היה \"מרתע\" כל גופו מפלפולו של רב חסדא (שם). בין תלמידיו החשובים היו: רבא (קידושין נ\"ג ע\"ב) ורמי בר חמא (עירובין ח\u0027 ע\"ב), ושניהם היו חתניו (יבמות ל\"ד ע\"ב, רש\"י ותוס\u0027 שם). בימי נעוריו היה עני (שבת ק\"מ ע\"ב). התעשר מעשיית שכר (פסחים קי\"ג ע\"א). בגיל 61 התחתן (קידושין כ\"ט ע\"ב) עם בת בתו של רב (ע\"ז י\"א ע\"ב). היתה לו משפחה ענפה (מו\"ק כ\"ח ע\"א). חי 29 שנה (שם). בעת פטירתו לא יכול מלאך המות לקרב אליו, אלא לאחר שהבהילו (שם). לאחר פטירתו לא נתמנה ריש מתיבתא בסורא, עד שמלך שם רב אשי (\"אגרת רב שרירא גאון\")."},{"i":1743,"n":"רב חסדא בן עוירא","l":"ח","b":"מובא ב\"ילקוט\" (שמואל רמז קי\"ח), ויתכן שיש ט\"ס בשם."},{"i":1744,"n":"רב חסדא בר אבדימי","l":"ח","b":"מובא בבבלי (ברכות נ\"ג ע\"ב)."},{"i":1745,"n":"רב חסדאי","l":"ח","b":"כך נקרא לפעמים ר\u0027 חסדא בירושלמי."},{"i":1746,"n":"רב חסדי","l":"ח","b":"מובא בירושלמי (מגילה פ\"א ה\"ו), והוא רב חסדא."},{"i":1747,"n":"חסיד","l":"ח","b":"כל מקום שמובא \"מעשה בחסיד אחד\" הוא רבי יהודה בן בבא או רבי יהודה בר\u0027 אילעאי (ב\"ק ק\"ג ע\"ב)."},{"i":1748,"n":"ר\u0027 חסידא","l":"ח","b":"אמורא ארץ ישראלי בדור החמישי. תלמידו של ר\u0027 חזקיה (ירו\u0027, סוף מע\"ש) ושל ר\u0027 יוסי (ירו\u0027, נדרים פ\"ה ה\"ה)."},{"i":1749,"n":"חסידי דבבל","l":"ח","b":"כך כונו רב הונא, ורב חסדא (תענית כ\"ג ע\"א), ורב נחמן (גיר\u0027 רש\"י: רב נחמן בר יצחק), (מגילה כ\"ח ע\"ב), ור\u0027 זירא (חולין קכ\"ב ע\"א)."},{"i":1750,"n":"חסידים הראשונים","l":"ח","b":"מובאים ללא שם, כגון בבבלי (נדרים י\u0027 ע\"א), ואין לדעת מי הם."},{"i":1751,"n":"ר\u0027 חפני בר יצחק","l":"ח","b":"מובא בב\"ר (פנ\"ו - ה\u0027)."},{"i":1752,"n":"ר\u0027 חצנא","l":"ח","b":"מובא בירושלמי (ברכות פ\"א ה\"א)."},{"i":1753,"n":"חריפי דפומבדיתא","l":"ח","b":"מובאים בבבלי: \"חריפי דפומבדיתא עיפה ואבימי\" (סנהדרין י\"ז ע\"ב)."},{"i":1754,"n":"רב טבות","l":"ט","b":"אמורא בבלי בדור החמישי. מובא בבבלי (ב\"מ מ\"ט ע\"א)."},{"i":1755,"n":"טבות רישבא","l":"ט","b":"מובא בבבלי (שבת קמ\"ו ע\"ב), והוא טבי רישבא."},{"i":1756,"n":"טבי","l":"ט","b":"עבדו של רבן גמליאל דיבנה, שאמר עליו שהוא \"תלמיד חכם\" (סוכה כ\u0027 ע\"ב) והיה ראוי לסמיכה: \"הרבה בנים היו לו לכנען שראויין ליסמך כטבי, עבדו של רבן גמליאל\" (יומא פ\"ז ע\"א). כשמת קיבל רבן גמליאל תנחומין עליו (ברכות ט\"ז ע\"ב)."},{"i":1757,"n":"ר\u0027 טבי","l":"ט","b":"אמורא בדור השלישי שאין לקבוע מקומו. מסר בשם חכמי בבל: רב (ירו\u0027, תרומות פ\"ח ה\"ג), ר\u0027 ששת (תמורה ל\"ד ע\"א) ור\u0027 חסדא (ירו\u0027, שבת פ\"ג ה\"ז), וכן בשם חכמי א\"י: ר\u0027 יאשיה (ירו\u0027, שקלים פ\"א ה\"א). בשמו מסרו ר\u0027 חזקיה (ירו\u0027, תרומות שם) ור\u0027 יוסי (ירו\u0027, סוכה פ\"ג ה\"א)."},{"i":1758,"n":"רב טבי בר קיסנא","l":"ט","b":"מובא בבבלי (עירובין ק\"ד ע\"ב), וצ\"ל: טובי בר קיסמא, וכן גיר\u0027 התוס\u0027 (סוטה כ\u0027 ע\"ב ד\"ה: לא)."},{"i":1759,"n":"טבי בריה דמרי טבי","l":"ט","b":"אמורא בבלי בדור השני - השלישי. מובא בבבלי: \"אמר טבי בריה דמרי טבי, אמר מר עוקבא, אמר שמואל\" (ר\"ה כ\"ב ע\"א)."},{"i":1760,"n":"טבי רישבא","l":"ט","b":"אמורא בבלי בדור השני. תלמידו של שמואל (שבת י\"ז ע\"ב). היה צד חיות ועופות (שם ברש\"י)."},{"i":1761,"n":"טביומי","l":"ט","b":"הוא מר בר רב אשי (ב\"ב י\"ב ע\"ב)."},{"i":1762,"n":"רב טביומי","l":"ט","b":"אמורא בבלי בדור החמישי. תלמידו של רבא (ב\"ק מ\"א ע\"ב) ושל אביי (ב\"מ נ\"ד ע\"ב). נראה, שעבר לארץ ישראל, שכן מצינו ששאל לר\u0027 חזקיה (ירו\u0027, ברכות פ\"א ה\"ב). מסר בשם ר\u0027 ירמיה (ויק\"ר פל\"ג - ב\u0027)."},{"i":1763,"n":"רב טביומי בר קיסנא","l":"ט","b":"מובא בבבלי (מנחות ע\u0027 ע\"א), והגיר\u0027 במקום אחר: \"רב טובי בר קיסנא\" (כתובות ס\"ד ע\"א), ונראה שאחד הוא, וכן גרס \"דק\"ס\"."},{"i":1764,"n":"רב טבית","l":"ט","b":"מובא בבבלי (חולין מ\"ט ע\"ב). ונראה שצ\"ל: רב טבות."},{"i":1765,"n":"רבי טבלא","l":"ט","b":"אמורא בבלי בדור השני - השלישי. תלמידו של רב (שבת ק\"א ע\"א). היה כפוף לר\"נ (ב\"ב קי\"א ע\"א: חולין קל\"ב ע\"ב). היה דיין (שם). היה גם תלמידו של רב ברונא [תלמיד רב] (סנהדרין כ\"ח ע\"ב). אולי היה בא\"י ונסמך, ולכן נקרא בירושלמי כמעט תמיד רבי טבלא (שבת פ\"ו ה\"ב). ר\u0027 יוסף אמר: \"היינו דשמענא לר\u0027 טבלא וכו\u0027 ולא ידענא מאי קאמר\" (עירובין ע\"ה ע\"א)."},{"i":1766,"n":"ר\u0027 טבלאי","l":"ט","b":"מובא בירושלמי (עירובין פ\"ח ה\"ו), והוא ר\u0027 טבלא."},{"i":1767,"n":"ר\u0027 טבלי","l":"ט","b":"הוא רבי טבלא."},{"i":1768,"n":"רבי טבליי","l":"ט","b":"מובא בירושלמי (שבת פ\"ו ה\"ב), והוא ר\u0027 טבלא."},{"i":1769,"n":"רבי טובי","l":"ט","b":"אמורא ארץ ישראלי בדור הרביעי. אמר בשם ר\u0027 אבהו (ירו\u0027, נדה פ\"א ה\"א)."},{"i":1770,"n":"ר\u0027 טובי בר יצחק","l":"ט","b":"מובא בב\"ר (פמ\"א - ד\u0027)."},{"i":1771,"n":"ר\u0027 טובי בר קיסמא","l":"ט","b":"כן גיר\u0027 תוס\u0027 (סוטה כ\u0027 ע\"ב ד\"ה: הא), ולפנינו טבי בר קיסנא."},{"i":1772,"n":"רב טובי בר קיסנא","l":"ט","b":"אמורא בבלי בדור השני. תלמידו של שמואל (כתובות ס\"ד ע\"א)."},{"i":1773,"n":"רב טובי בר קסנא","l":"ט","b":"מובא בבבלי (מנחות ע\"ו ע\"א), וצ\"ל: רב טובי בר קיסנא."},{"i":1774,"n":"רב טובי בר רב מתנה","l":"ט","b":"אמורא בבלי בדור השלישי. ר\u0027 יוסף מסתמך על מאמרו (ב\"ב כ\"ג ע\"א) מאידך, שלח ר\u0027 טובי בר מתנה לקמיה דר\u0027 יוסף (חולין ל\"ט ע\"ב). האריך ימים אחר ר\u0027 יוסף, וכאשר שוחט העז פנים כנגדו, נידוהו אביי ורבא (מו\"ק ט\"ז ע\"א). נפטר לפני אביי, ונקבר בפומבדיתא (ב\"ב נ\"ח ע\"א)."},{"i":1775,"n":"רב טובי בר רב קטינא","l":"ט","b":"מובא בבבלי (נדה ו\u0027 ע\"ב), ונראה שצ\"ל: רב טובי בר קיסנא (כמו נדרים י\"ב ע\"ב)."},{"i":1776,"n":"רב טובי בר רב קיסנא","l":"ט","b":"אמורא בבלי בדור החמישי. הקשה לרבא (קידושין ל\"ט ע\"ב)."},{"i":1777,"n":"רב טובי בריה דרב נחמיה","l":"ט","b":"אמורא בבלי בדור השלישי - הרביעי. בא לשאול דין אצל ר\u0027 יוסף (ביצה י\"ב ע\"ב)."},{"i":1778,"n":"ר\u0027 טוביה","l":"ט","b":"מובא בקה\"ר (פ\"א - י\"ג)."},{"i":1779,"n":"טוביה הרופא","l":"ט","b":"מובא בירושלמי: \"מעשה בטוביה הרופא שראה את החודש\" (ר\"ה פ\"א מ\"ו) שם מוכח, שהיה בזמן הבית ואין ראיה שנמנה עם החכמים."},{"i":1780,"n":"ר\u0027 טיופה סמוקא","l":"ט","b":"אמורא ארץ ישראלי בדור החמישי. מצינו ש\"בעי קמי רבי יוסי\" (ירו\u0027, יבמות רפ\"ח). מסר בשם ר\u0027 אבהו (ירו\u0027, דמאי פ\"ג רה\"ד)."},{"i":1781,"n":"ר\u0027 טייפה סמוקה","l":"ט","b":"מובא בירושלמי (ירו\u0027, דמאי פ\"ג ה\"ד), והוא ר\u0027 טיופה סמוקא."},{"i":1782,"n":"טרטירוי","l":"ט","b":"חי בזמן הבית. שם מקום מגוריו היה מחלול, והיה עולה לעשות שבת בבית המקדש (ירו\u0027, מע\"ש פ\"ה ה\"ב). ואין ראיה כלל שנמנה עם החכמים."},{"i":1783,"n":"ר\u0027 טרייא","l":"ט","b":"מובא בשהש\"ר (פ\"א)."},{"i":1784,"n":"רבי טרפון (2)","l":"ט","b":"תנא בדור השני - השלישי. ראה את הבית בבניינו וזכה לשמוע את קולו של הכהן הגדול (קידושין ע\"א ע\"א). נראה, שקיבל מרבן יוחנן בן זכאי (תוספתא חגיגה ספ\"ג). מתלמידי בית שמאי (יבמות ט\"ו ע\"א רש\"י). מזקני דורו וקראו לו \"אביהן של כל ישראל\" (ירו\u0027, יומא פ\"א ה\"א). מראשי המדברים ביבנה: \"וזו שאלה נשאלה לפני חכמים בכרם יבנה וכו\u0027, נענה ר\"ט וכו\u0027\" (זבחים נ\"ז ע\"א). מקומו הקבוע היה לוד (חגיגה י\"ח ע\"א). חברם של ר\u0027 יהושע ורבי אלעזר בן עזריה (ידים פ\"ד מ\"ג). הגמרא מפקפקת אם היה רבו או חברו של ר\"ע (כתובות פ\"ד ע\"ב). ר\"ט אמר לר\"ע: \"כל הפורש ממך, כפורש מחייו\" (תוספתא מקואות ספ\"א). בין תלמידיו היו אלעזר בן מתיא, חנינא בן חכינאי, שמעון בן עזאי ושמעון התימני (תוספתא ברכות פ\"ד), וכן ר\u0027 יהודה (תלמידו של ר\"ע) למד אצלו בילדותו (מגילה כ\u0027 ע\"א). היה עשיר גדול (מסכת כלה רבתי פ\"ב). קיים בהקפדה מלאה מצות כיבוד אם (קידושין ל\"א ע\"ב). נהג לומר \"אקפח את בני\" (פרש\"י שבת י\"ז ע\"א: \"מצטער היה על תורה המשתכחת ומקלל את עצמו\"), ובאמת קיפח את בניו ולא נשאר לו בן, רק בן בתו (ב\"מ פ\"ה ע\"א) נפטר אחרי רבי אליעזר (גיטין פ\"ג ע\"א)."},{"i":1785,"n":"רב יאשיה","l":"י","b":"אמורא בבלי בדור החמישי. תלמידו של רבא (ב\"ב כ\"ב ע\"א). חברו של ר\u0027 עובדיה (שם). לשניהם התיר רבא וכו\u0027 לפנים משורת הדין (שם)."},{"i":1786,"n":"רבי יאשיה","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו המובהק של רבי אלעזר (סוטה י\"ט ע\"א). ר\u0027 חייא בר אבא, רבי אמי ורבי אסי היו חבריו (ירו\u0027, תענית פ\"ב ה\"א). ר\u0027 זירא פנה אליו בשאלה (ירו\u0027, שבת פי\"ח רה\"א). ר\u0027 טובי הרבה למסור בשמו (ברכות ט\"ו ע\"ב ועוד). בימי ר\u0027 ירמיה היה גדול הדור ור\u0027 ירמיה כינהו \"אריות\", בעוד שעל עצמו אמר \"שועלים\" (ירו\u0027, שבועות פ\"ט ה\"ד). בשעת פטירתו ביקש ר\u0027 יאשיה שילבישוהו בגדים לבנים (ירו\u0027, כלאים פ\"ט ה\"ג)."},{"i":1787,"n":"ר\u0027 יאשיה","l":"י","b":"תנא בבלי בדור הרביעי. מכונה ר\u0027 יאשיה רבה (סנהדרין י\"ט ע\"א). היה הריש בהוצל והרביץ שם תורה (סנהדרין י\"ט ע\"א: גיטין ס\"א ע\"א). עלה לארץ ישראל והיה תלמידו המובהק של ר\u0027 ישמעאל (מנחות נ\"ז ע\"ב). למד גם לפני ר\u0027 יהודה בן בתירא בנציבין (ירו\u0027, סנהדרין פ\"ח ה\"ו). היה חברו של ר\u0027 יונתן (מנחות נ\"ז ע\"ב) ושל ר\u0027 מתיא בן חרש (אבות דר\u0027 נתן רפ\"א). נפטר לפני רבי (קידושין ע\"ב ע\"א). אחריו היה בנו, ר\u0027 אחי, הריש בהוצל (שם)."},{"i":1788,"n":"ר\u0027 יאשיה בי רבי ינאי","l":"י","b":"מובא בירושלמי (תרומות פ\"ב ה\"א), ואולי צ\"ל: בשם ר\u0027 ינאי."},{"i":1789,"n":"ר\u0027 יאשיה בן לוי","l":"י","b":"מובא בב\"ר (פצ\"ב - ג\u0027), ונראה שצ\"ל: ר\u0027 יהושע בן לוי."},{"i":1790,"n":"ר\u0027 יאשיה דמן אושה","l":"י","b":"אמורא ארץ ישראלי בדור השני. בן העיר אושה. מסר בשם שמואל (מנחות ל\"ט ע\"א לפי ס\"א). היה רבו של רבה בר בר חנא (שם)."},{"i":1791,"n":"רבי יאשיה רבה","l":"י","b":"מובא בבבלי (סנהדרין י\"ט ע\"א), והוא רבי יאשיה התנא."},{"i":1792,"n":"ידוע הבבלי","l":"י","b":"תנא בדור החמישי. תלמידו של ר\"מ. מובא במשנה בש\"ס בבלי: \"ידוע הבבלי אומר, משום ר\"מ\" (ב\"מ צ\"ג ע\"ב)."},{"i":1793,"n":"רב יהודה","l":"י","b":"הוא רב יהודה בר יחזקאל."},{"i":1794,"n":"רבי יהודה","l":"י","b":"הוא התנא רבי יהודה בר אלעאי."},{"i":1795,"n":"רב יהודה אחוה דרב כהנא","l":"י","b":"מובא בבבלי: \"יתיב ר\u0027 כהנא אחוה דרב יהודה וכו\u0027\" (חולין קי\"א ע\"ב) וגיר\u0027 הרא\"ש: \"יתיב ר\u0027 כהנא אחוריה דר\u0027 יהודה\"."},{"i":1796,"n":"רב יהודה אחוה דרב סלא חסידא","l":"י","b":"אמורא בבלי בדור השלישי - הרביעי. שאל מאביי (שבת קי\"ב ע\"א). נראה שהאריך ימים, כי דיבר עם ר\"ה (ברכות ה\u0027 ע\"ב). היה חסיד גדול ואליהו הנביא היה רגיל אצלו (ברכות כ\"ט ע\"ב), וסיפר לו בעוון מה מתעכבת הגאולה (יומא י\"ט ע\"ב)."},{"i":1797,"n":"יהודה איש הוצא","l":"י","b":"מובא בירושלמי (נדרים פי\"א ה\"א), וצ\"ל: יוסי איש הוצל, והוא איסי בן עקביה."},{"i":1798,"n":"יהודה איש הוצי","l":"י","b":"מובא בירושלמי (שביעית פ\"ח ה\"ה), והוא איסי בן עקביה."},{"i":1799,"n":"ר\u0027 יהודה איש טיבעים","l":"י","b":"מובא בספרי (האזינו פסוק איכה ירדוף), וגיר\u0027 ה\"ילקוט\" שונה."},{"i":1800,"n":"ר\u0027 יהודה איש כפר גבור חיל","l":"י","b":"מובא בבבלי (מגילה י\"ח ע\"א)."},{"i":1801,"n":"ר\u0027 יהודה איש כפר גבוריא","l":"י","b":"מובא בבבלי (מגילה י\"ח ע\"א)."},{"i":1802,"n":"רבי יהודה איש כפר נביריא","l":"י","b":"מובא בבבלי (כתובות ס\"ה ע\"א), וגיר\u0027 \"מסה\"ש\": \"גבוריא\"."},{"i":1803,"n":"ר\u0027 יהודה איש כפר נפור חיל","l":"י","b":"מובא בבבלי (כתובות ס\"ה ע\"א). וגיר\u0027 \"מסה\"ש\": \"איש כפר גבור חיל\"."},{"i":1804,"n":"יהודה איש כפר עכו","l":"י","b":"מובא במכילתא (יתרו פ\u0027 ויאמר משה לחותנו). ונראה שהוא ר\u0027 יהודה בן אגרא איש כפר עכו."},{"i":1805,"n":"ר\u0027 יהודה בן אגרא","l":"י","b":"תנא בדור הרביעי - החמישי. מסר בשם רבי מאיר (חולין קל\"ד ע\"א), ובשם רבי יוסי (נדה נ\"ב ע\"ב)."},{"i":1806,"n":"רבי יהודה בן אגרא איש כפר עכו","l":"י","b":"תנא בדור הרביעי - החמישי. שאל מרבן גמליאל דיבנה (מכילתא יתרו מסכתא דעמלק פ\"ב). מסר בשם ר\u0027 מאיר (חולין קל\"ד ע\"א), ובשם ר\u0027 יוסי (נדה נ\"ב ע\"ב). רבן שמעון בן גמליאל (אבי רבי) מסר הלכה בשמו (תוספתא כלאים פ\"א י\"ב). ר\u0027 שמעון בן יהודה איש כפר עכו (סוטה ל\"ז ע\"ב) הוא אולי בנו."},{"i":1807,"n":"רבי יהודה בן אחותו של רבי יוסי בר חנינא","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם דודו ר\u0027 יוסי בר חנינא (ירו\u0027, תרומות פי\"א סה\"ד). רבין, באגרתו לבבל, מסתמך על דבריו (כתובות מ\"ט ע\"ב)."},{"i":1808,"n":"רבי יהודה בן בתירא א\u0027","l":"י","b":"תנא בדור הראשון. מושבו בנציבין שבבבל ושם היתה לו ישיבה (סנהדרין ל\"ב ע\"ב). ראה את בית המקדש בבניינו. כאשר ארמי התפאר שאכל בירושלים מקרבן הפסח, הערים עליו ולכדו והרגוהו ושלחו לו: \"אתה בנציבין ומצודתך פרוסה בירושלים\" (פסחים ג\u0027 ע\"ב)."},{"i":1809,"n":"רבי יהודה בן בתירא ב\u0027","l":"י","b":"תנא בבלי בדור השלישי. נולד ברומי (ירו\u0027, סנהדרין פ\"ז הי\"ג). חי בארץ ישראל. חברו של ר\"ע ובר פלוגתיה (שבת צ\"ו ע\"ב). מפאת רדיפות המלכות, עזב את א\"י והלך לבבל. בהגיעו לגבול יחד עם חבריו ר\u0027 מתיא בן חרש (שפנה לרומי ויסד שם ישיבה) ור\u0027 חנינה בן אחי ר\u0027 יהושע (שיצא לנהר פקוד שבבבל ויסד ישיבה), זכרו את א\"י וזלגו עיניהם דמעות וקרעו בגדיהם (ספרי דברים פיסקא פ\u0027). \"צדק צדק תרדוף... אחרי ר\u0027 יהודה בן בתירא לנציבין\" (סנהדרין ל\"ב ע\"ב). ר\"א בן שמוע ור\u0027 יוחנן הסנדלר הלכו לנציבין ללמוד אצלו תורה, וכשהגיעו לצידון החליטו לשוב מפאת חשיבות ישיבת א\"י (ספרי שם). מתלמידיו: ר\u0027 יאשיא (ירו\u0027, סנהדרין פ\"ח ה\"ו). ר\u0027 חנינא בן אחי ר\u0027 יהושע התיעץ עמו כשאסרו עליו לעבר שנים בחו\"ל ושמע לעצתו (ברכות ס\"ג ע\"א). נראה, שלו אמר ר\u0027 אליעזר: \"חכם גדול אתה\" (נגעים פ\"ט מ\"ג)."},{"i":1810,"n":"יהודה בן גדידיה","l":"י","b":"חי בימי בית שני, בזמנו של שמעון בן שטח (דור שלישי לחכמי ה\"זוגות\"). אמר לינאי המלך: \"רב לך כתר מלכות\" וינאי הרג אח\"כ כל חכמי ישראל (קדושין ס\"ו ע\"א)."},{"i":1811,"n":"רבי יהודה בן גדיש","l":"י","b":"תנא בדור השני - השלישי. העיד לפני רבי אליעזר (עירובין כ\"ז ע\"א)."},{"i":1812,"n":"יהודה בן גוריא","l":"י","b":"תנא בדור השלישי. תלמידו של רבי אליעזר. הורה לפני רבו ולא הוציא שנתו (עירובין ס\"ג ע\"א)."},{"i":1813,"n":"רבי יהודה בן גירין","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. הוא ורבי יהושע דסכנין אמרו בשם רבי לוי (מדרש שמואל)."},{"i":1814,"n":"רבי יהודה בן גמדא איש כפר עכו","l":"י","b":"מובא בבבלי (סוטה מ\"ג ע\"ב), ונראה שהוא ר\u0027 יהודה בן אגרא איש כפר עכו."},{"i":1815,"n":"ר\u0027 יהודה בן גמליאל","l":"י","b":"תנא בדור הרביעי. בנו של רבן גמליאל דיבנה ואחיהם של רבן שמעון בן גמליאל (אבי רבי) ושל ר\u0027 חנינא בן גמליאל. מסר בשם אחיו ר\u0027 חנינא (ע\"ז ל\"ד ע\"ב)."},{"i":1816,"n":"רבי יהודה בן גרים","l":"י","b":"תנא בדור הרביעי - החמישי. בן גר וגיורת (שבת ל\"ג ע\"ב ברש\"י). תלמידו של רבי שמעון בר יוחאי (מו\"ק ט\u0027 ע\"א). רשב\"י שלח אליו ולחברו ר\u0027 יונתן בן עסמיי את בנו שיברכהו (שם). פעם דיבר רשב\"י נגד מלכות רומי ויהודה בן גרים שמע וסיפר זאת למקורביו, ונודע למלכות ורצו להרוג את רשב\"י, וברח והסתתר במערה י\"ג שנה, וכשיצא רשב\"י פגש את יהודה תלמידו, ונתן עיניו בו ונהפך לגל עצמות (שבת ל\"ג ע\"ב)."},{"i":1817,"n":"רבי יהודה בן דוסתאי","l":"י","b":"תנא שאין לקבוע זמנו המדוייק. מובא במשנה, שאמר משום רבי שמעון בן שטח (ברכות ז\u0027 ע\"א)."},{"i":1818,"n":"יהודה בן דורתאי","l":"י","b":"מחכמי א\"י בתקופת ה\"זוגות\", כמאה שנה לפני חורבן הבית בדורם של שמעיה ואבטליון (הזוג הרביעי). פרש עם בנו והלך וישב בדרום, משום שחלק על החכמים בענין דין קרבן חגיגה (פסחים ע\u0027 ע\"ב). מובא פעם אחת בלבד בש\"ס. \"סה\"ד\" כתב: \"ונראה שהיה צדוקי\", ותמוה מנין לו."},{"i":1819,"n":"ר\u0027 יהודה בן דמא","l":"י","b":"בפיוט \"אלה אזכרה\" למוסף יום הכיפורים נמנה בין עשרת הרוגי מלכות שנהרגו על קידוש ה\u0027 יחד עם ר\u0027 עקיבא וחבריו. במקומות אחרים לא הובא שם זה כלל."},{"i":1820,"n":"ר\u0027 יהודה בן דרדייא","l":"י","b":"מובא בירושלמי (נדרים פ\"ז ה\"א). אולי אפשר להסיק מהענין שהוא אמורא ארץ ישראלי בדור הרביעי."},{"i":1821,"n":"רבי יהודה בן חגרא","l":"י","b":"מובא בירושלמי (פאה פ\"ד ה\"ז), והוא רבי יהודה בן אגרא."},{"i":1822,"n":"ר\u0027 יהודה בן חנניה","l":"י","b":"תנא שאין לקבוע זמנו המדוייק. מובא בספרי (האזינו פסוק א\u0027)."},{"i":1823,"n":"רבי יהודה בן חרגא","l":"י","b":"מובא בירושלמי (כתובות פ\"א ה\"ג). \"סה\"ד\" כתב: \"ודאי שהוא רבי יהודה בן אגרא\"."},{"i":1824,"n":"יהודה בן טבאי","l":"י","b":"מחכמי ישראל הקדומים, שעמדו בראש הסנהדרין בימי בית שני. והוא וחברו שמעון בן שטח היו השלישי ב\"זוגות\". היה הנשיא או אב\"ד (חגיגה ט\"ז ע\"ב). רצו למנותו נשיא וברח לאלכסנדריה (ירו\u0027, חגיגה פ\"ב ה\"ב). שמעיה ואבטליון היו תלמידיו. פעם טעה והרג עד זומם, ומיד קיבל עליו לא להורות אלא בפני שמעון בן שטח (חגיגה שם). הוא בעל המאמר: \"אל תעש עצמך כעורכי הדיינין, וכשיהיו בעלי הדין עומדים לפניך, יהיו בעיניך כרשעים, וכשנפטרים מלפניך, יהיו בעיניך כזכאין וכו\u0027\" (אבות פ\"א מ\"ח)."},{"i":1825,"n":"רבי יהודה בן טיטוס","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי אחא (ירו\u0027, ברכות פ\"ג ה\"ד). מסר גם בשמו של יהודה בן פזי (ירו\u0027, שבת פי\"ג ה\"ב). הלך לרומי ולפני נסיעתו קבל סמיכה, בתנאי שיחזור לארץ ישראל (ירו\u0027, בכורים פ\"ג סה\"ג)."},{"i":1826,"n":"רבי יהודה בן יאיר","l":"י","b":"תנא בדור השלישי. רבן שמעון בן גמליאל (אבי רבי) מסר בשמו (יבמות פ\u0027 ע\"ב)."},{"i":1827,"n":"ר\u0027 יהודה בן יעקב מבית גוברין","l":"י","b":"תנא שאין לקבוע זמנו המדוייק. מובא בתוספתא (אהלות פי\"ח ט\"ז)."},{"i":1828,"n":"ר\u0027 יהודה בן ישעיה הבשם","l":"י","b":"תנא בדור השלישי - הרביעי. תלמידו של רבי טרפון והעיד לפני רבי עקיבא משמו של ר\"ט (תוספתא שביעית פ\"ה י\"ב). (ובחולין נ\"ה ע\"ב, הגירסה: \"ר\u0027 אושעיא בנו של ר\u0027 יהודה הבשם\"). מלאכתו היתה מכירת בשמים (חולין נ\"ה ע\"ב - רש\"י). ע\"ע רבי אושעיא בנו של רבי יהודה הבשם."},{"i":1829,"n":"רבי יהודה בן כיני","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידו של רבי אמי (ירו\u0027, תרומות פי\"א סה\"א)."},{"i":1830,"n":"רבי יהודה בן לוי","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. תלמידו של ר\u0027 יהושע בן לוי (ירו\u0027, שבת פ\"ז סה\"ב), ויש סבורים שהיה אחיו. רבי יוחנן שאל ממנו (שבת קי\"ג ע\"א) נראה, שגם בנו מנחם היה חכם (ירו\u0027, דמאי פ\"ה ה\"ח)."},{"i":1831,"n":"ר\u0027 יהודה בן לקיש","l":"י","b":"תנא בדור החמישי. מסר בשם רבן שמעון בן גמליאל (קה\"ר פ\"א - ט\"ו)."},{"i":1832,"n":"ר\u0027 יהודה בן לקרח","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מסר בשם רבי שמואל בר נחמן. היה מבעלי האגדה (ירו\u0027, סוכה פ\"ד ה\"ו)."},{"i":1833,"n":"ר\u0027 יהודה בן מנשי","l":"י","b":"מובא בבבלי (מגילה י\"ד ע\"א), ובמקום אחר (ברכות י\u0027 ע\"א): הגיר\u0027: ר\u0027 יהודה בר מנסיא."},{"i":1834,"n":"ר\u0027 יהודה בן נקוסא","l":"י","b":"תנא בדור החמישי. תלמידו של רבי (ב\"ב ע\"א ע\"א) ושל סומכוס (ב\"ק ל\"ט ע\"א). מסר בשם ר\u0027 יעקב (חולין קי\"ח ע\"ב). כל מעשיו היו לשם שמים (ב\"ק פ\"א ע\"ב). הרבה להתוכח עם מינים (קה\"ר פ\"א פסוק ח\u0027 - ד\u0027)."},{"i":1835,"n":"יהודה בן פדייה","l":"י","b":"מובא בב\"ר (פצ\"ד - ה\u0027). ונראה שהוא בר פדא."},{"i":1836,"n":"ר\u0027 יהודה בן פדייה","l":"י","b":"מובא בתנחומא (וארא - ב\u0027). ונראה שהוא בר פדא."},{"i":1837,"n":"ר\u0027 יהודה בן פזי (2)","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. לדעת תוספות (ב\"ב קמ\"ט ע\"א ד\"ה: רב) שם אמו של ר\u0027 יהודה היתה פזי (אולי בתו של ר\u0027 חייא - יבמות ס\"ה ע\"ב). מסר בשם ריב\"ל (ירו\u0027, ברכות פ\"ג ה\"א) ובשם ר\u0027 יוחנן (ירו\u0027, מע\"ש פ\"ג ה\"ג). התאכסן בבית הנשיא (ירו\u0027, שבת פי\"ב ה\"ג)."},{"i":1838,"n":"יהודה בן פטורא","l":"י","b":"ע\"ע יהודה בן פטורי."},{"i":1839,"n":"יהודה בן פטורי","l":"י","b":"תנא בדור השני. מובא בבבלי: \"דרש בן פטוראי וכו\u0027, עד שבא ר\"ע ולימד וכו\u0027\" (ב\"מ ס\"ב ע\"א)."},{"i":1840,"n":"ר\u0027 יהודה בן פילויה","l":"י","b":"מובא בש\"ר (פמ\"ב - ט\u0027), ונראה שהוא ר\u0027 יודן בר פליא."},{"i":1841,"n":"ר\u0027 יהודה בן פפוס","l":"י","b":"תנא בדור השני. ור\u0027 יהושע אמר עליו: \"שכל מעשיו לשם שמים\" (ירו\u0027, ברכות פ\"ב ה\"ט)."},{"i":1842,"n":"ר\u0027 יהודה בן קנוסא","l":"י","b":"מובא בבבלי (ב\"ק פ\"א ע\"ב), וצ\"ל: ר\u0027 יהודה בן נקוסא."},{"i":1843,"n":"יהודה בן רבי חייא","l":"י","b":"אמורא בדור הראשון. נולד בבבל ועלה יחד עם אביו ואחיו לא\"י (סוכה כ\u0027 סע\"א). הוא ואחיו חזקיה היו תאומים, אחד נולד בתחילת ז\u0027 חדשים והשני לסוף ט\u0027 חדשים (יבמות ס\"ה ע\"ב), ונראה שיהודה היה הבכור, שכן נזכר תחילה בכל מקום. הם נקראו \"אמוראי דמערבא\" (ב\"ב ע\"ה ע\"א). התחתן עם בתו של ר\u0027 ינאי (כתובות ס\"ב ע\"ב). נפטר בחיי חותנו (שם) ונקבר לימין אביו [בטבריה] (מו\"ק כ\"ה ע\"א). כשעלה מבבל כבר היה גדול הדור (חולין פ\"ו ע\"א). היה כה גדול, עד שר\u0027 ינאי קראו: \"יהודה בריבי\" (ירו\u0027, בכורים פ\"ג ה\"ג). היה מאוכלי שולחנו של רבי (סנהדרין ל\"ה ע\"א). חלק עם רבי יונתן בהלכה (עירובין ק\"ג ע\"ב). אליהו הנביא גילה לרבי שרבי חייא ובניו הם דוגמת אברהם יצחק ויעקב (ב\"מ פ\"ה ע\"ב)."},{"i":1844,"n":"ר\u0027 יהודה בן רועץ","l":"י","b":"מובא בבבלי: \"שאלו תלמידיו את ר\u0027 יהודה בן רועץ וכו\u0027\" (סנהדרין ד\u0027 ע\"א)."},{"i":1845,"n":"יהודה בן שמוע","l":"י","b":"תנא בדור הרביעי - החמישי. תלמידו של רבי מאיר (ר\"ה י\"ט ע\"א). רשב\"ג (אבי רבי) מסר הלכה אחת בענייני טומאה, שיהודה בן שמוע אמר בשם ר\"מ (שם). פעם גזרה המלכות ביום כ\"ח באדר שלא יעסקו בתורה ושלא ימולו את בניהם ושיחללו את השבת, והלך יהודה בן שמוע וחבריו, ונטל עצה ממטרונית אחת שכל גדולי רומי מצויין אצלה וביטל הגזרה (שם)."},{"i":1846,"n":"ר\u0027 יהודה בן תימא","l":"י","b":"תנא שאין לקבוע את זמנו המדוייק. היה מראשי דורו ועליו אמרו: \"בעלי משנה כגון ר\u0027 יהודה בן תימא וחבריו, פליגי בה ר\"פ ורבנן, חד אמר: \u0027שש מאות סדרי משנה\u0027 וחד אמר: \u0027שבע מאות סדרי משנה\u0027\" (חגיגה י\"ד ע\"א). מפורסם מאמרו: \"הוי עז כנמר וקל כנשר ורץ כצבי וגבור כארי, לעשות רצון אביך שבשמים\" (אבות פ\"ה מ\"כ)."},{"i":1847,"n":"רב יהודה בנו של רב שמואל בר שילת","l":"י","b":"אמורא בבלי בדור השלישי. מסר פעמים רבות בשם רב (ברכות מ\"ז ע\"א). היה חברם של רב יהודה (תענית י\"ד ע\"א) ורב הונא בר חיננא (מו\"ק ט\"ז ע\"א)."},{"i":1848,"n":"רבי יהודה בנו של רבן יוחנן בן זכאי","l":"י","b":"תנא בדור השני. הלכה אחת בלבד הובאה בשמו (נדה ט\"ו ע\"א), וכן הוא בתוספתא (שם פ\"ג)."},{"i":1849,"n":"רב יהודה בר אבא","l":"י","b":"מובא בבבלי (מנחות ל\"א ע\"ב), ויש גירסאות שונות בשם."},{"i":1850,"n":"רב יהודה בר אביי","l":"י","b":"מובא בבבלי (פסחים צ\"ב ע\"ב), וגיר\u0027 \"מסורת הש\"ס\" ו\"דק\"ס\": \"רבי יהודה בר אמי\"."},{"i":1851,"n":"ר\u0027 יהודה בר אבין","l":"י","b":"מובא בירושלמי (ר\"ה פ\"א ה\"ח)."},{"i":1852,"n":"רב יהודה בר אושעיא","l":"י","b":"אמורא בבלי בדור השלישי. שאלוהו שאלה ולא ידע להשיב, וחזרו ושאלוה לר\u0027 מתנה ולא ידע להשיב, ושאלוה מר\u0027 יהודה והשיב: \"הכי אמר שמואל\" (עירובין פ\u0027 ע\"א). נראה, שמושבו היה בפומבדיתא, שמצינו: \"רב יהודה בר אושעיא היה קא קליף ליה טחלא ללוי בריה דר\"ה בר חייא\" (חולין צ\"ג ע\"א), ור\"ה בר חייא הרביץ תורה בפומבדיתא (\"אגרת רב שרירא גאון\")."},{"i":1853,"n":"רב יהודה בר אחותאי","l":"י","b":"מובא בבבלי (כריתות י\"ג ע\"ב)."},{"i":1854,"n":"רב יהודה בר אידי","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של ר\u0027 יוחנן (ר\"ה ל\"א ע\"א)."},{"i":1855,"n":"רב יהודה בר אישתתא","l":"י","b":"אמורא בבלי בדור הרביעי. רב נתן בר אושעיה היה תלמידו (עירובין נ\"ב ע\"א)."},{"i":1856,"n":"רבי יהודה בר אלעאי","l":"י","b":"תנא בדור הרביעי, והוא סתם רבי יהודה בש\"ס (מנחות י\"ח ע\"א). \"כל היכא דאמר מעשה בחסיד אחד או ר\u0027 יהודה בן בבא או ר\u0027 יהודה בר אילעאי\" (ב\"ק ק\"ג ע\"ב). בנו ותלמידו של התנא רבי אילעאי (מנחות שם). מושבו היה באושא (שהש\"ר פ\"ב - ה). בילדותו למד אצל ר\"ט בלוד (מגילה כ\u0027 ע\"א) ואצל ר\u0027 ישמעאל (מו\"ק כ\"ד ע\"ב). מגדולי תלמידיו של רבי עקיבא (יבמות ס\"ב ע\"ב). על פיו כתב את הספרא: \"סתם ספרא רבי יהודה, סתם סיפרי ר\"ש, וכולהו אליבא דר\"ע\" (סנהדרין פ\"ו ע\"א). כן קיבל מר\"א בן עזריה (ברכות ט\"ו ע\"ב). הוא וארבעת חבריו: ר\"מ, ר\u0027 יוסי, ר\"ש ור\"א בן שמוע, נסמכו ע\"י ר\u0027 יהודה בן בבא (סנהדרין י\"ד ע\"א). מגדולי התנאים וראש המדברים בכל מקום (שבת ל\"ג ע\"ב). בכל מחלוקת בינו לבין ר\u0027 מאיר או ר\u0027 שמעון, ההלכה כר\u0027 יהודה (עירובין מ\"ו ע\"ב). בין תלמידיו: רבנו הקדוש (שבועות י\"ג ע\"א) ורבי ישמעאל ברבי יוסי (סוכה י\"ח ע\"א). חלק עם ר\u0027 יוחנן בן ברוקה (עירובין ק\"ד ע\"ב) ועם ר\u0027 שמעון שזורי (מנחות ל\u0027 ע\"ב). מצינו מחלוקת: \"איזו היא משנה? ר\"מ אומר הלכות ר\u0027 יהודה אומר מדרש\" (קידושין מ\"ט ע\"א). לבן עזאי אמר: \"עד כאן העזת פניך ברבך\" [ר\"ע] (ברכות ס\"ב ע\"א). היה עני מרוד עד שלא היתה לו כסות (נדרים מ\"ט ע\"ב). פניו האירו תמיד (שם). מנהגו בערב שבת: \"רוחץ פניו ידיו ורגליו, ומתעטף ויושב בסדינין המצוייצין, ודומה למלאך ה\u0027 צבאות\" (שבת כ\"ה ע\"ב). נראה שהאריך ימים, שכן נפטר אחרי רבי מאיר (נזיר מ\"ט ע\"ב), וכנראה גם אחרי רבי יוסי (סוכה י\"ח ע\"א). הורה הלכות בבית רבי (מנחות ק\"ד ע\"א). הניח אחריו בן חכם ושמו רבי יוסי (מנחות ס\"ג ע\"ב), שהיה מן התנאים בדור החמישי. בן אחר נפטר על פניו (מו\"ק כ\"א ע\"א)."},{"i":1857,"n":"רבי יהודה בר אמי","l":"י","b":"אמורא ארץ ישראלי. מסר בשם ר\"ל (ירו\u0027, תרומות ספ\"ב) ובשם רב יהודה (עירובין ל\u0027 ע\"ב). ר\"ז, כשהתעייף מלימוד, היה יושב ליד פתח ביתו של רבי יהודה בר אמי, כדי לקיים מצות קימה לפני חכמים (שם כ\"ח ע\"ב)."},{"i":1858,"n":"רב יהודה בר אשי","l":"י","b":"אמורא בבלי בדור השלישי. אמר משמו של רב (ברכות י\"ט ע\"ב) גיר\u0027 \"דק\"ס\": ר\u0027 יהודה בר אמי."},{"i":1859,"n":"רב יהודה בר בבא","l":"י","b":"תנא בדור השלישי. תלמידו של שמואל הקטן (תוספתא סוטה פי\"ג ד\u0027). חברו של רבי עקיבא (יבמות קכ\"ב ע\"א) וחלק עמו (יומא פ\"ו ע\"ב). היה מופלג בחסידות עד שאמרו: \"כל היכא דאמרינן מעשה בחסיד אחד או רבי יהודה בן בבא או רבי יהודה בר אילעאי\" (ב\"ק ק\"ג ע\"ב). נהרג על קידוש ה\u0027 והיה מעשרת הרוגי מלכות: \"זכור אותו איש לטוב ורבי יהודה בן בבא שמו, שאילמלא הוא וכו\u0027 בטלו דיני קנסות מישראל, שפעם אחת גזרה המלכות גזרה על ישראל שכל הסומך יהרג וכו\u0027, וסמך שם חמישה זקנים ואלו הן: רבי מאיר ורבי יהודה ורבי שמעון ורבי יוסי ורבי אלעזר בן שמוע\" (כולם תלמידי רבי עקיבא), והכירו אויביהם בהם ונעצו בו 003 חניתות של ברזל (סנהדרין י\"ג ע\"ב). רבי עקיבא נהרג קודם לו (מסכת שמחות פ\"ח)."},{"i":1860,"n":"ר\u0027 יהודה בר ביזנא","l":"י","b":"מובא בבבלי (נדרים ל\"ב ע\"א)."},{"i":1861,"n":"ר\u0027 יהודה בר ביני","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. אמר בשם ר\u0027 אמי (ירו\u0027, תרומות פי\"א סה\"א)."},{"i":1862,"n":"רבי יהודה בר גדיא","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. סיפר על מנהגו של ר\u0027 יעקב בר בון בענייני מעשרות (ירו\u0027, מע\"ש פ\"ד ה\"א)."},{"i":1863,"n":"יהודה בר גרוגרות","l":"י","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (יומא ע\"ח ע\"א). תוספות ישנים גורסים: יהודה גרוגרות."},{"i":1864,"n":"רבי יהודה בר זבדא","l":"י","b":"מובא בירושלמי (ברכות פ\"א ה\"ה), והוא ר\u0027 יהודה בר זבידא."},{"i":1865,"n":"רב יהודה בר זבדי","l":"י","b":"מובא בבבלי (קידושין ע\"ג ע\"ב), והוא ר\u0027 יהודה בר זבדא."},{"i":1866,"n":"רבי יהודה בר זבידא","l":"י","b":"אמורא ארץ ישראלי בדור השני. ר\u0027 שמואל בר נחמן (תלמידו של ר\u0027 יוחנן) מסר בשמו (ירו\u0027, ברכות פ\"א ה\"ה). רבי אבהו בר זוטרי היה תלמידו (ברכות י\"ב ע\"ב). היו לו שני אחים: ר\u0027 אבא (יבמות פ\"ג ע\"ב) ור\u0027 סימון (ירו\u0027, ב\"ב רפ\"ג)."},{"i":1867,"n":"רב יהודה בר זבינא","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. חברו ובר פלוגתיה דר\u0027 חנינא [חברון דרבנן] (חולין צ\"ט ע\"ב)."},{"i":1868,"n":"ר\u0027 יהודה בר זכריה","l":"י","b":"מובא ב\"ילקוט\" (תבוא - תתק\"ל)."},{"i":1869,"n":"רב יהודה בר חביבא","l":"י","b":"אמורא ארץ ישראלי בדור השני. תלמידו של שמואל (כתובות ס\u0027 ע\"א). בתו התחתנה עם בנו של רב יהודה (ברכות מ\"ב ע\"א)."},{"i":1870,"n":"רב יהודה בר חיננא","l":"י","b":"אמורא בבלי בדור החמישי. תלמידו של רב הונא בריה דרב יהושע (ב\"ק י\"ד ע\"ב)."},{"i":1871,"n":"ר\u0027 יהודה בר חמא","l":"י","b":"מובא בתנחומא (נ\"ח - ח\u0027)."},{"i":1872,"n":"רבי יהודה בר חנינא","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. מרבותיו של ר\"ל, כמובא בגמרא: \"הא דידיה הא דרביה\" (עירובין י\"א ע\"ב). ר\"ל מסר בשמו על תקנות אושא (ירו\u0027, פאה פ\"א ה\"א). ר\"ל קנס אדם בליטרא זהב, לאחר שהעליב את רבו זה (ירו\u0027, ב\"ק פ\"ח ה\"ו)."},{"i":1873,"n":"רב יהודה בר יחזקאל","l":"י","b":"מגדולי אמוראי בבל בדור השני. מייסדה של ישיבת פומבדיתא [שהתקיימה כ - 008 שנה] (\"אגרת רב שרירא גאון\"). נולד ביום שנפטר רבי יהודה הנשיא (קידושין ע\"ב ע\"ב). האריך ימים ונפטר בשנת ד\"א נ\"ח (842) (\"אגרת רב שרירא גאון\"). תלמידם של רב (קידושין פ\"א ע\"א) ושל שמואל (יבמות י\"ז ע\"א). אחרי פטירת רב היה כפוף לר\"ה (חולין קי\"א ע\"ב, לגירסת הרא\"ש), וישב זמן מה לפני רב אסי מהוצל (יבמות ט\"ז ע\"ב). אחר פטירת ר\"ה היתה פומבדיתא לישיבה המרכזית והוא היה ראש הדור. בין תלמידיו המובהקים: רבה (עירובין י\"ז ע\"א), ור\u0027 יוסף (יבמות י\"ז ע\"א) ור\u0027 זירא (שם ע\"ח ע\"ב). הוא ור\u0027 עינא כונו: \"חריפי דפומבדיתא\" (סנהדרין י\"ז ע\"ב), עד שאמרו עליהם שיודעים להכניס פיל בנקב של מחט (ב\"מ ל\"ח ע\"ב). אביו של ר\u0027 יהודה היה חכם גדול, שאפילו שמואל היה קם בפניו (קידושין ל\"ג ע\"ב). ר\u0027 יהודה היה גדול מאביו (שם רש\"י). שמואל אמר עליו ש\"אין זה ילוד אשה\" [אלא מלאך] (נדה י\"ג ע\"א). כשהיה גוזר תענית בגלל עצירת גשמים וחולץ נעל אחת לאות אבל, מיד ירד גשם (תענית כ\"ד ע\"ב). היה בקי בהויות העולם והטבע (שבת ע\"ז ע\"ב). התנגד חריפות שתלמידי בבל יעזבוה ויעלו לא\"י (ברכות כ\"ד ע\"ב). היה גבה קומה מאד (נדה כ\"ד ע\"ב). לעת זקנתו כהו עיניו (גיטין י\"ט ע\"א). אחיו, רמי בר יחזקאל, היה אף הוא אמורא, וחלק עם אחיו ר\u0027 יהודה כמה פעמים (כתובות כ\"א ע\"א). על כסאו ישב תלמידו רבה בר נחמני (\"אגרת רב שרירא גאון\")."},{"i":1874,"n":"רב יהודה בר יצחק","l":"י","b":"מובא בבבלי (תענית ו\u0027 ע\"ב)."},{"i":1875,"n":"ר\u0027 יהודה בר ישמעאל","l":"י","b":"מובא בבבלי (חולין קי\"ח ע\"ב). אמורא שאין לקבוע את זמנו המדוייק. ניהל ישיבה והיו לו תלמידים (ירו\u0027, ברכות פ\"ה ה\"א). פעם נפלה לו גלימתו, ונחש שמרה (שם)."},{"i":1876,"n":"רבי יהודה בר ליואי","l":"י","b":"מובא בבבלי (שבת קי\"ג ע\"א), והוא כנראה ר\u0027 יהודה בן לוי."},{"i":1877,"n":"ר\u0027 יהודה בר לקרה","l":"י","b":"הוא ר\u0027 יהודה בר לקרח."},{"i":1878,"n":"ר\u0027 יהודה בר מנסיא","l":"י","b":"אמורא ארץ ישראלי בדור השני - השלישי. מובא בבבלי (ברכות י\"א ע\"א). אותה אימרה מובאת בשמו במקום אחר (מגילה י\"ד ע\"א), ושם הגירסא ר\u0027 יהודה בר מנשי. יתכן מאוד, שר\u0027 יודן בר מנשה (ירו\u0027, תענית רפ\"ז) הוא ר\u0027 יהודה בר מנסיא."},{"i":1879,"n":"ר\u0027 יהודה בר מספרתא","l":"י","b":"אמורא ארץ ישראלי בדור השני. ר\u0027 אלעאי מסר בשמו (סנהדרין מ\"ד ע\"א), ואולי הוא ר\u0027 יהודה בן ספרא."},{"i":1880,"n":"ר\u0027 יהודה בר מערבא","l":"י","b":"מובא בבבלי (סוטה מ\"א ע\"ב)."},{"i":1881,"n":"יהודה בר מרימר","l":"י","b":"אמורא בבלי בדור השביעי. חברם של מר בר רב אשי ורב אחא מדיפתי. שלושתם היו שקולים, ולא היה אחד גדול מחברו (ברכות מ\"ה ע\"ב)."},{"i":1882,"n":"ר\u0027 יהודה בר נחמיה","l":"י","b":"מובא בתנחומא (סוף תשא), והוא ר\u0027 יהודה בר נחמני."},{"i":1883,"n":"יהודה בר נחמן","l":"י","b":"מובא בירושלמי (סוכה פ\"א ה\"א), והוא ר\u0027 יהודה בר נחמני."},{"i":1884,"n":"יהודה בר נחמני","l":"י","b":"תנא בדור השלישי. נפטר בחיי ר\"ט ור\"ע, כעונש שהשיב על דברי ר\"ט (כנראה בלגלוג מסויים): \"א\"ל ר\"ע: \u0027יהודה צהבו פניך שהשבת את זקן, תמהני אם תאריך ימים\u0027\". ואמנם לא הוציא שנתו ונפטר לפני תום השנה (מנחות ס\"ח ע\"ב)."},{"i":1885,"n":"ר\u0027 יהודה בר נחמני","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. הוא וחברו ר\u0027 לוי היו דרשנים בבית מדרשו של רבי יוחנן (ירו\u0027, סוכה רפ\"ה). היה מתורגמנו של רבי שמעון בן לקיש (סנהדרין ז\u0027 ע\"ב). רבי שמעון בן לקיש הלך עמו לנחם אבלים ואמר לו: \"קום אימא מילתא\" (כתובות ח\u0027 ע\"ב)."},{"i":1886,"n":"ר\u0027 יהודה בר נריא","l":"י","b":"אמורא ארץ ישראלי בדור הראשון מרבותיו של רבי יהושע בן לוי (מד\u0027 קהלת פ\u0027 כי העושק)."},{"i":1887,"n":"יהודה בר נתן","l":"י","b":"מובא בבבלי (ברכות ס\u0027 ע\"א) שהלך אחר רב המנונא, ואין להכריע לאיזה רב המנונא הכוונה."},{"i":1888,"n":"ר\u0027 יהודה בר סיגנא","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. אמר בשם ר\u0027 אחא (איכ\"ר פ\"א - ל\"ט)."},{"i":1889,"n":"ר\u0027 יהודה בר ספרא","l":"י","b":"אמורא ארץ ישראלי בדור השני. ר\u0027 אלעאי מסר בשמו (פסחים ע\u0027 ע\"ב), ואולי הוא ר\u0027 יהודה בר מספרתא."},{"i":1890,"n":"ר\u0027 יהודה בר פזי דברדליה","l":"י","b":"מובא בירושלמי (שקלים ספ\"ז)."},{"i":1891,"n":"ר\u0027 יהודה בר פלמא","l":"י","b":"מובא בתנחומא (וירא - מ\"ה). ונראה שהוא ר\u0027 יודן בר פליא."},{"i":1892,"n":"ר\u0027 יהודה בר פפי","l":"י","b":"מובא בירושלמי (תענית פ\"ד ה\"א). וצ\"ל: ר\u0027 יהודה בר פזי."},{"i":1893,"n":"רב יהודה בר קזא","l":"י","b":"נראה שהוא אמורא בבלי שהיה לו בית מדרש. מובא בבבלי: \"אמר רב נחמן: \u0027תני רב יהודה בר קזא [פרש\"י: שם חכם] במתניתא דבי בר קזא\u0027\" (כתובות ק\"ד ע\"א)."},{"i":1894,"n":"רב יהודה בר שילא","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של רב אסי (זבחים כ\"ב ע\"א). הביא עמו לבבל מסורות מארץ ישראל, שמצינו: \"כי אתא רב יהודה בר שילא, אמר: \u0027אמרי במערבא\u0027\" (יבמות כ\"א ע\"ב). נראה כי המובא: \"אמר רב יהודה בר שילא, אמר רב אשי\" (נדה ס\"ג ע\"א), צ\"ל: רב אסי ולא רב אשי."},{"i":1895,"n":"רב יהודה בר שילת","l":"י","b":"מובא בבבלי (שבת קכ\"ו ע\"א), והוא ר\u0027 יהודה בר שילא."},{"i":1896,"n":"רב יהודה בר שלום","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי יוסי [חברו דר\u0027 יונה] (ירו\u0027, דמאי פ\"ו ה\"ב). חברו של רבי פנחס (תנחומא וארא ס\u0027 כ\"ב). חלק עם ר\u0027 מתניה (ירו\u0027, שבת פי\"ב ה\"ד) נמנה עם בעלי המדרש. בבבלי מובא פעם אחת: \"דרש ר\u0027 יהודה בר שלום: כשם שמזונותיו של אדם קצובין לו מר\"ה, כן חסרונותיו וכו\u0027\" (ב\"ב י\u0027 ע\"א). ואולי הוא הנקרא ר\u0027 יהודה הלוי בר שלום (מד\u0027 תהלים פקי\"ט - ב\u0027). היה דיין בעירו (ירו\u0027, תרומות פ\"ה סה\"ד)."},{"i":1897,"n":"יהודה בר שמואל","l":"י","b":"מובא בבמד\"ר (פי\"ב - ג\u0027) שראה קטב מרירי ומת."},{"i":1898,"n":"רבי יהודה בר שמואל","l":"י","b":"מובא (שבת ל\"ח ע\"א). יתכן שהוא רבי יהודה, בנו של שמואל בר שילת."},{"i":1899,"n":"רבי יהודה ברבי","l":"י","b":"מובא בבבלי: \"א\"ר יוסי: \u0027ומודה לי רבי יהודה ברבי\u0027\" (מנחות ל\"ד ע\"ב), ופרש\"י: \"יהודה החכם\", וא\"כ, סבר שזה רבי יהודה התנא בר פלוגתיה דר\u0027 יוסי."},{"i":1900,"n":"רבי יהודה ברבי שמעון","l":"י","b":"אמורא ארץ ישראלי בדור המעבר בין התנאים לאמוראים. תלמידו של התנא רבי אלעזר בר שמעון (חולין מ\"ח ע\"א). רבו שאינו מובהק של רבי יוחנן (ב\"ב קי\"ד ע\"ב - רשב\"ם). ר\u0027 יוחנן שלח אליו שאלה (חולין שם)."},{"i":1901,"n":"רב יהודה בריה דרב יהושע","l":"י","b":"מובא בבבלי (ע\"ז מ\"ג ע\"ב), והוא ט\"ס וצ\"ל: רב הונא בריה דרב יהושע. וכן מוכח מרש\"י (ע\"ז מ\"ב ע\"ב ד\"ה: \"וכדרב הונא בריה דרב יהושע\"), וכן גירסת הרי\"ף והרא\"ש."},{"i":1902,"n":"ר\u0027 יהודה בריה דר\u0027 שמעון בן פזי","l":"י","b":"נראה אולי שהוא זהה לר\u0027 יהודה בן פזי."},{"i":1903,"n":"ר\u0027 יהודה בר\u0027 אלעזר","l":"י","b":"מובא בויק\"ר (פכ\"א - ז\u0027)."},{"i":1904,"n":"ר\u0027 יהודה בר\u0027 יעקב","l":"י","b":"מובא ב\"זהר חדש\" (בראשית פסוק תוצא הארץ)."},{"i":1905,"n":"ר\u0027 יהודה בר\u0027 סיחון","l":"י","b":"מובא בב\"ר (פצ\"ד - ט\u0027) והוא ט\"ס וצ\"ל: ר\u0027 יהודה בר סימון."},{"i":1906,"n":"ר\u0027 יהודה בר\u0027 סימון","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. בנו של האמורא ר\u0027 סימון (ירו\u0027, מו\"ק פ\"ג סה\"ה). מסר בשם ר\u0027 יהושע בן לוי (ויק\"ר פי\"ב פסוק ויותר) ובשם רבי יוחנן (תנחומא נשא י\"ט). משמו מסרו ר\u0027 עזריה (ב\"ר פ\"ו - ה\u0027). ועוד. ר\u0027 ירמיה ור\u0027 יוסי שאלו אצלו ממנהגי אביו (ירו\u0027, ברכות פ\"ד ה\"א). התחתן בבית הנשיא (ירו\u0027, שבת פי\"ב ה\"ג)."},{"i":1907,"n":"יהודה ב\"ר","l":"י","b":"מובא בירושלמי (שבת פ\"ז ה\"ב). והוא יהודה בר ריבי, כלומר יהודה בנו של רבי חייא (רבי חייא נקרא \"בריבי\" שפירושו: גדול בדורו)."},{"i":1908,"n":"ר\u0027 יהודה גוזריא","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. מסר בשם ר\u0027 אחא (ירו\u0027, ר\"ה פ\"ג ה\"ט). נראה שמלאכתו היתה מוהל, כמו שפירש רש\"י (שבת ק\"ל ע\"ב ד\"ה): \"ר\u0027 יהודה הגוזר את התינוקות\"."},{"i":1909,"n":"ר\u0027 יהודה גלוסטרא","l":"י","b":"מובא בבבלי (ברכות כ\"ב סע\"א), ואין להכריע אם היה תנא או אמורא. מהלשון נראה כתנא בדורו של רבי עקיבא. \"יוחסין\" כתב שהיה אמורא מתלמידיו של רבי יוחנן, ותמה עליו \"סה\"ד\" וכתב: \"וצ\"ע מנ\"ל שיהיה תלמיד רבי יוחנן, וה\u0027שארית יוסף\u0027 לא הביאו בתלמידיו\"."},{"i":1910,"n":"יהודה גרוגרות","l":"י","b":"מובא בתוספות ישנים (יומא ע\"ח ע\"א), והוא יהודה בר גרוגרות."},{"i":1911,"n":"ר\u0027 יהודה דסכנין","l":"י","b":"מובא בתנחומא (הישן, עקב). ואולי צ\"ל: ר\u0027 יהושע דסכנין."},{"i":1912,"n":"ר\u0027 יהודה דציפורן","l":"י","b":"מובא במ\"ר (פט\"ז - כ\"ד), ואולי ט\"ס וצ\"ל: ר\u0027 הונא דציפורן."},{"i":1913,"n":"ר\u0027 יהודה הגוזר","l":"י","b":"תנא - אמורא בדור המעבר שבין התנאים לאמוראים. רבי אושעיא (בעל הברייתות) סיפר ששאל ממנו הלכה (שבת ק\"ל ע\"ב). היה מוהל."},{"i":1914,"n":"רב יהודה הינדואה","l":"י","b":"אמורא בבלי בדור הששי. היה גר ללא יורשים (קידושין כ\"ב ע\"ב). ומר זוטרא ביקרו בעת שמת, וזכה בממונו (שם). מובא ממנו מעשה מופלא שסיפר שראה על הים (ב\"ב ע\"ד ע\"ב)."},{"i":1915,"n":"רבי יהודה הכהן","l":"י","b":"תנא בדור השלישי. מובא פעם אחת, שהעיד על הלכה יחד עם רבי יהודה בן בבא (עדיות פ\"ח מ\"ב)."},{"i":1916,"n":"רבי יהודה הכהן בר אבין","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. תלמידו של רב ביבי (מדרש תהלים פ\"ב)."},{"i":1917,"n":"ר\u0027 יהודה הלוי","l":"י","b":"מובא באגדה, ונראה שהוא ר\u0027 יהודה בר שלום."},{"i":1918,"n":"ר\u0027 יהודה הלוי בר שלום","l":"י","b":"מובא במדרש תהלים (פקי\"ט - ב\u0027), ואולי הוא ר\u0027 יהודה בר שלום. ו\"סה\"ד\" חילקו לשנים."},{"i":1919,"n":"רבי יהודה הנחתום","l":"י","b":"תנא בדור השלישי בדורו של ר\"ע (ר\"ה כ\"ב ע\"א). היה מעשרה הרוגי מלכות. יש אומרים שאלישע בן אבויה שראה את לשונו נתונה בפי כלב, אמר: \"זו תורה וזו שכרה\" ויצא לתרבות רעה (ירו\u0027, חגיגה פ\"ב ה\"א)."},{"i":1920,"n":"רבי יהודה הנשיא","l":"י","b":"נשיא וראש הדור כולו, בדור החמישי לתנאים. דור שביעי להלל הזקן. ידוע בשם \"רבי\" (כתובות ק\"ג ע\"ב), בשם \"רבינו הקדוש\" (שבת קי\"ח ע\"ב), ובשם \"רבי יהודה הנשיא\" (שבת ל\"ה ע\"ב). נולד כשנפטר רבי עקיבא (קידושין ע\"ב ע\"ב). מושבו היה בית שערים, שם היתה ישיבתו (סנהדרין ל\"ב ע\"ב). בשבע עשרה שנותיו האחרונות גר בציפורי (כתובות שם). ערך וסידר את המשנה (יבמות ס\"ד ע\"ב): \"מכדי מתניתין מאן תיקן? רבי\". \"סה\"ד\" כתב: \"וחתם שמו בראש חיבורו מאימתי גימטריא: אני יהודה קדוש\" (כ\"כ בהקדמה לס\u0027 באר אברהם בשם בעל מגלה עמוקות). קיבל תורה מחמשת תלמידי ר\"ע הגדולים: רבי יוסי (נדה ס\"ח ע\"ב), רבי מאיר (עירובין י\"ג ע\"ב), רבי אלעזר בן שמוע (שם י\"ג ע\"א) ורבי שמעון בן יוחאי (שבת קמ\"ז ע\"ב). מרבי יהודה למד עוד בטרם היה בר מצוה (מגילה כ\u0027 ע\"א) וכן מר\u0027 יעקב בר קרשאי (ירו\u0027, פסחים פ\"י ה\"א). למד יחד עם חברו רבי אלעזר בר\u0027 שמעון, לפני אביו רבן שמעון בן גמליאל ור\u0027 יהושע בן קרחה (ב\"מ פ\"ד ע\"ב). תלמידיו של רבי היו רבים ומהם היו ראשי דור הראשון לאמוראים, כגון רב (חולין קל\"ז ע\"ב), רבי יוחנן (שם, ושם נ\"ד ע\"א), לוי (סנהדרין י\"ז ע\"ב) ור\u0027 חנינא בר חמא (ע\"ז י\"ט ע\"ב). היה משכמו ומעלה (נדה כ\"ד ע\"ב). עשיר מופלג (ב\"מ פ\"ה ע\"א). עליו נאמר: \"מימות משה ועד רבי לא מצינו תורה וגדולה במקום אחד\" (גיטין נ\"ט ע\"א). הוציא 021 אלף ממון לבטל גזירת הקרבת שור פטום ביום אידם (ע\"ז ט\"ז ע\"א). בשנות בצורת פתח אוצרותיו לעניים (ב\"ב ח\u0027 ע\"א). כשנפטר זקף עשר אצבעותיו ואמר שלא נהנה אפילו באצבע קטנה (כתובות ק\"ד ע\"א). היה ישן ביום לא יותר ממשך ששים נשימות (סוכה כ\"ו ע\"ב). היה לו תדיר גילוי אליהו (ב\"מ פ\"ה ע\"א). קיסר רומי אנטנינוס היה ידידו בנפש ולמד תורה עמו (ע\"ז י\u0027 ע\"ב). לאחר פטירתו מילא בנו ר\"ג את מקומו בנשיאות, ולו מסר סדרי הנשיאות (כתובות ק\"ג ע\"א). כשמת רבי בטלה ענוה ויראת חטא והוכפלו הצרות (שם)."},{"i":1921,"n":"ר\u0027 יהודה הסבר","l":"י","b":"תנא שאין לקבוע את זמנו המדוייק. מובא בבבלי (עירובין ע\"ב ע\"ב). רש\"י ותוספות חולקים במשמעות השם."},{"i":1922,"n":"ר\u0027 יהודה הענתותי","l":"י","b":"\"סה\"ד\" מביא ממנו מעשה נורא וכיצד קרה לו נס גדול וניצל. לדבריו חי בדור הרביעי לתנאים, בזמנו של רבי מאיר ואינו מוזכר בשום מקום בש\"ס או במדרשים."},{"i":1923,"n":"ר\u0027 יהודה חייטא","l":"י","b":"סופר מומחה בדור החמישי לתנאים. כתב ספר תהלים ורבי שבח את כתיבתו (ב\"ב קס\"ד ע\"ב)."},{"i":1924,"n":"רב יהודה מדאסקרתא","l":"י","b":"אמורא בבלי בדור הרביעי - החמישי. הקשה הרבה לרבא (יבמות פ\"ז ע\"ב). רב פפא היה תלמידו (נדה ל\"ט ע\"א)."},{"i":1925,"n":"רב יהודה מדפתי","l":"י","b":"אמורא בבלי בדור החמישי. מרבותיו של רבינא (ברכות כ\"ה ע\"א), וגירסת \"דק\"ס\": \"ר\u0027 ירמיה מדפתי\"."},{"i":1926,"n":"רב יהודה מהגרוניא","l":"י","b":"אמורא בבלי בדור השני. נראה, שהיה תלמידו של שמואל (ע\"ז ל\"ט ע\"א). חנן חייטא שאל ממנו, וענה לו \"הכי אמר שמואל\" (שם)."},{"i":1927,"n":"ר\u0027 יהודה מנשייא בר מנשה","l":"י","b":"מובא בירושלמי (שבת פ\"ו רפ\"ה), ואפשר שצ\"ל: ר\u0027 יהודה בר מנשיה או בר מנשה, וערבוב גירסאות יש כאן. ע\"ע ר\u0027 יהודה בר מנסיא."},{"i":1928,"n":"רב יהודה מסורא","l":"י","b":"אמורא שאין לקבוע את זמנו המדוייק. מובא בבבלי (ב\"מ פ\"ט ע\"א)."},{"i":1929,"n":"יהודה מר בר מרימר","l":"י","b":"אמורא בבלי בדור החמישי. תלמידו של רבא. חברו של רב פפא (כתובות פ\u0027 ע\"ב). היה עם ר\"פ, כשר\"פ הלך לכתוב כתובה לנשואי בנו ור\"פ כיבד את דבריו (כתובות נ\"ב ע\"ב)."},{"i":1930,"n":"רבי יהודה נשיאה א\u0027","l":"י","b":"נשיא וראש הדור וריש מתיבתא, בדור הראשון לאמוראי ארץ ישראל. דור תשיעי להלל ונכדו של רבי יהודה הנשיא. \"נשיאה\" הוא בארמית מקביל ל\"נשיא\" בעברית. (ע\"ז ל\"ו ע\"א תד\"ה: אשר). מוזכר במשנה שהוא ובית דינו התירו השמן (ע\"ז ל\"ה ע\"ב). בנו ותלמידו של רבן גמליאל ג\u0027 (ירו\u0027, ביצה פ\"א הי\"א). ר\"ל היה תלמידו המובהק (נזיר כ\u0027 ע\"ב). גדולי דור הראשון היו חבריו: ר\u0027 חנינא (ירו\u0027, סנהדרין ספ\"ב), ר\u0027 הושעיא (מגילה ז\u0027 ע\"ב) ור\u0027 יונתן (ירו\u0027, קידושין פ\"ג הי\"ב). ר\u0027 יהודה נשיאה היה אחרון הנשיאים שגם החזיק בנזר התורה והיה גדול בתורה (ירו\u0027, ע\"ז פ\"א ה\"א). מוזכר יחד עם אחיו הלל (פסחים נ\"א ע\"א). הצטיין בענוה ובפשטות (ירו\u0027, סנהדרין שם), אך בתוקף סמכותו נהג נשיאותו בתקיפות (נדה נ\"ב ע\"א)."},{"i":1931,"n":"ר\u0027 יהודה נשיאה ב\u0027","l":"י","b":"נשיא בדור השני - השלישי לאמוראי ארץ ישראל. דור אחד עשר להלל. אביו רבן גמליאל ד\u0027 לא נזכר בתלמוד בבלי. היה תלמידו של רבי יוחנן (ר\"ה כ\u0027 ע\"א). אחרי פטירת ר\u0027 יוחנן ישב לפני ר\u0027 אמי (מנחות כ\"ט ע\"ב). נראה שהמעשה שקיסר דיקליטיינוס קרא לנשיא ישראל לפתע (ירו\u0027, תרומות ספ\"ח), מתייחס אליו לפי סדר הזמנים, כי דיקליטיינוס נתקסר בשנת 482 ור\u0027 יוחנן נפטר בשנת 972."},{"i":1932,"n":"ר\u0027 יהודה נשיאה ג\u0027","l":"י","b":"נשיא בדור השלישי - הרביעי לאמוראי ארץ ישראל. דור י\"ג להלל הזקן. בזמנו היה ר\u0027 ירמיה (ירו\u0027, מגילה פ\"ג ה\"ב). אביו ר\u0027 גמליאל ה\u0027, היה תלמידו של ר\u0027 אבהו (ירו\u0027, ע\"ז פ\"א ה\"א), והוא עצמו זכה להעמיד בן גדול ושמו הלל שחיבר את הלוח עד ביאת המשיח."},{"i":1933,"n":"ר\u0027 יהודה קלוסטרא","l":"י","b":"מובא בבבלי (ברכות כ\"ב ע\"א). \"סה\"ד\" כתב שה\"יוחסין\" מביאו בין תלמידי ר\u0027 יוחנן, ותמה מנ\"ל לו שהיה תלמיד ר\u0027 יוחנן."},{"i":1934,"n":"רב יהושע","l":"י","b":"מובא בבבלי: \"אמר רב יהושע: דרש רבא\" (פסחים נ\"ג ע\"ב), ולא ברור מי הוא רב יהושע זה. \"סה\"ד\" מביא: \"ר\u0027 יהושע ור\u0027 נחמיה בש\"ר אחא\" (מדרש ריש פתיחתא דאיכה) וגם הוא תמה וכותב: \"ר\u0027 יהושע זה לא ידעתי מי הוא\"."},{"i":1935,"n":"רבי יהושע","l":"י","b":"הוא רבי יהושע בן חנניה."},{"i":1936,"n":"ר\u0027 יהושע אונייא","l":"י","b":"אמורא ארץ ישראלי בדור השני - השלישי. מ\"התנאים\" שוני הברייתות. ר\u0027 שמואל בר יצחק מסר קטע אחד מהברייתא ששנה (ירו\u0027, פסחים פ\"ג ה\"א), ושם משובש שמו לר\u0027 יושוע אונייה."},{"i":1937,"n":"יהושע איש עוזי","l":"י","b":"תנא שאין לקבוע את זמנו המדוייק. מובא בבבלי (נדרים ל\"ח ע\"ב)."},{"i":1938,"n":"ר\u0027 יהושע בן אביין","l":"י","b":"מובא בירושלמי (יומא פ\"ג ה\"ה), וצ\"ל: יהושע בן אבין."},{"i":1939,"n":"ר\u0027 יהושע בן אבין","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. מסר בשם ר\u0027 סימון (ירו\u0027, יומא פ\"ג סה\"ה). ור\u0027 מנחמא מסר משמו (רו\"ר פ\"ג - י\"ט)."},{"i":1940,"n":"ר\u0027 יהושע בן אבירם","l":"י","b":"מובא באס\"ר (פ\"ה - ד\u0027), והגירסא במדרש שמואל (פי\"ג - ה\u0027): ר\u0027 יהושע בריה דר\u0027 בירי."},{"i":1941,"n":"ר\u0027 יהושע בן אלישע","l":"י","b":"תנא מראשי דורו: \"דתניא מעשה שמת וכו\u0027 ושאל את רבי יהושע בן אלישע וד\u0027 זקנים שעמו\" (נזיר מ\"ד ע\"א)."},{"i":1942,"n":"ר\u0027 יהושע בן ביתות","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. מסר בשם ר\u0027 יהודה בר סימון (ב\"ר פפ\"ד - י\"ח)."},{"i":1943,"n":"ר\u0027 יהושע בן בתירא","l":"י","b":"תנא בדור השלישי. זכה לראות את הבית (מנחות ק\"ג ע\"ב). לפני שסמכוהו נקרא \"בן בתירא\", ולאחר שסמכוהו קראו לו: \"ר\u0027 יהושע בן בתירא\" (תענית ג\u0027 ע\"א). ר\u0027 יהודה [תלמידו של ר\"ע] קיבל ממנו (שם)."},{"i":1944,"n":"יהושע בן גמלא","l":"י","b":"כהן גדול בזמן בית שני (יומא י\"ח ע\"א). תקנתו מוזכרת בתלמוד: \"דאמר רב יהודה אמר רב: \u0027ברם, זכור אותו האיש לטובה, ויהושע בן גמלא שמו, שאלמלא הוא נשתכחה תורה מישראל\u0027\" (ב\"ב כ\"א ע\"א)."},{"i":1945,"n":"רבי יהושע בן הורקנוס","l":"י","b":"תנא בדור הרביעי. תלמידו של רבי עקיבא (סוטה כ\"ז ע\"ב רש\"י)."},{"i":1946,"n":"ר\u0027 יהושע בן זירוז","l":"י","b":"תנא בדור הרביעי. בן חמו (גיסו) ותלמידו של רבי מאיר (חולין ו\u0027 ע\"ב). פעם העיד לפני רבי על רבי מאיר, שאכל עלה של ירק בבית שאן ללא הפרשת מעשר, והתיר רבי על ידו את בית שאן כולה (שם)."},{"i":1947,"n":"יהושע בן זריז","l":"י","b":"מובא בירושלמי (דמאי פ\"ב ה\"א), והוא יהושע בן זירוז."},{"i":1948,"n":"רבי יהושע בן חנניה","l":"י","b":"מראשי התנאים בדור השני. והוא רבי יהושע סתם במשנה (נזיר נ\"ו ע\"ב רש\"י). היתה לו ישיבה בפקיעין (סנהדרין ל\"ב ע\"ב). עליו אמרו: \"אשרי יולדתו\" (אבות פ\"ב מ\"ח). היה משבט לוי, ועוד זכה לשמש במקדש עם המשוררים (ערכין י\"א ע\"ב). כשרבן גמליאל נתמנה לנשיא, שימש כאב בית דין על ידו (ב\"ק ע\"ד ע\"ב). מתלמידיו המובהקים ביותר של רבי יוחנן בן זכאי (גיטין נ\"ו ע\"א). היה חברו הגדול של רבי אליעזר - מחלוקתם מובאת הרבה בש\"ס. יחד הוציאו את רבם ר\u0027 יוחנן בן זכאי מירושלים הנצורה (שם). אחר פטירתו של רבי אליעזר, כשבאו חכמים להשיב על דברי רבי אליעזר, לא הניחם ר\u0027 יהושע ואמר: \"אין משיבין את הארי לאחר מיתה\" (גיטין פ\"ג ע\"א). היה במחלוקת הגדולה של רבי אליעזר נגד החכמים בענין תנור של עכנאי, כשיצאה בת קול ואמרה: \"הלכה כרבי אליעזר בכל מקום, עמד רבי יהושע על רגליו ואמר: לא בשמים היא... אין אנו משגיחים בבת קול\". ולבסוף נידו את רבי אליעזר (ב\"מ נ\"ט ע\"ב). וכשפגע רבן גמליאל (דיבנה) כמה פעמים בכבודו של רבי יהושע, הורידוהו מנשיאותו ומינו את רבי אלעזר בן עזריה במקומו (ברכות כ\"ז ע\"ב). בין תלמידיו המובהקים היה רבי עקיבא (שם ס\"ב ע\"א), שהיה אח\"כ תלמיד חבר שלו (מסכת כלה רפ\"ב). וכן היה תלמידו ר\u0027 ישמעאל (ע\"ז כ\"ט ע\"ב), ואת ר\u0027 ישמעאל זה פדה בממון רב מבית האסורים ברומי אחר החורבן (גיטין נ\"ח ע\"ב). היה מחכמי הסנהדרין שידע לשונות רבים (סנהדרין י\"ז ע\"ב). היה לו ידע רב בתכונה (הוריות י\u0027 ע\"א). היה חכם מופלג והצטיין בויכוחים עם מינים (חגיגה ה\u0027 ע\"ב) עם קיסר רומי (חולין נ\"ט ע\"ב) ועם חכמי אתונא (בכורות ח\u0027 ע\"ב), ואת כולם ניצח. ומשמת אמרו עליו: \"בטלה עצה ומחשבה\" (סוף סוטה). אמר: \"מימי לא נצחני אדם חוץ מאשה תינוק ותינוקת\" (עירובין נ\"ג ע\"ב). היה עני גדול (ברכות כ\"ח ע\"א). האריך ימים והגיע לזקנה מופלגת (שבת קנ\"ב ע\"א)."},{"i":1949,"n":"ר\u0027 יהושע בן יאיר","l":"י","b":"מובא בירושלמי (תענית פ\"ג ה\"ד). אמר בשם ר\u0027 פנחס בן יאיר."},{"i":1950,"n":"רבי יהושע בן כפיסאי","l":"י","b":"תנא בדור השלישי - הרביעי. חתנו של רבי עקיבא. האריך ימים ודיבר עם רבי (שבת קמ\"ז ע\"א). העיד על מה שראה ממעשיהם של רבן גמליאל ואונקלוס הגר (תוספתא מקואות פ\"ו ג\u0027). רבן שמעון בן גמליאל מסר בשמו (ע\"ז ל\"ב ע\"ב). שם אביו נשתבש לכמה אופנים: קבסאי, קבוסיו, קבסוי, קפוסאי, קפוצאי."},{"i":1951,"n":"רבי יהושע בן לוי","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. היה גם מגדולי חכמי האגדה (ב\"ק נ\"ה ע\"א). מושבו היה בדרום (איכ\"ר פ\"ג - ו\u0027). תלמידם של רבי אלעזר הקפר (ע\"ז מ\"ג ע\"א) ורבי יהודה בן פדיה (תנחומא וארא ב\u0027). מסר הרבה גם בשם בר קפרא (תענית כ\"ו ע\"ב). ומשמע שהיה גם תלמידו של רבי (שבת מ\"ו ע\"א). בין תלמידיו הרבים היו רבי יוחנן (סוכה ל\"ב ע\"ב), רבי אלעזר (ברכות י\"ט ע\"א) ואף רבי חייא בר אבא (ירו\u0027, שבת פ\"א ה\"ב). היה חסיד מופלג והיה מיחידי סגולה בכל הדורות שלא טעם טעם מיתה וזכה להכנס חי לגן עדן (כתובות ע\"ז ע\"ב). אליהו הנביא נגלה לו תדיר (סנהדרין צ\"ח ע\"א), וזכה לדבר עם משיח צדקנו (שם). פניו היו כפני מלאך (ירו\u0027, ברכות פ\"ה ה\"א). יצג את היהודים בפני המלכות (שם). מאמר אחד שלו זכה להכנס למשנה (בסוף מסכת עוקצין) ומשמש חתימה לששה סדרי משנה: \"עתיד הקב\"ה להנחיל לכל צדיק וצדיק וכו\u0027\"."},{"i":1952,"n":"ר\u0027 יהושע בן לוי בר שלום","l":"י","b":"מובא בויק\"ר (פט\"ו - ט\"ז)."},{"i":1953,"n":"ר\u0027 יהושע בן לקיש","l":"י","b":"מובא בתוספתא (סנהדרין פ\"א), ונראה שצ\"ל: ר\u0027 יהודה בן לקיש."},{"i":1954,"n":"רבי יהושע בן ממל","l":"י","b":"תנא בדור השלישי. מסר בשם רבי יהושע (נזיר נ\"ו ע\"ב). ר\"מ אמר עליו: \"בעל הלכות היה\" (תוספתא נזיר פ\"ה א\u0027)."},{"i":1955,"n":"רבי יהושע בן מתיא","l":"י","b":"תנא בדור הרביעי. יתכן שהיה תלמידו של רבי ישמעאל: \"שלשה דברים אמרו לפני רבי ישמעאל ולא אמר בהם איסור ולא היתר, ופירשו ר\u0027 יהושע בן מתיא\" (עדיות פ\"ב מ\"ה)."},{"i":1956,"n":"רבי יהושע בן עוזאה","l":"י","b":"מובא בבבלי (יומא מ\"ז ע\"ב). \"אמר רבי יוחנן: הדר פשט\u0027 יהושע בן עוזאה\"."},{"i":1957,"n":"ר\u0027 יהושע בן פדיה","l":"י","b":"כך מביא \"סה\"ד\" ממדרש משלי (פ\"ו), ואולי ט\"ס שם."},{"i":1958,"n":"יהושע בן פרחיה","l":"י","b":"היה נשיא (חגיגה ט\"ז ע\"ב). הוא וחברו ניתאי הארבלי היו השני בחמשת ה\"זוגות\" בזמן הבית, לפני התחלת תקופת התנאים (אבות פ\"א מ\"ו). חי שלושה דורות לפני הלל הזקן. היה תלמידם של יוסי בן יועזר איש צרידה ויוסי בן יוחנן איש ירושלים, ורבם של יהודה בן טבאי ושמעון בן שטח (שם). בימיו היה יוחנן כהן גדול שנעשה צדוקי והרג לחכמי ישראל (קידושין ס\"ו ע\"א), והוא ברח לאלכסנדריה של מצרים (סוטה מ\"ז ע\"א). מסופר (שם לפי הגירסא בדפוסים ישנים) שדחה בשתי ידיו לאחד מתלמידיו שיצא לתרבות רעה, והיו שסברו שזה ישו הנוצרי אך נראה שהיה מסית ומדיח אחר, כי יהושע בן פרחיה חי שני דורות לפני ישו הנוצרי."},{"i":1959,"n":"רבי יהושע בן פתייה","l":"י","b":"מובא בירושלמי (שקלים פ\"ג ה\"ב: שם פ\"ח ה\"א)."},{"i":1960,"n":"ר\u0027 יהושע בן פתר ראש","l":"י","b":"תנא בדור הרביעי - החמישי. תלמידו של רבי מאיר. ורבי אלעזר מספר שראהו דן לפני רבי מאיר בהלכה (נזיר נ\"ו ע\"ב). רש\"י כתב: בן פתר ראש \"כך שמו\" ותוספות כתבו: בן פתר ראש \"כך שם אביו\"."},{"i":1961,"n":"ר\u0027 יהושע בן קבוסיו","l":"י","b":"מובא בתוספתא (סוף מעשרות), והוא ר\u0027 יהושע בן כפוסאי."},{"i":1962,"n":"ר\u0027 יהושע בן קבסוי","l":"י","b":"מובא בירושלמי (דמאי פ\"ג ה\"ד), והוא ר\u0027 יהושע בן כפוסאי."},{"i":1963,"n":"ר\u0027 יהושע בן קפוסאי","l":"י","b":"מובא בבבלי (בכורות ל\"ה ע\"ב), והוא ר\u0027 יהושע בן כפוסאי."},{"i":1964,"n":"ר\u0027 יהושע בן קפוצאי","l":"י","b":"מובא בבבלי (בכורות ל\"ט ע\"א), והוא ר\u0027 יהושע בן כפוסאי."},{"i":1965,"n":"רבי יהושע בן קרחה","l":"י","b":"תנא בדור הרביעי. לדעתו של רבנו גרשום ורש\"י (בכורות נ\"ח ע\"א) היה בנו של רבי עקיבא. לדעתו של רש\"י היה תלמידו של אביו רבי עקיבא (שבועות ו\u0027 ע\"א). תוס\u0027 סוברים (בכורות נ\"ח ע\"א) שרבי עקיבא לא היה אביו. היה חברו של רבן שמעון בן גמליאל (אביו של רבי) ושניהם היו רבותיהם של רבי אלעזר בר שמעון ורבי (ב\"מ פ\"ד ע\"ב). התוכח עם המינים (שבת קנ\"ב ע\"א) והשיב להם תשובות ניצחות (ויק\"ר פ\"ד - ו\u0027). זכה לאריכות ימים מופלגת ורבי שאלו: \"במה הארכת ימים\" (מגילה כ\"ח ע\"א). בשעת פטירתו בירך את רבי: \"יהי רצון שתגיע לחצי ימי\" (שם)."},{"i":1966,"n":"רבי יהושע בנו של רבי עקיבא","l":"י","b":"מובא בבבלי (שבועות ו\u0027 ע\"א) ופרש\"י: הוא יהושע בן קרחה. ומובא: \"ז\u0027 דברים צוה ר\"ע את ר\u0027 יהושע בנו\" (פסחים קי\"ב ע\"א). תוס\u0027 חולקים על רש\"י וסוברים שרבי יהושע בן קרחה אינו בנו של רבי עקיבא (בכורות נ\"ח ע\"א)."},{"i":1967,"n":"רבי יהושע בר אבא","l":"י","b":"אמורא בדור השלישי. נראה שהיה ארץ ישראלי שקיבל סמיכה וירד לבבל, ולכן נקרא רבי ולא רב."},{"i":1968,"n":"ר\u0027 יהושע בר בנימין בר לוי","l":"י","b":"מובא בשהש\"ר (ספ\"ד)."},{"i":1969,"n":"ר\u0027 יהושע בר זידל","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. \"כשחלה ר\u0027 ינאי בר ישמעאל ובאו לבקרו ר\"ג ור\u0027 הושעיא ור\u0027 חנינא ור\u0027 אבין בר כהנא, מצאו שם את ר\u0027 יהושע בן זידל ואמרו אליו: \u0027הרי בעל השמועה והרי בעל העובדא\u0027\" (ירו\u0027, תרומות פ\"ח ה\"ג)."},{"i":1970,"n":"ר\u0027 יהושע בר מנחמה","l":"י","b":"מובא בב\"ר (פנ\"ג - י\u0027)."},{"i":1971,"n":"רבי יהושע בר נחמיה","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. מסר בשם ר\u0027 חנינא בר יצחק (ב\"ר פ\"ח - י\"א). ר\u0027 מנחמא מסר בשמו (ויק\"ר פ\"כ - י\u0027)."},{"i":1972,"n":"ר\u0027 יהושע בר נחמן","l":"י","b":"מובא בויק\"ר (פ\"ב - ג\u0027), ונראה אולי שהוא ר\u0027 יהושע בר נחמיה."},{"i":1973,"n":"ר\u0027 יהושע בר סימון","l":"י","b":"מובא בויק\"ר (פל\"ד - ח\u0027). מסר בשם לוי. וצ\"ל: ר\u0027 יהודה בר סימון."},{"i":1974,"n":"רבי יהושע בריה דרב אידי","l":"י","b":"אמורא בבלי בדור החמישי - הששי. היה מגדולי דורו. מצינו שרב אשי הקשה לו (יבמות ל\"ו ע\"ב). לפנינו רב הושעיא, אך רש\"י (יבמות ל\"ד ע\"א ד\"ה: הכא) גרס ר\u0027 יהושע בריה דרב אידי. כשביקר את רב אשי כבדו בעיגלא תילתא (שבת י\"א ע\"א). כשהלך לבקר את רב כהנא [רבו של ר\u0027 אשי], מצא שכבר נפטר (פסחים ג\u0027 ע\"ב). אביו ר\u0027 אידי היה נקרא רב אידי בר אבין, ונשא כהנת והיו לו שני בנים חכמים: רב שישא ורב יהושע (פסחים מ\"ט ע\"א)."},{"i":1975,"n":"ר\u0027 יהושע בריה דרב חננאל","l":"י","b":"מובא בירושלמי (מגילה פ\"א ה\"ט), ואם נאמר שהוא בנו של רב חננאל, תלמידו דרב, הרי היה אמורא בבלי בדור השלישי."},{"i":1976,"n":"ר\u0027 יהושע בריה דר\u0027 בירי","l":"י","b":"מובא במדרש שמואל (פי\"ג - ה). והגירסא במקום אחר (אס\"ר פ\"ה - ד\u0027): ר\u0027 יהושע בן אבירם."},{"i":1977,"n":"ר\u0027 יהושע בריה דר\u0027 טומי","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. חברו של ר\u0027 בורקי, ואת שניהם כינה ר\u0027 יצחק בן אלעזר \"עדה קדושה\", משום שהיו משלשין את היום שליש לתורה, שליש לתפילה ושליש למלאכה (קה\"ר פ\"ט - ט\u0027)."},{"i":1978,"n":"ר\u0027 יהושע בריה דר\u0027 תנחום בר חייא דכפר אגין","l":"י","b":"מובא ב\"ילקוט\" (ישעיה רמז שיז)."},{"i":1979,"n":"ר\u0027 יהושע בריה דר\u0027 תנחום דכפר חנון","l":"י","b":"מובא בקה\"ר (פ\"ג - ב\u0027)."},{"i":1980,"n":"רבי יהושע דיימא","l":"י","b":"מובא בירושלמי פעם אחת: \"בעא קומי רבי יונה\" (שבועות פ\"ו ה\"א) ונראה לי שט\"ס הוא, וצ\"ל: רבי יהושע דרומיא."},{"i":1981,"n":"רבי יהושע דסכנין","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. תלמידו של רבי לוי (ירו\u0027, ברכות פ\"ד ה\"א). בשמו מסרו רבי אבא בריה דרבי פפי (ירו\u0027, ברכות פ\"ד ה\"א), ר\u0027 יוסי ממלחייא (פסיקתא דר\u0027 כהנא ל\"א א\u0027), רבי מני דשאב (שם ל\"ח א\u0027), ור\u0027 יוסטא בר שונם (תנחומא בובר ויצא סי\u0027 ו\u0027)."},{"i":1982,"n":"ר\u0027 יהושע דרומיא","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. תלמידם של רבי יונה (ירו\u0027, סוכה ספ\"ד) ושל רבי יוסי (ירו\u0027, שבת פ\"י ה\"ה). מסר גם בשם ר\u0027 אחא (ירו\u0027, שבת פ\"י ה\"ה)."},{"i":1983,"n":"רבי יהושע הגרסי","l":"י","b":"תנא בדור הרביעי. מתלמידיו המובהקים של רבי עקיבא ומשרתו הנאמן עד יום מותו. כשהיה ר\"ע בבית האסורים עמד רבי יהושע הגרסי לשרתו (עירובין כ\"א ע\"ב), ומסופר: \"ומעשה בר\"ע שהיה חבוש בבית האסורים ורבי יהושע הגרסי תלמידו היה משמשו וכו\u0027, נפטר ממנו והלך לביתו. בא אליהו ועמד על פתח ביתו, א\"ל וכו\u0027: \u0027באתי להגיד לך שרבי עקיבא מת בבית האסורים\u0027, מיד הלכו שניהם וכו\u0027\" (מד\u0027 משלי פ\"ט - ב\u0027). היה לו אח ושמו נימוס (בכורות ו\u0027 ע\"ב)."},{"i":1984,"n":"ר\u0027 יהושע הכהן בר נחמני","l":"י","b":"מובא בתנחומא (תשא ה\u0027), ונראה שאולי הוא ר\u0027 יהושע בר נחמיה."},{"i":1985,"n":"ר\u0027 יהושע הלוי בר שלום","l":"י","b":"מובא במ\"ר (פט\"ו - ט\"ז), ואולי צ\"ל: ר\u0027 יהודה הלוי בר שלום."},{"i":1986,"n":"ר\u0027 יהושע חילפיי","l":"י","b":"מובא בפדר\"כ (קכ\"ה)."},{"i":1987,"n":"ר\u0027 יהושעיא בריה דר\u0027 שמאי","l":"י","b":"מובא בירושלמי (כתובות פ\"ב ה\"ד), וסביר שצ\"ל: ר\u0027 הושעיא בריה דר\u0027 שמאי."},{"i":1988,"n":"ר\u0027 יוד","l":"י","b":"מובא בבבלי: \"אמר ר\u0027 אמי בר יוד\" (תענית כ\"ב ע\"ב), ופרש\"י: \"חכם ששמו יוד\"."},{"i":1989,"n":"יוד קרת","l":"י","b":"מובא בבבלי (קידושין ט\"ז ע\"ב), ופירש \"הערוך\" שהוא שם חכם."},{"i":1990,"n":"יודא","l":"י","b":"ע\"ע יהודה."},{"i":1991,"n":"ר\u0027 יודא בר אימי","l":"י","b":"מובא בירושלמי (תרומות ספ\"ב), והוא ר\u0027 יהודה בר אמי."},{"i":1992,"n":"ר\u0027 יודא בר דרדייא","l":"י","b":"מובא בירושלמי (נדרים פ\"ז ה\"א)."},{"i":1993,"n":"ר\u0027 יודא בר סיסין","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. מסר בשם ר\u0027 אחא (ירו\u0027 קידושין פ\"ג ה\"ג). ספק הוא אם הוא זהה לר\u0027 יהודה בר סיגנא."},{"i":1994,"n":"רבי יודה בי ר\u0027 בון","l":"י","b":"מובא בירושלמי (כתובות פ\"ה ה\"ו)."},{"i":1995,"n":"ר\u0027 יודה ענתורייא","l":"י","b":"מובא בירושלמי (שקלים ספ\"ח), ואולי זהה לר\u0027 יודן ענתונדריא."},{"i":1996,"n":"ר\u0027 יודן (2)","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מבעלי האגדה וההלכה. תלמידו של ר\u0027 אבא (ירו\u0027, כתובות פ\"ב ה\"ד). מסר גם בשם ר\u0027 יוחנן (ירו\u0027, קידושין פ\"ב ה\"ה) ור\u0027 אלעזר ב\"ר פמ\"ד - י\"ב). חברו של רבי יוסי (ירו\u0027, כתובות שם). רבו של רבי מנא (ירו\u0027, ביצה פ\"א ה\"ה)."},{"i":1997,"n":"ר\u0027 יודן אבוי דר\u0027 מתליא","l":"י","b":"מובא בירושלמי (כלאים פ\"ג ה\"א), ונראה שצ\"ל: מתניא."},{"i":1998,"n":"ר\u0027 יודן אבוי דר\u0027 מתניא","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. נקרא על שם בנו ר\u0027 מתניא. מובא בירושלמי (דמאי פ\"ה ה\"ג). שמו השתבש בכמה אופנים."},{"i":1999,"n":"ר\u0027 יודן אבויה דר\u0027 מתנה","l":"י","b":"מובא בירושלמי (תענית פ\"א ה\"ג), ונראה שהוא ר\u0027 יודן אבויה דר\u0027 מתניה."},{"i":2000,"n":"ר\u0027 יודן אבויה דר\u0027 מתניתא","l":"י","b":"מובא בירושלמי (יבמות פ\"א), ונראה שצ\"ל: ר\u0027 יודן אבויה דר\u0027 מתניא."},{"i":2001,"n":"ר\u0027 יודן אנתודרייא","l":"י","b":"מובא בירושלמי (ע\"ז פ\"א ה\"ב), ואולי זהה לר\u0027 יודן ענתונדריא."},{"i":2002,"n":"ר\u0027 יודן אנתורדייא","l":"י","b":"מובא בירושלמי (ברכות פ\"ד ה\"א), ואולי זהה לר\u0027 יודן ענתונדריא."},{"i":2003,"n":"ר\u0027 יודן אנתורי","l":"י","b":"מובא בירושלמי (ברכות פ\"ד ה\"ג), ואולי זהה לר\u0027 יודן ענתונדריא."},{"i":2004,"n":"ר\u0027 יודן בי רבי חנן","l":"י","b":"מובא בירושלמי (קידושין פ\"ב ה\"ה), והוא ר\u0027 יודן בר חנין."},{"i":2005,"n":"ר\u0027 יודן בי ר\u0027 ישמעאל","l":"י","b":"מובא בירושלמי (ברכות פ\"ד ה\"ב), ונראה שהוא ר\u0027 יהודה בר ישמעאל."},{"i":2006,"n":"ר\u0027 יודן בן גדיא","l":"י","b":"מובא באיכ\"ר (פ\"ג - ת\u0027), ונראה שהוא ר\u0027 יהודה בר גדיא."},{"i":2007,"n":"ר\u0027 יודן בן טרפון","l":"י","b":"כן גורס \"פני משה\" בירושלמי (שבועות פ\"א ה\"ו), ולפנינו הגיר\u0027: \"ר\u0027 יודן כד טריפן וכו\u0027\"."},{"i":2008,"n":"ר\u0027 יודן בר ברתיה דר\u0027 שמעון בן יוחאי","l":"י","b":"כך מובא בירושלמי (קידושין פ\"א ה\"ז)."},{"i":2009,"n":"ר\u0027 יודן בר גורייא","l":"י","b":"מובא בירושלמי (שבועות פ\"ב ה\"ג), ואולי הוא זהה לר\u0027 יודן גיריא."},{"i":2010,"n":"ר\u0027 יודן בר דורתי","l":"י","b":"ע\"ע ר\u0027 יודן בר ברתיה דר\u0027 שמעון בן יוחאי."},{"i":2011,"n":"ר\u0027 יודן בר חלפיי","l":"י","b":"כך מביא היוחסין ו\"סה\"ד\" מויק\"ר (פ\"ז - ג\u0027)."},{"i":2012,"n":"ר\u0027 יודן בר חנין","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. מסר בשם ר\u0027 ברכיה (ירו\u0027, סנהדרין פ\"י ה\"א)."},{"i":2013,"n":"ר\u0027 יודן בר חנינא","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מסר בשם ר\u0027 שמואל בר נחמני (רו\"ר פ\"ב ט\"ז)."},{"i":2014,"n":"ר\u0027 יודן בר יודן בר שלום","l":"י","b":"מובא בירושלמי (מגילה פ\"א ה\"ט), ואולי ט\"ס וצ\"ל: ר\u0027 יודן בר שלום (הוא ר\u0027 יהודה בר שלום). במדרש תהלים (פק\"ו - ז\u0027) מצינו: ר\u0027 יודן בריה דר\u0027 יודן."},{"i":2015,"n":"ר\u0027 יודן בר ישמעאל","l":"י","b":"ע\"ע ר\u0027 יהודה בר ישמעאל."},{"i":2016,"n":"ר\u0027 יודן בר מנשה","l":"י","b":"מובא בירושלמי (תענית רפ\"ב), שחלק עם ר\u0027 שמואל בר נחמן. נראה, שאולי הוא ר\u0027 יהודה בר מנסיא."},{"i":2017,"n":"יודן בר נחמיה","l":"י","b":"מובא באיכ\"ר (פ\"א פ\u0027 ומרוב), והוא ר\u0027 יהודה בר נחמני."},{"i":2018,"n":"ר\u0027 יודן בר פדיא","l":"י","b":"כך הגיר\u0027 בירושלמי (שביעית פ\"ה ה\"א), אך \"פני משה\" גורס: \"ר\u0027 יודן בר פליא\"."},{"i":2019,"n":"ר\u0027 יודן בר פיליא","l":"י","b":"מובא בויק\"ר (פכ\"ד - ב\u0027), ונראה שהוא ר\u0027 יודן בר פליא."},{"i":2020,"n":"ר\u0027 יודן בר פליא","l":"י","b":"אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר\u0027 יונה (ירו\u0027, שביעית פ\"ה ה\"א - לגיר\u0027 \"פני משה\"). שמו נשתבש לכמה אופנים: בר פדיא, ר\u0027 יהודה בן פלויה, בר פילייא, ר\u0027 יהודה בר פלמא."},{"i":2021,"n":"ר\u0027 יודן בר פלייא","l":"י","b":"מובא במדרש תהלים (רפק\"א), ונראה שהוא ר\u0027 יודן בר פליא."},{"i":2022,"n":"ר\u0027 יודן בר שלום","l":"י","b":"ע\"ע רב יהודה בר שלום."},{"i":2023,"n":"ר\u0027 יודן בר שקלי","l":"י","b":"אמורא ארץ ישראלי בדור החמישי - הששי. הביא שאלה בפני רבי יוסי (ירו\u0027, כתובות פ\"ט ה\"י)."},{"i":2024,"n":"ר\u0027 יודן ברבי שמואל","l":"י","b":"מובא בויק\"ר (פט\"ו - ב\u0027)."},{"i":2025,"n":"יודן בריבי","l":"י","b":"תנא מובא בבבלי (קידושין כ\"א ע\"ב). ופרש\"י: יודן שמו וגדול בדורו היה."},{"i":2026,"n":"ר\u0027 יודן בריבי","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. אמר בשם ר\u0027 ברכיה (ויק\"ר ספל\"ו)."},{"i":2027,"n":"ר\u0027 יודן בריה דרב","l":"י","b":"מובא בירושלמי (ע\"ז פ\"ב ה\"א)."},{"i":2028,"n":"ר\u0027 יודן בריה דר\u0027 אייבו","l":"י","b":"מובא בירושלמי (ברכות פ\"ב ה\"ד), ואולי צ\"ל: ר\u0027 יודן בשם ר\u0027 אייבו."},{"i":2029,"n":"ר\u0027 יודן בריה דר\u0027 חמא דכפר תחומין","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. מסר בשם חזקיה (ירו\u0027, תענית פ\"א ה\"ז)."},{"i":2030,"n":"ר\u0027 יודן בריה דר\u0027 יודן","l":"י","b":"מובא במדרש תהלים (פק\"ו - ז\u0027). ע\"ע ר\u0027 יודן בר יודן בר שלום."},{"i":2031,"n":"ר\u0027 יודן בר\u0027 יוסי","l":"י","b":"מובא בויק\"ר (פ\"ט - ט\u0027)."},{"i":2032,"n":"ר\u0027 יודן בר\u0027 שמעון","l":"י","b":"מובא בב\"ר (פ\"ד - ב\u0027)."},{"i":2033,"n":"ר\u0027 יודן גזורי","l":"י","b":"מובא בירושלמי (מגילה פ\"א ה\"ה), ואולי זהה ליודן גירי."},{"i":2034,"n":"יודן גירי","l":"י","b":"מובא בב\"ר (פל\"ה - ג\u0027), ואולי הוא יהודה בן גרים."},{"i":2035,"n":"ר\u0027 יודן גיריא","l":"י","b":"מובא בירושלמי (תענית פ\"ג ה\"ט), ואולי זהה לר\u0027 יודן גירי."},{"i":2036,"n":"ר\u0027 יודן דיפו","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. מובא בויק\"ר (פ\"כ - י\u0027). הגירסא במקום אחר: \"ר\u0027 יוחנן דיפו\" (מד\"ר פ\"ב - כ\"ד)."},{"i":2037,"n":"ר\u0027 יודן דכפר אימי","l":"י","b":"מובא בירושלמי (שבת פט\"ז ה\"ז). אותו מעשה מובא במקום אחר: \"ר\u0027 יונה דכפר אימי\" (ירו\u0027, נדרים פ\"ד ה\"ט)."},{"i":2038,"n":"ר\u0027 יודן דמן גלייא","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. חברו של ר\u0027 שמואל בר נחמני. שניהם מסרו משום ר\u0027 אליהו עיני (ב\"ר פנ\"א - י\"א)."},{"i":2039,"n":"ר\u0027 יודן דמן גלילא","l":"י","b":"מובא בויק\"ר (פ\"ב - ד\u0027)."},{"i":2040,"n":"ר\u0027 יודן מגדלייא","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. ר\u0027 יוסי בר יעקב בא לבקרו בחוליו (ירו\u0027, ברכות פ\"ט ה\"ב)."},{"i":2041,"n":"ר\u0027 יודן נסייא","l":"י","b":"מובא בירושלמי (עירובין פ\"ז ה\"י), והוא ר\u0027 יהודה נשיאה."},{"i":2042,"n":"ר\u0027 יודן ענתדרייא","l":"י","b":"מובא בירושלמי (שבת פ\"ט ה\"ג), ואולי זהה לר\u0027 יודן ענתנדריא."},{"i":2043,"n":"ר\u0027 יודן ענתונדריא","l":"י","b":"מובא בירושלמי (תענית פ\"ב ה\"ב), ואולי זהה לר\u0027 יודן ענתנדריא."},{"i":2044,"n":"ר\u0027 יודן ענתנדריא","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. שאל מר\u0027 יוסי (ירו\u0027, שקלים ספ\"ח). מובא בשם ר\u0027 יודן ענתונדריא (ירו\u0027, תענית פ\"ב ה\"ב). שמו השתבש בש\"ס הירושלמי לכמה אופנים: ענתונדרייא, ענתדרייא, ענתורייא, אנתורי, אנתורדיא, אנתודרייא."},{"i":2045,"n":"ר\u0027 יודן קפודקיא","l":"י","b":"אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר\u0027 יוסי (ירו\u0027, פאה פ\"א ה\"ד)."},{"i":2046,"n":"ר\u0027 יוחי בר יודן","l":"י","b":"מובא בפדר\"כ (ל\"ח), ונראה שיש ט\"ס בשם."},{"i":2047,"n":"רבי יוחנן","l":"י","b":"גדול אמוראי ארץ ישראל בדור השני וראש הדור כולו: גם חכמי בבל היו כפופים לו. בטרם נולד, אמר עליו רבי את הפסוק: \"בטרם אצרך בבטן ידעתיך\" (יומא פ\"ב ע\"ב). היה יתום כפול מלידה, כי כשעיברתו אמו - מת אביו, וכשילדתו - מתה (קידושין ל\"א ע\"ב). בצעירותו למד לפני רבי (פסחים ג\u0027 ע\"ב). רבותיו היו: חזקיה (עירובין כ\"ד ע\"א), ר\u0027 ינאי (ב\"ב קנ\"ד ע\"ב), ר\u0027 חנינא (ירו\u0027, הוריות פ\"ג ה\"ד) ור\u0027 אושעיא (עירובין נ\"ג ע\"א). המשיך לבוא לפני ר\u0027 אושעיא במשך 31 שנה, אף שכבר לא היה צריך לו (ירו\u0027, עירובין פ\"ה ה\"א). בישיבה של מעלה יושב ר\u0027 יוחנן אצל ר\u0027 ינאי (ב\"מ פ\"ה ע\"ב). כשנפטר רבי חנינא קרע עליו ר\u0027 יוחנן שלושה עשר בגדים (מו\"ק כ\"ד ע\"א). את רב החשיב לרבו, ונהג לכתוב לרב לבבל: \"לקדם רבותינו שבבבל\" (חולין צ\"ה ע\"ב). יסד ישיבה גדולה בטבריה. היה ראש ישיבה 08 שנה (סה\"ד). הראש והראשון בישיבתו היה ר\u0027 שמעון בן לקיש, שהיה לו גם כתלמיד (תענית ח\u0027 ע\"א), ואח\"כ הפך להיות לו תלמיד חבר (כתובות פ\"ד ע\"ב). רבי יוחנן הביא את רשב\"ל ללימוד תורה, וגם נתן לו את אחותו לאשה, ובסוף ימיהם היה ביניהם דין ודברים חריף, ור\u0027 יוחנן העניש את רשב\"ל והוא מת, ואח\"כ מרוב צער נעקרה דעתו של ר\u0027 יוחנן וביקשו רחמים ומת גם ר\u0027 יוחנן (ב\"מ פ\"ד ע\"א). רבי אלעזר בן פדת היה בתחילה תלמידו המובהק (יבמות צ\"ו ע\"ב), ואח\"כ הפך תלמיד חבר (ירו\u0027, סנהדרין פ\"א ה\"א), ולבסוף ישב על כסאו של ר\u0027 יוחנן כראש מתיבתא (\"אגרת רב שרירא גאון\"). לר\u0027 יוחנן היו תלמידים רבים מאד, וביניהם: ר\u0027 אמי [שהיה ממלא מקומו אחרי ר\u0027 אלעזר, שנפטר באותה שנה שנפטר ר\u0027 יוחנן] (כתובות ס\"ב ע\"א), ר\u0027 אסי (שם), ר\u0027 חייא בר אבא (ברכות ל\"ח ע\"ב), ר\u0027 יוסי בר חנינא (סנהדרין ל\u0027 ע\"ב), ר\u0027 אבהו (כתובות נ\"ז ע\"א) ורבים אחרים שהיו ראשי הדור וראשי ישיבות אחריו. היה מבורך בכח גופני גדול (ב\"מ ס\"ב ע\"א), יופי נדיר (שם פ\"ד ע\"א) ובעושר (תענית כ\"א ע\"א רש\"י). היו לו יסורים של אהבה וכל עשרת בניו מתו עליו בחייו (ברכות ה\u0027 ע\"ב רש\"י). היה לו כח להחיות מתים ולאחר שהעניש בטעות את ר\u0027 כהנא, החיה אותו (ב\"ק קי\"ז ע\"א). היה גדול כל כך, עד שאמרו: \"רב ור\u0027 יוחנן, הלכה כרבי יוחנן\" (ביצה ד\u0027 ע\"א), וכן: \"שמואל ור\u0027 יוחנן, הלכה כרבי יוחנן\" (ב\"ק ק\"ד ע\"ב תד\"ה: ורבי יוחנן). יש \"ראשונים\" (ביניהם הרמב\"ם) שמייחסים לו את סידור ש\"ס הירושלמי. נפטר בשנת ד\u0027 ל\"ט (972) \"אגרת רב שרירא גאון\")."},{"i":2048,"n":"ר\u0027 יוחנן אחוה דמר בריה דרבינא","l":"י","b":"אמורא בבלי בדור הרביעי - החמישי. מובא בבבלי (שבת צ\"ד ע\"א), שהקשה לרב נחמן בר יצחק."},{"i":2049,"n":"ר\u0027 יוחנן אחוה דרב ספרא","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. מובא בירושלמי (חגיגה פ\"א ה\"ו), שם מתיב על דברי ר\u0027 יוסי [חברו של ר\u0027 יונה]."},{"i":2050,"n":"יוחנן אחי ר\u0027 שמעון בן יהוצדק הכהן","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. אחיו של ר\u0027 שמעון בן יהוצדק (שהיה מרבותיו של רבי יוחנן) (שמחות פ\"ד הי\"א)."},{"i":2051,"n":"ר\u0027 יוחנן בן אלעאי","l":"י","b":"תנא בדור השלישי. תלמידו של רבי אליעזר. כשרבי אליעזר שבת בסוכתו של ר\u0027 יוחנן ברבי אלעאי, שאלו דיני סוכה, ור\u0027 אליעזר השתמט מלענות לו (סוכה כ\"ז ע\"ב)."},{"i":2052,"n":"ר\u0027 יוחנן בן אלעזר","l":"י","b":"מובא בבבלי (פסחים נ\"א ע\"א), ונראה שצ\"ל: ר\u0027 יונתן (כמו בשבת מ\"ט ע\"ב)."},{"i":2053,"n":"ר\u0027 יוחנן בן ארזא","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. חברו של ר\u0027 יוסי בן נהוראי. על חילוקי דעות ביניהם הוסיף ר\u0027 יהושע בן לוי את הסבריו (ע\"ז נ\"ח ע\"א)."},{"i":2054,"n":"יוחנן בן בג בג","l":"י","b":"מובא בבבלי (קידושין י\u0027 ע\"ב). ע\"ע בן בג בג."},{"i":2055,"n":"רבי יוחנן בן ברוקא","l":"י","b":"תנא בדור השלישי. תלמידו המובהק של רבי יהושע. חברו של רבי אלעזר חסמא - שניהם הלכו לקבל פני ר\u0027 יהושע בפקיעין, ולבקשת רבם מסרו לו תוכן דרשתו של ר\u0027 אלעזר בן עזריה (חגיגה ג\u0027 ע\"א). השאיר אחריו בן חכם ושמו ר\u0027 ישמעאל (ברכות נ\"ט ע\"א)."},{"i":2056,"n":"רבי יוחנן בן בתירא","l":"י","b":"מובא בבבלי (זבחים ס\"ג ע\"א), וב\"שיטה מקובצת\": \"ר\u0027 יהודה בן בתירא\", וכן במקום אחר (מנחות מ\"א ע\"ב), גיר\u0027 \"שיטה מקובצת\": \"ר\u0027 יונתן בן בתירא\"."},{"i":2057,"n":"ר\u0027 יוחנן בן גודגדא","l":"י","b":"תנא בדור השני. היה לוי, ושימש בבית המקדש כממונה על נעילת שערים. פעם רצה ר\u0027 יהושע בן חנניה לעזור לו, ואמר לו: \"חזור בני וכו\u0027\" (ערכין י\"א ע\"ב). מובא במשנה (גיטין נ\"ה ע\"א) שהעיד ד\u0027 דברים: \"על חרשת וכו\u0027 על קטנה וכו\u0027\". נהג בחסידות ובזהירות מופלגת (חגיגה י\"ח ע\"ב)."},{"i":2058,"n":"רבי יוחנן בן דהבאי","l":"י","b":"תנא שאין לקבוע את זמנו המדוייק. מסר בשמו של רבי יהודה בן תימא (סנהדרין ד\u0027 ע\"ב). חלק עם רבי חנינא בן גמליאל (מנחות מ\"ב ע\"ב)."},{"i":2059,"n":"רבי יוחנן בן החורנית","l":"י","b":"תנא בדור הראשון. תלמידו של שמאי (יבמות ט\"ו ע\"ב). רבו של רבי אלעזר בר צדוק א\u0027 (שם). זקני בית שמאי וזקני בית הלל הלכו לבקרו בסוכתו (סוכה כ\"ח ע\"א)."},{"i":2060,"n":"ר\u0027 יוחנן בן החרבות","l":"י","b":"מובא בתוספתא (סוכה פ\"ב), והוא רבי יוחנן בן החורנית."},{"i":2061,"n":"רבי יוחנן בן המשולם","l":"י","b":"תנא בדור הרביעי - החמישי. מובא בבבלי: \"העיד ר\u0027 יוסי בן המשולם, משום ר\u0027 יוחנן אחיו, שאמר משום רבי אלעזר חסמא\" (גיטין ס\"ב ע\"א)."},{"i":2062,"n":"רבן יוחנן בן זכאי","l":"י","b":"תנא בדור הראשון. מגדולי התנאים. היחיד מבין כל חכמי ישראל שזכה בתואר \"רבן\", אף שלא היה ממשפחת הנשיאים. אחרון שקיבל מן \"הזוגות\" (אבות פ\"ב מ\"ח). מתלמידיו החשובים של הלל הזקן, שאמר עליו: \"שהוא אב לחכמה ואב לדורות\" (ירו\u0027, נדרים ספ\"ה). חי מאה ועשרים שנה \"ארבעים שנה עסק בפרקמטיא, ארבעים שנה למד, ארבעים שנה לימד\" (ר\"ה ל\"א ע\"ב). כבר 04 שנה לפני החורבן היה מראשי הדור (יומא ל\"ט ע\"ב). אחרי החורבן שימש נשיא ישראל שנה או שנתיים (שבת נ\"ד ע\"ב תד\"ה: היה). זכה לראות 4 נשיאים בחייו: הלל, שמעון, ר\"ג הזקן ורשב\"ג הנהרג. היתה לו ישיבה גדולה בברור חיל (סנהדרין ל\"ב ע\"ב). בחירי תלמידיו היו חמישה: רבי אליעזר בן הורקנוס, רבי יהושע בן חנניה, רבי יוסי הכהן, רבי שמעון בן נתנאל ורבי אלעזר בן ערך (אבות שם). כשדרש לפני קהל, נאלץ לדרוש בצילו של היכל (פסחים כ\"ו ע\"א פרש\"י: \"שאין לך בית המדרש מחזיקן\" את המוני השומעים). היה עד לחורבן הבית: ערב החורבן הוציאוהו תלמידיו מירושלים הנצורה, והוא התייצב לפני אספסינוס הרומי וביקש ממנו שלוש בקשות: יבנה וחכמיה, שלשלת הנשיאות של רבן גמליאל ורופא שירפא את רבי צדוק (שצם 04 שנה שבית המקדש לא יחרב) (גיטין נ\"ו ע\"ב). אחר החורבן תיקן תקנות \"זכר למקדש\" (ר\"ה ל\u0027 ע\"א). \"מימיו לא שח שיחת חולין, ולא הלך ד\u0027 אמות בלא תורה ובלא תפילין\" (סוכה כ\"ח ע\"א). הבין שיחת מלאכי השרת ושיחת שדים ושיחת דקלים (שם). לפני פטירתו קראו לו תלמידיו: \"נר ישראל, עמוד הימיני, פטיש חזק\", והוא אמר להם: \"הכינו כסא לחזקיה מלך יהודה שבא אלי ללוותי\" (ברכות כ\"ח ע\"ב). \"סה\"ד\" כתב בשם \"צמח דוד\" שנולד ג\u0027 תשי\"ג (35) ונפטר תתקל\"ג (371) ועליו אמרו: \"משמת רבי יוחנן בן זכאי בטל זיו החכמה\" (סוף סוטה)."},{"i":2063,"n":"רבי יוחנן בן יהושע בן חמיו של רבי עקיבא","l":"י","b":"תנא בדור השלישי. גיסו של רבי עקיבא. מובא במשנה, שאמר כדברי בן עזאי (ידים פ\"ג מ\"ה)."},{"i":2064,"n":"רבי יוחנן בן יוסף","l":"י","b":"מובא בבבלי (חולין קמ\"ט ע\"א). לפי גירסת \"סה\"ד\" הוא רבי יונתן בר יוסף (והוא רבי יונתן התנא)."},{"i":2065,"n":"ר\u0027 יוחנן בן לוי","l":"י","b":"מובא בב\"ר (פי\"ג - ט\"ז), ואולי צ\"ל: ר\u0027 יהושע בן לוי."},{"i":2066,"n":"ר\u0027 יוחנן בן מתיא","l":"י","b":"תנא שאין לקבוע זמנו המדוייק. חי בזמנו של רבן שמעון בן גמליאל (שחי בדור הרביעי) או לפניו. מסופר שאמר לבנו: \"צא ושכור לנו פועלים וכו\u0027\" (ב\"מ פ\"ג ע\"א)."},{"i":2067,"n":"ר\u0027 יוחנן בן נורי","l":"י","b":"תנא בדור השלישי, מושבו היה בנגנינר (ירו\u0027, כלאים פ\"ד ה\"ב). מסר משום רבי אליעזר (קידושין ל\"ט ע\"א). חברו המובהק של רבי עקיבא (ערכין ט\"ז ע\"ב). דיבר לר\u0027 יהושע כחבר: \"יהושע, אין שומעין לך\" (עירובין מ\"א ע\"א). ר\u0027 יוסי הגלילי מסר בשמו (מנחות ל\"ח ע\"ב). ר\u0027 יהושע בן קרחה הלך אצלו (ירו\u0027, כלאים שם). היה חכם מופלג וידע לשער כמה טיפות יש בים (ספרי דברים ט\"ז). היה עני מרוד ולא היה לו פת לאכול (ספרי שם). ואמרו: \"הרואה ר\u0027 יוחנן בן נורי בחלום, צפה ליראת חטא\" (אדר\"נ ספ\"מ)."},{"i":2068,"n":"ר\u0027 יוחנן בן ניזוף","l":"י","b":"מובא בתוספתא (שבת רפ\"ג), והוא ר\u0027 יוחנן הנזיף."},{"i":2069,"n":"ר\u0027 יוחנן בן פדיה","l":"י","b":"מובא ב\"ילקוט תהלים\" (רמז תשץ), ואולי צ\"ל: ר\u0027 יוחנן בר מריה כמו במקום אחר (ב\"ר פי\"ג - ה\u0027)."},{"i":2070,"n":"ר\u0027 יוחנן בן פזי","l":"י","b":"מובא בפסיקתא רבתי (פ\u0027 פרה ס\"ו)."},{"i":2071,"n":"ר\u0027 יוחנן בן קצרתה","l":"י","b":"מובא בשהש\"ר (פ\"ב - ט\u0027), ונראה שצ\"ל: ר\u0027 יצחק בן קצרתה (ירו\u0027, ר\"ה פ\"א ה\"א)."},{"i":2072,"n":"ר\u0027 יוחנן בן שאול","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. חלק עם ר\u0027 יוסי בן שאול (שבת קכ\"ה ע\"ב). ר\u0027 יוסי בר שאול (שהיה תלמידו של רבי), אולי הוא אחיו. ר\u0027 לוי מסר בשמו (ב\"ר צ\"ח - א\u0027)."},{"i":2073,"n":"רבי יוחנן בן תורתא","l":"י","b":"תנא בדור השלישי. חברו של רבי עקיבא. כשדרש רבי עקיבא על בר כוכבא \"דרך כוכב מיעקב\" שהוא מלך המשיח, אמר לו רבי יוחנן בן תורתא: \"עקיבא, יעלו עשבים בלחייך ועדיין בן דוד לא יבוא\" (ירו\u0027, תענית פ\"ד ה\"ה). ואולי עליו מסופר (פסיקתא רבתי פ\u0027 פרה ב\u0027) שישראל מכר פרתו לעכו\"ם, ובשבת לא רצתה הפרה לחרוש, ובא היהודי ולחש באזני הפרה: שנמכרה לעכו\"ם וחייבת לחרוש בשבת, ואזי התחילה לחרוש בשבת. ודן העכו\"ם ק\"ו בעצמו: \"ומה פרה כך, אדם על אחד כמה וכמה\". והתגייר ולמד תורה, וקראו לו: יוחנן בן תורתא. יש גורסים: רב הונא בר תורתא."},{"i":2074,"n":"רבי יוחנן בנו של ר\u0027 יהושע בן קרחה","l":"י","b":"תנא בדור החמישי. בן בנו של רבי עקיבא (לשיטת רש\"י שבועות ו\u0027 ע\"א). מובא בספרא (ריש אחרי)."},{"i":2075,"n":"ר\u0027 יוחנן בנו של ר\u0027 יוסי בן קיסמא","l":"י","b":"מובא במדרש תהלים (פק\"י - ד\u0027)."},{"i":2076,"n":"ר\u0027 יוחנן בר חנינא","l":"י","b":"מובא בבבלי (סנהדרין ל\"ח ע\"ב). \"דק\"ס\" גורס: ר\u0027 חמא או ר\u0027 אחא בר חנינא."},{"i":2077,"n":"ר\u0027 יוחנן בר יאשיה","l":"י","b":"מובא במכילתא (משפטים פט\"ז). \"ילקוט\" גורס: ר\u0027 אחי בר יאשיה."},{"i":2078,"n":"ר\u0027 יוחנן בר יודן דמן גלילא","l":"י","b":"מובא בתנחומא (הישן פ\u0027 אחרי). יתכן שיש שיבוש בשם."},{"i":2079,"n":"ר\u0027 יוחנן בר יישוע","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. \"אמר רבי מתנייה סלקית לסחורה [עליתי למקום ששמו סחורה] ושמעית ר\u0027 יוחנן ור\u0027 ישמעאל בני יישוע\" (ירו\u0027, יבמות פ\"ז ה\"ו)."},{"i":2080,"n":"ר\u0027 יוחנן בר מדייא","l":"י","b":"מובא בירושלמי (פסחים פ\"ז הי\"ב), והוא ר\u0027 יוחנן בר מריא."},{"i":2081,"n":"ר\u0027 יוחנן בר מולדא","l":"י","b":"כן הגירסא בכמה דפוסים ישנים, והנכון שצ\"ל: ר\u0027 חנן בר מולדא."},{"i":2082,"n":"ר\u0027 יוחנן בר מרי","l":"י","b":"מובא בירושלמי (תרומות רפי\"א), והוא ר\u0027 יוחנן בר מריא."},{"i":2083,"n":"ר\u0027 יוחנן בר מריא","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. תלמידו של ר\u0027 פנחס (ירו\u0027, פסחים פ\"ז הי\"ב). מסר בשם ר\u0027 יוחנן (ירו\u0027, פאה פ\"א ה\"א). שמו נשתבש בכמה אופנים: מרייא, מדייא, מרי, מרייה. היה בקי בחשבון העיבור (ירו\u0027, ע\"ז פ\"א ה\"א)."},{"i":2084,"n":"ר\u0027 יוחנן בר מרייא","l":"י","b":"מובא בירושלמי (פסחים פ\"ה ה\"ו), והוא ר\u0027 יוחנן בר מריא."},{"i":2085,"n":"ר\u0027 יוחנן בר מרייה","l":"י","b":"מובא בירושלמי (שבת פ\"ג ה\"א), והוא ר\u0027 יוחנן בר מריא."},{"i":2086,"n":"ר\u0027 יוחנן בר נחמן","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. ר\u0027 יהודה הלוי בר שלום מסר בשמו (תנחומא וירא ח\u0027)."},{"i":2087,"n":"ר\u0027 יוחנן בר סימון","l":"י","b":"מובא ב\"ילקוט\" (שהש\"ר רמז תתקפ\"ב), ואולי צ\"ל: ר\u0027 יהודה בר\u0027 סימון כמו בשהש\"ר (פ\"א - ז\u0027)."},{"i":2088,"n":"ר\u0027 יוחנן בר פפא","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. ר\u0027 עזריה אמר בשמו (ב\"ר פמ\"ה - ד\u0027). יש סבורים שצ\"ל: ר\u0027 חנינא בר פפא."},{"i":2089,"n":"ר\u0027 יוחנן בר שאונה","l":"י","b":"בויק\"ר (פ\"ה - ב\u0027) מביא ר\u0027 לוי בשמו. \"סה\"ד\" סבור, שר\u0027 יוחנן בר שאונה הוא ר\u0027 חנא בר שאונה."},{"i":2090,"n":"ר\u0027 יוחנן בר שילא","l":"י","b":"מובא בירושלמי (שבת פ\"ד ה\"א)."},{"i":2091,"n":"ר\u0027 יוחנן דבית גוברין","l":"י","b":"מובא בתנחומא (תולדות כ\"ג), ונראה שצריך אולי לגרוס ר\u0027 יונתן דבית גוברין."},{"i":2092,"n":"ר\u0027 יוחנן דיפו","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. מובא בבמד\"ר (פ\"ב - כ\"ד), שפנה בשאלה לר\u0027 פנחס בר חמא. והגירסא במקום אחר (ויק\"ר פ\"כ - י\u0027): ר\u0027 יודן דיפו."},{"i":2093,"n":"ר\u0027 יוחנן דצפרין","l":"י","b":"מובא מאמרו בשהש\"ר (פ\"ח - פי\"א - ג\u0027): \"מי שהוא טפש אומר: \u0027מי הוא יכל ללמוד כל התורה\u0027 וכו\u0027 והחכם אומר: \u0027הריני לומד ג\u0027 הלכות היום ב\u0027 למחר\u0027 וכו\u0027\". יש סבורים שצריך לגרוס ר\u0027 חנוך דצפורין."},{"i":2094,"n":"ר\u0027 יוחנן דקציון","l":"י","b":"מובא בירושלמי (ביצה פ\"ה ה\"ה), והוא ר\u0027 יוחנן דקרציין."},{"i":2095,"n":"ר\u0027 יוחנן דקרציין","l":"י","b":"מובא בירושלמי (ברכות פ\"ח ה\"ו)."},{"i":2096,"n":"רבי יוחנן החורני","l":"י","b":"מובא בבבלי (יבמות ט\"ו ע\"ב), והוא רבי יוחנן בן החורנית."},{"i":2097,"n":"יוחנן הכהן הסופר","l":"י","b":"מובא בירושלמי (מע\"ש פ\"ה ה\"ד), והוא יוחנן סופר."},{"i":2098,"n":"ר\u0027 יוחנן המכיתי","l":"י","b":"תנא בדור החמישי. רבו דרבו של רבי יוחנן. מובא בבבלי: \"רבי יוחנן משום ר\u0027 שמעון המחוזי, משום ר\u0027 יוחנן המכיתי\" (סוכה מ\"ח ע\"ב)."},{"i":2099,"n":"ר\u0027 יוחנן הנזוף","l":"י","b":"תנא בדור השלישי. מובא בבבלי: \"א\"ר יוסי: \u0027מעשה באבא חלפתא שהלך אצל ר\"ג בריבי לטבריה, ומצאו שהיה יושב על שולחנו של יוחנן הנזוף\u0027\" (שבת קט\"ו ע\"א)."},{"i":2100,"n":"ר\u0027 יוחנן הסנדלר","l":"י","b":"תנא בדור הרביעי. עיר מולדתו היתה אלכסנדריה של מצרים (ירו\u0027, חגיגה פ\"ג ה\"ח). וזה אולי הכינוי הסנדלר, למרות שמקובל שהכינוי הוא על שם שהיה סנדלר. וה\"יוחסין\" כתב שהיה \"נוקב מרגליות\", ותרגום: סנדלרון (לכן נקרא הסנדלר). תלמידו המובהק של רבי עקיבא (ברכות כ\"ב ע\"א). אמר לרבי מאיר: \"שימשתי את ר\"ע עומדות, מה שלא שימשת ישובות\" [כלומר שימשתי את ר\"ע הרבה ממך] (ירו\u0027, שם). כשישב רבי עקיבא בבית הסוהר בזמן גזירת שמד ואיסור לימוד תורה, והיו צריכים לשאול ממנו דין, עשה עצמו ר\u0027 יוחנן הסנדלר כרוכל המכריז על סחורתו ושאלו ור\"ע ענה לו ברמיזות (ירו\u0027, יבמות פי\"ב ה\"ה). אחרי חורבן ביתר, כשבוטלו גזירות אדריינוס, מסופר \"מעשה שנכנסו שבעה זקנים לעבר את השנה בבקעת רימון, ומי היו? ר\"מ ור\u0027 יהודה ור\u0027 יוסי ור\"ש ור\u0027 נחמיה ור\"א בן יעקב ור\u0027 יוחנן הסנדלר\" (ירו\u0027, חגיגה שם). (\"סה\"ד\" כתב: \"אני הכותב יחיאל בידי מגילת יוחסין כתובה דאבי אמי מזרע דר\u0027 יוחנן הסנדלר, וסדר שלשלת היוחסין ממנו, רש\"י מאור הגולה, והגאון מהרש\"ל\")."},{"i":2101,"n":"יוחנן חקוקאה","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. בא לפני רבי לשאול דין בענין פסח (פסחים י\"ג ע\"א). תוספות מפרש (שם ג\u0027 ע\"ב) שהיה מעיר חקוקה. ור\"ח פירש (שם) שהיה סופר."},{"i":2102,"n":"רבי יוחנן מלחשך","l":"י","b":"מובא בבבלי (עירובין צ\"א ע\"א). לגיר\u0027 תוספות (שם) הוא רבי יוחנן (בר פלוגתיה דרבי שמעון בן לקיש)."},{"i":2103,"n":"יוחנן סופר","l":"י","b":"סופרו של רבן גמליאל דיבנה (דור שלישי לתנאים). חי בזמן הבית (סנהדרין י\"א ע\"ב)."},{"i":2104,"n":"ר\u0027 יוחנן ספרא דגופתא","l":"י","b":"סופר ארץ ישראלי מהעיר גופתא, בדור הרביעי לאמוראי ארץ ישראל. מובא בירושלמי (סוכה פ\"ב ה\"ה), שרב הונא הלך לקדש את החודש, והיה צמא ונכנס לסוכתו לשתות."},{"i":2105,"n":"ר\u0027 יוחנן ענתנייתא","l":"י","b":"מובא בירושלמי (ברכות פ\"ה ה\"א). מאמרו: \"היגע בתלמודו בצנעה לא במהרה הוא משכח\" (שם)."},{"i":2106,"n":"יוחנן שר הבירה","l":"י","b":"מובא במדרש תהלים (הישן פ\"ג), ואולי צ\"ל: יונתן שר הבירה."},{"i":2107,"n":"ר\u0027 יולימנא בר עבדי","l":"י","b":"מובא בפס\u0027 רבתי (רפ\"ז), שאמר בשם ר\u0027 יצחק. יש גורסים ר\u0027 לוליאני בר טברי."},{"i":2108,"n":"רבי יונה","l":"י","b":"מגדולי אמוראי ארץ ישראל בדור הרביעי - החמישי. קיבל תורה מרבי יוחנן (בכורות ל\u0027 ע\"א). רבותיו המובהקים היו: רבי אלעאי (ירו\u0027, תרומות פ\"ב ה\"ד), רבי זירא (בכורות שם) וכן למד מר\u0027 ירמיה (ירו\u0027, מגילה פ\"ד ה\"ה). חברו המובהק היה רבי יוסי, ושניהם עמדו בראש ישיבת טבריה, ושניהם יצאו לקדם את המלך מאנטיוכא (ירו\u0027, ברכות פ\"ה ה\"א). בזמן הרדיפות הקשות התירו שניהם ליהודי הגליל לאפות לחם בשבת לצבאו של אורסיקינוס (ירו\u0027, שביעית פ\"ד ה\"ב). ר\u0027 יונה כונה: \"תקיפי דארעא דישראל\" (תענית כ\"ג ע\"ב). הביא גשם בתפילתו (שם). פעם נפלה אש בשכונתו, ופרס את טליתו והאש ברחה (ירו\u0027, נדרים פ\"ד ה\"ט). נפטר לפני ר\u0027 יוסי חברו (ירו\u0027, מע\"ש פ\"ד ה\"ו). זכה לבן גדול בתורה, מגדולי האמוראים בארץ ישראל בדור החמישי - ר\u0027 מנא (ירו\u0027, דמאי רפ\"ד)."},{"i":2109,"n":"רבי יונה אבוה דרבי מני","l":"י","b":"מובא בבבלי (תענית כ\"ג ע\"ב), והוא רבי יונה, חברו דרבי יוסי, מגדולי אמוראי א\"י בדור הרביעי."},{"i":2110,"n":"ר\u0027 יונה אביו דר\u0027 ישמעאל","l":"י","b":"מובא בירושלמי (סנהדרין ריש חלק), ונראה שיש ט\"ס בשם."},{"i":2111,"n":"רבי יונה בוצירוי","l":"י","b":"מובא בירושלמי (כלאים פ\"ט ה\"א), והוא ר\u0027 יונה בוצריי."},{"i":2112,"n":"ר\u0027 יונה בוצריא","l":"י","b":"מובא בירושלמי (יומא פ\"ה ה\"א), והוא ר\u0027 יונה בוצריי."},{"i":2113,"n":"יונה בוצריה","l":"י","b":"מובא בירושלמי (מו\"ק פ\"ב ה\"ג), והוא ר\u0027 יונה בוצריי."},{"i":2114,"n":"רבי יונה בוצריי","l":"י","b":"אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר\u0027 מנא (ירו\u0027, כלאים רפ\"ט). שאל גם מר\u0027 הונא ב\u0027 (ירו\u0027, מו\"ק פ\"ב ה\"ג). שמו שובש בכמה אופנים: בוצירוי, בוצרייה, בוצרייא, בוצריא, מבוצרצא, בוצריה."},{"i":2115,"n":"רבי יונה בוצרייא","l":"י","b":"מובא בירושלמי (שביעית פ\"ב ה\"ז), והוא ר\u0027 יונה בוצריי."},{"i":2116,"n":"רבי יונה בוצרייה","l":"י","b":"מובא בירושלמי (כלאים פ\"ח ה\"ג), והוא ר\u0027 יונה בוצריי."},{"i":2117,"n":"ר\u0027 יונה בן צדיה","l":"י","b":"מובא בפדר\"כ, והוא ר\u0027 יונה בוצריי."},{"i":2118,"n":"ר\u0027 יונה בן צרויה","l":"י","b":"מובא בירושלמי (שבת פ\"ה ה\"א), והוא ר\u0027 יונה בוצריי."},{"i":2119,"n":"ר\u0027 יונה בר אבא","l":"י","b":"מובא בויק\"ר (ספל\"ה). נראה שאולי יש ט\"ס בשם."},{"i":2120,"n":"רבי יונה בר תחליפא","l":"י","b":"אמורא בבלי בדור הרביעי - חמישי. מובא בבבלי: \"רבא הוה בדיק להו גירא [חץ] לרבי יונה בר תחליפא, ושחט בה עופא וכו\u0027\" (חולין ל\u0027 ע\"ב)."},{"i":2121,"n":"רבי יונה דכפר אימי","l":"י","b":"מובא בירושלמי (נדרים פ\"ד ה\"ט). אותו מעשה מובא בשם \"ר\u0027 יודן דכפר אימי\" (ירו\u0027, שבת פט\"ז ה\"ז)."},{"i":2122,"n":"ר\u0027 יונה חמוה דר\u0027 אמי","l":"י","b":"מובא בירושלמי (גיטין פ\"ב ה\"א)."},{"i":2123,"n":"ר\u0027 יונה מבוצרצא","l":"י","b":"מובא בפסיקתא רבתי (פ\u0027 תשא ס\"ח), והוא ר\u0027 יונה בוצריי."},{"i":2124,"n":"רבי יונתן","l":"י","b":"תנא בדור הרביעי. נראה שסתם ר\u0027 יונתן בר יוסף ור\u0027 יונתן בי ר\u0027 יוסי חד הם. היה תלמידו של רבי עקיבא (ירו\u0027, מעשרות פ\"ה ה\"ב). חברו של ר\u0027 יאשיה, ושניהם היו תלמידיו המובהקים של ר\u0027 ישמעאל (מנחות נ\"ז ע\"ב). מסופר: \"א\"ר יונתן: \u0027נמתי לו לבן עזאי וכו\u0027 נם לי \u0027ומה ישמעאל אומר בדבר הזה וכו\u0027 ובלשון הזה אמר לי [בן עזאי] חבל על שלא שמשתי את ר\u0027 ישמעאל\u0027\" (חולין ע\u0027 ע\"ב)."},{"i":2125,"n":"ר\u0027 יונתן","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. היה מבבל ועלה לארץ ישראל (חולין מ\"ה ע\"א רש\"י). מבעלי האגדה. תלמידו של ר\u0027 שמעון בר יוסי בר לקוניא ושל רבי חייא (ירו\u0027, עירובין פ\"ג ה\"ד). חברם של ר\u0027 חנינא ושל ר\u0027 יהושע בן לוי (ירו\u0027, מע\"ש פ\"ג ה\"ג). רבו המובהק של ר\u0027 שמואל בר נחמני (פסחים כ\"ד ע\"א). רבי יוחנן אמר על ר\u0027 יונתן: \"ידעין חברין וכו\u0027\" (חולין מ\"ה ע\"א). מקומו היה כנראה בטבחה (קה\"ר פ\"ג - י\"ד)."},{"i":2126,"n":"ר\u0027 יונתן איש הבירה","l":"י","b":"מובא במדרש תהלים (פ\"ג - ג\u0027), ונראה שהוא ר\u0027 יונתן רבו של ר\u0027 שמואל בר נחמני."},{"i":2127,"n":"רבי יונתן בי רבי יוסי","l":"י","b":"מובא בירושלמי (מעשרות פ\"ה ה\"ב), והוא ר\u0027 יונתן התנא."},{"i":2128,"n":"ר\u0027 יונתן בן אבטולמוס","l":"י","b":"תנא שאין לקבוע את זמנו המדוייק. מובא בבבלי (נדה י\"ט ע\"א). במקום אחר (זבחים מ\"ט ע\"ב) הגירסא: ר\u0027 נתן בן אבטולמוס."},{"i":2129,"n":"ר\u0027 יונתן בן אלעזר","l":"י","b":"מובא בתנחומא (בחוקותי - ד\u0027), ונראה שהוא ר\u0027 יונתן רבו של ר\u0027 שמואל בר נחמני."},{"i":2130,"n":"יונתן בן אריה","l":"י","b":"מובא ב\"ילקוט\" (תהלים רמז תתנט), ונראה שיש ט\"ס בשם."},{"i":2131,"n":"ר\u0027 יונתן בן בתירא","l":"י","b":"מובא בבבלי (מנחות מ\"א ע\"ב), לפי גירסת \"שיטה מקובצת\". ולפנינו: יוחנן בן בתירא."},{"i":2132,"n":"ר\u0027 יונתן בן הרכינס","l":"י","b":"תנא מתלמידי שמאי. האריך ימים עד דור השלישי. אחיו של ר\u0027 דוסא בן הרכינס, שקראו בכור שטן (פרש\"י: חריף ועומד על שמועתו). ור\u0027 דוסה הזהיר את ר\u0027 יהושע, רבי עקיבא ורבי אלעזר בן עזריה, שלא יקפחם בהלכות, לפי שיש עמו ג\u0027 מאות תשובות וכו\u0027 (יבמות ט\"ז ע\"א). ובירושלמי (יבמות פ\"א ה\"ו) ומסופר שמרוב חריפותו לא הבינו את הסבריו."},{"i":2133,"n":"יונתן בן הרסא","l":"י","b":"מובא בתוספתא (כלים), והוא ר\u0027 יונתן בן חרשא איש גנוסר."},{"i":2134,"n":"ר\u0027 יונתן בן חגי","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. מובא בקה\"ר (פ\"ט - י\"ב), שמסר יחד עם ר\u0027 עזריה בשם ר\u0027 יצחק בר מריון."},{"i":2135,"n":"ר\u0027 יונתן בן חלי","l":"י","b":"מובא בירושלמי (סנהדרין פ\"ו ה\"ה)."},{"i":2136,"n":"יונתן בן חרשא איש גינוסר","l":"י","b":"תנא בדור השלישי - הרביעי. מובא בירושלמי (מעשרות פ\"א ה\"ב). ששאל את רבן גמליאל וחכמים ביבנה."},{"i":2137,"n":"רבי יונתן בן יוסי","l":"י","b":"מובא בירושלמי (כלאים פ\"ב ה\"ו), והוא ר\u0027 יונתן התנא."},{"i":2138,"n":"ר\u0027 יונתן בן יוסי בן לקוניא","l":"י","b":"מובא בבבלי (שבועות י\"ח ע\"א). יתכן שיש שיבוש בשם."},{"i":2139,"n":"ר\u0027 יונתן בן יוסף","l":"י","b":"מובא בבבלי (יומא פ\"ה ע\"ב), והוא ר\u0027 יונתן התנא."},{"i":2140,"n":"יונתן בן משולם","l":"י","b":"תנא בדור הרביעי. רבי אלעזר בן יעקב (תלמידו של ר\"ע) שאל ממנו, והוא השיב לו משמו של רבי עקיבא (ילקוט ח\"א, רמז תשפה)."},{"i":2141,"n":"יונתן בן עוזיאל","l":"י","b":"תנא בדור הראשון. הגדול שבתלמידי הלל (סוכה כ\"ח ע\"א). \"אמרו עליו על יונתן בן עוזיאל בשעה שיושב ועוסק בתורה כל עוף שפורח עליו מיד נשרף\" (פרש\"י שם: \"שהיו מלאכי השרת מתקבצין סביביו לשמוע דברי תורה מפיו\") וכשתרגם הנביאים \"יצתה בת קול ואמרה לו דייך\" (מגילה ג\u0027 ע\"א) שמאי (חברו של הלל) בא ליונתן בן עוזיאל \"במקלו ובתרמילו\" לברר ענין, וא\"ל שמאי: \"אם אתה יכול וכו\u0027\", אמר (שמאי) \"הטיח עלי בן עוזיאל\" (ב\"ב קל\"ג ע\"ב)."},{"i":2142,"n":"רבי יונתן בן עכינאי","l":"י","b":"אמורא ארץ ישראל בדור הראשון. חברו של ר\u0027 חנינא בר חמא (שבת מ\"ט ע\"א)."},{"i":2143,"n":"רבי יונתן בן עכמאי","l":"י","b":"אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של רבי יוחנן (סנהדרין י\"ד ע\"א). ר\u0027 אבהו מסר ברייתא ששנה לו ר\u0027 יונתן בן עכמאי ואמר לר\"ז: \"אדם גדול היה ובקי במשנתו היה\" (ירו\u0027, תרומות פי\"א ה\"ה)."},{"i":2144,"n":"ר\u0027 יונתן בן עמרם","l":"י","b":"תנא בדור החמישי. תלמידו של רבי. לא רצה ליהנות ולהתפרנס מכבוד תורה אף בשנת בצורת (ב\"ב ח\u0027 ע\"א). ר\u0027 ינאי שאל ממנו (ע\"ז ל\"ו ע\"ב רש\"י)."},{"i":2145,"n":"ר\u0027 יונתן בן עסמיי","l":"י","b":"תנא בדור החמישי. תלמידו של רבי שמעון בן יוחאי. חברו של ר\u0027 יהודה בן גרים (מו\"ק ט\u0027 ע\"א). רשב\"י שלח את בנו לקבל ברכה מהם ואמר עליהם: \"בני אדם הללו אנשים של צורה הם\" (שם)."},{"i":2146,"n":"ר\u0027 יונתן בן שאול","l":"י","b":"מובא בברייתא (סנהדרין נ\"ז ע\"א), ויש סבורים שצ\"ל: ר\u0027 יוחנן בן שאול."},{"i":2147,"n":"ר\u0027 יונתן בר יוסי","l":"י","b":"הוא ר\u0027 יונתן בר יוסף והוא ר\u0027 יונתן התנא."},{"i":2148,"n":"ר\u0027 יונתן בר יצחק בר אחא","l":"י","b":"מובא בירושלמי (פאה רפ\"ה)."},{"i":2149,"n":"ר\u0027 יונתן דבית גוברין","l":"י","b":"אמורא ארץ ישראלי בדור השני. מבעלי האגדה. מסר בשם ר\u0027 יהושע בן לוי (שהש\"ר פ\"א - א\u0027). ר\u0027 סימון מסר בשמו (ירו\u0027, יומא פ\"ז ה\"ג)."},{"i":2150,"n":"יונתן הקטיני","l":"י","b":"תנא בדור הרביעי. מובא בברייתא שחלק עם ר\u0027 נתן (עירובין צ\"ו ע\"א)."},{"i":2151,"n":"ר\u0027 יונתן ספרא דגיפתרא","l":"י","b":"מובא במסכת סופרים (פי\"ב ה\"ד), ואולי צ\"ל: ר\u0027 יוחנן ספרא דגופתא."},{"i":2152,"n":"ר\u0027 יונתן קיפא","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. אחיו מנחם בר מבסימא מסר בשם ר\u0027 אמי (ירו\u0027, סוף מעשרות)."},{"i":2153,"n":"יונתן שידא","l":"י","b":"מובא: \"א\"ר חנינא אמר לי יונתן שידא\" (יבמות קכ\"א ע\"א). ופרש\"י: \"שד היה או בקי בהן וגם אם נאמר שלא היה שד על כל פנים נראה שלא היה מן החכמים\"."},{"i":2154,"n":"ר\u0027 יונתן שר הבירה","l":"י","b":"מובא בב\"ר (פצ\"ה - ג\u0027). ונראה שהוא ר\u0027 יונתן רבו דר\u0027 שמואל בר נחמני."},{"i":2155,"n":"ר\u0027 יוסא סבא","l":"י","b":"מובא ב\"זוהר\" (תזריע ע\"ו) שדוסתאי סבא אמר משמו."},{"i":2156,"n":"יוסה","l":"י","b":"הוא יוסי."},{"i":2157,"n":"ר\u0027 יוסה בן ביביי","l":"י","b":"אמורא ארץ ישראלי שאין לקבוע את זמנו המדוייק. מובא בירושלמי (מגילה פ\"ד ה\"ט), שהיה שונה ברייתות."},{"i":2158,"n":"ר\u0027 יוסה בר אביי","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. ר\u0027 יוחנן מסר משמו, הוא אבא יוסף בר אבא (חולין צ\"ז ע\"א)."},{"i":2159,"n":"יוסה בריה דר\u0027 יהושע בן לוי","l":"י","b":"מובא בירושלמי (תענית פ\"א ה\"ו), והוא רב יוסף בריה דר\u0027 יהושע בן לוי."},{"i":2160,"n":"רבי יוסה גלילייא","l":"י","b":"מובא בירושלמי (שבת פ\"ג ה\"ז). והוא רבי יוסי גלילאה."},{"i":2161,"n":"יוסה חפני","l":"י","b":"מובא בירושלמי (כתובות פי\"ב ה\"ג). והוא יוסף חפני."},{"i":2162,"n":"ר\u0027 יוסטא","l":"י","b":"מובא בירושלמי (ב\"מ פ\"י ה\"ב), ונראה, שהוא וסטיני תלמידיו דר\"ל."},{"i":2163,"n":"ר\u0027 יוסטא בר מתון (2)","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של ר\u0027 יוחנן (זבחים צ\"ט ע\"א). ע\"ע ר\u0027 דוסתאי בר מתון."},{"i":2164,"n":"ר\u0027 יוסטא בר שונה","l":"י","b":"מובא בירושלמי (עירובין פ\"א ה\"י), וצ\"ל: ר\u0027 יוסא בר שונם."},{"i":2165,"n":"ר\u0027 יוסטא בר שונם","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. תלמידו של ר\u0027 מנא (ירו\u0027, תרומות פי\"א ה\"ד). מסר גם בשם ר\u0027 יהושע דסכנין (תנחומא ויצא - ו\u0027)."},{"i":2166,"n":"ר\u0027 יוסטאי בר מתון","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של ר\u0027 יוחנן (זבחים צ\"ט ע\"א)."},{"i":2167,"n":"ר\u0027 יוסטי בר סימון","l":"י","b":"מובא בירושלמי (עירובין פ\"ו ה\"ד), שאמר משמו של ר\u0027 בייתוס."},{"i":2168,"n":"יוסטי חברא","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. מסר בשם רבי ברכיה (ב\"ר רפ\"ו)."},{"i":2169,"n":"ר\u0027 יוסטיני","l":"י","b":"מובא בירושלמי (ב\"ב פ\"ח ה\"ה), והוא וסטיני תלמידו דר\"ל."},{"i":2170,"n":"יוסטני","l":"י","b":"מובא בבבלי (ב\"מ קי\"ז ע\"א). כן גיר\u0027 \"דק\"ס\". ולפנינו: וסטיני."},{"i":2171,"n":"יוסי","l":"י","b":"ע\"ע רב יוסף."},{"i":2172,"n":"רב יוסי","l":"י","b":"מובא בבבלי (עירובין י\"ח ע\"ב), והוא רב יוסף מראשי רבנן סבוראי."},{"i":2173,"n":"רבי יוסי (2)","l":"י","b":"מגדולי אמוראי ארץ ישראל בדור הרביעי - החמישי. חברו של ר\u0027 יונה, ושניהם היו תלמידים של ר\u0027 אלעאי (ירו\u0027, תרומות פ\"ב ה\"ד), ר\u0027 זירא (ירו\u0027, כלאים פ\"א ה\"א) ור\u0027 ירמיה (ירו\u0027, ברכות פ\"א ה\"ב). לאחר פטירת ר\u0027 אמי ור\u0027 אסי הם היו גדולי הדור בארץ ישראל, בימי גזירות הם התירו לאפות לחם בשבת בשביל ראש החיל וחיילותיו (ירו\u0027, סנהדרין פ\"ג ה\"ה), ושניהם באו לקבל פני המלך באנטוכיא (ירו\u0027, ברכות פ\"א ה\"א). כשמת בנו של ר\u0027 יוסי צם ר\u0027 יונה (ירו\u0027, נדרים פ\"ח ה\"א). ר\u0027 יונה נפטר לפני ר\u0027 יוסי (ירו\u0027, מעשרות פ\"ד ה\"ו). בין תלמידיו הרבים היה בנו של ר\u0027 יונה ר\u0027 מנא, שהיה ראש הדור החמישי בא\"י (ירו\u0027, ברכות פ\"א ה\"ב). כשנפטר ר\u0027 יוסי נטמאו לו תלמידיו הכהנים (שם פ\"ג ה\"א)."},{"i":2174,"n":"ר\u0027 יוסי איש צייתור","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. ר\u0027 ברכיה כינהו חסיד, וסיפר כיצד הבריח רוח שרצתה להזיק (תנחומא פ\u0027 קדושים - ט\u0027)."},{"i":2175,"n":"ר\u0027 יוסי אלעאי","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. רבי פנחס מסר משמו (ירו\u0027, מגילה פ\"א הי\"ב)."},{"i":2176,"n":"ר\u0027 יוסי אשיין","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם רבי שמעון בן לקיש (ירו\u0027, סוכה פ\"ד ה\"ו)."},{"i":2177,"n":"ר\u0027 יוסי בן אלישע","l":"י","b":"תנא שאין לקבוע זמנו המדוייק. מובא בבבלי (שבת קל\"ט ע\"א)."},{"i":2178,"n":"יוסי בן גילאי","l":"י","b":"תנא בדור השלישי. \"מעשה ושאלו את רבן גמליאל א\"ל: צאו ושאלו את יוסי בן גילאי שהוא בר ובקי בהלכות כלאי הכרם\" (תוספתא כלאים פ\"ג)."},{"i":2179,"n":"רבי יוסי בן דולגאי","l":"י","b":"מובא בבבלי (יומא ל\"ט ע\"ב), והוא רבי אלעזר בן דגלאי."},{"i":2180,"n":"רבי יוסי בן דורמסקית","l":"י","b":"תנא בדור השלישי. תלמידו המובהק של רבי אליעזר (חגיגה ג\u0027 ע\"ב). כשר\u0027 אליעזר כעס עליו התעוור ר\u0027 יוסי, ולאחר שדעתו של ר\"א התיישבה עליו ריפא אותו ושב לראות (שם). מסר גם משום רבי יוסי הגלילי (קידושין ל\"ט ע\"א). אמר לר\u0027 יהודה [תלמידו של ר\"ע]: למה אתה מעוות עלינו את הכתובים (ספרי דברים פיסקא א\u0027). ר\u0027 אלעזר בר יוסי מסר משמו (קידושין שם)."},{"i":2181,"n":"ר\u0027 יוסי בן החוטף אפרתי","l":"י","b":"תנא בדור הרביעי. תלמידו של ר\u0027 ישמעאל. חלק עם רבי מאיר (כלאים פ\"ג מ\"ז)."},{"i":2182,"n":"רבי יוסי בן המשולם","l":"י","b":"תנא בדור החמישי. הוא ור\u0027 שמעון בן מנסיא מכונים \"עדה קדושה\" (ירו\u0027, מע\"ש פ\"ב ה\"ד), משום שהיו משלשין את היום שליש לתורה, שליש לתפילה, שליש למלאכה: ויש אומרים שהיו יגעין בתורה בימות החורף ובמלאכה בימות הקיץ (קה\"ר פ\"ט - ט\u0027). מסר בשם אחיו ר\u0027 יוחנן, שאמר משום ר\u0027 אלעזר בג חסמא (גיטין ס\"ב ע\"א). חלק עם חנינא בן חכינאי ורבי (מנחות ס\"ב ע\"א)."},{"i":2183,"n":"ר\u0027 יוסי בן זמרא","l":"י","b":"מאחרוני התנאים. מגדולי הדור בדורו של רבי. בנו של רבי התחתן עם בתו (כתובות ס\"ב ע\"ב). שמו נזכר בברייתא (מכילתא ויהי בשלח פ\u0027 ויסע). האריך ימים וחי בזמנו של ר\u0027 יהודה נשיאה א\u0027 (יומא ע\"ח ע\"א). בשמו מסרו ר\u0027 יוחנן (שבת ק\"ה ע\"א) ור\u0027 אלעזר (ברכות ל\"א ע\"ב)."},{"i":2184,"n":"ר\u0027 יוסי בן זעירא דכפר ראמין","l":"י","b":"מובא ב\"זוהר\" (שמיני ל\"ט ע\"ב)."},{"i":2185,"n":"יוסי בן חוני","l":"י","b":"תנא שאין לקבוע את זמנו המדוייק. מובא במשנה (זבחים ב\u0027 ע\"א)."},{"i":2186,"n":"רבי יוסי בן חלפתא","l":"י","b":"תנא בדור הרביעי, והוא רבי יוסי סתם במשנה ובברייתא (זבחים נ\"ח סע\"ב רש\"י). מוצא משפחתו היה מבבל (יומא ס\"ו ע\"ב רש\"י). מושבו היה ציפורי (ב\"ב ע\"ה ע\"ב), שם היתה לו ישיבה גדולה (סנהדרין ל\"ב ע\"ב). תלמידו המובהק של רבי עקיבא (פסחים י\"ח ע\"א). כשמתו תלמידי ר\"ע מסופר: \"והיה העולם שמם, עד שבא רבי עקיבא אצל רבותינו שבדרום ושנאה להם: ר\u0027 מאיר, ר\u0027 יהודה, ור\u0027 יוסי, ור\u0027 שמעון ור\u0027 אלעזר בן שמוע, והם הם העמידו תורה אותה שעה\" (יבמות ס\"ב ע\"ב). הוסמך על ידי ר\u0027 יהודה בן בבא (סנהדרין י\"ד ע\"א). קיבל מאביו ר\u0027 חלפתא (בכורות כ\"ו ע\"א), ומאבטולמוס, (עירובין ל\"ו ע\"א). חברם של רשב\"ג ור\u0027 יהודה (פסחים ק\u0027 ע\"א). בין תלמידיו הרבים היה רבינו הקדוש (נדה ס\"ח ע\"ב), שאמר עליו: \"שכשם שבין קדשי הקדשין לבין חולי חולין, כך בין דורנו לדורו של ר\u0027 יוסי\" (ירו\u0027, גיטין פ\"ו ה\"ז). תוספות סובר שרבי בזקנותו היה גדול מר\u0027 יוסי (שבת נ\"א ע\"א תד\"ה: אילו). יבם את אשת אחיו, והיא ילדה לו חמישה תנאים: ר\u0027 ישמעאל, ר\u0027 אלעזר, ר\u0027 מנחם, ר\u0027 חלפתא ור\u0027 אבדימוס (ירו\u0027, ריש יבמות). \"ואמר ר\u0027 יוחנן: \u0027מאן תנא סדר עולם [העוסק בסדרי זמנים ומאורעות הסטוריים] - רבי יוסי\u0027\" (יבמות ס\"ב ע\"ב). אליהו הנביא היה רגיל אצלו וקראו \"רבי\" (ברכות ג\u0027 ע\"א). יותר משלש מאות פעמים מובא שמו במשנה וכן בתוספתא. רגיל היה להתוכח עם גויים בעניני אמונה ולנצחם (ב\"ר פ\"ד - ו\u0027 שם פס\"ח - ד\u0027). היה אומן מעבד עורות (שבת מ\"ט ע\"ב רש\"י). נפטר אחרי רבי מאיר (נזיר מ\"ט ע\"ב) ולפני רבי יהודה (סוכה י\"ח ע\"ב). ואמרו: \"משמת רבי יוסי, פסקה הבינה\" (ירו\u0027, סוף סוטה)."},{"i":2187,"n":"ר\u0027 יוסי בן חנמאל","l":"י","b":"מובא ב\"ילקוט\" (נחמיה רמז תתרע\"א)."},{"i":2188,"n":"ר\u0027 יוסי בן טרטס","l":"י","b":"מובא בויק\"ר (פ\"ז - ב\u0027), והוא ר\u0027 יוסי בן פטרוס."},{"i":2189,"n":"ר\u0027 יוסי בן יאסין","l":"י","b":"תנא בדור השלישי. חברו של ר\u0027 יהודה הנחתום, וביחד אמרו שניהם הלכה (תוספתא מנחות פ\"א ט\"ו)."},{"i":2190,"n":"ר\u0027 יוסי בן יהושע","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. ר\u0027 יוחנן מסר משמו (חולין נ\"ו ע\"ב)."},{"i":2191,"n":"יוסי בן יוחנן איש ירושלים","l":"י","b":"מחכמי ה\"זוגות\". הוא וחברו יוסי בן יועזר היו בתחילת תקופת ה\"זוגות\", מיד לאחר תקופת אנשי כנסת הגדולה. שימש כאב בית דין וחברו כנשיא. ע\"ע יוסי בן יועזר איש צרידה."},{"i":2192,"n":"ר\u0027 יוסי בן יוסי","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. מסר משום רבי יוחנן (ירו\u0027, גיטין פ\"א ה\"א), ומשום ר\u0027 יצחק בן אלעזר (ירו\u0027, תרומות פ\"א ה\"ה)."},{"i":2193,"n":"ר\u0027 יוסי בן יוסי בן יאסיין","l":"י","b":"מובא בבבלי (מנחות ו\u0027 ע\"ב), והוא ר\u0027 יוסי בן יאסין."},{"i":2194,"n":"רבי יוסי בן יוסי בן פרורה","l":"י","b":"מובא בירושלמי (עירובין פ\"א ה\"ב), והוא ר\u0027 יוסי פרידה תלמידו של רבי אליעזר."},{"i":2195,"n":"יוסי בן יועזר איש צרידה","l":"י","b":"מהחכמים הקדמונים. ראשון מחכמי ה\"זוגות\", חמישה דורות לפני התחלת תקופת התנאים. נשיא הסנהדרין. חברו ובן זוגו היה יוסי בן יוחנן איש ירושלים, ששימש אב בית דין (חגיגה ט\"ז ע\"א). שניהם קבלו מאנטיגנוס, ואולי אף משמעון הצדיק (אבות פ\"א מ\"ד). מנהיגי הדור הבא היו תלמידיהם: יהושע בן פרחיה ונתאי הארבלי (אבות פ\"א מ\"ד). \"היה חסיד שבכהונה\" (חגיגה י\"ח ע\"ב). \"מימות משה עד שמת יוסף בן יועזר היו למדין תורה כמשה רבינו\" (תמורה ט\"ו ע\"ב). ואמרו: \"משמת יוסי בן יועזר איש צרידה ויוסי בן יוחנן איש ירושלים, בטלו האשכולות\" (סוטה מ\"ז ע\"א). יוסי בן יועזר נהרג בתקופת שמד של היוונים על ידי בן אחיו הכהן הגדול, המתיוון אלקימוס (ב\"ר פס\"ה - כ\"ב)."},{"i":2196,"n":"רבי יוסי בן יסיאן","l":"י","b":"הוא ר\u0027 יוסי בן יאסין."},{"i":2197,"n":"ר\u0027 יוסי בן יעקב","l":"י","b":"תנא שחי לפני רבי שמעון בן יוחאי. מובא ב\"זוהר\" (ריש אידרא זוטא האזינו)."},{"i":2198,"n":"ר\u0027 יוסי בן יעקב איש כפר אונו","l":"י","b":"תנא בדור החמישי. מובא ב\"זוהר\" (שמות י\u0027 ע\"ב) ששאל לרבי מאיר."},{"i":2199,"n":"ר\u0027 יוסי בן כיפר","l":"י","b":"תנא בדור החמישי. חברו של ר\u0027 דוסתאי בר ינאי, ושניהם היו בבבל אצל ר\u0027 אחי בר\u0027 יאשיה (גיטין י\"ד ע\"א). בצעירותו שלחוהו לבבל יחד עם בן בנו של זכריה בן קבוטל, להשפיע על חנינא בן אחי ר\u0027 יהושע לחדול מעיבור שנים וקביעת חדשים (ברכות ס\"ג ע\"א). מסר משום רבי אלעזר (יבמות י\"א ע\"ב)."},{"i":2200,"n":"ר\u0027 יוסי בן משולם","l":"י","b":"הוא ר\u0027 יוסי בן המשולם."},{"i":2201,"n":"ר\u0027 יוסי בן נהוראי","l":"י","b":"נראה היה לומר שהיה אמורא ארץ ישראלי בדור הראשון, אך תוספות אומרים במפורש שהיה תנא (ב\"מ מ\"א ע\"ב ד\"ה: קרנא). שאל מר\u0027 יהושע בן לוי (חולין נ\"ז ע\"ב). חברו של ר\u0027 יוחנן בן ארזא (ע\"ז נ\"ח ע\"א). ר\u0027 יוחנן היה תלמידו (ב\"מ מ\"א ע\"ב רש\"י). חכמי ארץ ישראל רבים מסרו משמו."},{"i":2202,"n":"ר\u0027 יוסי בן סמאי","l":"י","b":"מובא בירושלמי (יומא פ\"ח ה\"ה). ע\"ע אבא יוסי בן סימאי."},{"i":2203,"n":"ר\u0027 יוסי בן עזי","l":"י","b":"מובא בירושלמי (שקלים פ\"ז ה\"ג)."},{"i":2204,"n":"ר\u0027 יוסי בן עזי דברדילה","l":"י","b":"מובא בירושלמי (שקלים פ\"ז ה\"ה - הנדפס בבבלי). אבל הגיר\u0027 בירושלמי: ר\u0027 יהודה בן פזי דברדילה."},{"i":2205,"n":"יוסי בן עקיבא","l":"י","b":"מובא בספרי (עקב י\"ח), והוא איסי בן עקביה."},{"i":2206,"n":"ר\u0027 יוסי בן פזי (2)","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מסר בשם ר\u0027 יוסי בן חנינא (ירו\u0027, שבת פ\"ד ה\"א)."},{"i":2207,"n":"ר\u0027 יוסי בן פטרוס","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. חותנו של ר\u0027 יהושע בן לוי. חברו של בר קפרא (ירו\u0027, מו\"ק פ\"ג ה\"ה) וחלק עמו באגדה (ב\"ר פצ\"ד - ה\u0027). מובאים פסוקים ששניהם אמרו בשעת פטירתם (ירו\u0027, ע\"ז פ\"ג ה\"א)."},{"i":2208,"n":"ר\u0027 יוסי בן פיטרס","l":"י","b":"מובא בירושלמי (ע\"ז פ\"ג ה\"א), והוא ר\u0027 יוסי בן פטרוס."},{"i":2209,"n":"יוסי בן פכסס","l":"י","b":"נראה שחי בזמן הבית. מובא מעשה ביוסי בן פכסס שעלתה על רגלו נומי כו\u0027 וחכמים אמרו עליו \"יש צדיק אובד וכו\u0027\" (ירו\u0027, נזיר פ\"ז ה\"א) אבל אין ראיה שהיה מן החכמים."},{"i":2210,"n":"ר\u0027 יוסי בן פרטא","l":"י","b":"תנא בדור השלישי. אמר משום רבי אליעזר (נדרים מ\"א ע\"א)."},{"i":2211,"n":"ר\u0027 יוסי בן פרידה","l":"י","b":"תנא בדור השלישי. תלמידו של רבי אליעזר (עירובין י\"א ע\"ב)."},{"i":2212,"n":"יוסי בן קיטונתא","l":"י","b":"מובא בירושלמי (סוף סוטה), והוא ר\u0027 יוסי קטנתא."},{"i":2213,"n":"רבי יוסי בן קיסמא","l":"י","b":"תנא בדור השלישי. הרביץ תורה והיו לו תלמידים הרבה (סנהדרין צ\"ח ע\"א). ר\u0027 חנינא בן תרדיון קרא לו: \"רבי\" (ע\"ז י\"ח ע\"א). בימיו היו גזירות קשות ונוראות, והוא היה מקורב למלכות, וכשנפטר הלכו כל גדולי רומי לקברו והספידוהו הספד גדול (שם). ולפני פטירתו אמר לר\u0027 חנינא בן תרדיון: \"תמה אני אם לא ישרפו אותך ואת ספר תורה באש\" (שם). ממנו המאמר: \"אם אתה נותן לי כל כסף וזהב ואבנים טובות ומרגליות שבעולם, איני דר אלא במקום תורה\" (אבות פ\"ו מ\"ט)."},{"i":2214,"n":"ר\u0027 יוסי בן שאול","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. תלמידו של רבי (ע\"ז נ\"ב ע\"ב). ורבי אמר לו: \"ברוך אתה לשמים שהחזרת לי אבידתי\" (שם). היה רבם של ר\u0027 יהושע בן לוי (ביצה י\"ד ע\"ב), ור\u0027 חייא בר גמדא (ר\"ה כ\"ד ע\"א). יתכן שר\u0027 יוחנן בן שאול היה אחיו (שבת קכ\"ה ע\"ב)."},{"i":2215,"n":"ר\u0027 יוסי בן תדאי איש טבריה","l":"י","b":"תנא בדור הרביעי. \"זו שאלה שאל ר\u0027 יוסי בר תדאי איש טבריה את רבן גמליאל\" (ד\"א רבה רפ\"א)."},{"i":2216,"n":"ר\u0027 יוסי בן תחליפא","l":"י","b":"מובא במדרש תהלים (פע\"ב), וסביר שצ\"ל: בן חלפתא."},{"i":2217,"n":"ר\u0027 יוסי בר אבא","l":"י","b":"מובא בבבלי (זבחים כ\"ה ע\"ב), ואולי הוא ר\u0027 יוסה בר אביי."},{"i":2218,"n":"ר\u0027 יוסי בר אבהו","l":"י","b":"מובא בבבלי (קי\"ב ע\"ב), ואולי צ\"ל: רב יוסף בר אבא."},{"i":2219,"n":"ר\u0027 יוסי בר אביי","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. רבי יוחנן מסר משמו (ירו\u0027, תענית פ\"ד ה\"ה): \"הלוחות היו מבקשין לפרוח והיה משה תופסן\"."},{"i":2220,"n":"ר\u0027 יוסי בר אבין","l":"י","b":"מגדולי ואחרוני אמוראי ארץ ישראל בדור החמישי. ירד לבבל (יבמות ע\"ה ע\"ב) וחזר לא\"י (ירו\u0027, פסחים פ\"י ה\"ב). שמו מובא פעמים רבות בתלמוד ירושלמי, ורב חלקו בסידור הירושלמי. הוא המסיים בו סוגיות רבות. אין כמעט חכמים אחריו שמסרו בשמו, מלבד \"חכמים דקסרין\" (ירו\u0027, שבת פ\"ח ה\"א). קיבל מתלמידי רבי יוחנן - ר\u0027 אבהו (ירו\u0027, ברכות פ\"ה ה\"א) ר\u0027 אבא (ירו\u0027, יבמות פ\"ד הי\"א). מסר בשם ר\u0027 יוסי בר חנינא (ירו\u0027, נזיר פ\"ד ה\"ה). חלק הרבה עם ר\u0027 יוסי בר זבידא (ברכות כ\"ב ע\"א)."},{"i":2221,"n":"ר\u0027 יוסי בר איבו","l":"י","b":"מובא בב\"ר (פל\"ד - י\"ג), ואולי הוא ר\u0027 יוסף בר אבא."},{"i":2222,"n":"ר\u0027 יוסי בר איקא","l":"י","b":"מובא בשהש\"ר (פ\"א פסוק משכני - ד\u0027)."},{"i":2223,"n":"ר\u0027 יוסי בר אליקים","l":"י","b":"מובא בבבלי (ברכות ט\u0027 ע\"ב). אם נניח שהוא אחיו של ר\u0027 שמעון בן אליקים, אם כן חי בא\"י בדור השלישי לאמוראים."},{"i":2224,"n":"ר\u0027 יוסי בר אלעזר בר ר\u0027 שמעון בר יוחאי","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. בן בנו של ר\u0027 שמעון בר יוחאי. מסופר שרבי בא למקומו ומצא שלא נהג כשורה, והחזירו למוטב, וכשנפטר רצו להכניסו למערת אביו ונחש ענקי חסם הדרך, ויצאה בת קול ואמרה: \"לא מפני שזה גדול מזה, אלא זה היה בצער מערה וזה לא היה בצער מערה\" (ב\"מ פ\"ה ע\"א)."},{"i":2225,"n":"ר\u0027 יוסי בר אסיין","l":"י","b":"מובא בבבלי (עירובין נ\"ג ע\"ב), ואולי הוא ר\u0027 יוסי אשיון."},{"i":2226,"n":"רבי יוסי בר אשיאן","l":"י","b":"הוא רבי יוסי אסיין."},{"i":2227,"n":"רבי יוסי בר ביבי","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. מסר בשם ר\u0027 שמואל [לא שמואל] (ירו\u0027, שקלים פ\"ג ה\"ב)."},{"i":2228,"n":"רבי יוסי בר ביבין","l":"י","b":"הוא רבי יוסי בר ביבי."},{"i":2229,"n":"ר\u0027 יוסי בר ביסא","l":"י","b":"מובא ב\"ילקוט\" (איוב רמז תתצ\"ז)."},{"i":2230,"n":"רבי יוסי בר ברתיה דרבי יוסי","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם אבי אמו רבי יוסי (ירו\u0027, נזיר פ\"ו ה\"א)."},{"i":2231,"n":"ר\u0027 יוסי בר גזירא","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. ר\u0027 יונה אמר בשמו (ירו\u0027, סוף ברכות)."},{"i":2232,"n":"ר\u0027 יוסי בר דוסא","l":"י","b":"מובא בב\"ר (פ\"ס - ז\u0027)."},{"i":2233,"n":"ר\u0027 יוסי בר הינא","l":"י","b":"מובא בבבלי (סנהדרין ק\"ה ע\"ב), ונראה שט\"ס וצ\"ל: ר\u0027 יוסי בר חנינא, כבמקומות אחרים כגון: (נזיר כ\"ג ע\"ב: הוריות י\u0027 ע\"ב)."},{"i":2234,"n":"ר\u0027 יוסי בר זבידא","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. חברו של ר\u0027 יוסי בר אבין (ברכות כ\"ב ע\"א). יתכן שבכל מקום שמוזכר ר\u0027 יוסי בר זבידא, הכוונה לר\u0027 יוסי סתם, האמורא הארץ ישראלי."},{"i":2235,"n":"ר\u0027 יוסי בר זבילא","l":"י","b":"מובא בבבלי (סוכה ל\"ז ע\"ב), ונראה ט\"ס וצ\"ל: ר\u0027 יוסי בר זבידא."},{"i":2236,"n":"ר\u0027 יוסי בר זמינא","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם ר\u0027 יוחנן (ירו\u0027, כלאים רפ\"ה)."},{"i":2237,"n":"ר\u0027 יוסי בר זעירא","l":"י","b":"אמורא ארץ ישראלי בדור השני. מסר בשם ר\u0027 יונתן (ירו\u0027, כתובות פ\"ה ה\"א)."},{"i":2238,"n":"רבי יוסי בר חנינא (2)","l":"י","b":"אמורא ארץ ישראלי מפורסם בדור השני - השלישי. מגדולי תלמידי ר\u0027 יוחנן ונסמך על ידו (סנהדרין ל\u0027 ע\"ב). כן מסר בשם ר\u0027 יהושע בן לוי (ירו\u0027, יומא רפ\"ח) ורבי אושעיא (ירו\u0027, ע\"ז פ\"ג ה\"ה). הנהיג ישיבה והיו לו תלמידים הרבה. כמה מתלמידי ר\u0027 יוחנן היו לתלמידיו וביניהם ר\u0027 אבהו (שבת צ\"ד ע\"ב) כל היכא שמצינו: \"מחכו עלה במערבא\", הכונה לר\u0027 יוסי בר חנינא (סנהדרין י\"ז ע\"ב). כמה מבניו נפטרו בחייו (תענית י\"ג ע\"ב). רבי זירא סיפר, שר\u0027 יוסי בר חנינא נראה לו בחלום, וסיפר לו שיושב בישיבה של מעלה אצל רבי יוחנן (ב\"מ פ\"ה ע\"ב)."},{"i":2239,"n":"ר\u0027 יוסי בר יאסיניאה","l":"י","b":"מובא בבבלי (ביצה ח\u0027 ע\"ב), ואולי הוא ר\u0027 יוסי בר אשיין."},{"i":2240,"n":"ר\u0027 יוסי בר יהודה","l":"י","b":"תנא בדור החמישי. בנו של התנא רבי יהודה בר אלעאי (מנחות ס\"ג ע\"ב). בר פלוגתיה וחברו של רבי (נדרים ס\"ב ע\"א: בכורות נ\"א ע\"א), ומצינו את שניהם יחד (נדרים שם). פעמים שסתם רבי המשנה אליביה (עירובין ל\"ח ע\"ב רש\"י) \"שראה רבי דבריו במקומות הרבה ושנאן במשנה סתם\". נראה שנפטר לפני רבי: \"שלשה דברים צוה רבי יוסי בר יהודה את רבי\" (פסחים קי\"ב ע\"ב). וממנו המאמר: \"תניא רבי יוסי בר יהודה: שני מלאכי השרת מלוין לו לאדם בערב שבת מבית הכנסת לביתו וכו\u0027\" (שבת קי\"ט ע\"ב)."},{"i":2241,"n":"ר\u0027 יוסי בר יהודה איש כפר הבבלי","l":"י","b":"תנא שאין לקבוע את זמנו המדוייק. ממנו המאמר: \"הלומד מן הקטנים למה הוא דומה? לאוכל ענבים קהות וכו\u0027\" (אבות פ\"ד מ\"כ)."},{"i":2242,"n":"ר\u0027 יוסי בר יעקב","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. הלך לבקר את חברו של ר\u0027 יודן מגדליא ושמע מפיו תפילת הודיה על הגשם, שאותה קיבל מר\u0027 סימון (ירו\u0027, ברכות פ\"ט ה\"ב)."},{"i":2243,"n":"ר\u0027 יוסי בר יעקב בר זבדי","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. אמר בשם רבי אבהו (ירו\u0027, פאה פ\"א ה\"א)."},{"i":2244,"n":"ר\u0027 יוסי בר יצחק","l":"י","b":"מובא בב\"ר (פמ\"א - ד\u0027). יתכן שיש ט\"ס בשם, וצ\"ל: ר\u0027 טובי בר יצחק."},{"i":2245,"n":"ר\u0027 יוסי בר ירמיה","l":"י","b":"מובא בשהש\"ר (ספ\"ד)."},{"i":2246,"n":"ר\u0027 יוסי בר ממל","l":"י","b":"מובא בירושלמי שאמר: \"כהנת מותרת לצאת וכו\u0027\" (קידושין פ\"א ה\"ז), ואותו מאמר מובא בשם ר\u0027 דוסא ממלחיא (ירו\u0027, סוטה פ\"ג ה\"ז)."},{"i":2247,"n":"יוסי בר מניישא","l":"י","b":"מובא בירושלמי (מגילה פ\"ב ה\"ד), שאמר בשם רב. סביר לומר שהוא ר\u0027 יוסף בריה דרב מנשיא מדויל תלמידו של רב."},{"i":2248,"n":"יוסי בר מנשיא","l":"י","b":"מובא בירושלמי (סוכה פ\"ג ה\"ב), שאמר בשם רב. סביר לומר שהוא ר\u0027 יוסף בריה דרב מנשיא מדויל תלמידו של רב."},{"i":2249,"n":"ר\u0027 יוסי בר נחמיה","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. מסר בשם לוי (פסדר\"כ ס\"פ רני עקרה)."},{"i":2250,"n":"ר\u0027 יוסי בר נחמן","l":"י","b":"תנא. מובא ב\"זוהר\" (חדש בראשית פ\u0027 אלה תולדות שמים)."},{"i":2251,"n":"ר\u0027 יוסי בר נתן","l":"י","b":"מובא בבבלי (ב\"ב קכ\"א ע\"א), והוא ר\u0027 אסי בר נתן."},{"i":2252,"n":"ר\u0027 יוסי בר סימון","l":"י","b":"אמורא ארץ ישראלי בדור השני. מסר משום ר\u0027 יהושע בן לוי (ירו\u0027, מע\"ש פ\"ד ה\"ב)."},{"i":2253,"n":"ר\u0027 יוסי בר קסריי","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. מצינו שחלק עם ר\u0027 תנחומא (שהש\"ר פ\"ו - ד\u0027)."},{"i":2254,"n":"ר\u0027 יוסי בר קצרתא","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. ר\u0027 יוחנן מסר בשמו (שבת קנ\"א ע\"ב). כן מסר בשמו ר\u0027 שמעון בר חנן (מדרש תהלים פע\"ח)."},{"i":2255,"n":"ר\u0027 יוסי בר רב כהנא","l":"י","b":"אמורא בדור השני. אמר בשם שמואל (ירו\u0027, ברכות פ\"ח ה\"ב)."},{"i":2256,"n":"ר\u0027 יוסי בר שונם","l":"י","b":"מובא בתנחומא (בשלח - י\"א), וצ\"ל: ר\u0027 יוסטא בר שונם."},{"i":2257,"n":"ר\u0027 יוסי בר שלום","l":"י","b":"מובא במדרש תהלים (הישן רפע\"ב), ונראה שיש ט\"ס בשם."},{"i":2258,"n":"ר\u0027 יוסי בר שמעון בר אבא","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. מסר משם רבי יוחנן (ירו\u0027, סוף ברכות)."},{"i":2259,"n":"רבי יוסי בריבי","l":"י","b":"מובא בירושלמי (סוכה פ\"ב ה\"ה), והוא רבי יוסי בר חלפתא, ובריבי פירושו גדול הדור."},{"i":2260,"n":"ר\u0027 יוסי בריה דרב חסדא","l":"י","b":"מובא ב\"זוהר\" (חדש רות פ\"א)."},{"i":2261,"n":"ר\u0027 יוסי בריה דר\u0027 יעקב בר אידי","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. אמר בשם ר\u0027 אחא (מדרש תהלים פפ\"א - ד\u0027). נראה שהוא בנו של האמורא ר\u0027 יעקב בר אידו."},{"i":2262,"n":"ר\u0027 יוסי בריה דר\u0027 תנחום מכפר אגין","l":"י","b":"מובא בירושלמי (שבת פ\"ב ה\"ו)."},{"i":2263,"n":"ר\u0027 יוסי גלילאה","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידו של ר\u0027 יוסי בר חנינא ומסר משמו (ירו\u0027, ברכות פ\"ג ה\"א). \"פעם איקלע לאתריה דר\u0027 יוסי בר חנינא, טילטל שרגא, ואיקפד ר\u0027 יוסי בר חנינא\" (שבת מ\"ו ע\"א)."},{"i":2264,"n":"ר\u0027 יוסי דכפר דן","l":"י","b":"מובא בירושלמי (דמאי פ\"ב ה\"א), שאמר בשם רבי בן מעדיה."},{"i":2265,"n":"ר\u0027 יוסי דכפר חנן","l":"י","b":"תנא. מובא ב\"זוהר\" (פ\u0027 לך פ\"ז ב\u0027)."},{"i":2266,"n":"ר\u0027 יוסי דמן יוקרת","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. רבו של ר\u0027 יוסי בר אבין (תענית כ\"ג ע\"ב). ור\u0027 יוסי בר אבין בא לפני ר\u0027 אשי וסיפר לו שעזב את רבו, כי לא חס על בנו ובתו. בנו אמר פעם לעץ תאנה: \"תאנה תאנה, הוציאי פירותיך ויאכלו פועלי אבא\" וכך היה, אמר לו אביו \"בני, אתה הטרחת את קונך להוציא תאנה פירותיה שלא בזמנו, יאסף שלא בזמנו\" [ומת בנו] וכן סופר שבתו בעלת יופי היתה, ואחד הסתכל בה דרך הגדר לראות ביופיה, אמר לה \"בתי קא מצערת להו לברייתא, שובי לעפריך ואל יכשלו בך בני אדם\" [ומתה] (שם)."},{"i":2267,"n":"ר\u0027 יוסי דמן קיסרי","l":"י","b":"מובא בבבלי (סנהדרין ק\"ח ע\"א). \"סה\"ד\" כתב שהוא ר\u0027 אסי דקיסרין."},{"i":2268,"n":"ר\u0027 יוסי דפקיעין","l":"י","b":"תנא בדור החמישי. מובא ב\"זוהר\" (פ\u0027 בלק ר\"ד ע\"ב)."},{"i":2269,"n":"ר\u0027 יוסי דרומייא","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. תלמידו של ר\u0027 יונה (ירו\u0027, שבועות פ\"א ה\"ה)."},{"i":2270,"n":"ר\u0027 יוסי הארוך","l":"י","b":"תנא בדור החמישי. משרתו של רבי (ב\"ר פצ\"ז - ג\u0027, וש\"ר פ\"ב - ה\u0027). ופירש הרד\"ל שהוא יוסף חפני המובא בבבלי (כתובות ק\"ג ע\"א). נפטר קודם לרבי (שם)."},{"i":2271,"n":"יוסי הבבלי","l":"י","b":"מובא בירושלמי (ב\"ק פ\"ג ה\"ז), והוא איסי בן עקביה."},{"i":2272,"n":"ר\u0027 יוסי הגלילי","l":"י","b":"תנא בדור השלישי. נמנה עם ראשי הזקנים, מראשי חכמי יבנה, ומוזכר לפני רבי טרפון, רבי אלעזר בן עזריה ורבי עקיבא (גיטין פ\"ג ע\"א), וכן מוזכר לפני ראב\"ע ור\"ע (מו\"ק כ\"ח ע\"ב). תוספות כתבו שר\u0027 יוסי הגלילי היה תלמיד חבר לר\"ע (ע\"ז מ\"ה ע\"א תד\"ה: אמר). ואילמלא תוספות, חשבנו להיפך, שר\u0027 יוסי הגלילי גדול מרבי עקיבא, או לפחות חברו ממש, שכן רבי אלעזר בן עזריה היה תלמידו (ירו\u0027, כתובות פי\"א ה\"ג). התוכח בהלכה עם ר\"ט ור\"ע וניצחם (זבחים נ\"ז ע\"א). לר\"ע אמר: \"עקיבא, אפילו אתה מרבה כל היום כולו, איני שומע לך\" (זבחים פ\"ב ע\"א). האומרים בשמו: ר\u0027 אלעזר (שם מ\"ד ע\"א) ור\u0027 יהודה (שבועות כ\"א ע\"א). בכוחו היה להוריד גשם (ירו\u0027, ברכות פ\"ה ה\"ב). שני בניו היו תנאים מפורסמים בדור הרביעי: ר\u0027 אלעזר בנו של ר\u0027 יוסי הגלילי (ברכות ס\"ג ע\"ב) ור\u0027 חנינא בנו של ר\u0027 יוסי הגלילי (ר\"ה ל\"ב ע\"א)."},{"i":2273,"n":"ר\u0027 יוסי החורם","l":"י","b":"תנא שאין לקבוע את זמנו המדוייק. מובא בבבלי (מנחות ל\"ז ע\"א). ר\u0027 נתן מוסיף על דבריו (שם)."},{"i":2274,"n":"רבי יוסי הכהן","l":"י","b":"תנא בדור השני. אחד מחמשת תלמידיו המובהקים ביותר של רבי יוחנן בן זכאי, ונזכר שלישי לפני ר\u0027 שמעון בן נתנאל ור\u0027 אלעזר בן ערך (אבות פ\"ב מ\"ח). היה בזמנו של ר\"ג (ר\"ה י\"ז ע\"ב). העיד עם ר\u0027 זכריה בן הקצב (עדיות פ\"ח מ\"ב). ריב\"ז קראו: \"חסיד\" (שם). פעם הלך עם ר\u0027 יהושע ודרשו במעשה המרכבה \"והיו מלאכי השרת מתקבצין ובאין לשמוע, כבני אדם שמתקבצין ובאין לראות\" (חגיגה י\"ד ע\"ב)."},{"i":2275,"n":"ר\u0027 יוסי הכהן","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. מובא בבבלי: \"א\"ל ר\u0027 אבא הכהן לר\u0027 יוסי הכהן: \u0027אמאי אישתוק ר\u0027 יוחנן לר\"ל\u0027\" (ר\"ה ט\"ו ע\"ב)."},{"i":2276,"n":"ר\u0027 יוסי המודעי","l":"י","b":"תנא בדור השלישי. מובא במכילתא (בשלח ט\"ז - ז\u0027) שמביא ראיה לדברי ר\u0027 אלעזר המודעי."},{"i":2277,"n":"ר\u0027 יוסי זוטא","l":"י","b":"תנא. מובא ב\"זוהר\" (וארא כ\"ט)."},{"i":2278,"n":"ר\u0027 יוסי חסידא","l":"י","b":"תנא שאין לקבוע את זמנו המדוייק. מובא בירושלמי: \"משמת ר\u0027 יוסי חסידא ור\u0027 יוסי קטונתא, פסקו אנשי חסידות\" (סוף סוטה)."},{"i":2279,"n":"ר\u0027 יוסי מדאה","l":"י","b":"מובא בבבלי (חולין נ\"א ע\"א). לפי רש\"י (שם) היה תלמידו של רבי. וזה פלא גדול, וכבר השיג עליו ה\"יוחסין\". ר\u0027 עוירא סיפר לאביי שר\u0027 הונא ציפוראה ורבי יוסי מדאה, ישבו לפני רבי וכו\u0027 (שם)."},{"i":2280,"n":"ר\u0027 יוסי ממלחיא","l":"י","b":"אמורא ארץ ישראלי בדור הראשון - השני. שאל מר\u0027 מנא א\u0027 (ירו\u0027, ע\"ז פ\"ב ה\"ד). נפטר בחיי ר\u0027 יוחנן ור\"ל, והם ליווהו (איכ\"ר פ\"א - ל\"ז)."},{"i":2281,"n":"ר\u0027 יוסי מנהרביל","l":"י","b":"מובא בבבלי (חולין קל\"ו ע\"א). ע\"ע ר\u0027 אסי מנהרביל."},{"i":2282,"n":"יוסי מעוני","l":"י","b":"אמורא ארץ ישראלי בדור השני. פגע בכבוד הנשיאות בדרשה, ור\u0027 יוחנן ור\"ל הלכו לר\u0027 יהודה נשיאה לפייסו, והעידו עליו שהוא גברא רבא (ירו\u0027, סנהדרין ספ\"ב)."},{"i":2283,"n":"ר\u0027 יוסי צוודניה","l":"י","b":"מובא בירושלמי (יבמות פ\"ט ה\"ד), והוא ר\u0027 יוסי ציידניא."},{"i":2284,"n":"ר\u0027 יוסי צידונייא","l":"י","b":"מובא בירושלמי (כתובות פי\"א ה\"ז), והוא ר\u0027 יוסי ציידניא."},{"i":2285,"n":"רבי יוסי ציידניא","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של ר\u0027 ירמיה (יבמות פ\"ט ה\"ד). מסר בשם ר\u0027 יוחנן (ירו\u0027, ברכות פ\"ד ה\"ד). שמו מובא בכמה אופנים: ציידנייה, צידוניא, ציידניה."},{"i":2286,"n":"ר\u0027 יוסי ציידנייה","l":"י","b":"מובא בירושלמי (נזיר ספ\"ז), והוא ר\u0027 יוסי ציידניא."},{"i":2287,"n":"רבי יוסי קטנותא","l":"י","b":"תנא שאין לקבוע את זמנו המדוייק. מובא במשנה: \"משמת רבי יוסי קטנתא, פסקו חסידים, ולמה נקרא שמו קטנותא? שהיה קטנותן של חסידים\" (סוטה מ\"ט ע\"א). ובירושלמי במשנה (סוף סוטה): \"משמת רבי חנינא בן דוסא ויוסי בן קיטונתא פסקה החסידות, ולמה נקרא שמו יוסי בן קיטונתא? שהיה תמציתן של חסידים\" ובגמרא שם: \"שהיה תמציתן של צדיקים\"."},{"i":2288,"n":"רבי יוסי קטנתא","l":"י","b":"מובא בבבלי (סוטה מ\"ט ע\"א), והוא איסי בן עקביה."},{"i":2289,"n":"ר\u0027 יוסנא","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי אמי (ע\"ז ל\"ג ע\"ב)."},{"i":2290,"n":"רב יוסף (2)","l":"י","b":"מגדולי אמוראי בבל בדור השלישי. שם אביו חייא (חולין י\"ח ע\"ב). ריש מתיבתא בישיבת פומבדיתא (סוף ברכות), משנת ד\u0027 פ\u0027 (023) בערך במשך שנתיים וחצי (\"אגרת רב שרירא גאון\"). תלמידם המובהק של רב הונא (שבת קכ\"ט ע\"ב) ורב יהודה (חולין שם). קיבל גם מרב נחמן (יבמות ס\"ו ע\"ב). חבריו הגדולים ממנו היו ר\u0027 אבא: \"יתיב רב יוסף אחורי דר\u0027 אבא ויתיב ר\u0027 אבא קמיה דרב הונא\" (ב\"ק ק\"ב ע\"א) ור\"ה בר חייא: \"יתיב רב יוסף אחורי דרב הונא בר חייא\" (ב\"ק קט\"ז ע\"ב). חברו המובהק היה רבה: \"רבה ורב יוסף אמוראי דנהרדעא\" (סנהדרין י\"ז ע\"ב). מצינו פעמים רבות: \"רבה ורב יוסף דאמרי תרוייהו\" (זבחים י\"ד ע\"ב), ומחלוקות רבות ביניהם מובאות בש\"ס. אחרי פטירת ר\u0027 יהודה רצו למנות את ר\u0027 יוסף לריש מתיבתא, שכן הוא היה \"סיני\" (הוריות י\"ד ע\"א, פרש\"י: \"שהיו משניות וברייתות סדורות לו כנתינתן מהר סיני\"), אך רב יוסף ביקש שרבה חברו ימלוך לפניו, ואחרי פטירת רבה, מלך ר\u0027 יוסף (ברכות שם). היו לו תלמידים רבים, וארבע מאות מתלמידיו היו מאוכלי שולחנו (כתובות ק\"ו ע\"א רש\"י). מגדולי תלמידיו היו אביי (קדושין ל\"ג ע\"א) ורבא (יומא נ\"ג ע\"א). נראה, שאביי היה בסוף ימיו תלמיד - חבר לר\u0027 יוסף (עירובין י\u0027 ע\"א). חלה ושכח תלמודו ואביי הזכיר לו מדי פעם (נדרים מ\"א ע\"א). הגמרא אומרת: (פסחים קי\"ג ע\"ב): \"ג\u0027 חייהן אינן חיים: הרחמנין והרתחנין ואניני הדעת. ואמר ר\u0027 יוסף: \u0027כולהו איתנהו בי\u0027\" (בי יש כל אלו). היה סגי נהור (שבת ק\"ט ע\"א). והרמב\"ן בחידושיו (קדושין ל\"א ע\"א) מביא שסימא עצמו, כי לא רצה להסתכל מחוץ לד\u0027 אמותיו. ו\"סה\"ד\" מביא מספר מקור חיים, שישב ר\u0027 יוסף בבית אפל מ\u0027 יום, וצוה להביא לפניו אבני שיש, והסתכל בהם ונעשה סגי נהור. צם 021 תעניות וביקש רחמים שלא תמוש התורה מזרעו וזרע זרעו (ב\"מ פ\"ה ע\"א). היה בקי בתרגום (ב\"ק ג\u0027 ע\"ב תד\"ה: כדמתרגם). גדול היה כיבוד אם שלו, ומספרת הגמרא כי כאשר שמע קול צעדי אמו, היה אומר: אקום מפני שכינה שבאה (קידושין ל\"א ע\"ב). כשנפטר, ישב אביי על כסאו (גיטין ס\u0027 ע\"א, ושם ברש\"י)."},{"i":2291,"n":"רבי יוסף","l":"י","b":"ע\"ע רבי יוסי."},{"i":2292,"n":"יוסף איש הוצל (2)","l":"י","b":"מובא בבבלי (פסחים קי\"ג ע\"ב), והוא איסי בן עקביה (ע\"ע)."},{"i":2293,"n":"יוסף אפרתי","l":"י","b":"מובא בירושלמי (כתובות פי\"ב ה\"ג), והוא שמעון אפרתי."},{"i":2294,"n":"רב יוסף בן זמרא","l":"י","b":"הוא ר\u0027 יוסי בן זמרא הכהן."},{"i":2295,"n":"רב יוסף בן חוני","l":"י","b":"אמורא מובא בבבלי (סנהדרין ק\"ה ע\"ב)."},{"i":2296,"n":"יוסף בן יהודה","l":"י","b":"מובא בירושלמי (ב\"ק פ\"ג ה\"ז), והוא איסי בן עקביה."},{"i":2297,"n":"יוסף בן יועזר","l":"י","b":"מובא בבבלי (תמורה ט\"ו ע\"ב), והוא יוסי בן יועזר איש צרידה."},{"i":2298,"n":"ר\u0027 יוסף בן סימאי","l":"י","b":"אפוטרופוס של מלך היה, ונפלה בשבת דליקה בחצרו, ולא נתן לכבות הדליקה מפני כבוד השבת, ונעשה לו נס וירדו גשמים וכיבו את האש (שבת קכ\"א ע\"א). נראה, שאולי הוא אבא יוסי בן סימאי."},{"i":2299,"n":"רב יוסף בר אבא","l":"י","b":"אמורא בבלי בדור השלישי - הרביעי. ור\u0027 ששת אמר לו: \"אסברא לך\" (עירובין ז\u0027 ע\"ב). קיבל גם מרב עוקבא (ב\"ב קמ\"ד ע\"ב). היה כחבר לרבה: \"רבה ורב יוסף בר אבא דאמרי תרוייהו\" (שבת ק\"ח ע\"ב)."},{"i":2300,"n":"רב יוסף בר אבדימי","l":"י","b":"אמורא בבלי בדור השלישי. נראה בזמנו של ר\"נ: \"אמר רב יוסף: \u0027בר אבדימי תנא וחכמים אוסרין\u0027, אמר רב נחמן: \u0027הלכה כדברי חכמים\u0027\" (עירובין ח\u0027 ע\"א)."},{"i":2301,"n":"רב יוסף בר אמי","l":"י","b":"אמורא בבלי. חי אחרי רבא: \"רב יוסף בר אמי רמי וכו\u0027 ומשני מי אמר רבא [כצ\"ל]\" (זבחים ג\u0027 ע\"ב)."},{"i":2302,"n":"רב יוסף בר דוסאי","l":"י","b":"מובא בבבלי (חולין מ\"ט ע\"א). גיר\u0027 \"דק\"ס\": \"אבא יוסי בן דוסתאי\", וגירסת הרי\"ף אבא יוסי בן ביסא (חולין ט\"ו)."},{"i":2303,"n":"רב יוסף בר חבו","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. רמי לר\u0027 אבהו (יומא פ\"ז ע\"א)."},{"i":2304,"n":"יוסף בר חייא","l":"י","b":"מובא בבבלי (חולין י\"ח ע\"ב), והוא רב יוסף."},{"i":2305,"n":"רב יוסף בר חמא","l":"י","b":"אמורא בבלי בדור השלישי. אביו של האמורא המפורסם רבא (ב\"ק צ\"ז ע\"א). מושבו היה במחוזא, ונראה שהיה הריש בעירו (ב\"ב קכ\"ז ע\"ב). תלמידם של רב ששת (ב\"מ ע\"ב ע\"ב), ור\u0027 נחמן (גיטין מ\"ג ע\"ב). ר\u0027 אבא שלח לו מארץ ישראל כמה הלכות (ב\"ב שם)."},{"i":2306,"n":"רב יוסף בר חנין","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. וגירסת \"יתו\"א\": רב יוסף בר חבישמיא. שאל מר\u0027 אבהו (שבת קט\"ז ע\"א)."},{"i":2307,"n":"רב יוסף בר מניומי","l":"י","b":"אמורא בבלי בדור השלישי. תלמידו של רב נחמן (כתובות ק\u0027 ע\"ב). כן קיבל מרב ששת (גיטין ע\"א ע\"א). נראה שרב מניומי בריה דרב נחומי, היה תלמידו (כתובות פ\"א ע\"ב)."},{"i":2308,"n":"רב יוסף בר רב נחוניא","l":"י","b":"אמורא בבלי בדור השלישי. מובא בבבלי (ברכות כ\"ד ע\"א) ששאל מרב יהודה."},{"i":2309,"n":"ר\u0027 יוסף ברב אלעאי","l":"י","b":"ע\"ע ר\u0027 יוסי אלעאי."},{"i":2310,"n":"רב יוסף בריה דרב סלא חסידא","l":"י","b":"אמורא בבלי בדור הששי. מצינו אותו כמה פעמים: \"תרגמא קמיה דרב פפא\" (פסחים ע\"ג ע\"ב)."},{"i":2311,"n":"רב יוסף בריה דרב עילאי","l":"י","b":"אמורא בבלי בדור הרביעי החמישי. מובא בבבלי (סוכה כ\"ו ע\"א) שמתרץ את קושיית אביי, ועל דבריו מתקיף ליה רב משרשיא."},{"i":2312,"n":"רב יוסף בריה דרב שמואל","l":"י","b":"אמורא בבלי בדור הששי. מצינו שהקשה לרב פפא (זבחים ו\u0027 ע\"ב). גיר\u0027 \"שיטה מקובצת\": \"בריה דרב שמעיה\". מובא פעם בש\"ס, ולגירסת \"שט\"מ\" לא היה כלל חכם ושמו ר\u0027 יוסף בריה דרב שמואל."},{"i":2313,"n":"רב יוסף בריה דרב שמעיה","l":"י","b":"אמורא בבלי בדור הששי. תלמידו של רב פפא (מנחות ט\u0027 ע\"ב)."},{"i":2314,"n":"רב יוסף בריה דרבא","l":"י","b":"אמורא בבלי בדור החמישי. בנו ותלמידו של רבא (חולין כ\"ח ע\"ב). למד שלוש שנים לפני רב יוסף (כתובות ס\"ג ע\"ב). היה צריך לשהות שם שש שנים, וחזר כעבור 3 שנים (שם). ליבן את דברי רבו ר\u0027 יוסף לפני אביו (יבמות ס\"ד ע\"ב). היו לו שלושה בנים חכמים: רב אבא (חולין קמ\"א ע\"א), רב חביבא (ב\"ב קמ\"ג ע\"ב) ונאנאי (יבמות ס\"ו ע\"ב)."},{"i":2315,"n":"רב יוסף בריה דר\u0027 יהושע בן לוי","l":"י","b":"אמורא ארץ ישראלי בדור השני. בנו ותלמידו של יהושע בן לוי (חולין נ\"ו ע\"ב). נשא אשה ממשפחת הנשיא, ובגלל זה נהג אביו לקום בפניו (קדושין ל\"ג ע\"ב). פעם חלה ונטה למות, וסיפר לאביו מה ראה בעולם האמת (ב\"ב י\u0027 ע\"ב). האריך ימים אחרי אביו (יומא ע\"ח ע\"א)."},{"i":2316,"n":"רב יוסף בריה רב מנשיא מדויל","l":"י","b":"אמורא בבלי בדור השני. תלמידו של רב (נדה כ\"ו ע\"ב). מסופר שעבד עובדא כותיה דרב, ואיקפד שמואל (קידושין ע\"ט ע\"ב), ושלח לשמואל (אולי אחר פטירתו של רב): \"ילמדנו רבנו\" (גיטין פ\"א ע\"א)."},{"i":2317,"n":"יוסף הבבלי","l":"י","b":"מובא בבבלי: \"אמר רבי: כשהלכתי למצות מדותי אצל ר\u0027 אלעזר בן שמוע וכו\u0027, מצאתי יוסף הבבלי וכו\u0027\" (מנחות י\"ח ע\"א). היו לו כמה שמות כדמצינו: \"תנא הוא יוסף איש הוצל הוא יוסף הבבלי וכו\u0027 ומה שמו איסי בן עקביה שמו\" (פסחים קי\"ג ע\"ב)."},{"i":2318,"n":"יוסף הכהן","l":"י","b":"מובא בבבלי: \"מעשה ביוסף הכהן שהלך אצל רבו לצידן ללמוד תורה\" (עירובין מ\"ז ע\"ב). מצינו במשנה: \"יוסף הכהן הביא וכו\u0027\" (סוף חלה). אם נאמר שזה אותו חכם, הרי שהיה תנא."},{"i":2319,"n":"יוסף חפני","l":"י","b":"ע\"ע ר\u0027 יוסי הארוך ועוד ע\"ע שמעון אפרתי."},{"i":2320,"n":"ר\u0027 יוסף צידונא","l":"י","b":"מובא בבבלי (כתובות מ\"ו ע\"ב). \"סה\"ד\" כתב, שהיה בזמן רבי שמעון בן יוחאי (א\"כ, היה תנא בדור הרביעי)."},{"i":2321,"n":"יוסף רישבא","l":"י","b":"אמורא בדור הראשון. מצינו ששאל לר\u0027 יהודה בן בתירא (חולין נ\"ד ע\"א) (כך פירש \"סה\"ד\" את הגמרא שם). לוי ביקר בביתו וסיפר אח\"כ לרבי על נוהגיו (שבת ק\"ל ע\"א)."},{"i":2322,"n":"יועזר איש הבירה","l":"י","b":"תנא בדור השני. מתלמידי בית שמאי ושאל לרבן גמליאל הזקן (משנה ערלה פ\"ב מ\"ב)."},{"i":2323,"n":"יועזר בן יעקב","l":"י","b":"מובא ב\"זוהר\" (שמות י\"ד)."},{"i":2324,"n":"רבי יוצדק","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. רבי אבא בר זמינא מסר משמו."},{"i":2325,"n":"ר\u0027 יושוע אונייה","l":"י","b":"מובא בירושלמי (פסחים פ\"ג ה\"א), והוא ר\u0027 יהושע אונייא."},{"i":2326,"n":"ר\u0027 יושוע בר גיזורה","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי זירא (ירו\u0027, תענית פ\"ד ה\"א)."},{"i":2327,"n":"ר\u0027 יושיע בן קבסא","l":"י","b":"מובא בירושלמי (פסחים פ\"ו ה\"א), והוא ר\u0027 יהושע בן כפוסא."},{"i":2328,"n":"יושעה בריה דרב חננאל","l":"י","b":"מובא בירושלמי (מגילה פ\"א ה\"ט)."},{"i":2329,"n":"רב יחונה","l":"י","b":"מובא בירושלמי (כתובות פ\"א ה\"ב), והוא רב הונא ב\u0027."},{"i":2330,"n":"רב יחזקאל","l":"י","b":"אמורא בבלי בדור הראשון. אביו של האמורא המפורסם רב יהודה. רב יהודה מספר על מנהגי אביו (ירו\u0027, תענית פ\"א ה\"ג); אח\"כ גדל רב יהודה והיה לרבו של אביו (קידושין ל\"ג ע\"ב, פרש\"י: \"אע\"ג דרב יהודה רביה דרב יחזקאל, אבוה הוה\"). שמואל נהג לקום בפני ר\u0027 יחזקאל, כי היה \"בעל מעשים\" (שם). היה לו בן חכם נוסף ושמו רמי בר יחזקאל ולימדו תורה (שם ל\"ב ע\"א)."},{"i":2331,"n":"ר\u0027 יחזקיה","l":"י","b":"מובא בירושלמי (ברכות פ\"ו ה\"א)."},{"i":2332,"n":"רב יחיאל","l":"י","b":"אמורא בבלי בדור השני. מובא בבבלי (עירובין ל\"א ע\"ב). חלק עם רב יהודה (מו\"ק י\u0027 ע\"א)."},{"i":2333,"n":"רב ייבא","l":"י","b":"מובא בבבלי (גיטין ס\"ב ע\"א)."},{"i":2334,"n":"ר\u0027 ייבא בר יוסי","l":"י","b":"אמורא בבלי בדור השני. תלמידו של רב. מובא בבבלי (ערכין ה\u0027 ע\"ב)."},{"i":2335,"n":"ייבא חמוה דאשיין בר נדבך","l":"י","b":"אמורא בבלי בדור השני. אמר משמיה דרב (ב\"ב כ\"ב ע\"ב). חתנו מסר בשם רב יהודה (מנחות כ\"ט ע\"א)."},{"i":2336,"n":"רב ייבא סבא","l":"י","b":"אמורא בבלי בדור השני - השלישי. היה משמש את רב ברונא ורב חננאל, שהיו תלמידי רב, ואמר להם משמו של רב (פסחים ק\"ג ע\"ב)."},{"i":2337,"n":"ר\u0027 ייבא סבא","l":"י","b":"תנא שאין לקבוע את זמנו המדוייק. מובא מספר פעמים ב\"זוהר\". מסופר על אחד שהירהר אחר מצות מילה ונתן ר\u0027 ייבא סבא עיניו בו ונעשה גל של עצמות (\"זוהר\", בראשית נ\"ט)."},{"i":2338,"n":"רבי יילי","l":"י","b":"מובא בירושלמי (ע\"ז פ\"ד הי\"ב), והוא רבי אלעאי."},{"i":2339,"n":"רב יימר","l":"י","b":"אמורא בבלי בדור הששי. נראה שהיה תלמידו של רב כהנא ה\u0027 (ע\"ז נ\"ט ע\"א). שאל לר\u0027 אשי ונשא ונתן עמו בהלכה (כתובות ס\"ט ע\"א). נפטר אחרי רב אשי, וחלק עם מר בר ר\u0027 אשי: \"אפכיהו ושדרוהו לקמיה דרב מרדכי\" (גיטין כ\"ט ע\"א), ונראה שהדבר היה אחרי מות רב אשי."},{"i":2340,"n":"רב יימר בר חשו","l":"י","b":"כן גירסת \"סה\"ד\", ולפנינו (כתובות פ\"ד ע\"ב): יימר בר חשו (בלי רב), ופרש\"י: \"שם איש\". חי בבבל בזמנו של רב פפא (דור חמישי לאומראים) וחבו לו כסף: \"פגעו בו רב פפא ורב הונא בריה דרב יהושע אמרו לו וכו\u0027\"."},{"i":2341,"n":"רב יימר בר שיזבי","l":"י","b":"אמורא בבלי בדור הששי. מובא בבבלי שהקשה למר זוטרא (ברכות נ\"ג ע\"ב)."},{"i":2342,"n":"רב יימר בר שלמיא","l":"י","b":"אמורא בבלי בדור החמישי - הששי. תלמידו של אביי (ב\"ב ס\"ג ע\"א). קיבל גם מרבא (ב\"ב ט\u0027 ע\"א), ושלח שאלה לרב פפא (מנחות ל\"א ע\"א)."},{"i":2343,"n":"רב יימר בריה דרב הלל","l":"י","b":"אמורא בבלי בדור הרביעי. מובא בבבלי (זבחים ט\u0027 ע\"א), ורבא השיב על דבריו (שם)."},{"i":2344,"n":"רב יימר מדיפתא","l":"י","b":"אמורא בבלי בדור הששי. חלק עם רב אשי (שבת קמו ע\"ב) ונזכר הראשון (שם)."},{"i":2345,"n":"רב יימר סבא","l":"י","b":"אמורא בבלי בדור הששי. תלמידו של רב נחמן (כתובות נ\"ג ע\"א). ר\"נ דיבר על אודותיו בכבוד גדול (ב\"ק מ\"ט ע\"ב). פעם שלחוהו חכמים לרב חסדא, לראות אם הוא נוהג לאמר \"שהחיינו\" בקידוש של ראש השנה (עירובין מ\u0027 ע\"ב), ורש\"י גורס שם: ייבא סבא."},{"i":2346,"n":"ר\u0027 ייסא","l":"י","b":"מובא ב\"זוהר\" (נשא קמד)."},{"i":2347,"n":"יישוע אחוה דדוריי","l":"י","b":"חי בארץ ישראל בדור הרביעי לאמוראים. בא לשאול מרבי אבהו שאלת חכם (ירו\u0027, מו\"ק פ\"ג ה\"ה) ואין להכריע אם נמנה על החכמים."},{"i":2348,"n":"רבי ינאי","l":"י","b":"מגדולי אמוראי ארץ ישראל בדור הראשון. תלמידו של רבי (ב\"ב פ\"ד ע\"ב). לדברי הרמב\"ם (בהקדמתו ל\"יד החזקה\") היה מבית דינו של רבי. תלמידו של רבי חייא (ירו\u0027, דמאי רפ\"ז). ר\u0027 חייא אמר: \"עתיד אתה להנהיג שררה על ישראל\" (שם). מושבו היה בעכברא שליד צפת (ע\"ז ל\u0027 ע\"א), ושם יסד ישיבה גדולה שהתקיימה כמה דורות אחריו, ועוד היא מוזכרת בימי ר\u0027 יונה (ירו\u0027, שבת פ\"ח ה\"א). בין תלמידיו הרבים היו רבי יוחנן (ב\"ב קנ\"ד ע\"ב) שהיה משבחו (ירו\u0027, כלאים פ\"ח ה\"א), רבי שמעון בן לקיש (עירובין י\"א ע\"ב), ר\u0027 אושעיא (כתובות ע\"ט ע\"א) ור\u0027 שמלאי (ב\"ב קי\"א ע\"א). אף ר\u0027 יהושע בן לוי מסר בשמו (ירו\u0027, קידושין פ\"ג ה\"ב). היה עשיר מופלג (ב\"ב י\"ד ע\"א) ועשרו היה למשל בפי הבריות (קידושין י\"א ע\"א). אחת מבנותיו נישאה ליהודה, בנו של רבי חייא, ויהודה מת על פניו (כתובות ס\"ב ע\"ב). היה לו בן ושמו רבי שמעון (ירו\u0027, שבת פי\"ג ה\"ז). נראה שהגיע לזקנה גדולה (ב\"ב קי\"א ע\"א רשב\"ם: רבי ינאי זקן היה והחלו עיניו כהות). קודם פטירתו ציווה לבנו שלא יקברוהו לא בכלים לבנים, שמא לא יזכה ויהיה כחתן בין אבלים, ולא בכלים שחורים, שמא יזכה ויהיה כאבל בין חתנים (שבת קי\"ד ע\"א)."},{"i":2349,"n":"ר\u0027 ינאי","l":"י","b":"תנא בדור הרביעי. מובא באבות (פ\"ד). פעם מסר בשם רבן שמעון בן גמליאל (תוספתא סנהדרין פ\"ב ה\u0027). אולי הוא אביהם של ר\u0027 דוסתאי בר ינאי ור\u0027 אלעזר בר ינאי."},{"i":2350,"n":"רב ינאי אחוה דרבי חייא בר אבא","l":"י","b":"מובא בבבלי (סנהדרין ע\"ד ע\"ב), והוא רבנאי אחוה דר\u0027 חייא בר אבא."},{"i":2351,"n":"ר\u0027 ינאי בר ישמעאל","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם ר\u0027 יוחנן (ירו\u0027, יבמות פ\"ח ה\"א) ורשב\"ל (ירו\u0027, עירובין פ\"א ה\"א). כשחלה באו לבקרו רבי זירא וחכמים נוספים (ירו\u0027, תרומות פ\"ח ה\"ג)."},{"i":2352,"n":"ר\u0027 ינאי בר נחמיה","l":"י","b":"אמורא בבלי בדור השני. תלמידו של שמואל (תמיד כ\"ט ע\"א). מאמרו המובא במסכת חולין (צ\u0027 ע\"ב), מובא בשם ר\u0027 יצחק בר נחמיה, גם הוא תלמידו של שמואל."},{"i":2353,"n":"ר\u0027 ינאי בר שמואל","l":"י","b":"מובא בשהש\"ר (פ\"א פסוק ג\u0027 - א\u0027)."},{"i":2354,"n":"ר\u0027 ינאי בר שמעון","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. מובא בקה\"ר (פ\"ב - ה\u0027) שאמר לר\u0027 אבא בר כהנא."},{"i":2355,"n":"רבי ינאי בריה דרבי ינאי סבא","l":"י","b":"מובא בבבלי (מגילה ל\"ב ע\"א), שאמר משמיה דר\u0027 ינאי רבה."},{"i":2356,"n":"ר\u0027 ינאי בריה דר\u0027 אמי","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. נראה אולי שהיה בנו של ר\u0027 אמי האמורא המפורסם. מובא בבבלי: \"וינאי בריה דר\u0027 אמי, איקלען לבי יהודה בריה דרבי שמעון בן פזי\" (חולין קי\"א ע\"א)."},{"i":2357,"n":"רבי ינאי בריה דר\u0027 שמואל בר\u0027 ינאי","l":"י","b":"מובא במדרש שמואל (הישן ספכ\"ח), ונראה שצ\"ל: רבי ינאי בריה דר\u0027 שמעון בר ינאי."},{"i":2358,"n":"ר\u0027 ינאי דשאב","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. אמר בשם ר\u0027 שמואל בר נחמן (פס\u0027 רבתי פ\u0027 פרה - פ\"י)."},{"i":2359,"n":"ר\u0027 ינאי הכהן","l":"י","b":"מובא במ\"ר (פכ\"ג - ז\u0027) ובתנחומא (מסעי - ה\u0027)."},{"i":2360,"n":"ר\u0027 ינאי זעירא","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. כשנפטר חמו, שהיה רבו, שאל את ר\u0027 יוסי אם מותר להטמא לכבודו, ואסר לו. שמע ר\u0027 אחא, והתיר (ירו\u0027, ברכות פ\"ג ה\"א)."},{"i":2361,"n":"ר\u0027 ינאי חמוהי דר\u0027 אמי","l":"י","b":"מובא בשהש\"ר (פ\"א - י\"א)."},{"i":2362,"n":"רבי ינאי סבא","l":"י","b":"מובא בבבלי: \"ר\u0027 ינאי בריה דר\u0027 ינאי סבא משמיה דר\u0027 ינאי רבה\" (מגילה ל\"ב ע\"א), ומובא שוב: \"בר בריה דר\u0027 ינאי סבא אתא לקמיה דר\u0027 ינאי סבא, והתיר לו נדרו\" (נדרים כ\"ב ע\"א)."},{"i":2363,"n":"ר\u0027 ינאי קפודקאי","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. שאל דין ירושת הבן משלושה דיינים - רב הונא ב\u0027, ר\u0027 יהודה בן פזי ור\u0027 אחא (ירו\u0027, ב\"ב רפ\"ח)."},{"i":2364,"n":"רבי ינאי רבה","l":"י","b":"מובא בבבלי: \"ר\u0027 ינאי בריה דר\u0027 ינאי סבא משמיה דר\u0027 ינאי רבה\" (מגילה ל\"ב ע\"ב)."},{"i":2365,"n":"ר\u0027 ינטה בר חיננא","l":"י","b":"מובא בירושלמי (פסחים רפ\"ד)."},{"i":2366,"n":"יסא","l":"י","b":"הוא יוסי או אסי."},{"i":2367,"n":"ר\u0027 יסא בי ר\u0027 שבתי","l":"י","b":"מובא בירושלמי (גיטין פ\"ט ה\"ז), ונראה שצ\"ל: ר\u0027 יסא בשם ר\u0027 שבתי."},{"i":2368,"n":"ר\u0027 יסא בר אחא","l":"י","b":"מובא בירושלמי (עירובין פ\"ה ה\"א), ואולי צ\"ל: ר\u0027 יעקב בר אחא, כפי שמשתמע מהסוגיא שם."},{"i":2369,"n":"ר\u0027 יסא בר ברתיה דר\u0027 יסא","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. מסר בשם ר\u0027 ירמיה (ירו\u0027, נזיר פ\"ו ה\"א)."},{"i":2370,"n":"יסא בר חלפותא","l":"י","b":"מובא בירושלמי (ע\"ז פ\"ג ה\"א), והוא רבי יוסי בן חלפתא."},{"i":2371,"n":"ר\u0027 יסא קוצירא","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. חתנו של ר\u0027 יוסי ואמר בשמו (ירו\u0027, ב\"ב פ\"י ה\"א)."},{"i":2372,"n":"יסי","l":"י","b":"הוא יוסי או אסי."},{"i":2373,"n":"יעבץ (2)","l":"י","b":"מובא בד\"א זוטא (ספ\"ק), שנכנס חי לגן עדן בנו של ר\u0027 יהודה הנשיא, ומזה נראה כאילו היה לר\u0027 יהודה הנשיא בן ושמו יעבץ, ולא נזכר בשום מקום בש\"ס ובמדרשים."},{"i":2374,"n":"ר\u0027 יעקב (2)","l":"י","b":"אמורא בבלי בדור השלישי. מובא כמה פעמים בש\"ס א\"ל ההוא מרבנן ור\u0027 יעקב שמו. תלמידו של רב יהודה (ע\"ז כ\"ח ע\"ב) ולמד גם אצל רב חסדא (ברכות כט ע\"א). עלה לארץ ישראל ולמד לפני רבי יוחנן (עירובין פ\u0027 ע\"א). כנראה שגם קיבל מרב אסי והיה בפטירתו בארץ ישראל (קידושין י\"ג ע\"א). תלמידו היה ר\u0027 ירמיה וכשנפטר ר\u0027 יעקב נראו כוכבים ביום (מו\"ק כ\"ה ע\"ב)."},{"i":2375,"n":"יעקב אבי ר\u0027 נחמן","l":"י","b":"אמורא בבלי בדור השני - השלישי. מספרי דדיינא של שמואל (ב\"מ ט\"ז ע\"ב). היה אביו של ר\u0027 נחמן בר יעקב. רב נחמן בנו קיבל ממנו (זבחים נ\"ו ע\"א)."},{"i":2376,"n":"ר\u0027 יעקב אחוה דרב אחא בר יעקב","l":"י","b":"אמורא בדור השלישי - הרביעי. התקיף על דברי ר\u0027 אלעאי (סנהדרין ע\"ו ע\"א)."},{"i":2377,"n":"ר\u0027 יעקב איש כפר חיטייה","l":"י","b":"בדור המעבר שבין התנאים לאמוראים בארץ ישראל. מובא בבבלי, שרבי ור\u0027 חייא באו למקום אחד, והלכו לקבל אפיה דצורבא מרבנן מאור עינים, והוא סיפר להם ששמע מפרקא דר\u0027 יעקב איש כפר חיטייא (חגיגה ה\u0027 ע\"ב)."},{"i":2378,"n":"יעקב איש כפר נבוריא","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. פעם הורה למול גוי בשבת ושמע ר\u0027 חגי והלקהו (ירו\u0027, יבמות פ\"ב ה\"ו). וכן מובא, שהורה שדגים טעונים שחיטה ואף על זה הלקהו ר\u0027 חגי (תנחומא חקת ט\"ו). דרש נגד המתמנים לדיינות תמורת כסף (ירו\u0027, בכורות פ\"ג ה\"ג). דרש בקיסרי והיה שם ר\u0027 יצחק בן אלעזר וקילסהו (מדרש שמואל פ\"ח - ו\u0027)."},{"i":2379,"n":"ר\u0027 יעקב ארמנייא","l":"י","b":"אמורא בדור השני. רב נחמן אמר משמו (ירו\u0027, גיטין פ\"ו ה\"ה)."},{"i":2380,"n":"ר\u0027 יעקב בן דוסאי","l":"י","b":"מובא בירושלמי (ב\"ב פ\"ב ה\"ט), והוא ר\u0027 יעקב בן דוסתאי."},{"i":2381,"n":"ר\u0027 יעקב בן יצחק מבית גיפנין","l":"י","b":"תנא. מובא בתוספתא (אהלות פי\"ח) שהעיד עם ר\u0027 יהודה בן יעקב מבית גובריא."},{"i":2382,"n":"ר\u0027 יעקב בן קורשאי","l":"י","b":"מובא בקה\"ר (פ\"ד - ו\u0027), והוא ר\u0027 יעקב (התנא)."},{"i":2383,"n":"רבי יעקב בן קרשי","l":"י","b":"מובא בבבלי (הוריות י\"ג ע\"ב), והוא רבי יעקב (התנא)."},{"i":2384,"n":"ר\u0027 יעקב בר אבא א\u0027","l":"י","b":"אמורא בבלי בדור השני. תלמידו של רב. מובא בירושלמי: \"אמר רב: אע\"ג דנצחני ר\u0027 יעקב בר אבא בדינא הלכה וכו\u0027\" (סנהדרין פ\"ז הי\"א)."},{"i":2385,"n":"ר\u0027 יעקב בר אבא ב\u0027","l":"י","b":"אמורא בבלי בדור החמישי. תלמידם של אביי (ב\"מ כ\"ג ע\"ב) ורבא (פסחים ק\"ג ע\"א)."},{"i":2386,"n":"ר\u0027 יעקב בר אבדימי","l":"י","b":"מובא ברו\"ר (רפ\"א)."},{"i":2387,"n":"ר\u0027 יעקב בר אבוה","l":"י","b":"אמורא בבלי בדור החמישי. מובא בבבלי, ששאל דין מאביי (קידושין ל\"א ע\"ב)."},{"i":2388,"n":"ר\u0027 יעקב בר אבון","l":"י","b":"מובא בירושלמי (נדרים פ\"ג ה\"ב), והוא ר\u0027 יעקב בר אבין"},{"i":2389,"n":"ר\u0027 יעקב בר אביי","l":"י","b":"אמורא בדור הרביעי - החמישי. מסר בשם ר\u0027 אחא (ירו\u0027, ברכות פ\"ב ה\"ג) ובשם רב ששת (ירו\u0027, סוכה פ\"א ה\"ו). יש סבורים שהיה בנו של האמורא אביי."},{"i":2390,"n":"ר\u0027 יעקב בר אבין","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מסר בשם ר\"ש בן לקיש (ירו\u0027, שביעית פ\"ג ה\"ה), בשם ר\u0027 חנינא (ירו\u0027, פאה פ\"ג) ובשם ר\u0027 יוסי בר חנינא (ירו\u0027, יבמות פ\"י ה\"ז). בימי ר\u0027 ירמיה כבר היה גדול הדור (ירו\u0027, מו\"ק פ\"ג ה\"א). ר\u0027 זריקן היה כתלמידו (ירו\u0027, עירובין פ\"ט ה\"ג)."},{"i":2391,"n":"ר\u0027 יעקב בר אבינא","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. חברו של ר\u0027 ברכיה (קה\"ר פ\"א - ד\u0027). אמר בשם רב הונא דציפורן (ירו\u0027, שבועות פ\"ו ה\"ג)."},{"i":2392,"n":"ר\u0027 יעקב בר אדא","l":"י","b":"מובא בבבלי (סנהדרין ס\"ו ע\"ב), וגיר\u0027 \"דק\"ס\": ר\u0027 יעקב בר אבא."},{"i":2393,"n":"ר\u0027 יעקב בר אדא בר עתליה","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. אמר בשם רבי אלעזר. היה חברו של ר\u0027 זירא (ירו\u0027, גיטין פ\"א ה\"ב)."},{"i":2394,"n":"רבי יעקב בר אחא","l":"י","b":"תנא בדור החמישי. חברו של רבי. מכונה \"גדול הדור\" (מו\"ק כ\"ב ע\"ב). מסר בשם רבי (נדרים נ\"ו ע\"ב)."},{"i":2395,"n":"ר\u0027 יעקב בר אחא","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. נראה, שאולי היה תלמידו של ר\u0027 יוחנן (ירו\u0027, שבועות פ\"א ה\"ג). נראה, שהיה גם תלמידו של ר\u0027 שמעון בן לקיש (ירו\u0027, סוטה פ\"ד ה\"ג). מסר גם בשם ר\u0027 אמי (סנהדרין כ\u0027 ע\"ב), בשם ר\u0027 אסי (תענית כ\"ז ע\"ב) ובשם ר\u0027 זירא (ברכות כ\"ז ע\"א). אך נראה יותר שהיה חברו של ר\"ז (ירו\u0027, יבמות פ\"ח ה\"ג). ר\u0027 יוסי היה תלמידו (ירו\u0027, כלאים פ\"ו ה\"ד)."},{"i":2396,"n":"ר\u0027 יעקב בר אחא בר אידי","l":"י","b":"אמורא בבלי בדור השני. אמר בשם ר\u0027 יהודע בן לוי (ירו\u0027, דמאי ספ\"א)."},{"i":2397,"n":"ר\u0027 יעקב בר אחאי","l":"י","b":"אמורא ארץ ישראלי בדור השני. אמר בשם ר\u0027 יונתן (מדרש ילמדנו תשא ס\"ד)."},{"i":2398,"n":"ר\u0027 יעקב בר אידי (2)","l":"י","b":"אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של ר\u0027 יהושע בן לוי (יבמות ס\u0027 ע\"ב). היה גם תלמידם של ר\u0027 חנינא (ברכות מ\"ד ע\"א) ור\u0027 אושעיא (שם כ\"ט ע\"ב). בתחילה היה תלמידו המובהק של ר\u0027 יוחנן (ירו\u0027, ברכות פ\"ב ה\"א) ואח\"כ היה לו לתלמיד - חבר (יבמות צ\"ו ע\"ב, וכן מוכח מחולין נ\"ז ע\"ב רש\"י ד\"ה: לא פרכיס). ר\"ז היה תלמידו (חולין ה\u0027 ע\"ב), וקרא לו ולר\u0027 שמואל בר נחמני \"שני גדולי הדור\" (חולין צ\"ח ע\"א). גם רב נחמן שלח מבבל לשאול אצלו (ביצה כ\"ה ע\"ב)."},{"i":2399,"n":"ר\u0027 יעקב בר אלעזר","l":"י","b":"מובא במדרש תהלים (פי\"ט - ב\u0027)."},{"i":2400,"n":"רבי יעקב בר אמי","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם רבי שמעון בן לקיש (ירו\u0027, כתובות רפ\"ו)."},{"i":2401,"n":"ר\u0027 יעקב בר אמי","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. אמר בשם ר\u0027 אחא (פסדר\"כ קע\"ג ב\u0027)."},{"i":2402,"n":"ר\u0027 יעקב בר בין","l":"י","b":"מובא בירושלמי (שביעית פ\"ג ה\"ג), והוא ר\u0027 יעקב בר אבין."},{"i":2403,"n":"רבי יעקב בר ברתיה דאחר","l":"י","b":"מובא בבבלי (סוף חולין), והוא רבי יעקב (תנא בדור הרביעי)."},{"i":2404,"n":"ר\u0027 יעקב בר ברתיה דרב אחא בר יעקב","l":"י","b":"אמורא בבלי בדור החמישי - הששי. גדל אצל סבו ר\u0027 אחא בר יעקב (סוטה מ\"ט ע\"א)."},{"i":2405,"n":"ר\u0027 יעקב בר גיורי","l":"י","b":"מובא בבבלי (עירובין ס\"ב ע\"א ועוד), שר\u0027 יצחק בר יעקב בר גיורי היה תלמידו של ר\u0027 יוחנן. ר\u0027 יעקב בר גיורי מוזכר בש\"ס רק בהקשר לבנו."},{"i":2406,"n":"רבי יעקב בר דוסתאי","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בבבלי (כתובות קי\"א ע\"ב). ר\u0027 יוסי בר אבין מסר בשמו (ירו\u0027, פסחים פ\"ו ה\"ד). כן מסרו משמו \"רבנן דקיסרי\" (ירו\u0027, יבמות פי\"א ה\"ז). שמו נשתבש בכמה אופנים: בן דוסאי, בר דסי, בר דסיי, בר דסאיי."},{"i":2407,"n":"ר\u0027 יעקב בר דסאיי","l":"י","b":"מובא בירושלמי (סנהדרין רפ\"ד), והוא ר\u0027 יעקב בר דוסתאי."},{"i":2408,"n":"ר\u0027 יעקב בר דסי","l":"י","b":"מובא בירושלמי (מכות פ\"א ה\"ז), והוא ר\u0027 יעקב בר דוסתאי."},{"i":2409,"n":"ר\u0027 יעקב בר דסיי","l":"י","b":"מובא בירושלמי (פסחים פ\"ו ה\"ד), והוא ר\u0027 יעקב בר דוסתאי."},{"i":2410,"n":"ר\u0027 יעקב בר זבדי","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של ר\u0027 אבהו (ירו\u0027, שבועות פ\"ד ה\"ב), כן היה תלמידו של ר\u0027 יוסי (ירו\u0027, ברכות פ\"ב ה\"ו), ושאל מר\u0027 ירמיה (ירו\u0027, כלאים פ\"א ה\"א). הניח אחריו שני בנים חכמים: ר\u0027 זבדי תלמידו של ר\u0027 יונה (ירו\u0027, ברכות פ\"ג ה\"ה) ור\u0027 יוסי (ירו\u0027, פאה פ\"א ה\"ד)."},{"i":2411,"n":"רבי יעקב בר חמא","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. אמר בשם ר\u0027 אלעזר (ירו\u0027, בכורים פ\"ב ה\"ב). כך מובא ב\"סה\"ד\" ולפנינו הגיר\u0027 יעקב בר אחא."},{"i":2412,"n":"ר\u0027 יעקב בר חנינא","l":"י","b":"תנא שזמנו אינו ידוע. מובא בבבלי (שבת ע\"ט ע\"ב). ר\u0027 אחא מסר בשמו."},{"i":2413,"n":"ר\u0027 יעקב בר יוסי","l":"י","b":"מובא בתנחומא (בהעלותך י\"א)."},{"i":2414,"n":"ר\u0027 יעקב בר ינאי","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. ר\u0027 נחמיה אמר משמו (מס\u0027 סופרים פט\"ז ה\"ג)."},{"i":2415,"n":"ר\u0027 יעקב בר יעקב","l":"י","b":"מובא ב\"ילקוט\" (תהלים רמז תר\"ל), ונראה שאולי צ\"ל: ר\u0027 יעקב ברה דבת יעקב."},{"i":2416,"n":"ר\u0027 יעקב בר יצחק","l":"י","b":"מובא בירושלמי (חלה פ\"ב ה\"א)."},{"i":2417,"n":"ר\u0027 יעקב בר נחמני","l":"י","b":"אמורא בבלי בדור השני. תלמידו של שמואל (חולין נ\u0027 ע\"ב)."},{"i":2418,"n":"רבי יעקב בר סוסי","l":"י","b":"מובא בירושלמי (מגילה ספ\"ב), והוא ר\u0027 יעקב בר סוסיי."},{"i":2419,"n":"ר\u0027 יעקב בר סוסיי","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של ר\u0027 אסי (ירו\u0027, פסחים פ\"ד ה\"ט). שמו נשתבש בכמה אופנים: סוסיי, סוסי, סיסי."},{"i":2420,"n":"רבי יעקב בר סיסי","l":"י","b":"מובא בירושלמי (חגיגה פ\"ג ה\"ח), והוא ר\u0027 יעקב בר סוסיי."},{"i":2421,"n":"ר\u0027 יעקב בר פליטי","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. ר\u0027 מנא היה שושביניה (ירו\u0027, סוכה פ\"ב ה\"ה)."},{"i":2422,"n":"ר\u0027 יעקב ברה דבת יעקב","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. פעם ביקשו ר\u0027 זירא שיכנס לר\u0027 יעקב בר אידי וישאל ממנו דבר הלכה (עירובין פ\u0027 ע\"א). ר\u0027 ברכיה מסר בשמו (ירו\u0027, מע\"ש פ\"ה ה\"א). ורש\"י פירש (עירובין שם): \"אביו לא היה הגון לפיכך לא הזכירו\"."},{"i":2423,"n":"ר\u0027 יעקב ברה דבת שמואל","l":"י","b":"אמורא בבלי בדור השלישי. מובא בבבלי (ברכות כ\"ה ע\"ב). החכם באלי אמר משמו (שם). נראה, שהוא אחיו של רב מרי ברה דבת שמואל."},{"i":2424,"n":"ר\u0027 יעקב בריה דרב יהודה בר יחזקל","l":"י","b":"מובא במ\"ר (פי\"ד - ג\u0027), וט\"ס וצ\"ל: ר\u0027 יצחק בריה דרב יהודה בר יחזקל."},{"i":2425,"n":"ר\u0027 יעקב בריה דר\u0027 אחא בר יעקב","l":"י","b":"אמורא בבלי בדור החמישי. אביו שלחו ללמוד לפני אביי. כשחזר לא השביעו ידיעותיו את רצון אביו, ואביו הלך במקומו לאביי (קדושין כ\"ט ע\"ב)."},{"i":2426,"n":"ר\u0027 יעקב גבולייא","l":"י","b":"אמורא ארץ ישראלי בדור השני. היה תלמידו של רבי יוחנן (ירו\u0027, יבמות פ\"ח ה\"ב), ומסר בשם ר\u0027 חנינא (ירו\u0027, חלה פ\"ג ה\"א). שמו השתבש בכמה אופנים: גבליא, גביליא."},{"i":2427,"n":"ר\u0027 יעקב גביליא","l":"י","b":"מובא בקה\"ר (פ\"א - ד\u0027), והוא ר\u0027 יעקב גבולייא."},{"i":2428,"n":"ר\u0027 יעקב גבליא","l":"י","b":"מובא (ירו\u0027, יבמות פ\"ח ה\"ב), והוא ר\u0027 יעקב גבולייא."},{"i":2429,"n":"ר\u0027 יעקב גרוסה","l":"י","b":"אמורא ארץ ישראלי בדור השני - השלישי. ר\u0027 שמואל בר נחמני כשביקר את ר\u0027 יעקב גרוסה, היה ר\u0027 זירא נטמן לשמוע היאך קורא קריאת שמע."},{"i":2430,"n":"ר\u0027 יעקב דכפר חנן","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם ר\u0027 שמעון בן לקיש (ירו\u0027, ברכות פ\"ה ה\"ב). שמו נזכר פעמים בב\"ר ובמדרש שמואל."},{"i":2431,"n":"ר\u0027 יעקב דקיסרין","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. ר\u0027 נחמיה ור\u0027 נחמן דיפו אמרו משמו (ויק\"ר פ\"ו - ה\u0027), וכן גם ר\u0027 מנחמא (מד\u0027 שמואל פט\"ז - א\u0027)."},{"i":2432,"n":"ר\u0027 יעקב דרומאי","l":"י","b":"ע\"ע ר\u0027 יעקב דרומייא."},{"i":2433,"n":"ר\u0027 יעקב דרומייא","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידו של רבי אלעזר (ירו\u0027, סוכה פ\"ד ה\"ב) ושל ר\u0027 אסי (ירו\u0027, תרומות פ\"ג ה\"א; מובא ר\u0027 יוסי, אך הוא רבי אסי)."},{"i":2434,"n":"ר\u0027 יעקב דרומנא","l":"י","b":"הוא ר\u0027 יעקב דרומייא."},{"i":2435,"n":"יעקב הדייבא","l":"י","b":"אמורא בבלי בדור השלישי - הרביעי. שאל מרב חסדא (ב\"ב כ\"ו ע\"ב ופרש\"י: מן הדייב היה)."},{"i":2436,"n":"ר\u0027 יעקב מנהר פקוד","l":"י","b":"אמורא בבלי בדור הששי - השביעי. תלמידו של רבינא, ישב לפניו ומסר בשם רב הונא בריה דר\u0027 יהושע (סנהדרין ס\"ט ע\"א). כן מסר בשם רבא (כתובות ל\"ג ע\"ב)."},{"i":2437,"n":"יעקב מעפרתים","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. מסר בשם רבי. ר\u0027 חוניא (ואולי זה רב הונא) מסר משמו (ירו\u0027, שבת פי\"ד ה\"ג)."},{"i":2438,"n":"יעקב מצעה","l":"י","b":"אמורא שאין לקבוע זמנו ומקומו. שאל לר\u0027 יהודה (מגילה כ\"ג ע\"א). וגיר\u0027 הגמרא (שם): יעקב מינאה, ותוספות גורסים: מצעה, כי יעקב מינאה היה מין ורשע (עיין ע\"ז י\"ז ע\"א תד\"ה: ויעקב). שאל גם מרב (חולין פ\"ד ע\"א), וגם שם גיר\u0027 הגמרא: יעקב מינאה (ולפי תוספות צריך לגרוס \"מצעה\")."},{"i":2439,"n":"ר\u0027 יעקב עמסונייא","l":"י","b":"מובא בירושלמי (ב\"מ פ\"ד ה\"ז), ומפרש המשנה שם."},{"i":2440,"n":"יעקב קרחה","l":"י","b":"אמורא בבלי שאין לקבוע זמנו המדוייק. שונה ברייתות (שבת קל\"ט ע\"ב; חולין כ\"ב ע\"ב)."},{"i":2441,"n":"יעקב קרחינאה","l":"י","b":"מובא בבבלי (עירובין פ\"ו ע\"א), ונראה שהוא יעקב קרחה."},{"i":2442,"n":"רב יצחק","l":"י","b":"מובא בירושלמי (שבועות פ\"ד ה\"א), והוא אבוה דשמואל בר יצחק (ע\"ע)."},{"i":2443,"n":"רבי יצחק","l":"י","b":"תנא בבלי בדור הרביעי - החמישי. מושבו היה בעיר נהר פקוד, יחד עם חברו ר\u0027 נתן (ירו\u0027, נדרים פ\"ו ה\"ח). שניהם סייעו שחנניה בן אחי יהושע יפסיק לעבר שנים בחו\"ל (שם). מובא יחד עם רבי ור\u0027 נתן בברייתא (ברכות מ\"ח ע\"ב). מובא יותר מעשרים פעם במכילתא."},{"i":2444,"n":"ר\u0027 יצחק","l":"י","b":"ע\"ע ר\u0027 יצחק בר אחא, וע\"ע ר\u0027 יצחק בר פנחס."},{"i":2445,"n":"יצחק אבי רב נחמן","l":"י","b":"בנו רב נחמן. מגדולי אמוראי בבל בדור השני - השלישי. יצחק, אביו של ר\"נ זה, לא נסמך (תענית כ\"א ע\"ב רש\"י)."},{"i":2446,"n":"ר\u0027 יצחק איש כפר עכו","l":"י","b":"אמורא ארץ ישראלי בדור השני. תלמידו של ר\u0027 יוחנן (ע\"ז ז\u0027 ע\"ב)."},{"i":2447,"n":"רבי יצחק בן אלעא","l":"י","b":"מובא בבבלי (פסחים קי\"ג ע\"ב), וצ\"ל: ר\u0027 יצחק בן אלעזר."},{"i":2448,"n":"רבי יצחק בן אלעזר","l":"י","b":"אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של רבי יוחנן (ירו\u0027, דמאי פ\"ב ה\"א, ושם ר\u0027 יצחק בר טבליי והוא ר\u0027 יצחק בן אלעזר פסחים קי\"ג ע\"ב). וכשנפטר ר\u0027 יוחנן הספידו ופתח: \"קשה היום לישראל וכו\u0027\" (מו\"ק כ\"ה ע\"ב). כן קיבל מרבי אלעזר (ירו\u0027, קידושין פ\"ג ה\"א). היה חברם של גדולי תלמידי ר\u0027 יוחנן: \"יתיב ר\u0027 חייא בר אבא ור\u0027 אמי ור\u0027 יצחק נפחא, אקלעא דר\u0027 יצחק בן אלעזר\" (מו\"ק כ\u0027 ע\"א)."},{"i":2449,"n":"ר\u0027 יצחק בן אלעזר ב\u0027","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. רבו של רבי מנא (ירו\u0027, דמאי פ\"ב ה\"א). מסרו בשמו: ר\u0027 יוסי בן יוסי (ירו\u0027, תרומות פ\"א ה\"ה) ור\u0027 תנחומא (ירו\u0027, בכורים פ\"א ה\"ג). פעם אחת ראה עצם, והטמינה באדמה, שלא יכשלו בה, ונתגלגלה מאליה למקום אחר, ושוב התגלגלה, ואמר: עצם זו נועדה לבצע שליחות, לבסוף עבר פקיד המלכות ונכשל בה ונהרג, ומצאו אצלו מסמכים נגד היהודים בקיסרין (ב\"ר פ\"י - ז)."},{"i":2450,"n":"ר\u0027 יצחק בן זעירא","l":"י","b":"אמורא שאין לקבוע זמנו ומקומו. דבריו הובאו אחרי שמואל (שבת כ\u0027 ע\"ב). מפורסמת אמרתו: \"תלמידי חכמים כיון שאומרים דבר שמועה מפיהם בעולם הזה, שפתותיהם דובבות בקבר\" (יבמות צ\"ז ע\"א)."},{"i":2451,"n":"רבי יצחק בן חקולא","l":"י","b":"ע\"ע ר\u0027 יצחק בן חקלא, וע\"ע רבי יצחק בן אלעזר."},{"i":2452,"n":"ר\u0027 יצחק בן חקולי","l":"י","b":"מובא בירושלמי (פאה פ\"א ה\"ד), והוא ר\u0027 יצחק בן חקלא."},{"i":2453,"n":"ר\u0027 יצחק בן חקלא","l":"י","b":"הוא רבי יצחק בן אלעזר [כצ\"ל] (פסחים קי\"ג ע\"ב)."},{"i":2454,"n":"רבי יצחק בן טבלא","l":"י","b":"הוא רבי יצחק בן חקלא, הוא רבי יצחק בן אלעזר [כצ\"ל] (פסחים קי\"ג ע\"ב)."},{"i":2455,"n":"ר\u0027 יצחק בן טבלאי","l":"י","b":"מובא בבבלי (יומא ל\"ט ע\"ב), והוא ר\u0027 יצחק בן טבלא."},{"i":2456,"n":"ר\u0027 יצחק בן פנחס","l":"י","b":"תנא מאחרוני התנאים בדור החמישי. רב יהודה מסר משמו (חולין כ\"ז ע\"ב). מאמרו מובא אחרי מאמרו של איסי בן יהודה (אבות דר\"נ פכ\"ט - ז\u0027): \"כל מי שיש בידו מדרש ואין בידו הלכות, לא טעם טעם של חכמה, יש בידו הלכות ולא מדרש, לא טעם טעם יראת חטא\" (פסחים קי\"ד ע\"א, ברשב\"ם: \"רבי יצחק סתם באגדתא הוא רבי יצחק בן פנחס\")."},{"i":2457,"n":"ר\u0027 יצחק בן פרנך","l":"י","b":"מובא בכלה רבתי (רפ\"ג). מאמרו: \"כל עונות של אדם חקוקין לו על עצמותיו\"."},{"i":2458,"n":"ר\u0027 יצחק בן תרדיון","l":"י","b":"מובא במדרש תהלים (פל\"א - ו\u0027), ואולי צ\"ל: ר\u0027 יצחק בר מריון."},{"i":2459,"n":"ר\u0027 יצחק בר אבא","l":"י","b":"אמורא בדור הרביעי. יתכן שהיה מארץ ישראל, שכן מכונה בתואר \"רבי\" ומצינו אותו בבבל. היה גדול מאביי (זבחים ה\u0027 ע\"א)."},{"i":2460,"n":"ר\u0027 יצחק בר אבא בר מחסיא","l":"י","b":"אמורא בבלי בדור השני. תלמידו של רב. ישב יחד עם רב חננאל לפני רב (ירו\u0027, מגילה פ\"ב ה\"ב)."},{"i":2461,"n":"רבי יצחק בר אבדימי א\u0027","l":"י","b":"תנא בדור החמישי, והוא ר\u0027 יצחק רובה (ירו\u0027, שבת פ\"ג ה\"ג), או ר\u0027 יצחק רבה (ירו\u0027, ברכות פ\"ה ה\"ב). מסר משום רבי (ירו\u0027, ר\"ה פ\"א ה\"ג) או משום רבינו, והכוונה לרבי (יבמות מ\"ה ע\"א רש\"י). היה ה\"תנא\" (שונה משניות וברייתות) בישיבתו של רבי (ירו\u0027, מע\"ש רפ\"ה). ורבי אומר: \"שאלון לרבי יצחק רובא, דבחנת ליה כל מתניתא\" (שם) ומפרש \"פני משה\": \"כלומר, אע\"פ שאני הוא הסותם המשנה, מ\"מ מסרתי לו ההבחנה של כל המשנה שהוא יבחין לסדר אותן על הסדר\". היה מקורב מאוד לרבי, וליווהו אפילו לבית המרחץ (שבת מ\u0027 ע\"ב). אחד מתלמידיו היה רב (חולין ק\"י ע\"א). מסרו בשמו ר\u0027 יעקב בר אידי (ירו\u0027, ברכות פ\"ה ה\"ב) ור\u0027 אבא בר יעקב (שם פ\"ו ה\"א)."},{"i":2462,"n":"רב יצחק בר אבדימי ב\u0027","l":"י","b":"אמורא בבלי בדור השני - השלישי. היה תלמידו של רב (ברכות ל\u0027 ע\"ב). תוספות כתבו: \"דעל כרחך רב יצחק בר אבדימי הוא תלמידו של רב\" (ב\"ב פ\"ז ע\"א ד\"ה: מי). חברו של רב חסדא, ונחלק עמו תדיר באגדה ובעניני מקראות (סנהדרין נ\"ו ע\"ב). רבא קבל ממנו (יבמות ג\u0027 ע\"א)."},{"i":2463,"n":"ר\u0027 יצחק בר אבודימי","l":"י","b":"מובא בבבלי (יבמות מ\"ה ע\"א), והוא רבי יצחק בר אבדימי א\u0027."},{"i":2464,"n":"רב יצחק בר אבין","l":"י","b":"אמורא בבלי שאין לקבוע את זמנו המדוייק. מובא כמה פעמים בש\"ס (קידושין ע\"ז ע\"א). בד\"כ דבריו בענייני הלכה, ומבהיר דברי הקודמים לו."},{"i":2465,"n":"רב יצחק בר אדא","l":"י","b":"אמורא בבלי בדור השני. תלמידו של רב (חולין ט\"ו ע\"ב)."},{"i":2466,"n":"ר\u0027 יצחק בר אוריון","l":"י","b":"אמורא ארץ ישראלי, ומשמע שהיה בדור הרביעי, דור ר\u0027 ירמיה (ירו\u0027, שבת פ\"י ה\"ו)."},{"i":2467,"n":"ר\u0027 יצחק בר אחא","l":"י","b":"אמורא ארץ ישראלי בדור השני. כל ר\u0027 יצחק האמורא המוזכר בש\"ס בענייני הלכה הוא ר\u0027 יצחק בר אחא (פסחים קי\"ד ע\"א רש\"י ורשב\"ם). היה תלמידם של ר\u0027 יוחנן (ברכות ל\"ה ע\"ב), ור\u0027 שמעון בן לקיש (ע\"ז י\"ד ע\"א) ור\u0027 אלעזר (ע\"ז ע\u0027 ע\"ב). היה גם בבבל, ורב חסדא שאל ממנו (ברכות כ\"ז ע\"א)."},{"i":2468,"n":"רבי יצחק בר איסטייה","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם ריש לקיש (ירו\u0027, יבמות פ\"א ה\"א)."},{"i":2469,"n":"ר\u0027 יצחק בר אלישיב","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בענייני הלכה (ירו\u0027, סוכה פ\"א הי\"א). ר\u0027 מני היה תלמידו המובהק (תענית כ\"ג ע\"ב). היה מפורסם כאדם גדול ובעל מופת (שם). כשנפטר פרצה מכת גניבות, שכן בזכותו לא באו גנבים (מו\"ק כ\"ה ע\"ב). ובירושלמי מובא, שבמותו נעקרו שבעים משקופים בגליל, שהיו תלויים בזכותו (ע\"ז פ\"ג ה\"א)."},{"i":2470,"n":"ר\u0027 יצחק בר אמי","l":"י","b":"אמורא בבלי בדור השלישי. תלמידו של רב חסדא (מו\"ק י\u0027 ע\"ב). ביקר את רב חסדא בביתו (שבת קכ\"ח ע\"א) והיה בפטירתו (מו\"ק כ\"ה ע\"א). ר\"ז מסר בשמו (חולין מ\"ט ע\"א). היה ענו ונוח לבריות (תענית ט\"ז ע\"א רש\"י). היה בקי גדול במקרא (סנהדרין ס\u0027 ע\"א)."},{"i":2471,"n":"רב יצחק בר אשי","l":"י","b":"אמורא בבלי בדור השני. תלמידו של רב (פסחים מ\"ה ע\"ב)."},{"i":2472,"n":"רב יצחק בר אשיאן","l":"י","b":"אמורא בבלי בדור השלישי. תלמידו של רב הונא (סוכה מ\"ב ע\"א). רב אידי בר אבין היה תלמידו (ברכות י\"ד ע\"א)."},{"i":2473,"n":"רב יצחק בר ביזנא","l":"י","b":"אמורא בבלי בדור השני. תלמידו של שמואל (ירו\u0027, שקלים פ\"ח ה\"ב)."},{"i":2474,"n":"רב יצחק בר ביסנא","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי אמי. נראה, שהיה גם תלמידו של רבי אסי (זבחים כ\u0027 ע\"א). שאל את ר\u0027 ביבי (ירו\u0027, שקלים פ\"ח ה\"א). מתיב על דברי רבי זירא (זבחים מ\"ג ע\"ב). מובא מעשה שאבדו לו בשבת מפתחות דבית המדרש ושאל לר\u0027 פדת, בנו של רבי אלעזר (יבמות קי\"ג ע\"ב)."},{"i":2475,"n":"ר\u0027 יצחק בר בר חנא","l":"י","b":"אמורא בבלי בדור השני. סיפר: \"אנא חזיתיה לזעירי, דאזל לגבי רב חייא בר אשי תלמידו\" (יומא ע\"ז ע\"ב)."},{"i":2476,"n":"רב יצחק בר גופתא","l":"י","b":"אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר\u0027 מנא (ירו\u0027, שבת פ\"ג ה\"ה)."},{"i":2477,"n":"רב יצחק בר גיורי","l":"י","b":"מובא בבבלי (תענית כ\"ט ע\"ב), והוא ר\u0027 יצחק בר יעקב בר גיורי."},{"i":2478,"n":"ר\u0027 יצחק בר חייא","l":"י","b":"מובא בויק\"ר (פכ\"ו - ז\u0027)."},{"i":2479,"n":"ר\u0027 יצחק בר חלוב","l":"י","b":"אמורא ארץ ישראלי בדור השני - השלישי. גדול הדור בימי ר\u0027 אמי: \"ור\u0027 אמי משדר להו לקמיה דרבי יצחק בר חלוב, דמורי בה להיתירא משום ר\u0027 יהושע בן לוי\" (חולין צ\"ט ע\"ב)."},{"i":2480,"n":"ר\u0027 יצחק בר חלוקה","l":"י","b":"מובא בפדר\"כ (ק\"פ), והוא זהה לר\u0027 יצחק בר חלקיה."},{"i":2481,"n":"ר\u0027 יצחק בר חלקיה","l":"י","b":"מובא בויק\"ר (פ\"ל - ג\u0027), והוא זהה לר\u0027 יצחק בר חלוקה. ר\u0027 יצחק בר חמא - אמורא ארץ ישראלי בדור החמישי. מובא במדרש תהלים (פ\"ב - ו\u0027). ומצינו: ר\u0027 יצחק הכהן בר חמא בשם ר\u0027 חלקיה (פס\u0027 רבתי פ\u0027 אנכי מנחמכם ס\"ג)."},{"i":2482,"n":"רב יצחק בר חנינא","l":"י","b":"אמורא בבלי בדור השלישי. תלמידו של רב הונא (כתובות ד\u0027 ע\"ב)."},{"i":2483,"n":"ר\u0027 יצחק בר חנינא בר פפא בר יצחק","l":"י","b":"מובא בפס\u0027 רבתי (ס\"פ ויקח אליהו כ\"ג)."},{"i":2484,"n":"ר\u0027 יצחק בר חנניה","l":"י","b":"מובא בבבלי (נדרים ל\"ח ע\"ב), והוא ר\u0027 יצחק בר חנינא תלמידו של רב הונא."},{"i":2485,"n":"ר\u0027 יצחק בר חקורי","l":"י","b":"מובא בב\"ר (פנ\"ד - ה\u0027)."},{"i":2486,"n":"רבי יצחק בר טבליי","l":"י","b":"מובא בירושלמי (דמאי פ\"ב ה\"א), והוא רבי יצחק בן טבלא."},{"i":2487,"n":"ר\u0027 יצחק בר יונתן","l":"י","b":"אמורא בבלי בדור השני. ישב יחד עם רב הונא ופסק בדיני נדה (ירו\u0027, נדה ספ\"ב)."},{"i":2488,"n":"ר\u0027 יצחק בר יוסי (2)","l":"י","b":"מובא בבבלי (נדה ס\"ה ע\"ב), והוא ר\u0027 יצחק בר יוסף."},{"i":2489,"n":"ר\u0027 יצחק בר יוסי מחוזאה","l":"י","b":"מובא ב\"זוהר\" (נח ס\"ג)."},{"i":2490,"n":"רב יצחק בר יוסף","l":"י","b":"אמורא בדור השלישי - הרביעי. תלמידם המובהק של ר\u0027 ירמיה (חולין מ\"ח ע\"א), ורבי אבהו (פסחים ע\"ב ע\"א). היה מ\"הנחותי\" שהעבירו את תורת ארץ ישראל לבבל, ועמד בשורה אחת עם רב דימי, רבין ורב שמואל בר יצחק (ע\"ז ע\"ג ע\"א), ואביי סבר שהיה קטן מרבין, שרבין בר סמכא והוא אינו בר סמכא, ורבין ישנו בחזרה (מצוי כל שעה לפני ר\u0027 יוחנן) והוא אינו בחזרה (יבמות ס\"ד ע\"ב). מכונה גם יצחק סומקא (שם). מסר משום ר\u0027 יוחנן (שבת נ\"ח ע\"א)."},{"i":2491,"n":"ר\u0027 יצחק בר יעקב בר גוריא","l":"י","b":"הוא ר\u0027 יצחק בר יעקב בר גיורי."},{"i":2492,"n":"רב יצחק בר יעקב בר גיורי","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. (נראה שלא נסמך ולכן מכונה \"רב\" ולא \"רבי\"). תלמידו של רבי יוחנן, ונהג לשלוח משמיה דר\u0027 יוחנן מארץ ישראל לבבל (עירובין ס\"ב ע\"א)."},{"i":2493,"n":"ר\u0027 יצחק בר כהנא","l":"י","b":"מובא בירושלמי (שבת פ\"ח ה\"א), ואולי צ\"ל: ר\u0027 יצחק בר ביסנא, וכך מובא במקום אחר (ירו\u0027, שקלים פ\"ח ה\"א)."},{"i":2494,"n":"ר\u0027 יצחק בר מנחם","l":"י","b":"מובא במדרש תהלים (ספל\"ד)."},{"i":2495,"n":"ר\u0027 יצחק בר מרי","l":"י","b":"אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר\u0027 יוסי בר אבין. ואמר לפניו משם ר\u0027 יוחנן (ירו\u0027, ברכות פ\"ו ה\"א)."},{"i":2496,"n":"ר\u0027 יצחק בר מריון","l":"י","b":"אמורא ארץ ישראלי בדור השני - השלישי. מסר בשם רבי חנינא (ירו\u0027, יבמות ספ\"ו) ושאל מרב אלעזר (ירו\u0027, סוכה פ\"ב ה\"ה). ר\u0027 אבהו מסר בשמו (ירו\u0027, יבמות שם). כן מסר בשמו ר\u0027 יונתן בר חגי (קה\"ר פ\"ט - י\"ב)."},{"i":2497,"n":"ר\u0027 יצחק בר משרשיא","l":"י","b":"מובא בירושלמי (שבת פי\"ב ה\"ד) שאמר בשם רבנן דתמן. ואולי הוא זהה לר\u0027 יצחק בריה דרב משרשיא."},{"i":2498,"n":"ר\u0027 יצחק בר מתנה","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו המובהק של ר\u0027 יוחנן. מובא רק פעם אחת בירושלמי (ע\"ז פ\"ג הי\"א)."},{"i":2499,"n":"ר\u0027 יצחק בר נחמן","l":"י","b":"מובא בירושלמי (סוכה פ\"ג ה\"ו), והוא ר\u0027 יצחק בר נחמני."},{"i":2500,"n":"ר\u0027 יצחק בר נחמני","l":"י","b":"אמורא ארץ ישראלי בדור השני - השלישי. היה תלמידו המובהק של ר\u0027 יהושע בן לוי (חולין מ\"ה ע\"א) וכן היה תלמידם של ר\u0027 אושעיא (שבת ל\"ז ע\"א) ור\u0027 שמעון בן לקיש (בכורות י\"ג ע\"א). נראה כתלמידו של ר\u0027 אלעזר (חולין מ\"ה ע\"א). גם ר\u0027 אלעזר שאל ממנו (ירו\u0027, יבמות פ\"ח ה\"א). יתכן שהיה בבבל, שכן מצינו: \"אמר ר\u0027 יצחק בר נחמני אמר שמואל\" (ר\"ה י\"ג ע\"ב). חברו היה ר\u0027 יעקב בר אידי, ושניהם היו פרנסים (ירו\u0027, סוף פאה). ומשמו אמר ר\u0027 יעקב בר אחא (ירו\u0027, כלאים פ\"ב ה\"ג)."},{"i":2501,"n":"רבי יצחק בר נפתלי","l":"י","b":"אמורא בבלי בדור הששי. מובא בבבלי, ש\"אמר לרבינא \u0027הכי אמרינן משמיה דרבא כוונתך\u0027\" (כתובות צ\"ו ע\"א)."},{"i":2502,"n":"ר\u0027 יצחק בר סברין","l":"י","b":"אמורא שאין לקבוע זמנו ומקומו. מובא בבבלי (זבחים ט\u0027 ע\"א)."},{"i":2503,"n":"ר\u0027 יצחק בר סימון","l":"י","b":"מובא באיכ\"ר (פ\"א פסוק דרכי ציון)."},{"i":2504,"n":"ר\u0027 יצחק בר פנחס","l":"י","b":"אמורא ארץ ישראלי בדור השני. כל ר\u0027 יצחק סתם באגדתא, הוא ר\u0027 יצחק בר פנחס (פסחים קי\"ד ע\"א רש\"י ורשב\"ם). היה תלמידם של ר\u0027 יוחנן (שבת קמ\"ט ע\"ב) ור\u0027 אלעזר (סנהדרין פ\"ב ע\"א). היה גם בבבל ור\u0027 נחמן שאל ממנו (תענית ה\u0027 ע\"א)."},{"i":2505,"n":"ר\u0027 יצחק בר קפרא","l":"י","b":"מובא בקה\"ר (פ\"ט - ח\u0027), ונראה שיש איזה ט\"ס בשם."},{"i":2506,"n":"ר\u0027 יצחק בר קצצתה","l":"י","b":"מובא בירושלמי (ר\"ה פ\"א ה\"א), והוא ר\u0027 יצחק בר קצרתה."},{"i":2507,"n":"ר\u0027 יצחק בר קצרתה","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. אמר בשם ר\u0027 יונה (מד\u0027 שמואל פכ\"ו - ה\u0027). שמו בא בשיבוש (ירו\u0027, ר\"ה פ\"א ה\"א): ר\u0027 יצחק בר קצצתה, והגיר\u0027 ב\"יוחסין\" וב\"סה\"ד\": \"ר\u0027 יצחק קריצפא\"."},{"i":2508,"n":"ר\u0027 יצחק בר רדיפא","l":"י","b":"אמורא בבלי שעלה לארץ ישראל. היה בדור השלישי - הרביעי. תלמידו של רב הונא (שבת כ\"ג ע\"ב) ורבי אמי (כתובות ק\"ו ע\"א). שאל לר\u0027 ירמיה (שביעית פ\"ט ה\"ד)."},{"i":2509,"n":"רב יצחק בר שילא","l":"י","b":"אמורא בבלי בדור הרביעי. תלמידו של ר\u0027 מתנא, שאמר משום רב חסדא (קידושין ל\"ב ע\"א)."},{"i":2510,"n":"רב יצחק בר שמואל","l":"י","b":"מובא בבבלי (כתובות ג\u0027 ע\"א), והוא כנראה ט\"ס, וצ\"ל: רב יצחק בר שמואל בר מרתא."},{"i":2511,"n":"רב יצחק בר שמואל בר מרתא","l":"י","b":"אמורא בבלי בדור השני - השלישי. אביו רב שמואל בר מרתא, היה בן דודו של רב. רב יצחק היה תלמידו המובהק של רב (חולין ק\"ו ע\"ב). גם אביו רב שמואל בר מרתא קיבל מרב (פסחים קי\"ג ע\"ב). אחר פטירת רב, היה לתלמידו של רב הונא (כתובות כ\"א ע\"ב). ישב גם לפני רב כהנא ב\u0027 (נדה כ\"ו ע\"ב) ולפני רב נחמן (חולין ל\"ה ע\"א). ר\u0027 זירא היה תלמידו (חולין ל\u0027 ע\"ב). כן קיבלו ממנו: ר\u0027 אבא (כתובות כ\"א ע\"ב) ורבה בר בר חנה (גיטין כ\"ח ע\"א)."},{"i":2512,"n":"רב יצחק ברבי","l":"י","b":"מובא בבבלי (נדרים כ\"ט ע\"ב) וצ\"ל: רב יצחק בר יוסף."},{"i":2513,"n":"רב יצחק בריה דרב","l":"י","b":"מובא בירושלמי (ברכות פ\"ג ה\"א), ונראה שיבוש בשם."},{"i":2514,"n":"רב יצחק בריה דרב אידי","l":"י","b":"מובא בבבלי (ברכות ד\u0027 ע\"א)."},{"i":2515,"n":"רב יצחק בריה דרב יהודה","l":"י","b":"אמורא בבלי בדור השלישי. בנו של האמורא המפורסם רב יהודה; אביו לימדו תורה (פסחים ק\"ד ע\"ב) והיה רבו המובהק (עירובין צ\"ז ע\"א). כן למד לפני רב הונא (נדה י\"ז ע\"ב). ולפני רמי בר חמא ועזבו, ובא לפני רב ששת (זבחים צ\"ו ע\"ב). עולא איקלע לפומבדיתא ושאל לרב יהודה: מדוע ר\u0027 יצחק בנו טרם התחתן (קדושין ע\"א ע\"ב). בת בנו חומא, התחתנה עם אביי (כתובות ס\"ה ע\"א)."},{"i":2516,"n":"רב יצחק בריה דרב משרשיא","l":"י","b":"אמורא בבלי בדור החמישי - הששי. היה מחשובי הדור בזמן רב פפא: \"שאני רב יצחק בריה דרב משרשיא דאדם חשוב הוא\" (ע\"ז ח\u0027 ע\"ב). פעם נזדמן לבית רב אשי והסביר שם דין (חולין ק\"ד ע\"ב), ורב אשי הוסיף אחרי דבריו (מנחות כ\"ד ע\"ב)."},{"i":2517,"n":"רב יצחק בריה דרבה בר בר חנה","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. אולי היה תלמידו של רבא (סוכה מ\"ג ע\"ב). נשא לאשה את חומה, ולאחר שנפטר התחתן עמה אביי (יבמות ס\"ד ע\"ב)."},{"i":2518,"n":"ר\u0027 יצחק בריה דרבי חייא כהנא","l":"י","b":"כן גורסים התוספות (בכורות י\"ט ע\"א ד\"ה: איש), ובירושלמי שלפנינו הגיר\u0027: ר\u0027 יצחק בריה דר\u0027 חייא כתובה."},{"i":2519,"n":"ר\u0027 יצחק בריה דר\u0027 חייא ברובה","l":"י","b":"מובא בירושלמי (תרומות פ\"ח ה\"ד), ונראה שצ\"ל: ר\u0027 יצחק בריה דר\u0027 חייא כתובה, כמו שמובא במקום אחר (ירו\u0027, פסחים פ\"א ה\"ח)."},{"i":2520,"n":"ר\u0027 יצחק בריה דר\u0027 חייא כתובה","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. \"קרבן העדה\" מפרש: \"כך שמו\" (ירו\u0027, פסחים פ\"א ה\"ח). חברו של ר\u0027 יודן. ר\u0027 יודן בא לבקרו באבל משפחתי (ירו\u0027, ברכות פ\"ג ה\"א)."},{"i":2521,"n":"ר\u0027 יצחק בריה דר\u0027 חייא מטיבא","l":"י","b":"מובא בירושלמי (יבמות פי\"ג הי\"ג), והוא ר\u0027 יצחק בריה דר\u0027 חייא כתובה."},{"i":2522,"n":"יצחק דבי ר\u0027 ינאי","l":"י","b":"מובא בבבלי (יומא פ\"ו ע\"א), וגיר\u0027 \"דק\"ס\": יצחק בריה דר\u0027 אמי."},{"i":2523,"n":"ר\u0027 יצחק דהבן","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. כשעבדיו ברחו, בא לברר דין אצל רבי אמי (ירו\u0027, גיטין פ\"ד ה\"ו)."},{"i":2524,"n":"ר\u0027 יצחק דיהבא","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. מצינו ששאל לר\u0027 יוחנן (ירו\u0027, ביצה פ\"א ה\"ט)."},{"i":2525,"n":"ר\u0027 יצחק דמן קרטיגנין","l":"י","b":"מובא בבבלי שאמר: \"הני תשע דראש השנה כנגד מי? כנגד תשעה אזכרות שאמרה חנה בתפלתה\" (ברכות כ\"ט ע\"א)."},{"i":2526,"n":"ר\u0027 יצחק הבבלי","l":"י","b":"מובא בב\"ר (פמ\"ג - ו\u0027), שאמר מלכי צדק נולד מהול."},{"i":2527,"n":"ר\u0027 יצחק הכהן בר חמא","l":"י","b":"מובא בפס\u0027 רבתי (פ\u0027 אנכי מנחמכם ס\"ג). ונראה שהוא זהה לר\u0027 יצחק בר חמא."},{"i":2528,"n":"יצחק כפתורא","l":"י","b":"מובא ב\"זוהר\" (תצוה קפז)."},{"i":2529,"n":"ר\u0027 יצחק מגדלאה","l":"י","b":"אמורא ארץ ישראלי בדור הראשון. מפרש כוונות המשנה (ב\"מ כ\"ה ע\"א; נדה ל\"ג ע\"א). מסר בשם רבי יהודה הנשיא (ב\"ר פצ\"ג - ז\u0027). רבי יוחנן דן במאמרו (נדה כ\"ז ע\"ב)."},{"i":2530,"n":"ר\u0027 יצחק מגדלים","l":"י","b":"מובא בפס\u0027 רבתי (פ\u0027 ותשלם), וצ\"ל: ר\u0027 יצחק מגדלאה."},{"i":2531,"n":"ר\u0027 יצחק נפחא","l":"י","b":"אמורא ארץ ישראלי בדור השני - השלישי. נראה, שהיה תלמידו של ר\u0027 יוחנן (ב\"מ כ\"ד ע\"ב). אולי אף שמע מר\u0027 אלעזר (מו\"ק כ\"ד ע\"ב). רבי שמעון בן לקיש החשיבו מאד ואמר עליו: \"טבא דנפחא, מדבר נפחא\" (טובים דברי ר\u0027 יצחק נפחא מדברי בן נפחא הוא ר\u0027 יוחנן שנקרא בר נפחא על שם יופיו) (סנהדרין צ\"ו ע\"א). חבריו היו ר\u0027 אבהו ור\u0027 חייא בר פפי (ב\"ק קי\"ז ע\"ב). ר\u0027 אמי ור\u0027 אסי ישבו לפניו (ב\"ק ס\u0027 ע\"ב). היה בבבל ודרש אפתחא דריש גלותא (שבת קכ\"ו ע\"ב), ושוב דרש אקלעא דריש גלותא, שמע ר\u0027 ששת, איקפד, אמר: \"אטו דידיה היא וכו\u0027\" (מו\"ק כ\"ד ע\"ב). היה זהיר במעשים טובים (חולין ק\"י ע\"א רש\"י). נראה, שהאריך ימים, שכן בתו נישאה לרב פפי, אמורא בדור החמישי (חולין קי\"א ע\"ב)."},{"i":2532,"n":"יצחק סומקא","l":"י","b":"מובא בבבלי (יבמות ס\"ד ע\"ב), הוא ר\u0027 יצחק בר יוסף."},{"i":2533,"n":"יצחק סחורה","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי (תענית פ\"ד ה\"א), ששאל לר\u0027 יצחק."},{"i":2534,"n":"ר\u0027 יצחק עטושיא","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. היה תלמידו של רבי שמעון בן לקיש (ירו\u0027, ביצה פ\"א ה\"ט). רבו היה רבי זירא (ירו\u0027, פאה פ\"ח ה\"ד). לפי דעה אחת היה גם תלמידו של ר\u0027 ירמיה (ירו\u0027, נזיר פ\"ג ה\"א). היה לו בן חכם ושמו ר\u0027 חייא, שהיה תלמידו של ר\u0027 ירמיה (שם)."},{"i":2535,"n":"ר\u0027 יצחק פסקאה","l":"י","b":"אמורא ארץ ישראלי בדור השני. כשמת ר\u0027 יוסי ממלחיא באו רבי יוחנן, ר\u0027 שמעון בן לקיש ור\u0027 יצחק פסקאה, והיה שם סבא אחד שרצה להספידו, ואמר לו ר\u0027 יצחק: \"איך תספיד לפני אריות אלו\" (איכ\"ר פ\"א - ל\"ז)."},{"i":2536,"n":"ר\u0027 יצחק קטריקי","l":"י","b":"מובא בפדר\"כ (ל\"ט), ואולי הוא ר\u0027 יצחק דמן קרטיגנין."},{"i":2537,"n":"ר\u0027 יצחק קסקסאה","l":"י","b":"אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של ר\u0027 יוסי בר אבין, ותרגם לפניו משמו של רבי יוחנן (ברכות נ\"א ע\"א)."},{"i":2538,"n":"ר\u0027 יצחק רבה","l":"י","b":"מובא בירושלמי (ברכות פ\"ה ה\"ב), והוא רבי יצחק בר אבדימי א\u0027."},{"i":2539,"n":"ר\u0027 יצחק רביא","l":"י","b":"מובא בב\"ר (פ\"ק - י\"ב), ואולי הוא ר\u0027 יצחק רובא."},{"i":2540,"n":"יצחק רובא","l":"י","b":"מובא בירושלמי (שבת פ\"ג ה\"ג), והוא רבי יצחק בר אבדימי א\u0027."},{"i":2541,"n":"יצחק ריש גלותא","l":"י","b":"בן אחותו של רב ביבי (אמורא בבלי בדור השלישי). הלך מקורטבא לאספמיא ומת שם (יבמות קט\"ו ע\"ב). \"סה\"ד\" מביא בשם הרא\"ש בתשובה כלל נ\u0027, שלא היה ריש גלותא, אלא כך היה שמו."},{"i":2542,"n":"ר\u0027 יקים","l":"י","b":"אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מבעלי האגדה. מובא בש\"ר (פמ\"ב - ט\u0027)."},{"i":2543,"n":"ר\u0027 יקים איש הדר","l":"י","b":"תנא בדור השני. העיד עם ר\u0027 יהושע (עדיות פ\"ז מ\"ה)."},{"i":2544,"n":"ירמיה","l":"י","b":"חי בארץ ישראל בדור השני לאמוראי ארץ ישראל. אחיו עוקבן הבבלי שלח תלונה עליו למר עוקבא לבבל (סנהדרין ל\"א ע\"ב), ואין להוכיח שנמנה עם החכמים."},{"i":2545,"n":"רבי ירמיה (2)","l":"י","b":"מגדולי אמוראי ארץ ישראל בדור הרביעי. נולד בבבל ועלה לארץ ישראל בצעירותו, ובהיותו בבבל עדיין: \"לא ידע מאי קאמרי רבנן\" (כתובות ע\"ה ע\"א). זכה לקבל מר\u0027 יוחנן (שבת ס\"ג ע\"ב רש\"י), אך רבו המובהק היה רבי זירא, שקראו \"בני\" (מו\"ק ד\u0027 ע\"א). כן היה תלמידם של ר\u0027 אבהו (ב\"מ ט\"ז ע\"ב) ור\u0027 אבא (יומא פ\"ז ע\"א). היה מראשי חכמי ארץ ישראל, ובכל מקום בש\"ס שאמרו: \"אמרי במערבא\", הכוונה לר\u0027 ירמיה (סנהדרין י\"ז ע\"ב). על חכמי בבל אמר: \"בבלאי טפשאי\". (פסחים ל\"ד ע\"ב). על תלמוד בבלי קרא: \"במחשכים הושיבני כמתי עולם\" (סנהדרין כ\"ד ע\"א). רבא אמר עליו שהוא שקול כנגד שנים מחכמי בבל (כתובות ע\"ה ע\"א). גדולי האמוראים בארץ ישראל בדור שלאחריו קיבלו ממנו: ר\u0027 יונה (ירו\u0027, מגילה פ\"ד ה\"ה) ור\u0027 יוסי (ירו\u0027, ברכות פ\"א ה\"ב) ורבים אחרים. לפני מותו ציווה להלבישו תכריכים לבנים, ולתת נעליו ברגליו, ומקלו בידו, ולהשכיבו על צדו, שאם יבוא משיח יהיה מוכן (ירו\u0027, כלאים פ\"ט ה\"ג)."},{"i":2546,"n":"רבי ירמיה ביראה","l":"י","b":"אמורא בבלי בדור השלישי. תלמידו של רב יהודה (גיטין ל\"ב ע\"א). רב יהודה כפאו לתת גט לאשתו (שם ל\"ד ע\"א)."},{"i":2547,"n":"ר\u0027 ירמיה בן אלעזר (2)","l":"י","b":"תנא שאין לקבוע זמנו המדוייק. בר קפרא מסר בשמו (ויק\"ר פ\"כ - ח\u0027). ועוד מובא: \"אמר ירמיה בן אלעזר: \u0027עתיד הקב\"ה לחדש מאור פניהם של צדיקים\u0027\" (קה\"ר פ\"א - ז\u0027). בהגהות רד\"ל כתב, שרבי אמר (שם) בשמו לר\u0027 ישמעאל בר\u0027 יוסי (א\"כ, חי כנראה בדור הרביעי לתנאים)."},{"i":2548,"n":"רב ירמיה בר אבא א\u0027","l":"י","b":"אמורא בבלי בדור השני. תלמידו המובהק של רב (ביצה כ\"ב ע\"ב) ואחר כך תלמיד - חבר שלו (ברכות כ\"ז ע\"ב). כן היה תלמידו של שמואל (סוף כתובות). גדולי האמוראים קיבלו ממנו: רב יהודה (בכורות ל\"ו ע\"ב), רב ששת (נדה ס\"ט ע\"א) ורב חסדא (ברכות נ\"ח ע\"ב). רב הונא בר חייא היה חתנו ותלמידו (שבת קנ\"ו ע\"א). בנו רב הונא, ובן בנו מרי, היו חכמים (עירובין כ\"א ע\"א). רב הונא בריה דרב ירמיה מוזכר רק בהקשר לבנו, ואין ממנו בש\"ס. תוספות כתבו ששני ר\u0027 ירמיה בר אבא היו (פסחים ק\"ו ע\"ב)."},{"i":2549,"n":"ר\u0027 ירמיה בר אבא ב\u0027","l":"י","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב הונא (קידושין מ\"ו ע\"א). עלה לארץ ישראל (כתובות קי\"א ע\"א)."},{"i":2550,"n":"רב ירמיה בר אחא","l":"י","b":"אמורא בבלי בדור השני. תלמידו של רב (חולין נ\"א ע\"ב). חלק עם רב חסדא (שם)."},{"i":2551,"n":"ר\u0027 ירמיה בר אלעאי","l":"י","b":"מובא בויק\"ר (רפי\"א)."},{"i":2552,"n":"רב ירמיה בר אמי","l":"י","b":"אמורא בדור השני - השלישי. מצינו שחלק עם רב הונא בר חייא (מו\"ק ט\u0027 ע\"ב). המאמר המובא שם בשמו בא במקומות אחרים בשינוי שמות (פסחים מ\"ג ע\"א; מגילה י\"ג ע\"א), ונראה שיש שיבוש וט\"ס בשם."},{"i":2553,"n":"ר\u0027 ירמיה בר חנינא","l":"י","b":"מובא בירושלמי (שבת פ\"ד ה\"א), ואולי צ\"ל: ר\u0027 יוסי בר חנינא, (כדאיתא ריש הלכה א\u0027)."},{"i":2554,"n":"ר\u0027 ירמיה בר יצחק","l":"י","b":"מובא בתנחומא (תשא - י\"ח). יתכן שיש שיבוש בשם (עיין ש\"ר פמ\"ז - ג\u0027)."},{"i":2555,"n":"ר\u0027 ירמיה בר שלום","l":"י","b":"מובא במדרש משלי (רפ\"א)."},{"i":2556,"n":"ר\u0027 ירמיה בר שמעיה","l":"י","b":"מובא בב\"ר (פצ\"ג - ו\u0027)."},{"i":2557,"n":"ר\u0027 ירמיה בר תחליפא","l":"י","b":"אמורא שאין לקבוע את מקומו. נראה שחי בדור הרביעי. תלמידו של ר\u0027 יעקב, שאמר לו: \"אסברה לך\" (ב\"ב ס\u0027 ע\"ב)."},{"i":2558,"n":"ר\u0027 ירמיה בריה דר\u0027 חייא בר אבא","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. בנו של רבי חייא בר אבא. אמר יחד עם ר\u0027 ברכיה בשם לוי בר סיסי (ויק\"ר פכ\"ג - ח\u0027)."},{"i":2559,"n":"ר\u0027 ירמיה בר\u0027 שמעון","l":"י","b":"מובא בירושלמי (שבת פ\"ג ה\"א דפוס ויניציא)."},{"i":2560,"n":"ר\u0027 ירמיה כהנא","l":"י","b":"מובא בב\"ר (פ\"ז - ד\u0027)."},{"i":2561,"n":"רב ירמיה מדיפתיא","l":"י","b":"אמורא בבלי בדור החמישי - הששי. מסר משמו של רבא (זבחים ל\"ד ע\"ב). נראה, שהיה גם תלמידו של רב פפא (ב\"ק ע\"ג ע\"א). היה תלמידו המובהק של רב פפי (ע\"ז ח\u0027 ע\"א). רבינא ישב לפניו (קדושין ל\"ג ע\"א). ר\u0027 אשי חלק עמו (שבת ע\"ד ע\"א)."},{"i":2562,"n":"ר\u0027 ירמיה ספרא","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. שאל לר\u0027 ירמיה (ירו\u0027, תענית פ\"ד ה\"א)."},{"i":2563,"n":"ר\u0027 ירמיה רבה","l":"י","b":"מובא בבבלי (שבת כ\"ט ע\"ב)."},{"i":2564,"n":"ר\u0027 ירמיה שיבשב","l":"י","b":"אמורא בבלי בדור השני. חתך זמורה ועשה ממנה עטרה וזה היה בניגוד לדעת החכמים ושמואל רגז על כך ומת ר\u0027 ירמיה שיבשב (ירו\u0027, סוטה פ\"ט הט\"ו, וראה \"קרבן העדה\" ו\"פני משה\")."},{"i":2565,"n":"ר\u0027 ישבב","l":"י","b":"תנא בדור השלישי. תלמידו של רבי יהושע (תוספתא חולין פ\"ב ב\u0027) וחברו המובהק של רבי עקיבא (כתובות כ\"ט ע\"ב; שם נ\u0027 ע\"א). נמנה עם עשרת הרוגי מלכות (איכ\"ר פ\"ב - ד\u0027) והיה בן תשעים וחמש שנה כשנהרג. נהג לחלק נכסיו לעניים (ירו\u0027, פאה פ\"א ה\"א)."},{"i":2566,"n":"ר\u0027 ישבב הסופר","l":"י","b":"מובא במדרש (אלה אזכרה), והוא ר\u0027 ישבב."},{"i":2567,"n":"רבי ישמעאל","l":"י","b":"תנא בדור השלישי. מושבו היה בדרום, סמוך לאדום (כתובות ס\"ד ע\"א), ונראה ששם היתה ישיבתו הגדולה \"בי ר\u0027 ישמעאל\". הוא סתם רבי ישמעאל בש\"ס וההוכחה, שמובא מעשה מרבי ישמעאל בן אלישע (בשבת י\"ב ע\"ב). ואותו מעשה מובא (ירו\u0027, שבת פ\"א ה\"ג) בשם סתם רבי ישמעאל. תלמידו המובהק של רבי נחוניא בן הקנה (שבועות כ\"ו ע\"א) ותלמידם של רבי אליעזר (ספרא תזריע פי\"ג) ושל רבי יהושע (ע\"ז כ\"ט ע\"ב) וחברו ובר פלוגתיה המובהק של ר\"ע (יומא ע\"ה ע\"ב). בין תלמידיו הגדולים היו רבי מאיר (עירובין י\"ג ע\"א), רבי יונתן (מנחות נ\"ז ע\"ב), רבי יאשיה (שם), ור\u0027 אלעאי [אביו של ר\u0027 יהודה] (גיטין ו\u0027 ע\"ב). הפירוש על ספר שמות שבידינו, הידוע בשם מכילתא דר\u0027 ישמעאל יצא מבית מדרשו. רבי טרפון אמר עליו: \"חכם גדול הוא ובקי באגדות\" (מו\"ק כ\"ח ע\"ב). בילדותו נשבה והובא לרומי ור\u0027 יהושע פדאו בממון רב (גיטין נ\"ח ע\"א)."},{"i":2568,"n":"ר\u0027 ישמעאל אבי ר\u0027 יודן","l":"י","b":"מובא בירושלמי (גיטין פ\"א ה\"ב)."},{"i":2569,"n":"ישמעאל איש כפר דימא","l":"י","b":"ע\"ע ישמעאל איש כפר ימא."},{"i":2570,"n":"ישמעאל איש כפר ימא","l":"י","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. שאל לר\u0027 אמי ולא ידע להשיב לו ובא לר\u0027 יצחק נפחא והשיב לו (נדרים נ\"ז ע\"ב). הגמרא מפקפקת שם אם היה מכפר ימא או דימא."},{"i":2571,"n":"רבי ישמעאל בן אלישע (2)","l":"י","b":"כהן גדול בבית שני (ברכות ז\u0027 ע\"א). חברו של רבן שמעון בן גמליאל כמובא בבבלי (סוטה מ\"ח ע\"ב), ושניהם היו מעשרה הרוגי מלכות (אדר\"נ פל\"ח - ג\u0027), ורש\"י פירש: \"כהן גדול ומהרוגי מלכות היה\" (ע\"ז י\"א ע\"ב ד\"ה: קרקיפלו של רבי ישמעאל). \"כשנהרג רבי שמעון ורבי ישמעאל באה השמועה אצל רבי עקיבא ורבי יהודה בן בתירא\" (שמחות פ\"ח). היה אולי סבו של רבי ישמעאל בר פלוגתא דר\"ע (\"סה\"ד\")."},{"i":2572,"n":"רבי ישמעאל בן אלעזר","l":"י","b":"תנא שאין לקבוע זמנו. מובא בירושלמי (ברכות ספ\"ב) ובבבלי (שבת ל\"ב ע\"א), ושם גורס \"דק\"ס\" רבי שמעון בן אלעזר."},{"i":2573,"n":"ר\u0027 ישמעאל בן אלעזר הקפר","l":"י","b":"מובא באבות דר\"נ (פכ\"ט - ה\u0027). נראה שיש כאן ט\"ס."},{"i":2574,"n":"רבי ישמעאל בן ברוקה","l":"י","b":"מובא בבבלי (שבת כ\"ו ע\"א). \"סה\"ד\" ו\"דק\"ס\" גורסים: רבי ישמעאל בנו של רבי יוחנן בן ברוקה."},{"i":2575,"n":"ר\u0027 ישמעאל בן גמליאל","l":"י","b":"כך מביא \"סה\"ד\" מן הירושלמי (ברכות פ\"ט ה\"ב), \"אולי ט\"ס, וצ\"ל ר\u0027 שמעון\", אכן בספר \u0027שדה יהושע\u0027 הנוסח גם כן כך. ולפנינו לא נמצא שם זה כלל."},{"i":2576,"n":"ר\u0027 ישמעאל בן זירוד","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. מובא בבבלי: שבא לבקר בחוליו את ר\u0027 ינאי בר\u0027 ישמעאל, ואמר לו: \"הכי אמר רבי שמעון בן לקיש משום רבי חייא וכו\u0027\" (ע\"ז ל\u0027 ע\"ב)."},{"i":2577,"n":"ר\u0027 ישמעאל בן זירוז","l":"י","b":"הוא ר\u0027 ישמעאל בן זירוד."},{"i":2578,"n":"ר\u0027 ישמעאל בן חנניה","l":"י","b":"תנא בדור השני. מובא באבות דר\"נ (פי\"ד), שהיה תלמידו של רבי יוחנן בן זכאי. אבל יש משבשים שם זה לר\u0027 שמעון בן נתנאל ושוב לא מובא שם זה בש\"ס."},{"i":2579,"n":"ר\u0027 ישמעאל בן יהוצדק","l":"י","b":"מובא בבבלי (ב\"מ כ\"ב ע\"ב), שרבי יוחנן אמר בשמו. וכבר הגיה \"מסורת הש\"ס\" שצ\"ל: רבי שמעון בן יהוצדק, וכן הוא ב\"ילקוט\" וכך הוא ברא\"ש וכן הגיה \"דק\"ס\"."},{"i":2580,"n":"רבי ישמעאל בן יוסף","l":"י","b":"הוא התנא רבי ישמעאל בר יוסי בן חלפתא. מובא בירושלמי: \"תני רבי ישמעאל בר יוסף משום אביי\" (יבמות פ\"ז ה\"ג), וצ\"ל: משום אביו."},{"i":2581,"n":"ר\u0027 ישמעאל בן יעקב דמן צור","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. מובא בבבלי, ששאל את רבי יוחנן (כתובות ז\u0027 ע\"א)."},{"i":2582,"n":"רבי ישמעאל בן לוגא","l":"י","b":"תנא בדור השלישי בדורו של רבי עקיבא, כמובא בבלי (יומא ל\"ח ע\"א). \"סה\"ד\" כתב שהוא ט\"ס וצ\"ל: שמעון בן לוגה, כמובא בירושלמי (שקלים פ\"ה). והגיר\u0027 במקום אחר בירושלמי: שמעון בן לגס (יומא פ\"ג ה\"ט)."},{"i":2583,"n":"רבי ישמעאל בן סתריאל","l":"י","b":"תנא בדור החמישי. מושבו היה במקום ששמו ערקת לבנה (בכורות נ\"ז ע\"ב). העיד לפני רבי (שם)."},{"i":2584,"n":"רבי ישמעאל בנו של רבי אלעזר בן עזריה","l":"י","b":"תנא בדור הרביעי. מובא פעם אחת בבבלי: \"רבי ישמעאל ורבי עקיבא ורבי אלעזר בן עזריה מהלכין בדרך, ולוי הסדר ורבי ישמעאל בנו של רבי אלעזר בן עזריה מהלכין אחריהן, נשאלה שאלה זו בפניהם וכו\u0027\" (יומא פ\"ה ע\"א)."},{"i":2585,"n":"רבי ישמעאל בנו של רבי יוחנן בן ברוקא","l":"י","b":"תנא בדור הרביעי. בנו ותלמידו של רבי יוחנן בן ברוקא (ב\"ב ק\"ל ע\"א). חלק על אביו (ב\"ק קי\"ד ע\"א). מובא יחד עם רשב\"ג, אך מוזכר לאחריו (עירובין מ\u0027 ע\"ב). ישב גם ביבנה (יבמות מ\"ב ע\"ב)."},{"i":2586,"n":"ר\u0027 ישמעאל בר אבא","l":"י","b":"אמורא ארץ ישראלי בדור השני. נראה שהיה תלמידו של רבי יהושע בן לוי (חולין קכ\"ב ע\"א) ור\"ל הודה לו (שם)."},{"i":2587,"n":"ר\u0027 ישמעאל בר אמי","l":"י","b":"מובא בויק\"ר (פ\"א - ג\u0027)."},{"i":2588,"n":"ר\u0027 ישמעאל בר ביבי","l":"י","b":"אמורא. מובא בויק\"ר (פי\"א - ח\u0027), ונראה שיש ט\"ס בשם זה, שכן לא מובא בש\"ס."},{"i":2589,"n":"ר\u0027 ישמעאל בר יישוע","l":"י","b":"אמורא ארץ ישראלי בדור השני. \"אמר רבי מתנייה, סלקית לסחורה [עליתי למקום ששמו סחורה] ושמעית ר\u0027 יוחנן ור\u0027 ישמעאל בני יישוע\" (ירו\u0027, יבמות פ\"ז ה\"ו)."},{"i":2590,"n":"ר\u0027 ישמעאל בר יעקב בר אחא","l":"י","b":"מראשוני האמוראים בארץ ישראל. ר\u0027 חנינא מסר משמו (ירו\u0027, שבת פ\"ד ה\"ב). \"סה\"ד\" גרס אחרת."},{"i":2591,"n":"רבי ישמעאל בר נחמן","l":"י","b":"אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי אבדימי דמן חיפא (ויק\"ר רפי\"ח)."},{"i":2592,"n":"ר\u0027 ישמעאל בר ר\u0027 יצחק","l":"י","b":"אמורא ארץ ישראלי בדור השלישי. (ירו\u0027, יומא פ\"ג ה\"ז)."},{"i":2593,"n":"ר\u0027 ישמעאל בר תנחום","l":"י","b":"אמורא ארץ ישראלי בדור החמישי. מובא בויק\"ר (רפכ\"ב), שאמר בשם ר\u0027 ירמיה. ויש גם ב\"ילקוט\" (קהלת פ\"ה פ\u0027 ויתרון): ר\u0027 ישמעאל בר תנחומא בשם ר\u0027 ירמיה, ואולי שניהם אחד."},{"i":2594,"n":"ר\u0027 ישמעאל בר תנחומא","l":"י","b":"מובא ב\"ילקוט\" (קהלת פ\"ה פ\u0027 ויתרון) ואולי הוא ר\u0027 ישמעאל בר תנחום."},{"i":2595,"n":"רבי ישמעאל בר\u0027 יונה","l":"י","b":"מובא בירושלמי (ריש חלה). \"סה\"ד\" מביא בשם \"שדה יהושע\" שט\"ס הוא, ולא היה חכם בשם זה."},{"i":2596,"n":"רבי ישמעאל בר\u0027 יוסי","l":"י","b":"תנא בדור החמישי. בנו ותלמידו של רבי יוסי בן חלפתא (שבת נ\"א ע\"א). אמר פעמים רבות משום אביו (יבמות ס\"ז ע\"א). מושבו של אביו היה בציפורי. אחר פטירת אביו מילא שם את מקומו (עירובין פ\"ו ע\"ב רש\"י). היה תלמידו של רבי יהודה (סוכה י\"ח ע\"א). נראה, שלמד מר\u0027 ישמעאל בר פלוגתיה דרבי עקיבא (יבמות ק\"ד ע\"א). אמרו עליו: \"ר\u0027 ישמעאל בר יוסי תנא הוא ופליג\" (שבת ס\"ד ע\"ב). ואמנם נראה שלמד לפני רבי (יבמות ק\"ה ע\"ב): \"אני ישמעאל בר יוסי שבאתי ללמוד תורה מרבי\". וכן \"פעם חש רבי במעיו וכו\u0027\" אמר לפניו רבי ישמעאל בר יוסי וכו\u0027\" (ע\"ז מ\u0027 ע\"ב). וכן \"פעם שאלו את רבי וכו\u0027 אמר לפניו רבי ישמעאל בר יוסי וכו\u0027\" (נדה כ\"ה ע\"א). אך רש\"י סובר (שבת נ\"א ע\"א) שרבי ישמעאל בר יוסי היה גדול כאביו רבי יוסי, והיה כפוף ויושב לפני רבי \"מפני כבוד הנשיאות, ולא היה מורה לפניו אעפ\"י שגדול הימנו\" (מרבי). ואכן מצינו: \"בעא מיניה רבי מרבי ישמעאל בר\u0027 יוסי\" (שם קי\"ג ע\"ב, וקי\"ט ע\"א). היה חברו של רבי חייא ונכנס לפני רבי חייא לבית הועד (ירו\u0027, כלאים פ\"ט ה\"ג). בין תלמידיו היה ר\u0027 חנינא בר חמא (קדושין ע\"א ע\"א). ומשמע שרב ראהו מתפלל כמובא (ברכות כ\"ז ע\"ב): \"אמר רב: \u0027בצד זה התפלל רבי ישמעאל בר יוסי\u0027\". הצטיין בבקיאותו במקרא ואמר שיכול לכתוב את כל המקרא בעל פה (ירו\u0027, מגילה פ\"ד ה\"א). היו לו ארבעה אחים (שבת קי\"ח ע\"ב). נפטר לפני רבי חייא (ירו\u0027, ב\"ק פ\"ו ה\"ז)."},{"i":2597,"n":"ר\u0027 ישמעאל השזורי","l":"י","b":"כך מובא בירושלמי (שבת פ\"י ה\"ד), והוא ט\"ס וצ\"ל: ר\u0027 שמעון שזורי."},{"i":2598,"n":"ר\u0027 ישעיה","l":"י","b":"תנא בדור השני. תלמידו של רבי חנינא בן דוסא. מובא ב\"ילקוט\" (בא רמז קפז) שהתענה שמונים ושמונה תעניות כדי שיזכה להבין מפני מה זכה הכלב לומר שירה."},{"i":2599,"n":"יששכר דפרמנדי","l":"י","b":"אמורא ארץ ישראלי בדור השני. מובא יחד עם ר\u0027 חמא בר חנינא (ב\"ר פנ\"ב - ו\u0027)."},{"i":2600,"n":"ר\u0027 יתא","l":"י","b":"הוא ר\u0027 איתי."},{"i":2601,"n":"כדי","l":"כ","b":"מובא בבלי 31 פעם (ברכות ל\u0027 ע\"א [לגיר\u0027 \"דק\"ס\"], יומא מ\"ד ע\"א; ע\"ב ע\"ב; מגילה ב\u0027 ע\"ב; גיטין נ\"ד ע\"א; יבמות צ\u0027 ע\"א; ב\"מ ב\u0027 ע\"א; נזיר ב\u0027 ע\"א; הוריות ח\u0027 ע\"א; מנחות נ\"ה ע\"ב; חולין ע\"ג ע\"א; פ\"א ע\"א; קי\"ח ע\"א). בב\"מ (ב\u0027 ע\"א) פירש הרש\"ל: \"בעלמא רגיל רש\"י לפרש שם חכם או פירש בחינם כמו בכדי, כלומר, שלא נזכר שם אמרו, רק סתמא נ\"ל\". ובחולין פירש רש\"ל: \"הוא שם חכם או פי\u0027 בחנם בלאו שום הזכרת חכם\" (ע\"ג ע\"א). ורש\"י פירש: \"וכדי, כלומר בולא כלום באין ספר, כמו כדי נסבה, וכמו [והוי כמו אי נמי], ואמרי לה כדי שם חכם\" (גיטין פ\"ה ע\"ב ד\"ה: ולורכיה)."},{"i":2602,"n":"רבי כהן","l":"כ","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. אחיו של רבי חייא בר אבא (ירו\u0027, שבת פ\"ב ה\"ו). טייל יחד עם רבי אמי, רבי חזקיה ורבי יעקב בר אחא (ירו\u0027, ברכות פ\"ג ה\"ח)."},{"i":2603,"n":"ר\u0027 כהנא","l":"כ","b":"מובא ב\"זוהר\" (תולדות קלט)."},{"i":2604,"n":"רב כהנא אחוה דרב יהודה","l":"כ","b":"אמורא בבלי בדור השלישי. מובא בבבלי (חולין קי\"א ע\"ב): \"יתיב \u0027קמיה\u0027 דרב הונא\". הרא\"ש גורס \"יתיב רב כהנא \u0027אחורי\u0027 (במקום אחוה) דרב יהודה\", ולפי גירסה זו לא היה קיים כלל אמורא ושמו רב כהנא אחוה דרב יהודה, שכן שוב לא הובא שמו בש\"ס."},{"i":2605,"n":"רב כהנא א\u0027","l":"כ","b":"אמורא בבלי בדור הראשון. תלמיד חבר לרב. חברו של רב אסי (סנהדרין ל\"ו ע\"ב). רב החשיבם וכיבדם (שבת קמ\"ו ע\"ב). א\"ל רב כהנא ורב אסי לרב: \"מ\"ט לא מפרשת לן וכו\u0027 א\"ל: \u0027אמינא דלמא לא צריכיתו\u0027\" (נזיר י\"ט ע\"א). מספר פעמים הוא ורב אסי הקשו לרב, ורב שתק, כי הודה להם (ב\"ק ס\"ב ע\"א תד\"ה: ומי זה). חברו רב אסי אף היה גדול משמואל (שם פ\u0027 ע\"ב רש\"י ד\"ה: מלתא). עלה לארץ ישראל ונפגש עם רבי שמעון בנו של רבי (זבחים נ\"ט ע\"א), ועם יהודה וחזקיה, בני רבי חייא (מנחות כ\"ג ע\"א) ושקיל וטרי עמם כחברים. חכמי ארץ ישראל שקיבלו ממנו: רבי אושעיא [רבו של רבי יוחנן] (ירו\u0027, חלה פ\"א ה\"ג), ורבי יוחנן וריש לקיש (ירו\u0027, ר\"ה רפ\"ד)."},{"i":2606,"n":"רב כהנא בר ביזנא","l":"כ","b":"מובא בילקוט (יחזקאל רמז שמ\"ז). יתכן שט\"ס היא, וצ\"ל: רב חנא בר ביזנא."},{"i":2607,"n":"רב כהנא בר טוביא","l":"כ","b":"מובא בבבלי (עירובין ח\u0027 ע\"א) בדפוס שאלוניקי, והגירסא לפנינו: רב כהנא בר מלכיו."},{"i":2608,"n":"כהנא בר ירמיה","l":"כ","b":"אמורא בבלי בדור השלישי. מסר בשם שמואל (ירו\u0027, ערלה פ\"ג ה\"ג)."},{"i":2609,"n":"רב כהנא בר מלכיה","l":"כ","b":"אמורא בבלי בדור השלישי. מסר בשם רב (ירו\u0027, ברכות פ\"ו ה\"א). ע\"ע רב כהנא בר תחליפא."},{"i":2610,"n":"רב כהנא בר מלכיו","l":"כ","b":"מובא בבבלי (עירובין ח\u0027 ע\"ב). ע\"ע רב כהנא בר תחליפא."},{"i":2611,"n":"רב כהנא בר מניומי","l":"כ","b":"מובא בבבלי (עירובין ח\u0027 ע\"ב). ע\"ע רב כהנא בר תחליפא."},{"i":2612,"n":"רב כהנא בר מתנה","l":"כ","b":"ע\"ע רב כהנא בר תחליפא."},{"i":2613,"n":"רב כהנא בר מתתיהו","l":"כ","b":"ע\"ע רב כהנא בר תחליפא."},{"i":2614,"n":"רב כהנא בר תחליפא","l":"כ","b":"חוסר בהירות גדול יש בשם זה ואין להכריע כיצד לגרוס. מובא בבבלי: \"אמר רב כהנא בר תחליפא משמיה דרב כהנא בר מניומי, משמיה דרב כהנא בר מלכיו, משמיה דרב כהנא רביה דרב, ואמרי לה רב כהנא בר מלכיו וכו\u0027\" (עירובין ח\u0027 ע\"ב). והב\"ח גורס שם אחרת, ו\"דק\"ס\" גורס: רב הונא בר תחליפא משמיה דרב כהנא רבה, ובדפוס פיזרו ווינציא רפ\"ה גרס: בר מתתיהו, וכן הוא באו\"ז סקי\"ד. \"סה\"ד\" כתב בערך רב כהנא בר תחליפא: \"וה\u0027יוחסין\u0027 כתב בפ\"ק דעירובין כהנא בר מתתיהו בשם רב כהנא בר מניומי וכו\u0027, ט\"ס הוא, כי הגיר\u0027 כאשר העתקתי וכו\u0027, וכבר הראתיך שט\"ס הוא, וצ\"ל וכו\u0027 וב\"שארית יוסף\" הביא כתלמיד רב, רב כהנא בר מתנה ולא מצאתי זכרו בכל הש\"ס, אולי כונתו לרב כהנא בר מתתיהו הנ\"ל, ובאמת ט\"ס הוא גם לא מצינו שאמר בשם רב\", עכ\"ל. ואני הכותב לא מצאתי ידי ורגלי בכל הגירסאות הנ\"ל. ואין בידי להכריע ומה גם שראיתי כי ה\"יוחסין\" כתב שרב כהנא בר מלכיו היה רבו דרב, ומצאתי בירושלמי (ברכות פ\"ו ה\"א) ההיפך: שרב כהנא בר מלכיו אמר בשם רב, ולכן לא סיווגתים לא כרב ולא כתלמיד."},{"i":2615,"n":"רב כהנא בריה דרב חיננא סבא","l":"כ","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (פסחים ע\"ו ע\"ב)."},{"i":2616,"n":"רב כהנא בריה דרב נחוניא","l":"כ","b":"אמורא בבלי בדור השלישי. שמשו של רב יהודה (תענית כ\"ד ע\"ב)."},{"i":2617,"n":"רב כהנא בריה דרב נחמיה","l":"כ","b":"אמורא בבלי. מובא יחד עם רבא ורב פפא, ואולי היה בדורם (יבמות ע\"א ע\"ב)."},{"i":2618,"n":"רב כהנא בריה דרב נתן","l":"כ","b":"אמורא בבלי שאין לקבוע זמנו המדוייק. יתכן שהיה בזמנו של רב אשי. מובא בבבלי (יבמות ס\u0027 ע\"ב)."},{"i":2619,"n":"רב כהנא בריה דר\u0027 חייא בר אבא","l":"כ","b":"אמורא ארץ ישראלי בדור הרביעי. בנו של רבי חייא בר אבא. מובא בירושלמי: \"ר\u0027 כהנא בריה דר\u0027 חייא בר אבא ור\u0027 אחא מטי בה בשם ר\u0027 יוחנן\". (שבת פ\"א ה\"ד)."},{"i":2620,"n":"רב כהנא ב\u0027","l":"כ","b":"אמורא בבלי בדור השני. תלמידו המובהק של רב (ב\"ק קי\"ז ע\"א). כן קיבל משמואל (יבמות ק\"ב ע\"ב). לאחר שהרג מלשין, נאלץ לברוח לארץ ישראל, ולפי בקשת רב קיבל על עצמו לא להקשות לרבי יוחנן שבע שנים. בתחלה אמרו עליו: \"ארי עלה מבבל\", והושיבוהו בשורה הראשונה לפני רבי יוחנן, ולאחר ששתק ולא הקשה החזירוהו משורה לשורה עד שורה השביעית, ור\u0027 יוחנן אמר לר\"ל: \"ארי שאמרת נעשה שועל\", ואמר רב כהנא: \"יהי רצון ששבע השורות יהיו תחת שבע השנים\" והחל להקשות לר\u0027 יוחנן שלא ידע להשיב לו, והחזירוהו משורה לשורה עד שורה ראשונה, וכשר\u0027 יוחנן הסתכל בו נדמה היה לו שרב כהנא מחייך, והיתה לו חלישות הדעת, ומת רב כהנא, ולאחר שהתברר לר\u0027 יוחנן שטעה, החיה את רב כהנא (ב\"ק קי\"ז ע\"א). שב לבבל, ולאחר פטירת רב ישב גם לפני רב יהודה (יבמות י\"ז ע\"א). לפי גיר\u0027 הרא\"ש ישב גם לפני רב הונא (חולין קי\"ג ע\"ב). בין תלמידיו היו: רבה (שם ק\"כ ע\"א) ורב יוסף (עירובין ס\"ז ע\"ב)."},{"i":2621,"n":"רב כהנא ג\u0027","l":"כ","b":"אמורא בבלי בדור הרביעי. תלמידו של רבה. חברו של רב ספרא (סנהדרין מ\"א ע\"ב). עלה לארץ ישראל, והיה תלמידו של רבי חייא בר אבא (ירו\u0027, ר\"ה פ\"ב ה\"ה), ורבי חייא בר אבא בירכו שיאריך ימים וכן היה (שם)."},{"i":2622,"n":"רב כהנא ד\u0027","l":"כ","b":"אמורא בבלי בדור החמישי. נראה, שהיה תלמידו של רבא (כתובות ס\"ג ע\"ב). מסר בשמו של רבא (ב\"ק מ\"א ע\"ב). שקיל וטרי עם רב ביבי, בנו של אביי (עירובין צ\u0027 ע\"א). היה חברו של רב פפא (גיטין פ\"ט ע\"ב). היתה לו ישיבה שכינויה \"בי רב כהנא\" (קידושין ע\"ז ע\"א). בין תלמידיו הרבים היה גם רב אשי, שהיה תלמידו המובהק (ברכות ל\"ט ע\"א), ורב אשי מזכיר פעמים רבות את רב כהנא זה (שם, סוכה מ\"ו ע\"א; חולין י\"א ע\"ב). כשחלה, שלחו את רבי יהושע בריה דרב אידו לבקרו, ומצאו מת (פסחים ג\u0027 ע\"ב)."},{"i":2623,"n":"רב כהנא ה\u0027","l":"כ","b":"אמורא בבלי בדור השביעי. תלמידו של שימי בר אשי (חולין י\"א ע\"ב; תמורה כ\"ה ע\"א). נראה, שהיה גם תלמידו של רב אשי (ברכות כ\"ד ע\"א)."},{"i":2624,"n":"רב כהנא חמוה דרב משרשיא","l":"כ","b":"אמורא בבלי בדור החמישי. תלמידו של רבא (ב\"ב צ\"ז ע\"ב)."},{"i":2625,"n":"כייליל","l":"כ","b":"מובא בבבלי (זבחים קי\"ח ע\"ב) ופירש רש\"י שם: \"נראה בעיני כי אביו של אביי כייליל שמו\", ולפי זה היה אחיו של רבה בר נחמני ושל רב חייא ורב אושעיא (לא רבי חייא ורבי אושעיא). כייליל זה מת עוד לפני שנולד אביי בנו (קידושין ל\"א ע\"ב) ואשתו (אמו של אביי) מתה בלידת אביי, וזה לשון הגמרא (שם): \"ר\u0027 יוחנן כי עברתו אמו מת אביו ילדתו - מתה אמו וכן אביי\"."},{"i":2626,"n":"רב כיני","l":"כ","b":"מובא בירושלמי (ע\"ז פ\"ג ה\"ג), והוא רב בינה כמו שנכתב בפירוש \"מראה פנים\" (ירו\u0027, ע\"ז פ\"ב ה\"ז), שדרך הירושלמי להחליף אותיות בי\"ת וכ\"ף."},{"i":2627,"n":"ר\u0027 כיריי","l":"כ","b":"מובא בירושלמי (פסחים ספ\"ב). נראה זהה לבירא."},{"i":2628,"n":"כלבא שבוע","l":"כ","b":"ע\"ע בן כלבא שבוע."},{"i":2629,"n":"רבי כרוספדאי","l":"כ","b":"תנא בדור השלישי. מובא ב\"זוהר חדש\" (רות פ\"א) שכאשר חלה, ביקרוהו רב יוסי בן קסמא ורבנן, וביום השבת חשבו שנפטר, ואח\"כ במוצ\"ש ראוהו חי. וכתב ה\"יוחסין\": \"ובזהר אמר שהם שנים\" (ר\u0027 כרוספדאי ור\u0027 כרוספדאי בריה דר\u0027 שבתי)."},{"i":2630,"n":"ר\u0027 כרוספדאי בריה דר\u0027 שבתי","l":"כ","b":"ע\"ע רבי כרוספדאי."},{"i":2631,"n":"רבי לא","l":"ל","b":"מובא בירושלמי (עירובין פ\"ו ה\"ט), והוא רבי אלעאי."},{"i":2632,"n":"ר\u0027 לא דכפרא","l":"ל","b":"מובא בירושלמי (סנהדרין פ\"ו ה\"ט), ואולי הוא ר\u0027 הלל דכיפרא."},{"i":2633,"n":"לודא","l":"ל","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (שבת צ\"ו ע\"ב; שם קל\"ז ע\"א; יבמות ע\"א ע\"ב). ה\"יוחסין\" ו\"סה\"ד\" כתבו שהיה בזמן שמואל ולעניות דעתי אין כל ראיה מהמקורות הנ\"ל שהיה בזמן שמואל. ובירושלמי (תענית פ\"ג ה\"י): ר\u0027 לודה."},{"i":2634,"n":"ר\u0027 לודה","l":"ל","b":"מובא בירושלמי (תענית פ\"ג ה\"י), ואולי הוא האמורא לודא."},{"i":2635,"n":"רבי לוונטי","l":"ל","b":"מובא בירושלמי (שבת פ\"ג ה\"ג), והוא רבי לונטי."},{"i":2636,"n":"לוטינוס דרומיה","l":"ל","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. מסר בשם ר\u0027 יודה (יהודה) בר סימון (פדר\"כ ק\u0027)."},{"i":2637,"n":"לוי","l":"ל","b":"מראשוני אמוראי ארץ ישראל. הוא לוי בר סיסי. וההוכחה, שבבבלי מובא (סוכה נ\"ג ע\"א): לוי, ואותו ענין בירושלמי (ברכות פ\"א ה\"ה): לוי בר סיסי. מבני פמלייתו של רבי ולמד לפניו (זבחים ל\u0027 ע\"ב), והיה חביב עליו עד שאמר עליו לבני העיר סימונייא: \"בר נש דכוותי יהבית לכון\" (ירו\u0027, יבמות פי\"ב ה\"ו), ופירש \"קרבן העדה\": \"אדם שכמותי גדול בתורה נתתי לכם\". לוי קרא לרבי: \"רבינו הקדוש\" (שבת קנ\"ו ע\"א), ועליו אמרו: \"כל היכא דאיתמר: \u0027למדין לפני חכמים\u0027 היינו לוי, שהיה לומד לפני רבי\" (סנהדרין י\"ז ע\"ב רש\"י). רבי חנינא היה חברו הגדול (כתובות ק\"ג ע\"ב). כן למד יחד עם רב לפני רבי (ביצה כ\"ד ע\"ב). אחרי שר\u0027 אפס מת ור\u0027 חנינא ישב בראש הישיבה בא\"י, ירד לוי לבבל (שבת נ\"ט ע\"ב), ושם היה לחברו של אבא בר אבא (אבוה דשמואל) ולמדו יחד (מגילה כ\"ט ע\"א). אבוה דשמואל חי אחריו והספידו כשנפטר (ירו\u0027, ברכות פ\"ב ה\"ח). ובין תלמידיו היה שמואל (מנחות ל\"ח ע\"ב). מסופר (תענית כ\"ה ע\"א) שפעם אחת גזר תענית שירדו גשמים ולא ירדו, \"אמר לפניו רבש\"ע: עלית וישבת במרום ואין אתה מרחם על בניך?\" ואמנם ירדו גשמים, אבל על שהטיח דברים כלפי מעלה לקה בצליעה, ומצינו שעוד היה צולע אחר פטירת רבי (כתובות ק\"ג ע\"ב). וכן מסופר, שפעם כשבאו גייסות לעירו, נטל ספר תורה ועלה לראש הגג ואמר: \"רבונו של עולם אם ביטלתי דבר אחד מספר תורה זה, יכנסו להם, ואם לאו, ילכו להם\" (ירו\u0027, תענית פ\"ג ה\"ח), ומיד הלכו כל הגיסות."},{"i":2638,"n":"ר\u0027 לוי","l":"ל","b":"אמורא ארץ ישראלי בדור השלישי. מבעלי האגדה. במשך עשרים ושתים שנה דרש בבית המדרש, קודם שבא רבי יוחנן לשם (ירו\u0027, סוכה פ\"ה ה\"א). רבי זירא, אף שהיה מתנגד מובהק לבעלי האגדה, ציוה לתלמידיו ללכת לשמוע דרשותיו של ר\u0027 לוי, משום שאי אפשר שלא יהא בהן דבר חידוש (ירו\u0027, ר\"ה פ\"ד ה\"א). ר\u0027 אבא בר כהנא נשקו על ראשו כששמעו דורש (ירו\u0027, סוף הוריות). מסר דרשות בשם התנאים: רבי יוסי בר תחליפא (ב\"ר פנ\"ז - ד\u0027) ורבי מאיר (סוכה ח\u0027 ע\"ב). כן קיבל מרבי שמעון בן לקיש (מד\u0027 שמואל רפ\"ט). מסרו בשמו: ר\u0027 יונה (ירו\u0027, חגיגה פ\"ב) ור\u0027 יוסי (ב\"ר פז\"ח - ה\u0027). ר\u0027 יהושע דסכנין מסר ממנו יותר ממאה דרשות."},{"i":2639,"n":"לוי בר בוטי","l":"ל","b":"אמורא בבלי בדור השלישי. תלמידו של רב הונא (מגילה ל\"א ע\"ב). נראה, שהשם שובש בכמה אופנים (ירו\u0027, מגילה פ\"ג ה\"ז): לוי בר פסטי, וכן מצינו (מסכת סופרים פי\"ב): בר פאטי, וכן (קה\"ר פ\"ח - ג\u0027): ר\u0027 לוי בר פנטי. ונראה שאולי כולם אחד. \"סה\"ד\" קבע, שלוי בר בוטא ולוי בר פנטי שניים."},{"i":2640,"n":"לוי בר ביריי","l":"ל","b":"אמורא ארץ ישראלי בדור השני. מסר בשם רבי יהושע בן לוי (ירו\u0027, ב\"ב רפ\"ה)."},{"i":2641,"n":"ר\u0027 לוי בר ברכיה","l":"ל","b":"מובא בתנחומא (בחוקותי - ז\u0027)."},{"i":2642,"n":"לוי בר היני","l":"ל","b":"מובא בירושלמי (תרומות פ\"ד ה\"ב)."},{"i":2643,"n":"ר\u0027 לוי בר זבדא","l":"ל","b":"מובא בתנחומא (דפוס וניציא, בחוקותי)."},{"i":2644,"n":"ר\u0027 לוי בר זכריה","l":"ל","b":"אמורא ארץ ישראלי בדור החמישי. מסר בשם רבי ברכיה (פסיקתא דר\"כ ס\"ו ב\u0027)."},{"i":2645,"n":"רבי לוי בר חויית","l":"ל","b":"מובא בב\"ר (פל\"ט - י\"א). ע\"ע רבי לוי בר חיותא."},{"i":2646,"n":"רבי לוי בר חזותא","l":"ל","b":"כך מובא ב\"ערוך\" ערך אלנסתין. ע\"ע רבי לוי בר חיותא."},{"i":2647,"n":"רבי לוי בר חיותא","l":"ל","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי (ירו\u0027, שבת ספ\"ו). יתכן ששמו שובש בכמה אופנים לרבי לוי בר חיתא (מו\"ק כ\"ט ע\"א) ולרבי לוי בר חיתה (ירו\u0027, סוטה פ\"ז ה\"א). ענין זה מובא ב\"ערוך\" ערך אלנסתין, ושם: רבי לוי בר חזותא, ומצינו: \"אמר רבי לוי בר חייתא\" (ב\"ר פנ\"ה - ז\u0027) ו\"רבי לוי בר חויית\" (ב\"ר פל\"ט - י\"א), ואולי כל השמות הללו או חלקם אחד הם."},{"i":2648,"n":"ר\u0027 לוי בר חייא","l":"ל","b":"מובא בבבלי, שאמר: \"היוצא מבית הכנסת ונכנס לבית המדרש ועוסק בתורה, זוכה ומקבל פני השכינה\" (ברכות ס\"ד ע\"א)."},{"i":2649,"n":"רבי לוי בר חייתא","l":"ל","b":"מובא בב\"ר (פנ\"ה - ז\u0027). ע\"ע רבי לוי בר חיותא."},{"i":2650,"n":"לוי בר חינא","l":"ל","b":"מובא (ירו\u0027, תרומות פ\"ד ה\"ג), והוא לוי בר היני."},{"i":2651,"n":"רבי לוי בר חיתא","l":"ל","b":"מובא בבבלי (מו\"ק כ\"ט ע\"א). ע\"ע רבי לוי בר חיותא."},{"i":2652,"n":"רבי לוי בר חיתה","l":"ל","b":"מובא בירושלמי (סוטה פ\"ז ה\"א). ע\"ע רבי לוי בר חיותא."},{"i":2653,"n":"רבי לוי בר חמא","l":"ל","b":"מובא בבבלי (ברכות ה\u0027 ע\"א). \"סה\"ד\" כתב: \"אולי אחד הוא עם רבי לוי בר לחמא\"."},{"i":2654,"n":"ר\u0027 לוי בר טרפון","l":"ל","b":"אמורא ארץ ישראלי בדור השני. מובא באיכ\"ר (פ\"א - ל\"ג), שר\u0027 יהודה בר סימון מסר משמו. יתכן שצריך לגרוס: בר פרטא, כמו בויק\"ר (פכ\"ג - י\"ב)."},{"i":2655,"n":"רבי לוי בר לחמא","l":"ל","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם רבי חמא בר חנינא (ר\"ה כ\"ט ע\"ב). וכתב \"סה\"ד\": אולי אחד הוא עם רבי לוי בר חמא (ברכות ה\u0027 ע\"א)."},{"i":2656,"n":"ר\u0027 לוי בר נזירא","l":"ל","b":"מובא בירושלמי (ברכות פ\"ב ה\"א). \"סה\"ד\" כתב שט\"ס בשם, וצ\"ל: שמעון נזירא."},{"i":2657,"n":"לוי בר סוסיי","l":"ל","b":"מובא בירושלמי (יבמות פ\"א ה\"א), והוא לוי תלמידו של רבי."},{"i":2658,"n":"לוי בר סימון","l":"ל","b":"מובא בבבלי (חולין קמ\"א ע\"ב), ש\"אקני פירות שובכו לרב יהודה וכו\u0027\". ואין להכריע אם היה חכם או לא שכן מובא רק פעם אחת בש\"ס. ה\"יוחסין\" ו\"סה\"ד\" מנו אותו בין החכמים."},{"i":2659,"n":"לוי בר סיסי","l":"ל","b":"הוא לוי בר סוסיי."},{"i":2660,"n":"לוי בר פייטם","l":"ל","b":"מובא בתנחומא (פקודי ז\u0027), ויתכן שט\"ס הוא וצ\"ל: ר\u0027 יוסי בר פוטרס, כמו בירושלמי (ע\"ז פ\"ג ה\"א)."},{"i":2661,"n":"ר\u0027 לוי בר פלטא","l":"ל","b":"אמורא ארץ ישראלי. מובא בירושלמי (תרומות פ\"י ה\"ו). נראה זהה ללוי בר פרטא (חולין צ\"ח ע\"א)."},{"i":2662,"n":"ר\u0027 לוי בר פנטי","l":"ל","b":"מובא בקה\"ר (פ\"ח - ג\u0027). ע\"ע לוי בר בוטי."},{"i":2663,"n":"ר\u0027 לוי בר פסטי","l":"ל","b":"מובא בירושלמי (מגילה פ\"ג ה\"ז). ע\"ע לוי בר בוטי."},{"i":2664,"n":"לוי בר פרטא","l":"ל","b":"אמרוא ארץ ישראלי. מובא בבבלי (חולין צ\"ח ע\"א). נראה זהה לר\u0027 לוי בר פלטא (ירו\u0027, תרומות פ\"י ה\"ו). ר\u0027 יהודה בר סימון, מאמוראי א\"י בדור השלישי - הרביעי מסר משמו (ב\"ר רפ\"נ)."},{"i":2665,"n":"ר\u0027 לוי בר רבי","l":"ל","b":"מובא בתנחומא (בהעלותך - ו\u0027), ונראה שט\"ס הוא, שכן שמו לא נודע לנו."},{"i":2666,"n":"ר\u0027 לוי בר שלום","l":"ל","b":"מובא בתנחומא (חיי שרה - ז\u0027)."},{"i":2667,"n":"לוי בר שמואל","l":"ל","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב יהודה (מגילה י\"ט ע\"א). למד יחד עם חברו רב הונא בר חייא בישיבת רב יהודה (סנהדרין ק\u0027 ע\"א)."},{"i":2668,"n":"לוי בריה דרב הונא בר חייא","l":"ל","b":"אמורא בבלי בדור השלישי - הרביעי. היה בן בתו של רבי ירמיה בר אבא (שהיה תלמיד חבר לרב), ובנו של רב הונא בר חייא. ור\"ה בר חייא אביו מסר לו מדברי סבו ר\u0027 ירמיה בר אבא (שבת קנ\"ו ע\"א). פעם הלך בדרך עם רבה בר רב הונא (שבת נ\"א ע\"ב), ומשם נראה, שרבה בר רב הונא היה גדול ממנו."},{"i":2669,"n":"ר\u0027 לוי בריה דרבי שמואל בר נחמיה","l":"ל","b":"מובא בגמרות ישנות ובש\"ס יונתן (ברכות כ\"ח ע\"ב). ה\"יוחסין\" ו\"סה\"ד\" כתבו, שלר\u0027 שמואל נחמני היו שלושה בנים: הלל, לוי, ור\"נ, ובאמת ט\"ס היא וצ\"ל: א\"ר לוי לרבי הלל בריה דרבי שמואל בר נחמני, וכן הוא בש\"ס וילנא שלפנינו, וכן הגיה \"דק\"ס\", וכ\"ה בכ\"י, וב\"ילקוט\" שם (\"דק\"ס\" מסביר כיצד נפלה הטעות). לפי זה לא היה כלל אמורא ושמו לוי בריה דרבי שמואל בר נחמני, שכן לרבי שמואל בר נחמני לא היה בן שנשא שם זה."},{"i":2670,"n":"ר\u0027 לוי בריה דר\u0027 זעירא","l":"ל","b":"מובא בקה\"ר (פ\"ז - ו\u0027)."},{"i":2671,"n":"ר\u0027 לוי הכהן בר חלפתא","l":"ל","b":"מובא בתנחומא (וירא - כ\"ה)."},{"i":2672,"n":"לוי הסדר","l":"ל","b":"תנא בדור הרביעי. תלמידם של רבי עקיבא ורבי ישמעאל. חברו של רבי ישמעאל בנו של רבי אלעזר בן עזריה (יומא פ\"ה ע\"א), שם מסופר, שהלך עם חברו אחרי רבותיו."},{"i":2673,"n":"לוי הסרד","l":"ל","b":"כך גירסת \"הערוך\". ולפנינו: לוי הסדר (ברכות ס\"ה ע\"א), וכן גרס רש\"י: הסדר."},{"i":2674,"n":"ר\u0027 לוי חתניה דר\u0027 זכריה","l":"ל","b":"מובא בשאלתות (פ\u0027 צ\"ו). ו\"סה\"ד\" מפקפק אם ט\"ס היא."},{"i":2675,"n":"לוי סבא","l":"ל","b":"אמורא ארץ ישראלי בדור הראשון. רבי שמעון בן לקיש מסר משמו (חולין כ\"ט ע\"ב). ונראה ששמו שובש בכמה אופנים: ר\"ש בן לקיש בשם ר\u0027 סובייה (ירו\u0027, פסחים פ\"ו ה\"א), ריש לקיש בשם לוי סוכיא (ירו\u0027, עירובין פ\"י ה\"ב), רבי שמעון בן לקיש בשם לוי סיכייה (שם, הי\"ב), ר\"ש (בן לקיש) בשם לוי סוכייה (ירו\u0027, יומא פ\"ח ה\"ו). וכן רבי שמעון בשם לוי שובדא (ירו\u0027, שבועות פ\"א ה\"ו)."},{"i":2676,"n":"לוי סוכיא","l":"ל","b":"מובא בירושלמי (עירובין פ\"י ה\"ב). ע\"ע לוי סבא."},{"i":2677,"n":"לוי סוכייה","l":"ל","b":"מובא בירושלמי (יומא פ\"ח ה\"ו). ע\"ע לוי סבא."},{"i":2678,"n":"לוי סיכייה","l":"ל","b":"מובא בירושלמי (עירובין פ\"י הי\"ב). ע\"ע לוי סבא."},{"i":2679,"n":"לוי סריסא","l":"ל","b":"מובא בירושלמי (שבת פ\"ג ה\"ג) אלבט (פילוסוף נכרי חברו של שמואל) שאל ללוי סריסא. ואולי צ\"ל: לוי בן סיסא (\"סה\"ד\" לא הביאו)."},{"i":2680,"n":"לוי פריסה","l":"ל","b":"מובא בירושלמי: \"ר\u0027 חנינא הוה מישתעי אהן עובדא לוי פריסה וכו\u0027\" (גיטין פ\"ו ה\"ה). אין לדעת איזה ר\u0027 חנינא דיבר עם לוי פריסה, רבי חנינא, או רב חנינא. ואולי ט\"ס היא וצ\"ל: לוי בן סיסי (והוא לוי תלמידו דרבי)."},{"i":2681,"n":"רבי לוי צנבריא","l":"ל","b":"אמורא ארץ ישראלי בדור הרביעי. שאל לרבי יצחק ולרבי אמי (ירו\u0027, שביעית פ\"ו ה\"ב)."},{"i":2682,"n":"לוי שובדא","l":"ל","b":"מובא בירושלמי (שבועות פ\"א ה\"ו). והוא לוי סבא."},{"i":2683,"n":"רבי לויטס איש יבנה","l":"ל","b":"תנא שאין לקבוע זמנו המדוייק. מובא ממנו מאמר אחד במשנה (אבות פ\"ד מ\"ד). וכן באבות דר\u0027 נתן (פכ\"ג)."},{"i":2684,"n":"ר\u0027 לויטס איש כפר אוני","l":"ל","b":"מובא ב\"זוהר\" (משפטים ק\"ג ע\"ב)."},{"i":2685,"n":"ר\u0027 לויטס חוזאה","l":"ל","b":"מובא ב\"זוהר חדש\" (ריש איכא)."},{"i":2686,"n":"ר\u0027 לולאני בר שווריה","l":"ל","b":"מובא בפדר\"כ (ל\"ט). ע\"ע ר\u0027 לוליאני בר טבריני."},{"i":2687,"n":"ר\u0027 לוליאני","l":"ל","b":"מובא במדרש תהלים (פי\"ח - כ\"ט). ע\"ע ר\u0027 לוליאני בר טבריני."},{"i":2688,"n":"ר\u0027 לוליאני בר טבריני","l":"ל","b":"אמורא ארץ ישראלי בדור הרביעי. שמו נשתבש כנראה בכמה אופנים: ר\u0027 לולייני בר טבריני (תנחומא בראשית - ד\u0027); ר\u0027 לולייאני בר טבראי (ב\"ר פ\"ג - ח); ר\u0027 לולאני בר שווריה (פדר\"כ ל\"ט); ר\u0027 לוליני בר כובריא (פס\u0027 רבתי פ\u0027 פרה); ר\u0027 לולינא בר טברין (ב\"ר פ\"א - ג\u0027); ר\u0027 לולינא בר טורין (שם פצ\"ח - כ\u0027) - ואולי כולם אחד. מובא גם ר\u0027 לוליאני (מדרש תהלים פי\"ח - כ\"ט)."},{"i":2689,"n":"ר\u0027 לולייאני בר טבראי","l":"ל","b":"מובא בב\"ר (פ\"ג - ח\u0027). ע\"ע ר\u0027 לוליאני בר טבריני."},{"i":2690,"n":"ר\u0027 לולינא בר טברין","l":"ל","b":"מובא בב\"ר (פ\"א - ג\u0027). ע\"ע ר\u0027 לוליאני בר טבריני."},{"i":2691,"n":"ר\u0027 לולינא בר טורין","l":"ל","b":"מובא בב\"ר (פצ\"ח - כ\u0027). ע\"ע ר\u0027 לוליאני בר טבריני."},{"i":2692,"n":"ר\u0027 לוליני בר כוריא","l":"ל","b":"מובא בפס\u0027 רבתי (פ\u0027 פרה). ע\"ע ר\u0027 לוליאני בר טבריני."},{"i":2693,"n":"לחמא בר לואי","l":"ל","b":"מובא ב\"זוהר\" (שמות ט\"ז ע\"ב)."},{"i":2694,"n":"רבי ליא","l":"ל","b":"מובא בירושלמי (ברכות פ\"ב ה\"ח), והוא רבי אלעאי."},{"i":2695,"n":"רבי ליונטי","l":"ל","b":"אמורא ארץ ישראלי בדור הששי. תלמידו של רבי יונה (ירו\u0027, יבמות פ\"ט ה\"ח), היה כנראה תלמידו המובהק (ירו\u0027, שבת פ\"ג ה\"ג)."},{"i":2696,"n":"ר\u0027 ליל בי ר\u0027 אלם","l":"ל","b":"מובא בירושלמי (ביצה פ\"ה ה\"ב). גיר\u0027 \"סה\"ד\": רבי הלל בריה דר\u0027 וולס. יש גורסים שהוא ר\u0027 ליל בר אלס."},{"i":2697,"n":"ר\u0027 ליל בר אלם","l":"ל","b":"מובא בירושלמי (ביצה פ\"ה ה\"ג), והוא רבי הלל בריה דר\u0027 וולס."},{"i":2698,"n":"רב לילי בר ממל","l":"ל","b":"אמורא בבלי בדור השני - השלישי. תלמידו של מר עוקבא (יבמות י\"ב ע\"א)."},{"i":2699,"n":"לילי בר מני","l":"ל","b":"כן גיר\u0027 \"יוחסין\". לפנינו: לילי בר ממל (יבמות י\"ב ע\"א)."},{"i":2700,"n":"ליליינוס ופפוס","l":"ל","b":"רש\"י כתב: \"צדיקים היו\" (תענית י\"ח ע\"ב), ושם מסופר שנהרגו ע\"י טוריינוס, אך במגילת תענית (רפי\"ב) לא כתוב שנהרגו, ואמנם היו בחיים בימי אדריינוס ורש\"י פירש: \"יש אומרין שנהרגו על בתו של מלך שנמצאה הרוגה ואמרו היהודים הרגוה וגזרו גזירה וכו\u0027 ואמרו אנו הרגנוה והרג המלך לאלו בלבד\" (תענית י\"ח ע\"ב) ותוספות מביא (שבת ע\"ב ע\"ב; סנהדרין ס\"א ע\"ב ד\"ה: רבא) ממה שמסופר (בירו\u0027, שביעית רפ\"ד): האחים לוליינוס ופפוס שנתנו להם מים בכלי זכוכית צבוע ולא רצו ונהרגו על קידוש ה\u0027. רש\"י כתב: \"אין כל בריה יכולה לעמוד במחיצתן בגן עדן\" (תענית, שם)."},{"i":2701,"n":"רבי לעיי","l":"ל","b":"מובא בירושלמי (דמאי פ\"א ה\"א), והוא רבי אלעאי."},{"i":2702,"n":"רבי מאיר","l":"מ","b":"גדול התנאים בדור הרביעי, כפי שאמרו: \"גלוי וידוע לפני מי שאמר והיה העולם, שאין בדורו של רבי מאיר כמותו\" (עירובין י\"ג ע\"ב), ועוד אמרו: \"כל הרואה רבי מאיר בבית המדרש, כאילו עוקר הרי הרים וטוחנן זה בזה\" (סנהדרין כ\"ד ע\"א), והוא היה כה חריף עד שאמרו: \"שלא יכלו חבריו לעמוד על סוף דעתו\" (עירובין שם). חברו רבי יוסי בן חלפתא היה משבח אותו ואומר: \"אדם גדול, אדם קדוש, אדם צנוע\" (ירו\u0027, מו\"ק פ\"ג ה\"ה). ריש לקיש אמר עליו \"פה קדוש\" (סנהדרין כ\"ג ע\"א). אביו של רבי מאיר היה שר צבא רומי, גוי ושמו נירון, וסמוך לפני חורבן הבית השני התגייר, ורבי מאיר היה בנו (גיטין נ\"ו ע\"א). רבי מאיר היה תלמידו המובהק של רבי עקיבא (עירובין י\"ג ע\"א). ואמרו: \"סתם משנה רבי מאיר, ואליבא דר\"ע\" (סנהדרין פ\"ו ע\"א). למד גם מרבי ישמעאל (עירובין שם). רבי עקיבא סמכו שעדיין היה בחור (סנהדרין י\"ד ע\"א רש\"י ד\"ה: ולא) ואח\"כ נסמך על ידי רבי יהודה בן בבא (שם). בין רבותיו היה גם אלישע בן אבויה (חגיגה ט\"ו ע\"ב). חבריו הגדולים היו: רבי יהודה (בר אלעאי), רבי שמעון (בר יוחי), רבי יוסי (בן חלפתא), ורבי אלעזר (בן שמוע). כשהעולם היה שמם מתורה, אמרו על רבי מאיר וחבריו: \"הם הם העמידו תורה אותה שעה\" (יבמות ס\"ב ע\"ב), והם מכונים \"רבותינו שבדרום\" (שם). בנוסף לחריפותו היה גם גדול באגדה ובדרוש (סנהדרין ל\"ח ע\"ב) ואמר רבי יוחנן: \"שלש מאות משלות היו לו לרבי מאיר\" (שם), וכן אמרו: \"משמת רבי מאיר בטלו מושלי משלים\" (סוף סוטה). בין תלמידיו המובהקים היו: סומכוס (עירובין י\"ג ע\"ב) ורבי שמעון בן אלעזר (חולין ו\u0027 ע\"א). וכן למד אצלו רבי (עירובין י\"ג ע\"ב). כשרבן שמעון בן גמליאל אבי רבי שימש כנשיא, היה רבי מאיר ה\"חכם\", ופעם פגע רשב\"ג בכבוד ר\"מ, והוא ניסה להוריד את רשב\"ג מנשיאותו, ועל כן קבעו שמו כ\"אחרים אומרים\" (עיין סוטה י\"ב ע\"א תד\"ה: אחרים). היה עניו ורודף שלום, עד שהרשה לאשה לירוק בעיניו למען השכנת שלום בינה לבין בעלה (ירו\u0027, סוטה פ\"א ה\"ד). התפרנס מהיותו לבלר (עירובין י\"ג ע\"א). ידע על פה כל המקראות בדקדוק חסירות ויתרות, ופעם כשהלך לעבר שנה בעסיא, ולא היתה שם מגילה, כתבה בעל פה (מגילה י\"ח ע\"ב). אשתו היתה ברוריה, בתו של רבי חנינא בן תרדיון (ע\"ז י\"ח ע\"א). היו לו ממנה שני בנים שמתו על פניו ביום שבת (מדרש משלי פל\"א - י\u0027). היתה לו עוד אשה ששם אביה זרוז (חולין ו\u0027 ע\"ב). נפטר באסיה וציווה שיעבירוהו לארץ ישראל (ירו\u0027, כלאים פ\"ט ה\"ד). נפטר לפני חבריו רבי יהודה ורבי יוסי (קידושין נ\"ב ע\"ב)."},{"i":2703,"n":"מבוג","l":"מ","b":"אמורא בבלי בדור הראשון, מראשוני האמוראים. רב אמר משמו (זבחים ט\u0027 ע\"ב)."},{"i":2704,"n":"מגבילה","l":"מ","b":"מגבילה אחוי דר\u0027 אבא בר כהן. אמורא ארץ ישראלי בדור החמישי. \"אמר קומי ר\u0027 יוסי בשם ר\u0027 אחא\" (ירו\u0027, ברכות פ\"ג ה\"א)."},{"i":2705,"n":"רבי מונא","l":"מ","b":"תנא בדור החמישי. נראה, שהיה תלמידו של רבי יהודה ומסר כמה פעמים משמו (מגילה י\"ח ע\"ב)."},{"i":2706,"n":"מונבז","l":"מ","b":"תנא בדור הרביעי. מתלמידי רבי עקיבא. דן לפני ר\"ע רבו (שבת ס\"ח ע\"ב)."},{"i":2707,"n":"ר\u0027 מוסיא","l":"מ","b":"מובא בבבלי: \"אמר ר\u0027 מוסיא בר בריה דר\u0027 מסיא משמיה דר\u0027 מוסיא רבה\" (יומא ד\u0027 ע\"ב)."},{"i":2708,"n":"ר\u0027 מחסיא בר אידי","l":"מ","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (יומא ב\u0027 ע\"א)."},{"i":2709,"n":"מיאשא","l":"מ","b":"מחכמי ארץ ישראל הקדומים לפני תקופת התנאים. מובא במשנה: \"מעשה שזרע ר\u0027 שמעון [נראה ט\"ס וצ\"ל שמעון בלי ר\u0027] איש המצפה, [ובא] לפני ר\"ג [הזקן] ועלו ללשכת הגזית ושאלו, אמר נחום הלבלר: מקובל אני מר\u0027 מיאשא שקיבל מן הזוגות שקבלו מן הנביאים וכו\u0027\" (פאה פ\"ב מ\"ו)."},{"i":2710,"n":"רבי מיאשא","l":"מ","b":"אמורא ארץ ישראלי בדור השני. בר בריה דרבי יהושע בן לוי. מסר משם סבו ריב\"ל (כתובות ע\"ה ע\"ב). נראה שעמו נהג ריב\"ל ללמוד את פרשת השבוע (ירו\u0027, שבת פ\"א ה\"ב). כן נראה, שעמו היה המעשה המסופר, שפעם עמד בן בנו של ריב\"ל להחנק, ובא אחד ולחש שם טומאה שיתרפא, ואמר ריב\"ל מוטב היה שימות ולא יתרפא משם טומאה, ואכן כך היה ומת בחיי ריב\"ל (שם פי\"ד ה\"ד), ואמנם מצינו שנפטר עוד בחיי רבי אמי (כתובות פ\"ה ע\"ב)."},{"i":2711,"n":"ר\u0027 מיאשא א\u0027","l":"מ","b":"תנא בדור השלישי. בר פלוגתיה דר\u0027 ישמעאל (פדר\"א פכ\"א)."},{"i":2712,"n":"ר\u0027 מיאשא ב\u0027","l":"מ","b":"מן האמוראים הארץ ישראלים הראשונים בתחילת הדור הראשון. רבי חנינא היה תלמידו (נדרים ח\u0027 ע\"ב)."},{"i":2713,"n":"מיישא","l":"מ","b":"הוא מיאשה."},{"i":2714,"n":"ר\u0027 מיישא בר ירמיה","l":"מ","b":"אמורא ארץ ישראלי המובא פעם אחת בירושלמי, שאמר משמו של רבי יוסי (נזיר פ\"ט ה\"ג). אם נניח שזה רבי יוסי, חברו של רבי יונה, א\"כ היה בדור החמישי לאמוראי ארץ ישראל, ואם נניח שזה רבי אסי (ולא רבי יוסי, כפי שיש פעמים רבות שיבוש מעין זה בירושלמי), הרי שהיה אמורא ארץ ישראלי בדור הרביעי (ואני סיווגתיו לרבי יוסי)."},{"i":2715,"n":"מיניימון","l":"מ","b":"תנא שאין לקבוע זמנו המדוייק. אפשר לומר, שאולי היה בדור הרביעי - החמישי, וזה לפי סדר החכמים המובא בירושלמי: \"כמה היא העראה וכו\u0027, ר\"א אומר וכו\u0027, מיניימון אומר וכו\u0027, בן עזאי אומר וכו\u0027, ר\"ע אומר וכו\u0027, ר\u0027 יהודה בן בתירא אומר וכו\u0027, ר\"א בן פנחס אומר וכו\u0027, מייניימון אומר וכו\u0027\" (סוטה פ\"א ה\"ב), על אף שעל פי סדר הבאת השמות אין לקבוע את סדר חשיבותם בחכמה, כמו שכתבו התוספות (סוטה ד\u0027 ע\"א ד\"ה: בן)."},{"i":2716,"n":"מישא","l":"מ","b":"ע\"ע מיישא."},{"i":2717,"n":"ר\u0027 מישא","l":"מ","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מסר משם רבי יוחנן (ירו\u0027, שבת פ\"א ה\"א). תלמידו של ר\u0027 שמואל בר יצחק (שם ה\"ב) ורבי אבהו (מד\u0027 שמואל פ\"ה - ג\u0027). בין האומרים בשמו היה רבי אחא (ירו\u0027, כלאים פ\"ב ה\"ג); בין תלמידיו היה רבי יונה (ירו\u0027, ביכורים פ\"ב ה\"ג)."},{"i":2718,"n":"רבי מלאי","l":"מ","b":"אמורא ארץ ישראלי בדור השני. מובא בבבלי: \"א\"ר מלאי משום רבי אלעזר בר\u0027 שמעון\" (שבת קל\"ט ע\"א). \"סה\"ד\" סובר, שר\"א בן מלאי המובא (שם) הוא בנו."},{"i":2719,"n":"ר\u0027 מלוך","l":"מ","b":"אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של רבי יהושע בן לוי (חולין מ\"ט ע\"א). מושבו היה בערביים ועל כן מכונה: ר\u0027 מלוך ערבאה (שם ברש\"י)."},{"i":2720,"n":"רב מלכיא","l":"מ","b":"ע\"ע רב מלכיו."},{"i":2721,"n":"רב מלכיו","l":"מ","b":"מובא בבבלי: \"אמר רבא: מאן חכים כרב מלכיו דגברא רבה הוא קסבר וכו\u0027\" (יבמות קי\"ג ע\"א). ועל מה שכתב \"שארית יוסף\", שהוא תלמיד רב (רב חי בדור הראשון) כתב \"סה\"ד\" שטעה, כי נראה שהיה בזמן רבא (רבא חי בדור הרביעי). ומצינו: \"רב מלכיא [א\u0027 בסוף ולא ו\u0027] איקלע לבי ר\u0027 שמלאי\" (שבת מ\"ו ע\"א). ור\u0027 שמלאי חי בדור השני לאמוראים. ואכן, \"סה\"ד\" מפרידם לשני חכמים: רב מלכיא ורב מלכיו. ומצינו \"רב אדא בר אהבה אמר רב מלכיו\" (ביצה כ\"ח ע\"ב), ואולי ט\"ס היא וצ\"ל להיפך, שכן מצינו מספר פעמים: \"אמר רב מלכיו אמר רב אדא בר אהבה\" (כתובות ס\"א ע\"ב, ועוד)."},{"i":2722,"n":"רבי מנא א\u0027","l":"מ","b":"אמורא ארץ ישראלי בדור השני. תלמידו של רבי ינאי (נדה ס\"א ע\"ב). שאל מרבי יוחנן (מנחות כ\"א ע\"א). חלק עם ריש לקיש (חולין כ\"א ע\"א). תלמיד רבי יוחנן. רב אסי קיבל ממנו (שם). משמו מסרו רבי אלעזר (ירו\u0027, מע\"ש פ\"א ה\"א) ורבי אבהו (ירו\u0027, סוטה פ\"ה ה\"ב)."},{"i":2723,"n":"רבי מנא בר תנחום","l":"מ","b":"אמורא ארץ ישראלי בדור השני - השלישי. היה כנראה מראשי העיר צור, בזמנו של רבי יוחנן (ירו\u0027, ע\"ז פ\"ב ה\"ח). רבי חייא בר אבא, שהיה אצלו, סיפר לר\u0027 יוחנן שיודע למתק את הים הגדול (שם). מסר בשם רבי חנינא (ירו\u0027, תרומות פ\"ח ה\"ג). משמו מסר רבי אסי (שם פ\"ה ה\"ב)."},{"i":2724,"n":"רבי מנא ב\u0027","l":"מ","b":"מגדולי ואחרוני האמוראים הארץ ישראלים בדור החמישי. בנו ותלמידו של רבי יונה (ירו\u0027, דמאי רפ\"ז). היה גם תלמידו של רבי יוסי (חברו של אביו), כמובא בירושלמי (ברכות פ\"א ה\"ב), והיה בפטירת רבי יוסי רבו (שם פ\"ג ה\"א). חברו הגדול רבי חנינא דציפורין היה תלמיד חבר שלו (ירו\u0027, פסחים פ\"ו ה\"א): \"ג\u0027 הניחו כתרן בעולם הזה וירשו חיי העולם הבא, ואלו הן: יונתן בן שאול ואליעזר בן עזריה וזקני בתירא וכו\u0027, אף רבי חנינא דציפורין לרבי מנא וכו\u0027\", (פירש \"קרבן העדה\", שנתן שררותיה לרבי מנא שהיה גדול ממנו). הלכות רבות משל ר\u0027 מנא מובאות בכל הש\"ס הירושלמי. העמיד תלמידים הרבה. נראה שהיה זמן מה בבבל (ירו\u0027, ב\"ב פ\"ב ה\"ח) ושם נפגש עם אביי (חברו של רבא), והיה לו דין ודברים עם בית הנשיא, ונרדף על ידם ונעשה לו נס וקיבלו עליהם אנשי בית הנשיא שלא יצערוהו עוד (תענית כ\"ג ע\"ב). בתקופת פטירתו של רבי מנא, גברו הגזרות בארץ ישראל ורבים מן האמוראים ירדו לבבל, ובתקופה ההיא נסתיימה תקופת האמוראים בארץ ישראל."},{"i":2725,"n":"ר\u0027 מנא דציפורין","l":"מ","b":"מובא בירושלמי (גיטין פ\"א ה\"ב), ונראה שהוא ר\u0027 מנא ב\u0027."},{"i":2726,"n":"רבי מנא דשאב","l":"מ","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. חברו של ר\u0027 יהושע דסכנין, ושניהם מסרו משמו של רבי לוי (תנחומא אחרי ז\u0027)."},{"i":2727,"n":"מנחם","l":"מ","b":"מחכמי ישראל הקדומים בדור האחרון ל\"זוגות\" לפני התחלת תקופת התנאים. חי בדורם של הלל ושמאי, כמאה שנה לפני החורבן. בבלי (חגיגה ט\"ז ע\"ב) יש מחלוקת אמוראים לגביו: לדעת אביי יצא מנחם לתרבות רעה, וזה משמעות המשנה (שם, ט\"ז ע\"א): \"יצא מנחם נכנס שמאי\". ולדעת רבא: \"יצא לעבודת המלך, ויצאו עמו שמונים זוגות תלמידים\". על כל פנים, מנחם יצא ושמאי נכנס תחתיו ושמש כאב בית דין."},{"i":2728,"n":"רבי מנחם","l":"מ","b":"אמורא ארץ ישראלי בדור השלישי. מובא בבבלי: \"אמר רב יוסף בר אבא אמר רבי מנחם אמר רבי אמי\" (כתובות ע\"ד ע\"א) ומצינו: \"א\"ר חגיי כד הוו יתבונן קומי מנחם\" (ירו\u0027, עירובין פ\"ז ה\"ה). מסר גם משם רבי יוחנן (ירו\u0027, מע\"ש פ\"ב ה\"ג)."},{"i":2729,"n":"ר\u0027 מנחם אחי ר\u0027 גוריון","l":"מ","b":"אמורא ארץ ישראלי בדור הרביעי. פירש לפני רבי אלעאי (ירו\u0027, ב\"מ פ\"ט ה\"ח)."},{"i":2730,"n":"מנחם איש גופתה אריה","l":"מ","b":"מובא בירושלמי (סנהדרין פ\"י ה\"ב), ונראה שהוא פנחס בן גובתא דאריח, כמובא בספרא (פ\u0027 בלק). אין לדעת אם נמנה עם החכמים."},{"i":2731,"n":"ר\u0027 מנחם איש גליא","l":"מ","b":"ע\"ע ר\u0027 מנחם דגליא."},{"i":2732,"n":"רבי מנחם איש כפר שערים","l":"מ","b":"אמורא ארץ ישראלי בדור הראשון. למד בבית המדרש בו למדו חייא וחזקיה, בני רבי חייא. ונראה שהיה גדול מהם (נדה כ\"ז ע\"א)."},{"i":2733,"n":"ר\u0027 מנחם בר אבין","l":"מ","b":"מובא רו\"ר (פ\"ב - ג\u0027)."},{"i":2734,"n":"מנחם בר יהודה בן לוי","l":"מ","b":"חי בדור שני לאמוראי ארץ ישראל. אביו היה חכם. נראה אולי, כי רבי יהושע בן לוי היה אח אביו, וכי הוא עצמו היה חכם (ירו\u0027, דמאי פ\"ה ה\"א)."},{"i":2735,"n":"רבי מנחם בר יוסי סתומתאה","l":"מ","b":"הוא רבי מנחם בר\u0027 יוסי בן חלפתא. ומובא בבבלי: \"אמר רבה בר בר חנה א\"ר יוחנן: \u0027זו דברי ר\u0027 מנחם בר יוסי סתומתאה\u0027\" (מגילה כ\"ו ע\"א)."},{"i":2736,"n":"ר\u0027 מנחם בר יעקב","l":"מ","b":"מובא בפסיקתא רבתי (פ\u0027 תשא - ס\"ט)."},{"i":2737,"n":"מנחם בר מבסימא","l":"מ","b":"אמורא ארץ ישראלי בדור הרביעי. מסר משם רבי אמי (ירו\u0027, סוף מעשרות)."},{"i":2738,"n":"רבי מנחם ברבי סימאי","l":"מ","b":"אמורא ארץ ישראלי בדור הראשון. בנו ותלמידו של רבי סימאי ומסר משם אביו (ירו\u0027, ברכות פ\"ה ה\"ב), ואביו רבי סימאי היה תנא (פסחים ק\"ד ע\"א רשב\"ם ד\"ה: ה\"ג). היה חסיד גדול, וקראו לו: \"בנן של קדושים\" (ע\"ז נ\"א ע\"א תד\"ה: ה\"ג) ומעולם לא הסתכל בצורת מטבע. כשנפטר, נתמעכו צורות פרצוף כל צלמים וצורת המטבעות (מו\"ק כ\"ה ע\"ב רש\"י ד\"ה: והוו)."},{"i":2739,"n":"רבי מנחם בר\u0027 יוסי בן חלפתא","l":"מ","b":"תנא בדור החמישי. הצעיר בחמשת בני ר\u0027 יוסי בן חלפתא. מכונה גם ורדימס, שפניו דומים לורד (שבת קי\"ח ע\"ב). רבי סתם כמה משניות אליביה (מגילה כ\"ו ע\"א) וסביר שאליו הכוונה (כתובות ק\"א ע\"ב): \"זו דברי ר\u0027 מנחם סתימתאה\". רב יוסף אמר עליו ש\"דרש להאי קרא כי סיני\" (סוטה כ\"א ע\"א). מובא בכמה שמות בש\"ס: אבירודימוס, אבדימוס."},{"i":2740,"n":"ר\u0027 מנחם דגליא","l":"מ","b":"מראשוני האמוראים בארץ ישראל. רבי יוחנן מסר משמו (ירו\u0027, ברכות פ\"ד ה\"ד). יתכן אולי, שהוא רבי מנחם איש גליא, תנא דברייתא הנזכר בתוספתא (עירובין פ\"ח)."},{"i":2741,"n":"ר\u0027 מנחם חתניה דר\u0027 אלעזר בר אבונה","l":"מ","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בהש\"ר (רפ\"ה), שמסר בשם רבי שמעון בר יאסיניא (שהיה מתלמידי ריש לקיש)."},{"i":2742,"n":"מנחם טלמא","l":"מ","b":"אדם גדול, או כנראה אמורא בזמן רבי יוחנן (ירו\u0027, סנהדרין ספ\"ב). וכן מובא בקה\"ר (פ\"ה פסוק ברבות)."},{"i":2743,"n":"מנחם יודאפה","l":"מ","b":"מובא בבבלי (מעילה י\"ג ע\"ב), ונראה שהוא רבי מנחם יודפאה."},{"i":2744,"n":"רבי מנחם יודפאה","l":"מ","b":"אמורא ארץ ישראלי בדור הראשון. רבי יוחנן מסר משמו (זבחים ק\"י ע\"ב). נראה, ששמו נשתבש לרבי מנחם יודפייה (ירו\u0027, סוכה פ\"ד ה\"ו) ולמנחם יודאפה (מעילה י\"ג ע\"ב)."},{"i":2745,"n":"רבי מנחם יודפייה","l":"מ","b":"מובא בירושלמי (סוכה פ\"ד ה\"ו), ונראה שהוא רבי מנחם יודפאה."},{"i":2746,"n":"רבי מנחם סתימתאה","l":"מ","b":"ע\"ע רבי מנחם בר יוסי סתומתאה."},{"i":2747,"n":"רבי מנחמא","l":"מ","b":"אמורא ארץ ישראלי בדור הששי. מסר בשם רבי מנא ב\u0027 (מדרש שמואל ספט\"ו), ומשם רב (ירו\u0027, שבת פי\"ד ה\"ג)."},{"i":2748,"n":"ר\u0027 מנחמא בר זעירע","l":"מ","b":"מובא בב\"ר (פל\"ד - ט\u0027), ונראה שצ\"ל: ר\u0027 מנחמא בר זעירא."},{"i":2749,"n":"ר\u0027 מנחמן","l":"מ","b":"מובא בשהש\"ר (פ\"ב פסוק כתפוח). ב\"סה\"ד\" הגיר\u0027: ר\u0027 מנאמן."},{"i":2750,"n":"מני","l":"מ","b":"ראה מנא."},{"i":2751,"n":"ר\u0027 מני","l":"מ","b":"מובא בבבלי (תענית כ\"ג ע\"ב), והוא ר\u0027 מנא ב\u0027."},{"i":2752,"n":"רבי מני בר פטיש","l":"מ","b":"אמורא ארץ ישראלי בדור השני. מסר משמו של רבי ינאי (חולין קל\"ה ע\"א). חלק עם רבי שמעון בן לקיש ורבי שמעון בן אליקם על רבי חנינא, רבי יוחנן ורבי אלעזר (שם מ\"ח ע\"ב)."},{"i":2753,"n":"רבי מני דמן צור","l":"מ","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מובא בבבלי (סנהדרין ה\u0027 ע\"ב)."},{"i":2754,"n":"ר\u0027 מני דקסרין","l":"מ","b":"אמורא ארץ ישראלי בדור השני. מובא בויק\"ר (ספט\"ז), שחלק עם רבי יוחנן ורבי שמעון בן לקיש."},{"i":2755,"n":"מניומי","l":"מ","b":"אמורא בבלי בדור השלישי - הרביעי. מצינו שחלק עם ר\"נ (ב\"מ ס\"ו ע\"א)."},{"i":2756,"n":"מניומי אסיא","l":"מ","b":"מובא בבבלי (ע\"ז כ\"ח ע\"ב). ספק אם היה חכם."},{"i":2757,"n":"רב מניומי בר חלקיה","l":"מ","b":"אמורא בבלי בדור השני - השלישי. תלמידו של רב חמא בר גוריא (שהיה תלמידו המובהק של רב), כמובא בבבלי (מנחות ל\"ב ע\"ב). היה חברם של רב חלקיה בר טוביא ורב הונא בר חייא (גיטין נ\"ז ע\"א)."},{"i":2758,"n":"רב מניומי בריה דרב נחומי א\u0027","l":"מ","b":"אמורא בבלי בדור השלישי - הרביעי. רב יוסף ואביי שלחו אליו לשאול שאלה בהלכה (כתובות פ\"א ע\"ב), לאחר ששאלו קודם לכן אותו ענין מרבי חנינא בר פפא (שם). ע\"ע רב מניומי בריה דרב נחומי ב\u0027."},{"i":2759,"n":"רב מניומי בריה דרב נחומי ב\u0027","l":"מ","b":"אמורא בבלי בדור הששי - השביעי. תלמידו דאמימר (כתובות ס\"ט ע\"א). יתכן שיש שיבוש בשמות שכן קצת קשה להניח שהיו שני רב מניומי בריה דרב נחומי (אם כי הדבר יתכן, כפי שסווגתים). \"סה\"ד\" חיברם בערך אחד, אך כתב: \"אמימר היה הרבה אחר רבא ואיך מניומי דקאי קמי אמימר יהיה בזמן רב יוסף ורבא\"."},{"i":2760,"n":"מניומי סבא דגוש חלב","l":"מ","b":"מובא ב\"זוהר חדש\" (ריש שה\"ש)."},{"i":2761,"n":"מניומין כנדיקא","l":"מ","b":"מובא בבבלי, שבא לשאול לפני רבא (חולין מ\"ט ע\"ב). ולי נראה שספק אם היה חכם בכלל (מלאכתו היה מכירת כדים), \"יוחסין\" ו\"סה\"ד\" הביאוהו כחכם בלי להעיר מאומה."},{"i":2762,"n":"מנימין בר איהי","l":"מ","b":"אמורא בבלי בדור השני. הוא ואחיו אבות בר איהי נהגו בחסידות (מגילה כ\"ח ע\"א). לאחד מהם היה גילוי אליהו (כתובות ס\"א ע\"א)."},{"i":2763,"n":"מנימין גר מצרי","l":"מ","b":"תנא ארץ ישראלי בדור הרביעי. תלמידו של רבי עקיבא. חברו של רבי יהודה (יבמות ע\"ו ע\"ב). משמו עולה, שהיה מצרי שהתגייר. נראה, שהוא בנימין שאמר לו ר\"ע: \"טעית\" (תוספתא שם פ\"ה)."},{"i":2764,"n":"מנימין סקסנאה","l":"מ","b":"ע\"ע בנימין גנוביא."},{"i":2765,"n":"ר\u0027 מנסיא בר בריה דר\u0027 מנסיא","l":"מ","b":"מובא בבבלי (יומא ד\u0027 ע\"ב) לפי גיר\u0027 השאלתות, ולפנינו: ר\u0027 מוסיא בר בריה דר\u0027 מסיא."},{"i":2766,"n":"מנשא","l":"מ","b":"אמורא ארץ ישראלי בדור הרביעי. ישב לפני רבי זירא (ירו\u0027, מגילה פ\"ב ה\"ב)."},{"i":2767,"n":"רבי מנשה","l":"מ","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רבי יהודה (ע\"ז כ\"ו ע\"א) וישב לפני רבי זירא (ירו\u0027, מגילה פ\"ה ה\"ב). חברו של רבה (עירובין ק\"ד ע\"א). עולא בא לביתו (שם)."},{"i":2768,"n":"רב מנשה בר זביד","l":"מ","b":"מובא בבבלי (יבמות י\"ט ע\"ב), והוא רב מנשיא בר זביד."},{"i":2769,"n":"רב מנשה בר שגובלי","l":"מ","b":"אמורא בבלי בדור השני. מובא בבבלי (עירובין כ\"ט ע\"א): \"גורסק בר דרי משמיה דרב, מנשיא בר שגובלי משמיה דרב וכו\u0027, אמר רב יוסף: \u0027שרא ליה מריה לרב מנשיא בר שגובלי\u0027 וכו\u0027\"."},{"i":2770,"n":"רב מנשיא בר גדא","l":"מ","b":"אמורא בבלי בדור הרביעי, תלמידו של רב הונא (סוכה י\"ג ע\"ב). לי נראה, שהיה מתלמידיו הקטנים של רב הונא, שכן מצינו: \"יתיב רב מנשיא בר גדא קמיה דאביי\" (מנחות י\"ז ע\"א) [שחי שני דורות אחרי רב הונא], ולא יתכן שתלמיד גדול של רב הונא ישב לפני אביי, אם כי אביי דיבר עליו בכבוד גדול: א\"ל אביי: \u0027עני מרי\u0027\" (שם). וכן מסר רב מנשיא בר גדא משמיה דרב חסדא (סוכה שם)."},{"i":2771,"n":"רב מנשיא בר זביד","l":"מ","b":"אמורא בבלי בדור השני - השלישי. תלמידו של רב (שבועות מ\"ה ע\"ב), ואח\"כ ישב לפני רב הונא (יבמות מ\"ה ע\"ב), ושם הגיר\u0027: רב מנשה בר זביד."},{"i":2772,"n":"רב מנשיא בר יעקב","l":"מ","b":"אמורא בבלי בדור השלישי - הרביעי. מובא בבבלי (ב\"מ כ\"ו ע\"א; מנחות ל\"ב ע\"א)."},{"i":2773,"n":"רב מנשיא בר ירמיה","l":"מ","b":"אמורא בבלי בדור השני. תלמידו של רב (נזיר ס\"ה ע\"ב)."},{"i":2774,"n":"רב מנשיא בר ירמיה מדיפתי","l":"מ","b":"אמורא בבלי בדור הששי. חברו של רב אבא בר שומני (עירובין ס\"ד ע\"א), וכשנפרדו אמר כל אחד דבר הלכה שכן \"לא יפטר אדם מחברו אלא מתוך דבר הלכה שמתוך כך זוכרו\" (שם). אביו של רב מנשיא, רב ירמיה מדיפתי, היה כנראה תלמידו של רב פפא (ב\"ק ע\"ג ע\"א), ומסר משם רבא (זבחים ל\"ד ע\"ב)."},{"i":2775,"n":"מנשיא בר מנחם","l":"מ","b":"מובא בבבלי: \"של בית מנשיא בר מנחם היו סוחטין ברימונים, אמר רב נחמן \u0027הלכה כשל בית מנשיא בר מנחם\u0027 א\"ל רבא לרב נחמן: \u0027מנשיא בן מנחם תנא הוא\u0027 וכו\u0027\" (שבת קמ\"ה ע\"ב). \"יוחסין\" כתב: \"בזמן רב,\" ו\"סה\"ד\": \"לא ידעתי מנ\"ל שהיה בזמן רב\"."},{"i":2776,"n":"מנשיא בר מנשה","l":"מ","b":"מובא בירושלמי (שבת פ\"ו ה\"ה), ונראה שט\"ס בשם, ו\"סה\"ד\" גם הוא היה לו ספק."},{"i":2777,"n":"רבי מנשיא בר עות","l":"מ","b":"תנא בבלי בדור החמישי. מובא בבבלי, ששאל את רבי יאשיה רבה בבית עלמין דהוצל (סנהדרין י\"ט ע\"א)."},{"i":2778,"n":"רב מנשיא בר שגובלי","l":"מ","b":"אמורא בבלי בדור השלישי, מסר משמיה דרב (עירובין כ\"ט ע\"א). ומצינו: \"אמר רב יוסף: שרא ליה מריה לרב מנשיא בר שגובלי, אנא אמריתא ניהליה אמתני\u0027 והוה אמרה אברייתא\" (שם)."},{"i":2779,"n":"רב מנשיא בר תחליפא","l":"מ","b":"אמורא בבלי בדור השלישי - הרביעי. מסר משם רב (פסחים ו\u0027 ע\"ב). מסופר, שרמי בר חמא לא אזמין עליה דרב מנשיא בר תחליפא [לא רצה לצרפו לשלשה לזימון], דתנא ספרא וספרי והלכתא, כי נח נפשיה דרמי בר חמא, אמר רבא: \u0027לא נח נפשיה דרמי בר חמא אלא דלא אזמין ארב מנשיא בר תחליפא\u0027\" (ברכות מ\"ז ע\"ב)."},{"i":2780,"n":"רב מנשיא בריה דרבא","l":"מ","b":"מובא בבבלי (ביצה ל\u0027 ע\"ב), ולפי גיר\u0027 ב\"ח, שגרס \"רב מנשיא\" במקום \"רב מנשיא בריה דרבא\" לא היה בכלל אמורא ושמו רב מנשיא בריה דרבא, שכן שמו מובא בש\"ס רק בפעם זאת."},{"i":2781,"n":"רב מנשיה","l":"מ","b":"אמורא בבלי בדור השני, תלמידו של שמואל (מנחות ל\"ה ע\"ב)."},{"i":2782,"n":"ר\u0027 מסיא","l":"מ","b":"מובא בבבלי (יומא ד\u0027 ע\"ב): \"מוסיא בר בריה דר\u0027 מסיא משמיה דר\u0027 מוסיא\"."},{"i":2783,"n":"מפשאה","l":"מ","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי: \"תני רב יוסף וכו\u0027 תני מפשאה\" (נדרים י\u0027 ע\"ב), ומפורש שם בפירוש המכונה פרש\"י: \"שם חכם\". \"יוחסין\" ו\"סה\"ד\" לא הביאוהו."},{"i":2784,"n":"מר (4)","l":"מ","b":"אמורא בבלי בדור השלישי. מובא בבבלי: \"מר ממשכי אייתי וכו\u0027\" (מנחות מ\"ג ע\"א), ופירש\"י ד\"ה מר: \"שם חכם\"; ד\"ה ממשכי: \"שם מקום\". ומצינו כמה חכמים ששמם \"מר\", כגון מר בר רב אשי, מר בר רב אידי, מר בר אמימר."},{"i":2785,"n":"מר אחא","l":"מ","b":"מובא בבבלי: \"שהא למר אחא תריסר ירחי\" (ב\"ק קי\"ב ע\"ב), דרבינא, ופירש\"י: \"מר אחא זה שמו\". ספק אם היה חכם, ונראה ששמו המלא היה מר אחא, ו\"מר\" לא שימש אצלו לשון כבוד."},{"i":2786,"n":"מר בר המדורי","l":"מ","b":"מובא בבבלי (שבת ק\"ז ע\"א), והוא בר המדורי."},{"i":2787,"n":"מר בר חייא","l":"מ","b":"אמורא בבלי בדור החמישי - הששי. מובא בבבלי: \"אמימר משמיה דרב נחמן וכו\u0027 מר בר רב חייא מתני איפכא וכו\u0027\" (חולין מ\"ה ע\"ב)."},{"i":2788,"n":"מר בר פופידתא","l":"מ","b":"חי בבבל בזמן אביי ורב יוסף. מובא בבבלי (עירובין ס\u0027 ע\"א). אין הוכחה שהיה חכם. \"סה\"ד\" כתב: \"ולא ידעתי אם חכם הוא\"."},{"i":2789,"n":"מר בר רב אדא","l":"מ","b":"אמורא בבלי בדור הראשון או השני. מובא בבבלי: \"רב אחא בר יוסף חש ביוקרא דליבא, אתא לקמיה דמר עוקבא, אמר ליה וכו\u0027, אזל שאל ביה מדרשא, אמרי ליה תנא דבי רב אדא, ואמרי לה תנא דבי מר בר רב אדא וכו\u0027\" (שבת ק\"מ ע\"א)."},{"i":2790,"n":"מר בר רב אידאי (2)","l":"מ","b":"אמורא בבלי בדור החמישי - הששי. מובא בבבלי, שרב אדא בר שימי הקשה לו (חולין ס\"ג ע\"א). מר בר אמימר - אמורא בבלי בדור השביעי. בנו ותלמידו של אמימר (ב\"ב קע\"ד ע\"א). היה גם תלמידו של רב אשי (שם). מסר משם רבא (שבת מ\"ה ע\"ב)."},{"i":2791,"n":"מר בר רב אשי","l":"מ","b":"אמורא בבלי בדור השביעי. כינויו היה טביומי (ב\"ב י\"ב ע\"ב). בנו ותלמידו של מסדר הש\"ס רב אשי (חולין ע\"ו ע\"ב). ישב על כסא אביו רק 82 שנה לאחר פטירתו, שכן כשנפטר רב אשי, ירש מרימר את מקומו ואחרי מרימר מלך רב אידי בר אבין, ואחריו רב נחמן בר רב הונא (\"אגרת רב שרירא גאון\"). רק בשנת ד\u0027 קי\"ד (453), כשנפטר ר\"נ בר ר\"ה, הומלך מר בר רב אשי (ב\"ב י\"ב ע\"ב). חברם של יהודה בר אמימר ורב אחא מדיפתי, ושלושתם היו שווים בחוכמה ולא היה אחד מופלג מחברו (ברכות מ\"ה ע\"ב). רש\"י כתב (חולין שם): \"וכמר בר רב אשי קיי\"ל בכל דוכתי בר מתרתי\" (שבועות מ\"א ע\"א תד\"ה: ולמר). \"יוחסין\" כתב: \"מר בר רב אשי, שחתם התלמוד\"."},{"i":2792,"n":"מר בריה דרב אחא בריה דרבא","l":"מ","b":"אמורא בבלי בדור הששי. בנו של רב אחא, שהיה בנו של רבא. מסופר שהוא ומריון חברו עשו שותפות בצמד בקר ובאו לברר דין לפני רב אשי (מו\"ק י\"א ע\"ב). ע\"ע מריון בר אבין."},{"i":2793,"n":"מר בריה דרב יוסף","l":"מ","b":"אמורא בבלי בדור החמישי. נראה, שהיה תלמידו של רבא, שכן מסר הרבה משמו (שבת מ\"ה ע\"ב). שקיל וטרי עם רב אשי בענין טריפות (חולין מ\"ח ע\"ב). אמר כי אינו חושש מהמינים ולא פחד ללכת להתוכח עמם (שבת קט\"ז ע\"א)."},{"i":2794,"n":"מר בריה דרבינא","l":"מ","b":"אמורא בבלי בדור הרביעי. תלמידו של רב ששת (שבת פ\u0027 ע\"ב). מסר משם רב נחמן (ברכות נ\"ח ע\"ב). חברו של רבא (חולין מ\"ג ע\"ב). היה מופלג בחסידות וישב בתענית כל השנה כולה מלבד עצרת ופורים וערב יום כיפור (פסחים ס\"ח ע\"ב). אמרו עליו: \"ירא שמים יוצא ידי שתיהן, ומנו: מר בריה דרבינא\" (שבת ס\"א ע\"א). מסופר על נסים שנעשו לו (ברכות נ\"ד ע\"א). בחתונת בנו ראה שהחכמים התבדחו יותר מהראוי. ושבר כוס של זכוכית לבנה שערכה 004 זוז, ונעצבו (שם, ל\u0027 ע\"ב). ממנו סיום תפילת \"שמונה עשרה\": \"אלקי נצור לשוני מרע וכו\u0027\" (שם י\"ז ע\"א)."},{"i":2795,"n":"מר הונא בריה דרב נחמן","l":"מ","b":"מובא בבבלי (ב\"מ מ\"ז ע\"א), וגיר\u0027 \"דק\"ס\": הונא מר בריה דרב נחמן."},{"i":2796,"n":"מר זוטרא (2)","l":"מ","b":"אמורא בבלי בדור הששי. מלך בפומבדיתא אחר רב כהנא בשנים ד\u0027 קע\"ג - קע\"ה (314 - 513) (\"אגרת רב שרירא גאון\"). תלמיד של רב פפא (חולין מ\"ג ע\"א) ושל רב פפי (סוכה כ\"ו ע\"ב) ומסר הרבה משמו, וכן היו בידו שמועות משם רב הונא (עירובין מ\"א ע\"ב). חברם של רב אשי ואמימר (ברכות מ\"ד ע\"ב), ושלושתם ישבו אפיתחא דבי אזגור מלכא (כתובות ס\"א ע\"א). רב אשי היה לו כתלמיד - חבר (מנחות ל\"ה ע\"ב). היו לו שני בנים חכמים, נתן בר מר זוטרא (סנהדרין כ\"ט ע\"א) והונא בריה דמר זוטרא (ב\"ב פ\"ו ע\"א)."},{"i":2797,"n":"מר זוטרא בר טוביה","l":"מ","b":"ע\"ע רב זוטרא בר טוביה."},{"i":2798,"n":"מר זוטרא בריה דרב הונא בריה דרב פפי","l":"מ","b":"אמורא בבלי בדור הששי. חברו של רבינא ושקיל וטרי עמו (חולין מ\"ח ע\"א)."},{"i":2799,"n":"מר זוטרא בריה דרב טבי","l":"מ","b":"אמורא בבלי בדור הששי. חברו של רבינא ושקיל וטרי עמו (זבחים מ\"ח ע\"ב)."},{"i":2800,"n":"מר זוטרא בריה דרב מרי","l":"מ","b":"אמורא בבלי בדור החמישי. נין לשמואל, אביו היה רב מרי. בנה של רחל בת שמואל שנשבתה, והתחתנה עם גר, ששמו היה איסר גיורא. היה צעיר מרבינא ומצינו ששאל אותו (חולין ק\"ח ע\"א), וחלק עמו (ב\"מ ס\"ז ע\"ב). היה לו אח ושמו ר\u0027 אחא סבא (קידושין ס\"ה ע\"ב)."},{"i":2801,"n":"מר זוטרא בריה דרב נחמן","l":"מ","b":"אמורא בבלי בדור הרביעי. בנו ותלמידו של ר\"נ (סוטה י\u0027 ע\"א). היה גדול בדורו. \"אמרוה רבנן קמיה דרבא משמיה דמר זוטרא בריה דר\"נ\" (ב\"ב קנ\"א ע\"ב). פעם דן דין תורה וטעה בפסק דין, ושאל את ר\u0027 יוסף אם חייב לשלם (סנהדרין ה\u0027 ע\"א). היה עשיר ומדקדק במעשיו (מו\"ק י\"ב ע\"א)."},{"i":2802,"n":"מר זוטרא חסידא","l":"מ","b":"אמורא בבלי שאין לקבוע זמנו במדוייק. נראה שהיה הריש במקומו: \"מר זוטרא חסידא כי הוו מכתפי ליה בשבתא דריגלא\" (סנהדרין ז\u0027 ע\"ב). היה זהיר במעשיו: \"דמר זוטרא חסידא כי מחייב בר בי רב שמתא, משמית נפשיה ברישא\" (נדרים ז\u0027 ע\"ב)."},{"i":2803,"n":"מר זוטרא מדרישבא","l":"מ","b":"אמורא בבלי בדור הששי - השביעי. בא לפני רב אשי לשאול בדין ירושה (ב\"ב קכ\"ו ע\"ב)."},{"i":2804,"n":"מר זוטרא רבה","l":"מ","b":"אמורא בבלי בדור החמישי. מר זוטרא דרש משמו (ביצה ח\u0027 ע\"א)."},{"i":2805,"n":"מר יהודה","l":"מ","b":"אמורא בבלי בדור השלישי. מסר בשם אבימי [רבו של ר\u0027 חסדא] (חולין מ\"ח ע\"א). הקשה לרב יוסף ולרב שמואל בריה דרבה בר בר חנה, ולא ידעו להשיב לו, ורבה קרא לו: קנטרן פלגא [קנטרן רגיל לחלוק על חברו] (קידושין נ\"ח ע\"א). פעם ישב לפני המלך הפרסי שבור מלכא, והמלך אמר עליו שהוא מכיר בו שהוא פרוש ולא יאכל דבר איסור (סוף ע\"ז)."},{"i":2806,"n":"מר יוחנא בריה דרב חנא בר אדא","l":"מ","b":"אמורא בבלי בדור הרביעי. רבא ורב ספרא ביקרו אצלו (חולין קל\"ג ע\"א), והגמרא מפקפקת אם צ\"ל \"בר ביזנא\" או \"בר אדא\"."},{"i":2807,"n":"מר יוחנא בריה דרב חנא בר ביזנא","l":"מ","b":"אמורא בבלי בדור הרביעי (ע\"ע מר יוחנא בריה דרב חנא בר אדא)."},{"i":2808,"n":"מר יחוני","l":"מ","b":"זו גירסת הרי\"ף (מו\"ק כ\"ד ע\"א)."},{"i":2809,"n":"מר ינוקא (2)","l":"מ","b":"אמורא בבלי. בנו של רב חסדא ואחיו של מר קשישא. דעת תוספות (ב\"ב ז\u0027 ע\"ב ד\"ה: מר) ש\"מר ינוקא\" הוא האח הקשיש, ועל שם שנולד בינקותו של רב חסדא, נקרא \"מר ינוקא\", ו\"מר קשישא\" הוא הצעיר ונולד בקשישותו של רב חסדא, ורש\"י פירש (כתובות פ\"ט ע\"ב): שני בנים היו לרב חסדא ושניהם שוים, אלא שהגדול קורין לו \"מר קשישא\" ולצעיר קורין לו \"מר ינוקא\". מוזכר רבות עם רב אשי, כגון: \"א\"ל מר ינוקא ומר קשישא בריה דרב חסדא לרב אשי וכו\u0027\" (פסחים ק\"ז ע\"א). לפי הזמנים קשה להולמו, כי רב חסדא נפטר ד\u0027 ס\"ח (803), ורב אשי נפטר ד\u0027 קפ\"ו (624) (811 שנה הבדילו ביניהם)."},{"i":2810,"n":"מר ממשכי","l":"מ","b":"אמורא ששמו מר ושם מקומו משכי (מנחות מ\"ג ע\"א רש\"י). ע\"ע מר."},{"i":2811,"n":"מר מר קשישא בריה דר\u0027 חסדא","l":"מ","b":"ע\"ע מר קשישא."},{"i":2812,"n":"מר נתן אסיא","l":"מ","b":"כך גירסת הרי\"ף, ולפנינו ר\u0027 נתן בר אסיא (פסחים נ\"ב ע\"א)."},{"i":2813,"n":"מר עוקבא (4)","l":"מ","b":"אמורא בבלי בדור הראשון - השני. היה ראש הגולה אחרי רב הונא ריש גלותא (\"אגרת רב שרירא גאון\"), וכן כתבו תוספות (סנהדרין ל\"א ע\"ב ד\"ה: אי). רש\"י כתב (מו\"ק ט\"ז ע\"ב) שהיה נשיא (ראש גולה בבבל כמו נשיא בא\"י). בלימוד תורה ישב מר עוקבא לפני שמואל, וכשהיו יושבים בדין ישב שמואל לפני מר עוקבא (שם). היה אב\"ד בכפרי (קידושין מ\"ד ע\"ב). האריך ימים אחרי רב ושמואל (כתובות ס\"ט ע\"ב). בין תלמידיו היו רב חסדא (ברכות י\u0027 ע\"ב) ורבי זירא (שבת ק\"ח ע\"ב). היה עשיר (שם נ\"ד ע\"ב רש\"י). נתן צדקה בסתר (כתובות ס\"ז ע\"ב). לפני שנפטר בדק ומצא כתוב בספריו שפיזר שבעת אלפי דינרי זהב, ואמר: \"צידה קלה לדרך רחוקה\", עמד ופיזר מחצית ממונו (שם)."},{"i":2814,"n":"מר עוקבא בן ברתא דרב","l":"מ","b":"אמורא בבלי בדור השלישי. הוא ואחיו נחמיה מכונים: \"שרים גאים היוצאים מישראל\" (חולין צ\"ב ע\"א). ע\"ע רבנא נחמיה בן ברתא דרב, וכן רבנא עוקבא."},{"i":2815,"n":"מר עוקבא בר חייא","l":"מ","b":"אמורא בבלי בדור הראשון. מרבותיו של רב חסדא (יבמות ס\"ג ע\"ב)."},{"i":2816,"n":"מר עוקבא בר חמא","l":"מ","b":"אמורא בבלי בדור השלישי - הרביעי. נראה שהוא רב עוקבא בר חמא. הוא ואחיו רמי בר חמא היו חתניו של רב חסדא, ונשאו שתי אחיות: בנותיו של רב חסדא (ברכות מ\"ד ע\"א). ומצינו: \"רמי בר חמא ורב עוקבא בר חמא זבון אמתא בהדי הדדי וכו\u0027, אתו לקמיה דאביי\" (ב\"ב כ\"ט ע\"ב). הקשה לרב נחמן (ב\"מ ס\"ה ע\"א). נראה, שהיה גם תלמידו של רבי יוסי בר חנינא (זבחים נ\"ה ע\"ב)."},{"i":2817,"n":"מר עוקבן","l":"מ","b":"אמורא בבלי בדור השני. אמר בשם רב (ירו\u0027, עירובין פ\"ח ה\"ה). ומצינו: \"ר\u0027 יעקב בר אחא ורבי זירא חד בשם מר עוקבן וחד בשם ר\"נ בר יהודה\" (שם פ\"ו ה\"ח), וכן מצינו: \"ר\u0027 יונה ור\u0027 יוסי חד בשם מר עוקבן וחד בשם ר\"נ בר יעקב\" (שם פ\"ז ה\"א)."},{"i":2818,"n":"מר קשישא","l":"מ","b":"אמורא בבלי בדור החמישי. בנו של האמורא המפורסם רב חסדא, ואחיו של מר ינוקא. תוספות סוברים שמר ינוקא הוא הגדול (ב\"ב ז\u0027 ע\"ב ד\"ה: מר). רש\"י סובר שמר קשישא הוא הגדול (כתובות פ\"ט ע\"ב ד\"ה: מר). לקח חלק בסידור הש\"ס עם רב אשי (פסחים ק\"ז ע\"א; ב\"מ ס\"ו ע\"ב; ב\"ב ז\u0027 ע\"ב). לפי סדר השנים נראה שנפטר בחיי רב אשי, ונראה שאחיו נפטר לפניו, שכן מצינו אותו עם רב אשי ללא אחיו (כתובות פ\"ט ע\"ב; שבת קי\"ד ע\"ב; סוכה ח\u0027 ע\"א)."},{"i":2819,"n":"מר קשישא בריה דרבא","l":"מ","b":"אמורא בבלי בדור הששי. מובא בבבלי: \"אשכחוה לרב אשי דקא מצטער מהבלא (שהיה אבק עולה ומרבה הבל), א\"ל: \u0027לא סבר לה מר להא דתניא, הרוצה לרבץ ביתו בשבת וכו\u0027\" (שבת צ\"ה ע\"א)."},{"i":2820,"n":"מר קשישא בריה דרבה","l":"מ","b":"מובא בבלי (שבת צ\"ו ע\"א), ודף קודם לכן (שבת צ\"ה ע\"א) הגיר\u0027: \"מר קשישא בריה דרבא\"."},{"i":2821,"n":"מר שמואל (2)","l":"מ","b":"מובא בבבלי (חולין ק\"ה ע\"א), והוא שמואל, ובאותו עמוד מובא גם \"שמואל\" וגם \"מר שמואל\" ואחד הם."},{"i":2822,"n":"מר שמואל מר","l":"מ","b":"אמורא בבלי בדור החמישי. היה בזמנו של רבא ורב פפא. ומצינו (ביצה כ\"א ע\"ב): \"אדבריה רבא למר שמואל\" (מר - דק\"ס); (שם י\"ד ע\"ב): \"רב פפי איקלע לבי מר שמואל\" (מר - דק\"ס) \"אייתי ליה דייסא ולא אכל וכו\u0027 מפני פריצותא דעבדי\"."},{"i":2823,"n":"רב מרדכי א\u0027","l":"מ","b":"אמורא בבלי בדור הרביעי. מובא בבבלי: \"בעא מיניה רב מרדכי וכו\u0027, אתא שיליה לרב יוסף וכו\u0027\" (שבת צ\"ט ע\"ב)."},{"i":2824,"n":"רב מרדכי ב\u0027","l":"מ","b":"אמורא בבלי בדור הששי. תלמיד תלמידו של רבא, ואמר לרב אשי: \"הכי אמר אבימי מהגרוניא משמיה דרבא\" (כתובות ק\"ט ע\"ב)."},{"i":2825,"n":"רב מרי א\u0027","l":"מ","b":"אמורא בדור השני - השלישי. תלמידו של רבי יוחנן (ברכות מ\u0027 ע\"א). ר\"נ הסתמך עליו ואמר: \"ולאו אמר רב מרי וכו\u0027\" (שבת קנ\"ב ע\"ב). אביי אמר לרב יוסף: \"והאמר רב מרי\" (ב\"ב כ\"ג ע\"א)."},{"i":2826,"n":"רב מרי בר אבוה","l":"מ","b":"אמורא בדור השלישי - הרביעי תלמידו של ר\u0027 יצחק (פסחים פ\"ג ע\"א)."},{"i":2827,"n":"רב מרי בר איסור גיורא","l":"מ","b":"אמורא בבלי בדור הרביעי. ופרש\"י: בכמה מקומות קרי ליה בר רחל, [ואמו] בתו של שמואל היתה ונשבית בין נכרים ונתעברה מנכרי, ואח\"כ התגייר הנכרי ושמו איסור והתחתן עמה ונולד רב מרי, כמובא (ב\"ב קמ\"ט ע\"א): רב מרי הורתו שלא בקדושה ולידתו בקדושה הואי (ברכות ט\"ז ע\"א). היה חכם גדול ורבא קרא לו \"מר\" (ב\"מ ע\"ג ע\"ב). אמר משמיה דאביי, (ב\"ב ס\"א ע\"ב). זכה לראות מלאכים (תענית כ\"ד ע\"ב). העמיד שני בנים חכמים ושמם מר זוטרא ורב אדא סבא, שהיו בימי רב אשי (קידושין ס\"ה ע\"ב). ההבדל בשנים בין בת שמואל לרב אשי גדול מאד, ואכן הגמרא תמהה דילמא תרי מרי בר רחל היו (שבת קנ\"ד ע\"א)."},{"i":2828,"n":"מרי בר איסק","l":"מ","b":"שני מרי בר איסק היו, אחד בימי רב חסדא ואחד בימי רב אשי, כפי שפירשו התוספות (יבמות כ\"א ע\"ב ד\"ה: רב אשי), ונראה ששניהם לא היו חכמים. \"יוחסין\" ו\"סה\"ד\" הביאום מבלי לציין שלא היו חכמים."},{"i":2829,"n":"מרי בר בריה דרב הונא בריה דרבי ירמיה בר אבא","l":"מ","b":"מובא בבבלי (ברכות ל\"א ע\"א), וצ\"ל מרי בריה דר\"ה וכו\u0027."},{"i":2830,"n":"רב מרי בר חמא","l":"מ","b":"אמורא בבלי בדור הרביעי. הקשה לרב חסדא, ונראה שהיה תלמידו (ערכין כ\"א ע\"א)."},{"i":2831,"n":"רב מרי בר יעקב","l":"מ","b":"אמורא ארץ ישראלי בדור החמישי. מבעלי האגדה. מסר משם רבי יודן (מדרש שמואל פי\"ג - ח\u0027)."},{"i":2832,"n":"רב מרי בר מר","l":"מ","b":"אמורא בבלי בדור השלישי. תלמידו של מר עוקבא (יבמות ע\"ו ע\"א). ר\u0027 אבא בר זבדא שלח [מארץ ישראל] למרי בר מר, שישאל הלכה מרב הונא, ואדהכי נפטר רב הונא (גיטין פ\"ו ע\"ב). חי עד דורו של רבה ואביי (מגילה ז\u0027 ע\"ב). רבה שדר ליה למרי בר מר ביד אביי (שם). ה\"יוחסין\" כתב שהיה בזמן שמואל, ו\"סה\"ד\" כתב: \"לא מצאתי\"."},{"i":2833,"n":"מרי בר מר עוקבא","l":"מ","b":"אמורא בבלי בדור השני. בנו של מר עוקבא. תלמידו של שמואל (חולין מ\"ג ע\"ב). יש משבשים וגורסים מר בר מר אמר מר עוקבא, ולגירסתם לא היה למר עוקבא בן ושמו מרי."},{"i":2834,"n":"מרי בר מרי","l":"מ","b":"מובא בבבלי (ב\"ב צ\"א ע\"א), וכתב \"דק\"ס\" שצ\"ל: מרי בר מר."},{"i":2835,"n":"רבי מרי בר רב כהנא","l":"מ","b":"אמורא בבלי בדור השלישי. בנו של רב כהנא (תלמידו של רב). נראה, שהיה תלמידו של רב יהודה (ע\"ז מ\"ט ע\"א)."},{"i":2836,"n":"רב מרי בר רחל","l":"מ","b":"מובא בבבלי (שבת קנ\"ד ע\"א), והוא רב מרי בר איסור גיורא."},{"i":2837,"n":"רב מרי ברה דבת שמואל","l":"מ","b":"ע\"ע רב מרי בר איסור גיורא."},{"i":2838,"n":"רב מרי ברה דבת שמואל בר שילת","l":"מ","b":"מובא בבבלי (ב\"ב ס\"א ע\"ב). \"סה\"ד\" הגיה מסברתו למחוק תיבות בר שילת, וכן הגיה \"דק\"ס\"; א\"כ, מעולם לא היה חכם בשם זה, שכן הוא מובא בש\"ס רק במקום זה."},{"i":2839,"n":"רב מרי בריה דבת שמואל","l":"מ","b":"מובא בבבלי (ברכות ט\"ז ע\"א), והוא רב מרי בר איסור גיורא."},{"i":2840,"n":"רב מרי בריה דרב אשי","l":"מ","b":"מובא בבבלי (ב\"מ ק\"ג ע\"א), ונראה ט\"ס, כמוכח ב\"סה\"ד\" וב\"דק\"ס\", וא\"כ לא היה ולא נברא חכם בשם זה שכן מובא בש\"ס רק במקום זה."},{"i":2841,"n":"רב מרי בריה דרב ביזנא","l":"מ","b":"אמורא בבלי בדור השלישי, בזמנו של רב יוסף (ביצה כ\"ח ע\"ב)."},{"i":2842,"n":"רב מרי בריה דרב הונא בריה דרב ירמיה בר אבא","l":"מ","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. בן בנו של ר\u0027 ירמיה בר אבא (תלמיד חבר של רב). \"א\"ל רב חסדא למרי בריה דר\"ה בריה דר\u0027 ירמיה בר אבא וכו\u0027: \u0027הא אמר אבוה דאבוך משמיה דרב\u0027\" (עירובין כ\"א ע\"א). אמר בשם רבי יוחנן (ברכות כ\"ו ע\"א)."},{"i":2843,"n":"רב מרי בריה דרב חסדא","l":"מ","b":"אמורא בבלי בדור הרביעי. בנו של רב חסדא. היה גיסו של רבא (רבא התחתן עם אחותו). מסופר עליו ועל אחיו רב פנחס, שלאחד מהם נגלה אליהו הנביא ודבר עמו (כתובות ס\"א ע\"א)."},{"i":2844,"n":"רב מרי בריה דרב פנחס","l":"מ","b":"אמורא בבלי בדור הששי. חי בימי רב אשי. בן בנו של רב חסדא כמובא \"ההוא גברא דאנסוהו נכרים, ואחוי אחמרא דרב מריה בריה דרב פנחס בריה דרב חסדא וכו\u0027, אתא לקמיה דרב אשי וכו\u0027\" (ב\"ק קי\"ז ע\"א)."},{"i":2845,"n":"מרי בת רב הונא","l":"מ","b":"מובא בבבלי (עירובין ס\"ד ע\"א), ונראה אולי שצ\"ל: מרי בריה דרב הונא בריה דר\u0027 ירמיה בר אבא."},{"i":2846,"n":"רב מרי ב\u0027","l":"מ","b":"אמורא בבלי בדור החמישי. נראה, שהיה תלמידו של רבא (קדושין ל\"ב ע\"ב). שאל מרב פפא (ברכות כ\"ד ע\"א). רב אשי הקשה לו (זבחים כ\"ט ע\"ב)."},{"i":2847,"n":"רבי מריון","l":"מ","b":"אמורא ארץ ישראלי בדור השני. תלמידו של רבי יהושע בן לוי, כמובא: \"והאמר רבי מריון אמר רבי יהושע בן לוי, ואמרי לה חנא רבה בר מריון בדבי רבן יוחנן בן זכאי וכו\u0027\" (עירובין י\"ט ע\"א)."},{"i":2848,"n":"מריון בר אבין","l":"מ","b":"אמורא בבלי בדור הששי. חברו של מר בריה דרב אחא בריה דרבא. מסופר, שהיה להם צמד בקר בשותפות, ואירע אבילות למר בריה דרב אחא, ולא שלח את שורו לחרוש בשדה לפי שהיה אבל (כי חשב שמצווה על שביתת בהמתו מדרבנן), ורב אשי העמידו על טעותו ואמר: \"גברא רבא כמר בריה דרב אחא בריה דרבא עביד הכי, נהי וכו\u0027\" (מו\"ק י\"א ע\"ב)."},{"i":2849,"n":"מריון בריה דרבין","l":"מ","b":"ע\"ע מריון בר אבין."},{"i":2850,"n":"מרימר","l":"מ","b":"אמורא בבלי בדור השביעי. תלמידו של רבינא (חברו של רב אשי), שמצינו: \"א\"ל רבינא למרימר וכו\u0027 ורבינא לשיבושי למרימר וכו\u0027\" (יבמות ע\"ה ע\"ב), ופרש\"י: \"לידע אם מחודד הוא להשיב על שאלתו\". נראה, שהיה קטן ממר זוטרא (פסחים ק\u0027 ע\"א), ואמר משמו של מר זוטרא (סוכה מ\"ה ע\"א). רבינא האחרון היה תלמידו: \"אמר רבינא: \u0027אמר לי מרימר\u0027\" (חולין קל\"ב ע\"א), וכן: \"יתיב מרימר וקאמר וכו\u0027, איתיביה רבינא למרימר וכו\u0027\" (שבת פ\"א ע\"ב). באו לשאול ממנו: יהודה בר מרימר (בנו), מר בר רב אשי ורב אחא מדיפתא (ברכות מ\"ה ע\"ב). נראה, שישב על כסאו של רב אשי משנים ד\u0027 קפ\"ו - קצ\"א (624 - 134)."},{"i":2851,"n":"מרימר בר חנינא","l":"מ","b":"חי בדור הרביעי לאמוראי בבל, ואין להכריע אם היה חכם. מובא בבבלי, ששכר פרידה ומתה ובאו לשאול מרבא אם חייב לשלם (ב\"מ צ\"ז ע\"א) ומהענין שם, שלא טען לפני רבא את הטענות שרבנן אמרו לרבא, ניתן אולי לומר שבאמת לא היה חכם."},{"i":2852,"n":"רבי מרינוס (2)","l":"מ","b":"אמורא ארץ ישראלי בדור השלישי. לדעתו של הרשב\"ם (ב\"ב נ\"ו ע\"א), מסר משום רבי יוחנן (ועיין שם תוספות ד\"ה: אין)."},{"i":2853,"n":"מרינוס בי רבי יהושע","l":"מ","b":"מובא בירו\u0027 (ברכות פ\"ו ה\"ה), והוא מרינוס בריה דרבי אושעיא רבה."},{"i":2854,"n":"רבי מרינוס בריה דרבי אושעיא רבה","l":"מ","b":"אמורא ארץ ישראלי בדור הראשון - השני. חברו של רבי חנינא, ויחד מסרו בשם אבא נהוראי (ב\"ר פצ\"א - ט\u0027). חלק עם אביו רבי אושעיא (ירו\u0027, גיטין פ\"ד ה\"ו)."},{"i":2855,"n":"מרתא (2)","l":"מ","b":"אחיו של רבי חייא ודודו של רב וחמישה אחים היו: \"איבו (אביו של רב) וחנה (אביו של רבה בר חנה) ושילא ומרתא ורבי חייא כולהו בני אבא בר אחא וכו\u0027\" (סנהדרין ה\u0027 ע\"א)."},{"i":2856,"n":"משה בר עצרא הכהן","l":"מ","b":"חי בבבל בזמנו של אביי, ואין לדעת אם היה חכם. בנו רב הונא היה חכם: \"משה בר עצרי ערבה דכתובתה דכלתיה הוה, רב הונא בריה צורבא מדרבנן היה וכו\u0027, אמר אביי וכו\u0027\" (ב\"ב קע\"ד ע\"ב)."},{"i":2857,"n":"ר\u0027 משין בר נגרי","l":"מ","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מסר יחד עם ר\u0027 יודן ור\u0027 איבו משמו של ר\u0027 יוחנן (ב\"ר פפ\"ב - ד\u0027)."},{"i":2858,"n":"רב משרשיא","l":"מ","b":"אמורא בבלי בדור החמישי. תלמידו המובהק של אביי (קידושין ל\"ג ע\"א), ותלמידו של רבא (גיטין צ\u0027 ע\"א). למד יחד עם חברו רבינא לפני רבא (יבמות ל\"ו ע\"ב), היה חתנו של רב כהנא (ב\"ב צ\"ז ע\"ב). חותנו רב כהנא שאל מרבא (שם). היה לו בן חכם ושמו רב סמא, שהיה תלמידו של רב אשי (חולין י\"ז ע\"ב). אמר לבנו שלמד לפני רב פפא, שישאל מרב פפא שאלה מסובכת, ורב פפא אמר לבנו של רב משרשיא: \"אי דייקינן כולי האי לא הוי תנינן\" (עירובין מ\"ח ע\"א)."},{"i":2859,"n":"רב משרשיא בר בריה דרב אחא בר רב","l":"מ","b":"מאחרוני האמוראים הבבליים בדור השמיני. נראה, שהיה מראשי רבנן סבוראי. מובא בבבלי: \"אמר רב משרשיא מ\"ט דאבוה דאבא וכו\u0027\" (סנהדרין ע\"ז ע\"א)."},{"i":2860,"n":"רב משרשיא בר חיקלאי","l":"מ","b":"אמורא בבלי שאין לקבוע זמנו המדוייק. מובא פעם אחת בבבלי (כתובות ק\u0027 ע\"ב)."},{"i":2861,"n":"רב משרשיא בר פקוד","l":"מ","b":"אמורא בבלי. \"סה\"ד\" כתב, שחי בזמנו של רב סמא בר רבא (בדור השביעי), ומלך פרס הרגו."},{"i":2862,"n":"רב משרשיא בר רב דימי","l":"מ","b":"מובא בבבלי (גיטין ע\"ח ע\"א), ונראה שצ\"ל: רב משרשיא בר רב אמי."},{"i":2863,"n":"רב משרשיא בר רבא","l":"מ","b":"אמורא בבלי בדור החמישי. בנו ותלמידו של רבא. רבא אמר על בנו: \"חכים ברי בטרפות כרבי יוחנן\" (חולין נ\u0027 ע\"א)."},{"i":2864,"n":"רב משרשיא בריה דרב אחא","l":"מ","b":"אמורא בבלי בדור הששי. מובא בבבלי: \"אמר ליה רב משרשיא בריה דרב אחא לרבינא וכו\u0027\" (חולין ס\"ז ע\"ב), היימן, שגורס: \"א\"ל רב משרשיא בר בריה דרב אחא\", עקר מהש\"ס את האמורא רב משרשיא בריה דרב אחא, והפכו לרב משרשיא בר בריה דרב אחא, שהיה מרבנן סבוראי."},{"i":2865,"n":"רב משרשיא בריה דרב אידי","l":"מ","b":"אמורא בבלי. מובא בבבלי (גיטין ל\u0027 ע\"ב). ונראה שחי בזמנו של אביי או לאחריו."},{"i":2866,"n":"רב משרשיא בריה דרב אמי","l":"מ","b":"אמורא ארץ ישראלי בדור השני - השלישי. חלק עם רבי יוחנן ועם רב אדא בר אהבה (ב\"ב פ\"ה ע\"ב; גיטין ע\"ח ע\"א - ושם הגיר\u0027: רב משרשיא בר רב דימי). אמר לר\u0027 אסי: \"אסברא לך\" (קידושין ס\u0027 ע\"א)."},{"i":2867,"n":"רב משרשיא בריה דרב חייא","l":"מ","b":"אמורא בבלי. נראה שחי בזמנו של רב אשי בן הדור הששי (ב\"ב פ\"ב ע\"א)."},{"i":2868,"n":"רב משרשיא בריה דרב נתן","l":"מ","b":"אמורא בבלי בדור החמישי - הששי. נראה, שאולי היה גדול מרבינא כמובא: \"אמר רבינא: אמר לי רב משרשיא בריה דרב נתן וכו\u0027\" (פסחים קט\"ו ע\"א)."},{"i":2869,"n":"רב משרשיא מתוסנייא","l":"מ","b":"אמורא בבלי בדור החמישי - הששי. מובא בבבלי, ששלח לרב פפי: \"ילמדנו רבינו\" (יבמות כ\"א ע\"ב)."},{"i":2870,"n":"רבי מתון","l":"מ","b":"אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של רבי יהושע בן לוי (ב\"ק צ\"ו ע\"א). שאל מרבי יוחנן (ירו\u0027, מו\"ק פ\"ג ה\"ז)."},{"i":2871,"n":"רב מתיא בן חרש","l":"מ","b":"תנא בדור השלישי - הרביעי. הלך לרומי ויסד שם ישיבה גדולה (סנהדרין ל\"ב ע\"ב): \"אחר רבי מתיא לרומי\". וכשהיה רבי שמעון בן יוחאי ברומי, ביקר אצלו בישיבה (מעילה י\"ז ע\"א). נראה, שלמד מרבי אליעזר בן הורקנוס (יומא נ\"ג ע\"ב). היה חברם של רבי יהודה בן בתירא (השני), חנינא בן אחי רבי יהושע ורבי יונתן, ומצינו שהלכו יחד מארץ ישראל לחוץ לארץ וחזרו למקומם (ספרי ראה - נ\"ג). היה בקי ברפואות (יומא פ\"ד). מעולם לא הסתכל באשה. זיו פניו דמה לחמה, וקלסתר פניו למלאכי השרת (\"ילקוט\" פ\u0027 ויחי בשם מד\u0027 אבכיר)."},{"i":2872,"n":"מתיא מן דבתרה","l":"מ","b":"אמורא ארץ ישראלי. מובא בירושלמי (ערלה פ\"א ה\"א). אם נלמד פשט שענה על דברי רבי יוסי א\"כ יתכן שאפשר להוכיח, שחי בדור הששי לאמוראי א\"י."},{"i":2873,"n":"ר\u0027 מתנה (2)","l":"מ","b":"בהגהות ר\"ש שלום ב\"יוחסין\" כתב, שראה ב\"מגילת סתרים\" לרב נסים גאון, שר\u0027 מתנה היה בנו של רבי יוחנן, והלך לבבל ללמוד לפני שמואל, ור\u0027 מתנה זה נשאר מעשרת בניו של ר\u0027 יוחנן שכן לר\u0027 יוחנן היו עשרה בנים וכולם מתו על פניו (ברכות ה\u0027 ע\"ב)."},{"i":2874,"n":"ר\u0027 מתנה א\u0027","l":"מ","b":"אמורא בבלי בדור השני. תלמידו המובהק של שמואל (עירובין ו\u0027 ע\"ב). תלמידו של רב (שבת כ\"א ע\"א). חברו של רב יהודה (קידושין ע\u0027 ע\"ב). רבי אבא שאל ממנו (ברכות י\"א ע\"ב). רבי זירא היה מתלמידיו (שבת ק\"ח ע\"ב). מושבו היה בפופוניא ושם דרש בדיני פסח (פסחים מ\"ב ע\"א)."},{"i":2875,"n":"רב מתנה ב\u0027","l":"מ","b":"אמורא בבלי בדור החמישי. מרבותיו של רב אשי (זבחים כ\"ט ע\"א). נשא - ונתן עם אביי (כתובות ל\"ה ע\"ב)."},{"i":2876,"n":"רבי מתניא","l":"מ","b":"אמורא ארץ ישראלי בדור החמישי - הששי. בנו של רבי יודן, נראה, שהיה גדול מאביו, שכן את אביו מיחסים אליו, כמובא בירושלמי: \"א\"ר יודן אבוי דרבי מתניא\" (דמאי פ\"ז ה\"ד). הורה יחד עם רבי אליעזר (כנראה רבי אליעזר ברבי יוסי האמורא הארץ ישראלי בדור החמישי - הששי) ועם רבי אבא מרי (ירו\u0027, ביצה פ\"א ה\"ט). מסופר כיצד השיא את בתו (ירו\u0027, כתובות פ\"א ה\"א)."},{"i":2877,"n":"מתתיה בן יהודה","l":"מ","b":"מובא פעמיים בבבלי: \"תני מתתיהו בן יהודה\" (חולין ס\"ז ע\"א; מנחות ע\"ט ע\"ב). \"יוחסין\" ו\"סה\"ד\" כתבו שהיה תלמידו של שמואל. (ואני לא ידעתי את המקור לזה, ואולי גיר\u0027 אחרת נזדמנה להם: א\"כ, לפי דעתם היה אמורא בבלי בדור השני)."},{"i":2878,"n":"נאנאי בריה דרב יוסף בריה דרבא","l":"נ","b":"אמורא בבלי בדור הששי. בן בנו של האמורא הידוע רבא. מובא בבבלי (יבמות ס\"ו ע\"ב): \"א\"ל נאנאי בריה דרב יוסף בריה דרבא, לרב כהנא: והאמר רבא וכו\u0027\"."},{"i":2879,"n":"נבו","l":"נ","b":"חי בתקופת התנאים בדור השלישי - הרביעי. מובא בתוספתא (פסחים ספ\"ג). ואולי הוא בן בוהיין."},{"i":2880,"n":"נגדא","l":"נ","b":"שם חכם. מובא בויק\"ר (פכ\"ה - ו\u0027): \"א\"ר תנחומא מסתברא דנגדא וכו\u0027\"."},{"i":2881,"n":"רבי נהוראי (2)","l":"נ","b":"תנא בדור הרביעי. מובא בבבלי (קידושין פ\"ב ע\"א). חלק על רבי מאיר (רבי מאיר עצמו גם כן נקרא \"רבי נהוראי\" [עירובין י\"ג ע\"ב], וכן נקרא רבי אלעזר בן ערך \"ר\u0027 נהוראי\" [שבת קמ\"ז ע\"ב]). מסר משם רבי יהושע (נזיר ה\u0027 ע\"א). אליהו הנביא שאל ממנו, וכשהשיב לו אמר לו אליהו הנביא \"בני חייך כן הוא\" (ירו\u0027, ברכות פ\"ט ה\"ב), ואין להכריע אם הכוונה אליו או לר\u0027 נהוראי האמורא."},{"i":2882,"n":"ר\u0027 נהוראי","l":"נ","b":"הוא רבי מאיר (עירובין י\"ג ע\"ב)."},{"i":2883,"n":"נהוראי בן שונייא","l":"נ","b":"תנא בדור החמישי. מסר משום רבי שמעון בן יוחאי (תוספתא ריש מעשרות)."},{"i":2884,"n":"נהוראי בר שיניא","l":"נ","b":"מובא בירושלמי (מעשרות פ\"א ה\"ג), והוא נהוראי בן שונייא."},{"i":2885,"n":"רבי נהוראי סבא","l":"נ","b":"חי בזמן התנאים. האניה שבה הפליג טבעה והוא ניצל בנס (\"זוהר\" ויקרא ו\u0027). מובא עם רבי שמעון בן יוחאי (שם, ספ\u0027 תצוה)."},{"i":2886,"n":"ר\u0027 נהילאי בר אידי","l":"נ","b":"אמורא בבלי בדור השני. תלמידו של שמואל (תענית ו\u0027 ע\"א)."},{"i":2887,"n":"נהרבלאי","l":"נ","b":"מובא בבבלי (סנהדרין י\"ז ע\"ב). ב\"נהרבלאי\" הכוונה לרמי בר ברבי ורש\"י גרס: \"רמי בר ברוכי\" (ביצה ח\u0027 ע\"ב). בהקדמת הרמב\"ם לזרעים בהגהה, ובספר הכריתות לשון לימודים (שער ג\u0027 פ\"ו), כתבו, שמה שאמרו בסנהדרין \"נהרבלאי\" הוא רב ביבי בר ביזנא."},{"i":2888,"n":"נהרדעי","l":"נ","b":"מובא בבבלי (ב\"ב ז\u0027 ע\"ב); ופירשו התוספות: \"רב חמא נהרדעא הוא וכו\u0027 ושמואל נמי נהרדעי הוא\". ע\"ע אמוראי דנהרדעא."},{"i":2889,"n":"נוולא","l":"נ","b":"\"סה\"ד\" תמה על ה\"יוחסין\" מדוע הביאו בין שמות החכמים, וזה לשון \"סה\"ד\": \"לא ידעתי מי הגיד לו [ל\"יוחסין\"] שהוא חכם וכו\u0027 יהיה איך שיהיה הוא שם אשה\", עכ\"ל. ורש\"י באמת מפרש כך וזה לשונו: \"ואני אומר שזה שמה\" (ב\"מ ס\"ז ע\"א); א\"כ, בוודאי אינו שם חכם. רש\"י מביא תשובת הגאונים ש\"נוולא\" זה לשון ארמי כשרוצה לומר אתה והוא או אתה והיא (שם)."},{"i":2890,"n":"רבי נזירא","l":"נ","b":"אמורא ארץ ישראלי בדור השני - השלישי. רבי לוי מסר משמו (ב\"ר פי\"ב - ו\u0027). וכן מובא בירושלמי (ברכות פ\"ח ה\"ח)."},{"i":2891,"n":"נחום","l":"נ","b":"אמורא ארץ ישראלי בדור הראשון - השני. מסר בשם רב (ירו\u0027, שבת פ\"י ה\"ו). ומצינו: ר\u0027 נחום בבבלי (ברכות נ\"ה ע\"ב; חולין צ\"ח ע\"א)."},{"i":2892,"n":"רבי נחום","l":"נ","b":"מובא בבבלי (שבת פ\"ח ע\"ב). אותו ענין מובא במקום אחר (סוכה ה\u0027 ע\"א) ושם \"רבי תנחום\"."},{"i":2893,"n":"ר\u0027 נחום אחוה דר\u0027 אילא","l":"נ","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (ירו\u0027, ביצה פ\"ה ה\"ב)."},{"i":2894,"n":"נחום איש גליה","l":"נ","b":"תנא דברייתא. וא\"ר יוסף הלכה כמותו (כתובות ס\u0027 ע\"א)."},{"i":2895,"n":"נחום איש גם זו","l":"נ","b":"תנא בדור השלישי. רבו המובהק של רבי עקיבא. רבי עקיבא שימשו עשרים ושתיים שנה (חגיגה י\"ב ע\"א). היה דורש כל אתין שבתורה (שם). היה צדיק וחסיד גדול ומלומד בנסים, ועל כל דבר ודבר שקרה לו נהג לומר: \"גם זו לטובה\" (תענית כ\"א ע\"א). פעם אחת ביקש ממנו עני מזון לאכול, ושהה לרגע והעני מת מרעב, וקילל עצמו שיהא סומא בעיניו ויקטעו ידיו ורגליו וכל גופו יהיה מצורע, כעונש על שלא נתן מייד מזון לעני, וכך היה - שכב במטה בבית רעוע, ורגלי מטתו מונחות בספלים של מים, שלא יעלו עליו נמלים."},{"i":2896,"n":"רבי נחום בר סימאי","l":"נ","b":"מובא בירושלמי (ע\"ז רפ\"ג), והוא רבי מנחם בר סימאי."},{"i":2897,"n":"רבי נחום בר פפא","l":"נ","b":"מובא בבבלי, שאמר משום רבי אלעזר הקפר (יומא ס\"ז ע\"א). גיר\u0027 \"יוחסין\": ר\u0027 נחמן בר פפא; גיר\u0027 \"דק\"ס\": ר\u0027 נחום בר פרנק."},{"i":2898,"n":"נחום בר שימלאי","l":"נ","b":"מובא ב\"זוהר חדש\" (רות פ\"א)."},{"i":2899,"n":"נחום הזקן","l":"נ","b":"תנא. מובא בבבלי (ברכות מ\"ח ע\"ב). \"סה\"ד\" תמה על \"יוחסין\" המפקפק אם הוא נחום הלבלר או נחום המדי, ולדעתו ברור שהיה בזמן רבי (ואינו מבין פליאת \"סה\"ד\", שכן יתכן שמסדר הש\"ס שיבצם יחד ואין ראיה שהיה בזמן רבי)."},{"i":2900,"n":"נחום הלבלר","l":"נ","b":"מחכמי ישראל בסוף תקופת ה\"זוגות\" ותחילת תקופת התנאים. ישב בלשכת הגזית. רבן גמליאל שאל ממנו (משנה פאה פ\"ב מ\"ו)."},{"i":2901,"n":"נחום המדי","l":"נ","b":"תנא קדמון בדור הראשון לתנאים. יליד ארץ מדי, שעלה לירושלים (ע\"ז ז\u0027 ע\"ב) ונתמנה בה לדיין. היה מ\"גוזרי גזירות שבירושלים\" (כתובות ק\"ה ע\"א). בימיו נחרב הבית (נזיר ל\"ב ע\"ב). לדעת חכמים טעה בהוראה (שם). ה\"יוחסין\" כתב: \"סתם נחום הוא נחום המדי\"."},{"i":2902,"n":"נחום הפיקולי","l":"נ","b":"מובא ב\"זוהר חדש\" (רות פ\"ב)."},{"i":2903,"n":"ר\u0027 נחום שמעיה דר\u0027 אבהו","l":"נ","b":"אמורא ארץ ישראלי בדור הרביעי. שמשו ותלמידו של רבי אבהו: \"מסתמיך ואזיל רבי אבהו, אכתפיה דר\u0027 נחום שמעיה\" (יבמות מ\"ב ע\"ב)."},{"i":2904,"n":"רב נחומאי","l":"נ","b":"ע\"ע רב נחומי."},{"i":2905,"n":"נחומאי בן אפקשיון","l":"נ","b":"תנא בדור השלישי - הרביעי. מובא בברייתא, נזכר אחר רבי ישמעאל ורבי עקיבא וחלק עליהם (יומא כ\"ח ע\"ב)."},{"i":2906,"n":"רב נחומי","l":"נ","b":"אמורא בבלי בדור הרביעי. הקשה לאביי: \"אמר ליה רב נחומאי, ואית דאמר רב חנניה בר מניומי, לאביי\" (ב\"ב קל\"א ע\"א), אבל אין ראיה שהיה תלמידו. מצינו: \"אמר רבי נחוניא שאילתינהו לכולהו טרופאי\" [מורי הוראות של טריפות] (חולין נ\"ה ע\"ב). \"דק\"ס\" כתב: ובכל כתבי היד רבי נחומי\". וכן מצינו: \"פליגי בה ר\u0027 נחומי ורבה\" (עירובין ע\"א ע\"ב), ושם גרס הרא\"ש: רחומי ולא נחומי."},{"i":2907,"n":"רב נחומי בר אדא","l":"נ","b":"מובא בבבלי (ביצה ל\"א ע\"ב), וגיר\u0027 \"סה\"ד\": רב נחמן בר אדא (כמו הגיר\u0027 עירובין ל\"ד ע\"ב)."},{"i":2908,"n":"רב נחומי בר זכריה","l":"נ","b":"אמורא בבלי בדור החמישי. תלמידו של אביי (ב\"ק כ\"ה ע\"ב). חברו של מר בריה דרבינא (שבת קל\"ו ע\"א). (בב\"ק כ\"ה ע\"ב. הגירסא נחמן וכתב \"סה\"ד\" נ\"ל שצ\"ל נחומי)."},{"i":2909,"n":"ר\u0027 נחומי בריה דר\u0027 חייא בר אבא","l":"נ","b":"אמורא ארץ ישראלי בדור הרביעי. בנו ותלמידו של ר\u0027 חייא בר אבא (ירו\u0027, דמאי פ\"א ה\"ב), ויש שהגיהו: ר\u0027 נחמיה בריה דר\u0027 חייא בר אבא (ירו\u0027, ברכות פ\"ג ה\"א)."},{"i":2910,"n":"ר\u0027 נחוניא","l":"נ","b":"מובא בבבלי: \"ר\u0027 נחוניא אמר מהכא\" (ב\"ק נ\u0027 ע\"א). ובאותו ענין מובא: \"ר\u0027 חנינא אמר מהכא\" (יבמות קכ\"א ע\"ב). ע\"ע רב נחומי."},{"i":2911,"n":"ר\u0027 נחוניא איש בקעת בית חורתן","l":"נ","b":"מובא בבבלי, שר\u0027 יוחנן אמר משמו (מו\"ק ג\u0027 ע\"ב), והוא רבי חוניא דברת חוורין (ירו\u0027, שביעית פ\"ו ה\"א). שמו שובש בכמה פנים, ו\"סה\"ד\" מביא ערך נפרד לר\u0027 נחוניא איש בקעת בית חורתן, בנוסף לערך רבי חוניא דמן חוורן. ה\"יוחסין\" מביא ערך נוסף: נחמיה איש בקעת בית חורתן: \"א\"ר יוחנן משום חוניא איש בקעת בית חורתן\" (סוכה מ\"ד ע\"א). לענ\"ד כולם אחד."},{"i":2912,"n":"רבי נחוניא בן אלינתן איש כפר הבבלי","l":"נ","b":"תנא בדור השני. העיד יחד עם רבי יהושע על אבר מן המת שהוא טמא, בניגוד לדעתו של רבי אליעזר (עדיות פ\"ו מ\"ב). ושנה במשנה (מ\"ב): \"רבי יהושע ורבי נחוניא מטהרים ורבי אליעזר מטמא\". וכן שם בענין אחר: \"רבי נחוניא מטמא ורבי אלעזר ורבי יהושע מטהרין\". נראה שצ\"ל: רבי נחוניא בן אלינתן."},{"i":2913,"n":"רבי נחוניא בן גודגדתא","l":"נ","b":"מובא במשנה (עדיות פ\"ז מ\"ט), ו\"סה\"ד\" כתב: \"עיין ר\u0027 יוחנן בן גודגדא\". נראה, ששני השמות הם של תנא אחד."},{"i":2914,"n":"רבי נחוניא בן הקנה","l":"נ","b":"תנא בדור השני. נראה, שהיה מתלמידיו של רבן יוחנן בן זכאי: ששאל רבן יוחנן בן זכאי לתלמידיו: מהו וכו\u0027, נענה רבי אליעזר וכו\u0027, נענה רבי יהושע וכו\u0027, נענה רבן גמליאל וכו\u0027, א\"ל רבן יוחנן בן זכאי לתלמידיו: \"נראין דברי נחוניא בן הקנה [כן גיר\u0027 \"דק\"ס\", ולפנינו: רבי נחוניא בן הקנא] מדברי ומדבריכם\" (ב\"ב י\u0027 ע\"ב). היה רבו המובהק של רבי ישמעאל (שבועות כ\"ו ע\"א). היה דורש את כל התורה כולה בכלל ופרט. (שם) זכה לאריכות ימים, ותלמידיו שאלוהו במה זכה, וענה להם: \"מימי לא נתכבדתי בקלון חברי, ולא עלתה על מטתי קללת חברי, וותרן בממוני הייתי\". \"יוחסין\" כתב שהוא כתב את \"ספר הבהיר\" על סודות הקבלה."},{"i":2915,"n":"רבי נחוניא הגדול","l":"נ","b":"תנא בדור השני. ומסופר שרבי עקיבא שאלו \"במה הארכת ימים?\" (מגילה כ\"ח ע\"א), שם מוכח לכאורה, שאין זה רבי נחוניא בן הקנה המובא באותו עמוד, ו\"סה\"ד\" חיברם לאחד."},{"i":2916,"n":"נחוניא חופר שיחין","l":"נ","b":"חסיד שהיה אחד מט\"ו הממונים במקדש, והיה ממונה לראות שיהיו מים מצויים לעולי רגל, והיה חופר שיחין ומערות (ירו\u0027, שקלים רפ\"ה). ופעם נפלה בתו לבור גדול, באו והודיעו לרבי חנינא בן דוסא, והוא אמר להם שתינצל (ב\"ק נ\u0027 ע\"א). בנו מת מצמא (שם), ש\"הקב\"ה מדקדק עם סביביו אפילו כחוט השערה\"."},{"i":2917,"n":"נחונייה בן יוסי בן פכסס","l":"נ","b":"מובא בירושלמי (נזיר רפ\"ז), ואין להכריע אם היה מן החכמים. \"סה\"ד\" מביאו בין החכמים."},{"i":2918,"n":"רבי נחמיה","l":"נ","b":"תנא בדור הרביעי. אחד משבעת תלמידיו הגדולים של רבי עקיבא, כמו שכתבו התוספות (יומא מ\u0027 ע\"ב ד\"ה: כיון) \"דר\u0027 יהודה ור\u0027 נחמיה נמי תלמידיו [של ר\"ע] כדאיתא בפ\u0027 הבא על יבמתו (יבמות ס\"ב ע\"ב)\", ולפנינו שם ליתא ר\u0027 נחמיה, אך כך היתה גיר\u0027 התוס\u0027. וכן מצינו (ב\"ר פס\"א - ג\u0027) שמחשיב את ר\u0027 נחמיה בן ז\u0027 תלמידיו של רבי עקיבא. ולפי דעתו של ר\u0027 אויא נסמך ר\u0027 נחמיה יחד עם תלמידיו של ר\"ע ע\"י ר\u0027 יהודה בן בבא (סנהדרין י\"ד ע\"א). וכן מצינו אותו בין תלמידיו של ר\"ע: \"ת\"ר, כשנכנסו רבותינו לכרם ביבנה, היה שם רבי יהודה ורבי יוסי ורבי נחמיה וכו\u0027\" (ברכות ס\"ג ע\"ב). וכן מצינו: \"סתם מתניתין רבי מאיר, סתם תוספתא רבי נחמיה\" (סנהדרין פ\"ו ע\"א). שם אביו לא מוזכר בשום מקום, אך נראה שהיה חכם, שמצינו: \"רבי נחמיה אומר משום אביו\" (פסחים נ\"ד ע\"א)."},{"i":2919,"n":"ר\u0027 נחמיה","l":"נ","b":"אמורא ארץ ישראלי בדור הרביעי. היה מחכמי האגדה. מסר משום רבי אבהו (ב\"ר פמ\"ג). כן מסר בשם רבי שמואל בר יצחק (מ\"ר פ\"ג - ב\u0027). היה חברם של ר\u0027 ברכיה, ר\u0027 עזריה ור\u0027 פנחס (שו\"ט כ\"ד - ה\u0027)."},{"i":2920,"n":"נחמיה איש בית דלי","l":"נ","b":"תנא בדור השני שירד לבבל. מובא בבבלי: \"אמר רבי עקיבא: כשירדתי לנהרדעא לעבר שנה, מצאתי נחמיה איש בית דלי ואמר לי וכו\u0027\" (יבמות קכ\"א ע\"א). וכן: \"העיד רבי עקיבא משמו שמשיאין האשה וכו\u0027\" (עדיות פ\"ח מ\"ה)."},{"i":2921,"n":"ר\u0027 נחמיה איש בקעת חורתן","l":"נ","b":"ע\"ע רבי חוניה דברת חוורין."},{"i":2922,"n":"ר\u0027 נחמיה איש כפר סיחון","l":"נ","b":"אמורא ארץ ישראלי בדור החמישי. מחכמי האגדה. חברו של ר\u0027 עזריה וחלק עמו (ב\"ר פי\"ב - ה\u0027)."},{"i":2923,"n":"נחמיה איש שיחין","l":"נ","b":"תנא בדור השלישי - הרביעי. מובא בירושלמי: אמר רבי יהודה: \"העיד נחמיה איש שיחון משום רבי עקיבא\" (סוטה פ\"ב ה\"ה). ובמקום אחר שובשה הגירסא ל\"נחמיה חופר שיחין\" (סוטה י\"ח ע\"ב). מסופר עליו, שעני אחד ביקשו ליתן לו תרנגולת, ונתן לו מעות שיקנה בשר ואכל ומת, ואמר: \"ספדי להרוגי נחמיה\" (ירו\u0027, סוף פאה)."},{"i":2924,"n":"ר\u0027 נחמיה בן אלעזר","l":"נ","b":"מובא באיכ\"ר (פ\"ב - ג\u0027): \"ר\u0027 ברכיה ואמרי לה ר\u0027 נחמיה בן אלעזר\"."},{"i":2925,"n":"נחמיה בר ברוך","l":"נ","b":"מובא בבבלי (מו\"ק ט\"ז ע\"א), ואולי הוא ר\u0027 נחמן בר ברוך."},{"i":2926,"n":"ר\u0027 נחמיה בר חנינא","l":"נ","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. חברו של ר\u0027 יצחק בר חייא (מד\u0027 תהלים הישן פע\"ה)."},{"i":2927,"n":"ר\u0027 נחמיה בר מר עוקבן בריה דר\u0027 יוסי","l":"נ","b":"אמורא ארץ ישראלי. מובא בירושלמי (יבמות י\"ד ע\"א)."},{"i":2928,"n":"ר\u0027 נחמיה בר עוקבן","l":"נ","b":"אמורא ארץ ישראלי. מובא בירושלמי (פאה פ\"א ה\"ה)."},{"i":2929,"n":"רב נחמיה בריה דרב הונא בר חנילאי","l":"נ","b":"כן גיר\u0027 הרי\"ף והרא\"ש, אך לפנינו: ר\u0027 נחמיה בריה דר\u0027 חנילאי (עירובין י\"ג ע\"ב)."},{"i":2930,"n":"רב נחמיה בריה דרב חנילאי","l":"נ","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב נחמן: \"א\"ל רב חסדא לרב נחמן: \u0027נחמיה תלמידך שרוי בצער\u0027\" (עירובין מ\"ג ע\"ב)."},{"i":2931,"n":"רב נחמיה בריה דרב יוסף","l":"נ","b":"אמורא בבלי בדור החמישי. תלמידו המובהק של רבא: \"אמר הוה קאימנא קמיה דרבא וכו\u0027\" (ביצה כ\"ח ע\"א), לפי גירסת \"סה\"ד\" ו\"דק\"ס\" היה חברם של רב פפא ור\u0027 פפי (מו\"ק י\"ט ע\"ב) שאמר: \"אשכחתינהו דיתבי וקא אמרי\". היה הריש בעירו (כתובות ס\"ה ע\"א)."},{"i":2932,"n":"ר\u0027 נחמיה בריה דר\u0027 חייא בר אבא (2)","l":"נ","b":"מובא בירושלמי (ברכות פ\"ג ה\"א), ונראה שהוא ר\u0027 נחומי בריה דר\u0027 חייא בר אבא."},{"i":2933,"n":"רב נחמיה בריה דר\u0027 יהושע","l":"נ","b":"אמורא בבלי בדור החמישי. מובא בבבלי, שאמר: \"אשכחתינהו לרב פפי ולרב פפא דיתבי וקאמרי וכו\u0027\" (מו\"ק י\"ט ע\"ב), אבל גיר\u0027 \"דק\"ס\": רב נחמיה בריה דרב יוסף, וכן גרס \"סה\"ד\"."},{"i":2934,"n":"ר\u0027 נחמיה דיפו","l":"נ","b":"אמורא ארץ ישראלי. מובא (פדר\"כ קע\"ג). יתכן שהוא ר\u0027 נחמן דיפו."},{"i":2935,"n":"נחמיה חתניה דבי נשיאה","l":"נ","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידם של ר\u0027 אמי ור\u0027 אסי כמובא בבבלי, שאמר \"אנא חזיתיה לר\u0027 אמי ור\u0027 אסי דמטי וכו\u0027\" (יומא ע\"ח ע\"א)."},{"i":2936,"n":"רב נחמן","l":"נ","b":"אמורא בבלי בדור השני - השלישי, והוא רב נחמן בר יעקב סתם בש\"ס (ב\"ב מ\"ו ע\"ב תד\"ה: שלח). אביו רבי יעקב היה מסופרי הדיינים בבית דינו של שמואל בנהרדעא (ב\"מ ט\"ז ע\"ב) רב נחמן מסר בשם אביו (ביצה כ\"ו ע\"ב), רבו המובהק היה רבה בר אבהו: \"והאמר רב נחמן: \u0027כי הוינן בי רבה בר אבהו\u0027\" (ברכות כ\"א ע\"א), וכן: \"אף לדידי קשיא לי, ושאלתיה לרבה בר אבהו\" (ע\"ז נ\"א ע\"א). נראה, שרב נחמן היה לחתנו של רבה בר אבהו (יבמות פ\u0027 ע\"ב), קיבל תורה גם משמואל (ברכות כ\"ז ע\"ב), ואף מצינו: \"דרש רב נחמן משום רבינו שמואל\" (עירובין ט\"ז ע\"ב). היה גם תלמידו של רב, כמו שרש\"י כתב במפורש (ביצה כ\"ה ע\"א ד\"ה: מדברי). שלח לשאול מחכמי ארץ ישראל (ביצה כ\"ה ע\"ב). רב יהודה היה גדול ממנו (קידושין ע\u0027 ע\"א רש\"י ד\"ה: לא מיבעי). בין תלמידיו הרבים היו רבה (יבמות ס\"ו ע\"ב), רב יוסף (ב\"ק קט\"ז ע\"ב) ורבי אבא (עירובין ע\"ו ע\"ב). רב נחמן היה הראש בנהרדעא (קידושין שם). היה מומחה גדול לדיני ממונות, ואמר לרב ששת: \"אנא דיינא, ומר לאו דיינא\" (כתובות צ\"ד ע\"ב). רב נחמן אמר: ד\"כולי עלמא לגבי דידי בדינא דרדקי [תינוקות] נינהו\" (ב\"מ ס\"ו ע\"א), ואכן נקבע הכלל: \"דקיימא לן הלכתא כרב נחמן בדיני\" (כתובות י\"ג ע\"א) שם אשתו היה ילתא (ברכות נ\"א ע\"ב) היו לו כמה בנים חכמים, הון (יבמות ל\"ד ע\"ב), הונא (הוריות, י\"ב ע\"ב), מר זוטרא (ב\"ב קנ\"א ע\"ב), רב פפא (ב\"מ קי\"ג ע\"א) ורבה (חולין קי\"א ע\"א). היתה לו בת ושמה דונג (קידושין ע\u0027 ע\"א). שתי בנותיו נשבו (גיטין מ\"ה ע\"א). על פטירתו מובא שרבא היה לידו בזמן שנפטר (מו\"ק כ\"ח ע\"א)."},{"i":2937,"n":"רבי נחמן","l":"נ","b":"אמורא ארץ ישראלי בדור הששי. מסר משמו של רבי מנא (ירו\u0027, ברכות פ\"א ה\"א). מסר גם בשם רבי אחא (איכ\"ר פתיחתא ה\u0027)."},{"i":2938,"n":"ר\u0027 נחמן","l":"נ","b":"פעמים, הכונה לר\u0027 נחמני."},{"i":2939,"n":"רב נחמן בר אבא","l":"נ","b":"מובא בבבלי (ע\"ז ל\"ט ע\"א), אבל גירסת הר\"י, והרא\"ש: רב נחמן בר רבא."},{"i":2940,"n":"רב נחמן בר אדא","l":"נ","b":"אמורא בבלי בדור השני. תלמידו של שמואל (עירובין ל\"ד ע\"ב). והגירסא במקום אחר: רב נחומי בר אדא (ביצה ל\"א ע\"ב), אך \"סה\"ד\" גורס בשניהם: רב נחמן בר אדא, וכולם אחד."},{"i":2941,"n":"רב נחמן בר אושעיא","l":"נ","b":"אמורא ארץ ישראלי בדור השלישי. מובא בבבלי: \"רב נחמן בר אושעיא אמר רבי יוחנן\" (שבת ס\"ה ע\"א), וגירסת הרי\"ף: ר\u0027 נתן בר אושעיא. כן כתב \"סה\"ד\", שרב נחמן בר אושעיא ט\"ס היא, וצ\"ל: ר\u0027 נתן בר אושעיא."},{"i":2942,"n":"רב נחמן בר אושפזתי","l":"נ","b":"אמורא בבלי בדור החמישי. מסופר, שרב פפא גזר תעניתא, חלש ליביה וטעם מידי, בעא רחמי ולא בא גשם: \"א\"ל רב נחמן בר אושפזתי וכו\u0027\" (תענית כ\"ד ע\"ב), וה\"ערוך\" גרס: \"א\"ל רב נחמן בר אושפרתי וכו\u0027\", כלומר, רב נחמן אמר לרב פפא: \"בר אושפרתי\" (בנו של אושפרתי; וסובר הערוך ששם אמו של רב פפא היה אושפרתי); א\"כ, לפי גירסת ה\"ערוך\" לא היה כלל חכם ושמו רב נחמן בר אושפזתי."},{"i":2943,"n":"רב נחמן בר אמי","l":"נ","b":"לפי גירסת ה\"ערוך\" (במו\"ק כ\"ב ע\"ב, ערך אסיתא) היה אמורא בבלי בדור השני - השלישי. ה\"ערוך\" גרס: א\"ל רב חסדא לרב נחמן בר אמי. ועוד מצינו: \"אמר רב נחמן בר אמי משמיה דאולפנא\" (עירובין ס\"ז ע\"א) ופרש\"י: ששמע מרבו ורבו מרבו."},{"i":2944,"n":"רב נחמן בר ברוך","l":"נ","b":"אמורא שאין לנו פרטים עליו. מובא בבבלי: \"אמר אדא מרי, אר\"נ בר ברוך\" (שבת ס\"ו ע\"ב), ואולי הוא נחמיה בר ברוך."},{"i":2945,"n":"רב נחמן בר זכריה","l":"נ","b":"מובא בבבלי (ב\"ק כ\"ה ע\"ב). לפי \"סה\"ד\" צריך לגרוס: רב נחומי בר זכריה."},{"i":2946,"n":"רב נחמן בר חנין","l":"נ","b":"מובא בב\"ר (פמ\"א - ז\u0027)."},{"i":2947,"n":"רב נחמן בר יהודה","l":"נ","b":"אמורא ארץ ישראלי בדור השני - השלישי. מובא בירושלמי: \"ר\u0027 יעקב בר אחא ור\"ז וכו\u0027 חד אמר בשם מר עוקבן וחד בשם ר\"נ בר יהודה\" (עירובין פ\"ו ה\"ח)."},{"i":2948,"n":"רב נחמן בר יעקב","l":"נ","b":"ע\"ע רב נחמן."},{"i":2949,"n":"רב נחמן בר יצחק","l":"נ","b":"אמורא בבלי בדור הרביעי - החמישי. מלך בפומבדיתא אחר פטירתו של רבא בשנים ד\u0027 קי\"א - קט\"ו (153 - 653) (\"אגרת רב שרירא גאון\"). היה מתלמידי רב חסדא (ע\"ז ס\"ג ע\"א). ישב מאחורי רבא לפני רב נחמן, וכשלא הבין את אשר רמז רב נחמן, שאל לרבא (ב\"ב קנ\"ב ע\"א). לפי פירוש התוספות היה תלמידו של רבא (שם מ\"ו ע\"ב תד\"ה: שלח). היה ריש כלה (שם כ\"ז ע\"א). בין תלמידיו היו רב הונא בריה דרב נחמן (פסחים מ\"ו ע\"ב), וכן רב אשי לפי גירסת התוספות (ב\"ב מ\"ו ע\"ב ד\"ה: שלח). לפי פירושו של רש\"י (תענית כ\"א ע\"ב ד\"ה: פרס), אביו של רב נחמן בר יצחק לא נסמך. חוזי הכוכבים ניבאו לאמו, שרב נחמן בר יצחק יהיה גנב, לכן הקפידה אמו לחנכו ליראת שמים והיתה אומרת לו תדיר שיכסה ראשו ויבקש רחמים. יום אחד ישב תחת צל אילן, ונפל כיסוי ראשו מעליו, ויצרו גבר עליו וחתך בשיניו אשכול תמרים מהאילן, שלא היה שייך לו (שבת קנ\"ו ע\"ב). היה ירא שמים גדול, עד שאמר אביי לרב יוסף: \"הא רב נחמן בר יצחק מרי דעובדא\" (שבת ל\"ז ע\"ב), ופירש\"י: \"מדקדק במעשיו\". נמנה עם חסידי בבל (מגילה כ\"ח ע\"ב רש\"י)."},{"i":2950,"n":"רב נחמן בר כהן","l":"נ","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בבבלי: \"כי אתא רב דימי אמר: דרש רב נחמן בר כהן מאי דכתיב וכו\u0027\" (סנהדרין ז\u0027 ע\"ב)."},{"i":2951,"n":"רב נחמן בר נתן","l":"נ","b":"מובא בבבלי (ב\"ב ח\u0027 ע\"ב) לפי גירסת הרא\"ש. ולפנינו: רב נחמן סתם."},{"i":2952,"n":"רב נחמן בר פפא","l":"נ","b":"אמורא בבלי בדור הרביעי. מצינו אותו מתיב על דברי רפרם בר פפא, שהיה תלמידו של רב חסדא (ב\"מ פ\u0027 ע\"ב). היה חסיד גדול, וכשביקש גשם נענה משמים וירד גשם לגינתו (חולין ס\u0027 ע\"ב)."},{"i":2953,"n":"ר\u0027 נחמן בר פרנק","l":"נ","b":"ע\"ע רבי נחום בר פפא."},{"i":2954,"n":"רב נחמן בר רב הונא","l":"נ","b":"אמורא בבלי בדור השביעי. עמד בראש ישיבת סורא אחרי רב אידי בר אבין במשך שלוש שנים, משנת דרי\"א עד דרי\"ד (154 - 454) ואז נפל שמדא, שגזר יזדגרד מלך פרס לחלל שבת\" (\"אגרת רב שרירא גאון\"). אחריו מלך מר בר רב אשי."},{"i":2955,"n":"רב נחמן בר רב זבדא","l":"נ","b":"מובא בבבלי: \"דאמר רב נחמן בר רב זבדא ואמרי לה אמר רב נחמן בר רבא אמר רב\" (שבת כ\"ה ע\"ב)."},{"i":2956,"n":"רב נחמן בר רב חסדא","l":"נ","b":"אמורא בבלי בדור הרביעי. בנו ותלמידו של האמורא המפורסם רב חסדא (שבת קמ\"ז ע\"א). ואף ששלח לרב נחמן: \"ילמדנו רבנו\" (ב\"ב מ\"ו ע\"ב), לא מצינו שרב נחמן בר רב חסדא למד לפני רב נחמן. כן שלח לרבה: \"ילמדנו רבנו\" (גיטין פ\u0027 ע\"ב), ולא מצינו שהיה תלמידו של רבה. חברו היה רב נחמן בר יצחק (תענית כ\"א ע\"ב). נראה, שהיה הריש בעיר דרוקרת (שם)."},{"i":2957,"n":"רב נחמן בר רבא","l":"נ","b":"אמורא בבלי בדור השני. תלמידו של רב (שבת כ\"ה ע\"ב). סביר לומר, שהוא, רב נחמן בר אבא אמר רב\", המובא בבבלי (ע\"ז ל\"ט ע\"א)."},{"i":2958,"n":"רבי נחמן בר שמואל בר נחמן","l":"נ","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. בנו ותלמידו של רבי שמואל בר נחמן (ירו\u0027, שבת פ\"א ה\"ד). נתפס לעבודת המלך ובא לפני רבי אמי (ירו\u0027, ב\"ב פ\"ט ה\"ד). כשרבי חלבו אמר לו שישב פעמים רבות לפני אביו רבי שמואל בר נחמן, ולא שמע מה שר\u0027 נחמן אמר, השיב לו רבי נחמן: \"כל מה דהוה אבא שמיע את שמיע\". נראה, שרבי תנחומא היה תלמידו (קה\"ר פ\"ב - כ\"ד)."},{"i":2959,"n":"רב נחמן ברב גוריא","l":"נ","b":"אמורא בבלי שאיקלע לנהרדעא ושאלו ממנו ולא השיב נכון, אמרו ליה: \"רבך קטיל קני באגמא היה\" (שבת צ\"ה ע\"א), ופרש\"י: \"חותך קנים מן האגם הוה לא ידע לפרש משנה\". \"דק\"ס\" גורס: רב חמא בר גוריא."},{"i":2960,"n":"רב נחמן בריה דרב איקא","l":"נ","b":"מובא בבבלי (מכות כ\"א ע\"א), ו\"סה\"ד\" וכתב ט\"ס. וכתב \"משה\"ס\": \"בכל המקומות איתא ר\u0027 חנינא\" ו\"סה\"ד\" גרס: רב חיננא בריה דרב איקא."},{"i":2961,"n":"רב נחמן בריה דרב יוסף","l":"נ","b":"מובא בבבלי (בכורות י\"א ע\"א), וגירסת \"סה\"ד\": רב נחמיה בריה דרב יוסף."},{"i":2962,"n":"ר\u0027 נחמן דיפו","l":"נ","b":"אמורא ארץ ישראלי בדור החמישי. מסר בשם ר\u0027 יעקב דקיסרין (ב\"ר פנ\"ג - ד\u0027), ובשם ר\u0027 פנחס (תנחומא אחרי - ח\u0027)."},{"i":2963,"n":"נחמן העמסוני","l":"נ","b":"תנא בדור הרביעי. תלמידו המובהק של רבי עקיבא. שימש את רבי עקיבא עשרים ושתיים שנה, ולמדו אתים וגמים, ריבויין, אכין ורקין, ומיעוטין (ירו\u0027, ברכות פ\"ט ה\"ה)."},{"i":2964,"n":"רב נחמן מנהרדעא","l":"נ","b":"אמורא בבלי בדור החמישי. מובא בבבלי, שאיקלע לרב כהנא לפום נהרא בערב יום הכפורים (חולין צ\"ה ע\"ב)."},{"i":2965,"n":"רב נחמן מפרהטיא","l":"נ","b":"אמורא בבלי בדור השביעי. תלמידו של רב אשי (קידושין פ\"א ע\"א)."},{"i":2966,"n":"נחמן סבא","l":"נ","b":"אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. מובא בירושלמי: \"רבי יוסי [חברו של רבי יונה, אמורא ארץ ישראלי בדור החמישי] אומר: תנא נחמן סבא וכו\u0027\" (ברכות פ\"ב ה\"ד)."},{"i":2967,"n":"נחמני (2)","l":"נ","b":"אביהם של ארבעה אחים חכמים: רבה בר נחמני, שהוא סתם רבה בש\"ס (גיטין ל\"ד ע\"ב רש\"י ד\"ה: והלכתא כנחמני); כייליל אבי אביי (זבחים קי\"ח ע\"ב רש\"י ד\"ה: חד ברא); רב (לא רבי!) חנניה; רב (לא רבי!) אושעיא (סנהדרין י\"ד ע\"א מהרש\"א)."},{"i":2968,"n":"ר\u0027 נחשון","l":"נ","b":"מובא ב\"ילקוט\" (תהלים רמז תשנ\"ב)."},{"i":2969,"n":"ניולי","l":"נ","b":"אמורא בבלי בדור השלישי. תלמידו של רב הונא: \"ת\"ש, דאמר ניולי אמר רב הונא\" (חולין מ\"ה ע\"ב), ופרש\"י: \"ניולי שם חכם\"."},{"i":2970,"n":"ניותי","l":"נ","b":"מובא בבבלי: \"אמר רבי אבא בר כהנא: פעם אחת נפל [בשבת] אחד [נחש] בבית המדרש, ועמד ניותי אחד והרגו\" (שבת קכ\"א ע\"ב), ופרש\"י: \"ניותי על שם מקומו, וישראל היה\", ואמנם אין להוכיח שהיה חכם, אך מסתבר כך, שכן היה בבית המדרש ונראה שם שהיה מלומדי הישיבה, ולאחר שהרג לנחש: \"אמר רבי: \u0027פגע בו כיוצא בו\u0027\" ופרש\"י: \"ולא לגנאי אמר רבי\", וזה שרש\"י אומר: \"ישראל היה\" ולא כתב: \"חכם\", אינו אומר ולא כלום, שכן כך דרכו של רש\"י, ומצינו הרבה בש\"ס שכך פירש. \"יוחסין\" ו\"סה\"ד\" מביאים אותו בין החכמים."},{"i":2971,"n":"ר\u0027 ניחא בר סבא","l":"נ","b":"אמורא ארץ ישראלי בדור הששי. תלמידו של רבי יונה: \"בעי קומי ר\u0027 יונה\" (ירו\u0027, יבמות רפ\"ט)."},{"i":2972,"n":"נימוס אחי רבי יהושע הגרסי","l":"נ","b":"תנא בדור הרביעי. מובא בבבלי: \"אמר רבי יוסי [תלמידו של רבי עקיבא]: \u0027סח לי נימוס, אחיו של רבי יהושע הגרסי, [תלמידו ומשרתו של ר\"ע (עירובין כ\"א ע\"ב)] שהשוחט את העורב להתלמד בו דמו מכשיר רבי אליעזר אומר וכו\u0027\" (בכורות י\u0027 ע\"ב)."},{"i":2973,"n":"נימוס הגרדי","l":"נ","b":"מובא בבבלי (חגיגה ט\"ו ע\"ב). ע\"ע אבנימוס הגרדי (פילוסוף נכרי)."},{"i":2974,"n":"ניפטיים הגר","l":"נ","b":"גר שחי בארץ ישראל בדור הרביעי לתנאים. מובא בבבלי: \"ת\"ש דא\"ר יוסי [תלמידו של ר\"ע]: מעשה בניפטיים הגר שנשא אשת אחיו מאמו, ובא מעשה לפני חכמים ואמרו וכו\u0027\" (יבמות צ\"ח ע\"א), ואין ראיה שנמנה עם החכמים. ואולי קצת ראיה יש שהיה חכם, כי שם באותו עמוד מובא מעשה בגר אחר והוא לא מוזכר בשמו, אך אין זו ראיה ברורה כלל."},{"i":2975,"n":"ניקומכי","l":"נ","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי זעירא: \"תני קומי ר\u0027 זעירא\" (ירו\u0027, סנהדרין פ\"ו ה\"ט)."},{"i":2976,"n":"נירון קיסר","l":"נ","b":"שר צבא רומי שהתגייר, והיה אביו של רבי מאיר (גיטין נ\"ו ע\"א)."},{"i":2977,"n":"רב ניתאי","l":"נ","b":"אמורא בבלי בדור השני. תלמידו של שמואל: \"רב נתאי סבר למעבד עובדא כרבי זכריה בן הקצב [התנא] א\"ל שמואל: \u0027אפס זכריה\u0027\" (ב\"ב קי\"א ע\"א), כלומר, אין הלכה כזכריה בן הקצב."},{"i":2978,"n":"ניתאי איש תקוע","l":"נ","b":"מובא במשנה: \"נתאי איש תקוע הביא חלות מביתר, ולא קבלו ממנו\" (חלה פ\"ד מ\"י). כן מובא בירושלמי: \"ניתאי איש תקוע הביא חלות מבייתות, ולא קבלו מממנו\" (חלה פ\"ד ה\"ה), ואין ראיה שנמנה עם החכמים. \"יוחסין\" כתב: \"היות והיה מן החסידים לכן הזכיר שמו\"."},{"i":2979,"n":"ניתאי הארבלי","l":"נ","b":"חכם קדמון מחכמי ה\"זוגות\". עמד בראש העם בימי החשמונאים. שימש כאב בית דין תחת נשיאותו של יהושע בן פרחיה (חגיגה ט\"ז ע\"ב), ושניהם היו הזוג השני מחמשת ה\"זוגות\" בימי בית שני - קיבלו תורתם מיוסי בן יועזר איש צרידה ויוסי בן יוחנן איש ירושלים (אבות פ\"א מ\"ו). פתגמו היה: \"הרחק משכן רע, ואל תתחבר לרשע, ואל תתייאש מן הפורענות\" (אבות שם מ\"ז)."},{"i":2980,"n":"רבי נסא","l":"נ","b":"אמורא ארץ ישראלי בדור הרביעי. מסר משמו של רבי אלעזר (ירו\u0027, שביעית פ\"ד ה\"ב) ורבי יוסי בר חנינא (ירו\u0027, ב\"מ רפ\"ג). חברו של ר\u0027 יונה (ירו\u0027, עירובין פ\"ב ה\"א; ב\"מ רפ\"ג). ר\u0027 רדיפא מסר משמו (ירו\u0027, עירובין ספ\"ק). נפטר בגיל צעיר ולא הכיר את אביו שהיה חכם (ירו\u0027, סוף תרומות)."},{"i":2981,"n":"ר\u0027 נסא דקסרין","l":"נ","b":"מובא באיכ\"ר (בפתיחתא - כ\"ו)."},{"i":2982,"n":"ר\u0027 נסים","l":"נ","b":"מובא בש\"ר (פט\"ו - י\"ט). ואולי יש ט\"ס בשם. \"סה\"ד\" לא הביאו."},{"i":2983,"n":"ר\u0027 נפתלי","l":"נ","b":"חי בארץ ישראל בדור הששי לאמוראים. היות ומכונה \"ר\u0027\", נראה שנמנה עם החכמים. היה כהן, והיתה לו אצבע עקומה וכו\u0027 ושאל לרבינא אם מותר לו לעלות לדוכן, ור\u0027 מנא ענה לו מכיון שאתה \"דש בעירך\" (בני העיר הורגלו לראותך בכך) - מותר."},{"i":2984,"n":"נקדימון בן גוריון","l":"נ","b":"חסיד גדול. חי בירושלים בזמן בית המקדש. שמו היה: \"בוני\", ולמה נקרא שמו נקדימון? ש\"קדרה חמה עבורו\", שהקב\"ה עשה לו נס כפול: בראשונה התפלל לה\u0027 שירדו גשמים, וירדו, והוסיף לבקש מה\u0027 שהשמש תזרח, וזרחה (תענית י\"ט ע\"ב). היה משלושת עשירי ירושלים, וקיבל על עצמו לזון ולכלכל את כל בני העיר במשך עשרים ואחת שנה (גיטין נ\"ו ע\"א). נראה, שהיה מן החכמים (כתובות ס\"ו ע\"ב). \"סה\"ד\" לא הביא את שמו."},{"i":2985,"n":"נקיי","l":"נ","b":"כך שמו. חי בזמן הבית. נראה שלא היה מן החכמים. מובא בירושלמי (מע\"ש פ\"ה ה\"ב). \"פני משה\" פירש: \"כך שמו והיה שמש [במקום שמו] מגדלא דצבעייא\". פירוש שני, שהיה סופר מלמד תינוקות."},{"i":2986,"n":"רב נתן","l":"נ","b":"אמורא בבלי בדור הששי. מושבו היה בהגרוניא. מובא בבבלי: \"ריש גלותא איקלע להגרוניא לבי רב נתן רפרם וכולהו רבנן אתו לפירקא, רבינא לא אתא\" (יומא ע\"ח ע\"א)."},{"i":2987,"n":"רבי נתן","l":"נ","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי: \"אמר רבי נתן טעמא דנתן בר הושעיה\" (תרומות פ\"ז ה\"א)."},{"i":2988,"n":"רב נתן אבוה דרב הונא בריה דרב נתן","l":"נ","b":"אמורא בבלי בדור החמישי. מובא בבבלי (פסחים מ\"ג ע\"ב; זבחים ע\u0027 ע\"ב). נקרא על שם בנו, אולי מפני שבנו היה ראש גולה (סמוך לאחר רב אשי) והיו בו (בבנו זה) תורה וגדולה במקום אחד, שלא היה מימי רבי (גיטין נ\"ט ע\"א). היה תלמידו של רב פפא, ואמר הקידוש לפני רב פפא [כסבי דפומבדיתא] ושבחיה רב פפא (פסחים קי\"ז ע\"ב)."},{"i":2989,"n":"רבי נתן ביראה","l":"נ","b":"מובא בבבלי (כתובות ע\"ה ע\"א). בברייתא ששנה שקלו וטרו רב אשי ורב אחא בריה דרבא (שם)."},{"i":2990,"n":"רבי נתן בן אבטולמיס","l":"נ","b":"תנא שאין לקבוע זמנו המדוייק. מובא בבבלי (זבחים מ\"ט ע\"ב), והגיר\u0027 במקום אחר: רבי יונתן בן אבטולמיס (נדה י\"ט ע\"א)."},{"i":2991,"n":"ר\u0027 נתן בן אלעזר","l":"נ","b":"אמורא ארץ ישראלי בדור החמישי. מובא בתנחומא (בראשית י\u0027) ששאל לר\u0027 שמואל."},{"i":2992,"n":"רבי נתן בן עמרם","l":"נ","b":"מובא בבבלי (ע\"ז ל\"ו ע\"ב), וצ\"ל: רבי יונתן בן עמרם."},{"i":2993,"n":"רב נתן בר אבא א\u0027","l":"נ","b":"אמורא בבלי בדור השני. תלמיד של רב: \"תרגמא רב נתן בר אבא קמיה דרב\" (ב\"מ מ\"א ע\"א), וכן היה תלמידו של שמואל. מסופר, שאמר לפני שמואל שיודע להבדיל בין עוברי דגים טמאים לטהורים, וטעה ואמר על טהור טמא, ושמואל הקפיד על כך, ואמר לו: אין אתה מתבייש לומר על טהור טמא, סופך לומר על טמא טהור (ירו\u0027, ע\"ז ספ\"ב)."},{"i":2994,"n":"רבי נתן בר אבא ב\u0027","l":"נ","b":"אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי, שבא לבקר את רבי שמואל בר אבא באבלו (מו\"ק פ\"ג ה\"א), וכן בא רבי אלעזר (שם)."},{"i":2995,"n":"רב נתן בר אביי","l":"נ","b":"אמורא בבלי בדור השלישי. מובא בבבלי (חולין צ\"ה ע\"ב) שבא לפני רב חסדא, ורב חסדא החזיר לו אבידה לפי טביעת עין, מבלי שהיה לו סימן. \"סה\"ד\" מפקפק אם צריך לגרוס: רב נתן בר אדא או רב נתן בר אבין."},{"i":2996,"n":"רב נתן בר אבין","l":"נ","b":"אמורא בבלי בדור השני. תלמידו של רב ויתיב לפניו ובדק בטרפות (חולין מ\"ה ע\"ב). גיר\u0027 \"דק\"ס\": רב נתן בר אבא, ואם נגרוס כך, הרי לא קיים חכם בשם רב נתן בר אבין, שכן שוב לא נזכר בש\"ס."},{"i":2997,"n":"רבי נתן בר אבישלום","l":"נ","b":"תנא דברייתא. מובא במחלוקת עם תלמידיו של רבי עקיבא - רבי יוסי, רבי יוחנן הסנדלר ורבי יהודה (ברכות כ\"ב ע\"א). סביר לומר, שחי בדור הרביעי לתנאים."},{"i":2998,"n":"רב נתן בר אושעיא","l":"נ","b":"אמורא בבלי בדור השני - השלישי. עלה לארץ ישראל וישב לפני רבי יוחנן (ירו\u0027, ב\"ב רפ\"ט). בר פלוגתיה דרב יהודה (קידושין ל\"ב ע\"א) ושל רב חסדא (חולין קל\"ח ע\"א). אביי תירץ קושייתו (גיטין י\"ח ע\"א)."},{"i":2999,"n":"ר\u0027 נתן בר אמי","l":"נ","b":"אמורא בבלי בדור החמישי. ממקורבי תלמידיו של רבא (שבת ק\"נ ע\"ב). רבא לימדו דרכי חיים וחינוך בנים (קידושין ל\u0027 ע\"א) היה עשיר גדול. רבא לקח ממנו ד\u0027 מאות זוזי לצדקה (ב\"ב ח\u0027 ע\"ב)."},{"i":3000,"n":"רב נתן בר אסיא","l":"נ","b":"אמורא בבלי בדור הרביעי. מובא בבבלי, שהלך מבי רב לפומבדיתא ביו\"ט שני של עצרת, ושמתיה רב יוסף (פסחים נ\"ב ע\"א)."},{"i":3001,"n":"ר\u0027 נתן בר טובי","l":"נ","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (ברכות כ\"ח ע\"א). ר\"ז ישב ליד פתח בית המדרש, ור\u0027 נתן בר טובי מסר לו דין ששמע בבית המדרש מרבי יוחנן, ור\"ז שיננו 04 פעם (שם). וטעות ב\"סה\"ד\", שכתב שרבי נתן בר טובי קיבל מר\"ז."},{"i":3002,"n":"ר\u0027 נתן בר יוסף","l":"נ","b":"מובא בבבלי (מגילה ל\"א ע\"ב), והוא ר\u0027 יונתן התנא."},{"i":3003,"n":"רב נתן בר מניומי","l":"נ","b":"אמורא בבלי בדור הרביעי - חמישי. רב כהנא מסר משמו שתי דרשות שמסר בשם ר\u0027 תנחום (שבת כ\"א ע\"ב)."},{"i":3004,"n":"נתן בר מר זוטרא","l":"נ","b":"אמורא בבלי בדור השביעי. בנו של מר זוטרא. נראה, שהיה כחבר לרב אשי בישיבתו: \"אמר רב אשי: \u0027אמר לי נתן בר מר זוטרא\u0027\" (סנהדרין כ\"ט ע\"א). גם אחיו הונא היה חכם, תלמיד של רבינא (ב\"ב פ\"ו ע\"א)."},{"i":3005,"n":"רב נתן בר מר עוקבא","l":"נ","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב יהודה (ברכות י\"ג ע\"ב)."},{"i":3006,"n":"נתן בר שילא","l":"נ","b":"ראש טבחי צפורי בזמנו של רבי. העיד לפני רבי משום רבי נתן: \"איזו כרס הפנימית וכו\u0027\" (חולין נ\u0027 ע\"ב). ואין ראיה שהיה חכם, גם אם העיד לפני רבי משמו של רבי נתן. \"יוחסין\" ו\"סה\"ד\" הביאוהו בין החכמים."},{"i":3007,"n":"ר\u0027 נתן בריבי","l":"נ","b":"כך מביא \"סה\"ד\" הגיר\u0027 בספרי (פ\u0027 ואתחנן)."},{"i":3008,"n":"ר\u0027 נתן בריה דר\u0027 ברכיה","l":"נ","b":"אמורא ארץ ישראלי בדור החמישי. יחד עם ר\u0027 ישמעאל בר תנחום מסר משום רבי ירמיה (ילקוט קהלת פ\"ה פסוק ויתרון)."},{"i":3009,"n":"ר\u0027 נתן דבית גוברין","l":"נ","b":"מובא בקהלת רבה (פסוק עת ללדת). \"סה\"ד\" כתב: \"ט\"ס וצ\"ל: ר\u0027 יונתן דבית גוברין\"."},{"i":3010,"n":"נתן דצוציתא","l":"נ","b":"הוא עוקבן בר נחמיה, ראש גלותא בבבל בדור השלישי לאמוראים. היה בעל תשובה גדול, ועל כינויו \"נתן דציצותא\" כתב רש\"י: על שם ניצוצין דנורא, שהמלאך פשט ידו וקבל תשובתו (שבת נ\"ו ע\"ב ד\"ה: נתן). תוספות כתבו שם, שהיה נר דלוק על ראשו, ועל כן קראו לו ר\u0027 נתן ציציתא."},{"i":3011,"n":"ר\u0027 נתן דרומה","l":"נ","b":"מובא בירושלמי שרבי חנינא ורבי יונתן שאלו ממנו (עירובין פ\"ו ה\"ד). יתכן שיש ט\"ס בשם."},{"i":3012,"n":"רבי נתן הבבלי","l":"נ","b":"תנא בבלי בדור הרביעי, שעלה לארץ ישראל (גיטין ס\"ה ע\"ב רש\"י ד\"ה: רבי נתן דבבלאה הוא). כשבא לא\"י, מינה אותו רבן שמעון בן גמליאל (אבי רבי) ל\"חכם\", דהיינו אב\"ד (ב\"מ קי\"ז ע\"ב רש\"י). אביו היה ריש גלותא בבבל (\"ערוך\" ערך קמרא, וכן מוכח מהוריות י\"ג ע\"ב). מסר משום רבי אליעזר (פסחים מ\"ח ע\"א), ורבי ישמעאל (שם ס\"ז ע\"ב) ורבי יוסי הגלילי (מנחות ל\"ח ע\"ב). היה חברו של רבי מאיר (הוריות י\"ג ע\"ב) וכשרשב\"ג פגע בכבוד רבי נתן ורבי מאיר, ניסו שניהם להוריד את רשב\"ג מנשיאותו (שם), ועל כך נקנס רבי נתן ובמקום שיזכירו את שמו מסרו את מאמריו בכינוי: \"יש אומרים\" (שם). היה רבו של רבי (ירו\u0027, כתובות פ\"ד הי\"א). מסכת אבות דרבי נתן מיוחסת לו. היה לו גילוי אליהו (גיטין ע\u0027 ע\"א). ועליו אמרו: \"רבי ורבי נתן סוף משנה\" (ב\"מ פ\"ו ע\"א), הרמ\"א כתב: \"רבי ורבי נתן הלכה כרבי נתן\"."},{"i":3013,"n":"נתן החבר","l":"נ","b":"אמורא ארץ ישראלי בדור החמישי. מובא בתנחומא (תולדות - כ\"ב), שאמר בשם רבי אחא."},{"i":3014,"n":"ר\u0027 נתן כהן אחוי דר\u0027 חייא בר אבא","l":"נ","b":"ע\"ע רבי כהן."},{"i":3015,"n":"ר\u0027 נתנאל","l":"נ","b":"מובא בפדר\"א (פי\"ז)."},{"i":3016,"n":"סבטא בן אלס","l":"ס","b":"מובא בבבלי (סנהדרין ס\"ד ע\"א). רש\"י גרס: סבטאי, ופירש: \"שם יהודי הוא\", \"בן אלס\" פרש\"י: \"שם מקום\". ואין לדעת אם היה מן החכמים."},{"i":3017,"n":"סביא","l":"ס","b":"אמורא ארץ ישראלי בדור הראשון - השני. מובא בבבלי: \"רבי יוחנן וסביא, חד אמר וכו\u0027\" (יבמות ט\"ז ע\"ב). אולי הוא לוי סבא, שריש לקיש מסר משמו."},{"i":3018,"n":"ר\u0027 סובייה","l":"ס","b":"מובא בירושלמי (פסחים פ\"ו ה\"א). ע\"ע לוי סבא."},{"i":3019,"n":"סומא בר כתבה","l":"ס","b":"אמורא ארץ ישראלי בדור השלישי. אמר בשם רבי שמעון בן לקיש (במ\"ר פי\"ד - א\u0027)."},{"i":3020,"n":"סומכוס","l":"ס","b":"תנא בדור החמישי. פעם אחת בש\"ס הובא שמו במלואו: \"סומכוס בן יוסף\" (ירו\u0027, ברכות פ\"ב ה\"א). תלמידו המובהק של רבי מאיר. היה חריף ביותר ואמרו עליו: \"תלמיד הוה לו לרבי מאיר וסומכוס שמו, שהיה אומר על כל דבר ודבר של טומאה ארבעים ושמונה טעמי טומאה, ועל כל דבר ודבר של טהרה ארבעים ושמונה טעמי טהרה\" (עירובין י\"ג ע\"ב). אחרי פטירת רבי מאיר, ביקש סומכוס ללמוד לפני רבי יהודה (נזיר מ\"ט ע\"ב). האריך ימים, עד שרב למד ממנו (כתובות פ\u0027 ע\"א): \"א\"ר אבא שאלתי את סומכוס\", ופי\u0027 רבינו האי גאון שזה ר\u0027 אבא הוא רב."},{"i":3021,"n":"סורחב בר פפא","l":"ס","b":"אמורא בדור השלישי. אמר משמיה דזעירי (כתובות י\"ז ע\"ב)."},{"i":3022,"n":"רב סחורה","l":"ס","b":"אמורא בבלי בדור השלישי. תלמידו של רב הונא (ברכות ה\u0027 ע\"א). רבו המובהק של רבא (יבמות ק\"ו ע\"א תד\"ה: רבא) ורבו שיבחו לפני רב נחמן שאדם גדול הוא (נדרים כ\"ב ע\"ב)."},{"i":3023,"n":"רבי סידור","l":"ס","b":"אמורא ארץ ישראלי בדור הראשון - השני. מובא בירושלמי: \"אמר רבי סידור, יהודה ברבי [יהודה בנו של רבי חייא] למד מכשירין ששה ירחים, לבסוף בא אחד מתלמידי רבי סימאי ושאלו דבר במכשירין ולא ידע לענות לו\" (שבת פ\"ז ה\"ב)."},{"i":3024,"n":"סילני","l":"ס","b":"מובא בירושלמי (שביעית רפ\"ג) ששאל לרבי חייא בר אבא. אין לדעת אם היה מן החכמים. \"סה\"ד\" הביאו בין החכמים (ונדפס ב\"סה\"ד\" בטעות \"שבועות רפ\"ג\", וצ\"ל \"שביעית\")."},{"i":3025,"n":"רב סימא בריה דרב אידי","l":"ס","b":"אמורא בבלי בדור השביעי. מתלמידי רב אשי והקשה לו (מנחות כ\"ה ע\"א)."},{"i":3026,"n":"רב סימא בריה דרב אשי","l":"ס","b":"מובא בבבלי (מנחות כ\"ה ע\"א), והוא רב סמא בריה דרב אשי."},{"i":3027,"n":"רבי סימאי","l":"ס","b":"מאחרוני התנאים בארץ ישראל. שמו מוזכר בברייתא (יבמות פ\"ג ע\"ב). רבי יונתן היה מתלמידיו (ב\"מ צ\u0027 ע\"ב). רבי יוחנן מסר משמו (ירו\u0027, מעשרות פ\"א ה\"א) ושם הגיר\u0027 רבי סיסיי, אך נראה שט\"ס היא וצ\"ל: סימאי. וכן היה ריש לקיש מתלמידיו (יבמות ע\"ד ע\"א). הלך לעבר שנה בלוד (חולין נ\"ו ע\"ב). לבנו מנחם קראו: \"בנן של קדושים\", שכן לא הסתכל בצורת מטבע מימיו (פסחים ק\"ד ע\"א). בנו היה תנא (שם)."},{"i":3028,"n":"ר\u0027 סימאי בר קיסי","l":"ס","b":"מובא בפסדר\"כ (ספי\"ז - קלד)."},{"i":3029,"n":"רבי סימון","l":"ס","b":"אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של רבי יהושע בן לוי (ב\"ק קט\"ו ע\"ב), והיה מסדר לפניו דברי אגדה (ברכות י\u0027 ע\"א). מסר בשם רבי יוחנן (ירו\u0027, פסחים פ\"ד ה\"א). היו לו שדות בהר המלך, שלא יכול לעבדם בעצמו, ושאל לרבי יהושע בן לוי וגם לרבי יוחנן כיצד לנהוג (ירו\u0027, דמאי פ\"א ה\"א). מחבריו היה בעל האגדה רבי לוי (ירו\u0027, ברכות פ\"א ה\"א). אמרו משמו: רבי ברכיה (ב\"ר רפ\"ו - ספ\"י) ורבי תנחום בר חמא (ירו\u0027, מו\"ק פ\"ג ה\"ז). מצינו: \"א\"ל ר\"ז לר\u0027 סימון: \u0027לוכחינהו מר להני דבי ריש גלותא\u0027\" (שבת נ\"ה ע\"א), ומזה ניתן אולי להסיק שר\u0027 סימון היה בבבל, או אולי ר\"ז, שהיה בבלי, קרא לנשיא: \"ריש גלותא\"."},{"i":3030,"n":"רבי סימון אחוה דר\u0027 יהודה בר זבדי","l":"ס","b":"אמורא ארץ ישראלי בדור השני. תלמידם של רבי אסי (ירו\u0027, שביעית פ\"ב ה\"ה) ורבי אלעאי (ירו\u0027, פסחים פ\"ח ה\"ו), נפטר בחיי ר\u0027 אלעאי, שהספידו (ירו\u0027, ברכות פ\"ח ה\"ו). מסר בשם רב (ירו\u0027, ב\"ב רפ\"ג). והמוסרים בשמו היו ר\u0027 חזקיה ר\u0027 יונה ור\u0027 פנחס (קה\"ר פ\"ב - א\u0027). היו לו שני אחים: ר\u0027 יהודה ור\u0027 אבא."},{"i":3031,"n":"ר\u0027 סימון בן קיזות","l":"ס","b":"אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי לוי (שהש\"ר פ\"ח - ו\u0027)."},{"i":3032,"n":"רבי סימון בר זבדי","l":"ס","b":"מובא בירושלמי (שביעית פ\"ב ה\"ה). נראה שהוא רבי סימון אחוה דרבי יהודה בר זבדי."},{"i":3033,"n":"ר\u0027 סימון בר יהושע","l":"ס","b":"מובא בויק\"ר (פכ\"ח - ט\u0027)."},{"i":3034,"n":"ר\u0027 סימון בר מרתא","l":"ס","b":"מובא בב\"ר (ספ\"ט)."},{"i":3035,"n":"ר\u0027 סימון בר תדאי","l":"ס","b":"כן גיר\u0027 הר\"ן ולפנינו ר\u0027 סימון דתרי (ירו\u0027, שבת פ\"ג ה\"א)."},{"i":3036,"n":"רבי סימון ברבי יהושע בן לוי","l":"ס","b":"מובא בירושלמי (מגילה פ\"א ה\"ה). יתכן שיש כאן ט\"ס וצ\"ל: ר\u0027 סימון בשם רבי יהושע בן לוי."},{"i":3037,"n":"ר\u0027 סימון דתרי","l":"ס","b":"אמורא ארץ ישראלי בדור השני. מסר בשם רבי אושעיא (ירו\u0027, שבת פ\"ג ה\"א)."},{"i":3038,"n":"ר\u0027 סימון מן דרומא","l":"ס","b":"מובא באס\"ר (פ\"ד - ד\u0027)."},{"i":3039,"n":"רב סימונא","l":"ס","b":"מראשי הדור השני של רבנן סבוראי. חברו ובן זוגו של רב עינא. עמד בראש ישיבת פומבדיתא. לא מובא בתלמוד, אך מוזכר ב\"אגרת רב שרירא גאון\", שרב עינא ורב סימונא הכניסו כמה הבהרות וסברות כהוספות בתלמוד."},{"i":3040,"n":"רבי סימיי","l":"ס","b":"מובא בירושלמי (מע\"ש פ\"ב ה\"א), ונראה שהוא רבי סימאי."},{"i":3041,"n":"סימן","l":"ס","b":"מובא בבבלי: \"סימן אמר רבה בר רב שילא, אמר קרא וכו\u0027\" (ב\"ב קי\"ג ע\"א), ו\"מסורת הש\"ס\" כתב: \"יש לומר שהוא שם אמורא\". אם כן, הרי שהיה אמורא בבלי בדור הרביעי - החמישי."},{"i":3042,"n":"ר\u0027 סיסא","l":"ס","b":"אמורא בבלי בדור השני. מובא בש\"ר (פנ\"א - ח\u0027) שחלק עם רב הונא."},{"i":3043,"n":"רבי סיסיי","l":"ס","b":"מובא בירושלמי (מעשרות פ\"א ה\"א), ונראה שצ\"ל רבי סימאי."},{"i":3044,"n":"רב סלא","l":"ס","b":"אמורא בדור הרביעי - החמישי. תלמידו של רבי ירמיה (ביצה ל\"א ע\"א). כן היה תלמידו של רב המנונא (תענית ז\u0027 ע\"ב)."},{"i":3045,"n":"רב סמא","l":"ס","b":"אמורא בבלי בדור השביעי. תלמידו של רב אשי (מנחות מ\"ב ע\"א): \"רבינא ורב סמא הוו יתבי קמיה דרב אשי וכו\u0027 א\"ל [רב אשי לר\u0027 סמא] וכו\u0027 איכסיף\"."},{"i":3046,"n":"רב סמא בר חילקאי","l":"ס","b":"אמורא בבלי בדור הששי. נראה שהיה חברו של רבינא: \"אמר רבינא: \u0027אמר לי סמא בר חילקאי [ולא אמר רב סמא]: אקשי בה אבוה דבר אבוברם וכו\u0027\" (חולין ל\"ח ע\"א)."},{"i":3047,"n":"רב סמא בר רקתא","l":"ס","b":"אמורא בבלי בדור הששי. מובא בבבלי, שחלק עם רבינא ונשבע \"בכתר המלך\" שדבריו נכונים (קידושין ט\u0027 ע\"א)."},{"i":3048,"n":"רב סמא בריה דרב אסי","l":"ס","b":"אמורא בבלי בדור השביעי. היה מתלמידיו של רב אשי והקשה לו (כתובות ל\"ג ע\"ב). אביו רב אסי היה בן דורו של רב אשי."},{"i":3049,"n":"רב סמא בריה דרב אשי","l":"ס","b":"אמורא בבלי בדור השביעי. בנו ותלמידו של רב אשי והקשה לאביו (כתובות ל\"ג ע\"ב). ולפי דעתו של רש\"י (שם, ס\"ט ע\"א ד\"ה: למיגבה) מת רב סמא בחיי רב אשי אביו."},{"i":3050,"n":"רב סמא בריה דרב ייבא","l":"ס","b":"אמורא בבלי בדור הששי. תלמידו של רב פפא (ב\"ב ט\u0027 ע\"א)."},{"i":3051,"n":"רב סמא בריה דרב ירמיה","l":"ס","b":"אמורא בבלי. אולי אפשר לומר, שהיה בזמנו של אביי (דור הרביעי לאמוראים), כמובא בבבלי: \"הדר אמר אביי וכו\u0027, מתקיף לה רב סמא בריה דרב ירמיה וכו\u0027 אמר קרא וכו\u0027\" (כתובות ל\"ג ע\"א). אין לדעת אם אביי ענה לו: \"אמר קרא\", או שזה ממסדר הש\"ס."},{"i":3052,"n":"רב סמא בריה דרב מרי","l":"ס","b":"אמורא בבלי בדור הרביעי. רב חנא בר אדא אמר משמו (ברכות ס\"ב ע\"ב)."},{"i":3053,"n":"רב סמא בריה דרב משרשיא","l":"ס","b":"אמורא בבלי בדור הששי - השביעי. תלמידו של רב אשי: \"א\"ל רבינא לרב אשי: אמר לן רב סמא בריה דרב משרשיא משמך דאמרת ליה משמיה דרבא וכו\u0027\" (חולין י\"ז ע\"ב)."},{"i":3054,"n":"רב סמא בריה דרבא","l":"ס","b":"אמורא בבלי בדור השביעי. היה ראש ישיבה בפומבדיתא בשנים ד\u0027 ר\"ה - רל\"ה (544 - 574) (\"אגרת רב שרירא גאון\"). מוזכר בבבלי קודם לרב אשי (ב\"מ מ\"ב ע\"ב). בימיו היו גזירות קשות על ישראל במלכות פרס, וכמה חכמים נהרגו על ידי המלך יזדגר השני, וביקשו רחמים ובא תנין ובלע את המלך בחדר משכבו ובטלו הגזירות (\"אגרת רב שרירא גאון\")."},{"i":3055,"n":"סמוכוס בר יוסף","l":"ס","b":"מובא בירושלמי (ברכות פ\"ה ה\"א). ע\"ע סומכוס."},{"i":3056,"n":"רבי סמיא","l":"ס","b":"מובא בבבלי, דאמר ריש לקיש אמר רבי סמיא (יבמות ע\"ד ע\"א), ונראה אולי שצ\"ל: רבי סימאי."},{"i":3057,"n":"סמליון","l":"ס","b":"מובא בבבלי: \"סמליון אומר\" (סוטה י\"ג ע\"ב), ופרש\"י: \"שם חכם\", והר\"ח וה\"ערוך\" ותוספות מפקפקים אם זה שם מלאך או שם חכם."},{"i":3058,"n":"רב סעורם","l":"ס","b":"מובא בבבלי (ב\"מ ע\"ג ע\"ב), והוא רב שעורם."},{"i":3059,"n":"רב ספרא","l":"ס","b":"אמורא בבלי בדור השלישי - הרביעי. היה מספר פעמים בארץ ישראל. שאל מרבי אבא (פסחים נ\"א ע\"ב) וקרא לו לרבי אבא: \"משה\" (פרש\"י בחולין צ\"ג ע\"א: תלמיד חכם). רבי אבהו אמר למינים שהוא אדם גדול (ע\"ז ד\u0027 ע\"א). רבא קרא לו: \"גברא רבא\" (ב\"ב קמ\"ד ע\"א). הקשה לרבי אבהו ורבי חנינא בר פפא ורבי יצחק נפחא, ולא ידעו להשיבו, ואמר רבא: \"קפחינהו רב ספרא לתלתא רבנן סמיכי\" (גיטין כ\"ט ע\"ב). אביי ביקש ממנו, שבבואו לארץ ישראל ישאל שם שאלה בהלכה, והוא שאל מרבי זריקא, וכשחזר מסר לאביי (חולין ק\"י ע\"ב). היה חברו של רב נחמן: וא\"ל רב ששת לרב נחמן: \"ספרא חברך תרגומה וכו\u0027\" (בכורות י\u0027 ע\"ב). נזהר ביותר להתרחק מכל דבר שקר (חולין צ\"ד ע\"ב). ודרשו: \"ודובר אמת בלבבו כגון רב ספרא\" (מכות כ\"ד ע\"א). רש\"י מביא מעשה עד כמה היה ירא שמים ואיש אמת: פעם הלך בשיירה ואריה נלוה אליהם ונעשה נס לרב ספרא (ב\"ק קט\"ז ע\"א), וכשנפטר רב ספרא צוה אביי שיקרעו עליו קריעה שהלכותיו מצויות בכל יום בבית המדרש (מו\"ק כ\"ה ע\"א)."},{"i":3060,"n":"רב ספרא בריה דרב ייבא","l":"ס","b":"אמורא בבלי בדור הששי. חברו של רבינא: \"א\"ל רב ספרא בריה דרב ייבא לרבינא: אמרי אינשי וכו\u0027\" (ב\"ב ה\u0027 ע\"א)."},{"i":3061,"n":"רב עובדיה","l":"ע","b":"אמורא בבלי בדור החמישי. תלמידו של רבא (ברכות ט\"ו ע\"ב). ישב לפני רבא כששלחה אפרא הורמיז, אמו של שבור מלכא, לשאול שאלה מרבא (נדה כ\u0027 ע\"ב)."},{"i":3062,"n":"רבי עוזיאל בר בריה דרבי עוזיאל רבה","l":"ע","b":"מובא בבבלי (מו\"ק ה\u0027 ע\"א)."},{"i":3063,"n":"ר\u0027 עוזיאל בריה דר\u0027 נחוניא דברת חוורין","l":"ע","b":"אמורא ארץ ישראלי בדור השני. מובא בירושלמי (שבת פ\"א ה\"ז). אביו. רבי נחוניא דברת חוורן, היה מרבותיו של רבי יוחנן."},{"i":3064,"n":"רב עוירא א\u0027","l":"ע","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידם של רבי אמי ורב אסי: \"דרש רב עוירא, זימנין משמיה דרבי אמי, וזימנין משמיה דרבי אסי\" (ברכות כ\u0027 ע\"ב). ורש\"י פירש שקיבל משניהם (שבת ק\"ח ע\"ב ד\"ה: זימנין). היה חברם של רבי חלבו ורבי יוסי בר חנינא (כתובות קי\"ב ע\"א). ביקר בבבל, ואביי בא אליו (חולין נ\"א ע\"א)."},{"i":3065,"n":"רב עוירא ב\u0027","l":"ע","b":"אמורא בבלי בדור החמישי - הששי. חברו של רבינא, ושניהם אמרו משמיה דרבא (ב\"ב קל\"א ע\"ב). תירץ קושיית רבינא (פסחים ע\"ג ע\"א)."},{"i":3066,"n":"רב עוירא סבא","l":"ע","b":"אמורא בבלי בדור השלישי. מובא בבבלי: \"כי אתה רבה בר בר חנה אכל דאייתרא [חלב שבכפיפת הקיבה שבני א\"י נהגו בו היתר], על לגביה רב עוירא סבא ורבה בריה דרב הונא, כיון דחזינהו כסייה מינייהו\" [נחבא מהם] (פסחים נ\"א ע\"א)."},{"i":3067,"n":"עולא (2)","l":"ע","b":"אמורא ארץ ישראלי בדור השני - השלישי. שם אביו היה ישמעאל: \"עולא בר ישמעאל, בשם רבי אלעזר: שלמי חגיגה ששחטן מערב הרגל אינו יוצא בהן ידי חובתו ברגל\" (ירו\u0027, סוכה פ\"ד ה\"ה). מאמר זה מובא בבבלי: \"אמר עולא אמר רבי אלעזר וכו\u0027\" (פסחים ע\u0027 ע\"א). רבו היה רבי יוחנן (מעילה י\"ב ע\"א). ועוד קיבל מהאמוראים של דור הראשון: רבי אושעיא (חולין ע\"ו ע\"א) ורבי חנינא (מנחות ל\u0027 ע\"א). מראשוני החכמים שניתן לו התואר \"נחותא\" (ירו\u0027, כלאים פ\"ט ה\"ג). תפקידו כ\"נחותא\" היה למסור תורת ארץ ישראל לחכמי בבל: \"דרש רב חסדא וכו\u0027 ורבותינו היורדין מארץ ישראל ומני עולא משמיה דרבי יוחנן וכו\u0027\" (ברכות ל\"ח ע\"ב). וכן: \"עולא איקלע לבי רב יהודה וכו\u0027\" (קידושין ע\"א ע\"ב), וכן: \"עולא איקלע לבי רב נחמן וכו\u0027\" (ברכות נ\"א ע\"ב). בין תלמידיו המובהקים היו רבי אבא ורבה בר בר חנה, כמו שמצינו, שעולא רכב ורבי אבא לימינו ורבה בר בר חנה לשמאלו (פסחים נ\"ג ע\"ב). וכן היו בין תלמידיו: רבה, רבי זירא (שם ל\"ז ע\"ב) ורב יוסף (שם). עולא נפטר בבבל, בחיי רבי אלעזר (כתובות קי\"א ע\"א)."},{"i":3068,"n":"עולא ביראה","l":"ע","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי אלעזר (מו\"ק כ\"ו ע\"א). רבו של רבי חלבו (ויק\"ר ספי\"א)."},{"i":3069,"n":"רב עולא בר אבא","l":"ע","b":"אמורא בבלי בדור השלישי - הרביעי. היה מופלג בחסידות ובמידות טובות, כמובא: \"שלחו מתם, איזהו בן עולם הבא? חסיד ועניו ושפל ברך, נכנס לבית המדרש ויצא בצנעה, ועוסק בתורה תדיר ואינו מחזיק טובה לנפשו, ונתנו רבנן עיניהם ברב עולא בר אבא\" (סנהדרין פ\"ח ע\"ב)."},{"i":3070,"n":"עולא בר חיננא","l":"ע","b":"מובא בבבלי: \"תנא עולא בר חיננא: נקטם ראשו וכו\u0027 בעי רבי ירמיה: נקטם ראשו מעיו\"ט וכו\u0027\" (סוכה ל\"ג ע\"א)."},{"i":3071,"n":"עולא בר ישמעאל","l":"ע","b":"מובא בירושלמי (סוכה פ\"ד ה\"ה), והוא סתם עולא."},{"i":3072,"n":"עולא בר מנשיא","l":"ע","b":"אמורא בבלי בדור השלישי. אמר משמיה דאבימי (גיטין ע\"ט ע\"א)."},{"i":3073,"n":"עולא בר קושב","l":"ע","b":"חי בדור הראשון לאמוראי ארץ ישראל. חויב במיתה ע\"י המלך וברח ללוד לרבי יהושע בן לוי, וחיילים באו ללוד והקיפו העיר ותבעו את הסגרתו. אחרת יחריבו את לוד, והסגיר את עצמו, ואליהו הנביא הקפיד עליו ואמר שכחסיד היה לו להסתלק מכל הענין (ירו\u0027, תרמות ספ\"ח). ואין ראיה שעולא בר קושב היה מן החכמים."},{"i":3074,"n":"עולא בר רב","l":"ע","b":"אמורא בבלי בדור החמישי. תלמידם של אביי (מגילה כ\"ד ע\"ב) ורבא (שם כ\"א ע\"ב). ושאל מהם. היה חזן והתפלל לפני רבא (פסחים קי\"ז ע\"ב)."},{"i":3075,"n":"עולא בר ר\u0027 זכאי","l":"ע","b":"כן גירסת התוספות (חולין נ\"ב ע\"א ד\"ה; נעקרה), אך לפנינו הגיר\u0027: אמר עולא, בן זכאי אמר."},{"i":3076,"n":"עולא בריה דרב אידי אמורא בבלי בדור השלישי","l":"ע","b":"הרביעי. רבא הקשה על דבריו ואמר: \"יציבא בארעא וגיורא בשמי שמיא\" (ב\"ק מ\"ב ע\"א)."},{"i":3077,"n":"רב עולא בריה דרב עילאי","l":"ע","b":"אמורא בבלי בדור השלישי. חברו של רב יוסף: \"רב עולא בריה דרב עילאי הוה ליה דינא קמיה דרב נחמן, שלח ליה רב יוסף: \u0027עולא חברנו עמית בתורה ובמצות\u0027\" (שבועות ל\u0027 ע\"א). נזכר בהלכה (זבחים י\"א ע\"ב)."},{"i":3078,"n":"עולא בריה דר\u0027 אלעזר","l":"ע","b":"מובא ב\"ילקוט\" (שה\"ש רמז תתקפ\"א), ואולי שם ט\"ס וצ\"ל: עולא ביראה."},{"i":3079,"n":"ר\u0027 עולא דקסרין","l":"ע","b":"אמורא ארץ ישראלי בדור השני. מסר בשם רבי חנינא. רבי יעקב בר אחא היה תלמידו (ירו\u0027, נדה פ\"ב ה\"ז)."},{"i":3080,"n":"עולא משגש ארחתיה דאימיה","l":"ע","b":"מובא בבבלי (ב\"ב ט\u0027 ע\"ב). לפירש\"י הכוונה לרב ששת, ולפירוש רבנו גרשום הכוונה לרב אחדבוי בר אמי."},{"i":3081,"n":"ר\u0027 עולא רבה","l":"ע","b":"מובא בבבלי: \"דרש ר\u0027 עולא רבה אפיתחא דבי נשיאה\" (כתובות ס\"ה ע\"ב)."},{"i":3082,"n":"עולא שכפא","l":"ע","b":"אמורא ארץ ישראלי בדור הרביעי. למד ברייתות לפני ר\u0027 דוסא, ואמר לו ר\u0027 דוסא: \"חזור בך\" [מאחת הברייתות] א\"ל ר\"ז: (לעולא שכפא) \"לא תחזור בך\" (ירו\u0027, ע\"ז פ\"ב ה\"ט)."},{"i":3083,"n":"רב עוקבא","l":"ע","b":"מובא בירושלמי, שאמר בשם רבי יהושע בן לוי (יומא פ\"א ה\"ב), ונראה שהוא מר עוקבא הירושלמי, תלמידו של ריב\"ל (עיין מר עוקבא)."},{"i":3084,"n":"רב עוקבא בר אבא","l":"ע","b":"אמורא בבלי בדור השלישי - הרביעי. מתלמידיו של רב נחמן, כמובא בבבלי: \"איתיביה רב עוקבא בר אבא לרב נחמן\" (עירובין ל\"ד ע\"ב)."},{"i":3085,"n":"רבי עוקבא בר אחא","l":"ע","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. חברם של רבי זירא ורבי אבא \"אמר רבי עקיבא בר אחא: עמו הייתי כד אמר רבי אבא וכו\u0027\" (ירו\u0027, קדושין פ\"ג הי\"ב)."},{"i":3086,"n":"רב עוקבא בר חיננא מפרישנא","l":"ע","b":"אמורא בבלי בדור החמישי. תלמידו של רבא והקשה לרבא (פסחים צ\"א ע\"א). אולי אביו הוא רב חיננא בריה דרבא מפשרוניא."},{"i":3087,"n":"רב עוקבא בר חמא","l":"ע","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב נחמן (ב\"מ ס\"ה ע\"א). נראה, שהוא מר עוקבא בר חמא."},{"i":3088,"n":"רב עוקבא ממישן","l":"ע","b":"אמורא בדור הששי. נראה אולי שהיה בארץ ישראל שכן מצינו (שבת ל\"ז ע\"ב) שאמר לרב אשי: \"אתון דמקרביתו לרב ושמואל וכו\u0027 [אף שפעמים \"אתון\" אינו מוכח כלום] אנו נעביד כרבי יוחנן\" (ורב ושמואל היו בבבל ורבי יוחנן היה בארץ ישראל). הרא\"ש סובר שהיה קשיש מרב אשי (שם ל\"ג ע\"ב)."},{"i":3089,"n":"עוקבן בר נחמיה","l":"ע","b":"ע\"ע נתן דצוציתא."},{"i":3090,"n":"עוקבן הבבלי","l":"ע","b":"מובא בבבלי, ששלח מארץ ישראל לבבל למר עוקבא תלונה על אחיו ירמיה (סנהדרין ל\"א ע\"ב), ואין לקבוע אם עוקבן הבבלי או אחיו ירמיה נמנו עם החכמים."},{"i":3091,"n":"ר\u0027 עזרא","l":"ע","b":"מובא בירושלמי (תרומות פ\"ז ה\"א), והוא ר\u0027 עזריה."},{"i":3092,"n":"ר\u0027 עזרא בר בריה דר\u0027 אבטולס","l":"ע","b":"אמורא מיוצאי חלציו של רבי אלעזר בן עזריה, שהיה מיוצאי חלציו של עזרא. מסופר (מנחות נ\"ג ע\"א) שבא לבית מדרשו של ר\u0027 פרידה (שחי 004 שנה - עירובין נ\"ד ע\"ב). קשה לקבוע את זמנו המדוייק."},{"i":3093,"n":"עזריה (2)","l":"ע","b":"חי בדור השני לתנאים. אביו של התנא רבי אליעזר בן עזריה. נראה, שהיה אדם גדול. לכאורה אפשר לומר שגם הוא היה תנא, שכן רבי דוסא בן הרכינס מכנהו: \"עזריה חברינו\" (יבמות ט\"ז ע\"א), אך מאידך נראה שזה רק לשון כבוד, שכן מצינו במשנה: \"שמעון אחי עזריה אומר\" (זבחים כ\u0027 ע\"א), ופרש\"י: \"על שם שעזריה עסק בפרקמטיא וסיפק צרכי שמעון אחיו בשעה שהיה עוסק בתורה והתנו ביניהן שיהא חלק לעזריה בשכר למודו של שמעון וכו\u0027, לפיכך נקרא על שמו שלמד על ידו\". ראיה ברורה יותר שלא היה תנא (סוטה כ\"א ע\"א) ופרש\"י (ד\"ה: שמעון אחי עזריה): \"תנא הוא במשנה קמייתא דזבחים שלמד תורה ע\"י אחיו שעסק בפרקמטיא כדי שיחלוק בזכות למודו של שמעון\", וא\"כ נראה יותר ששמעון היה תנא ולא הוא."},{"i":3094,"n":"ר\u0027 עזריה","l":"ע","b":"אמורא ארץ ישראלי בדור החמישי. מבעלי האגדה. תלמידו של רבי מנא (ירו\u0027, פסחים פ\"א ה\"ח). כן מסר יחד עם יונתן בן חגי בשם ר\u0027 יצחק בר מריון (קה\"ר פ\"ט - י\"ב) ור\u0027 יוסי בר חנינא (תנחומא ראה - ט\"ז). ר\u0027 תנחומא מסר בשמו (ר\"ור פ\"ג - ו\u0027)."},{"i":3095,"n":"ר\u0027 עזריה איש כפר אונו","l":"ע","b":"מובא ב\"זוהר חדש\" (רות פ\"א)."},{"i":3096,"n":"ר\u0027 עזריה בר\u0027 סימון","l":"ע","b":"מובא ברו\"ר (פ\"ב - ז\u0027), ואולי ט\"ס שם."},{"i":3097,"n":"ר\u0027 עזריה דכפר חטיא","l":"ע","b":"אמורא ארץ ישראלי בדור השני. רבי אבא בר כהנא אמר משמו (ויק\"ר פ\"ז - ד\u0027)."},{"i":3098,"n":"עייא","l":"ע","b":"רבי כינה את רבי חייא: \"עייא\" (מו\"ק ט\"ז ע\"ב פרש\"י: \"כך כינו שמו של רבי חייא לשון גנאי, כי רבי הקפיד על ר\u0027 חייא שעבר על דבריו\"). גם בר קפרא כינהו כך (כריתות ח\u0027 ע\"א)."},{"i":3099,"n":"רב עילא","l":"ע","b":"אמורא בבלי בדור הרביעי. מובא בבבלי, שאביי ורבנן עלו לבקרו כשחלה (מנחות פ\"א ע\"א)."},{"i":3100,"n":"עילא בר חנינא","l":"ע","b":"מובא בבבלי (נזיר ס\"ה ע\"א), והוא עולא בר חיננא."},{"i":3101,"n":"ר\u0027 עילאי","l":"ע","b":"מובא בבבלי (ע\"ז י\"ג ע\"ב), ו\"דק\"ס\" גרס: \"אלעאי\" (האמורא הנודע)."},{"i":3102,"n":"רב עיליש","l":"ע","b":"אמורא בבלי בדור הרביעי. נפטר לפני רבא (ב\"ב ס\"ח ע\"ב). רבא אמר עליו: \"גברא רבא\" (שם). נראה, שהיה כפוף לרבא (ב\"ב קל\"ג ע\"ב). פעם אחת הקשה לרבא ורבא איכסיף (גיטין ע\"ז ע\"ב). פעם נשבה רבי עיליש ובאותו שבי היו גם בנות רב נחמן, והוא ברח משביו (שם מ\"ה ע\"א)."},{"i":3103,"n":"רב עינא","l":"ע","b":"אמורא בבלי בדור השני. חברו של רב יהודה ושניהם מכונים \"סבי דפומבדיתא\" (סנהדרין י\"ז ע\"ב): \"איתמר רב יהודה ורב עינא, חד תני שואבה וחד תני חשובה\" (סוכה נ\u0027 ע\"ב). ומצינו: \"דרש רב עינא אפתחא דבי ריש גלותא וכו\u0027, אמר להו רבה וכו\u0027 לישמטו\" (חולין פ\"ד ע\"ב), ופרש\"י: \"יחתכו את לשונו, וכו\u0027 לביישו\". \"יוחסין\" סבר שרב עינא ורב עינא סבא (פסחים פ\"ח ע\"א) אחד הוא, לכן לא הביא את רב עינא בערך נפרד, אלא רק את רב עינא סבא."},{"i":3104,"n":"רב עינא סבא","l":"ע","b":"אמורא בבלי בדור השלישי. מובא בבבלי, שהקשה לרב נחמן ור\"נ אמר לו: \"פתיא אוכמא\" (פסחים פ\"ח ע\"א)."},{"i":3105,"n":"עיפא בן רחבא מפומבדיתא","l":"ע","b":"אמורא בבלי בדור הרביעי. אחיו הוא אבימי, ושניהם כונו \"חריפי דפומבדיתא\" (סנהדרין י\"ז ע\"ב). וכן ברש\"י (קידושין ל\"ט ע\"א). כן כונו \"בני רחבא\" (שבת ק\"ג ע\"א). עיפא היה תלמידו של רבה (שבועות כ\"ח ע\"ב)."},{"i":3106,"n":"רב עמרם א\u0027","l":"ע","b":"אמורא בבלי בדור השני. תלמידו של רב (פסחים ק\"ה ע\"א). וכן קיבל מרב אסי (תלמיד חבר של רב), שמצינו: \"שלח ליה רמי בר יחזקל לרב עמרם נימא לן מר מהלין מילי מעלייתא דאמרת משמיה דרב אסי\" (עירובין ק\"ב ע\"א). היה זקן מרב נחמן ומרמי בר חמא (בכורות כ\"ז ע\"ב). ורמי בר חמא אמר לרב נחמן: \"לא לחוש מר לסבא\" (הכוונה לרב עמרם)."},{"i":3107,"n":"רב עמרם בריה דר\u0027 שמעון בר אבא","l":"ע","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. יתכן שקיבל מרבי חנינא כמובא: \"אמר רב עמרם בריה דרבי שמעון בר אבא אמר רבי חנינא\" (סנהדרין ע\u0027 ע\"א), ויתכן שנשמטו מספר מלים וצריך לומר כמובא במקום אחר: \"אמר רב עמרם בריה דרבי שמעון בר אבא אמר רבי שמעון בר אבא אמר רבי חנינא\" (שבת קי\"ט ע\"ב)."},{"i":3108,"n":"רב עמרם ב\u0027","l":"ע","b":"אמורא בבלי בדור השלישי. חברם של רבה ורב יוסף. רבה כינהו: \"תרדא\" ופקע ארזא דבי רב (ב\"מ כ\u0027 ע\"ב). היה תלמידו של רב ששת: \"אמר רב עמרם: \u0027האי מילתא אמר לן רב ששת ואנהר לן עיינין\u0027 וכו\u0027 א\"ל רב יוסף וכו\u0027\" (סוטה ו\u0027 ע\"א). רב ששת אמר לרב עמרם: \"דילמא מפומבדיתא את דמעיילין פילא בקופא דמחטא\" (ב\"מ ל\"ח ע\"ב)."},{"i":3109,"n":"רב עמרם חסידא","l":"ע","b":"אמורא בבלי בדור השני. נפטר לפני רב יוסף (ע\"ז ל\"ט ע\"א). על חסידותו מסופר שאנשי בית ריש גלותא היו מענים אותו, פרש\"י: \"מפני שהיה חסיד ופרוש, ומחמיר עליהן באיסורין\" (גיטין ס\"ז ע\"ב), וילתא אשת רב נחמן הצילתו מידם, ומעשה מופלא מסופר עליו במקום אחר (קידושין פ\"א ע\"א)."},{"i":3110,"n":"עמרם צבעא","l":"ע","b":"חי בבבל בדור השלישי לאמוראים. היה אפוטרופוס של יתומים והם באו לפני רב נחמן (גיטין נ\"ב ע\"ב). אין ראיה שהיה חכם. \"סה\"ד\" כתב: \"לא ידעתי אם חכם היה\"."},{"i":3111,"n":"רב ענן","l":"ע","b":"אמורא בבלי בדור השני. שם אביו היה רב: רב ענן בר רב (עירובין ע\"ד ע\"ב). היה תלמידו המובהק של שמואל (עירובין צ\"ה ע\"א). כן היה תלמידו של רב (ברכות ל\u0027 ע\"ב). קרא לרב הונא: \"הונא חברין\", ורב הונא הקפיד על כך (כתובות ס\"ט ע\"א). לרב נחמן קרא: \"נחמן חקלאה\" (שם ע\"א ע\"א פרש\"י: \"אינו בקי בדינין\"). אליהו הנביא היה רגיל לבוא אליו ועל פיו כתב את אליהו רבה ואליה זוטא (כתובות ק\"ו ע\"א)."},{"i":3112,"n":"רב ענן בר יוסף","l":"ע","b":"אמורא ארץ ישראלי בדור הרביעי. יחד עם רבי ברכיה ורבי חלקיה אמרו בשם רבי אידו (מד\u0027 תהלים פס\"ה - ד\u0027). כן מצינו: \"רבי ברכיה בשם רבי ענן בר\u0027 יוסי\" (פד\"כ פ\u0027 שובה)."},{"i":3113,"n":"רב ענן בר רבא","l":"ע","b":"אמורא בבלי בדור השני. מסר בשם רב (ר\"ה ל\"א ע\"א). ואולי יש ט\"ס בשם. \"סה\"ד\" כתב: \"ס\"א רב חנן בר רבא\"."},{"i":3114,"n":"רב ענן בר תחליפא","l":"ע","b":"אמורא בבלי בדור השני. תלמידו המובהק של שמואל: \"זימנין סגיאין הוה קאימנא קמיה דשמואל\" (פסחים ק\"א ע\"א), וכן: \"לדידי מיפרשא לי מיניה דמר שמואל\" (מו\"ק י\"ח ע\"א)."},{"i":3115,"n":"רבי ענן בר\u0027 יוסי","l":"ע","b":"מובא בפד\"כ (פ\u0027 שובה), ונראה שהוא רב ענן בר יוסף."},{"i":3116,"n":"רב ענן ר חייא","l":"ע","b":"אמורא בבלי בדור הראשון, כמובא: \"ההוא שטרא דנפיק מבי דינא דמר שמואל והוה כתיב בו, מדאתא רב ענן בר חייא וכו\u0027\" (כתובות כ\"א ע\"א). נראה אולי, שהוא המובא בשם ענן בר חייא (יבמות קט\"ז ע\"א)."},{"i":3117,"n":"רבי ענני בר נחשון","l":"ע","b":"מובא בקה\"ר (פ\"ג - י\"א), ואולי הוא רבי אנינייא בר סיסי (ע\"ע)."},{"i":3118,"n":"רבי ענני בר ששון","l":"ע","b":"אמורא ארץ ישראלי בדור השלישי. מובא בבבלי, שדרש אפיתחא דבי נשיא, שמע רבי אמי ואיקפד, אמר: \"אטו דידיה הוא, דרבי אלעזר אמר רב אושעיא היא\" (מו\"ק כ\"ד ע\"ב)."},{"i":3119,"n":"ר\u0027 ענניאל בר ששון","l":"ע","b":"מובא בש\"ר (פ\"ג - ו\u0027)."},{"i":3120,"n":"עקביא בן מהללאל","l":"ע","b":"מחכמי ישראל הקדומים. חי בדור החמישי ל\"זוגות\" בסמוך לחורבן הבית. ורבי יהודה אמר עליו ש\"אין העזרה ננעלת על כל אדם בישראל בחכמה ובטהרה וביראת חטא כעקביא בן מהללאל\" (ברכות י\"ט ע\"א). חלק על חכמים בארבעה דינים, והם אמרו לו \"עקביא חזור בך בארבע דברים שהיית אומר, ונעשך אב\"ד לישראל, אמר להן: מוטב להקרא שוטה כל ימי ולא לעשות שעה אחת רשע לפני המקום, שלא יהיו אומרים בשביל שררה חזר בו\" (עדיות פ\"ה מ\"ו). ומסופר (שם) שנידוהו ומת בנידויו וסקלו ב\"ד את ארונו אמר רבי יהודה חס ושלום שעקביא נתנדה וכו\u0027 בשעת פטירתו אמר לבנו חזור בד\u0027 דברים שהייתי אומר וכו\u0027."},{"i":3121,"n":"עקביה","l":"ע","b":"אמורא ארץ ישראלי בדור השני - השלישי. מובא בירושלמי, ששאל את רבי חנינא ואת רבי שמעון בן לקיש (סוטה פ\"ד ה\"ג)."},{"i":3122,"n":"רב עקביה","l":"ע","b":"אמורא בבלי בדור הרביעי. רבא אמר עליו: \"מאן חכים למיעבד כי הא מילתא אי לא רב עקביה דגברא רבה הוא\" (ע\"ז ע\"ו ע\"ב). תוספות גורסים: \"מר עוקבא\" (פסחים מ\u0027 ע\"ב ד\"ה: האילפס), ו\"מסורת הש\"ס\" תיקן: \"רב עוקבא\", וכך גם גרס התוספות במקום אחר (שבת מ\"ג ע\"ב ד\"ה אבל), וגם שם תיקן \"מסורת הש\"ס\" ל\"רב עוקבא\"."},{"i":3123,"n":"רבי עקיבא (2)","l":"ע","b":"מגדולי התנאים בכל הדורות. ראש הדור השלישי לתנאים. זמן פעילותו היה בין חורבן הבית לחורבן ביתר. חי 021 שנה (ספרי ברכות סל\"ו). \"סה\"ד\" כתב, שיש אומרים שנולד ג\u0027 תש\"ס (1 לס\u0027) ונהרג ג\u0027 תת\"פ (021). שם אביו היה יוסף (מנחות כ\"ט ע\"ב). רבי דוסא בן הרכינס אמר על ר\"ע: \"אתה הוא עקיבא בן יוסף ששמך הולך מסוף העולם ועד סופו\" (יבמות ט\"ז ע\"א). ומסופר (מנחות כ\"ט ע\"ב): \"אמר לו [הקב\"ה למשה רבנו] אדם אחד יש שעתיד להיות בסוף כמה דורות ועקיבא בן יוסף שמו, שעתיד לדרוש על כל קוץ וקוץ תילין תילין של הלכות וכו\u0027\", אמר [משה רבנו] לפניו: \"רבש\"ע, יש לך אדם כזה ואתה נותן תורה על ידי?\" ומובא (במד\"ר פי\"ט): דברים שלא נתגלו למשה רבנו נתגלו לר\"ע. ומסופר: \"ארבעה נכנסו לפרדס [פרש\"י עלו לרקיע על ידי שם] ואלו הן: בן עזאי, בן זומא, אחר, ורבי עקיבא וכו\u0027, בן עזאי הציץ ומת, בן זומא הציץ ונפגע, אחר קצץ בנטיעות [יצא לתרבות רעה], רבי עקיבא יצא בשלום\" (חגיגה י\"ד ע\"ב). וכן: \"ואף רבי עקיבא בקשו מלאכי השרת לדוחפו, אמר להם הקב\"ה: \u0027הניחו לזקן זה שראוי להשתמש בכבודי\u0027\" (שם ט\"ו ע\"ב). הרמב\"ם (בהקדמתו ל\"יד החזקה\") כתב שיוסף, אבי רבי עקיבא, היה גר צדק וכתב רב נסים גאון: \"מבני בניו של סיסרא למדו תורה וכו\u0027, ומאן אינון, רבי עקיבא\" (ברכות כ\"ז ע\"ב). עד גיל 04 לא למד דבר ולא ידע אפילו צורת אות אחת (אבות דר\u0027 נתן פ\"ו). היה רועה אצל כלבא שבוע מעשירי ירושלים, ורחל בת כלבא שבוע אמרה לו שאם ילך ללמוד תורה תתחתן עמו. לאחר שהתחתנו הדיר אותה אביה מכל נכסיו (כתובות ס\"ב ע\"ב). רבי עקיבא הלך ולמד תורה עשרים וארבע שנה (שם), וחזר לביתו עם עשרים וארבעה אלף תלמידים, ואשתו יצאה לקראתו ונשקה את רגליו, וכשדחפוה תלמידיו מעליו, אמר להם ר\"ע: \u0027שלי ושלכם שלה היא\u0027 (כלומר בזכות אשתו רחל שהשפיעה עליו להתחיל ללמוד והיה למה שהיה). את נחום איש גם זו, שימש עשרים ושתיים שנה (חגיגה י\"ב ע\"א). שלוש עשרה שנה שימש את רבי אליעזר (ירו\u0027, פסחים פ\"ו ה\"ג). וגם רבי יהושע היה רבו המובהק (ברכות ס\"ב ע\"א), ואח\"כ גדל רב עקיבא והיה לתלמיד - חבר לרבי אליעזר ורבי יהושע (מסכת כלה רבתי רפ\"ב): \"כיון דחזו דקא גבר עלייהו הוו להו חבריו\" (שם). גם רבי טרפון היה בתחלה רבו ואח\"כ היה לו ר\"ע לתלמיד - חבר (כתובות פ\"ד ע\"ב), ור\"ט אמר עליו \"כל הפורש ממך כפורש מן החיים\" (קידושין ס\"ו ע\"ב). יסד ישיבה גדולה בבני ברק (סנהדרין ל\"ב ע\"ב). לקח חלק בסנהדרין ביבנה, והיה אחד מארבעה שידעו 07 לשון (שם י\"ז ע\"ב). מחבריו הגדולים היו רבי אליעזר בן עזריה (חגיגה י\"ד ע\"א) ור\u0027 יוחנן בן נורי (ערכין ט\"ז ע\"ב). וחברו המובהק ביותר היה רבי ישמעאל (סנהדרין נ\"א ע\"ב). תלמידיו הגדולים היו רבי מאיר (עירובין י\"ג ע\"א), רבי יהודה (שם מ\"א ע\"א), רבי יוסי (פסחים י\"ח ע\"א), רבי שמעון בן יוחאי (מעילה ז\u0027 ע\"א) ורבי אלעזר בן שמוע (זבחים צ\"ג ע\"א). ואמרו: \"סתם מתני\u0027 רבי מאיר, סתם תוספתא רבי נחמיה, סתם סיפרא רבי יהודה, סתם ספרי רבי שמעון, וכולהו אליבא דרבי עקיבא\" (סנהדרין פ\"ו ע\"א). רבי עקיבא מוזכר 622 פעם במשנה ו - 465 פעם בתלמוד. עוד טרם החל ללמוד היו בו מידות תרומיות. הוא היה צנוע (כתובות ס\"ב ע\"ב) וירא שמים (עירובין כ\"א ע\"ב) וחסיד (שם). הוא אמר: \"מוטב אמות מיתת עצמי ולא אעבור על דעת חברי\", וכן: \"שבקה רבי עקיבא לחסידותיה\" (שם ק\"י ע\"ב). ומסופר: \"וכשהיה מתפלל בינו לבין עצמו, אדם מניחו בזוית זו ומוצאו בזוית אחרת, וכל כך למה, מפני כריעות והשתחויות\" (ברכות ל\"א ע\"א), והיה מעביר על מידותיו (תענית כ\"ה ע\"ב) ונהג לומר: \"הכל לטובה\" (ברכות ס\u0027 ע\"ב). היו לו ארבע נשים בחייו. עוד בהיותו עם הארץ התחתן, ומאשתו זו נולד לו בן והוא ובנו החלו ללמוד אלף בית (אבות דר\"נ פ\"ו). אשתו השניה היתה בתו של כלבא שבוע (כתובות ס\"ב ע\"ב). ועוד שתי נשים היו לו: אלמנתו או גרושתו של טורנוסרופוס (נדרים נ\u0027 ע\"ב) ובתו של יהושע (ידים פ\"ג מ\"ה). היו לו בנים חכמים: בנו ר\u0027 יהושע בן קרחה (לפירוש רש\"י שבועות ו\u0027 ע\"א ד\"ה: יהושע), ובנו שמעון שהוליכו לחופה (ירו\u0027, ברכות ספ\"ו) ומת בחיי ר\"ע (שמחות פ\"ח). וכן הוליך לחופה את בתו שניצלה בנס ביום חופתה (שבת קנ\"ו ע\"ב). ושם חתנו היה ר\u0027 יהושע בן כפוסאי (שבת קמ\"ז ע\"ב). בן עזאי תלמידו אירס לו לאשה את בתו (כתובות ס\"ג ע\"א). האמין בבר כוכבא ואמר עליו: \"דרך כוכב מיעקב\" (ירו\u0027 תענית פ\"ד ה\"ה). הרמב\"ם כתב בסוף ספר משפטים, כי ר\"ע היה נושא כליו של בר כוכבא. הרומאים תפסו את ר\"ע ועינוהו ביסורים נוראים והיו סורקים את בשרו במסרקות של ברזל (ברכות ס\"א ע\"ב), וכן מסופר שחתכו בשרו כמו באטליז (מנחות כ\"ט ע\"ב), והמושל הרומי טורנוסרופוס לא יכול להאמין למראה עיניו כיצד ר\"ע מקבל את היסורין בשלוה ובאהבה ושאלו: \"סבא סבא או חרש את או מבעט ביסורין\" (ירו\u0027, סוטה פ\"ה ה\"ה), וקרא \"שמע ישראל\" ונשמתו יצאה בקריאת \"ה\u0027 אחד\" ויצאה בת קול ואמרה: \"אשריך רבי עקיבא שיצאה נשמתך באחד\" (ברכות ס\"א ע\"ב). ואמרו: \"משמת רבי עקיבא, בטל כבוד התורה\" (סוטה מ\"ט ע\"א), (ושם ע\"ב): \"משמת ר\"ע, בוטלו זרועי תורה ונסתתמו מעיינות החכמה\"."},{"i":3124,"n":"ר\u0027 עקיבא בן דוסא","l":"ע","b":"\"סה\"ד\" כתב: \"בזמן רבי מאיר, כ\"כ ב\u0027אגרת רב שרירא גאון\u0027\"; וא\"כ, היה תנא בדור הרביעי."},{"i":3125,"n":"רבי עקיבא בר אחא","l":"ע","b":"מובא בירושלמי (יבמות פט\"ז ה\"ה), ואולי יש ט\"ס בשם."},{"i":3126,"n":"ר\u0027 עקיבא בר זבדי","l":"ע","b":"אמורא ארץ ישראלי בדור הרביעי. אמר בשם רבי אבהו (\"ילקוט\" אמור רמז תרמ\"ב)."},{"i":3127,"n":"רבי עקיבא ברבי חנינא","l":"ע","b":"תנא מובא בבבלי, שרב אחא מסר משמו (מנחות ל\"ב ע\"ב). יתכן, שתנא בשם זה לא היה ולא נברא; \"שיטה מקובצת\" מחק \"עקיבא\" וגרס: \"רבי יעקב ברבי חנינא\", וכן ציין \"מסה\"ש\", וכן הגירסא במקום אחר: \"רבי אחא מכשיר משום אחי בר חנינא, ואמרי לה משום רבי יעקב בר חנינא\" (שבת ע\"ט ע\"ב), וכן גרס \"סה\"ד\" (ואילו לא גדולי עולם גרסו כשם שגרסו, מי יערוב לידנו שלא צריך לגרוס ההיפך גם במסכת שבת כמו במנחות, כלומר, רבי עקיבא ברבי חנינא, ולא רבי יעקב בר\u0027 חנינא בשני המקומות, שכן שמות שני תנאים אלה לא נמצאו בש\"ס?)"},{"i":3128,"n":"רבי עקיבה בן יוסף","l":"ע","b":"הוא רבי עקיבא."},{"i":3129,"n":"עקילס","l":"ע","b":"ע\"ע אונקלוס."},{"i":3130,"n":"עקילס הגר","l":"ע","b":"ע\"ע אונקלוס."},{"i":3131,"n":"רב פדא","l":"פ","b":"הוא בר פדא."},{"i":3132,"n":"ר\u0027 פדא","l":"פ","b":"מובא בבבלי (קידושין י\"ז ע\"ב). וכן: \"א\"ר יהודה בריה דרבי חייא וכו\u0027, שמעה אילפא אמרה קמיה דרב פדא\" (זבחים י\"ג ע\"ב) ואולי צ\"ל: בר פדא."},{"i":3133,"n":"ר\u0027 פדיה","l":"פ","b":"הוא בר פדא."},{"i":3134,"n":"רבי פדת","l":"פ","b":"ע\"ע רבי פדת הזקן או רבי פדת בנו של רבי אלעזר."},{"i":3135,"n":"רבי פדת בנו של רבי אלעזר","l":"פ","b":"אמורא ארץ ישראלי בדור השלישי. בנו ותלמידו רבי אלעזר בן פדת (מו\"ק כ\u0027 ע\"א). שימש בתפקיד \"אמורא\" אצל רבי אסי (ירו\u0027, מגילה פ\"ד ה\"י). ר\"ז היה כמו חברו (נדה ח\u0027 ע\"א). רבי ירמיה מסר משמו (ירו\u0027, יומא פ\"ד ה\"ו)."},{"i":3136,"n":"רבי פדת הזקן","l":"פ","b":"חי בסוף תקופת התנאים או בתחילת תקופת האמוראים בארץ ישראל. \"יוחסין\" כתב בסדר הקבלה עם הגהות הרמ\"א: \"רבי פדת חברו של רבי, ורבי אלעזר בן פדת בנו, ורבי פדת בן אלעזר נכדו\". ומובא, שר\u0027 אלעזר בר\u0027 שמעון אמר עליו דצדיק גמור הוא (\"תיקוני זוהר\" ס\"ט), וכן מובא (\"אגרת רב שרירא גאון\"): ר\u0027 פדת קמאי בדור שלפני רבי. מובא בירושלמי, שרבי יהושע בן לוי מסר משמו (פ\"י הי\"ב)."},{"i":3137,"n":"פוגא","l":"פ","b":"שמשו של רבי יוסי בר חנינא (ב\"ב צ\u0027 ע\"ב), ואין לדעת אם היה מן החכמים. היו שמשים של אמוראים שהיו חכמים מובהקים, אך יתכן שמש שלא היה חכם כלל."},{"i":3138,"n":"פזי","l":"פ","b":"השם \"פזי\" שימש כשם גבר וכשם אשה. מצינו פזי בדור החמישי לתנאים (תוספתא אהלות פי\"ח): \"מעשה ברבי ורבי ישמעאל ברבי יוסי ורבי אלעזר הקפר ששבתו בחנותו של פזי בלוד\" (ויש גירסאות בחנותו של כותי). ויש \"פזי\" אשה, בתו של רבי חייא, אחות תאומה לטוי, שילדה לו אשתו יהודית (יבמות ס\"ה ע\"ב). ומצינו: \"ר\u0027 שמעון בן פזי\" (מגילה י\"ג ע\"א), אך תוספות כתבו (ב\"ב קמ\"ט ע\"א ד\"ה: רב) שפזי שם אמו של רבי שמעון בן פזי (ז\"א שם אשה). ומצינו: \"רבי יודה בן פזי\" (ירו\u0027, ביצה פ\"ד ה\"ד). ומצינו מפורש שפזי הוא שם גבר: \"רבי יודה בן פזי בשם רבי פזי בשם רבי יוחנן\" (ירו\u0027, סנהדרין פ\"ב ה\"ג)."},{"i":3139,"n":"רבי פטרוקי אחוה דרבי דרוסא","l":"פ","b":"אמורא ארץ ישראלי בדור החמישי. מובא בירושלמי (יומא פ\"ד ה\"ד)."},{"i":3140,"n":"רבי פילא","l":"פ","b":"אמורא ארץ ישראלי בדור הראשון. מובא בש\"ר (רפכ\"ד - ה\u0027), שאמר רבי תחליפא דקסרין משמו."},{"i":3141,"n":"פיליפא בר ר\u0027 פריט","l":"פ","b":"מובא במסכת סופרים (פכ\"א), והוא רבי פליפה בר פרוטה."},{"i":3142,"n":"פישון הגמל","l":"פ","b":"מובא בבבלי: \"תניא, אמרו להן בית הלל לבית שמאי: \u0027והלא פישון הגמל מיאנה אשתו שלא בפניו\u0027 אמרו להן בית שמאי לבית הלל: \u0027פישון הגמל וכו\u0027\" (יבמות ק\"ז ע\"ב). אין לדעת אם נמנה עם החכמים."},{"i":3143,"n":"פלטון איש רומי","l":"פ","b":"מובא (במדרש תהלים כ\"ח - ב\u0027), ונראה שהוא פלטיון איש רומי."},{"i":3144,"n":"ר\u0027 פלטיא דנוה","l":"פ","b":"אמורא ארץ ישראלי בדור החמישי. מובא בקה\"ר (פ\"א - ה\u0027) שר\u0027 שמואל אמר בשמו."},{"i":3145,"n":"פלטיון איש רומי","l":"פ","b":"מובא (שהש\"ר פ\"ח - ה\u0027). נראה, שהוא פלטון איש רומי."},{"i":3146,"n":"פלימו","l":"פ","b":"תנא בדור החמישי. שאל מרבי: \"מי שיש לו שני ראשין וכו\u0027\" (מנחות ל\"ז ע\"א), ורבי הקפיד עליו ורצה להענישו בחשבו שדרך שחוק שאל, אדהכי בא אדם ואמר לרבי שנולד לו תינוק בעל שני ראשים. ומסופר: \"פלימו אומר: \u0027אני ראיתי אותו בית\u0027\" [שרבי חנינא בן דוסא עשה בו נס] (תענית כ\"ה ע\"א). היה מופלג בחסידות ובפרישות והתגרה בשטן (קידושין פ\"א ע\"א)."},{"i":3147,"n":"רבי פליפא בר פרוטה","l":"פ","b":"מובא בירושלמי (מגילה פ\"א ה\"א), והוא פליפה בר פריטה."},{"i":3148,"n":"רבי פליפה בר פרוטה","l":"פ","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. תלמידו של רבי זירא (ירו\u0027, תענית פ\"ד ה\"ג). קיבל גם מרבי יונה (ירו\u0027, מגילה פ\"א ה\"א). שמו שובש כמה פנים: פיליפא בר ר\u0027 פריט (מס\u0027 סופרים פכ\"א), ר\u0027 פליפא בר פרוטה (ירושלמי שם). \"סה\"ד\" כתב, שמה שמצינו (ב\"ר פע\"א - ט\u0027): \"א\"ל ר\u0027 פליפי בר נהוראי\" צ\"ל: \"א\"ל ר\u0027 פליפי לרבי נהוראי\" (והוא ר\u0027 פליפה בר פרוטה)."},{"i":3149,"n":"ר\u0027 פליפי בר נהוראי","l":"פ","b":"מובא בב\"ר (פע\"א - ט\u0027). \"סה\"ד\" גורס: א\"ל ר\u0027 פליפי לר\u0027 נהוראי. ע\"ע רבי פליפה בר פרוטה."},{"i":3150,"n":"ר\u0027 פנדא","l":"פ","b":"מובא בבבלי: \"א\"ר ביזנא בר זבדא א\"ר עקיבא א\"ר פנדא א\"ר נחום אמר רבי בירים משום זקן אחד, ומנו ר\u0027 בנאה\" (ברכות נ\"ה ע\"ב); (ואם אין ט\"ס, הרי שלא ידעתי מיהו ר\u0027 פנדא זה). \"דק\"ס\" מביא כמה גירסאות: ר\u0027 פבנא ור\u0027 פרנא."},{"i":3151,"n":"פנחס","l":"פ","b":"ע\"ע פנחס בר אבא (אחיו של שמואל)."},{"i":3152,"n":"רב פנחס","l":"פ","b":"אמורא בבלי בדור החמישי. תלמידו של רבא (שבת מ\"ו ע\"ב). תירץ דברי רב פפא (שבועות כ\"ב ע\"א). רב אשי הקשה על דבריו (מו\"ק י\"ד ע\"ב)."},{"i":3153,"n":"רבי פנחס","l":"פ","b":"אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי יוסי (שהיה חברו של רבי יונה) (ירו\u0027, פסחים פ\"ה ה\"ג). חברם של רב הונא ב\u0027 ור\u0027 חזקיה (ירו\u0027, פאה פ\"ג ה\"ז). יש מדרשים מר\u0027 פנחס בר חמא שנאמרו בשם ר\u0027 פנחס סתם."},{"i":3154,"n":"פנחס אחוה דמר שמואל","l":"פ","b":"מובא בבבלי (בכורות ל\"ז ע\"א). ע\"ע פנחס בר אבא."},{"i":3155,"n":"רבי פנחס בי ר\u0027 חנינא","l":"פ","b":"אמורא ארץ ישראלי בדור החמישי. מובא בירושלמי (שקלים פ\"ב ה\"א), שחלק עם ר\u0027 אבא מרי."},{"i":3156,"n":"רבי פנחס בן יאיר","l":"פ","b":"תנא בדור החמישי. מקומו בלוד (תוספתא סוף אהלות). חתנו של רבי שמעון בן יוחאי (שבת ל\"ג ע\"ב). קודם שישב רבי שמעון בן יוחאי במערה, היה ר\u0027 פנחס בן יאיר מתרץ את קושיות רשב\"י, ולאחר שיצא רשב\"י מהמערה, היה רשב\"י מתרץ בעשרים וארבעה תירוצים את קושיות ר\u0027 פנחס בן יאיר (שם). היה חברו של רבי (חולין ז\u0027 ע\"ב), וכשראה פרדות לבנות בביתו של רבי סירב לאכול אצלו, ואמר: \"מלאך המות בביתו של זה ואני אסעד אצלו?\" (שם). היה מופלג בחסידות ובפרישות. מימיו לא נהנה משל אחרים. ומיום שעמד על דעתו לא נהנה מסעודת אביו (שם). היה זהיר ביותר במצוות מעשר, ומסופר שאפילו חמורו סירב לאכול תבואה בלתי מעושרת (שם). היה מלומד בנסים, וכשהלך למצות פדיון שבויים, נבקעו מי הנהר לפניו (שם ע\"א). בירושלמי מסופרים עליו נסים רבים. וממנו מאמר: \"א\"ר פנחס בן יאיר תורה מביאה לידי זהירות, זהירות מביאה לידי זריזות, זריזות מביאה לידי נקיות, נקיות מביאה לידי פרישות, פרישות מביאה לידי טהרה, טהרה מביאה לידי קדושה, קדושה מביאה לידי ענוה, ענוה מביאה לידי יראת חטא, יראת חטא מביאה לידי חסידות, חסידות מביאה לידי רוח הקודש רוח הקודש מביאה לידי תחית המתים\" (ע\"ז כ\u0027 ע\"ב). בעל \"מסילת ישרים\" (רמח\"ל) ביסס את ספרו על מאמר זה. מקום קבורתו בצפת. \"סה\"ד\" כתב: \"קבורתו בכפר ברעם\"."},{"i":3157,"n":"ר\u0027 פנחס בן לוי","l":"פ","b":"מובא בירושלמי (שקלים פ\"ב)."},{"i":3158,"n":"רבי פנחס בן ערובה","l":"פ","b":"תנא בדור השני. מובא בבבלי \"אני הייתי בין גדולי רומי וכשמת טיטוס [הרשע שהחריב את בית המקדש] פצעו את מוחו ומצאו יתוש כצפור דרור משקל ב\u0027 סלעים\" (גיטין נ\"ו ע\"ב). רבי יוחנן (האמורא) אמר משמו (בכורות ל\"ח ע\"ב)."},{"i":3159,"n":"רב פנחס בן רב חסדא","l":"פ","b":"אמורא בבלי בדור הרביעי. גיסו של רבא. מסופר שהיה בחתונת בנו של רבא יחד עם אחיו רב מרי (קידושין ל\"ב ע\"ב). זכה לגילוי אליהו (כתובות ס\"א ע\"א)."},{"i":3160,"n":"פנחס בר אבא","l":"פ","b":"אמורא בבלי בדור הראשון. אחיו של שמואל (חברו של רב). ושאל משמואל שאלה שלא ידע להשיב עליה (בכורות ל\"ט ע\"א): קרי שמואל עליה \"פוסחים בזזו\" פרש\"י: \"כלומר, אתה אינך מחודד ושאלת שאלה כזו שאיני יודע תשובה\". הוא ושמואל נשאו אחיות לנשים (סנהדרין כ\"ח ע\"ב). שמואל הלך לבקר את פנחס אחיו כשהיה אבל, ובגלל פליטת פיו של פנחס נעשה גם שמואל אבל (מו\"ק י\"ח ע\"א)."},{"i":3161,"n":"ר\u0027 פנחס בר אבין","l":"פ","b":"מובא במ\"ר (פי\"א)."},{"i":3162,"n":"ר\u0027 פנחס בר אידי","l":"פ","b":"מובא מ\"ר (פ\"א - י\"א)."},{"i":3163,"n":"ר\u0027 פנחס בר זבאי","l":"פ","b":"מובא בירושלמי (מו\"ק פ\"ב ה\"א)."},{"i":3164,"n":"ר\u0027 פנחס בר חייא הכהן","l":"פ","b":"מובא בתנחומא (נ\"ח - ה\u0027), וכנראה שצ\"ל: ר\u0027 פנחס בר חמא (מ\u0027 הפך לשני יודים) הכהן."},{"i":3165,"n":"רב פנחס בר חמא הכהן","l":"פ","b":"אמורא ארץ ישראלי בדור הרביעי. מבעלי האגדה. מוזכר הרבה במדרשים. פעמים מובא כסתם רבי פנחס או רבי פנחס הכהן. קיבל מגדולי דורו ומסר מדורות שלפניו, מרבי יוחנן (ירו\u0027, ברכות פ\"ב ה\"א) ומרבי שמעון בן לקיש (ירו\u0027, שקלים פ\"ו ה\"א). האומרים בשמו: ר\u0027 יוחנן דיפו (מ\"ר פכ\"ב - כ\"ד) ור\u0027 יהודה נשיאה ג\u0027 (רו\"ר ספ\"ה). היה לו אח ושמו ר\u0027 שמואל, שמת בחייו (מד\u0027 שמואל פ\"ט - ג\u0027)."},{"i":3166,"n":"ר\u0027 פנחס בר ראובן","l":"פ","b":"\"סה\"ד\" כתב: \"ובילקוט ר\u0027 פנחס בר\u0027 ראובן ט\"ס וצ\"ל: בש\"ר ראובן (ר\u0027 פנחס בשם ר\u0027 ראובן)\"."},{"i":3167,"n":"רב פנחס בריה דרב אמי","l":"פ","b":"אמורא בבלי בדור החמישי. חברם הגדול של רב פפא ורב הונא בריה דרב יהושע (כתובות פ\"ה ע\"א). מרבותיו של רב אשי (זבחים ז\u0027 ע\"ב). ומצינו: \"מרימר, ואיתימא רב יימר, איקלע לפרקיה דרב פנחס בריה דרב אמי, וקם תנא ותני קמיה\" (כתובות ק\u0027 ע\"א)."},{"i":3168,"n":"רב פנחס בריה דרב מרי","l":"פ","b":"מובא בבבלי (זבחים צ\u0027 ע\"ב), וגירסת \"דק\"ס\": \"בריה דרב אמי\"."},{"i":3169,"n":"ר\u0027 פנחס בריה דר\u0027 שמעון","l":"פ","b":"מובא ב\"ילקוט\" (רות רמז תר\"ה), אבל הגירסא ברו\"ר (סוף פ\"ו): ר\u0027 פנחס בר חמא."},{"i":3170,"n":"ר\u0027 פנחס דדהובא","l":"פ","b":"מובא בקה\"ר (פ\"ב - ב\u0027): \"א\"ר פנחס דדהובא מערבב וכו\u0027\". ו\"סה\"ד\" כתב: \"אל יטעך לבך דשם מקום הוא כי ט\"ס הוא, וצ\"ל: דחוכה מערבב וכו\u0027\" (כלומר אמר ר\u0027 פנחס, דחוכה מערבב וכו\u0027)."},{"i":3171,"n":"ר\u0027 פנחס דיפו","l":"פ","b":"מובא בירושלמי (פסחים פ\"א ה\"א)."},{"i":3172,"n":"ר\u0027 פנחס החבר","l":"פ","b":"אמורא ארץ ישראלי בדור החמישי. מובא בש\"ר (פ\"א - י\"ד) שמסר בשם רבי יונה."},{"i":3173,"n":"ר\u0027 פנחס צפוראה","l":"פ","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בבבלי, שר\u0027 פנחס מסר משמו (יומא ע\"ז ע\"ב). כך גירסת \"דק\"ס\" ו\"יוחסין\". ו\"סה\"ד\" כתב: \"לא מצאתי זכרו\". ולפנינו: רב הונא צפוראה."},{"i":3174,"n":"פנימין","l":"פ","b":"מובא בילקוט המכירי (תהלים פכ\"ה - י\"ד), ואולי צ\"ל מינימון (כמו בירו\u0027, סוטה פ\"א ה\"ב)."},{"i":3175,"n":"רבי פס","l":"פ","b":"מובא בירושלמי (קדושין פ\"ג ה\"ה), והוא רבי אפס."},{"i":3176,"n":"רב פפא","l":"פ","b":"מגדולי אמוראי בבל בדור החמישי. תלמידם המובהק של אביי (פסחים קי\"א ע\"ב) ורבא (כתובות פ\"ה ע\"א). והיה תלמיד כל כך מובהק לרבא, עד שאמרו תוספות (שבת כ\"ז ע\"ב) שהתלמידים לא ידעו אם רב פפא אמר משם עצמו או משם רבו רבא. ולאחר פטירתו של רבא, כשנחלקה ישיבת מחוזא לשנים, מלך רב נחמן בר יצחק בפומבדיתא, ורב פפא מלך תשע עשרה שנה בנרש (\"אגרת רב שרירא גאון\") וחברו המובהק: רב הונא בריה דרב יהושע שימש על ידו כראש כלה (ברכות נ\"ז ע\"א, \"אגרת רב שרירא גאון\"), ושניהם הגיעו להוראה עוד בחיי רבא (ב\"ב ק\"ל ע\"ב). היו לו תלמידים רבים, ביניהם מאתיים מתלמידיו שהיו מאוכלי שולחנו (כתובות ק\"ו ע\"א). בין תלמידיו היה רב אשי (ע\"ז מ\u0027 ע\"א). רבינא הקשה לרב פפא (ב\"מ ע\"ד ע\"ב). התנהג לפנים משורת הדין (כתובות צ\"ז ע\"א). על בנו אבא העיד רב פפא, שמעולם לא הוציא דבר שקר מפיו (כתובות פ\"ה ע\"א). היה עשיר גדול (ב\"מ מ\"ו ע\"א). בתחילה היה עני (הוריות ו\u0027 ע\"ב) התעשר מעשיית שכר (פסחים קי\"ג ע\"א). אשתו היתה כהנת ותלה את עושרו בזכותה (שם מ\"ט ע\"א). שם אביו של רב פפא לא מוזכר בש\"ס, ולפי דעת ה\"ערוך\" (ערך בר) היה שם אמו אושפרתי (תענית כ\"ד ע\"ב). פעם אחת גבר על רבו אביי והקפיד עליו אביי, ואמר: \"כמדומה אני שיש לך אב ואם סמוכין לך לספק צרכיך לפיכך אתה חריף מדי\", והענישם ומתו הוריו. ואחר פטירתו של רב פפא מלך רב אשי (\"אגרת רב שרירא גאון\")."},{"i":3177,"n":"רב פפא בר אבא","l":"פ","b":"אמורא בבלי בדור החמישי. היה בימיו של רב פפא, שאמר כגון: \"כלתיה דבי רב פפא בר אבא\" (יבמות כ\"א ע\"ב). היו לו בנים חכמים ושאלו מרב פפא (שבת קי\"ט ע\"א)."},{"i":3178,"n":"רב פפא בר אבא רישבא","l":"פ","b":"אמורא בדור הרביעי. מובא בבבלי, ששאל מרבי אבא (חולין נ\"ד ע\"א). \"סה\"ד\" כתב: \"וה\u0027יוחסין\u0027 לא הביאו, כמדומה, שלא היה חכם. וצריך לומר: דבי פפא בר אבא רישבא ולא רב פפא\"."},{"i":3179,"n":"רב פפא בר יעקב","l":"פ","b":"מובא בבבלי (חגיגה י\"ד ע\"א). גירסת \"עין יעקב\": רב אחא בר יעקב. מובא ב\"ילקוט\" (ישעיה רמז ס\"ג)."},{"i":3180,"n":"רב פפא בר שמואל","l":"פ","b":"אמורא בבלי בדור הרביעי. תלמידם של רב ששת (כתובות ל\"ז ע\"א) ורב חסדא (שבת נ\"ד ע\"ב). תירץ קושית רב חסדא (פסחים מ\"ז ע\"ב). היה ראש הדיינים בפומבדיתא: \"דייני דפומבדיתא - רב פפא בר שמואל\" (סנהדרין י\"ז ע\"ב). רבא היה חברו (ר\"ה י\"ז ע\"א), ועל ספורי נפלאותיו של רבה בר בר חנה אמר, שאילולי היה שם לא היה מאמין (ב\"ב ע\"ג ע\"ב)."},{"i":3181,"n":"רב פפא בריה דרב אחא בר אדא","l":"פ","b":"אמורא בבלי בדור הרביעי - החמישי. מסר בשם אביו ששמע מרב (ברכות כ\"ט ע\"ב). אמר לאביי (לגירסת השאלתות): \"הכי אמרינן משמיה דרבא\" (סנהדרין כ\"ט ע\"ב). רבא התקיף לה על מימרא שאמר (עירובין כ\"א ע\"ב)."},{"i":3182,"n":"רב פפא בריה דרב חנין (2)","l":"פ","b":"אמורא בבלי בדור הרביעי. תלמידו של רב יוסף (מנחות כ\"ח ע\"ב). רב יוסף אמר לו: \"סמי דידך מקמי דידי וכו\u0027\"."},{"i":3183,"n":"רב פפא בריה דרב חנן מבי כלוחית","l":"פ","b":"אמורא בבלי בדור הששי. נראה, שהיה תלמידו של רב שימי בר אשי (כתובות מ\u0027 ע\"ב). \"סה\"ד\" איחד את רב פפא בריה דרב חנן מבי כלוחית עם רב פפא בריה דרב חנין לאחד."},{"i":3184,"n":"רב פפא בריה דרב יוסף","l":"פ","b":"אמורא בבלי בדור הרביעי. בנו ותלמידו של רב יוסף. מובא בבבלי, שתירגם לפני אביו (ב\"מ קי\"ג ע\"ב)."},{"i":3185,"n":"רב פפא בריה דרב נחמן","l":"פ","b":"אמורא בבלי בדור הרביעי. תלמידו של רב יוסף, ותירגם לפני רב נחמן (ב\"מ קי\"ג ע\"א)."},{"i":3186,"n":"רב פפא סבא","l":"פ","b":"אמורא בבלי בדור השני. תלמידו של רב (קידושין מ\"ט ע\"ב). \"סה\"ד\" כתב שהיו לו י\"א בנים: דארו, סורחב, רכיש, רפרם, אבא, אחא, רמי, חנינא, אבא מרי, נחמן, אדא. \"יוחסין\" כתב, \"שקיבל מאביו שקיבל מחכמים וזקנים שמועילים לשכחה ויאמרו אותם ז\u0027 פעמים\". ספר \"האשכול\" כתב, שי\"א בני רב פפא אינם מרב פפא אחד, אלא היו בזמנים שונים ויש לו קבלה שמועילים לשכחה, ועל כן נהגו להזכירם כשמסיימים מסכתא."},{"i":3187,"n":"פפא תוראה","l":"פ","b":"חי בבבל בדור החמישי לאמוראים: \"אורי ליה רב פפא לפפא תוראה\" (גיטין י\"ט ע\"א), ופרש\"י: \"ספסר של שוורים\". נראה לומר, שלא נמנה עם החכמים. \"יוחסין\" ו\"סה\"ד\" לא הביאו שמו."},{"i":3188,"n":"פפוס","l":"פ","b":"ע\"ע ליליינוס ופפוס."},{"i":3189,"n":"פפוס בן יהודה","l":"פ","b":"תנא בדור השלישי. חברו של רבי עקיבא. כשמצא את רבי עקיבא מקהיל קהילות ברבים ועוסק בתורה אמר לו עקיבא: \"אי אתה מתירא מפני המלכות\", לבסוף נתפסו שניהם, ואמר פפוס בן יהודה לרבי עקיבא: \"אשריך ר\"ע שנתפסת על דברי תורה, אוי לו לפפוס שנתפס על דברים בטלים\" (ברכות ס\"א ע\"ב). ומצינו: \"דריש פפוס וכו\u0027 א\"ל: \u0027ר\"ע דייך פפוס\u0027\" (מכילתא פ\u0027 בשלח)."},{"i":3190,"n":"רב פפי","l":"פ","b":"אמורא בבלי בדור החמישי. תלמידו של רבא (פסחים ז\u0027 ע\"א). חברו של רב פפא ורב הונא בריה דרב יהושע, ושקיל וטרי עמם (כתובות ס\u0027 ע\"ב). היה חברו של רב ביבי בר אביי (יבמות ע\"ה סע\"ב). רב אשי היה תלמידו (ר\"ה כ\"ט ע\"ב). נראה, שגם רבינא קיבל ממנו (ב\"מ נ\"ד ע\"ב). היה חתנו של רבי יצחק נפחא (חולין ק\"י ע\"א)."},{"i":3191,"n":"רבי פפייס","l":"פ","b":"תנא בדור השני. העיד יחד עם רבי יהושע [רבו של רבי עקיבא]. (עדיות פ\"ז מ\"ו). סיפר מעשה מימי הבית (שם)."},{"i":3192,"n":"רבי פרוזדק","l":"פ","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. אמר בשם רבי יהודה בר סימון (מד\u0027 תהלים רפצ\"א)."},{"i":3193,"n":"ר\u0027 פרורי","l":"פ","b":"מובא בירושלמי (פאה פ\"ז ה\"ג), והוא רבי פרידא."},{"i":3194,"n":"ר\u0027 פרחיה","l":"פ","b":"מובא ב\"זוהר\" (חדש רות)."},{"i":3195,"n":"רבי פרטא","l":"פ","b":"תנא בדור הרביעי - החמישי. חי בימי רבי ודן עמו בהלכה, ואמר לו \"א\"כ מה כח ב\"ד יפה\" (כתובות ק\u0027 ע\"א). נכדו של רבי פרטא הגדול (שם)."},{"i":3196,"n":"ר\u0027 פרטא בנו של ר\"א בן פרטא","l":"פ","b":"ע\"ע רבי פרטא הגדול."},{"i":3197,"n":"רבי פרטא הגדול","l":"פ","b":"תנא בדור הראשון - השני. מובא בבבלי (כתובות ק\u0027 ע\"א). בנו רבי אליעזר בן פרתא, שהיה חברו של ר\u0027 חנינא בן תרדיון. ונכדו רבי פרטא, חי בזמן רבי (ע\"ע ר\u0027 פרטא בנו של ר\"א בן פרטא)."},{"i":3198,"n":"ר\u0027 פריגורי דקיסרין","l":"פ","b":"אמורא ארץ ישראלי בדור השלישי. מובא בירושלמי (תרומות פי\"א ה\"ב)."},{"i":3199,"n":"רבי פרידא","l":"פ","b":"אין לקבוע את זמנו המדוייק ואם היה תנא או אמורא. מובא בבבלי, שהוסיפו לו 004 שנות חיים על שחזר עם תלמידו 004 פעם את לימודו (עירובין נ\"ד ע\"ב). הרמב\"ם כתב בהקדמה לפי\u0027 המשניות שר\u0027 פרידא נולד קודם לחורבן. מצינו שהיה בימי רבי (ירו\u0027, פאה פ\"ז ה\"ג), וכן מצינו שהיה בימי רבי אמי ושאל ממנו (מנחות נ\"ב ע\"ב), ראה את ר\u0027 עזרא בר בריה דר\u0027 אבטילס שהיה דור עשירי לר\u0027 אלעזר בן עזריה (שם נ\"ג ע\"א)."},{"i":3200,"n":"רבי פרירא","l":"פ","b":"כן גירסת \"סה\"ד\" מירושלמי (פאה פ\"ז ה\"ג), ולפנינו \"רבי פרידא\"."},{"i":3201,"n":"רבי פרנק","l":"פ","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (שבת י\"ד ע\"א). מסר גם בשם רבי חנינא (ירו\u0027, פסחים פ\"ה ה\"ז). מצינו: \"אמר רבי פרנק אמר רבי יוחנן: \u0027כל שהוא תלמיד חכם ובנו תלמיד חכם ובן בנו תלמיד חכם, שוב אין תורה פוסקת מזרעו לעולם\u0027\" (ב\"מ פ\"ה ע\"א)."},{"i":3202,"n":"פשפשה","l":"פ","b":"מובא בירושלמי: \"פשפשה א\"ר יוסי: שאלית לרבי אחא ושרא וכו\u0027\" (שבועות פ\"ו ה\"א). בפשטות משמע, שהיה פשפשה אמורא בדור החמישי, והיה תלמידו של רבי יוסי (חברו של ר\u0027 יונה). \"פני משה\" פירש, שפשפשה שם איש ששאל לר\u0027 אחא ושרא ליה, ואם כן, לדעתו נמנה עם החכמים. הספר \"אהבת ציון\" מפרש: \"פשפשה הוא כמו שצריכין לבדוק ואינו שם איש\"."},{"i":3203,"n":"רבי צדוק","l":"צ","b":"תנא בדור הראשון. ישב ארבעים שנה בתענית שלא תחרב ירושלים (גיטין נ\"ו ע\"א). רבי יוחנן בן זכאי ביקש מאספסינוס שירפאו את ר\u0027 צדוק (שם). ורבי יוחנן בן זכאי קם לפניו (איכ\"ר פ\"א - ה\u0027). עליו מסופר: \"מעשה בשני כהנים וכו\u0027 עמד רבי צדוק על מעלות האולם ואמר וכו\u0027\" (יומא כ\"ג ע\"א). היה חברם של ר\"א ור\u0027 יהושע, ואמר להם: \"עד מתי אתם מניחים כבודו של מקום\" (קידושין ל\"ב ע\"ב). כשהורידו את ר\"ג מנשיאותו אמרו: \"אשתקד צעריה בבכורות במעשה דר\u0027 צדוק\" (ברכות כ\"ז ע\"ב). בנו הוא ר\"א בר\u0027 צדוק."},{"i":3204,"n":"ר\u0027 צדוק בן חלוקה","l":"צ","b":"אמורא ארץ ישראלי בדור הראשון. תלמידו של רבי יוסי בן זמרא: \"אמר רבה בר בר חנא: שאלו את רבי אלעזר (בן פדת) וכו\u0027\", \"עמד ר\u0027 צדוק בן חלוקה על רגליו ואמר: אני ראיתי את ר\u0027 יוסי בן זמרא שזקן ויושב בישיבה היה וכו\u0027\" (יומא ע\"ח ע\"א)."},{"i":3205,"n":"רבי קורייס","l":"ק","b":"מובא בירושלמי (ערלה פ\"ב ה\"ב)."},{"i":3206,"n":"רב קטינא","l":"ק","b":"אמורא בבלי בדור השני. מתלמידי ריש לקיש (בכורות מ\"ד ע\"ב). אולי היה זמן - מה בארץ ישראל. מרבותיו של רב חסדא (ב\"מ ע\"ט ע\"א). מצינו: \"אמר ליה רב מרדכי לרבא: \u0027יתיב רק קטינא תיובתא\u0027\" (שבת נ\u0027 ע\"ב). יש ממנו כמה מאמרי אגדה בש\"ס. היה מופלג בחסידות וזכה לגילוי מלאכים ואף דיבר עמם בדברי הלכה (מנחות מ\"א ע\"א). מסופרות נפלאות נוספות עליו (ברכות כ\"ט ע\"א). גם בנו רב דניאל בר קטינה היה מופלג בחסידות ובעל מופת (תענית ט\u0027 ע\"ב)."},{"i":3207,"n":"ר\u0027 קיסמא בן גירי","l":"ק","b":"\"מובא בזוהר\" (חדש רות צ\"ו) יחד עם רב רחומי (שלשה רב רחומי היו: א\u0027 בדור הרביעי, ב\u0027 בדור השביעי וג\u0027 בדור השמיני ואף נמנה על הסבוראים)."},{"i":3208,"n":"ר\u0027 קיריס דאירמא","l":"ק","b":"מובא בירושלמי (ביצה פ\"ג ה\"ח). מאמרו: \"מי שיש בידו למחות ואינו מוחה, קלקלה תלויה בו\". ואותו מאמר מובא בירושלמי בשם רבי קיריס דידמא (שבת ספ\"ה) והוא ר\u0027 קיריס דאירמא."},{"i":3209,"n":"ר\u0027 קיריס דידמא","l":"ק","b":"מובא בירושלמי (שבת ספ\"ה) והוא ר\u0027 קיריס דאירמא."},{"i":3210,"n":"קלא","l":"ק","b":"חי בדור השלישי - הרביעי לאמוראים. \"וכן אורי ליה ר\u0027 אבא לקלא: \u0027הלכה כר\u0027 יוסי\u0027\" (נדה נ\"ט ע\"ב). התוספות כתבו: \"נראה דקלא שם חכם\", ורש\"י כתב: \"שם אדם שהוצרך לדבר\". נראה לי, שרש\"י לא סבר שהוא חכם, שכן כשהשם הוא של חכם הוא נוהג לכתוב זאת כגון \"ניולי - שם חכם\" (חולין מ\"ה ע\"ב). \"בריבי שם חכם\" (שם נ\"ב ע\"ב); \"מבוג שם חכם\" (זבחים ט\u0027 ע\"ב); \"בר קזא - שם חכם\" (כתובות ק\"ד ע\"א); \"איו - שם חכם\" (עירובין ל\"ו ע\"ב); \"בלווטי - שם חכם\" (ערכין י\"א ע\"א); ואמנם מצינו שרש\"י כתב \"טבי - שם האיש\" (שבת י\"ז ע\"ב) והוא היה החכם טבי רישבא תלמידו דשמואל."},{"i":3211,"n":"ר\u0027 קצרה","l":"ק","b":"אמורא ארץ ישראלי בדור השני. מובא בתנחומא (ויחי) שהלך עם רבי אלעזר ליד טבריה."},{"i":3212,"n":"רבי קרוספאי","l":"ק","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (כריתות כ\"ד ע\"א). מסר גם בשם ריש לקיש (ירו\u0027, יבמות רפ\"א). בשמו מסרו רבי יונה (ירו\u0027, כתובות פ\"א ה\"א), ורבי יוסי (ירו\u0027, מע\"ש פ\"ד ה\"ב). נפטר בחיי רבי אמי (ירו\u0027, סוף מו\"ק). שמו השתבש בכמה פנים: ר\u0027 כרוספדאי (כריתות שם), ר\u0027 קריספי (ירו\u0027, סוף מו\"ק), ר\u0027 קריצפי (מד\u0027 משלי פ\"ד - כ\"ז), ר\u0027 קרציפא (ויק\"ר פ\"ד - ב\u0027), ר\u0027 קריספדא (ירו\u0027, שבת פ\"א ה\"ד), ר\u0027 קרוצפי (קה\"ר פ\"ד - ז\u0027), ר\u0027 קריספא (ירו\u0027, מע\"ש פ\"ד ה\"ב)."},{"i":3213,"n":"רב קרוספי","l":"ק","b":"מובא בירושלמי (סוף מו\"ק), והוא רבי קרוספאי."},{"i":3214,"n":"רבי קרוצפי","l":"ק","b":"מובא בקה\"ר (פ\"ד - י\"ז), והוא רבי קרוספאי."},{"i":3215,"n":"רבי קריספא","l":"ק","b":"מובא בירושלמי (מע\"ש פ\"ד - ה\"ב), ר\u0027 יוסי בשם ר\u0027 קריספא, והוא רבי קרוספאי."},{"i":3216,"n":"רבי קריספאי","l":"ק","b":"הוא ר\u0027 קרוספאי."},{"i":3217,"n":"רבי קריספדא","l":"ק","b":"מובא בירושלמי (שבת פ\"א ה\"ד), והוא רבי קרוספאי."},{"i":3218,"n":"רבי קריצפי","l":"ק","b":"מובא במדרש משלי (פ\"ד - כ\"ז), והוא רבי קרוספאי."},{"i":3219,"n":"קרנא","l":"ק","b":"אמורא בבלי בדור הראשון. והוא ושמואל מכונים: \"דייני גולה\" (סנהדרין י\"ז ע\"ב), וכן גיר\u0027 הרשב\"ם (ב\"ב ק\"ז ע\"ב). שמואל הענישו (ב\"ב פ\"ט ע\"א), ומשמע שהיה תלמידו, וחלק עמו (קידושין מ\"ד ע\"ב) וכשרב בא לבבל, שלח שמואל את קרנא לתהות על קנקנו, ורב הקפיד והענישו (שבת ק\"ח ע\"א). חיבר ברייתות הקרויות \"נזיקין דבי קרנא\" (ב\"ק מ\"ז ע\"ב)."},{"i":3220,"n":"רבי קרציפא","l":"ק","b":"מובא בויק\"ר (פ\"ד - ב\u0027), והוא רבי קריספאי."},{"i":3221,"n":"ר חסדיי","l":"ר","b":"כך נקרא לפעמים ר\u0027 חסדא בירושלמי."},{"i":3222,"n":"רבי ראובן (2)","l":"ר","b":"אמורא ארץ ישראלי בדור השני - השלישי. מובא בבבלי: \"שלח משמיה דרבי יוחנן\" (מנחות נ\"ז ע\"ב), אבל גיר\u0027 רש\"י: \"שלח רבין משמיה דרבי יוחנן\" (שם). כן: (ירו\u0027, כתובות פי\"א ה\"ז), \"רבי אבין בעא קומי רמי מנא [א]. ו\"סה\"ד\" גרס: \"ר\u0027 ראובן\". בשמו מסרו: רבי פנחס (תנחומא בראשית) ורבי ביבי (ירו\u0027, סנהדרין פ\"א ה\"א)."},{"i":3223,"n":"ר\u0027 ראובן איצטרובילי","l":"ר","b":"הוא רבי ראובן איסטרובלי."},{"i":3224,"n":"ר\u0027 ראובן בן איסטרובלי","l":"ר","b":"תנא בדור הרביעי. היה מקורב למלכות בזמן רבי שמעון בן יוחאי (מעילה י\"ז ע\"א). פעם גזרה המלכות גזרה שלא ישמרו את השבת ולא ימולו את בניהם, והוא בחכמתו גרם לביטול זמני של הגזרה (שם). שני בניו היו תלמידיו של רבי (ירו\u0027, כלאים פ\"ט ה\"ג). רב מסר בשמו (מו\"ק י\"ח ע\"ב)."},{"i":3225,"n":"רבי ראובן בן אצטרובילי","l":"ר","b":"מובא בבבלי (מו\"ק י\"ח ע\"ב), והוא ר\u0027 ראובן בן איסטרובלי."},{"i":3226,"n":"ר\u0027 ראובן בר איסטרובילוס","l":"ר","b":"מובא בירושלמי (כלאים פ\"ט ה\"ג), והוא ר\u0027 ראובן בן איסטרובלי."},{"i":3227,"n":"ראמי בר תמרי","l":"ר","b":"מובא בבבלי (מנחות כ\"ט ע\"ב), והוא רמי ברי תמרי. ותיבת \"חמוה\" שם נראית ט\"ס, ונראה שצ\"ל: ראמי (רמי) בר תמרי, הוא רמי בר דיקולי (חולין ק\"י ע\"א)."},{"i":3228,"n":"רב","l":"ר","b":"אמורא בבלי בדור הראשון. מגדולי האמוראים. נפטר בשנת ד\u0027 ו\u0027 (642) (\"אגרת רב שרירא גאון\"). רב תנא הוא ופליג (עירובין נ\u0027 ע\"ב). מוזכר פעמים בברייתא (כתובות פ\"א ע\"א; שם מ\"ט ע\"א). שמו היה אבא, בלשון כבוד קראו לו: בבבל \"רב\" כמו שקראו \"רבינו\" לרבי יהודה הנשיא בא\"י (ב\"ב קי\"ט ע\"ב רשב\"ם). יש אומרים, שבכל מקום שנאמר בש\"ס: \"והאמר מר\" הכוונה לרב. מובא ג\"כ בהג\"ה בהקדמת הרמב\"ם לסדר זרעים. עלה לא\"י ולמד תורה מר\u0027 חייא, שהיה דודו (סנהדרין ה\u0027 ע\"א) ורבו המובהק (מו\"ק ט\"ז ע\"ב). גם רבי היה רבו המובהק (חולין קל\"ז ע\"ב). כשרב שימש את רבי בישיבה, עדיין שימש רבי יוחנן את רבי בעמידה (שם נ\"ד ע\"א), וכשר\u0027 יוחנן שימש את רבי בישיבה, ישב 71 שורות מאחרי רב (שם קל\"ז ע\"ב). את רבי היה מכנה \"רבינו הקדוש\" (ביצה כ\"ב ע\"ב). למד עם חברו לוי לפני רבי (שם כ\"ד ע\"ב). נמנה עם חשובי החכמים בא\"י ופסיק סידרא קמיה רבי ור\u0027 חייא, ובר קפרא, ור\u0027 שמעון בן רבי ואחר בא גם ר\u0027 חנינא בר חמא (יומא פ\"ז ע\"ב). נמנה עם בית דינו של רבי (גיטין נ\"ט ע\"א). ירד לבבל ומשם שלח שאלותיו לרבי (כתובות ס\"ט ע\"א). אח\"כ חזר לא\"י (ירו\u0027, סוטה פ\"ט ה\"ה; פסחים ד\u0027 ע\"א). נראה שנשאר בא\"י עד לאחר פטירת רבי (ירו\u0027, חגיגה פ\"א ה\"ח). בשנת ג\u0027 תתקע\"א (812) ירד לבבל והשתקע שם (\"אגרת רב שרירא גאון\"). כשהגיע לבבל לא הכירו שמואל (שבת ק\"ח ע\"א), וגם חכמים אחרים לא הכירוהו (יומא כ\u0027 ע\"ב). אח\"כ הפכו רב ושמואל לחברים. היה גדול משמואל (כתובות כ\"ב ע\"א), ושמואל היה כפוף לו (מגילה כ\"ב ע\"א). הניח לשמואל להיות הראש בנהרדעא, וייסד ישיבה בסורא (גיטין ו\u0027 ע\"א רש\"י). ישיבתו התקיימה כ - 008 שנה עד סוף תקופת הגאונים (\"אגרת רב שרירא גאון\"). תלמידיו מנו אלפים (כתובות ק\"ו ע\"א). מבין גדולי תלמידיו: רב הונא (שבת קכ\"ח ע\"א), רב יהודה (קדושין פ\"א ע\"א), ורבי חננאל (פסחים ק\"ג ע\"א), היו לו גם תלמידי - חברים: רבי ירמיה בר אבא (ברכות כ\"ז ע\"ב), רב כהנא ורב אסי (שבת קמ\"ו ע\"ב רש\"י). רב ושמואל נקראו בש\"ס: \"רבותינו שבבבל\" (סנהדרין י\"ז ע\"ב). הש\"ס מלא במחלוקותיהם הקרויות \"הוויות דרב ושמואל\" (ברכות ל\u0027 ע\"א). תלמידיו קראו לו: \"רבנו הגדול\" (סוכה ל\"ג ע\"א). רש\"י פירש: \"ומאדם חשוב כמו רב וכו\u0027 פרכינן כאילו כתוב במשנה\" (ב\"ק ל\"ג ע\"ב) וכן: \"ואע\"ג דרב אמורא הוא, מקשי מיניה, מפני שרבן של כל בני הגולה היה חוץ משמואל\" (ביצה ט\u0027 ע\"א). ההלכה נקבעה כרב בדיני איסורים, וכשמואל בדיני ממונות (בכורות מ\"ט ע\"ב). נהג בחסידות מופלגת (\"תשובות הגאונים\", \"שערי תשובה\" סימן קע\"ח). כשבא לבבל היה עני גדול: \"אין לו מה יאכל הוה\" (מו\"ק י\"ב ע\"ב), אח\"כ התעשר: \"והאמר רב: \u0027לא איעתרי עד וכו\u0027\" (ברכות נ\"ז ע\"ב) כמה מן התפלות הנאמרות התקין רב: \"יהי רצון וכו\u0027 חיים ארוכים וכו\u0027\", שאומרים בשבת מברכים ראש חודש (ברכות ט\"ז ע\"ב). \"אתה זוכר\" בתפילת מוסף של ראש השנה (ירו\u0027, ר\"ה פ\"א ה\"ג), וכן \"תודיענו\" למוצש\"ק מכונה: \"מרגניתא\", שרב ושמואל התקינו בבבל (ברכות ל\"ב ע\"ב). כשנפטר קרע עליו שמואל 21 בגדים (מו\"ק כ\"ד ע\"א), ותלמידיו באו לפני שמואל (ברכות י\"ב ע\"א). אשתו ציערה אותו (יבמות ס\"ג ע\"א). את בנו חייא לימד בעצמו (פסחים ע\u0027 ע\"א). בנו השני איבו ניהל את ענייניו המסחריים (פסחים קי\"ג ע\"א). שלש בנות היו לו, אחת נישאה לתלמידו רב חנן בר רבא (חולין צ\"ה ע\"ב), אחת היתה אם החכמים: איבו וחזקיה (סוכה מ\"ד ע\"ב) ואחת היתה אם האחים רבנא עוקבא ורבנא נחמיה, שהיו עשירים ומקורבים למלכות (חולין צ\"ב ע\"א)."},{"i":3229,"n":"רבא (2)","l":"ר","b":"מגדולי אמוראי בבל ומראשי הדור הרביעי. אביו היה האמורא רב יוסף בר חמא (עירובין נ\"ד ע\"א). רש\"י כתב: \"רבא בריה דרב יוסף בר חמא (כצ\"ל) הוא והוא רבא בכולי גמרא בר פלוגתיה דאביי\" (חולין מ\"ג ע\"ב). היה ראש ישיבת מחוזא ארבע עשרה שנה נפטר בשנת ד\u0027 קי\"א (153). במותו נחלקה ישיבת מחוזא לשתים: רב נחמן בר יצחק תלמידו מלך בפומבדיתא ורב פפא תלמידו מלך בנרש (\"אגרת רב שרירא גאון\"). רב נחמן היה רבו המובהק (ברכות כ\"ג ע\"ב). רבא היה אצלו כשרב נחמן נפטר (מו\"ק כ\"ח ע\"א). וגם רב חסדא היה רבו (קידושין נ\"ג ע\"ב), וכן היה חותנו (יבמות ל\"ד ע\"ב). גם רב יוסף היה רבו המובהק (יומא נ\"ג ע\"א). וכשנודע לרב יוסף שרבא מכבדו מאוד, ברכו שיהיה ראש ישיבה (שם). ולדעת תוספות היה גם רב סחורה רבו המובהק. \"רב סחורה רבו המובהק של רבא היה\" (ע\"ז י\"ט ע\"א ד\"ה: אמר). חברו הגדול והמובהק היה אביי, ועל שמם נקרא הש\"ס: \"הויות דאביי ורבא\" (סוכה כ\"ח ע\"א). מחלוקותיהם ושקלי וטרי שלהם פזורים בכל הש\"ס, וכבר בילדותם למדו יחד (ברכות מ\"ח ע\"א). כשנפטר רב יוסף, מינו את אביי לראש (סוף הוריות), וכשאביי נפטר בשנת ד\u0027 צ\"ח (833) בפומבדיתא, מלך רבא. אך במקום בפומבדיתא, יסד את ישיבתו במחוזא, והיא היתה הישיבה המרכזית בבבל (\"אגרת רב שרירא גאון\"), ורב נחמן בר יצחק שימש כראש כלה אצלו (ב\"ב כ\"ב ע\"א). דרך לימודו של רבא היה בחריפות: \"אמר רבא וכו\u0027 היינו דאמרי אינשי: \u0027טבא פילפלתא חריפתא ממלי צנא דקרי\u0027\" (חגיגה י\u0027 ע\"א). אהב את הסברא: \"אמר להו (רבא): \u0027זיל בתר סברא\u0027\" (גיטין ע\"ג ע\"א). והלכה כרבא שהוא בתראה (ברכות י\"ג ע\"ב תוס\u0027). תוספות כתבו: \"בכל מקום שהרב והתלמיד חולקין הלכה כדברי הרב באמוראי עד אביי ורבא, אבל מכאן ואילך פסקינן כבתראי\" (קידושין מה ע\"ב ד\"ה: הוה). בין תלמידיו הרבים היו רבינא (ב\"ב ט\"ז ע\"ב), רב פפא (כתובות פ\"ה ע\"א), ובניו רב יוסף (חולין כ\"ח ע\"ב) ורב משרשיא (שם ע\"א), ועל שניהם אמר רבא: \"חכים ברי בטריפות\" (שם). היה מופלג בחסידות ולא בוש לומר: \"טעיתי\" (עירובין ק\"ד ע\"א). נהג לצום שני ימים ביום הכיפורים משום ספיקא (ר\"ה כ\"א ע\"א). ובכל ערבי יום כפורים יצאה בת קול מהשמים ושאלה לשלומו (תענית כ\"א ע\"ב). היה עשיר מופלג וחכם נדיר (מו\"ק כ\"ח ע\"א). היה מקורב למלכות (ב\"ב י\u0027 ע\"ב). לפי דרישתו של שבור מלכא מלך פרס, שניסה אותו, ביקש פעם מן השמים בחודש תמוז שירד גשם שוטף ובקשתו נתקבלה, ואביו בא לו בחלום ואמר שלא ישן במיטתו בלילה, שכן יש הקפדה מהשמים שהטריח בעניין הגשמים, ובלילה, חתכו השדים את מיטתו (תענית כ\"ד ע\"ב). ושוב שלחו מבית שבור מלכא לשאלו אם יודע להבחין בין סוגי דם, וידע להבחין יותר מששים סוגי דם (נדה כ\u0027 ע\"ב). ומסופר (מו\"ק שם) על פטירתו, שרב שעורים אחיו של רבא היה אצלו כשמת, וביקש רבא את אחיו שיאמר למלאך המות שלא יצערו. אחרי פטירתו נגלה לאחיו רב שעורים וסיפר לו שהיתה לו מיתה קלה בלי צער, והתחושה היתה כאילו הקיזו דם. כשמת רב יהודה, נולד רבא, וכשמת רבא, נולד רב אשי (קידושין ע\"ב ע\"ב)."},{"i":3230,"n":"רבא אבוה דרב מרי בר רחל","l":"ר","b":"מובא בבבלי (שבת קנ\"ד ע\"א). ע\"ע רב מרי בר איסור גיורא."},{"i":3231,"n":"רבא אחוה דר\u0027 מרי בר רחל","l":"ר","b":"מובא בבבלי (שבת קנ\"ד ע\"א). ע\"ע רב מרי בר איסור גיורא."},{"i":3232,"n":"רבא בר אבא","l":"ר","b":"אמורא בבלי בדור השלישי. תלמידו של רבי חייא בר אשי: \"אמר רבא אמר רבי חייא בר אשי אמר שמואל\" (פסחים ל\u0027 ע\"ב)."},{"i":3233,"n":"רבא בר אבין","l":"ר","b":"אמורא בבלי בדור השני - השלישי (פסחים מ\u0027 ע\"א)."},{"i":3234,"n":"רבא בר אהילאי","l":"ר","b":"אמורא בבלי בדור החמישי. מובא בבבלי, שמתקיף על דברי רבא (זבחים י\u0027 ע\"ב). רבינא ורב אשי שקלו וטרו בדבריו (פסחים ל\u0027 ע\"ב)."},{"i":3235,"n":"רבא בר אהינא","l":"ר","b":"מובא בבבלי (מנחות ל\"ז ע\"ב). אולי הוא בר אהינא."},{"i":3236,"n":"רבא בר איתי","l":"ר","b":"אמורא בדור השלישי - הרביעי. נראה, שהיה בארץ ישראל ובבבל. בארץ ישראל היה תלמידו של ריש לקיש (כריתות כ\"ד ע\"א), ובבבלי מצינו: \"אמר להו רבא בר איתי\" [לתלמידי רבה] (שבועות ל\"ו ע\"א)."},{"i":3237,"n":"רבא בר אפיתון","l":"ר","b":"כך מובא ב\"ילקוט\" (אסתר תתרנ\"ו), ונראה שצ\"ל: רבה בר עופרון."},{"i":3238,"n":"רבא בר בונא","l":"ר","b":"מובא בירושלמי (סנהדרין פ\"ג ה\"ג). ע\"ע רבי אבא בר אבינא."},{"i":3239,"n":"רבא בר בריה דרב פפי","l":"ר","b":"מובא בירושלמי (שבת פ\"א)."},{"i":3240,"n":"רבא בר זבדא","l":"ר","b":"מובא בירושלמי (יבמות פ\"א ה\"ו), ונראה שהוא רבי אבא בר זבדא."},{"i":3241,"n":"רבא בר זוטרא","l":"ר","b":"מובא בירושלמי (שבת פי\"ג ה\"ד). ע\"ע ר\u0027 אבא בר זוטרא."},{"i":3242,"n":"רבא בר זימונא","l":"ר","b":"מובא בבבלי (שבת קי\"ב ע\"ב). ע\"ע ר\u0027 אבא בר זמינא."},{"i":3243,"n":"רבא בר זימנא","l":"ר","b":"הוא אבא בר זמינא."},{"i":3244,"n":"רבא בר זמינא","l":"ר","b":"הוא רבי אבא בר זמינא."},{"i":3245,"n":"רבא בר חיננא","l":"ר","b":"אמורא בבלי בדור הששי, ואולי הוא ורבה בר חנינא אחד הוא. מובא ממנו, שהכריז על שחיטתו של שוחט כטריפה, כי לא הראה לו את הסכין, ומר זוטרא ורב אשי מצאו זכות עבורו: \"אמר ליה מר זוטרא [לרב אשי] ולא ליחש מר לסברא\" (חולין י\"ח ע\"א), ופרש\"י: \"לרבא בר חיננא שהעבירו, ואתה מכשירו\" לפי שקראו לו \"סבא\", יתכן שהיה בדור הרביעי וחי עד ימי רב אשי. שמו רבא ורבה וחנינא וחיננא - מתחלפים. ומה שמצאנו: \"אמר רבא בר חנינא אמר רבי יוחנן\" (שבת י\"ט ע\"ב), כבר גרסו הרי\"ף והרא\"ש: רבה בר בר חנה במקום רבא בר חנינא."},{"i":3246,"n":"רבא בר חקלאי","l":"ר","b":"אמורא בבלי בדור השלישי. תלמידו של רב הונא ושאל ממנו (עירובין ס\"ז ע\"ב)."},{"i":3247,"n":"רבא בר יוסף","l":"ר","b":"מובא בבבלי (סוטה ל\"ד ע\"א) אחרי אביי, ואולי הוא רבא סתם, כדמפרש רש\"י: \"רבא בריה דרב יוסף וכו\u0027 והוא רבא דכולי גמרא\" (חולין מ\"ג ע\"ב). אך הרא\"ש גורס: \"רבא בר יוסף משמיה דרבא\" (ב\"מ ס\"ז ע\"א), ולפנינו שם: \"מר בריה דרב יוסף משמיה דרבא\"."},{"i":3248,"n":"רבא בר ירמיה","l":"ר","b":"מובא בבבלי (ברכות מ\"ג ע\"א), והוא רבה בר ירמיה."},{"i":3249,"n":"רבא בר ישמעאל","l":"ר","b":"מובא בבבלי (מו\"ק ו\u0027 ע\"ב)."},{"i":3250,"n":"רבא בר מחסיא","l":"ר","b":"אמורא בבלי בדור השלישי. תלמיד תלמידו של רב. עשרה מאמרים של רב קיבל מרב חמא בר גוריא, תלמידו של רב (שבת י\u0027 ע\"ב)."},{"i":3251,"n":"רבא בר מרי","l":"ר","b":"מובא בבבלי (עירובין פ\"ו ע\"א). ו\"עין יעקב\" גרס: רבה בר מרי."},{"i":3252,"n":"רבא בר משרשיא","l":"ר","b":"אמורא בדור החמישי. הקשה לרבא (נזיר מ\u0027 ע\"ב) (\"סה\"ד\" בתמה על מה שהקשה רבא בר משרשיא לרבא מהשקלא וטריא של רבא מברניש עם רב אשי, שהיו מאוחרים יותר, לענ\"ד לא קשה מידי וזה ממסדר הש\"ס, ולא שרבא ראה לרב אשי)."},{"i":3253,"n":"רבא בר מתנה","l":"ר","b":"ע\"ע רבה בר מתנה."},{"i":3254,"n":"רבא בר נתן בר אמי","l":"ר","b":"כן גרס \"סה\"ד\" (קדושין ל\u0027 ע\"א), ולפנינו: \"אמר ליה רבא לרב נתן בר אמי\"; א\"כ, לפי גיר\u0027 \"סה\"ד\" לא היה אמורא בשם זה, שכן שוב לא מובא בש\"ס."},{"i":3255,"n":"רבא בר פפא","l":"ר","b":"מובא בבבלי: \"מאי לוקמטין, א\"ר אבהו: \u0027חמרא דאכפא\u0027, רבא בר פפא אמר: \u0027קשירי\u0027, רבא בר רב הונא אמר: \u0027פרמי\u0027\" (שבת ס\"ו ע\"ב). \"יוחסין\" גרס: רבא בריה דרב פפא, ורי\"ף גרס: רפרם בר פפא."},{"i":3256,"n":"רבא בר קיסי","l":"ר","b":"כך גירסת מהרש\"ל בבבלי (חולין כ\u0027 ע\"ב). ע\"ע רביא בר קיסי."},{"i":3257,"n":"רבא בר קיסנא","l":"ר","b":"מובא בבבלי (ב\"ב י\"ב ע\"א)."},{"i":3258,"n":"רבא בר רב אדא","l":"ר","b":"אמורא בבלי בדור השלישי. הוא ואחיו רבין בר רב אדא היו תלמידיו של רב יהודה (ביצה ל\"ג ע\"ב). היה תלמידו של רב (קידושין ע\u0027 ע\"א). גם אביו רב אדא היה חכם והוא קיבל מאביו (מנחות ל\"ט ע\"א)."},{"i":3259,"n":"רבא בר רב הונא זוטי","l":"ר","b":"אמורא בבלי בדור החמישי. \"שלח לו רב נחמיה בריה דרב יוסף [לרבא בר רב הונא זוטא]: כי אתיא הא איתתא לקמך וכו\u0027\" (כתובות ס\"ט ע\"א). היה הדיין בנהרדעא (שם)."},{"i":3260,"n":"רבא בר רב חנן","l":"ר","b":"אמורא בבלי בדור הרביעי. תלמידו של רב יוסף (עירובין נ\"א ע\"ב בפירוש הר\"ח) ושקיל וטרי עמו. וכן שקיל וטרי עם אביי (ברכות מ\"ה ע\"א). ישב לפני רבא (זבחים נ\"ה ע\"א), וקשה להניח שהיה תלמידו ממש."},{"i":3261,"n":"רבא בר רב חסדא","l":"ר","b":"מובא בב\"ר (פ\"ה - י\"ג)."},{"i":3262,"n":"רבא בר רב עזא","l":"ר","b":"אמורא בבלי בדור הרביעי. מצינו: \"אמר רבא בר רב עזא: \u0027בען במערבא וכו\u0027 א\"ל אביי\u0027 וכו\u0027\" (תמורה כ\"א ע\"א)."},{"i":3263,"n":"רבא בר רב שילא","l":"ר","b":"מובא בבבלי (עירובין ס\u0027 ע\"ב), והוא רבה בר שילא."},{"i":3264,"n":"רבא בר שאילנא","l":"ר","b":"הוא רבה בר שילא."},{"i":3265,"n":"רבא בר שאילתא","l":"ר","b":"אמורא בבלי בדור החמישי. מובא בבבלי, ששאל מרב נחמן בר יצחק כנראה שהוא הוא רבה בר שילא (גיטין ל\"ט ע\"ב)."},{"i":3266,"n":"רבא בר שבא","l":"ר","b":"אמורא בבלי בדור השביעי. תלמידו של רבינא (שבת קל\"ט ע\"ב)."},{"i":3267,"n":"רבא בר שירא","l":"ר","b":"אמורא בבלי בדור השלישי - הרביעי. מובא בבבלי, שמתקיף על דברי רב יוסף: \"לא שמיע להו הא דתני רב חנן בר רבא לחייא בר רב וכו\u0027\" (שבת ס\"ו ע\"א)."},{"i":3268,"n":"רבא בר שמואל (2)","l":"ר","b":"אמורא בבלי בדור החמישי. חברם של רב פפא ורב הונא בריה דרב יהושע (ברכות כ\"ב ע\"ב)."},{"i":3269,"n":"רבא בר שרשום","l":"ר","b":"חי בבבל בדור הרביעי. יצא עליו קול, שלקח קרקע של יתומים, ואביי אמר לו: \"אימא לי איזו גופא דעובדא וכו\u0027\" (ב\"ב ל\"ב ע\"ב). אין הכרח מוחלט, אך נראה שהיה אמורא."},{"i":3270,"n":"רבא בר תחליפא","l":"ר","b":"אמורא בבלי בדור הששי. מצינו: \"אמר ליה רבא בר תחליפא לרבינא\" (עירובין מ\u0027 ע\"א). יש רבה בר תחליפא, שמסר משם רב (שבת ק\"כ ע\"ב)."},{"i":3271,"n":"רבא בריה דרב אויא","l":"ר","b":"כן גיר\u0027 \"אור זרוע\" (הלכות טרפות סתי\"א) בבבלי (חולין מ\"ז ע\"א), ולפנינו הגיר\u0027: רב הונא בר מר אויא. והיה בדורו של רב אשי (בדור הששי לאמוראי בבל)."},{"i":3272,"n":"רבא בריה דרב אחא בר הונא","l":"ר","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב ששת (נדה ל\"א ע\"ב)."},{"i":3273,"n":"רבא בריה דרב אידי בר אבין","l":"ר","b":"אמורא בבלי בדור החמישי. כן גיר\u0027 הרא\"ש בבבלי (שבת קל\"ו ע\"א), ולפנינו הגיר\u0027: רב פפא ורב הונא בריה דרב יהושע, איקלעו לבי בריה דרב אידי בר אבין, (בלי המלה \"רבא\")."},{"i":3274,"n":"רבא בריה דרב עילאי","l":"ר","b":"אמורא. נראה שהיה בדור השלישי: \"דרש רבא בריה דרב עילאי: מאי דכתיב: ויאמר ה\u0027 יען כי גבהו בנות ציון וכו\u0027, א\"ר יצחק דבי רב אמי [תלמידו של רב חסדא]: \u0027מלמד שמטילות מור ואפרסמון במנעליהן וכו\u0027\" (שבת ס\"ב ע\"ב)."},{"i":3275,"n":"רבא בריה דרבה","l":"ר","b":"אמורא בבלי בדור הרביעי. בנו של האמורא המפורסם רבה. שלח לרב יוסף: \"ילמדנו רבנו\" (שבת קכ\"ג ע\"א; יבמות ע\"ו ע\"א, ועוד), אך לא מצינו שישב לפני רב יוסף. מצינו: \"רבה בריה דרבא\" (מגילה כ\"ב ע\"א ועוד), וצ\"ל: רבא בריה דרבה, ומסופר: (מכות י\u0027 ע\"א): \"אמר רבה בר מרי: \u0027מי אוהב בהמון וכו\u0027, יהבי בי רבנן עינייהו ברבא בריה דרבה\u0027\" [שהיה אוהב תלמידי חכמים ביותר והיו לו בנים תלמידי חכמים] (מכות י\u0027 ע\"א)."},{"i":3276,"n":"רבא בריה דרבה בר רב הונא","l":"ר","b":"אמורא בבלי בדור הרביעי. בן בנו של רב הונא המפורסם. חלק עם אביו רבה בר רב הונא (עירובין נ\"ה ע\"ב). אביי אמר: \"כוותיה דרבא בריה דרבה בר רב הונא מסתברא\". אולי הוא אבא בריה דרבה בר רב הונא (סוטה מ\"ט ע\"א)."},{"i":3277,"n":"רבא זעירא","l":"ר","b":"אמורא שאין לקבוע זמנו ומקומו. מצינו: \"אמר רבי אלעזר: \u0027כל שארגו\u0027 וכו\u0027 מתקיף לה רבא זעירא ואיתמא רבי שמואל בר נחמני וכו\u0027\" (ערכין ט\"ז ע\"ב). הגמרא מפקפקת אם רבא זעירא הקשה או רבי שמואל בר נחמני הקשה, אך אין בכך להוכיח מאומה שהיה בזמנו של ר\u0027 שמואל בר נחמני."},{"i":3278,"n":"רבא מברניש","l":"ר","b":"אמורא בבלי בדור השביעי. תלמידו של רב אשי (ב\"מ ע\"ג ע\"ב), שקיל וטרי עמו (שבת כ\"ח ע\"א)."},{"i":3279,"n":"רבא מפרזקיא","l":"ר","b":"אמורא בבלי בדור השביעי. תלמידו של רב אשי (תמורה ל\u0027 ע\"א), ושקיל וטרי עמו (כתובות ל\"ט ע\"ב). נראה, שהיה דיין במקומו: \"ההיא ביניתא וכו\u0027, אסרה רבא מפרזיקיא\" (פסחים ע\"ו ע\"ב)."},{"i":3280,"n":"רב רבאי דמן רוב","l":"ר","b":"מחכמי רבנן סבוראי האחרונים. ראש ישיבת פומבדיתא אחרי רב סימונא. האריך ימים. שם עירו היה רוב, והעיר רוב היתה בסביבות נהרדעא (\"אגרת רב שרירא גאון\"). מוזכר בש\"ס הבבלי (סנהדרין מ\"ג ע\"א) לגירסת הר\"ח."},{"i":3281,"n":"רבה (3)","l":"ר","b":"מגדולי אמוראי בבל בדור השלישי, והוא סתם רבה בכל הש\"ס. שם אביו נחמני, בר פלוגתיה דרב יוסף (ב\"מ פ\"ו ע\"א רש\"י). ראש ישיבת פומבדיתא במשך עשרים ושתיים שנה בשנים ד\u0027 נ\"ח - ד\u0027 פ\u0027 (892 - 023). מלך אחרי רב יהודה רבו. אחרי שנפטר מלך רב יוסף (\"אגרת רב שרירא גאון\"). בגיל 81 היה לראש ישיבה, ובגיל 04 נפטר (מו\"ק כ\"ח ע\"א). לפי דברי תוספות, הלך לארץ ישראל ולמד לפני רבי יוחנן (עירובין כ\"ב ע\"ב ד\"ה: קרקפנא). רבותיו היו רב הונא (עירובין י\"ז ע\"א), רב חסדא (ב\"מ מ\u0027 ע\"א רש\"י), רב ששת (עירובין ס\"ה ע\"ב) ורב נחמן (יבמות ס\"ו ע\"א). בין חבריו היה רבי זירא (חולין מ\"ו ע\"א), ופעם עשו שניהם סעודת פורים, ורבה השתכר ושחט את רבי זירא, ואחרי שהתפכח ביקש רחמים והחיה אותו (מגילה ז\u0027 ע\"ב). חברו המובהק ובר פלוגתיה היה רב יוסף. רבה הצטיין בפלפול ובחריפות וקראו לו: \"עוקר הרים\" ולרב יוסף קראו: \"סיני\", על שהצטיין בשמועות רבות וכשנפטר רבי יהודה רבם שלחו מבבל לא\"י לשאול את מי להמליך, והשיבו שימליכו את רב יוסף, אלא שרב יוסף ויתר, ורבה מלך במקומו (ברכות ס\"ד ע\"א). היו לו מאות תלמידים, ו - 004 מהם היו אוכלי שולחנו (כתובות ק\"ו ע\"א רש\"י). בחודשים ניסן ותשרי התאספו אליו שנים עשר אלף איש לשמוע את דרשותיו לחגים (ב\"מ פ\"ו ע\"א). לא ישן ביום יותר משינת הסוס, שהיא ששים נשימות (סוכה כ\"ו ע\"ב). בצעירותו היה עני מרוד עד שלא נמצא לחם שעורים בביתו (מו\"ק כ\"ח ע\"א), ואחרי שמלך כנראה שהעשירוהו, כמו שכתב רש\"י: \"מנהג הוא, מי שהוא ראש ישיבה היו מגדלין אותו\" (תענית כ\"א ע\"א ד\"ה: מלך). וכן מוכח מזה, שאביי אמר לרבה: \"נעשית מלך וראש בפומבדיתא ואינך שולח לו אלא דברים המצויין לכל\" (מגילה ז\u0027 ע\"ב רש\"י ד\"ה: אי). היו לו שלושה אחים, שניים, רב חייא ורב אושעיא, היו בארץ ישראל ושלחו לו לבוא לא\"י ללמוד לפני רבי יוחנן (כתובות קי\"א ע\"א), והשלישי היה כייליל, אביו של אביי (זבחים קי\"ח ע\"ב רש\"י ד\"ה: חד). בין תלמידיו המובהקים היה אביי בן אחיו (ברכות ל\"ג ע\"ב). היה לו בן חכם ושמו רבא (שבת קכ\"ג ע\"א). כשנודע למלכות שאלפי אנשים מתאספים לשמוע את דרשותיו, ואינם משלמים מסים למלכות, שלחו לתפסו, והוא ברח. ובאותו זמן היתה מחלוקת הלכתית במתיבתא דרקיע, ושלחו למלאך המות שיביאוהו, ולא יכול מלאך המות לקרב אליו. ובשעת פטירתו אמר: \"טהור טהור\" ויצאה בת קול ואמרה: \"אשריך רבה בר נחמני שגופך טהור ויצאה נשמתך בטהור\", ונפל פתק מהשמים לפומבדיתא: \"רבה בר נחמני נתבקש לישיבה של מעלה\". ולאחר שהספידוהו שלשה ימים, נפל פתק שני: \"מי שפורש יהיה בנידוי\", ולאחר שבעה ימי הספד נפל פתק שלישי: \"לכו לביתכם לשלום\"."},{"i":3282,"n":"רבה בר אבוה","l":"ר","b":"אמורא בבלי בדור השני. תלמידו של רב (שבת קכ\"ט ע\"ב). רבו המובהק של רב נחמן (ברכות כ\"א ע\"א) נראה, שנתן לרב נחמן את בתו ילתא לאשה (יבמות פ\u0027 ע\"ב). יותר ממאה פעמים מצינו בש\"ס: \"אמר רב נחמן אמר רבה בר אבוה\". רבה בר אבוה היה ממשפחת הנשיאים (\"אגרת רב שרירא גאון\"). בשנת ד\u0027 י\"ח (852), כשנחרבה נהרדעא על ידי פפא בן נצר, הלך כנראה, רבה בר אבוה למחוזא (עירובין כ\"ו ע\"א) והיה מראשי הדיינים שם (יבמות קט\"ו ע\"ב). היה עני מרוד ואליהו הנביא נגלה לו והעשירו (שם קי\"ד ע\"ב). היה לו בן חכם (עירובין ג\u0027 ע\"א)."},{"i":3283,"n":"רבה בר אהיליי","l":"ר","b":"מובא בבבלי (זבחים צ\"ה ע\"ב). ע\"ע רבא בר אהילאי."},{"i":3284,"n":"רבה בר איבו","l":"ר","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב ששת (גיטין ל\"ב ע\"א)."},{"i":3285,"n":"רבה בר איסי","l":"ר","b":"אמורא בבלי בדור השני. תלמידו של רב (סוטה ל\u0027 ע\"א)."},{"i":3286,"n":"רבה בר איתא","l":"ר","b":"אמורא. תלמידו של ריש לקיש (כריתות כ\"ד ע\"א), והוא רבא בר איתי. נראה, שהיה בבבל ודיבר עם תלמידי רבה (שבועות ל\"ז ע\"א)."},{"i":3287,"n":"רבה בר איתי","l":"ר","b":"הוא רבא בר איתי."},{"i":3288,"n":"רבה בר בר חנא","l":"ר","b":"אמורא בדור השלישי. ממשפחת רב (סנהדרין ה\u0027 ע\"א). היה יליד בבל, כמובא שריש לקיש שחה בירדן, ובא רבה בר בר חנא והושיט לו ידו, אמר לו ר\"ל: \"סנינא לכו\" [אני שונא לכם לכל בני בבל, שלא עלו בימי עזרא לא\"י] (יומא ט\u0027 ע\"ב). תלמידו המובהק של רבי יוחנן (ברכות מ\"ד ע\"א), ויותר ממאתים מאמרים מסר בשמו. כן היה תלמידו המובהק של רבי אלעזר (שבת י\"ב ע\"ב). כן קיבל מרבי יהושע בן לוי (ברכות כ\"ד ע\"ב). היה מה\"נחותאי\", כמובא: \"כי אתא רבה בר בר חנא אכל דאייתרא\" [חלק שבכפיפת הקיבה שבני א\"י נוהגים בו היתר ובני בבל נוהגים בו איסור] (פסחים נ\"א ע\"א). ורב יהודה שאל ממנו: \"מידי שמיע לך בהא, א\"ל: הכי אמר רבי יוחנן\" (מו\"ק י\"ז ע\"א). רב יוסף קבל ממנו (יבמות ט\"ז ע\"ב), וגם רב נחמן קיבל ממנו (ב\"ק ק\u0027 ע\"ב). אביו רבה בר חנא היה שני בשני עם רב (סנהדרין ה\u0027 ע\"א). סיפר מראות מופלאים ממסעותיו (ב\"ב ע\"ג ע\"ב). סיפוריו נראים כגוזמאות גדולות, אך יש בהם רמזים עמוקים. בנו רב יצחק שהיה אף הוא חכם (יבמות ס\"ד ע\"ב), נשא לאשה את חומא בת איסי, נכדתו של רב יהודה ואחרי שרב יצחק זה מת, התחתן אביי עם חומא (שם)."},{"i":3289,"n":"רבה בר בר חנן","l":"ר","b":"מובא בבבלי (סוטה ל\"ד ע\"ב). אולי יש שיבוש בשם, שכן במקום אחר: \"רבה בר רב חנן\" (תמורה י\"ד ע\"ב), וכן ברוב המקומות בש\"ס. אך נראה שגירסתם של התוספות (סוטה ל\"ד ע\"ב ד\"ה: ואמר) היתה כמו לפנינו: רבה בר בר חנן."},{"i":3290,"n":"רבה בר ברונא","l":"ר","b":"אמורא בבלי בדור השלישי. מובא בבבלי (שבת ק\"י ע\"א). תלמיד תלמידו של רב. אביו רב ברונא היה תלמידו המובהק של רב (פסחים ק\"ג ע\"א)."},{"i":3291,"n":"רבה בר זבדא","l":"ר","b":"מובא בבבלי (שבת י\"ט ע\"ב). נראה, שהוא ר\u0027 אבא בר זבדי."},{"i":3292,"n":"רבה בר זוטרא","l":"ר","b":"מובא בירושלמי (גיטין פ\"ד ה\"ד). ע\"ע ר\u0027 אבא בר זוטרא."},{"i":3293,"n":"רבה בר חייא קטוספאה","l":"ר","b":"אמורא בבלי בדור השני. מסר משם רב (ב\"ב צ\"ג ע\"ב). אותו מאמר מובא בירושלמי, ושם מכונה: \"אבא בר חייא\" (כלאים פ\"ב ה\"א). עשה חליצה בניגוד לדעתו של שמואל, ועל כך אמר עליו שמואל: \"כמה רב גובריה דעביד כיחידאה\" (יבמות ק\"ד ע\"א), ופרש\"י: \"בלשון גנאי אמרה\"."},{"i":3294,"n":"רבה בר חיננא סבא","l":"ר","b":"אמורא בבלי בדור השני. תלמידו של רב (ברכות י\"ב ע\"ב)."},{"i":3295,"n":"רבה בר חנה","l":"ר","b":"אמורא בבלי. עלה לארץ ישראל. בן אחיו של רבי חייא ואביו של רבה בר בר חנא (סנהדרין ה\u0027 ע\"א). היה שני בשני עם רב ויחד עם רב למד לפני רבי חייא (מו\"ק ט\"ז ע\"ב). לפני שחזר לבבל נתן לו רבי רשות לדון ולהתיר בכורות (שם). עם תלמידיו נמנה רב חננאל, שהיה גם תלמידו של רב (מו\"ק י\"ט ע\"א)."},{"i":3296,"n":"רבה בר חנינא","l":"ר","b":"אמורא בבלי בדור הרביעי. תלמידו של רב נחמן (ב\"ב קי\"ג ע\"ב). ע\"ע רבא בר חיננא."},{"i":3297,"n":"רבה בר טוביה בר יצחק","l":"ר","b":"אמורא בבלי בדור השני. תלמידו של רב (עירובין כ\"ח ע\"א). \"דק\"ס\" גרס: \"רבה בר יצחק\" (ולא טוביה), ולגירסתו לא היה כלל חכם ושמו רבה בר טוביה בר יצחק, שכן מובא בש\"ס רק במקום זה."},{"i":3298,"n":"רבה בר יונתן","l":"ר","b":"אמורא בבלי בדור השלישי (יומא מ\"ז ע\"א). תלמידו של רב יחיאל [ורבי יחיאל היה בר פלוגתיה של רב יהודה] (מו\"ק י\u0027 ע\"א)."},{"i":3299,"n":"רבה בר יוסף","l":"ר","b":"אמורא בבלי בדור השני. תלמידו של רב (ערכין ה\u0027 ע\"ב)."},{"i":3300,"n":"רבה בר יוסף בר חמא","l":"ר","b":"אמורא בבלי בדור השלישי - הרביעי. נראה תלמידו של רב ששת (ב\"מ ע\u0027 ע\"א). יש גורסים: אמר רב יוסף בר חמא."},{"i":3301,"n":"רבה בר ירמיה","l":"ר","b":"אמורא בבלי בדור השני - השלישי. מושבו היה בסורא (ע\"ז ט\"ז ע\"ב). מסר בשם רב (שם) והיה תלמידו של שמואל (נדה י\"א ע\"ב). רבו של רבי זירא (שם), שבא אליו לסורא לקבל הלכות (ע\"ז שם). מסרו בשמו רבי אבא (ירו\u0027, ר\"ה פ\"ד ה\"ו) ורבי יונה (ויק\"ר פי\"א - ב\u0027)."},{"i":3302,"n":"רבה בר ליואי","l":"ר","b":"אמורא בבלי בדור הרביעי. חברו של רבא ונהג להקשות לרבא ברבים, ופעמים שרבא נכלם מקושיותיו ונענש על כך (פסחים ק\"י ע\"א)."},{"i":3303,"n":"רבה בר לימא","l":"ר","b":"אמורא בבלי, כנראה בדור השני. אמר בשם רב (מגילה י\"ג ע\"ב)."},{"i":3304,"n":"רבה בר ממל","l":"ר","b":"מובא בבבלי (ב\"מ נ\"ו ע\"ב)."},{"i":3305,"n":"רבה בר מרי","l":"ר","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (סנהדרין ק\"ה ע\"א). כן קיבל מרבי יהושע בן לוי (ברכות מ\"ב ע\"ב). מצינו הלשון: \"אמרי במערבא משמיה דרבה בר מרי\" (יומא פ\"ו ע\"ב; סנהדרין ק\u0027 ע\"א, ועוד). אח\"כ ירד לבבל ורבא קיבל ממנו (ב\"ב ח\u0027 ע\"ב) ובירר אצלו סתירות באגדה, ורבה בר מרי תירץ לו מאמרי רבי יוחנן, ואמר לו: \"הכי אמר רבי יוחנן\" (מו\"ק כ\"ח ע\"ב). כן שאל ממנו ר\u0027 אבא והוא השיב לו: \"הכי אמר ר\u0027 יוחנן\" (סנהדרין ק\"א ע\"א)."},{"i":3306,"n":"רבה בר מריון","l":"ר","b":"מובא בבבלי: \"תנא רבה בר מריון בדבי רבי יוחנן בן זכאי\" (עירובין י\"ט ע\"א), ופרש\"י: \"ברייתא שסידר בביהמ\"ד\" ובמקום אחר מובא המאמר: \"תני רבה בר מרי משום רבי יוחנן בן זכאי\" (סוכה ל\"ב ע\"ב)."},{"i":3307,"n":"רבה בר מתנה","l":"ר","b":"אמורא בבלי בדור הרביעי. תלמידם של רבה ורב ששת (פסחים ל\"ד ע\"א). חברם של אביי ורבא ורב זירא. לאחר פטירת רב יוסף היו ארבעתם מועמדים להבחר לראש מתיבתא בפומבדיתא, ואביי נבחר לשמש ראש ישיבה (סוף הוריות). אמרו עליו שבניגוד לרבי זירא, שהיה חריף ומקשה, הוא היה: \"מתון ומסיק\" (שם), ופירש\"י: \"שהוא שוהה ומעיין יפה יפה\"."},{"i":3308,"n":"רבה בר נחמני","l":"ר","b":"הוא סתם רבה (גיטין ל\"ד ע\"ב רש\"י ד\"ה: והלכתא)."},{"i":3309,"n":"רבה בר נתן","l":"ר","b":"אמורא בבלי בדור השלישי. תלמידו של רב הונא (ב\"ק ל\"ב ע\"א). חברם של ר\u0027 חייא בר אבא ורב אסי. שלושתם ישבו ורב נחמן ישב לידם (עירובין ל\"ב ע\"ב). עלה לארץ ישראל ולמד שם לפני רבי יוחנן (ב\"ב קע\"ו ע\"ב). פעם נדמה לרבי יוחנן שהוא מגחך והקפיד עליו, ומת בו במקום (ירו\u0027, נזיר פ\"ז ה\"ב)."},{"i":3310,"n":"רבה בר עולא","l":"ר","b":"אמורא בבלי בדור השלישי - הרביעי. חברם של אביי ורבא ושקיל וטרי עמם בהלכה (מנחות כ\"א ע\"א). חלק עם עולא (חגיגה כ\"ה ע\"ב). שקיל וטרי עם עולא (יבמות ע\"ז ע\"א). לא מוכח וגם לא נראה, שהיה בנו של עולא."},{"i":3311,"n":"רבה בר עופרן","l":"ר","b":"מובא בבבלי (מגילה י\u0027 ע\"ב) וגירסת התוספות: \"עופרון ולא עפרון, דעפרון היה רשע ולא קוראים יהודי בשם רשע\"."},{"i":3312,"n":"רבה בר עשבי","l":"ר","b":"חי בבבל בדור השלישי לאמוראים. רב יהודה התיר לו לעשות נפה בחול המועד (מו\"ק י\"א ע\"א), ואין ראיה שנמנה על החכמים. \"יוחסין\" גורס: \"רבה בר עסבי\" ומביאו בין החכמים, וכן הביאו \"סה\"ד\" בין החכמים."},{"i":3313,"n":"רבה בר קיריא","l":"ר","b":"אמורא ארץ ישראלי בדור השני. חברו של ר\u0027 אלעזר וטיילו יחד (ירו\u0027, כלאים פ\"ט ה\"ג). ויש גיר\u0027 אחרת: רבי בר קיריא (פ\u0027 רבתי פ\u0027 דשבת ור\"ח - ו\u0027), ויש גורסים: ר\u0027 ברוקאי."},{"i":3314,"n":"רבה בר רב הונא","l":"ר","b":"אמורא בבלי בדור השלישי. בנו ותלמידו המובהק של האמורא המפורסם רב הונא (ברכות נ\"ג ע\"ב). היה גם תלמידו של רב (ב\"ב קל\"ו ע\"ב). קיבל משמואל (ערכין מ\"ט ע\"א). בעצת אביו קיבל תורה מרב חסדא (שבת פ\"ב ע\"א), ואח\"כ הפך לו לתלמיד - חבר [ראיה לכך, שאת רב חמא בר גיורא מכנה: \"רבותינו\", ואת רב חסדא מכנה: \"חברינו\" (גיטין פ\"ו ע\"ב)]. רב חסדא ישב עמו יחד בדין כדיינים (שם י\u0027 ע\"א). ושניהם ביקרו את רב נחמן כשבא לסורא (סוכה י\"ד ע\"ב). נראה, שהיה בארץ ישראל וישב לפני רבי יוחנן (מנחות נ\"ט ע\"ב). היה עשיר, בעל יערות (ב\"מ ק\"ח ע\"א). היה מופלג בענוה עד שרבא התפלל שיזכה להיות עניו כמוהו (מו\"ק כ\"ח ע\"א). היה לו בן חכם ושמו רבא (חולין ע\"ו ע\"א). הוא ורב המנונא נפטרו באותו זמן ואת ארונות שניהם העלו לארץ ישראל (מו\"ק כ\"ה ע\"ב)."},{"i":3315,"n":"רבה בר רב הונא זוטא מנהרדעא","l":"ר","b":"מובא בבבלי (כתובות ס\"ט ע\"א). ע\"ע רבא בר רב הונא זוטי."},{"i":3316,"n":"רבה בר רב יצחק","l":"ר","b":"אמורא בבלי בדור השלישי. תלמידו של רב (יבמות ע\"א ע\"ב). אח\"כ ישב לפני רב יהודה (מנחות כ\"ו ע\"א)."},{"i":3317,"n":"רבה בר רב כהנא","l":"ר","b":"כך הגיר\u0027 בתוספות (נזיר מ\"ב ע\"ב), ולפנינו שם: \"אמר רבה אמר רב הונא\"."},{"i":3318,"n":"רבה בר רב שילא","l":"ר","b":"אמורא בבלי בדור השלישי - הרביעי. תלמידו של רב חסדא (שבת פ\"א ע\"א). היה גם תלמידו של רב נחמן (ב\"ב קנ\"ה ע\"ב). רבי זירא קיבל ממנו (כתובות מ\u0027 ע\"א). היה דיין במקומו, ופעם אחת עירערו על פסק דינו לפני רבא, ורבא הצדיק את פסק הדין (שם ק\"ד ע\"ב). זכה לגילוי אליהו ושאל לאליהו: \"מאי קעביד הקב\"ה וכו\u0027\" (חגיגה ט\"ו ע\"ב). לימד זכות על רבי מאיר, שלמד תורה מ\"אחר\" ואמר לאליהו הנביא: \"תוכו אכל וקליפתו זרק\", וטיעונו זה של רבה בר רב שילא התקבל בשמים (שם)."},{"i":3319,"n":"רבה בר שאילתא","l":"ר","b":"מובא בבבלי (גיטין פ\"א ע\"ב), והוא רבה בר שילא."},{"i":3320,"n":"רבה בר שילא","l":"ר","b":"הוא רבה בר רב שילא."},{"i":3321,"n":"רבה בר שימי א\u0027","l":"ר","b":"אמורא בבלי בדור הרביעי. תלמידו של רב יוסף, ואמר לרבא \"מר לא אמר הכי, ומנו, רב יוסף\" (חולין כ\"ט ע\"ב). היה גם תלמידו של רב חסדא (שם ק\"ב ע\"א)."},{"i":3322,"n":"רבה בר שימי ב\u0027","l":"ר","b":"אמורא בבלי בדור השביעי. תלמידו של רבינא, כדמצינו שא\"ל רבנן לרבינא: \"ודילמא וכו\u0027 ואמר להו רבה בר שימי בפירוש אמר מר וכו\u0027\" (קידושין מ\"ה ע\"ב), ופרש\"י: \"מר - רבינא\". אך קשה להניח שרבה בר שימי האריך ימים הרבה והיה תלמידו של רב יוסף (חולין כ\"ט ע\"א), שחי בדור השלישי, ותלמידו של רבינא שחי בדור הששי, ולכן כתב \"יוחסין\" ששניים היו, ו\"סה\"ד\" כתב: \"לא ידעתי מנ\"ל שהיו שנין או משום שדיבר עם רב יוסף ועם רבינא וכו\u0027 אין הכרח שמא האריך ימים\", עכ\"ל. אך גם אם נניח שהאריך ימים, לא סביר שאמורא בדור הרביעי ידבר לרבינא בדור הששי כדבר תלמיד לרבו, ולכן הסקתי ששנים היו."},{"i":3323,"n":"רבה בר שמואל","l":"ר","b":"אמורא בבלי בדור השלישי. זכה להיות תלמידו של רב (יומא ל\"ו ע\"ב). וכן היה תלמידו של רב חסדא (חולין ק\"כ ע\"א). היה מן התנאים השונים ובקיאים בברייתות. אף רב חסדא רבו שאלו: \"אשכחית רב חסדא א\"ל: \u0027תנית מידי באיסורי הנאה\u0027, א\"ל: \u0027אין תנינא וכו\u0027\" (ב\"ק צ\"ח ע\"ב). כן שאלו רב ששת כמה פעמים: \"אשכחיה רב ששת א\"ל: \u0027תני מר מידי בצורת הפתח וכו\u0027\" (עירובין י\"א ע\"ב ועוד). הגמרא מקשה כמה פעמים: \"והתני רבה בר שמואל וכו\u0027\" (שם צ\"ז ע\"א, ועוד). \"יוחסין\" כתב שהיה בנו של שמואל (בר פלוגתיה של רב)."},{"i":3324,"n":"רבה בר תחליפא","l":"ר","b":"אמורא בבלי בדור השני - השלישי. מסר משם רב (שבת ק\"כ ע\"ב). כן היה תלמידו של רב ירמיה בר אבא (חולין מ\"ה ע\"ב)."},{"i":3325,"n":"רבה בריה דרבא","l":"ר","b":"מובא בבבלי (מגילה כ\"ב ע\"א) רבה בריה דרבא, וצ\"ל רבא בריה דרבה (ע\"ע)."},{"i":3326,"n":"רבה דבי רב שילא","l":"ר","b":"מובא בבבלי (שבת ז\u0027 ע\"א), והוא רבה בר שילא."},{"i":3327,"n":"רבה זוטי","l":"ר","b":"אמורא בבלי בדור הששי. חברו ובר פלוגתיה של רב אשי ושקיל וטרי עמו הרבה (ב\"ב ק\"כ ע\"א). כן שקיל וטרי עם רבינא (בכורות ל\"ו ע\"א)."},{"i":3328,"n":"רבה מקובי","l":"ר","b":"אמורא בבלי בדור השביעי. מושבו בעיר מקובי. מר בר רב אשי קנה סודר מאמו שוי עשרה בתליסר (קידושין ח\u0027 ע\"א). \"יוחסין\" ו\"סה\"ד\" גרסו: רבה מקובריה, ולגירסתם מר בר רב אשי קנה מרבה מקובריה את הסודר, ולא מאמו."},{"i":3329,"n":"רבה ריחומי","l":"ר","b":"מובא בבבלי (מנחות ל\"ג ע\"ב), והוא ר\u0027 רחומי ג\u0027 מרבנן סבוראי."},{"i":3330,"n":"רבה תוספתא","l":"ר","b":"אמורא בבלי בדור השביעי - השמיני. עמד בראש ישיבת סורא אחרי מר בר רב אשי בשנים ד\u0027 רכ\"ז - רל\"ג (764 - 374) (\"אגרת רב שרירא גאון\"). נראה, שהיה תלמידו של רבינא (חברו של רב אשי), שמצינו שהקשה לרבינא והוא השיב לו (סוכה ל\"ב ע\"א), וכן שקיל וטרי עמו (ב\"ב ס\"ד ע\"א). מובאת ממנו הלכה אחת שחידש באשה שהלך בעלה למדינת הים (יבמות פ\u0027 ע\"ב). נראה שבימיו כבר היה התלמוד בגמר עריכתו, והוא הוסיף עליו, ויתכן שלכן כינוהו רבה תוספתא."},{"i":3331,"n":"רבי","l":"ר","b":"הוא רבי יהודה הנשיא."},{"i":3332,"n":"רביא בר קיסי","l":"ר","b":"אמורא בבלי בדור הששי. נפטר בזמן שרבינא חלק עם רבי ירמיה מדיפתא, ושמו של רביא בר קיסי שימש להם כסימן במחלוקתם (יומא מ\"ב ע\"א), ואולי הוא רבין בר קיסי (ע\"ע)."},{"i":3333,"n":"רבין (2)","l":"ר","b":"אמורא בדור השלישי - הרביעי. נולד כנראה בבבל (\"אגרת רב שרירא גאון\"). היה יתום, כדברי עצמו: \"פטור אני מכיבוד אב ואם\"; כשעיברתו אמו מת אביו, וכשילדתו מתה (ירו\u0027, קידושין פ\"א ה\"ז). בצעירותו למד בא\"י בבית מדרשו של ר\u0027 יוחנן (קידושין מ\"ד ע\"א). היה מצוי כל שעה לפני רבי יוחנן (יבמות ס\"ד ע\"ב - רש\"י). היה גם תלמידו של רבי אבהו (פסחים פ\"ד ע\"א). מחשובי ה\"נחותי\", שתפקידם היה להביא מתורת א\"י לבבל ומבבל לא\"י. בזמן אביי ורבא, כשנתרבו הגזרות בא\"י, ירדו רבין ורב דימי ונחותי אחרים לבבל (\"אגרת רב שרירא גאון\"), ויתכן שלכך מתכוונת הגמרא: \"כי אתא רבין וכל נחותי וכו\u0027\" (חולין קכ\"ד ע\"א). מסר בשם חכמי ארץ ישראל: \"כי אתא רבין, אמר: \u0027מתיב ר\u0027 יוסי בר חנינא\u0027\" (נדה י\"ח ע\"ב); \"כי אתא רבין, אמר: \u0027ר\u0027 חייא בר אבא אמר ר\u0027 יוחנן\u0027\" (קידושין ע\"ה ע\"ב). פעמים, הבהיר את דברי ר\u0027 דימי שגם הוא היה מ\"נחותי\", כגון: \"כי אתא ר\u0027 דימי, אמר ר\u0027 יוחנן: \u0027שלוש לשונות שמעתי וכו\u0027 ואין לי לפרש\u0027 [ואיני יודע לפרש], כי אתא רבין, פירשה משמיה דר\u0027 יונתן\" (יומא מ\"א ע\"ב). במסרו את תורת חכמי א\"י בבואו לבבל סמכו על דבריו. אביי נתן בו אמון רב וחשבו לבר סמכא (יבמות ס\"ד ע\"ב). כן הביא עמו לא\"י מאמרים של חכמי בבל: \"רבי אבין [רבין] בשם רבנן דתמן [בבל]\" (ירו\u0027, פאה פ\"ז ה\"ג). נהג לעלות לא\"י ולשוב מפעם לפעם. בשבתו בא\"י היה שולח איגרות לבבל: \"דשלח רבין משמיה דרבי אבהו\" (גיטין ט\u0027 ע\"ב)."},{"i":3334,"n":"רבין בר אבא","l":"ר","b":"אמורא שאין לקבוע זמנו המדוייק. מובא בבבלי (חולין פ\"ו ע\"א)."},{"i":3335,"n":"רבין בר חיננא","l":"ר","b":"אמורא בבלי בדור השלישי. תלמידו של רב חסדא (כתובות נ\"ג ע\"א). אמר משם רבי אלעזר (שם). אמר לרבי זירא: \"הכי אמר עולא\" (חולין קכ\"ב ע\"א). הגיע לזקנה מופלגת, שכן רב אשי קיבל ממנו (פסחים ק\"ט ע\"ב). פעם התדיינו הוא ואחיו רב דימי בר חיננא לפני רבא (ב\"ב י\"ג ע\"ב)."},{"i":3336,"n":"רבין בר חנינא","l":"ר","b":"מובא בבבלי (כתובות נ\"ג ע\"א). ע\"ע רבין בר חיננא."},{"i":3337,"n":"רבין בר כהנא","l":"ר","b":"הוא אבין בר כהנא."},{"i":3338,"n":"רבין בר ממל","l":"ר","b":"מובא בירושלמי (ב\"מ פ\"ה ה\"ה), וגירסת \"סה\"ד\" שהוא אבא בר ממל."},{"i":3339,"n":"רבין בר קיסי","l":"ר","b":"אמורא בבלי בדור החמישי. מרבותיו של רבינא (חולין כ\u0027 ע\"ב)."},{"i":3340,"n":"רבין בר רב אדא","l":"ר","b":"אמורא בבלי בדור השלישי. למד עם רבא בר רב אדא (נראה שהיה אחיו), ושניהם למדו יחד בבית מדרשו של רב יהודה (ביצה ל\"ג ע\"ב)."},{"i":3341,"n":"רבין בר רב חסדא","l":"ר","b":"אמורא ארץ ישראלי בדור השני. הביא גט לפני רבי יוחנן (גיטין ה\u0027 ע\"ב). יש ממנו מאמרי אגדה (ב\"ר פי\"א - ב\u0027)."},{"i":3342,"n":"רבין בר שבא","l":"ר","b":"אמורא בדור השלישי. מרבותיו של רבא (חולין מ\"ח ע\"א). מאמרו: \"משעלו בני הגולה פסקו הזיקין\" (שם פ\"ו ע\"א)."},{"i":3343,"n":"רבין בר שמואל","l":"ר","b":"אמורא בבלי בדור השני. מסר בשם שמואל (ב\"ב מ\"ג ע\"א)."},{"i":3344,"n":"רבין בריה דרב נחמן","l":"ר","b":"אמורא בבלי בדור השלישי. תלמידו החביב של רב יהודה, שפנה אליו בלשון חיבה: \"אחי\" (ב\"מ ק\"ז ע\"א). עמד בקשר עם רב ששת (יבמות ק\"ט ע\"ב)."},{"i":3345,"n":"רבין דמן נרש","l":"ר","b":"חי בבבל בדור הששי לאמוראים. מצינו שעשה רפואה לבתו של רב אשי ונתרפאה (גיטין ס\"ט ע\"ב). אינו בהכרח חכם."},{"i":3346,"n":"רבין חסידא","l":"ר","b":"זמנו ומקומו אינם ידועים, מצינו שהלך לקדש אשה לבנו וקדשה לנפשיה (קדושין נ\"ט ע\"א)."},{"i":3347,"n":"רבין סבא א\u0027","l":"ר","b":"אמורא בבלי בדור השני. תלמידו של רב (קידושין נ\"ג ע\"ב). \"דק\"ס\" משנה הגירסאות וסובר, שרק רבין סבא אחד היה, תלמידו של רב פפא."},{"i":3348,"n":"רבין סבא ב\u0027","l":"ר","b":"אמורא בבלי בדור הששי. תלמידו של רב פפא (ב\"ב קמ\"ו ע\"ב). ע\"ע רבין סבא ב\u0027."},{"i":3349,"n":"רבין תכלא","l":"ר","b":"מובא בבבלי (חולין ק\"י ע\"א), והוא רבין. ופרש\"י: \"קובר בניו היה\" (פסחים ע\u0027 ע\"ב ד\"ה: אבין)."},{"i":3350,"n":"רבינא (2)","l":"ר","b":"מגדולי אמוראי בבל בדור הששי. בנעוריו היה תלמידו המובהק של רבא (ב\"ב ט\"ז ע\"ב). הקשה לרבא ורבא איכסיף (ע\"ז כ\"ב ע\"א). בחיי רבא הגיע להוראה (עירובין מ\u0027 ע\"א), ולמד יחד עם רב פפא לפני רבא (זבחים ב\u0027 ע\"ב), ובכל זאת היה לתלמיד - חבר לרב אשי (עירובין ס\"ג ע\"א) שמעולם לא ראה את רבא (קידושין ע\"ב ע\"ב), ושניהם שקלו וטרו בכל הש\"ס, ולהם מיוחסת עריכת התלמוד: \"רב אשי ורבינא סוף הוראה\" (ב\"מ פ\"ו ע\"א) - נראה, שהכוונה שאז התחילו לערוך ולסדר את התלמוד, שכן התלמוד נחתם בשנת ד\u0027 ר\"ס (005). מושבו היה במתא מחסא (ליד סורא), כמו שכתב רש\"י (יומא פ\"ו ע\"א ד\"ה: ומתא מחסא), וגם מקומו של רב אשי היה שם (ברכות י\"ז ע\"ב), ורש\"י כתב שרבינא מארץ ישראל היה (מנחות מ\"ב ע\"א ד\"ה: חד) נפטר 07 שנה אחרי רבא, בשנת ד\u0027 קפ\"א (124) (ספר כריתות - ויטרי)."},{"i":3351,"n":"רבינא בר אבינא","l":"ר","b":"מובא בויק\"ר (פ\"ד - ג\u0027), ונראה שצ\"ל: רבי ביבי בר אבינא."},{"i":3352,"n":"רבינא בר ירמיה","l":"ר","b":"אמורא בבלי בדור השביעי. רב סמא בריה דרב אשי הקשה לו (ע\"ז נ\u0027 ע\"ב). \"דק\"ס\" מחק תיבת בר ירמיה."},{"i":3353,"n":"רבינא בר סילא","l":"ר","b":"מובא בבבלי (זבחים ל\"ו ע\"ב), וצ\"ל: רבינא בר שילא."},{"i":3354,"n":"רבינא בר סיסי","l":"ר","b":"מובא ב\"ילקוט\" (איוב רמז תתקכ\"ג)."},{"i":3355,"n":"רבינא בר קיסי","l":"ר","b":"מובא בבבלי (ב\"ב ס\"ג ע\"א), ואולי הוא רביא בר קיסי (ע\"ע)."},{"i":3356,"n":"רבינא בר שילא","l":"ר","b":"אמורא בבלי בדור הראשון. רב חסדא קיבל ממנו (מו\"ק י\"ט ע\"ב)."},{"i":3357,"n":"רבינא בריה דר\u0027 עולא","l":"ר","b":"מובא בבבלי (ביצה ג\u0027 ע\"ב). \"סה\"ד\" סבור, שהוא ר\u0027 בנאה בריה דר\u0027 עולאי."},{"i":3358,"n":"רבינא זוטי","l":"ר","b":"אמורא בבלי בדור השביעי, ואולי הוא רבינא האחרון, שהוא רבינא בר רב הונא. היה בן אחות רבינא, והיה יתום, והחזיק ברשותו את חמוריו (כתובות ק\u0027 ע\"ב)."},{"i":3359,"n":"רבינא מפרזקיא","l":"ר","b":"אמורא בבלי בדור השביעי. הקשה לרב אשי (נזיר ל\"ח ע\"ב). אולי צ\"ל: רבא מפרזיקא."},{"i":3360,"n":"רבינו הקדוש","l":"ר","b":"הוא רבי יהודה הנשיא."},{"i":3361,"n":"רבמי","l":"ר","b":"מובא בירושלמי (ע\"ז פ\"ה הי\"א), והוא רבי אמי."},{"i":3362,"n":"רבנא אשי","l":"א","b":"מובא בבבלי (כתובות כ\"ב ע\"א), והוא רב אשי."},{"i":3363,"n":"רבנא נחמיה (2)","l":"נ","b":"ע\"ע רבנא נחמיה."},{"i":3364,"n":"רבנא נחמיה אחוה דריש גלותא","l":"נ","b":"מובא בבבלי (שבת כ\u0027 ע\"ב), שרבין ואביי ישבו לפניו. נראה, שהוא רבנא נחמיה בר ברתיה דרב."},{"i":3365,"n":"רבנא נחמיה בן ברתא דרב","l":"נ","b":"אמורא בבלי בדור השלישי. עליו ועל אחיו עוקבא אמרו שהם \"שרי גאים היוצאים מישראל\" (חולין צ\"ב ע\"א), ואולי היו מתלמידיו של רב חסדא (ב\"ב נ\"א ע\"ב). נראה, שהוא רבנא נחמיה אחוה דריש גלותא, שאביי ישב לפניו (שבת כ\u0027 ע\"ב)."},{"i":3366,"n":"רבנא עוקבא (2)","l":"ע","b":"אמורא בבלי בדור השלישי. הוא ואחיו רבנא נחמיה, היו בני בתו של רב, ושניהם מכונים: \"שרי גאים היוצאים מישראל\" (חולין צ\"ב ע\"א). הוא ואחיו רבנא נחמיה אמרו לרב חסדא: \"שביק מר רברבי ועבוד כזוטרי\" (ב\"ב נ\"א ע\"ב), אך אין בכך ראיה שהיו תלמידיו, ואפשרי שהיו חבריו ואין ראיה ממה שמצינו: \"אדבריה רב חסדא לרבנא עוקבא\" (ביצה כ\"ט ע\"א). פרש\"י: \"הנהיג ומטייל עמו במבואות העיר\"."},{"i":3367,"n":"רבנא עוקבא בר ברתיה דרב","l":"ע","b":"ע\"ע רבנא עוקבא."},{"i":3368,"n":"רבנא עוקבא ורבנא נחמיה בני ברתיה דרב","l":"ע","b":"ע\"ע רבנא נחמיה בן ברתא דרב; רבנא עוקבא."},{"i":3369,"n":"רבנאי","l":"ר","b":"אמורא בבלי בדור השביעי. מובא בבבלי, שאמר משמיה דאביי (ברכות ל\"ח ע\"ב)."},{"i":3370,"n":"רבנאי אחוה דר\u0027 חייא בר אבא","l":"ר","b":"אמורא ארץ ישראלי בדור השלישי. מובא בבבלי (כתובות כ\"א ע\"ב), והוא רב ינאי אחוה דר\u0027 חייא בר אבא."},{"i":3371,"n":"רבנאי חוזאי","l":"ר","b":"אמורא ארץ ישראלי בדור הראשון - השני. אחיו היה רב תחליפא: \"רב תחליפא אחוה דרבנאי חוזאה\" (ביצה ט\"ו ע\"ב). רבי אבהו הוסיף על דבריו."},{"i":3372,"n":"רבסי","l":"ר","b":"מובא בירושלמי (ע\"ז פ\"ה הי\"א), והוא רבי אסי."},{"i":3373,"n":"רבי רדיפה","l":"ר","b":"אמורא ארץ ישראלי בדור הששי. מסר הרבה משם רבי יונה (ירו\u0027, פאה פ\"ד ה\"ה)."},{"i":3374,"n":"רובין","l":"ר","b":"כינוי ליהודה וחזקיה, בניו של רבי חייא (חולין כ\u0027 ע\"א)."},{"i":3375,"n":"רבי רומנוס","l":"ר","b":"מהתנאים האחרונים או מהאמוראים הראשונים. תלמידו של רבי: \"א\"ר רומנוס \u0027לי התיר רבי לטלטל\u0027\" (שבת מ\"ז ע\"א). רבי שלחו לאנטונינוס קיסר (ירו\u0027, מגילה פ\"א הי\"א), וכן שלחו לעיר אחת בארץ ישראל (יבמות ס\u0027 ע\"ב)."},{"i":3376,"n":"רחבא","l":"ר","b":"הוא רחבא דפומבדיתא."},{"i":3377,"n":"רחבא דפומבדיתא","l":"ר","b":"אמורא בבלי בדור השלישי. תלמידו המובהק של רב יהודה (פסחים נ\"ב ע\"ב), והיה מדקדק בלשון רבו וקבע לעצמו סימנים (ברכות ל\"ג ע\"ב רש\"י). התחתן עם חומה בת איסי (נכדתו של רב יהודה), ואחרי פטירתו התחתנה חומה עם רב יצחק בריה דרבה בר בר חנה, ואחרי שהוא נפטר התחתנה עם אביי, וגם הוא מת בחייה (יבמות ס\"ד ע\"ב). רחבא הניח שני בנים חכמים, איפא ואבימי, שנקראו \"חריפי שפומבדיתא\" (סנהדרין י\"ז ע\"ב), או \"בני רחבא\" (שבת ק\"ג ע\"א). \"סה\"ד\" כתב: \"ונראה דאיפא ואבימי לא היו מן אשתו חומה\"."},{"i":3378,"n":"ר\u0027 רחומאי","l":"ר","b":"חי בזמן התנאים בדור הרביעי. מובא ב\"זוהר\", שהיה זקן מאד ועיניו כהות, ואמר לר\u0027 פנחס: \"שמעתי שלרבי שמעון [בן יוחאי] יש מרגלית אבן טובה [בנו רבי אלעזר בר שמעון]\" (הקדמה י\"א)."},{"i":3379,"n":"רב רחומי א\u0027","l":"ר","b":"אמורא בבלי בדור הרביעי. תלמידו של אביי (פסחים ל\"ט ע\"א). תלמידו המובהק של רבא (כתובות ס\"ב ע\"ב), ונפטר בחייו. מסופר, שבכל ערב יום כיפור היה שב לביתו מישיבתו של רבא, ופעם נמשך אחרי לימודו ולא חזר לביתו, ואשתו ציפתה לשובו וכל הזמן אמרה: עכשיו יבוא עכשיו יבוא, ולא בא, והתחילה לבכות, ובאותה שעה ישב רב רחומי בקומה שניה, ונשברה הרצפה תחתיו ונפל ומת (כתובות ס\"ב ע\"ב)."},{"i":3380,"n":"רב רחומי ב\u0027","l":"ר","b":"אמורא בבלי בדור השביעי. תלמידו של רבינא (חברו של רב אשי): \"יתיב רב רחומי קמיה דרבינא, ויתיב וקאמר משמיה דרב הונא בר תחליפא\" (זבחים ע\"ז ע\"א). עמד בראש ישיבת פומבדיתא אחרי רפרם בשנים ד\u0027 ר\"ב - ר\"ח (244 - 844). בסוף ימיו היו גזרות חמורות מהמלך יזדגרד (\"אגרת רב שרירא גאון\")."},{"i":3381,"n":"רב רחומי ג\u0027","l":"ר","b":"מאמוראי בבל האחרונים בדור השמיני. נמנה עם חכמי רבנן סבוראי (\"אגרת רב שרירא גאון\"). דבריו מובאים בתלמוד (עירובין י\"א ע\"א). חלק עם רב יוסף, גם הוא מרבנן סבוראי (שם), ומובא לפניו."},{"i":3382,"n":"רב רחומי מבירתא דשחורי","l":"ר","b":"כן הביא ה\"אור זרוע\" (מגילה כ\"א ע\"ב)."},{"i":3383,"n":"ר\u0027 רימון","l":"ר","b":"כן גיר\u0027 \"סה\"ד\" ממדרש שמואל (רפי\"ג), ולפנינו: ר\u0027 סימון."},{"i":3384,"n":"ריש לקיש","l":"ר","b":"הוא רבי שמעון בן לקיש."},{"i":3385,"n":"רכיש בר פפא","l":"ר","b":"אמורא בבלי בדור השני. מסר משם רב (חולין מ\"ב ע\"ב)."},{"i":3386,"n":"רמי בר אבא א\u0027","l":"ר","b":"אמורא בבלי בדור השני - השלישי. תלמידו של רב הונא (עירובין ס\"א ע\"א). נראה, שהיה בארץ ישראל וקיבל מרבי אסי (שם ק\u0027 ע\"ב). היה רבו של רב יוסף (שם ס\"א ע\"א). סיפר על תקנות שרבי יוסי (בר חלפתא) התקין בציפורי (סנהדרין י\"ט ע\"א). אילולי ידענו שרמי בר אבא אמור, וחי דורות אחרי רבי יוסי בר חלפתא, היינו מדמים בטעות שהוא מספר את שראה. יש ממנו כמה מאמרי אגדה בתלמוד (נדרים ל\"ב ע\"א), ושם יש גורסים: ר\u0027 אמי בר אבא."},{"i":3387,"n":"רמי בר אבא ב\u0027","l":"ר","b":"אמורא בבלי בדור הששי. מובא בבבלי: \"אתא לקמיה דרב פפא ואסר ליה\" (מגילה כ\"ו ע\"ב). קשה לומר שזה רמי בר אבא תלמידו של רב הונא."},{"i":3388,"n":"רמי בר אבא חמוה דרב אשי","l":"ר","b":"מובא בבבלי (חולין קי\"א ע\"ב)."},{"i":3389,"n":"רמי בר אבין","l":"ר","b":"אמורא בבלי. נראה שהיה בדור השלישי, בזמנו של רב יוסף. דבריו מובאים אחרי רב יוסף: \"אלא אמר רב יוסף: \u0027שוכא דארזא\u0027. רמי בר אבא אמר: \u0027זאזא\u0027\" (שבת כ\u0027 ע\"ב)."},{"i":3390,"n":"רמי בר ברבי","l":"ר","b":"מובא בבבלי: \"נהרבלאי\" (סנהדרין י\"ז ע\"ב), והכוונה לרמי בר ברבי. רש\"י גרס: רמי בר ברוכי (ביצה ח\u0027 ע\"ב ד\"ה: נהרבלאי; וכן גירסת ה\"ערוך\" בערך נהר)."},{"i":3391,"n":"רמי בר ברוכי","l":"ר","b":"(ע\"ע רמי בר ברבי)."},{"i":3392,"n":"רמי בר דיקולי","l":"ר","b":"מובא בבבלי, והוא רמי בר תמרי (יבמות פ\u0027 ע\"א)."},{"i":3393,"n":"רמי בר חמא","l":"ר","b":"אמורא בבלי בדור הרביעי. תלמידו של רב חסדא (עירובין ח\u0027 ע\"ב). הוא ואחיו רב עוקבא בר חמא נשאו לנשים את בנות רב חסדא (ברכות מ\"ד ע\"א). למד יחד עם רבא לפני רב חסדא (ב\"ב י\"ב ע\"ב). נפטר בחיי רבא (ברכות מ\"ז ע\"ב). אשתו התחתנה אח\"כ עם רבא (יבמות ל\"ד ע\"ב, ושם רש\"י ותוס\u0027). בהיות בת רב חסדא ילדה קטנה התנבאה שרוצה להתחתן עם שניהם (ב\"ב י\"ב ע\"ב). הצטיין בחריפות (עירובין צ\u0027 ע\"א; ב\"ב קט\"ז ע\"ב; ב\"מ צ\"ו ע\"ב). רב ירמיה קרא לו: גברא רבא (עירובין צ\u0027 ע\"א). מסופר, שרב יצחק בר יהודה היה רגיל ללמוד אצל רמי בר חמא, ועבר ללמוד אצל רב ששת, והסביר לרמי בר חמא שעזבו, מפני שמתרץ מסברא, ורב ששת מתרץ ומביא ברייתות לסיוע (זבחים צ\"ו ע\"ב). היו לו שתי בנות: אחת היתה אמו של האמורא אמימר (כתובות כ\"א ע\"ב), ואחת התחתנה עם רב אשי (ביצה כ\"ט ע\"ב)."},{"i":3394,"n":"רמי בר יחזקל","l":"ר","b":"אמורא בבלי בדור השני. אחיו של רב יהודה האמורא המפורסם. כשלמד לפני אביו רב יחזקל תיקן אחיו רב יהודה לאביו, ושמואל העיר לו שלא יתקן לאביו (קידושין ל\"ב ע\"א). למד גם לפני רב (חולין מ\"ד ע\"א) ולפני שמואל (כתובות ס\u0027 ע\"א). ביקר בארץ ישראל (שם קי\"א ע\"ב), וחזר משם: \"כי אתא רמי בר יחזקל, אמר: \u0027לא תציתינהו להני כללי דכייל יהודה אחי משמיה דשמואל\u0027\" (שם כ\"א ע\"א)."},{"i":3395,"n":"רמי בר פפא","l":"ר","b":"אמורא בבלי בדור השלישי. שאל לרב יהודה בעמדו על שפת נהר אמברא, ורב יהודה עמד בעבר השני (יומא ע\"ז ע\"ב). אחותו נישאה לרב אויא, ומתה בחיי רב אויא (ב\"ב ק\u0027 ע\"ב). ואמר רב יוסף עליו שטעה בשני דברים (שם)."},{"i":3396,"n":"רמי בר רב","l":"ר","b":"אמורא בבלי בדור השני. תלמידו של רב (שבת ל\"ב ע\"ב)."},{"i":3397,"n":"רמי בר רב יוד","l":"ר","b":"אמורא בבלי בדור השני. תלמידו של רב (פסחים ס\"ב ע\"ב). ע\"ע רמי בר רב יודא."},{"i":3398,"n":"רמי בר רב יודא","l":"ר","b":"כך מובא בבבלי: \"רמי בר רב יודא אמר רב\" (זבחים נ\"ה ע\"ב). \"דק\"ס\" גרס: רב יוד, ו\"סה\"ד\" חילקם לשניים: רב יוד (תענית כ\"ב ע\"ב) ורב יודא וא\"כ, שניהם היו לדעת \"סה\"ד\" תלמידיו של רב, ורש\"י פירש: \"חכם ששמו יוד\" (תענית, שם). וכן: \"רמי בר רב יודא אמר רב\" (פסחים ס\"ב ע\"ב)."},{"i":3399,"n":"רמי בר שמואל","l":"ר","b":"אמורא בבלי בדור השלישי. תלמידו של רב הונא. יחד עם חברו רב יצחק בריה דרב יהודה למדו מסכת נדה בישיבת רב הונא ושמע רבה בנו של רב הונא שלמדו וכו\u0027, הלך ואמר לרב הונא וכו\u0027 (נדה י\"ז ע\"ב). היה חברו של רב נחמן ואמר לו לר\"נ על פסק דינו: \"א\"כ נמצאת מכשילן לעתיד לבוא וכו\u0027\" (כתובות צ\"ז ע\"א)."},{"i":3400,"n":"רמי בר תמרי","l":"ר","b":"אמורא בבלי בדור השלישי. תלמידו של רב יהודה (חולין ק\"י ע\"א) והוא רמי בר דיקולי (שם). היה חריף ושקיל וטרי עם רב חסדא שאמר לו: \"חזינא לך דחריפא טובא\". היה גם תלמידו של ר\"ז (מנחות כ\"ט ע\"ב)."},{"i":3401,"n":"רמי בריה דרב ייבא","l":"ר","b":"אמורא בבלי. נראה, שהיה בזמנו של אביי או אחריו (ערכין י\"א ע\"ב)."},{"i":3402,"n":"רפרם","l":"ר","b":"אמורא בבלי בדור השביעי. תלמידו של רב אשי (כתובות צ\"ה ע\"ב). חברו של רבינא האחרון: \"רבינו סבר לאכשורי וכו\u0027 אמר ליה רפרם וכו\u0027\" (גיטין י\"א ע\"א). אחרי רב גביהה מבי כתיל עמד בראש ישיבת פומבדיתא בשנים ד\u0027 קצ\"ב - ד\u0027 ר\"ב (234 - 244). רב אבהו האחרון היה מראשי כלה בישיבתו: \"אמר רב שמואל בריה דרב אבהו [היה מראשוני רבנן סבוראי]: \u0027אבא מרישי כלי דרפרם הוה\u0027\" (חולין מ\"ט ע\"א)."},{"i":3403,"n":"רפרם בר פפא א\u0027","l":"ר","b":"אמורא בבלי בדור הרביעי. תלמידו של רב חסדא (שבת פ\"ב ע\"א) ותירגם קמיה. ומצינו: \"אמר רפרם בר פפא אמר רב חסדא וכו\u0027, א\"ל רבא לרפרם בר פפא: \u0027מנא ליה לסבא הא וכו\u0027\" (נדה ס\"א ע\"ב). היה קשיש מרבא: \"א\"ל רבא [לרפרם בר פפא]: \u0027לימא לן מר מהני מילי מעלייתא דאמרת משמיה דרב חסדא\u0027\" (ברכות ח\u0027 ע\"א), הכיר את רב הונא ורבא אמר לו: \"לימא לן מר מהני מילי מעליתא דהוה עביד רב הונא\" (תענית כ\u0027 ע\"א)."},{"i":3404,"n":"רפרם בר פפא ב\u0027","l":"ר","b":"אמורא בדור החמישי נראה תלמידו של רבא, ורבא קראו לו: \"פתיא אוכמא\" (ברכות נ\u0027 ע\"א), ופרש\"י: \"כלי חרס\". נראה, שהוא רפרם המוזכר שמלך בפומבדיתא בשנים ד\u0027 קמ\"ד - קנ\"ד (483 - 493) אחר רב דימי מנהרדעא (\"אגרת רב שרירא גאון\")."},{"i":3405,"n":"רפרם בר פפא מסיכרא","l":"ר","b":"מובא בבבלי (פסחים ל\"א ע\"ב). מצינו אותו ענין \"רפרם מסיכרא\" (ב\"מ מ\"ב ע\"א) ופרש\"י: \"שם מקום\"."},{"i":3406,"n":"רפרם מסיכרא","l":"ר","b":"מובא בבבלי (ב\"מ מ\"ב ע\"א), ובמקום אחר הגיר\u0027: רפרם בר פפא מסיכרא (פסחים ל\"א ע\"ב)."},{"i":3407,"n":"רבי שאול","l":"ש","b":"אמורא ארץ ישראלי, שאין לקבוע זמנו המדוייק. מובא בירושלמי: \"רבי זירא בעי וכו\u0027 א\"ר שאול וכו\u0027\" (מעשרות פ\"ג ה\"ב), ואין ראיה מכך שהיה בזמנו של רבי זירא. \"יוחסין\" כתב: \"ר\u0027 שאול בזמן ר\u0027 זירא\" (נראה, שהסתמך על המקור הנ\"ל), ו\"סה\"ד\" כתב: \"לא מצאתי\"."},{"i":3408,"n":"ר\u0027 שאול דנוה","l":"ש","b":"מובא בקה\"ר (פי\"ב - י\u0027)."},{"i":3409,"n":"רב שבא","l":"ש","b":"אמורא בבלי. \"יוחסין\" כתב, שהיה בזמן רבא (דור רביעי לאמוראים). מצינו: \"א\"ל רב שבא לרב כהנא\" (הוריות ה\u0027 ע\"ב)."},{"i":3410,"n":"שבור מלכא","l":"ש","b":"כינוי לשמואל (פסחים נ\"ד ע\"א). ויש אומרים (שם) שהוא כינוי לרבא (ו\"מסה\"ש\" כתב: רבה). הרשב\"ם פירש: \"שמואל, קרי ליה רבא שבור מלכא [רבא קרא לו שבור מלכא] משום דבקי היה בדינין, והלכתא כוותיה בדיניה, כדין היוצא מפי המלך שמתקיים, ושבור מלכא, מלך פרסיים היה בימי רבא\". ע\"ע אריוך."},{"i":3411,"n":"שבנא אחי הלל","l":"ש","b":"אחיו של הלל הנשיא. עסק במסחר, ורצה לפרנס את הלל ולהיות שותף ללימודו של הלל, ויצאה בת קול ומנעה את העיסקה (סוטה כ\"א ע\"א). אין ראיה שנמנה עם החכמים."},{"i":3412,"n":"שבנא איש ירושלים","l":"ש","b":"מובא בבבלי (שבת י\"ב ע\"ב), ופרש\"י: \"אדם גדול היה\"."},{"i":3413,"n":"ר\u0027 שבתאי","l":"ש","b":"ע\"ע ר\u0027 שבתי."},{"i":3414,"n":"ר\u0027 שבתי","l":"ש","b":"אמורא ארץ ישראלי בדור הראשון - השני. תלמידו של רבי יצחק מגדלאה (נדה כ\"ז ע\"ב), הגמרא מפקפקת שם מי אמר בשם מי - ר\u0027 יצחק מגדלאה בשם ר\u0027 שבתי או ר\u0027 שבתי בשם ר\u0027 יצחק מגדלאה. רבי יוחנן וריש לקיש דנו במאמרו (שם). שמו של ר\u0027 שבתי שובש בכמה פנים: שבתאי, שובתיי, שובתי. תוספות כתבו, שצריך לגרוס \"שבתי\", כי שבתאי הוא שם עכו\"ם (גיטין י\"א ע\"א), ואכן מצינו, שהיה רשע ושמו שבתאי (יומא פ\"ב ע\"ב)."},{"i":3415,"n":"שבתי בריה דר\u0027 מרינוס","l":"ש","b":"חי בארץ ישראל בדור הראשון לאמוראים. ביקר בבבל (ביצה ל\"ב ע\"ב), ושם אולי מוכח שהיה מן החכמים, אך מצינו שכתב לכלתו בכתובתה לבוש של משי, וכשאבדה כתובתה אמר: \"לא היו דברים מעולם\" (ב\"מ י\"ז ע\"א). אם כן, קצת קשה לומר שהיה מן האמוראים. ולפי גיר\u0027 הרי\"ף והרא\"ש (שם) יתכן לומר שהיה מן החכמים."},{"i":3416,"n":"שובחה","l":"ש","b":"מובא בבבלי (ב\"ק צ\"א ע\"ב). ע\"ע שכחת."},{"i":3417,"n":"ר\u0027 שובתי","l":"ש","b":"ע\"ע ר\u0027 שבתי."},{"i":3418,"n":"ר\u0027 שובתי הצדוקי","l":"ש","b":"אמורא ארץ ישראלי בדור השני. רבי אלעזר הורה לו כמו שאמר רבי שמעון בן שזורי (ירו\u0027, שבועות פ\"ב ה\"ה)."},{"i":3419,"n":"ר\u0027 שובתיי","l":"ש","b":"ע\"ע ר\u0027 שבתי."},{"i":3420,"n":"שוקד","l":"ש","b":"ע\"ע שקוד."},{"i":3421,"n":"שיבחה ברי","l":"ש","b":"מובא בבבלי (ב\"ק צ\"א ע\"ב). ע\"ע שכחת."},{"i":3422,"n":"רב שיזבי","l":"ש","b":"אמורא בבלי בדור הרביעי. רב חסדא נהג לעבור ליד ביתו של אביו של רב שיזבי, וכשראה שהיה מדליק נרות רבים לכבוד שבת, אמר: אדם גדול יצא מכאן, ונולד לו רב שיזבי (שבת כ\"ג ע\"ב). היה תלמידם של רב חסדא (שם ק\"כ ע\"א) ושל רב הונא (בכורות י\"א ע\"א). קיבל גם מרבא (ב\"מ קי\"ד ע\"ב). רבא אמר עליו: \"גברא רבא\" (גיטין נ\"ה ע\"ב)."},{"i":3423,"n":"רב שייא","l":"ש","b":"אמורא בבלי בדור השביעי. מצינו: \"אמר רב שייא: כוותיה דרב אשי מסתברא\" (זבחים ל\"ד ע\"ב)."},{"i":3424,"n":"רבי שיין","l":"ש","b":"אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של רב אחא (ירו\u0027, עירובין פ\"א ה\"ו). מצינו: \"א\"ר שיין: \u0027זה שהוא מתמני בכסף אין עומדין בפניו, ואין קורין אותו רבי, והטלית שעליו כמרדעת של חמור\u0027\" (ירו\u0027, בכורים פ\"ג ה\"ג). נראה לומר, שרבי אשיאן ור\u0027 אשיין אחד הוא."},{"i":3425,"n":"שילא (2)","l":"ש","b":"אחיו של רבי חייא, ודודו של רב (סנהדרין ה\u0027 ע\"א), היו לו עוד ארבעה אחים: איבו (אביו של רב), מרתא, חנה (אביו של רבה בר חנה) ורבי חייא."},{"i":3426,"n":"רב שילא","l":"ש","b":"אמורא בבלי בדור הראשון. היה ריש סידרא בבבל, אחר פטירת רבי (\"אגרת רב שרירא גאון\"). כשרב בא לבבל לא הכירו רב שילא, ורב היה זמנית האמורא שלו, וכשר\u0027 שילא הכיר בו שהוא רב, אמר לו: \"לך ושב בכבודך שאינך כדאי שתהא מתורגמני\" (יומא כ\u0027 ע\"ב). ואחרי כן קיבל רב שילא מרב (ברכות מ\"ט ע\"ב). רב לא רצה לפגוע בכבודו: \"דרוש ר\u0027 שילא וכו\u0027, בתר דנפק איקום רב אמורא עליה ודרש וכו\u0027\" (סנהדרין מ\"ד ע\"א) ופרש\"י: \"ולא יפה דרש רבי שילא\", ולכן תיקן רב את דבריו. התיר אשה שבעלה טבע במים שאין להם סוף, ורב רצה לנדותו על כך (כי טעה בדין) ושמואל מנעו מכך (יבמות קכ\"א ע\"א). בין תלמידיו היה רב חסדא (כתובות ע\"ה ע\"א)."},{"i":3427,"n":"רבי שילא","l":"ש","b":"תנא בדור השלישי. מינוהו שופט על פי הקיסר. מסופר שנעשו לו נסים לאחר שהלשינו עליו (ברכות נ\"ח ע\"א), ואליהו בא להצילו (שם). רבן שמעון בן גמליאל (אבי רבי) מסר משמו (תוספתא כלים פ\"ד ט\u0027)."},{"i":3428,"n":"רבי שילא איש כפר תמריתא","l":"ש","b":"מובא בבבלי (מגילה ט\"ז ע\"ב), והוא רב שילא איש כפר תמרתה."},{"i":3429,"n":"רב שילא איש כפר תמרתה","l":"ש","b":"אמורא ארץ ישראלי בדור השני - השלישי. מסר משם רבי יוחנן (ירו\u0027, חגיגה פ\"ג ה\"ח). ר\u0027 לוי אמר בשמו (ב\"ר פמ\"ה - ד\u0027), וכן מצינו: \"אמר רבי אסי: \u0027דרש רבי שילא איש כפר תמרתא\u0027\" וכן מצינו: \"א\"ר חנינא בר פפא: \u0027דרש ר\u0027 שילא איש כפר תמריתא\u0027\" (מגילה ט\"ז ע\"ב)."},{"i":3430,"n":"רב שילא בר אבינא","l":"ש","b":"אמורא בבלי בדור השני. מתלמידיו המובהקים של רב. לפני פטירתו של רב אמר לרב אסי: \"זיל צנעיה [אמור לרב שילא בר אבינא שיחזור בו מדעתו על דין מסויים] ואי לא גרייה\" [כלומר אם לא ירצה משוך אותו בדברי טעם ושכנוע וראיות שיחזור בו], ורב אסי הבין במקום \"גרייה\" \"גדייה\" (כלומר הכריחו בשמתא), ומאחר שרב שילא בר אבינא לא רצה לחזור בו, הכניסו רב אסי לשמתא, ורב אסי חלה ונפטר. ובעקבות זאת נפטר מיד לאחריו גם רב שילא בר אבינא."},{"i":3431,"n":"שילא בר בריה דרב אחא","l":"ש","b":"מובא ב\"ילקוט\" (יחזקאל רמז שסו)."},{"i":3432,"n":"ר\u0027 שילא בר יצחק","l":"ש","b":"מובא במדרש תהלים (הישן פצ\"א)."},{"i":3433,"n":"שילא בר מרי","l":"ש","b":"מובא בבבלי (גיטין נ\"ח ע\"א), ו\"סה\"ד\" כתב: \"תיבת בר ט\"ס\", וצ\"ל: שילא מרי."},{"i":3434,"n":"ר\u0027 שילא דינוה","l":"ש","b":"מובא בירושלמי, שרבנן דקיסרין אמרו בשמו (שבת פ\"ב ה\"ה)."},{"i":3435,"n":"ר\u0027 שילא דכפר תמרתא","l":"ש","b":"ע\"ע רב שילא איש כפר תמרתה."},{"i":3436,"n":"שילא מרי","l":"ש","b":"מובא בבבלי: \"אמר רב כהנא ואיתימא שילא מרי\" (שבת ל\"ב ע\"ב). וכן: \"אמר רב שמואל בר יהודה: \u0027וכן תני שילא מרי\u0027\" (שם מ\"ג ע\"ב)."},{"i":3437,"n":"רבי שילא משלנייא","l":"ש","b":"אמורא בבלי בדור הששי. לרב אשי היה יער במקום ששמו שלנייא, והלך לגזום בחול המועד, ואמר לו רב שילא משלנייא שאביי אסר ורב אשי ענה לו שהוא סובר שמותר. הגרזן נפל, וכמעט חתך את רגלו של רב אשי, וחש רב אשי שבגלל שעבר על דברי אביי כמעט נענש והפסיק את המלאכה (מו\"ק י\"ב ע\"ב)."},{"i":3438,"n":"ר\u0027 שילה דנוהא","l":"ש","b":"מובא בויק\"ר (פל\"ד - ט\u0027), והוא ר\u0027 שילא דינוה."},{"i":3439,"n":"ר\u0027 שימי","l":"ש","b":"הוא ר\u0027 שמאי."},{"i":3440,"n":"רב שימי בר אבא","l":"ש","b":"אמורא בבלי בדור החמישי - הששי. \"יוחסין\" כתב, ששניים היו: אחד בימי רבי יוחנן ואחד בימי רב פפא. \"סה\"ד\" כתב: \"לא ידעתי מנין לו כי שניים היו\". וכנראה הוכיח \"יוחסין\" ששנים היו, שכן מצינו \"א\"ל רב שמן בר אבא [אמורא ארץ ישראלי בדור השלישי] לרב פפא\" [אמורא בבלי בדור הרביעי] (פסחים מ\"ט ע\"ב), ודק\"ס\" גרס: \"א\"ל רב שמי בר אבא לרב פפא\" (ולא רב שמן). וכן מצינו: \"מתיר ר\u0027 שימי בר אבא\" (נדרים ל\"ו ע\"א)."},{"i":3441,"n":"רב שימי בר אביי","l":"ש","b":"אמורא בבלי בדור הרביעי. מובא בבבלי, שאמר הלכה כר\u0027 יצחק שאמר משום רבי יוחנן (כתובות ס\u0027 ע\"א)."},{"i":3442,"n":"רב שימי בר אדא","l":"ש","b":"אמורא בבלי בדור הרביעי. מובא פעם בבבלי: \"א\"ל רב שימי בר אדא לרב פפא וכו\u0027 תיקו\" (נזיר נ\u0027 ע\"ב). אין להכריע שהיה תלמיד של רב פפא. \"סה\"ד\" מפקפק אולי יש ט\"ס בשם, וצ\"ל: רב שימי בר אבא, ואם נניח כדבריו כי אז יש למחוק שם חכם מהש\"ס, או שלא היה קיים חכם ושמו רב שימי בר אבא, או שלא היה קיים חכם ושמו רב שימי בר אדא."},{"i":3443,"n":"רב שימי בר אשי","l":"ש","b":"אמורא בבלי בדור החמישי. תלמיד מובהק של אביי (גיטין ס\u0027 ע\"ב). בתחילה אביי נהג להשקות את שדהו בלילה ורב שימי בר אשי השקה את שדהו של אביי ביום, ואביי למד עמו בלילה (נדה ל\"ג ע\"ב). מסר גם משם רבא (יומא ס\"ב ע\"ב). נהג לשאול הרבה מרב פפא, ופעם שמע את ר\"פ שהתפלל שה\u0027 יצילנו מבושות שאלותיו, ומיד גזר על עצמו שתיקה. נראה, שהיה לתלמיד - חבר לרב פפא (נדה שם). רב כהנא (חברו של רב אשי) היה תלמידו (תמורה כ\"ח ע\"א). בלע נחש ונתרפא על ידי אליהו הנביא (שבת ק\"ט ע\"ב). ריפא נכרי מצרעתו (גיטין ע\u0027 ע\"א). \"יוחסין\" כתב, שבשיטתו ריפא הרמב\"ם לישמעאלים (סמ\"ג מל\"ת מ\"ה)."},{"i":3444,"n":"רב שימי בר זירי","l":"ש","b":"אמורא בבלי בדור החמישי. תלמידו של רב פפא (תמורה כ\"ד ע\"א)."},{"i":3445,"n":"רב שימי בר חזקיה","l":"ש","b":"אמורא בבלי בדור השני. מסר בשם רב (כתובות ו\u0027 ע\"א)."},{"i":3446,"n":"שימי בר חייא בר רב","l":"ש","b":"אמורא בבלי בדור השלישי. בן בנו של רב. זכה להיות תלמידו המובהק (קידושין י\"ב ע\"א). רב אמר לו: \"שימי את\" (פרש\"י בכורות מ\"ג ע\"ב) \"חכם גדול כמותך אינו יודע לתרץ מתני\u0027\". רב ביקר אצלו (חולין קי\"א ע\"ב). פעם ישבו רב ושמואל ואכלו, ושימי בר חייא בר רב הצטרף אליהם לזימון (ברכות מ\"ז ע\"א)."},{"i":3447,"n":"רב שימי בר עוקבא","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי. מובא בבבלי, שהיה שכיח קמיה דר\u0027 שמעון בן פזי, והיה מסדר אגדתא קמיה דרבי יהושע בן לוי (ברכות י\u0027 ע\"א)."},{"i":3448,"n":"רב שימי מבירתא דשיחורי","l":"ש","b":"מובא בבבלי: \"והתני רב שימי: \"מבירתא דשיחורי וכו\u0027\" (סוטה ל\"ח ע\"א)."},{"i":3449,"n":"רב שימי מחוזנאה","l":"ש","b":"אמורא בבלי בדור הרביעי - החמישי. מובא בבבלי (מכות ט\"ז ע\"א)."},{"i":3450,"n":"רב שימי מנהרדעא","l":"ש","b":"אמורא בבלי בדור החמישי. תלמידו של רבא, ו\"רבא טפח ליה בסנדליה וא\"ל עטו וכו\u0027\" (ב\"ק ל\"ב ע\"ב). ומפרש פלוגתא דרבה ורבא (עירובין כ\"ה ע\"א). ומצינו (שבועות י\"ב ע\"ב) רבא אמר: \"הא בורכא\" [פרש\"י: \"דבר הבדוי מן הלב דמנא לך הא\"] אמר ליה רב נחמן בר יצחק לרבא: \"מאי בוכרא אנא אמריתא ניהליה ומשמיה דרב שימי מנהרדעא אמריתא ניהליה\" (שבועות י\"ב ע\"ב)."},{"i":3451,"n":"רב שיננא בריה דרב אידי","l":"ש","b":"מובא בבבלי (גיטין פ\"ט ה\"ב). וגירסת הרי\"ף והרא\"ש: רב שישא. \"סה\"ד\" כתב: \"ואולי ט\"ס וצ\"ל: שישא\"."},{"i":3452,"n":"רב שישא בריה דרב אידי בר אבין","l":"ש","b":"אמורא בבלי בדור החמישי. בנו ותלמידו של האמורא רב אידי בר אבין (תענית י\"ג ע\"א). אחיו של האמורא רב יהושע בריה דרב אידי. הקשה על דברי רבא: \"ומי מצית אמרת וכו\u0027\" [ורבא ענה] (יבמות ע\"ד ע\"ב). שקיל וטרי עם רב פפא (ב\"מ ק\"ט ע\"א)."},{"i":3453,"n":"שכחת","l":"ש","b":"לדעת הרשב\"ם היה שכחת בנו של רבי חנינא (ב\"ב קכ\"ו ע\"ב ד\"ה שכחת ברי), אבל דעתו של רש\"י (שם כ\"ו ע\"א ד\"ה: שכחת ברי) ששמו של האיש היה שכחת ברי, והגירסא במקום אחר (ב\"קצ\"א ע\"ב): שיבחה."},{"i":3454,"n":"שכחת ברי","l":"ש","b":"מובא בבבלי (ב\"ב קכ\"ו ע\"ב), ע\"ע שכחת."},{"i":3455,"n":"ר\u0027 שלום","l":"ש","b":"מובא בב\"ר (פל\"ד - ט\u0027), שאמר בשם ר\u0027 מנחמא בר זעירא."},{"i":3456,"n":"ר\u0027 שלום בר מניומי","l":"ש","b":"מובא ב\"זוהר\" (בראשית קכ\"ד)."},{"i":3457,"n":"רב שלמון","l":"ש","b":"מובא במדרש (סוף רו\"ר), והוא רב שלמן."},{"i":3458,"n":"ר\u0027 שלמוני","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי. אמר בשם ר\"ל (ב\"ר פס\"ח - י\"ב)."},{"i":3459,"n":"רב שלמן","l":"ש","b":"אמורא בבלי בדור החמישי. שימש \"תנא\" שונה ברייתות, לפני רב נחמן בר יצחק. ומצינו: \"תני תנא קמיה דרנב\"י וכו\u0027 א\"ל: \u0027מה שמך\u0027 א\"ל: \u0027שלמן\u0027, א\"ל: \u0027שלום אתה ושלמה משנתך ששמת שלום בין התלמידים\u0027\" (ברכות ל\"ט ע\"ב), ומצינו: \"תרגמא רב שלמן\" (ב\"ב י\"ג ע\"ב)."},{"i":3460,"n":"שלמן בר לוי","l":"ש","b":"אמורא ארץ ישראלי בדור השני. אחיו של זבדי בר לוי. מסר בשם רב יהושע בן לוי (ירו\u0027, כלאים פ\"א ה\"ד)."},{"i":3461,"n":"רב שלמן מבי כלוחית","l":"ש","b":"מובא בבבלי: \"רב אדא ורב שלמן תרווייהו מבי כוחלת\" (ביצה ה\u0027 ע\"ב)."},{"i":3462,"n":"שמאי (2)","l":"ש","b":"מחכמי ה\"זוגות\" האחרונים. הוא וחברו הלל הזקן היו ה\"זוג\" החמישי והאחרון שהפריד בין סוף תקופת ה\"זוגות\" לתקופת התנאים. הלל שימש כנשיא ושמאי כאב בית דין (חגיגה ט\"ז ע\"א), ושניהם קיבלו מבני ה\"זוג\" שלפניהם, שמעיה ואבטליון (אבות פ\"א מי\"ב). הלל ושמאי הם אבות בית הלל ובית שמאי. ומסופר: \"ת\"ר, לעולם יהא אדם ענוותן כהלל ואל יהא קפדן כשמאי, מעשה בשני בני אדם וכו\u0027\" (שבת ל\u0027 סע\"ב). כל חייו היה אוכל לכבוד שבת, מצא בהמה נאה, אמר: \"זו לשבת, מצא אחרת נאה הימנה וכו\u0027\" (ביצה ט\"ז ע\"א). מתלמידיו מצינו את בבא בן בוטא, החכם שהורדוס עיוור את עיניו (גיטין נ\"ז ע\"א), ואת רבן יוחנן בן זכאי (אבות רפ\"ב)."},{"i":3463,"n":"ר\u0027 שמאי","l":"ש","b":"אמורא ארץ ישראלי בדור החמישי - הששי. תלמידו של רב אחא ומסר הרבה משמו (ירו\u0027, דמאי פ\"ח ה\"א). היה גם תלמידו של רבי יוסי (ירו\u0027, מעשרות פ\"ה ה\"א). ושקיל וטרי עם רבי מנא (ירו\u0027, שבת פ\"ג ה\"ב). בנו רבי אושעיא בר שמאי היה, כנראה, מחכמי קיסרין."},{"i":3464,"n":"שמואל","l":"ש","b":"מגדולי אמוראי בבל בדור הראשון. מכונה בכמה כינויים בש\"ס: \"מר שמואל\" (ברכות י\"ט ע\"א), \"שמואל ירחינאה\" ע\"ש חכמת העיבור (ב\"מ פ\"ה ע\"ב), \"שקוד\" (כתובות מ\"ג ע\"ב); פרש\"י: \"על שום ששוקד על דבריו לאומרם כהלכה\", ו\"הערוך\" פי\u0027 שהיה שוקד על דלתי תורה. \"שבור מלכא\" (ב\"ב קט\"ו ע\"ב) פרשב\"ם: \"ולפי שהלכה כמותו בדין, קרי ליה הכי, וכן נקרא: \"אריוך\" (חולין ע\"ו ע\"ב) ופרש\"י: \"קרי שמואל על שם אריוך מלך אלסר דהלכתא כוותיה בדיני\". לאחר שרב נפטר בסורא מלך הוא בנהרדעא, משנת ד\u0027 ז\u0027 - ד\u0027 י\"ג (742 - 352). אביו נודע בשם אבוה דשמואל, וכונה על שם בנו אף שהוא עצמו היה חכם גדול. מתלמידיו של רבי (ירו\u0027, ר\"ה פ\"ג ה\"ו), וראש בנהרדעא (ביצה ט\"ז ע\"ב). מסופר, שאביו בא בשם המפורש לביתו והוליד את שמואל (קידושין ע\"ג ע\"א תד\"ה: מאי). עלה לארץ ישראל ולמד לפני רבי, אך לא נסמך (ב\"מ פ\"ה ע\"ב). לוי היה רבו המובהק (מנחות ל\"ח ע\"ב). חברו המובהק של רב והלכותיהם פזורות בכל הש\"ס. ומצינו: \"רבותינו שבבבל - רב ושמואל\" (סנהדרין י\"ז ע\"ב). וכן \"הוויות דרב ושמואל\" (ברכות כ\u0027 ע\"א). אך רב היה גדול ממנו (ב\"ק פ\u0027 ע\"ב), ושמואל היה כייף לרב (מגילה כ\"ב ע\"א), ולמד ממנו 04 פעם (כתובות כ\"ב ע\"ב). כשנפטר רב, קרע עליו 21 בגדים ואמר: הלך אדם שפחדתי ממנו מקושיותיו (מו\"ק כ\"ד ע\"א). גדולי הדור שלאחריו היו תלמידיו, ובינהם רב יהודה (ברכות ל\"ו ע\"א), רב נחמן (שם כ\"ז ע\"ב) ורבי אבא (ירו\u0027, עירובין פ\"ו ה\"ז). כשנפטר רב, הלכו מתלמידי רב ללמוד לפני רב אסי. כדמצינו (יבמות י\"ז ע\"א רש\"י ד\"ה: כי) ורב אסי נפטר סמוך אחרי רב (נדה ל\"ו ע\"ב), ואז באו רבים מתלמידי רב לפני שמואל: \"שלחו מבי רב לשמואל: \u0027ילמדנו רבנו\u0027\" (גיטין ס\"ו ע\"ב) וסידר תוספתא כדפירש\"י \"בתוספתא שסידר שמואל מתנאים שלפניו, כמו שסידרו רבי חייא ורבי אושעיא, וכמו שסידר רבי את המשנה\" (ביצה כ\"ט סע\"א). שמואל היה רופא גדול (ב\"מ קי\"ג ע\"ב). הלך לארץ ישראל וריפא את רבי (ב\"מ פ\"ה ע\"ב). היה ידען גדול בחכמת התכונה, ואמר: \"נהירין לי שבילי דשמיא כשבילי נהרדעא\" (ברכות נ\"ח ע\"ב). היה מומחה גדול בדיני ממונות, ובכל המחלוקות בין רב לשמואל בדיני ממונות ההלכה כשמואל (בכורות מ\"ט ע\"ב). כן היה מומחה גדול בענייני טריפות, וכשרבי יוחנן כתב לו לקדם \"חברנו\", שלח לו שמואל 31 גוילים (גיר\u0027 הר\"ח) בענייני טריפות, ואז כתב רבי יוחנן לקדם \"רבותינו שבבבל\". הוא ואחיו פנחס נשאו שתי אחיות (סנהדרין כ\"ח ע\"ב). בנים לא נתקיימו לו, כי רב קיללו (שבת ק\"ח ע\"א), ובגלל קללה זו כיבדו רב ולא רצה להכנס לפני שמואל (ב\"ק פ\u0027 ע\"ב). שתיים מבנותיו נשבו והובאו לארץ ישראל. נראה, שבת שלישית ושמה רחל היתה אמו של רב מרי בר איסק, כמו שפירש רש\"י (ברכות ט\"ז ע\"א ד\"ה: ברה). כשנפטר שמואל, מלך בסורא רב הונא, ורב יהודה יסד את ישיבת פומבדיתא."},{"i":3465,"n":"ר\u0027 שמואל","l":"ש","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של רבי אבהו (ירו\u0027, סנהדרין ספ\"א). כן היה תלמידו של רב זירא (ירו\u0027, כלאים פ\"ב ה\"ו)."},{"i":3466,"n":"ר\u0027 שמואל אחוה דר\u0027 פנחס בר חייא","l":"ש","b":"אמורא ארץ ישראלי בדור הרביעי. נפטר בחיי אחיו ר\u0027 פנחס שהיה רחוק ממנו בשעה שמת, ור\u0027 פנחס חש במיתת אחיו, אף שלא היה לידו (מדרש שמואל פ\"ט - ג\u0027)."},{"i":3467,"n":"ר\u0027 שמואל אחוי דרב","l":"ש","b":"מובא בירושלמי (יומא פ\"ג ה\"ח), ו\"סה\"ד\" כתב: \"ואולי ט\"ס וצ\"ל: אחוי דר\u0027 ברכיה\"."},{"i":3468,"n":"ר\u0027 שמואל אחוי דר\u0027 אושעיא","l":"ש","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בירושלמי, שאמר שר\u0027 ירמיה בעי וכו\u0027 (חגיגה פ\"ב ה\"ז)."},{"i":3469,"n":"ר\u0027 שמואל אחוי דר\u0027 ברכיה","l":"ש","b":"אמורא ארץ ישראלי בדור הרביעי. אחיו של בעל האגדה הידוע רבי ברכיה. הכיר את רבי אמי, כדמוכח בירושלמי (הוריות פ\"ג ה\"ה). רבי יוסי הקשה עליו (ירו\u0027, שבת ספט\"ו)."},{"i":3470,"n":"ר\u0027 שמואל בן אלעזר","l":"ש","b":"כך מובא בירושלמי (שבת פי\"ד ה\"ג), ונראה שהיה כתוב: ר\"ש, ועשו מזה \"ר\u0027 שמואל\" ואותו עניין בבבלי (שבת קל\"ד ע\"א), וצ\"ל: ר\u0027 שמעון בן אלעזר, וכן הוא בירושלמי (ברכות פ\"א ה\"א)."},{"i":3471,"n":"רבי שמואל בן יהוצדק","l":"ש","b":"מובא בירושלמי (ברכות ג\u0027 ע\"א), והוא ט\"ס וצ\"ל: רבי שמעון בן יהוצדק (רבו דרבי יוחנן), כמו שמובא במקום אחר (ירו\u0027, נזיר פ\"ז ה\"א). וחכם ושמו רבי שמואל בן יהוצדק נראה שלא היה קיים כלל שכן מובא רק בפעם הזאת בש\"ס, ונראה שהיה כתוב: \"ר\"ש בן יהוצדק\", והמדפיס פיענח: \"רבי שמואל\" במקום \"רבי שמעון\"."},{"i":3472,"n":"ר\u0027 שמואל בן סיסרטא","l":"ש","b":"מובא בירושלמי (כלאים רפ\"ג), והוא רב שמואל בר סוסרטאי."},{"i":3473,"n":"רבי שמואל בר אבא","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי. תלמיד מובהק של רבי יוחנן (מגילה כ\"ג ע\"א). וכן קיבל מרבי אסי (ירו\u0027, נזיר סה\"ב). רבי אלעזר ביקרו בארץ (ירו\u0027, מו\"ק פ\"ג ה\"א). נראה שביקר בבבל, ורב ששת אמר לו: \"אסברה לך\" (עירובין ז\u0027 ע\"ב)."},{"i":3474,"n":"רב שמואל בר אבא מהגרוניא","l":"ש","b":"אמורא בבלי בדור הרביעי. תלמידו של רבי אבא ושאל ממנו (ב\"ק ז\u0027 ע\"ב). אמו נישאה לרבי אבא, וכתבה נכסיה לבנה רב שמואל (שהיה בנו של ר\u0027 אבא מהגרוניא), ורבי אבא ערער על כך, ופסק רב יהודה שהנכסים שייכים לרבי אבא (ב\"ק פ\"ח ע\"א)."},{"i":3475,"n":"ר\u0027 שמואל בר אבדומי","l":"ש","b":"אמורא ארץ ישראלי בדור הששי. תלמידו של רבי מנא (ירו\u0027, הוריות פ\"ב ה\"ה). פעם היה צריך למול בשבת ושכח להביא איזמל מע\"ש ושאל את רבי מנא (ירו\u0027, שבת פי\"ט ה\"א). אמו מתה ח\u0027 ימים קודם המועד ובא לשאול את רבי מנא (ירו\u0027, מו\"ק פ\"ג). פעם אחת הובא שמו באגדה (תנחומא תצא י\u0027)."},{"i":3476,"n":"ר\u0027 שמואל בר אבין","l":"ש","b":"מובא בירושלמי (כלאים פ\"ג ה\"ב), ואביו, שגם הוא היה חכם, מתייחס אליו: \"דתני אבוה דשמואל בר אבין\" (סנהדרין נ\"א ע\"ב)."},{"i":3477,"n":"רב שמואל בר אוניא","l":"ש","b":"מובא בבבלי (מגילה ג\u0027 ע\"ב), והוא רב שמואל בר איניא."},{"i":3478,"n":"רב שמואל בר אחא","l":"ש","b":"אמורא בבלי בדור הששי. תלמידו של רב פפא: \"אמר קמיה דרב פפא\" (מנחות ל\"ד ע\"א)."},{"i":3479,"n":"רב שמואל בר אחיתאי","l":"ש","b":"אמורא בבלי בדור הרביעי. תלמידו של רב המנונא סבא (גיטין ל\"ט ע\"ב)."},{"i":3480,"n":"רב שמואל בר איביה","l":"ש","b":"מובא בויק\"ר (פ\"י - ט\u0027), ונראה שהוא רב שמואל בר איניא."},{"i":3481,"n":"רב שמואל בר אידי","l":"ש","b":"אמורא בבלי בדור החמישי. תלמידו של רבא. אחרי פטירתו של רבא היה לתלמידו של רב פפא (תענית ט\u0027 ע\"א). ע\"ע רב הונא בר מנוח."},{"i":3482,"n":"רב שמואל בר אינא","l":"ש","b":"מובא בבבלי (כתובות י\"ז ע\"א), והוא רב שמואל איניא."},{"i":3483,"n":"רב שמואל בר איניא","l":"ש","b":"אמורא ארץ ישראלי בדור הרביעי. תלמידו של רב אחא ומסר משמו (ירו\u0027, תענית פ\"ב הי\"ג) וכן מסר בשם רב (עירובין ס\"ג ע\"ב). שמו שובש בכמה פנים: רב שמואל בר אוניא (מגילה ג\u0027 ע\"ב), רב שמואל בר איני (כתובות י\"ז ע\"א), ובירושלמי שמואל בר בונא (סנהדרין פ\"י ה\"ב), ונראה אולי שהוא ר\u0027 שמואל בר יונה (ויק\"ר פ\"ל - ג\u0027), וכן ר\u0027 שמואל בר איביה (ויק\"ר פ\"י - ט\u0027), ור\u0027 שמואל בר חובה (קה\"ר פ\"א - ז\u0027 - ח\u0027), וכן ר\u0027 שמואל בר חנא (ב\"ר פ\"ה - ז\u0027)."},{"i":3484,"n":"רב שמואל בר אמי","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. אביו אימי (אמי) מתיחס לבנו, ומסר בשם רב יהודה (ירו\u0027, יבמות פ\"י ה\"ו): \"אימי אבוה דשמואל בר אימי\". רבי זירא שקיל וטרי עמו (פסחים ט\"ז ע\"ב). חותנו שמואל סבא מסר משמו (סוטה י\u0027 ע\"ב): \"אמר שמואל סבא, חמוה דרב שמואל בר אמי, משמיה דרב שמואל בר אמי\"."},{"i":3485,"n":"שמואל בר בונא","l":"ש","b":"מובא בירושלמי (סנהדרין פ\"י ה\"ב), והוא רב שמואל בר איניא."},{"i":3486,"n":"ר\u0027 שמואל בר בידרי","l":"ש","b":"אמורא בבלי בדור השני. תלמידו של רב (מנחות ל\"ה ע\"ב)."},{"i":3487,"n":"רב שמואל בר ביסנא","l":"ש","b":"אמורא בבלי בדור הרביעי. תלמידו של רב יוסף (נדה מ\"ב ע\"א), ושאל מרב יוסף, וכן תרגם קמיה דרב יוסף (קידושין כ\"ו ע\"ב). היה גם תלמידו של רב נחמן (כתובות ק\u0027 ע\"א)."},{"i":3488,"n":"רב שמואל בר בר חנה","l":"ש","b":"הוא רב שמואל בריה דרבה בר בר חנה."},{"i":3489,"n":"ר\u0027 שמואל בר ברכיה","l":"ש","b":"מובא בירושלמי (תרומות ספ\"ח)."},{"i":3490,"n":"ר\u0027 שמואל בר גדליה","l":"ש","b":"מובא בתנחומא (בהר)."},{"i":3491,"n":"ר\u0027 שמואל בר גוריא","l":"ש","b":"מובא בתנחומא (הישן בהר)."},{"i":3492,"n":"רב שמואל בר זוטרא","l":"ש","b":"אמורא בבלי בדור החמישי. אולי אפשר להסיק מלשון הגמרא, שהיה תלמידו של רבא \"אמר רבא וכו\u0027 רב שמואל בר זוטרא מתני לה לשמעתא דרבי בהאי לישנא\" (נדה מ\"ו ע\"א). מובא: \"אמר רב פפי: \u0027אמר לי רבינא לדידי אמר לי ההוא מרבנן וכו\u0027 ואמרי לה רב שמואל בר זוטרא שמיה, דאי הוו יתבי ליה כל חללא דעלמא לא הוי קא משני בדיבוריה\u0027\" (ב\"מ מ\"ט ע\"א)."},{"i":3493,"n":"ר\u0027 שמואל בר זעירא","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי. אמר בשם ר\u0027 הונא הכהן (מ\"ר פ\"ג - ח\u0027)."},{"i":3494,"n":"רב שמואל בר חובה","l":"ש","b":"מובא בקה\"ר (פ\"א - ז\u0027 - ח\u0027), ונראה שהוא רב שמואל בר איניא."},{"i":3495,"n":"רב שמואל בר חייא","l":"ש","b":"אמורא בדור השלישי. תלמידו של רבי אלעזר (ב\"מ ע\"ב ע\"ב)."},{"i":3496,"n":"רבי שמואל בר חייא בר יהודה","l":"ש","b":"אמורא ארץ ישראלי בדור השני. מסר בשם רבי חנינא (ירו\u0027, מע\"ש פ\"ג ה\"ב)."},{"i":3497,"n":"רבי שמואל בר חלף","l":"ש","b":"מובא בירושלמי (מגילה רפ\"ג), והוא רבי שמואל בר חלפתא (אמורא)."},{"i":3498,"n":"רבי שמואל בר חלפתא","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידו של רב אדא בר אהבה. רבו של רבי ירמיה (ירו\u0027, ברכות פ\"ג ה\"ה). ובמקום אחר: \"רבי שמואל בר חלף\" (ירו\u0027, מגילה רפ\"ג)."},{"i":3499,"n":"ר\u0027 שמואל בר חנא","l":"ש","b":"מובא בב\"ר (פ\"ה - ז\u0027), ונראה שהוא ר\u0027 שמואל בר איניא."},{"i":3500,"n":"ר\u0027 שמואל בר חנינא","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. תלמידו של רב אסי: \"רבי יסא (הוא רבי אסי) הורי לשמואל בר חנינא\" (ירו\u0027, מו\"ק פ\"א ה\"ח). מסר בשם רבי אלעזר (ירו\u0027, יומא פ\"ה ה\"ד)."},{"i":3501,"n":"רב שמואל בר חתאי","l":"ש","b":"מובא בבבלי (סוכה מ\"ב ע\"א), והוא רב שמואל בר אחיתאי."},{"i":3502,"n":"רב שמואל בר יהודה","l":"ש","b":"אמורא בבלי בדור השלישי, והוא ואביו התגיירו (יבמות ק\"א ע\"ב רש\"י), ואמו היתה ישראלית (כתובות מ\"ד ע\"ב תוספות ישנים). היה חברו של רב יהודה ואמר לו (כדוגמת שמואל רבו דרב יהודה) \"שיננא וכו\u0027\" (כתובות י\"ב ע\"ב). כשרב יהודה התיר בשבת למיכחל עינא, אמר רב שמואל בר יהודה: \"מאן ציית ליהודה\" (ע\"ז כ\"ח ע\"ב). רב יהודה אמר עליו שיודע בו שאינו משקר (כתובות מ\"ד ע\"ב). הלך לארץ ישראל וקיבל מרבי יוחנן (שבת ל\"ז ע\"ב). נראה, שהיה לאחד מן ה\"נחותי\", שמצינו: \"כי אתא רב שמואל בר יהודה אמר רבי יוחנן\" (גיטין כ\"ג ע\"ב), וכן אמר הוא וה\"נחותי\" ר\u0027 דימי משמיה דרבי אלעזר (שבת ל\"ח ע\"ב). אביי קיבל ממנו (מנחות מ\"ב ע\"ב)."},{"i":3503,"n":"רב שמואל בר יונה","l":"ש","b":"מובא בויק\"ר (פ\"ל - ג\u0027). נראה, שהוא רב שמואל בר איניא."},{"i":3504,"n":"רבי שמואל בר יוסי","l":"ש","b":"מובא בבבלי (קידושין ל\"ג ע\"א), ונראה שהוא ט\"ס וצ\"ל: רבי ישמעאל בר יוסי. הקפיד על רבי שמעון בר רבי, וכן נראה שצ\"ל במד\u0027 תהלים (הישן פ\"ג). ונראה אולי שלא היה קיים כלל חכם ושמו רבי שמואל בר יוסי."},{"i":3505,"n":"רב שמואל בר ייבא","l":"ש","b":"אמורא בדור הרביעי. הקשה לרב אבא (נדה ט\"ו ע\"ב)."},{"i":3506,"n":"ר\u0027 שמואל בר ינא","l":"ש","b":"מובא (ירו\u0027, תענית פ\"ב ה\"א) והוא ר\u0027 שמואל בר איניא."},{"i":3507,"n":"ר\u0027 שמואל בר ינאי","l":"ש","b":"מובא במדרש שמואל (פכ\"א - ג\u0027)."},{"i":3508,"n":"רב שמואל בר יעקב","l":"ש","b":"אמורא בבלי מובא בירושלמי (נדרים פ\"ג ה\"ב) ובבבלי (מנחות ל\"ב ע\"א)."},{"i":3509,"n":"רב שמואל בר יצחק","l":"ש","b":"אמורא בבלי בדור השלישי. תלמידו של רב (נדה ס\"ב ע\"ב) ושל רב הונא (עירובין ל\"ו ע\"ב). עלה לארץ ישראל ולקח תורה מרבי חייא בר אבא (חולין צ\"ח ע\"א). מסר בשם רבי יוחנן (חולין קט\"ז ע\"ב). הוא ורבי זירא מכונים \"שני גדולי הדור\" (גיטין נ\"ג ע\"ב). המוסרים בשמו: רבי ירמיה (ירו\u0027, עירובין פ\"א ה\"א), רבי יונה ורבי יוסי (ירו\u0027, ר\"ה פ\"א ה\"ב). אביו היה חסיד גדול ונהג לצום שני ימים ביום כיפור ומת בגלל זה (שם ה\"ד). רב שמואל בר יצחק נהג לרקוד לפני חתן וכלה ובידו בדי הדס. רבי זירא נהג לומר, שמבייש אותם בזה. בשעת מותו היו שלש שעות קולות וברקים, ויצאה בת קול ואמרה: נפטר רב שמואל בר יצחק וירדה אש מן השמים בצורת בדי הדס והפרידה בין מטתו לבין מלוויו (ירו\u0027, ע\"ז פ\"ג ה\"א). בתו התחתנה עם רב אושעיא, אחיו של רבה (ירו\u0027, סנהדרין פ\"א ה\"א)."},{"i":3510,"n":"רבי שמואל בר כהנא","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. ורבי ירמיה מסר בשמו (שהש\"ר פ\"ז - ח\u0027)."},{"i":3511,"n":"רב שמואל בר מינא","l":"ש","b":"מובא (ירו\u0027, ברכות פ\"א ה\"א), והוא ר\u0027 שמואל בר איניא."},{"i":3512,"n":"רב שמואל בר מרתא","l":"ש","b":"אמורא בבלי. תלמידו של רב (פסחים קי\"ג ע\"ב). הרשב\"ם סובר שהיה אחי רבי חייא (ב\"ב נ\"ב ע\"א) ואם כן היה בדור הראשון והיה בן דורו של רב. ורבנו גרשום פירש ש\"מרתא\" \"זו שם של אשה\". רבה בר בר חנא היה תלמידו של רב שמואל בר מרתא (פסחים קי\"ג ע\"ב)."},{"i":3513,"n":"רבי שמואל בר נדב","l":"ש","b":"אמורא ארץ ישראלי בדור השני. מובא בבבלי: \"בעא מיניה רבי שמואל בר נדב מרבי חנינא, ואמר לה רבי שמואל בר נדב חתניה דרבי חנינא מרבי חנינא, ואמרי לה מרבי יהושע בן לוי\" (ערכין ט\"ז ע\"ב)."},{"i":3514,"n":"רבי שמואל בר נחום","l":"ש","b":"אמורא ארץ ישראלי בדור הראשון - השני. מובא בבבלי: \"שאל רבי חנינא בן עגיל את רבי חייא בר אבא: \u0027מפני מה בדברות הראשונות לא נאמר בהם טוב, ובדברות האחרונות נאמר בהם טוב? \u0027 אמר לו: וכו\u0027 \u0027כלך אצל ר\u0027 תנחום בר חנילאי שהיה רגיל אצל ריב\"ל\u0027 וכו\u0027 אזל לגביה א\"ל: \u0027ממנו לא שמעתי אלא כך אמר לי שמואל בר נחום וכו\u0027\" (ב\"ק נ\"ה ע\"ב)."},{"i":3515,"n":"רבי שמואל בר נחמני","l":"ש","b":"אמורא ארץ ישראלי בדור השני - השלישי. מבעלי האגדה החשובים. מושבו היה בלוד (ויק\"ר פל\"ה - ב\u0027). בבבלי מכונה בדרך כלל: \"רבי שמואל בר נחמני\" ובירושלמי מכונה בד\"כ: \"רבי שמואל בר נחמן\". היה יליד ארץ ישראל. נראה, שהגיע לזקנה מופלגת שכן בהיותו ילד זכה לראות, ואף לשמוע את דרשותיו של התנא רבי שמעון בן אלעזר (ב\"ר פ\"ט - ה\u0027). קרא לרב יהודה: \"חברנו\" (מו\"ק י\"ז ע\"א) ונפטר אחרי רב יהודה, כדמוכח (שם). רבו המובהק היה רבי יונתן (פסחים כ\"ד ע\"א). גם רבי יהושע בן לוי היה רבו המובהק (ירו\u0027, ר\"ה פ\"ד ה\"ד). קיבל גם מרבי יוחנן (ירו\u0027, תרומות רפ\"ה), ונראה שגם מרבי אלעזר (ירו\u0027, חגיגה פ\"ה ה\"א). היה מקורב לרבי יהודה נשיאה, ונהגו ללכת יחד להתרחץ במרחצאות של טבריה, ופעם בא לשם שליחו של הקיסר דיוקליטינוס להזמינם לבוא לחצר הקיסר (ירו\u0027, תרומות ספ\"ח), ומסופר על הנסים שנעשו להם (שם). הוא ורבי יעקב בר אידי מכונים: \"גדולי הדור\" (חולין צ\"ח ע\"א). היתה לו ישיבה (ברכות י\"ז סע\"א). והאומרים בשמו רבים, ומהם מתלמידי רבי יוחנן, כגון ר\u0027 אבהו (ירו\u0027, תענית ספ\"ג) ורבי אלעאי (ירו\u0027, שקלים פ\"ג ה\"ב). עיקר דבריו היו באגדה, וכך פנו אליו ר\u0027 חלבו ואחרים, כדמצינו: \"מפני ששמעתי עליך שאתה בעל אגדה\" (איכ\"ר פ\"ג - ס\u0027, ועוד). רבות מדרשותיו נשארו בידינו. כשהתאכסן אצל ר\u0027 יעקב גרוסה, התחבא רבי זירא כדי לשמוע האיך קורא קריאת שמע (ירו\u0027, ברכות פ\"א ה\"א). היו לו שני בנים חכמים, רבי נחמן (ירו\u0027, מגילה פ\"א ה\"א) ור\u0027 הלל (שבת פ\u0027 ע\"א)."},{"i":3516,"n":"ר\u0027 שמואל בר נפחא","l":"ש","b":"מובא בפדר\"כ (נ\"ד), ואולי צ\"ל: ר\u0027 שמואל בר נחמני."},{"i":3517,"n":"ר\u0027 שמואל בר נתן","l":"ש","b":"אמורא ארץ ישראלי בדור השני. תלמידו של רבי חנינא (ע\"ז ע\"ד ע\"א). חברו של רבי אלעזר ובר פלוגתיה (סוכה מ\"ג ע\"ב)."},{"i":3518,"n":"רב שמואל בר סוטר","l":"ש","b":"מובא בירושלמי (ברכות פ\"א ה\"א), והוא כנראה רב שמואל בר סוסרטאי."},{"i":3519,"n":"רב שמואל בר סוסרטאי","l":"ש","b":"אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי אבהו (ירו\u0027, סנהדרין פ\"ז ה\"א). שמו נשתבש בכמה אופנים: רבי שמואל בר סוסרטיי (ירו\u0027, ב\"מ פ\"ב ה\"ה), ושם מסופר שהלך לרומא ומצא מציאה של המלכות וקידש שם שמים בהחזרתה; רב שמואל בר ססרטי (ב\"ק ק\"ב ע\"ב), ושם מובא שרבי אבהו השיב על דבריו; רב שמואל בר ססרטאי (תענית י\"ד ע\"א): שמואל בן סיסרטא (ירו\u0027, כלאים רפ\"ג): ר\u0027 שמואל בר סיסרטיי (ירו\u0027, ביצה פ\"ד ה\"א). ונראה אולי שלגבי המובא בירושלמי: \"ר\u0027 חנינא בר אנדריי בשם ר\u0027 שמואל בר סוטר\" (ברכות פ\"א ה\"א), כי (לפי השינויים שיש בירושלמי בד\"כ) ר\u0027 שמואל בר סוטר הוא ר\u0027 שמואל בר סוסרטאי, ופלא ש\"סה\"ד\" קבע שהם שני חכמים ללא הטלת כל ספק בדבר. היו לו שני אחים, אחד ר\u0027 הוריינא נראה חכם והאחר, ושמו אלכסנדריי, ספק אם היה חכם (ירו\u0027, ב\"ב פ\"ט ה\"ג)."},{"i":3520,"n":"רבי שמואל בר סוסרטיי","l":"ש","b":"מובא בירושלמי (ב\"מ פ\"ב ה\"ה), והוא רב שמואל בר סוסרטאי."},{"i":3521,"n":"ר\u0027 שמואל בר סימון","l":"ש","b":"מובא ברו\"ר (פ\"ג - ו\u0027), והגיר\u0027 ב\"ילקוט\" (רות רמז תרא) ר\u0027 שמואל בר נחמני."},{"i":3522,"n":"רב שמואל בר סיסרטיי","l":"ש","b":"מובא בירושלמי (ביצה פ\"ד ה\"א), והוא רב שמואל בר סוסרטאי."},{"i":3523,"n":"רב שמואל בר ססרטאי","l":"ש","b":"מובא בבבלי (תענית י\"ד ע\"א), והוא רב שמואל בר סוסרטאי."},{"i":3524,"n":"רב שמואל בר ססרטי","l":"ש","b":"מובא בבבלי (ב\"ק ק\"ב ע\"ב), והוא רב שמואל בר סוסרטאי."},{"i":3525,"n":"ר\u0027 שמואל בר פוניא","l":"ש","b":"מובא: \"א\"ר יודן בשם ר\u0027 שמואל בר פוניא בשם בר קפרא\" (פדר\"כ ט\u0027)."},{"i":3526,"n":"רב שמואל בר פפא","l":"ש","b":"אמורא בבלי בדור השלישי. תירגם קמיה דרב אדא (יומא ל\"ז ע\"א)."},{"i":3527,"n":"רב שמואל בר רב קטינא","l":"ש","b":"אמורא בבלי בדור השלישי - הרביעי. מצינו: \"רבה בר בר חנא הוה עסיק ליה לבריה בי רב שמואל בר קטינא וכו\u0027\" (ברכות מ\"ז ע\"א)."},{"i":3528,"n":"רב שמואל בר שבא","l":"ש","b":"אמורא בבלי בדור השלישי. תלמידו של רב הונא ורבו של רבא (שבועות י\"ז ע\"ב)."},{"i":3529,"n":"רב שמואל בר שילת","l":"ש","b":"אמורא בבלי בדור הראשון - השני. תלמידו של רב ושאל ממנו (ירו\u0027, פ\"ז ה\"ב). היה מלמד תינוקות במסירות רבה, ושלוש עשרה שנה ברציפות לא הפסיק ולא נח ממלאכתו, ורב היללו מאד (ב\"ב ח\u0027 ע\"ב) והדריכו כיצד להתנהג עם הילדים (שם כ\"א ע\"א). ורב ביקשו שיספידו לאחר פטירתו בחמימות, כדי שהמלווים יבכו (שבת קנ\"ג ע\"א). היה לו בן ושמו רב יהודה וגם הוא היה תלמידו של רב (ברכות מ\"ז ע\"א)."},{"i":3530,"n":"רב שמואל בר שימי","l":"ש","b":"אמורא בבלי בדור הששי. תלמידו של רב פפא ותירגם קמיה (כריתות כ\"ז ע\"ב)."},{"i":3531,"n":"ר\u0027 שמואל בר תנחום","l":"ש","b":"מובא שהש\"ר (רפ\"ז), ואולי יש ט\"ס והוא ר\u0027 ישמעאל בר תנחום."},{"i":3532,"n":"ר\u0027 שמואל בריבי","l":"ש","b":"מובא בקה\"ר (פ\"ו - ו\u0027)."},{"i":3533,"n":"רב שמואל בריה דרב אבהו","l":"ש","b":"מאמוראי בבל האחרונים בדור השמיני, ונחשב לבן דור הראשון לרבנן סבוראי. אביו, רב אבהו, היה מראשי הכלה בישיבתו של רפרם בפומבדיתא (חולין מ\"ט ע\"א). ועוד מובאת מחלוקת שלו עם רב אחאי, שגם כן היה מרבנן סבוראי (שם נ\"ט ע\"ב). ומובא (\"אגרת רב שרירא גאון\" דפוס ב\"ג) שנפטר בכסלו בשנת ד\u0027 רס\"ו (605)."},{"i":3534,"n":"רב שמואל בריה דרב איקא","l":"ש","b":"מובא בבבלי (ע\"ז ס\"ט ע\"א). גירסת \"דק\"ס\": \"בריה דר\u0027 אבהו\" (מראשי רבנן סבוראי), א\"כ, לדעתו לא היה קיים כלל חכם ושמו \"רב שמואל בריה דרב איקא\", שכן אינו מובא במקום אחר."},{"i":3535,"n":"רב שמואל בריה דרבה בר בר חנא","l":"ש","b":"אמורא בבלי בדור הרביעי. חברם של רב אחא בר הונא ורב יצחק בריה דרב יהודה, ושלושתם למדו מסכת שבועות בבית מדרשו של רבה, ורב כהנא שאלם (שבועות ל\"ו ע\"ב). מצינו אותו עם רב יוסף אפיתחא דבי רבה (קידושין נ\"ח ע\"א) ואמר לרב יוסף: \"בפירוש אמרת לן\" (שבת נ\"ט ע\"ב)."},{"i":3536,"n":"רבי שמואל בר\u0027 יוסי בר בון","l":"ש","b":"מאחרוני אמוראי ארץ ישראל בדור הששי. בנו ותלמידו של אביו האמורא הידוע רבי יוסי בר אבין (ירו\u0027, גיטין פ\"ה ה\"ג). חברו של רב מתנייה (שם)."},{"i":3537,"n":"ר\u0027 שמואל דסופפתא","l":"ש","b":"בירושלמי (סנהדרין פ\"ב ה\"ב) הגירסא \"ר\u0027 שמעון דתוספתא\" ויש גירסא (ירו\u0027, ברכות פ\"ג ה\"ב) ר\u0027 שמעון דתוספתא, ואין לדעת הנכון, ונראה שהיה כתוב \"ר\"ש\" ופיענחוהו פעם \"ר\u0027 שמואל\" ופעם \"ר\u0027 שמעון\"."},{"i":3538,"n":"שמואל הזקן","l":"ש","b":"אמורא ארץ ישראלי בדור החמישי. תלמידו של רבי אחא (ירו\u0027, סנהדרין פ\"ב ה\"ג)."},{"i":3539,"n":"שמואל הקטן","l":"ש","b":"תנא בדור השני, שחי מדורו של הלל עד לר\u0027 אליעזר בן הורקנוס: \"מעשה שנכנסו זקנים לעלית בית גדיא, ויצאה בת קול ואמרה להן: \u0027יש ביניכם שנים ראויין לרוח הקודש והלל הזקן אחד מהן\u0027, ונתנו עיניהן בשמואל הקטן, [שהוא השני]. ושוב נכנסו זקנים לעליה ביבנה, ויצאה בת קול ואמרה להן: \u0027יש ביניכן שנים ראויין לרוח הקודש ושמואל הקטן אחד מהן\u0027, ונתנו עיניהן ברבי אליעזר בן הורקנוס\" (ירו\u0027, סוף סוטה). רבן גמליאל הזקן (בן בנו של הלל) קרא לו: \"בני\" (סנהדרין י\"א ע\"א). ומה שמצינו: \"ואף הוא [שמואל הקטן] אמר בשעת מיתתו: \u0027שמעון וישמעאל לחרבא\u0027\" (סוטה מ\"ח ע\"ב), פרש\"י: \"רבן שמעון בן גמליאל שהיה נשיא ור\u0027 ישמעאל בן אלישע שהיה כהן גדול שהרגתם מלכות יון\", מוכיח ששמואל הקטן היה צעיר בזמן פטירת הלל הזקן ורבי אליעזר היה צעיר בזמן פטירת שמואל הקטן, וכשמת שמואל הקטן הספידוהו: \"הי עניו, הי חסיד, תלמידו של הלל\". הוא שחיבר את ברכת \"המינים\" (ברכות כ\"ח ע\"ב). ולמה נקרא שמו \"קטן\"? לפי שהיה מקטין עצמו, ויש אומרים: לפי שמעט היה קטן משמואל הרמתי (ירו\u0027, סוטה פ\"ט הי\"ג)."},{"i":3540,"n":"ר\u0027 שמואל חתניה דר\u0027 חנינא חברון דרבנן","l":"ש","b":"מובא בב\"ר (ספי\"ד)."},{"i":3541,"n":"שמואל ירחינאה","l":"ש","b":"כינוי לשמואל (ב\"מ פ\"ה ע\"ב), ופרש\"י: \"הוא שמואל בר אבא חבירו של רב, ועל שהיה בקי בסוד העיבור, כדאמרינן במס\u0027 ראש השנה (דף כ\u0027 ע\"ב) אמר שמואל: \"יכילנא לתקוני כולה גלותא, קרי ליה ירחינאה\"."},{"i":3542,"n":"ר\u0027 שמואל כוזית","l":"ש","b":"אמורא ארץ ישראלי בדור החמישי. רבי תנחומא מסר בשמו. כך הגיר\u0027 ב\"ערוך\" ערך כזית (מב\"ר פכ\"ד), ולפנינו הגיר\u0027 שונה."},{"i":3543,"n":"רב שמואל מדיפתא","l":"ש","b":"אמורא בבלי בדור הששי. חלק עם רב אחא בריה דרבא היכן צריך להניח נר חנוכה (שבת כ\"ב ע\"א). ו\"השאלתות\" פ\u0027 וישלח סי\u0027 כ\"ו גורס: רב ירמיה וכן גרס \"דק\"ס\": רב ירמיה מדיפתא. א\"כ, לא היה חכם ושמו רב שמואל מדיפתא, שכן הוא מובא בש\"ס רק במקום זה."},{"i":3544,"n":"רב שמואל מזרוקיניא","l":"ש","b":"מובא בבבלי: \"מתקיף לה רב אשי ואיתימא רב שמואל מזרוקיניא\" (חולין קי\"א ע\"א), ומלשון הש\"ס אין ראיה שהיה בזמנו של רב אשי."},{"i":3545,"n":"רב שמואל מתואך","l":"ש","b":"אמורא בבלי בדור החמישי. מובא שרב פפא ביקר בביתו, רב שמואל מתואך שחט לכבודו שור, ושאל מרב פפא ולא ידע להשיב כראוי, והלך רב פפא וסיפר לרב שימי בר אשי ואמר לו רב שימי בר אשי מדוע לא השבת לו וכו\u0027 (נדה ל\"ג ע\"ב)."},{"i":3546,"n":"שמואל סבא חתניה דרבי חנינא","l":"ש","b":"אמורא ארץ ישראלי בדור השני. חתנו ותלמידו של רבי חנינא (ברכות ס\"ב ע\"ב). אמר משמו של רבי חנינא ור\u0027 יוחנן חלק עמו (שם)."},{"i":3547,"n":"ר\u0027 שמואל פרגריטא","l":"ש","b":"מובא דב\"ר (פ\"ב - כ\"ד)."},{"i":3548,"n":"רב שמואל קפודקיא","l":"ש","b":"אמורא ארץ ישראלי בדור הרביעי. ר\u0027 יונה מסר משמו (ירו\u0027, חלה פ\"ג ה\"א)."},{"i":3549,"n":"ר\u0027 שמי","l":"ש","b":"הוא ר\u0027 שמאי."},{"i":3550,"n":"רבי שמלאי","l":"ש","b":"אמורא בדור השני. נולד בבבל בנהרדעא ועלה לארץ ישראל וחי בלוד (פסחים ס\"ב ע\"ב). שמו של אביו היה אבא, ושאל אבא פעם את שמואל (חברו של רב) שאלה בסוד העיבור ולא ידע להשיב (ר\"ה כ\u0027 ע\"ב). תלמידו של רבי ינאי (ב\"ב קי\"א ע\"ב) ותלמידו המובהק של רבי יהודה נשיאה א\u0027 (ע\"ז ל\"ז ע\"א). כשרבי יהודה נשיאה א\u0027 התיר את השמן הלך ר\u0027 שמלאי לנציבין בבבל ודרש על היתר השמן (שם ל\"ו ע\"א). בין תלמידיו היה רבי אלעזר (סנהדרין פ\"ח ה\"א). הרבה להתווכח עם המינים (ב\"ר פ\"ח - ט\u0027). הרבה לדרוש: \"דרש רבי שמלאי, שש מאות ושלש עשרה מצות נאמרו לו למשה, שס\"ה לאוין כמנין ימות החמה, ורמ\"ח עשה כנגד איבריו של אדם\" (מכות כ\"ג ע\"ב)."},{"i":3551,"n":"ר\u0027 שמלאי","l":"ש","b":"מובא ב\"זוהר\" (אחרי עה)."},{"i":3552,"n":"ר\u0027 שמלאי דבירא","l":"ש","b":"מובא בירושלמי: \"א\"ר שמלאי דבירא א\"ל ובדברך עשיתי ובדיבורך עשיתי (מגילה פ\"א הי\"א), ופירש \"קרבן העדה\": \"כך שמו\". \"פני משה\" פירש שר\u0027 שמלאי אמר: דבירא אמר ליה, מפי הדובר נאמר לו לעשות כדכתיב ובדברך וכו\u0027 (א\"כ אינו שם חכם)."},{"i":3553,"n":"רב שמן","l":"ש","b":"אמורא בבלי בדור הששי. אמר לרב אשי, והתני רמי בר יחזקל (קידושין כ\"ד ע\"ב)."},{"i":3554,"n":"רב שמן בר אבא","l":"ש","b":"אמורא בבלי בדור השני. ר\u0027 שמעון בר אבא הוא רב שמן בר אבא כמובא בבבלי (כתובות כ\"ג ע\"א), שמכונה שמן בר אבא, ואותו ענין מובא בירושלמי (כתובות פ\"ב ה\"ו) ושם מכונה ר\u0027 שמעון בר אבא. עלה לארץ ישראל ולמד לפני רבי יוחנן והיה תלמידו המובהק (שבת ס\"א ע\"א). רבי יוחנן קרא לו בבלייא (ירו\u0027, שבת פ\"ו ה\"ב). היה בדעתו לחזור לבבל ואולי בגלל זה קראו לו רב ולא רבי. ורש\"י פירש (חולין צ\"ג ע\"ב ד\"ה: אל): \"שאתה מבבל ושם נוהגין בו איסורא\". לקח תורה מרבי חנינא (כתובות כ\"ג ע\"א) ומרבי יהושע בן לוי (גיטין ה\u0027 ע\"א). כשהובאו בנות שמואל כשבויות מבבל לארץ ישראל א\"ל רבי חנינא שישא אחת מהן לאשה (ירו\u0027, כתובות פ\"ב ה\"ו). ומיד לאחר נשואיה מתה והוא התחתן עם אחותה ומתה אף היא (ירו\u0027, כתובות פ\"ה ה\"ו). היה עני מרוד ולא היה לו לחם לאכול ור\u0027 יוחנן פיזר סלעים כדי שיזכה בהן רב שמן בר אבא (רו\"ר פ\"ה - ז\u0027). לפני שנפטר ציווה לפנות הכלים מפני הטומאה (ירו\u0027, נזיר פ\"ג ה\"ה). הניח אחריו בן חכם ושמו רב עמרם (שבת קי\"ט ע\"ב)."},{"i":3555,"n":"ר\u0027 שמן בר רב יצחק","l":"ש","b":"מובא ב\"ילקוט\" (ישעיה סוף רמז רנז), ואולי יש ט\"ס בשם."},{"i":3556,"n":"רבי שמעון","l":"ש","b":"סתם רבי שמעון הוא רבי שמעון בן יוחאי. נראה (פסחים קי\"ב ע\"א), שאמר רבי שמעון לר\"ע וכו\u0027 \"ואם אין אתה מלמדני אני אומר ליוחי אבא\"."},{"i":3557,"n":"שמעון אחי עזריה","l":"ש","b":"תנא בדור השני. דודו של רבי אלעזר בן עזריה ואחיו של עזריה. עזריה עסק במסחר לספק לשמעון אחיו את צרכיו, והיות ושמעון למד תורה ע\"י אחיו נקרא על שמו (סוטה כ\"א ע\"א רש\"י ד\"ה: ר\u0027 שמעון). מובא במשנה, שחלק על רבי אליעזר ויוסי בן חונא (זבחים ב\u0027 ע\"א), וכן מובא שחלק על רבי אליעזר ורבי יהושע (טהרות פ\"ח מ\"ז)."},{"i":3558,"n":"ר\u0027 שמעון אחיה דר\u0027 ברכיה","l":"ש","b":"מובא בירושלמי (ברכות פ\"ז ה\"א), ואולי יש ט\"ס בשם."},{"i":3559,"n":"שמעון איש המצפה","l":"ש","b":"תנא בדור הראשון. חי בזמן הבית. מובא (פאה פ\"ב מ\"ו) שזרע שני מיני חיטים ובא לפני רבן גמליאל ועלו ללשכת הגזית ושאלו אמר נחום הלבלר וכו\u0027 (פאה פ\"ב מ\"ו), ומובא: \"מאן תנא סדר יומא רבי שמעון איש המצפה\" (יומא י\"ד ע\"ב)."},{"i":3560,"n":"שמעון איש קטרון","l":"ש","b":"תנא. מובא במכלתא (פ\u0027 בשלח פ\"ג)."},{"i":3561,"n":"שמעון אפרתי","l":"ש","b":"תנא בדור החמישי. משרתו של רבי. קודם פטירתו אמר רבי: \"יוסף חפני ושמעון אפרתי הם שמשוני בחיי והם ישמשוני במותי\" (כתובות ק\"ג ע\"א). הם נפטרו מיד לפני שרבי נפטר, והובן שכוונת רבי היתה שישמשוהו בעולם הבא."},{"i":3562,"n":"רבי שמעון בולוטה","l":"ש","b":"אמורא ארצישראלי בדור השני. מסר בשם רבי חנינא (ירו\u0027, פסחים רפ\"ד). ר\u0027 יעקב בר אחא היה תלמידו (שם)."},{"i":3563,"n":"שמעון בן אבטולמוס","l":"ש","b":"מובא בבבלי (ב\"ב ס\"ח ע\"א)."},{"i":3564,"n":"רבי שמעון בן אבישלום","l":"ש","b":"מובא בבבלי (ברכות ז\u0027 ע\"ב, מגילה י\"ד ע\"א), וצריך לגרוס אבישלום ולא אבשלום. כן פירשו תוספות, כי אבשלום אין לו חלק לעולם הבא (יומא ל\"ח ע\"ב)."},{"i":3565,"n":"רבי שמעון בן איסי בן לקוניא","l":"ש","b":"מובא בבבלי (ב\"מ פ\"ה ע\"א), והוא ר\u0027 שמעון בן יוסי בן לקוניא."},{"i":3566,"n":"רבי שמעון בן אליקים","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו המובהק של רבי יוחנן (סנהדרין ל\u0027 ע\"ב). הקשה לרבי שמעון בן לקיש (ע\"ז ל\"ד ע\"ב), אך אין להכריע אם היה תלמידו. אף שקרא לרבי אלעזר רבי (כתובות נ\u0027 ע\"ב), נראה יותר שהיו חברים. שאל את רבי אלעזר, ואמר לו: \"דבר שהראשונים לא אמרו בו טעם תשאלני בבית המדרש כדי לביישני\" (ב\"ב פ\"א ע\"ב)."},{"i":3567,"n":"רבי שמעון בן אלעזר","l":"ש","b":"תנא בדור החמישי. תלמידו המובהק של רבי מאיר (חולין ו\u0027 ע\"א). אמר: \"משרת רבי מאיר הייתי וכו\u0027\" (ירו\u0027, מו\"ק פ\"ג ה\"א). יש אומרים מקלו של רבי מאיר היה בידו. וכן מצינו: \u0027אמר רבי שמעון בן אלעזר: \u0027פעם אחד חש רבי מאיר בעיניו וביקשני לטרוף לו יין ושמן\u0027 וכו\u0027\" (שבת קל\"ד ע\"א). מובא מעט במשנה ופעמים רבות בתוספתא ובברייתא. ומסופר מעשה שבא מבית רבו ושמח שמחה רבה והיתה דעתו גסה עליו מפני שלמד תורה הרבה; נזדמן לו אדם אחד מכוער ביותר, א\"ל: \u0027ריקא כמה מכוער אותו איש\u0027 ענה לו האיש: \u0027לך לאומן שעשני ואמור לו\u0027, כיון שידע בעצמו שחטא ירד מן החמור וביקש ממנו מחילה (אדר\"ב פמ\"א). וממנו המאמר במשנה: \"ראית מימיך חיה ועוף שיש להם אומנות והם מתפרנסין שלא בצער\" (קידושין פ\"א ע\"א). האריך ימים עד שרבי יוחנן בהיותו תינוק ראהו (ירו\u0027, מעשרות פ\"א ה\"ב), וכן ראהו רבי שמואל בר נחמני (ב\"ר פ\"ט - ה\u0027)."},{"i":3568,"n":"שמעון בן אנטיפרס","l":"ש","b":"חי בדור השני לתנאים. מובא (ד\"א רבה פ\"ו), שהיה מלקה את אורחיו ורבי יהושע הלך אליו לברר הסיבה. ואין להוכיח שהיה מן החכמים."},{"i":3569,"n":"רבי שמעון בן בתירא","l":"ש","b":"תנא בדור השני - השלישי. מובא במשנה: \"העיד ר\"ש בן בתירא וכו\u0027 הוסיף רבי עקיבא\" (עדיות פ\"ח מ\"א)."},{"i":3570,"n":"שמעון בן גודא","l":"ש","b":"תנא. העיד לפני בנו של ר\"ג (ע\"ז ל\"ב ע\"א). אם נניח שהעיד לפני בנו של רבן גמליאל הזקן, הרי שהיה בדור השני - השלישי לתנאים, ואם נניח שהעיד לפני בנו של ר\"ג דיבנה, הרי שהיה בדור הרביעי - החמישי. ועיין שם בתוספות (ד\"ה: אבל) והגמרא מפקפקת אם היה תנא אחד או שנים - אחד גודא ואחד גודע."},{"i":3571,"n":"שמעון בן גודע","l":"ש","b":"מובא בבבלי (ע\"ז ל\"ב ע\"א). ע\"ע שמעון בן גודא."},{"i":3572,"n":"רבן שמעון בן גמליאל (2)","l":"ש","b":"תנא בדור הראשון - השני. היה הנשיא הרביעי מבית הלל ושימש בנשיאות קודם החורבן, שאמרו: הלל שמעון גמליאל (הוא רבן גמליאל הזקן) ושמעון (הוא רבן שמעון בן גמליאל שלנו) נהגו נשיאותן בפני הבית מאה שנה (שבת ט\"ז ע\"א). היה מעשרת הרוגי מלכות, ושמואל הקטן ניבא קודם פטירתו ואמר: \"שמעון וישמעאל לחרבא\", ופרש\"י: \"רבן שמעון שהוא נשיא ור\u0027 ישמעאל בן אלישע כהן גדול שהרגתם מלכות יון\" (סוטה מ\"ח ע\"ב). וכן מצינו: \"כשנהרגו רשב\"ג הזקן ור\u0027 ישמעאל בן אלישע כהן גדול באה השמועה אצל רבי עקיבא ור\u0027 יהודה בן בתירא עמדו וחגרו שקים וקרעו בגדיהם (שמחות פ\"ח). \"אמרו עליו על רשב\"ג כשהיה שמח שמחת בית השואבה היה נוטל שמונה אבוקות של אור וזורק אחת ונוטל אחת ואין נוגעות זו בזו וכשהוא משתחוה נועץ שני גודליו בארץ ושוחה ונושק את הריצפה וזוקף ואין כל בריה [בדורו] יכולה לעשות כן\" (סוכה נ\"ג ע\"א). בנו הוא רבן גמליאל דיבנה ובתו היא אימא שהתחתנה עם רבי אליעזר בן הורקנוס (ב\"מ נ\"ט ע\"ב)."},{"i":3573,"n":"רבן שמעון בן הלל הזקן","l":"ש","b":"נשיא ישראל. בנו של הלל. מובא רק פעם אחת בש\"ס: \"הלל ושמעון גמליאל [רבן גמליאל הזקן] ושמעון [רבן שמעון הנהרג] נהגו נשיאותן בפני הבית מאה שנה\" (שבת ט\"ו ע\"א), והיות שידוע לנו שהלל החל בנשיאותו 001 שנה לפני החורבן, ושימש כנשיא 04 שנה (ספרי ברכות סל\"ו), א\"כ החל שמעון נשיאותו 06 שנה לפני החורבן. הנשיא אחריו היה רבן גמליאל הזקן בנו. לא מובאת ממנו שום הלכה, תקנה, מימרה או אגדה."},{"i":3574,"n":"רבי שמעון בן הסגן","l":"ש","b":"לדעתו של הרמב\"ם (בהקדמתו לזרעים) היה בנו של רבי חנינא סגן הכהנים, ואם כן היה תנא בדור השני - השלישי. רשב\"ג אמר משמו כמה פעמים (מנחות ק\u0027 ע\"ב)."},{"i":3575,"n":"שמעון בן זומא","l":"ש","b":"תנא בדור השלישי. אמרו: \"ראוי להוראה כגון מאן אמר רבא כגון שמעון בן עזאי ושמעון בן זומא\" (הוריות ב\u0027 ע\"ב), ופרש\"י: \"שהיו יושבין לפני חכמים והיו ראויין להוראה\". ועל אף שלא הגיע לסמיכה כמו חברו בן עזאי לא היו בימיהם כמותם בתורה (קידושין מ\"ט ע\"ב רשי ד\"ה: בן), ועל שניהם אמרו: \"דנין לפני חכמים\" (סנהדרין י\"ז ע\"ב). היה תלמידו של רבי יהושע (ירו\u0027, נזיר פ\"ח ה\"א) וחברו של רבי עקיבא (חגיגה י\"ד ע\"ב). נמנה עם ארבעת החכמים שנכנסו ל\"פרדס\" (פרש\"י: \"עלו לרקיע על ידי שם\") ואלו הן: בן עזאי ובן זומא אחר ורבי עקיבא וכו\u0027, והוא הציץ ונפגע (שם), ופירש\"י: \"נטרפה דעתו\". היה עשיר גדול (ברכות כ\"ה ע\"א רש\"י). היה דרשן גדול ואמרו: \"משמת בן זומא בטלו הדרשנים\" (סוטה מ\"ט ע\"א). ואמרו: \"הרואה בן זומא בחלום יצפה לחכמה\" (ברכות נ\"ז ע\"ב). נראה, שנפטר בחיי רבי יהושע (תוספתא חגיגה פ\"ב)."},{"i":3576,"n":"ר\u0027 שמעון בן זירא","l":"ש","b":"אמורא בבלי. מובא בבבלי: \"אמר אביי בירושלים וכן תני רב שמעון בר זירא בקידושי דבי לוי\" (קידושין ע\"ו ע\"ב)."},{"i":3577,"n":"רבי שמעון בן זירוז","l":"ש","b":"הוא רבי שמעון בר זירוד."},{"i":3578,"n":"ר\u0027 שמעון בן זכריה","l":"ש","b":"אמורא ארץ ישראלי בדור הרביעי. רבי יונה מסר משמו (ירו\u0027, דמאי פ\"ב ה\"א)."},{"i":3579,"n":"רבי שמעון בן חלפתא","l":"ש","b":"תנא בדור החמישי. בן בנו של רבי יוסי בן חלפתא, כמובא שרבי יוסי יבם את אשת אחיו ונטע חמשה ארזים בישראל: רבי ישמעאל ורבי אלעזר ורבי חלפתא וכו\u0027 (שבת קי\"ח ע\"ב). מסר בשם רבי מאיר (ירו\u0027, תענית פ\"ד ה\"א) והיה חביב על רבי, שא\"ל רבי לרבי שמעון בן חלפתא: \"מפני מה לא הקבלנו פניך ברגל וכו\u0027\" (שבת קנ\"ב ע\"א). הלך יחד עם רבי חייא בבקעת ארבל וראו איילת השחר שבקע אורה (ירו\u0027, ברכות פ\"א ה\"א), וכן מצינו אותו יחד עם רבי חייא ורבי שמעון בר רבי (ב\"ר פע\"ט - ז\u0027). היה עני מרוד (רו\"ר פ\"ה - ז\u0027). נתנו לו מרגלית מן השמים והחזירה (רו\"ר פ\"ג - ז\u0027). פעם אחת פגעו בו שני אריות ואירע לו נס וירדו מן השמים שתי ירכים האחת אכלו האריות והשניה הביא לבית המדרש (סנהדרין נ\"ט ע\"ב). בירך בברית מילה שיזכה התינוק להכנס לחופה ובלילה פגש במלאך המות שבא ליטול את נשמת התינוק וביטל את הגזירה והתינוק נשאר בחיים (קה\"ר פ\"ג - ב\u0027)."},{"i":3580,"n":"רבי שמעון בן חנניה","l":"ש","b":"תנא בדור השלישי - הרביעי. חברו של רבי יוסי הגלילי. ומצינו: \"פעם היה ר\u0027 יוסי הגלילי יושב ודורש בפרה בטבריה ור\u0027 שמעון בן חנינא יושב עמו\" (ילקוט חוקת פ\u0027 ולקח). ומצינו: א\"ר חלפתא איש כפר חנניא שאלתי את שמעון בן חנניה ששאל בנו של רבי חנינא בן תרדיון\" (תוספתא כלים פ\"ט ט\u0027)."},{"i":3581,"n":"שמעון בן טרפון","l":"ש","b":"תנא שאין לקבוע זמנו ומקומו. מובא בבבלי (שבועות מ\"ז ע\"ב). קשה להניח שהיה בנו של רבי טרפון."},{"i":3582,"n":"רבי שמעון בן יאסיניה","l":"ש","b":"הוא רבי שמעון בן יוסינא."},{"i":3583,"n":"רבי שמעון בן יהודה","l":"ש","b":"נראה שהוא רבי שמעון בן יהודה איש כפר עכו (ע\"ע)."},{"i":3584,"n":"רבי שמעון בן יהודה איש כפר עכו","l":"ש","b":"תנא בדור החמישי. מסר הרבה פעמים בשם רבי שמעון בן יוחאי (סוטה ל\"ז ע\"ב), אך לא מצינו במפורש שיש קשר ביניהם. קשה לקבוע בוודאות מי היה יהודה אביו. סביר לומר שרבי שמעון בן יהודה (שבת ע\"ט ב\u0027) הוא הוא רבי שמעון בן יהודה איש כפר עכו."},{"i":3585,"n":"רבי שמעון בן יהוצדק א\u0027","l":"ש","b":"תנא, וכתבו תוספות (סוכה י\"א ע\"ב ד\"ה: דברי). מאחרוני התנאים בארץ ישראל. רבו של רבי יוחנן (יומא מ\"ג ע\"ב), ולא מצינו בשום מקום בש\"ס שדיברו יחד או ישב לפניו. היה כהן ונפטר בלוד. ובא יוחנן אחיו להטמא לו (שמחות פ\"ד י\"א) ורבי יוחנן ורבי ינאי הלכו אחרי מטתו (ירו\u0027, נזיר פ\"ז ה\"א)."},{"i":3586,"n":"רבי שמעון בן יהוצדק ב\u0027","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי. חברו של ר\u0027 חייא בר זרנוקי. שניהם הלכו לעבר שנה באסיא (סנהדרין כ\"ו ע\"א), וריש לקיש פגש בהם והקשה להם כמה קושיות ולבסוף קרא להם \"רועי בקר\" ובאו להתלונן לפני רבי יוחנן (שם)."},{"i":3587,"n":"רבי שמעון בן יוחאי","l":"ש","b":"מגדולי התנאים בדור הרביעי, וסתם רבי שמעון בש\"ס הוא רבי שמעון בן יוחאי (שבועות ב\u0027 ע\"ב רש\"י). מחשובי תלמידיו של רבי עקיבא (כתובות ס\"ב ע\"ב) ולמד אצלו שלש עשרה שנה (ויק\"ר פכ\"א - ח\u0027) ורבי עקיבא קראו \"בני\" (מעילה ז\u0027 ע\"א). גם כשרבי עקיבא נחבש בבית האסורים היה רבי שמעון לידו (פסחים קי\"ב ע\"א). בצעירותו למד ביבנה ומצינו (ברכות כ\"ז ע\"ב) מעשה בתלמיד אחד שבא לפני רבי יהושע וכו\u0027 בא לפני רבן גמליאל (דיבנה וכו\u0027) ושם (כ\"ח ע\"א) \"ואותו תלמיד רבי שמעון בן יוחאי הוה\". אח\"כ הוסמך יחד עם חבריו על ידי רבי יהודה בן בבא (סנהדרין י\"ד ע\"א). דיבר נגד המלכות ורצו להרגו וברח יחד עם בנו רבי אלעזר למערה. לסוף י\"ב שנה בא אליהו ואמר להם לצאת וכשיצאו ראו אנשים מניחים חיי עולם ועוסקים בחיי שעה וכל מקום שנתנו עיניהם מיד נשרף. יצאה בת קול ואמרה: \"להחריב עולמי יצאתם?\" חזרו למערתם וחזרו ושהו בה שנה נוספת (שבת ל\"ג ע\"ב). חתנו רבי פנחס בן יאיר היה גדול ממנו בטרם נכנס למערה, אך לאחר שיצא משם היה רבי שמעון בן יוחאי גדול ממנו (שם). ורבי שמעון אמר לבנו אלעזר: \"די לעולם אני ואתה\" (שם), ורבי עקיבא אמר לו: \"דייך שאני ובוראך מכירין כוחך\" (ירו\u0027, סנהדרין פ\"א ה\"ז) וכן אמר רשב\"י: \"יכול אני לפטור את כל העולם כולו מן הדין וכו\u0027 ואלמלא אלעזר בני עמי וכו\u0027\" (סוכה מ\"ה ע\"ב). ומצינו (סנהדרין פ\"ו ע\"א) סתם ספרי רבי שמעון אליבא דר\"ע. וכן יצא מבית מדרשו של רבי שמעון מדרש הלכה לספר שמות הוא מכילתא דרשב\"י (להבדילה ממכילתא דר\u0027 ישמעאל), ומיוחס לו ספר \"הזוהר\". פעם אחת גזרה המלכות גזרה שלא ישמרו את השבת ולא ימולו את בניהם ויבעלו נדות וכו\u0027. אמרו: \u0027מי ילך ויבטל הגזרות? ילך ר\"ש בן יוחאי, שהוא מלומד בנסים\u0027 (מעילה י\"ז ע\"א). פעם יצא אחד מתלמידי רשב\"י לחו\"ל וחזר עשיר והיו מהתלמידים מקנאים בו, ואמר רשב\"י: \"בקעה בקעה המלאי זהב\", וכך היה, ואמר לתלמידיו: \"טלו לכם זהב, אך מחלקכם בעולם הבא אתם נוטלים\" (שמו\"ר פנ\"ב - ג\u0027) האריך ימים אחר ר\u0027 ישמעאל (יומא נ\"ט ע\"ב תד\"ה: משכיה). בין תלמידיו היה בנו רבי אלעזר (שבת ל\"ג ע\"ב) ורבינו הקדוש (עירובין צ\"א ע\"ב)."},{"i":3588,"n":"רבי שמעון בן יוסי","l":"ש","b":"מובא בבבלי (הוריות ב\u0027 ע\"א), ואולי צ\"ל: רבי שמעון בן יהודה."},{"i":3589,"n":"רבי שמעון בן יוסינא (2)","l":"ש","b":"אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של ריש לקיש (בכורות מ\"ז ע\"ב). מסר בשם רבי אושעיא (ירו\u0027, יבמות פי\"ג ה\"א). רבי אלעאי מסר בשמו (שם)."},{"i":3590,"n":"רבי שמעון בן יעקב דמן צור","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן. שאל את רבי יוחנן (ברכות ל\"ג ע\"א). מצינו: \"אמר רבי אבהו שאל רבי ישמעאל בן יעקב דמן צור את ר\u0027 יוחנן בציידן\" [בענין אחר] (כתובות ז\u0027 ע\"א), ולכן \"סה\"ד\" כתב שאולי אחד ט\"ס עכ\"ל, ואני סיווגתי את שניהם כתלמידי רבי יוחנן."},{"i":3591,"n":"רבי שמעון בן יקים","l":"ש","b":"מובא בירושלמי (פאה פ\"ז ה\"א), והוא רבי שמעון בן אליקים."},{"i":3592,"n":"שמעון בן לגס","l":"ש","b":"מובא בירושלמי (יומא פ\"ג ה\"ט), והוא כנראה רבי ישמעאל בן לוגא."},{"i":3593,"n":"שמעון בן לוגא","l":"ש","b":"מובא בירושלמי (שקלים פ\"ה), והוא רבי ישמעאל בן לוגא."},{"i":3594,"n":"רבי שמעון בן לוי","l":"ש","b":"מובא בבבלי (קדושין ל\u0027 ע\"ב) המאמר המובא שם במקום אחר (סוכה נ\"ב ע\"ב) בשם רבי שמעון בן לקיש, ואולי היה כתוב רשב\"ל והמדפיס פיענח רבי שמעון בן לוי במקום לקיש. כן מובא מאמרו: \"כל שהוא רחמן על האכזרים סוף שנעשה אכזר על הרחמנים\" (מדרש שמואל פי\"ח). וב\"ילקוט\" (שם) מובא מאמר זה בשם ריב\"ל."},{"i":3595,"n":"רבי שמעון בן לקיש","l":"ש","b":"מגדולי אמוראי ארץ ישראל בדור הראשון. גיסו (בעל אחותו) של רבי יוחנן (ב\"מ פ\"ד ע\"א). בתחילה היה תלמידו המובהק של רבי יוחנן ולמד בשקידה עצומה והיה מסדר מתניתיה ארבעים פעם לפני שבא לפני רבי יוחנן ללמוד (תענית ח\u0027 ע\"א) ואח\"כ הפך להיות לו לתלמיד חבר: \"אמר להו [ר\u0027 יוחנן] מה אעשה כנגדי\" [ריש לקיש שקול כמותי] (כתובות פ\"ד ע\"ב). רבי יוחנן קראו מר (יומא ג\u0027 ע\"ב). ומצינו: \"איתיביה רבי יוחנן לריש לקיש\" (יבמות י\u0027 ע\"ב). היה צעיר מרבי יוחנן (מעילה ז\u0027 ע\"ב רש\"י ד\"ה: אמר). מוצאו ממשפחת חכמים (שבת קי\"ט ע\"ב) בצעירותו זכה להיות מתלמידיו הקטנים של רבינו הקדוש, כפי שהוא עצמו אמר: \"לא זכינן לאורייתא אלא בגיל דחמינן אצבעתיה דרבי\" (ירו\u0027, ביצה פ\"ה ה\"ב). תוספות כתבו \"מכאן אמר ר\"ת דריש לקיש מתחילה ידע הרבה אלא שפרק עול תורה ונעשה עם הארץ\" (ב\"מ שם ד\"ה: אי) - [אולי על המשקל של רבי אלעזר בן ערך, שנמשך אחר היין והרחיצה ונעקר תלמודו ושכחו ואחר כך חזר אליו, (שבת קמ\"ז ע\"ב)]. ועסק בליסטות ופגש ברבי יוחנן, ורבי יוחנן התפעל מכוחו העצום, ובהשפעתו התחיל ללמוד תורה ונתן לו את אחותו לאשה. ומשמע שיגיעתו בתורה היתה כמו של רבי חייא (ירו\u0027, כלאים פ\"ט ה\"ג). והיה כה חריף עד שאמר הרואה את ריש לקיש בבית המדרש כאילו עוקר הרים וטוחנן זה בזה (סנהדרין כ\"ד ע\"א). היה מתפלפל עם רבי יוחנן ועל כל דבר ודבר הקשה לו עשרים וארבע קושיות ומתרץ עשרים וארבעה תירוצים (ב\"מ פ\"ד ע\"א) ולשניהם קראו \"שני גדולי עולם\" (ירו\u0027, ברכות פ\"ח ה\"ו). היה גם תלמידם של רבי יהושע בן לוי (ירו\u0027, מו\"ק פ\"ב ה\"ד) רבי חנינא (שבת קי\"ד ע\"א) ורבי אושעיא (יבמות נ\"ז ע\"א תוס\u0027). צם 003 תעניות כדי לראות את רבי חייא (ירו\u0027, כלאים פ\"ט ה\"א). כשהיה מראשי הדור תפסו גזלנים את רבי אמי, ור\"ל אמר אני ארדוף אחריהם, או שאהרגם או שיהרגו אותי, ולבסוף הסתכן והצילו מידם (ירו\u0027, תרומות ספ\"ח). פעם הרג לחבורת רוצחים שלמה וניצל (גיטין מ\"ז ע\"א). נקרא \"תקיפי ארעא דישראל\" (חולין קכ\"ב ע\"א). לא היה מתחיל לדבר עם איש, ולמי שר\"ל דיבר עמו יכלו לתת הלואה ללא עדים (יומא ט\u0027 ע\"ב). מאחר שהיה כתלמיד - חבר לרבי יוחנן היו להם תלמידים משותפים רבים ור\"ל היה חוזר ושונה לתלמידים מה שדרש רבי יוחנן (ב\"ק קי\"ז ע\"א רש\"י ד\"ה: וסיים). לא רצה ליהנות מכבוד התורה (מגילה כ\"ח ע\"ב). כל ימיו כל מה שהיה משתכר לא היה מצמצם להצניע ליום מחר (גיטין מ\"ז ע\"א רש\"י ד\"ה: יתיב). כשמת היה כל עזבונו שהניח אחריו קב של מוריקא, וקרא על עצמו \"ועזבו לאחרים חילם\" (שם). על פטירתו מסופר (ב\"מ שם) שפעם אחת בשעת ויכוח הלכתי עם רבי יוחנן על כלי זין לענין טומאה הזכיר לו ר\u0027 יוחנן את עברו, שהיה משתמש בכלי זין, ור\"ל השיב לו בתקיפות רבה ורבי יוחנן הקפיד עליו וחלה ריש לקיש ומת, ורבי יוחנן קרע בגדיו ומיאן להתנחם עד שדעתו נעקרה עליו וחכמים בקשו רחמים ומת גם הוא (ב\"מ שם). ריש לקיש השאיר אחריו בן צעיר חכם גדול וחריף (תענית ט\u0027 ע\"א)."},{"i":3596,"n":"רבי שמעון בן מנסיא","l":"ש","b":"תנא בדור החמישי. מסר בשם רבי שמעון בן יוחאי (אבות פ\"ו מ\"ט), אך נראה מדברי רש\"י שלא היה תלמידו של רשב\"י (ביצה כ\"ו ע\"א ד\"ה: א\"ל רבי). גם ממה שמצינו: \"רבי שמעון בן אלעזר אומר משום רבי מאיר וכן היה רבי שמעון בן מנסיא אומר כדבריו\" (כתובות י\"ד ע\"ב) אין ראיה, שהיה תלמידו של רבי מאיר. ר\u0027 יוסי בן המשלם היה חברו ושניהם מכונים \"עדה קדושה\" והיה חברו של רבי וחלק עמו (ביצה כ\"ו ע\"א) ואמר על רבי \"שבע מידות שמנו חכמים לצדיקים כולן נתקיימו ברבי ובניו\" (אבות פ\"ו מ\"ט)."},{"i":3597,"n":"שמעון בן נזירא","l":"ש","b":"אמורא ארץ ישראלי בדור הראשון - השני. מובא בירושלמי (שקלים פ\"ב ה\"ה) ע\"ע בר טירא."},{"i":3598,"n":"רבי שמעון בן ננס","l":"ש","b":"תנא בדור השלישי. חברם של רבי ישמעאל ורבי עקיבא ובר פלוגתיה שלהם. רבי ישמעאל אמר עליו: \"הרוצה שיחכים יעסוק בדיני ממונות וכו\u0027 והרוצה שיעסוק בדיני ממונות ישמש את שמעון בן ננס\" (ב\"ב קע\"ה ע\"ב). חלק עם רבי עקיבא (מנחות מ\"ה ע\"ב). לפי דעת הרמב\"ם (בהקדמה לזרעים) וכן לדעת הר\"ח (סנהדרין י\"ז ע\"ב) היה שמעון בן ננס מן הדנים לפני חכמים ביבנה (שם)."},{"i":3599,"n":"רבי שמעון בן נתנאל","l":"ש","b":"תנא בדור השני. תלמיד רביעי מחמשת תלמידיו המצויינים של רבי יוחנן בן זכאי (אבות פ\"ב מ\"ח). ריב\"ז אמר עליו: \"ירא חטא\". רבן גמליאל הזקן נתן לו את בתו לאשה (תוספתא ע\"ז פ\"ג). דרש במעשה מרכבה: \"בתקופת תמוז היה ורעשה הארץ ונראתה הקשת בענן ויצאה בת קול ואמרה: \u0027הרי המקום פנוי לכם והטרקלין מוצע לכם וכו\u0027\" (ירו\u0027, חגיגה פ\"ב ה\"א)."},{"i":3600,"n":"שמעון בן עזאי","l":"ש","b":"תנא בדור השלישי - הרביעי. תלמידו המובהק של רבי עקיבא (ברכות ס\"ב ע\"א) והפך לו לתלמיד חבר (ב\"ב קנ\"ח ע\"ב), ונכנס עמו ל\"פרדס\" (חגיגה י\"ד ע\"ב, וע\"ע שמעון בן זומא) והציץ ומת. אף שהיה מן \"הדנים לפני חכמים\" (סנהדרין י\"ז ע\"ב) לא נסמך מעולם (קידושין מ\"ט ע\"ב רש\"י). כשדרש בן עזאי (יבמות ס\"ג ע\"ב): \"כל יהודי שאין עוסק בפריה ורביה וכו\u0027 כאילו שופך דמים\" אמרו לו: \"נאה דרש ואין נאה מקיים\" (שלא התחתן מעולם או התחתן ופרש - סוטה ד\u0027 ע\"ב) ענה להן בן עזאי: \"ומה אעשה שנפשי חשקה בתורה\". ולקח את בת רבי עקיבא באירוסין ופרש ממנה (כתובות ס\"ג ע\"א תד\"ה: ברתיה). רבנו גרשום כתב, שלמד לפני רבי אליעזר בן הורקנוס (ב\"ב קנ\"ח ע\"ב) [לא מצאתי את המקור לדברי רבנו גרשום] וכן מסר בשם רבי יהושע (יומא כ\"ה ע\"א), והצטער על שלא שימש את רבי ישמעאל (חולין ע\u0027 ע\"ב). רבי ישמעאל ורבי עקיבא ובן עזאי מכונים \"ג\u0027 זקנים\" (תמורה כ\"א ע\"ב). היה סמל השקידה ואמרו: \"משמת בן עזאי בטלו השקדנים\" (סוטה מ\"ט ע\"א). רש\"י כתב: \"ולא היה בימיהם [בן זומא ובן עזאי] כמותם בתורה\" (קידושין מ\"ט ע\"ב). וכך הפך בן עזאי להיות לסמל בידיעת התורה. רבי יוחנן אמר: \"אנא בן עזאי, דהכא\" (ירו\u0027, בכורים פ\"ב ה\"ב), אביי אמר: \"הריני כבן עזאי בשוקי טבריה\" (קידושין כ\u0027 ע\"א) וכן אמר רבא: (עירובין כ\"ט ע\"א). ומצינו: \"בן עזאי אומר: \u0027כל חכמי ישראל דומין עלי כקליפת השום חוץ מן הקרח הזה\u0027\" (בכורות נ\"ח ע\"א), ופירש רש\"י: רבי עקיבא. ודעת המדרש, שבן עזאי היה מעשרת הרוגי מלכות (איכ\"ר פ\"ב פ\u0027 בלע)."},{"i":3601,"n":"ר\u0027 שמעון בן עקשיה","l":"ש","b":"תנא שאין לקבוע זמנו. מאמרו היחיד מובא במשנה (סוף קנים)."},{"i":3602,"n":"רבי שמעון בן פזי","l":"ש","b":"אמורא ארץ ישראלי בדור השני. תלמידו המובהק של רבי יהושע בן לוי (ברכות י\u0027 ע\"א) מסר גם בשם בר קפרא (זבחים ס\"א ע\"ב) רבין מסר משמו: \"כי אתא רבין אמר ר\"ש בן פזי וכו\u0027\". הניח אחריו בן חכם ושמו רב יהודה (ברכות ט\u0027 ע\"ב)."},{"i":3603,"n":"רבי שמעון בן קיסמא","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי שמעון בן לקיש."},{"i":3604,"n":"ר\u0027 שמעון בן רבי עקיבא","l":"ש","b":"תנא בדור הרביעי. בנו של רבי עקיבא. רבי עקיבא הביאו לחופה ועשה לו משתה ופתח חביות יין במשתה (ירו\u0027, ברכות ספ\"ו). בנו זה מת על פני אביו ורבי עקיבא הספידו ואמר: \"יודע אני שהוא בן עולם הבא, שזיכה את הרבים\" (שמחות פ\"ח)."},{"i":3605,"n":"שמעון בן שטח","l":"ש","b":"מחכמי ה\"זוגות\" שלפני התנאים. הוא וחברו יהודה בן טבאי היו ה\"זוג\" השלישי. קיבלו מיהושע בן פרחיה ונתאי הארבלי ומסרו לשמעיה ואבטליון. יהודה בן טבאי היה הנשיא ושמעון בן שטח היה אב\"ד (חגיגה ט\"ז ע\"ב). כשיהודה בן טבאי טעה פעם בפסק דין והרג שלא כדין עד זומם, אמר לו שמעון בן שטח: \"אראה בנחמה אם לא שפכת דם נקי\", ומאז קיבל עליו יהודה בן טבאי להורות רק ע\"פ שמעון בן שטח (תוספתא סנהדרין פ\"ו ז\u0027). אחותו המלכה שלומציון היתה נשואה לינאי המלך (ברכות מ\"ח ע\"ב). הסתכסך עם ינאי המלך ומכעס המלך ברח (ירו\u0027, ברכות פ\"ז ה\"ב), וכשבאו שרים גדולים מפרס ושאלו עליו החזירו המלך (שם). פעם הרג עבדו של ינאי המלך נפש וכשהעמידוהו לדין ציווה עליו שמעון בן שטח שיעמוד על רגליו וסירב ואמר שהסנהדרין יצוו עליו והיו הסנהדרין יראים מינאי מלומר לו שיעמוד. אמר להם שמעון בן שטח: \"בעלי מחשבות אתם, יבוא בעל המחשבות וייפרע מכם, מיד בא גבריאל וחבטן בקרקע ומתו\" (סנהדרין י\"ט ע\"ב). תלה 08 מכשפות באשקלון (ירו\u0027, חגיגה פ\"ב ה\"ב) והענין מובא ברש\"י (סנהדרין מ\"ד ע\"ב). כשמת ינאי המלך ציווה לפני מותו שאשתו שלומציון תמלוך ויעץ לה להשלים עם הפרושים (סוטה כ\"ב ע\"ב), ומאז היה למנהיג האומה כולה (קדמוניות היהודים). ואז היו הימים הטובים לישראל כמסופר, שבימי שמעון בן שטח \"ירדו להם גשמים בלילי רביעית ובלילי שבתות עד שנעשו חטים ככליות ושעורים כגרעיני זיתים ועדשים כדינרי זהב וצררו מהם דוגמא לדורות\" (תענית כ\"ג ע\"א). בימיו היה חוני המעגל (בכורות י\"ט ע\"א). בבנו העידו שני עדי שקר (מקרובי המכשפות שנתלו באשקלון) על חיוב מיתה ונגמר דינו וחזרו בהם העדים ואעפ\"כ הרגוהו בית דין על פי הדין שנגמר נגדו (סנהדרין מ\"ד ע\"ב רש\"י)."},{"i":3606,"n":"ר\u0027 שמעון בן שקפא","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי. מובא בקה\"ר, שאמר רבי יודן בשמו (פ\"א - רפי\"א)."},{"i":3607,"n":"רבי שמעון בן תחליפא","l":"ש","b":"מובא בבבלי (כתובות קי\"א ע\"ב), וגירסת הגר\"א: רבי שמעון בן תחלפא."},{"i":3608,"n":"רבי שמעון בנו של רבי יוחנן בן ברוקא","l":"ש","b":"מובא בבבלי (פסחים צ\"א ע\"א), וצ\"ל כנראה \"רבי ישמעאל בנו\" וכו\u0027."},{"i":3609,"n":"רבי שמעון בר אבא","l":"ש","b":"הוא רב שמן בר אבא."},{"i":3610,"n":"רבי שמעון בר אחא","l":"ש","b":"מובא (ירו\u0027, ע\"ז פ\"ב ה\"ד) ונראה שצריך לומר רבי שמעון בר אבא."},{"i":3611,"n":"רבי שמעון בר אמי","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי. רבי ברכיה מסר משמו: \"אשרי לאדם שהוא גבוה מפשעיו\" (ב\"ר פכ\"ב - ו\u0027)."},{"i":3612,"n":"ר\u0027 שמעון בר בא","l":"ש","b":"הוא רב שמן בר אבא."},{"i":3613,"n":"ר\u0027 שמעון בר ביסנא","l":"ש","b":"מובא בתנחומא (הישן פ\u0027 נשא), וכן גירסת הב\"ח בבבלי (שבת ע\"ה ע\"ב) ולפנינו רבי שמעון בן קיסמא."},{"i":3614,"n":"רבי שמעון בר ברסנה","l":"ש","b":"מובא בירושלמי (ע\"ז פ\"א ה\"א), וצ\"ל: רבי שמעון בר כרסנא."},{"i":3615,"n":"ר\u0027 שמעון בר הלל","l":"ש","b":"מאחרוני האמוראים בארץ ישראל בדור הששי. אביו רבי הלל בר פזי היה תלמידו של רבי יוסי (חברו של רבי יונה), כדמצינו בירושלמי (כתובות רפ\"ט). בנו ר\u0027 שמעון היה תלמידו של אביו (ירו\u0027, סנהדרין פ\"ז ה\"ה)."},{"i":3616,"n":"שמעון בר ווא","l":"ש","b":"הוא רב שמן בר אבא."},{"i":3617,"n":"רבי שמעון בר זביד","l":"ש","b":"אמורא בדור הרביעי. תלמידו של רבי יצחק בן טבלא (נדרים ח\u0027 ע\"ב). גם אחיו היה חכם גדול: \"משתבחין ליה רבנן לר\u0027 זירא את בר רב זביד אחוה דרבי שמעון בר רב זביד\" (ברכות ל\"ח ע\"א)."},{"i":3618,"n":"רבי שמעון בר זירוד","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן (סנהדרין י\"ד ע\"א)."},{"i":3619,"n":"שמעון בר חוטא","l":"ש","b":"מובא בב\"ר (פכ\"ו - א\u0027), ויש בר חטייא (ב\"ר פ\"ל - ח\u0027)."},{"i":3620,"n":"שמעון בר חייא","l":"ש","b":"אמורא בבלי בדור השני. מתלמידיו הגדולים של רב ורבו של חייא בנו של רב (ירו\u0027, ע\"ז פ\"ד ה\"א). מסרו משמו רב יהודה (ירו\u0027, שבת ספ\"ה) ורבי אלעאי (שם פ\"ו ה\"א)."},{"i":3621,"n":"ר\u0027 שמעון בר חנן","l":"ש","b":"אמורא ארץ ישראלי בדור השני. מסר בשם ר\u0027 יוסי בר קצרתא (מדרש תהלים פע\"ח)."},{"i":3622,"n":"רבי שמעון בר יוסי בן לקוניא","l":"ש","b":"תנא בדור החמישי. גיסו של רבי אליעזר בן שמעון [שהיה חתנו של רבי יוסי בן לקוניא] (ב\"מ פ\"ח ע\"א). חברו של רבי חייא (ירו\u0027, ברכות פ\"ב ה\"ג). רבו של רבי יונתן (ירו\u0027, הוריות פ\"ב ה\"ה). כשנפטר רבי שמעון בר יוסי בן לקוניא הלכו שניהם אחרי מיטתו (ירו\u0027, ברכות שם). לימד תורה לבנו של רבי אלעזר בן שמעון ורבי קרא עליו: \"ולוקח נפשות חכם\" (ב\"מ פ\"ה ע\"א). \"יוחסין\" כתב, שהיה מבית דינו של רבי."},{"i":3623,"n":"רבי שמעון בר ינאי","l":"ש","b":"אמורא ארץ ישראלי בדור השני. בנו של רבי ינאי האמורא הנודע. נראה, שבדרך כלל קיבל מאביו כמובא: \"דאמר רבי שמעון בי רבי ינאי אני לא שמעתי מאבא\" (ירו\u0027, שבת פי\"ג ה\"ז) ונראה דוקא בשאלה זו לא שמע, אבל בד\"כ שמע. מובא מעשה על ר\u0027 ינאי שקטף בכרמו במועד (מו\"ק י\"ב ע\"ב), ובירושלמי מובא אותו מעשה על רבי שמעון בר ינאי (מו\"ק פ\"ב ה\"ב). היה לו בן ושמו ר\u0027 ינאי (ב\"ר ספס\"א)."},{"i":3624,"n":"ר\u0027 שמעון בר ישמעאל","l":"ש","b":"מובא בש\"ר (פנ\"א - ד\u0027)."},{"i":3625,"n":"רבי שמעון בר כהנא","l":"ש","b":"תנא בדור השלישי. תלמידו של רבי אליעזר בן הורקנוס (ירו\u0027, דמאי פ\"ג ה\"ב). ורבנן שמעון בן גמליאל (אבי רבי) היה תלמידו (ירו\u0027, חלה פ\"ד ה\"ה). מובא מעשה בליסטים שנתפס בקיסרין שבקפודקיא וכשהיה יוצא ליהרג אמר להם צאו ואימרו לאשתו של שמעון בר כהנא שהרגתיו בכניסתו ללוד ובא מעשה לפני חכמים וכו\u0027 (תוספתא יבמות פ\"ד). \"סה\"ד\" סבר, כנראה, שאין זה התנא רבי שמעון בר כהנא אלא אחר ועל כן חילקו לשני ערכים."},{"i":3626,"n":"רבי שמעון בר כרסנא","l":"ש","b":"אמורא ארץ ישראלי בדור החמישי. מסר משמו של רבי אחא ונראה שהיה תלמידו (ירו\u0027, שבת פ\"א רה\"ח)."},{"i":3627,"n":"ר\u0027 שמעון בר מיישא","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי אלעזר ושאל ממנו (ירו\u0027, מגילה פ\"א הי\"ב)."},{"i":3628,"n":"שמעון בר נרשייא","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם ריש לקיש (ירו\u0027 כלאים פ\"ג ה\"א). רבו של רבי אבא בר כהנא (שם)."},{"i":3629,"n":"ר\u0027 שמעון בר סימון","l":"ש","b":"מובא במדרש תהלים (פכ\"ה - ב\u0027), ונראה שאולי יש ט\"ס בשם."},{"i":3630,"n":"רבי שמעון בר סני","l":"ש","b":"מובא בירושלמי (דמאי פ\"ג ה\"א), ונראה שיבוש ואולי צ\"ל: רבי שמעון בר כרסנא."},{"i":3631,"n":"רבי שמעון בר רב יצחק","l":"ש","b":"מובא בירושלמי (שבת פ\"ב ה\"ג)."},{"i":3632,"n":"רבי שמעון בר רבי","l":"ש","b":"תנא, מהתנאים האחרונים בדור המעבר בין התנאים לאמוראים. שמו מובא במשנה (מכות כ\"ג ע\"ב). בנו הצעיר של רבי (כתובות ק\"ג ע\"ב). \"יוחסין\" כתב, שהיה קטן מרבן גמליאל אחיו וגדול ממנו בחכמה. למד יחד עם ר\u0027 חייא ור\u0027 ישמעאל בר יוסי (יבמות ק\"ה ע\"ב). היה תלמידו המובהק של אביו (ב\"ק קי\"א ע\"ב). אביו קרא לו \"נר ישראל\" (ערכין י\u0027 ע\"א) לפני פטירתו מינה אותו אביו ל\"חכם\" ומסר לו את \"סדרי החכמה\" (כתובות ק\"ג ע\"ב). למד בחברותא יחד עם בר קפרא (מו\"ק ט\"ז ע\"א), וכן עם רבי חייא (קידושין ל\"ג ע\"א). היה גדול מרבי חייא (גיטין פ\"ד ע\"ב תד\"ה: רבי) כשהתחתן, עדיין רבי מאיר חי (ירו\u0027, ביצה פ\"ה ה\"ב). היה עשיר גדול (מנחות פ\"ו ע\"א). עסק בסחר משי בשותפות עם רבי חייא (ב\"ר פע\"ז - ב\u0027). היה לו קול עבה ור\u0027 חייא אמר לו: \"אלמלא לוי אתה פסול אתה מן הדוכן משום דעבי קולך\" (מגילה כ\"ד ע\"ב). לא מצאנו שהיו לו בנים, וכשנולדה לו בת ניחמו אביו, ובר קפרא אמר לו: תנחומים של הבל ניחמך אביך (ב\"ב ט\"ז ע\"ב)."},{"i":3633,"n":"רבי שמעון בריה דרבי אייבו","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מובא בירושלמי (יבמות פי\"א ה\"ב) שעל קושייתו השיב רבי אלעאי."},{"i":3634,"n":"ר\u0027 שמעון בריה דר\u0027 אבהו","l":"ש","b":"אמורא בדור הרביעי. בנו של רבי אבהו. מובא (ב\"ר פי\"ח - ה\u0027), ואולי יש ט\"ס בשם וצ\"ל \"ר\u0027 שמעון בריה דר\u0027 אייבו\", כמובא בירושלמי (יבמות פי\"א ה\"ב)."},{"i":3635,"n":"ר\u0027 שמעון בר\u0027 אלעזר בן פרטא","l":"ש","b":"כן גיר\u0027 \"יוחסין\", ולפנינו אין."},{"i":3636,"n":"ר\u0027 שמעון דיינא","l":"ש","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. תלמידו של רבי זירא וישב לפניו (ירו\u0027, נדרים פ\"ז ה\"י)."},{"i":3637,"n":"ר\u0027 שמעון דתוספתא","l":"ש","b":"מובא בירושלמי (ברכות פ\"ג ה\"ב). ע\"ע ר\u0027 שמואל דסופפתא."},{"i":3638,"n":"רבי שמעון החסיד","l":"ש","b":"תנא דברייתא. מובא כמה פעמים באגדה (חגיגה י\"ג ע\"ב). רב הונא בר תורתא היה תלמידו (חולין קכ\"ז ע\"ב)."},{"i":3639,"n":"רבי שמעון המחוזי","l":"ש","b":"אמורא ארץ ישראלי בדור הראשון. רבי יוחנן מסר משמו: \"ורבי יוחנן משום רבי שמעון המחוזי משום רבי יוחנן המכותי\" (סוכה מ\"ה ע\"ב)."},{"i":3640,"n":"רבי שמעון הנשיא","l":"ש","b":"מובא בבבלי, והגמרא שואלת: \"נשיא היה או משמיה דנשיא אמר?\", ונשארת הגמרא בתיקו (גיטין ט\"ו ע\"א)."},{"i":3641,"n":"שמעון העמסוני","l":"ש","b":"מובא בבבלי: שמעון העמסוני ואמרי לה נחמיה העמסוני היה דורש כל אתים שבתורה כיון שהגיע לאת ה\u0027 אלקיך תירא פירש וכו\u0027 עד שבא ר\"ע וכו\u0027 (פסחים כ\"ב ע\"ב). אם כן נראה שהיה קודם רבי עקיבא, אך אין זו ראיה מוחלטת שכן מצינו: \"אמר רבי אלעזר בן עזריה וכו\u0027 עד שדרשה בן זומא וכו\u0027\" (ברכות י\"ב ע\"ב) ובן זומא היה בן דורו של ראב\"ע. ומאידך, הגמרא מפקפקת אם שמעון העמסוני או נחמיה העמסוני היה, ומצינו שנחמיה העמסוני שימש את ר\"ע עשרים ושתים שנה, ואם כן אולי יתכן, ששניהם - גם נחמיה וגם שמעון העמסוני - היו תלמידים של ר\"ע (ירו\u0027, ברכות פ\"ט ה\"ה)."},{"i":3642,"n":"שמעון הפקולי","l":"ש","b":"תנא בדור השני - השלישי. סידר י\"ח ברכות (תפלת שמונה עשרה) לפני רבן גמליאל (ברכות כ\"ח ע\"ב), ואת שמו פיקולי פרש\"י: \"יש אומרים שמשתכר בצמר גפן שנקרא פקולא\" (מגילה י\"ז ע\"ב ד\"ה: הפקולי)."},{"i":3643,"n":"שמעון הצדיק","l":"ש","b":"אחרון החכמים מאנשי כנסת הגדולה: \"שמעון הצדיק היה משירי אנשי כנסת הגדולה\" (אבות פ\"א מ\"ב), וממנו ומתלמידו אנטיגנוס ואילך החלה תקופת ה\"זוגות\". בימיו בא אלכסנדר מוקדון לארץ ישראל, וכיון שראה לשמעון הצדיק ירד ממרכבתו והשתחווה לפניו ואמר: \"דמות דיוקנו של זה מנצחת לפני בבית מלחמתי\" (יומא ס\"ט ע\"א). מתקופתו החלה ספירת מנין השטרות (וזה מנין השטרות שהחל בשנת ג\u0027 תמ\"ח /213 לפה\"ס). שימש ארבעים שנה בכהונה גדולה (יומא ט\u0027 ע\"א). ובגמרא מסופר: \"אותה שנה שמת שמעון הצדיק, אמר להן \u0027שנה זו הוא מת\u0027. אמרו לו: \u0027מניין אתה יודע? \u0027 אמר להן: \u0027כל יום הכיפורים נזדמן לי זקן אחד לבוש לבנים ונתעטף לבנים ונכנס עמי ויצא עמי (מנחות ק\"ט ע\"ב). שנה זו נזדמן לי זקן אחד לבוש שחורים ונתעטף שחורים ונכנס עמי ולא יצא עמי\u0027. לאחר הרגל חלה שבעת ימים ומת\" (מנחות ק\"ט ע\"ב). ופירשו תוספות שכתב הירושלמי דשמא שכינה היתה (שם). היו לו שני בנים, שמעי וחוניו, ואמר להם: \"חוניו בני ישמש תחתי\", ונתקנא שמעי באחיו והטעה את חוניו והלבישו לבוש שאינו מתאים בזמן העבודה ורצו אחיו הכהנים להורגו וברח חוניו לאלכסנדריה של מצרים ובנה שם מזבח (שם)."},{"i":3644,"n":"ר\u0027 שמעון השילוני","l":"ש","b":"תנא שאין לקבוע זמנו. מובא בבבלי (פסחים קי\"ח ע\"א), ועל דרשתו חלק רבי נתן (שם)."},{"i":3645,"n":"שמעון השקמוני","l":"ש","b":"תנא בדור הרביעי. תלמידו של רבי עקיבא וחברו של רבי חדקא: \"א\"ר חדקא שמעון השקמוני היה לי חבר מתלמידי רבי עקיבא\" (ב\"ב קי\"ט ע\"א)."},{"i":3646,"n":"שמעון התימני","l":"ש","b":"תנא בדור השלישי. מכונה תימני, כי מתמנה היה (תענית י\"ט ע\"א רש\"י). היה מן הארבעה ביבנה שידעו שבעים לשון (סנהדרין י\"ז ע\"ב). תלמידם של רבי אליעזר ור\u0027 יהושע ור\u0027 עקיבא: \"רבי אליעזר רבי יהושע רבי עקיבא ושמעון התימני דן לפניהם בקרקע\" ופרש\"י: \"תלמיד היה ולא נסמך שלא בא לכלל זקנה\" (שם). חלק על רבי עקיבא ורבי עקיבא ענה לו (ב\"ק צ\u0027 ע\"ב). מסופר מעשה בשמעון התימני שלא בא לבית המדרש, מצאו רבי יהודה בן בבא ושאלו למה לא בא לבית המדרש (ביצה כ\"א ע\"א)."},{"i":3647,"n":"ר\u0027 שמעון חסידא","l":"ש","b":"אמורא בדור השני. רב חנא בר ביזא, שהיה מבבל, היה תלמידו ומסר ממנו אגדות (יומא ע\"ז ע\"א). גם ר\u0027 יעקב בר אידי מארץ ישראל היה מתלמידיו: \"כי אתא רבין אמר רבי יעקב בר אידי א\"ר שמעון חסדא\" (סוף ר\"ה). גם רבי יונה מארץ ישראל מסר משמו, ולכן אין לקבוע את מקומו של ר\u0027 שמעון חסידא."},{"i":3648,"n":"רבי שמעון יאסיניא","l":"ש","b":"מובא בבבלי (בכורות מ\"ז ע\"ב), והוא רבי שמעון בן יוסינא."},{"i":3649,"n":"ר\u0027 שמעון לודייא","l":"ש","b":"אמורא ארץ ישראלי בדור הרביעי. מובא בש\"ר (פ\"ג - ה\u0027), שאמר בשם ר\u0027 סימון."},{"i":3650,"n":"שמעון נזירא","l":"ש","b":"מובא בבלי (יבמות צ\"ז ע\"א). ע\"ע בר טירא."},{"i":3651,"n":"שמעון סיכנא איש עוצה","l":"ש","b":"חי בארץ ישראל בדור הראשון לתנאים. אמר לרבן יוחנן בן זכאי: אני גדול כמוך, שהיה חופר בורות ושיחין בירושלים וקרא עליו הפסוק \"וקרוב לשמוע מתת הכסילים\" (קה\"ר ספ\"ד). מהענין שלפנינו אין להכריע אם היה חכם, ו\"יוחסין\" ו\"סה\"ד\" הביאוהו בין החכמים."},{"i":3652,"n":"ר\u0027 שמעון ספרא דטרכנס","l":"ש","b":"סופר בעיר טרכנס שבארץ ישראל חי בדור השני - השלישי לאמוראים וקרא בתורה ורצו בני עירו שיפסיק בקריאתו באמצע פסוק, כדי שיקראו עם בניהן, ושאל את רבי חנינא וא\"ל: \"אפילו יחתכו ראשך לא תשמע להם\" והעבירוהו ממשרתו, ואמר רבי זירא: \"אילו היה בימי הייתי ממנה אותו לא לסופר אלא לחכם\" (ירו\u0027, מגילה פ\"ד ה\"ה). אין להכריע שהיה חכם, שמא סופר היה, ו\"יוחסין\" ו\"סה\"ד\" הביאוהו בין שמות החכמים."},{"i":3653,"n":"שמעון קמטריא","l":"ש","b":"אמורא ארץ ישראלי בדור הרביעי. שאל את רבי חייא בר אבא (ירו\u0027, ברכות פ\"ט ה\"ב). עלה כל שנה לירושלים עם חמורים טעונים משא (שם). ופירש \"שדה יהושע\", שהיה עושה ארגזים."},{"i":3654,"n":"רבי שמעון שזורי","l":"ש","b":"תנא בדור הרביעי. תלמידו של רבי טרפון (מנחות ל\"א ע\"א). מובא במחלוקת עם תלמידי רבי עקיבא, רבי מאיר רבי יהודה ורבי יוסי (מנחות ל\u0027 ע\"ב) ואמרו: \"כל מקום ששנה רבי שמעון שזורי הלכה כמותו\" (שם). \"יוחסין\" כתבו: \"נקרא שזורי על מלאכתו כ\"כ הרמב\"ם ולי נראה מקום יש בגליל העליון נקרא שזור\", וכן כתב \"כפתור ופרח\" שהוא שם עיר."},{"i":3655,"n":"שמעיה (2)","l":"ש","b":"מחכמי ה\"זוגות\" לפני התנאים. הוא וחברו אבטליון היו \"זוג\" רביעי. שימש כנשיא וחברו אבטליון היה אב\"ד (חגיגה ט\"ז ע\"א). שניהם קיבלו מיהודה בן טבאי ושמעון בן שטח (אבות פ\"א מ\"י), ושניהם היו גרים (גיטין נ\"ז ע\"ב): \"מבני בניו של סנחריב למדו תורה ברבים מאן אינון שמעיה ואבטליון\". יהודה בן דורתאי אמר עליהם (פסחים ע\u0027 ע\"ב): \"חכמים גדולים ודרשנין גדולים\". הלל, שהיה תלמידם המובהק (יומא ל\"ה ע\"ב), אמר עליהם: \"שני גדולי הדור שמעיה ואבטליון\" (פסחים ס\"ו ע\"א). ומסופר: \"מעשה בכהן גדול אחד שיצא מבית המקדש והלכו כל העם ללוותו, כיון שראו את שמעיה ואבטליון הניחו את הכהן גדול והלכו אחריהם\" (יומא ע\"א ע\"ב). מהלל ושמאי שהיו תלמידיהם, החלה תקופת התנאים."},{"i":3656,"n":"שמעיה איש כפר עותני","l":"ש","b":"מובא בתוספתא \"אמר רבי אליעזר מעשה בשמעיה איש כפר עותני וכו\u0027 ושאל לרבי יוחנן בן זכאי\" (פרה פ\"י - צוקרמנדל). וגיר\u0027 שלנו: רבי אליעזר בן שמעיה איש כפר אותני."},{"i":3657,"n":"רב שמעיה א\u0027","l":"ש","b":"אמורא בבלי בדור השלישי - הרביעי. חברו של רבי אבא ושקיל וטרי עמו (סוף נדה). מצינו, שאביי ורבא דנים בקטע ברייתא ששנה רב שמעיה (סנהדרין מ\"ז ע\"א). ע\"ע רב שמעיה ב\u0027."},{"i":3658,"n":"רב שמעיה בקלנב","l":"ש","b":"מובא בבבלי רב שמעיה בקלנבו (יומא כ\"א ע\"א). ושוב מובא (זבחים צ\"ו ע\"א) אישתמיטתיה הא דתני שמעיה בקלנבו (נ\"א רב שמעיה), ופרש\"י: \"שם מקום שנקרא על שם עכו\"ם\"."},{"i":3659,"n":"רב שמעיה בר זירא","l":"ש","b":"מובא בבבלי (כתובות פ\"א ע\"א) והוא שמעיה בר זעירא."},{"i":3660,"n":"רב שמעיה בר זעירא","l":"ש","b":"אמורא בבלי בדור החמישי. תלמידם של אביי ורבא, שמצינו: \"שלח ליה רבא לאביי ביד רב שמעיה בר זעירא\" (עירובין צ\"ג ע\"א). ומצינו, שאביי תירץ לו את קושייתו (חולין קט\"ז ע\"א)."},{"i":3661,"n":"רב שמעיה ב\u0027","l":"ש","b":"אמורא בבלי בדור החמישי. מובא בבבלי (עירובין מ\u0027 ע\"א). \"סה\"ד\" חילקם לשניים - ר\u0027 שמעיה א\u0027 ור\u0027 שמעיה ב\u0027, ואולי הדין עמו אף שאין הכרח בכך, שכן יתכן שהאריך ימים עד רבינא, וגם לשון הגמרא אינה מוכיחה זאת בוודאות גמורה, וזה לשון הגמרא: \"א\"ל רבא בר תחליפא לרבינא וכו\u0027 ומתקיף לה רב שמעיה וכו\u0027 אזלו שיילוה לרבא אמר להו וכו\u0027\"."},{"i":3662,"n":"ר\u0027 שמעיה חסידא","l":"ש","b":"מובא ב\"זוהר\" (פ\u0027 בלק קפ\"ו)."},{"i":3663,"n":"רב שעורים","l":"ש","b":"אמורא בבלי בדור הרביעי. אחיו של רבא. נכח בפטירת רבא, ורבא ביקשו שיאמר למלאך המות שלא יצערו. רב שעורים ביקש את רבא אחיו שיבוא לראותו אחרי פטירתו ורבא בא וסיפר לו שצער מיתתו היה אך כהקזת דם (מו\"ק כ\"ח ע\"א). מובא גם במקום אחר, ושם הגיר\u0027 רב סעורם (ב\"מ ע\"ג ע\"ב)."},{"i":3664,"n":"רבי שפטיה","l":"ש","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי יוחנן. מובא בבבלי, שאמר ה\u0027 מאמרים מרבי יוחנן רבו (מגילה ל\"ב ע\"א)."},{"i":3665,"n":"שפיפון בן ליש","l":"ש","b":"מובא ב\"סה\"ד\", שהיה צדיק וחברו של בן סבר; מלאך המות לא יכול לו, שכן השביעו בשם המפורש, ויצאה בת קול ואמרה: \"מה אעשה לצדיקים שאנו גוזרים והם מבטלים\", והוסיפו לו שבעים שנה לחייו. מעשה זה אינו נמצא בש\"ס או במדרשים, ומקורו של \"סה\"ד\" הוא \"ספר קטן מעשיות\"."},{"i":3666,"n":"רב שפיר","l":"ש","b":"אמורא בבלי בדור הראשון. מובא בבבלי \"רב איקלע לבי רב שפיר\" (מו\"ק י\"א ע\"א). ו\"סדר תנאים ואמוראים\" גרס: בר שפיר."},{"i":3667,"n":"שקוד","l":"ש","b":"כינוי לשמואל על שם ששוקד על דבריו לאומרם כהלכה (כתובות מ\"ג ע\"ב), והירושלמי גרס: שוקד (כתובות פ\"ד ה\"ב)."},{"i":3668,"n":"רב שרביה","l":"ש","b":"אמורא בבלי בדור החמישי. תלמידו המובהק של רבא, והוא ורבינא אמרו משמו של רבא (שבת קט\"ו ע\"ב). הקשה לרבא מברייתא, ורבא ענה לו: \"אי תניא תניא\" (יבמות קי\"ב ע\"א). היה גם תלמידו של אביי, ואביי תירץ לו את קושייתו (בכורות י\"ט ע\"א)."},{"i":3669,"n":"ר\u0027 ששא בנו של ר\u0027 אבא","l":"ש","b":"מובא בש\"ר (רפכ\"ד)."},{"i":3670,"n":"רב ששעה","l":"ש","b":"מאחרוני האמוראים בארץ ישראל בדור הששי. בנו של ר\u0027 שמואל בר אבדימי. מובא בירושלמי, שר\u0027 שמואל בר אבדימי היה צריך למול את בנו של רב ששעה בשבת ושכח האיזמל והורה ר\u0027 מנא לר\u0027 שמואל בר אבדימי לדחות הברית ליום א\u0027 (שבת פי\"ט ה\"א)."},{"i":3671,"n":"רב ששת","l":"ש","b":"אמורא בבלי בדור השני - השלישי. תלמידו המובהק של רב הונא: \"דרב ששת איעקר מפירקיה דרב הונא\" (יבמות ס\"ב ע\"ב), ופרש\"י: \"שהיה מאריך בדרשותיו וצריכים למי רגלים ומעמידים עצמם ונעקרים\". היה גם תלמידו של רב ירמיה בר אבא (נזיר ס\"ח ע\"א). היה חוזר על לימודו כל שלושים יום (פסחים ס\"ח ע\"ב). היה בקי גדול במשניות ומצינו שרב חסדא היה נרעד מבקיאותו בהיפגשו עימו (עירובין ס\"ז ע\"א), ופרש\"י שם: \"שהיו משניותיו סדורות לו וירא רב חסדא שלא יקשה לו ממשנה על משנה ויאמר לו לתרצן\". וכן אמר רב יצחק בר יהודה: \"רב ששת כי בעינא מילתא מיניה פשיט לי ממתניתא\" (זבחים צ\"ו ע\"ב). היה חריף, ורבא אמר: \"אדם קשה שהוא קשה כברזל ומנו רב ששת\" (מנחות צ\"ו ע\"ב), ופרש\"י: \"חכם ומחודד לחתוך הלכה כברזל\". נהג לומר: \"אמינא כי ניים ושכיב רב אמר להאי שמעתתא\" (יבמות כ\"ד ע\"ב). וכתב בשו\"ת \"חות יאיר\" סי\u0027 קנ\"ב, שלא לגנאי אמר כך רק שבח גדול וכו\u0027. בין תלמידיו היו גם אביי (קידושין ט\"ז ע\"ב) ורבא (ברכות ל\"ד ע\"ב). גם רבותיהם של אביי ורבא רבה ורב יוסף, שמעו ממנו (עירובין ס\"ה ע\"ב). היה עיוור (ברכות נ\"ח ע\"א): \"רב ששת סגי נהור הוה\" ונראה שעיוורונו לא בא לו מלידה, שמצינו: \"שראה נחש בחלום והרגו\" (שם נ\"ז ע\"ב), (אילו היה עוור איך ידע צורת נחש?). היה לו גילוי שכינה (מגילה כ\"ט ע\"א). לא היו לו בנים אלא בנות (יבמות ס\"ב ע\"ב). ביום פטירתו פגש בו מלאך המות בשוק ורצה לקחת נשמתו, אמר לו רב ששת: \"בשוק כבהמה?\" (מו\"ק כ\"ה ע\"א)."},{"i":3672,"n":"רב ששת בריה דרב אידי","l":"ש","b":"מובא בבבלי (פסחים מ\"ט ע\"א), והוא רב שישא בריה דרב אידי. \"יוחסין\" חילקם לשניים וכתב לכל אחד ערך נפרד."},{"i":3673,"n":"רב ששת בריה דרב יהושע","l":"ש","b":"מובא בבבלי (פסחים קט\"ו ע\"א), ואולי יש ט\"ס בשם."},{"i":3674,"n":"רב ששת מקטרזיא","l":"ש","b":"אמורא בבלי בדור השביעי. תלמידו של רב אשי: \"רב ששת מקטרזיא איקלע לקמיה דרב אשי\" (מגילה כ\"א ע\"ב) ומלשון הש\"ס יש להוכיח שהיה תלמידי דרב אשי, שכן אילולא היה תלמידו, היה לשון הש\"ס \"איקלע\" בלי \"לקמיה\"."},{"i":3675,"n":"רבי תדאי","l":"ת","b":"אמורא ארץ ישראלי בדור השני. רבו של רבי אבא (שבת ל\"ח ע\"ב). רבי אמי אמר: \"רבי תדאי לגרמיה [לנפשו] הוא דעבד\" (שם)."},{"i":3676,"n":"תודוס איש רומי","l":"ת","b":"חי ברומי בזמנו של שמעון בן שטח, בדורם של ה\"זוג\" השלישי לפני תקופת התנאים. שמעון בן שטח שלח לו: \"אלמלא תודוס אתה גוזרני עליך נידוי\" (ברכות י\"ט ע\"א), ובמקום אחר מפקפקת הגמרא אם היה גברא רבה או גברא אלימא (פסחים נ\"ג ע\"ב), ומסקנת הגמרא שהיה גברא רבה או שהיה מפרנס תלמידי חכמים."},{"i":3677,"n":"תודוס הרופא","l":"ת","b":"חי בדור השלישי לתנאים. מובא במשנה (בכורות כ\"ח ע\"ב) \"ומעשה בפרה וכו\u0027 ובא מעשה לפני חכמים ביבנה והתירוה שאמר תודוס הרופא אין פרה וכו\u0027\". ומובא בירושלמי \"מעשה שהביאו קופה מליאה עצמות וכו\u0027 ונכנס תודרוס הרופא ונכנסו כל הרופאים עמו אמר תודרוס הרופא אין כאן שדרה ממת אחת ולא גולגולת ממת אחד אמרו הואיל ויש כאן מטהרין ויש כאן מטמאין נעמוד על המנין התחילו מר\"ע וכו\u0027\" (ברכות פ\"א ה\"א). אין ראיה שתודוס זה היה חכם, גם לשון המשנה שאומרת שחכמים התירוה שאמר (כן גורס \"מסה\"ש\") תודוס וכו\u0027 (כלומר המשנה מסתמכת על דברי תודוס הרופא) וכן מירושלמי, אין ראיה לכך, ויתכן שרק ידע מקצועי הביאו ממנו ולא ציטטו דבריו כחכם."},{"i":3678,"n":"תודרוס הרופא","l":"ת","b":"מובא בירושלמי (ברכות פ\"א ה\"א), והוא תודוס הרופא."},{"i":3679,"n":"תוטאי","l":"ת","b":"תנא דברייתא. מובא בבבלי: \"אביי אמר הכי אמר רב ששת הא מני תוטאי הוא דתניא תוטאי אומר וכו\u0027\" (קידושין ט\"ז ע\"ב)."},{"i":3680,"n":"רב תחליפא","l":"ת","b":"אמורא בבלי בדור השלישי. תלמידו של רב הונא, ומספר: \"אנא חזיתיה לרב הונא וכו\u0027\" (מו\"ק כ\"ה ע\"א)."},{"i":3681,"n":"רבי תחליפא","l":"ת","b":"אמורא ארץ ישראלי בדור השלישי. אביו של רב נסא. ר\u0027 נסא מספר, שבילדותו אכל עם ר\u0027 תחליפא אביו ועם ר\u0027 אינייני בר סיסי דודו, ולא צירפוהו לזימון עד שגדל (ירו\u0027, ברכות פ\"ז ה\"ב)."},{"i":3682,"n":"רב תחליפא אבוה דרב הונא בר תחליפא","l":"ת","b":"אמורא בבלי בדור הרביעי - החמישי. מסר משמו של רבא (יומא ו\u0027 ע\"ב). גם בנו רב הונא בר תחליפא היה תלמידו של רבא (יבמות ח\u0027 ע\"ב). נראה, שהבן היה גדול מאביו ועל כן נקרא האב על שם בנו."},{"i":3683,"n":"רב תחליפא אחוה דרבנאי חוזאה","l":"ת","b":"אמורא ארץ ישראלי בדור הראשון - השני. מתיחס לאחיו כמובא בבבלי: \"תני רב תחליפא אחוה דרבנאי חוזאה כל מזונותיו של אדם קצובים לו מראש השנה ועד יום הכפורים חוץ מהוצאת שבתות והוצאת יו\"ט והוצאת בניו לתלמוד תורה\" (ביצה ט\"ו ע\"ב)."},{"i":3684,"n":"רב תחליפא בר אבדימי","l":"ת","b":"אמורא בבלי בדור השני. תלמידו של שמואל (ע\"ז ו\u0027 ע\"א), ומובא: דרב תחליפא בר אבדימי עבד עובדא כותיה דשמואל ואמר רב תחלת הוראה דהאי צורבא מרבנן לקלקולא (ביצה ט\"ז ע\"ב), ופרש\"י: \"דרב פליג עליה ואמר הלכה כתנא קמא\". אמר לרב חסדא \"הכי אמר שמואל\" (בכורות ל\"ז ע\"ב)."},{"i":3685,"n":"רב תחליפא בר אבודימי","l":"ת","b":"מובא בבבלי, והוא רב תחליפא בר אבדימי (בכורות ל\"ז ע\"ב)."},{"i":3686,"n":"רב תחליפא בר אבינא","l":"ת","b":"אמורא בבלי בדור הרביעי. תלמידו של רב חסדא (חולין ס\u0027 ע\"ב)."},{"i":3687,"n":"רב תחליפא בר אימי","l":"ת","b":"אמורא ארץ ישראלי בדור השלישי. תלמידו של רבי אלעזר וחברו של הונא בר חיננא, ושניהם ישבו לפני רבי אלעזר (ירו\u0027, מעשרות פ\"ד ה\"ד)."},{"i":3688,"n":"רב תחליפא בר אמיבי","l":"ת","b":"מובא בבבלי (פסחים ק\"ז ע\"א), ונראה שהוא רב תחליפא בר אבדימי."},{"i":3689,"n":"רב תחליפא בר בר חנא","l":"ת","b":"מובא באס\"ר (פ\"א - א\u0027)."},{"i":3690,"n":"רב תחליפא בר גזא","l":"ת","b":"מובא בבבלי (זבחים ל\"ט ע\"א), והוא רב תחליפא בר גיזא."},{"i":3691,"n":"רב תחליפא בר גיזא","l":"ת","b":"אמורא בבלי בדור הששי. מובא בבבלי, שא\"ל לרבינא: דילמא וכו\u0027 (ע\"ז ס\"ט ע\"א)."},{"i":3692,"n":"ר\u0027 תחליפא בר יעקב","l":"ת","b":"אמורא ארץ ישראלי בדור הרביעי. מסר בשם רבי יהודה בר סימון (מד\u0027 תהלים הישן פקי\"ד)."},{"i":3693,"n":"רב תחליפא בר מערבא","l":"ת","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. היה מארץ ישראל, ולכן קראו לו בר מערבא (רש\"י ב\"מ ז\u0027 ע\"א). תלמידו של רבי אבהו ושאל ממנו (גיטין נ\"ב ע\"ב). שמע מדברי רבי יוחנן והלך ומסרם לרבי אבהו (ברכות נ\"ה ע\"א). נראה, ששנה ברייתא בישיבת רבי יוחנן (מנחות י\"ד ע\"ב). ביקר בבבל (כתובות ח\u0027 ע\"א) ובחוזרו משם מסר מדברי רב חסדא לרבי אבהו רבו (עירובין נ\"ד ע\"ב)."},{"i":3694,"n":"ר\u0027 תחליפא בר קרויה","l":"ת","b":"מובא בפס\u0027 רבתי (פכ\"ו). הגיר\u0027 במדרש תהלים: ר\u0027 אילפא בר קרויא (פקל\"ז - ג\u0027)."},{"i":3695,"n":"רב תחליפא בר רב חסדא","l":"ת","b":"אמורא בבלי בדור הרביעי. בנו ותלמידו של רב חסדא (גיטין ל\"א ע\"ב). רבא היה גיסו, שכן התחתן עם אחותו."},{"i":3696,"n":"רב תחליפא בר שאול","l":"ת","b":"מובא בבבלי (מו\"ק י\u0027 ע\"א), וגיר\u0027 \"דק\"ס\": ר\u0027 חלפתא בר שאול."},{"i":3697,"n":"ר\u0027 תחליפא חמיו דר\u0027 אבהו","l":"ת","b":"אמורא ארץ ישראלי בדור השני. חמיו של רבי אבהו. רבי אבהו אמר משמו (קה\"ר ספ\"י)."},{"i":3698,"n":"ר\u0027 תחליפא חמיו דר\u0027 אחא","l":"ת","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. ושניהם ר\u0027 אחא וחמו אמרו משמו של רבי שמואל בר נחמני (ירו\u0027, ברכות פ\"א ה\"א)."},{"i":3699,"n":"רב תחליפא ממערבא","l":"ת","b":"מובא בבבלי (מנחות י\"ד ע\"ב), והוא רב תחליפא בר מערבא."},{"i":3700,"n":"ר\u0027 תחליפא קיסריא","l":"ת","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. מובא בירושלמי (תענית רפ\"ב). חברו של ר\"ז ושקיל וטרי עמו (ירו\u0027, סוטה ספ\"ה)."},{"i":3701,"n":"ר\u0027 תחנא","l":"ת","b":"\"סה\"ד\" מביאו שמובא בפדר\"א."},{"i":3702,"n":"ר\u0027 תימא בר פפייס","l":"ת","b":"אמורא ארץ ישראלי בדור החמישי. מובא פעם בש\"ס הירושלמי, ומסר בשם רב אושעיא (ירו\u0027, סנהדרין פ\"ד ה\"ז). אם נניח שיש ט\"ס, וצ\"ל \"רבי אושעיא\" במקום \"רב אושעיא\" (רב אושעיא היה אחיו של רבה), הרי שלא היה אמורא בדור החמישי אלא בדור השני, שכן רבי אושעיא היה רבו של ר\u0027 יוחנן וחי בדור הראשון, וא\"כ תלמידו היה בדור השני. דבר זה אין להכריע, ואני כתבתיו בדור החמישי, שכך נראה לי."},{"i":3703,"n":"תנא דבי אליהו","l":"ת","b":"מובא בבבלי (פסחים צ\"ד ע\"א). \"סה\"ד\" כתב: \"אינו אליהו הנביא, אלא הוא תנא ואין לקבוע את זמנו\"."},{"i":3704,"n":"רבי תנחום","l":"ת","b":"אמורא ארץ ישראלי בדור השני - השלישי. תלמידו של רבי יהושע בן לוי (ברכות כ\"ח ע\"ב) מסר גם בשם רבי יוחנן (שבת ל\"ט ע\"ב)."},{"i":3705,"n":"ר\u0027 תנחום אדרייא","l":"ת","b":"מובא בירושלמי (תענית פ\"א ה\"א)."},{"i":3706,"n":"ר\u0027 תנחום איסבולסטיקא","l":"ת","b":"מובא בירושלמי (ברכות פ\"ד ה\"ב)."},{"i":3707,"n":"ר\u0027 תנחום בוצרייא","l":"ת","b":"אמורא ארץ ישראלי בדור הרביעי - החמישי. מובא בירושלמי (כלאים פ\"ג ה\"א). מסר בשם רבי ירמיה (ויק\"ר פט\"ו - ו\u0027). רבי אלעזר בר\u0027 יוסי מסר משמו (שם)."},{"i":3708,"n":"ר\u0027 תנחום בר אחא","l":"ת","b":"מובא בשהש\"ר (פ\"א פ\u0027 כי טובים)."},{"i":3709,"n":"רבי תנחום בר חייא","l":"ת","b":"אמורא ארץ ישראלי בדור השני - השלישי. מסר בשם רבי יהושע בן לוי (ירו\u0027, שקלים רפ\"ג) ובשם רבי יוחנן (ירו\u0027, שבת פ\"א ה\"ד). רבי יונה מסר משמו (ירו\u0027, ברכות פ\"ה ה\"א)."},{"i":3710,"n":"ר\u0027 תנחום בר חכינאי","l":"ת","b":"מובא בבבלי (שבועות ל\"ו ע\"א)."},{"i":3711,"n":"ר\u0027 תנחום בר חמא","l":"ת","b":"מובא בפסדר\"כ (קע\"ג)."},{"i":3712,"n":"רבי תנחום בר חנילאי","l":"ת","b":"אמורא ארץ ישראלי בדור השני. היה רגיל ללמוד אגדה לפני רבי יהושע בן לוי (ב\"ק נ\"ה ע\"א). כשר\u0027 חנינא בר עגיל בא לשאול ממנו א\"ל: \"מריב\"ל לא שמעתי אך כך אמר לי שמואל בר נחום אחי אמי\" (שם). בין האומרים בשמו רבי לוי (ב\"ר פ\"ד - ו\u0027). יש ממנו דרושי אגדות רבים בש\"ס (ב\"מ פ\"ו ע\"ב ועוד)."},{"i":3713,"n":"ר\u0027 תנחום בר חנינא","l":"ת","b":"מובא בירושלמי (ברכות פ\"ד ה\"ד)."},{"i":3714,"n":"ר\u0027 תנחום בר יודן","l":"ת","b":"מובא בירושלמי (ברכות פ\"ו ה\"א)."},{"i":3715,"n":"ר\u0027 תנחום בר יוסי","l":"ת","b":"מובא בתנחומא (פ\u0027 ויצא - כ\"ב)."},{"i":3716,"n":"ר\u0027 תנחום בר ירמיה","l":"ת","b":"מאחרוני האמוראים בארץ ישראל בדור הששי. מתלמידיו של רבי מנא. היה בעיר חפר והורה שם ואמר לו: לימדתנו שאסור להורות הלכה בפני רבו עד שיהא במרחק י\"ב מיל ור\u0027 מנא יושב בציפורין שהיא קרובה מי\"ב מיל, וענה להם שלא ידע (ירו\u0027, גיטין פ\"א ה\"ב)."},{"i":3717,"n":"ר\u0027 תנחום בר מרי","l":"ת","b":"אמורא ארץ ישראלי בדור החמישי - הששי. מסר בשם רבי יוסי (חברו דרבי יונה), כדמצינו בירושלמי (כתובות פ\"ח ה\"י)."},{"i":3718,"n":"ר\u0027 תנחום בר מריון","l":"ת","b":"אמורא ארץ ישראלי בדור השלישי. מסר בשם רבי יוחנן (ירו\u0027, מעשרות פ\"א ה\"ב). סיפר מענייני רומי (ב\"ר פכ\"ב - ו\u0027)."},{"i":3719,"n":"ר\u0027 תנחום בר עילאי","l":"ת","b":"אמורא ארץ ישראלי בדור השלישי - הרביעי. אמר בשם רבי יוסי בר חנינא (ירו\u0027, חגיגה פ\"א ה\"ב). נפטר בחנוכה (ירו\u0027, סוף מו\"ק)."},{"i":3720,"n":"ר\u0027 תנחום בר פפא","l":"ת","b":"חכם, כנראה אמורא בדור הרביעי - החמישי. חי באלכסנדריה ושלח לשאול לרבי יוסי (חברו דר\u0027 יונה). ר\u0027 יוסי צוה לר\u0027 מנא תלמידו לחתום על התשובה (ירו\u0027, קדושין פ\"ג הי\"ב)."},{"i":3721,"n":"ר\u0027 תנחום ברבי חתניה דר\u0027 שמלאי","l":"ת","b":""},{"i":3722,"n":"רבי תנחום בריה דר\u0027 חייא","l":"ת","b":"(איש כפר עכו) - אמורא ארץ ישראלי בדור הרביעי. אמר בשם ר\u0027 יעקב בר אחא (מו\"ק ט\"ז ע\"ב). מושבו היה בטבריה, ופעם הביאו שבויות יהודיות לטבריה ואחת מהן היתה מעוברת לנוכרי ובאו לשאול הוא וחברו ר\u0027 אחא שר הבירא מרבי אמי (יבמות מ\"ה ע\"א). יש ממנו כמה מאמרי אגדות. (תענית ז\u0027 ע\"ב) כשנפטר נשברו כל האנדרטאות בעירו (מו\"ק כ\"ה ע\"ב - \"דק\"ס\")."},{"i":3723,"n":"ר\u0027 תנחום דכפר גון","l":"ת","b":"אמורא ארץ ישראלי, מאחרוני האמוראים בדור הששי. מובא בירושלמי, שאמר בשם רבי אלעזר ברבי יוסי (ב\"ב פ\"ה ה\"א), אביו רבי יוסי היה מראשי הדור הרביעי לאמוראי א\"י, חברו של רבי יונה."},{"i":3724,"n":"ר\u0027 תנחום דמן יפו","l":"ת","b":"אמורא ארץ ישראלי שאין לקבוע את זמנו המדוייק. יתכן שחי בדור הרביעי - החמישי. אמר בשם ר\u0027 נחוניא (פדר\"כ ר\"פ בחצי הלילה), וכן בשם ר\u0027 מנא דקיסרין (פס\u0027 רבתי שם)."},{"i":3725,"n":"ר\u0027 תנחום דמן נוי","l":"ת","b":"אמורא ארץ ישראלי שאין לקבוע זמנו המדוייק. חי אחרי הדור השלישי. היה דרשן ודיין בעירו (שבת ל\u0027 ע\"א). דיבר בענווה (שם ע\"ב רש\"י)."},{"i":3726,"n":"ר\u0027 תנחום דמן פרוד","l":"ת","b":"אמורא. נראה, שהיה בדור הראשון. רבי יוחנן נזדמן לעיר פרוד: \"אמר: \u0027כלום יש משנת בר קפרא\u0027, תנא ליה ר\u0027 תנחום דמן פרוד\" (ע\"ז ל\"א ע\"א). אין לקבוע שרבי יוחנן קיבל ממנו. ונראה שר\u0027 תנחום דמן פרוד היה מתלמידי בר קפרא."},{"i":3727,"n":"ר\u0027 תנחום חתניה דר\"א בר אבינא","l":"ת","b":"מובא (ריש פסדרו\"כ), ונראה, שהוא ר\u0027 מנחם חתניה דר\"א בר אבונה."},{"i":3728,"n":"רבי תנחומא","l":"ת","b":"אמורא ארץ ישראלי בדור הששי. מחבר מדרש תנחומא. מגדולי בעלי האגדה ובעלי הדרוש. אחרון הדרשנים הארץ ישראלים הידוע לנו בשמו, והוא החותם של תקופת המדרש העתיקה, ששורשיה נעוצים בתקופת הסופרים ואנשי כנסת הגדולה. ידועות כמה מהדורות של מדרש תנחומא מלבד שתי המהדורות השלמות שבידינו והן \"מדרש ילמדנו\" (ע\"ש תחילת כל דרשה \"ילמדנו רבנו\"), וכן הפסיקתות המכילות דרשות השאובות הרבה ממדרש תנחומא. ר\u0027 תנחומא ידוע גם בתור ר\u0027 תנחומא בר אבא ורבותיו היו ר\u0027 הונא ב\u0027, ומסר הרבה בשמו (ירו\u0027, פאה פ\"א ה\"א; חלה פ\"א ה\"ג, ועוד) ורבי פנחס, והקשה לפניו (ירו\u0027, שקלים פ\"ו ה\"א). מסר גם משם חכמים רבים אחרים. מקומו היה בעיר אנטוכיא (ב\"ר פי\"ט - ד\u0027). מובא גם בהלכה בירושלמי (חלה פ\"א ה\"ג) ובבבלי (חולין נ\"ה ע\"ב)."},{"i":3729,"n":"ר\u0027 תנחומא אדרעיה","l":"ת","b":"מובא בירושלמי (ברכות פ\"ד ה\"ב), והוא ר\u0027 תנחום אדרייא."},{"i":3730,"n":"ר\u0027 תנחומא בי ר\u0027 יונה מבצוצרא","l":"ת","b":"ע\"ע ר\u0027 תנחומא בי ר\u0027 יונה ממצוצרא."},{"i":3731,"n":"ר\u0027 תנחומא בי ר\u0027 יונה ממצוצרא","l":"ת","b":"מובא בפסיקתא רבתי (פ\u0027 תשא - ח\u0027)."},{"i":3732,"n":"ר\u0027 תנחומא בי ר\u0027 מנחם בר יעקב","l":"ת","b":"מובא בפס\u0027 רבתי (פ\u0027 תשא - ט\u0027), שאמר בשם אביו."},{"i":3733,"n":"ר\u0027 תפדאי","l":"ת","b":"אמורא ארץ ישראלי בדור החמישי. אמר בשם רבי אחא (ב\"ר פ\"ח - י\"א). \"סה\"ד\" גורס: ר\u0027 תפריי."},{"i":3734,"n":"ר\u0027 תפדיי","l":"ת","b":"מובא בב\"ר (פ\"ח - י\"א), ואולי הוא ר\u0027 תפדאי."}];